def index2ptr(index: Tensor, size: Optional[int] = None) -> Tensor:
    if size is None:
        size = int(index.max()) + 1 if index.numel() > 0 else 0

    return torch._convert_indices_from_coo_to_csr(
        index, size, out_int32=index.dtype != torch.int64)

def apply_(
    tensor: Index,
    fn: Callable,
    *args: Any,
    **kwargs: Any,
) -> Union[Index, Tensor]:

    data = fn(tensor._data, *args, **kwargs)

    if data.dtype not in INDEX_DTYPES:
        return data

    if tensor._data.data_ptr() != data.data_ptr():
        out = Index(data)
    else:  # In-place:
        tensor._data = data
        out = tensor

    # Copy metadata:
    out._dim_size = tensor._dim_size
    out._is_sorted = tensor._is_sorted
    out._cat_metadata = tensor._cat_metadata

    # Convert cache:
    if tensor._indptr is not None:
        out._indptr = fn(tensor._indptr, *args, **kwargs)

    return out

def _sort(
    tensor: Index,
    dim: int = -1,
    descending: bool = False,
) -> Tuple[Index, Tensor]:

    if tensor.is_sorted and not descending:
        return tensor, torch.arange(tensor._data.numel(),
                                    device=tensor._data.device)

    data, perm = aten.sort.default(tensor._data, dim, descending)

    out = Index(data)
    out._dim_size = tensor._dim_size

    if not descending:
        out._is_sorted = True

    return out, perm

def _add(
    input: Union[int, Tensor, Index],
    other: Union[int, Tensor, Index],
    *,
    alpha: int = 1,
) -> Union[Index, Tensor]:

    data = aten.add.Tensor(
        input._data if isinstance(input, Index) else input,
        other._data if isinstance(other, Index) else other,
        alpha=alpha,
    )

    if data.dtype not in INDEX_DTYPES:
        return data
    if data.dim() != 1:
        return data

    out = Index(data)

    if isinstance(input, Tensor) and input.numel() <= 1:
        input = int(input)

    if isinstance(other, Tensor) and other.numel() <= 1:
        other = int(other)

    if isinstance(other, int):
        assert isinstance(input, Index)
        if input.dim_size is not None:
            out._dim_size = input.dim_size + alpha * other
        out._is_sorted = input.is_sorted

    elif isinstance(input, int):
        assert isinstance(other, Index)
        if other.dim_size is not None:
            out._dim_size = input + alpha * other.dim_size
        out._is_sorted = other.is_sorted

    elif isinstance(input, Index) and isinstance(other, Index):
        if input.dim_size is not None and other.dim_size is not None:
            out._dim_size = input.dim_size + alpha * other.dim_size

    return out

def add_(
    input: Index,
    other: Union[int, Tensor, Index],
    *,
    alpha: int = 1,
) -> Index:

    dim_size = input.dim_size
    is_sorted = input.is_sorted
    input._clear_metadata()

    aten.add_.Tensor(
        input._data,
        other._data if isinstance(other, Index) else other,
        alpha=alpha,
    )

    if isinstance(other, Tensor) and other.numel() <= 1:
        other = int(other)

    if isinstance(other, int):
        if dim_size is not None:
            input._dim_size = dim_size + alpha * other
        input._is_sorted = is_sorted

    elif isinstance(other, Index):
        if dim_size is not None and other.dim_size is not None:
            input._dim_size = dim_size + alpha * other.dim_size

    return input

def _sub(
    input: Union[int, Tensor, Index],
    other: Union[int, Tensor, Index],
    *,
    alpha: int = 1,
) -> Union[Index, Tensor]:

    data = aten.sub.Tensor(
        input._data if isinstance(input, Index) else input,
        other._data if isinstance(other, Index) else other,
        alpha=alpha,
    )

    if data.dtype not in INDEX_DTYPES:
        return data
    if data.dim() != 1:
        return data

    out = Index(data)

    if not isinstance(input, Index):
        return out

    if isinstance(other, Tensor) and other.numel() <= 1:
        other = int(other)

    if isinstance(other, int):
        if input.dim_size is not None:
            out._dim_size = input.dim_size - alpha * other
        out._is_sorted = input.is_sorted

    return out

def dim_resize_(self, dim_size: Optional[int]) -> 'Index':
    r"""Assigns or re-assigns the size of the underlying sparse vector."""
    if self.is_sorted and self._indptr is not None:
        if dim_size is None:
            self._indptr = None

        elif self._indptr.numel() - 1 >= dim_size:
            self._indptr = self._indptr[:dim_size + 1]

        else:
            fill_value = self._indptr.new_full(
                (dim_size - self._indptr.numel() + 1, ),
                fill_value=self._indptr[-1],  # type: ignore
            )
            self._indptr = torch.cat([self._indptr, fill_value], dim=0)

    self._dim_size = dim_size

    return self

def is_compiling() -> bool:
    r"""Returns :obj:`True` in case :pytorch:`PyTorch` is compiling via
    :meth:`torch.compile`.
    """
    if torch_geometric.typing.WITH_PT23:
        return torch.compiler.is_compiling()
    if torch_geometric.typing.WITH_PT21:
        return torch._dynamo.is_compiling()
    return False  # pragma: no cover

def is_in_onnx_export() -> bool:
    r"""Returns :obj:`True` in case :pytorch:`PyTorch` is exporting to ONNX via
    :meth:`torch.onnx.export`.
    """
    if is_compiling():
        return False
    if torch.jit.is_scripting():
        return False
    return torch.onnx.is_in_onnx_export()

def _recursive_config(value: Any) -> Any:
    if isinstance(value, ConfigMixin):
        return value.config()
    if is_torch_instance(value, ConfigMixin):
        return value.config()
    if isinstance(value, (tuple, list, ModuleList)):
        return [_recursive_config(v) for v in value]
    if isinstance(value, (dict, ModuleDict)):
        return {k: _recursive_config(v) for k, v in value.items()}
    return value

def _recursive_from_config(value: Any) -> Any:
    cls: Any = None
    if is_dataclass(value):
        if getattr(value, '_target_', None):
            try:
                cls = _locate_cls(value._target_)  # type: ignore
            except ImportError:
                pass  # Keep the dataclass as it is.
        else:
            cls = class_from_dataclass(value.__class__)
    elif isinstance(value, dict) and '_target_' in value:
        cls = _locate_cls(value['_target_'])

    if cls is not None and issubclass(cls, ConfigMixin):
        return cls.from_config(value)
    if isinstance(value, (tuple, list)):
        return [_recursive_from_config(v) for v in value]
    if isinstance(value, dict):
        return {k: _recursive_from_config(v) for k, v in value.items()}
    return value

def _locate_cls(qualname: str) -> Any:
    parts = qualname.split('.')

    if len(parts) <= 1:
        raise ValueError(f"Qualified name is missing a dot (got '{qualname}')")

    if any([len(part) == 0 for part in parts]):
        raise ValueError(f"Relative imports not supported (got '{qualname}')")

    module_name, cls_name = '.'.join(parts[:-1]), parts[-1]
    return getattr(import_module(module_name), cls_name)

def config(self) -> Any:
    r"""Creates a serializable configuration of the class."""
    data_cls = dataclass_from_class(self.__class__)
    if data_cls is None:
        raise ValueError(f"Could not find the configuration class that "
                         f"belongs to '{self.__class__.__name__}'. Please "
                         f"register it in the configuration store.")

    kwargs: Dict[str, Any] = {}
    for field in fields(data_cls):
        if not hasattr(self, field.name):
            continue
        kwargs[field.name] = _recursive_config(getattr(self, field.name))
    return data_cls(**kwargs)

def from_config(cls, cfg: Any, *args: Any, **kwargs: Any) -> Any:
    r"""Instantiates the class from a serializable configuration."""
    if getattr(cfg, '_target_', None):
        cls = _locate_cls(cfg._target_)
    elif isinstance(cfg, dict) and '_target_' in cfg:
        cls = _locate_cls(cfg['_target_'])

    data_cls = cfg.__class__
    if not is_dataclass(data_cls):
        data_cls = dataclass_from_class(cls)
        if data_cls is None:
            raise ValueError(f"Could not find the configuration class "
                             f"that belongs to '{cls.__name__}'. Please "
                             f"register it in the configuration store.")

    field_names = {field.name for field in fields(data_cls)}
    if isinstance(cfg, dict):
        _kwargs = {k: v for k, v in cfg.items() if k in field_names}
        cfg = data_cls(**_kwargs)
    assert is_dataclass(cfg)

    if len(args) > 0:  # Convert `*args` to `**kwargs`:
        param_names = list(inspect.signature(cls).parameters.keys())
        if 'args' in param_names:
            param_names.remove('args')
        if 'kwargs' in param_names:
            param_names.remove('kwargs')

        for name, arg in zip(param_names, args):
            kwargs[name] = arg

    for key in field_names:
        if key not in kwargs and key != '_target_':
            kwargs[key] = _recursive_from_config(getattr(cfg, key))

    return cls(**kwargs)

def get_options(options: Options) -> List[str]:
    if options is None:
        options = list(__experimental_flag__.keys())
    if isinstance(options, str):
        options = [options]
    return options

def is_experimental_mode_enabled(options: Options = None) -> bool:
    r"""Returns :obj:`True` if the experimental mode is enabled. See
    :class:`torch_geometric.experimental_mode` for a list of (optional)
    options.
    """
    if torch.jit.is_scripting() or torch.jit.is_tracing():
        return False
    options = get_options(options)
    return all([__experimental_flag__[option] for option in options])

def log(**kwargs: Any) -> None:
    def _map(value: Any) -> str:
        if isinstance(value, int) and not isinstance(value, bool):
            return f'{value:03d}'
        if isinstance(value, float):
            return f'{value:.4f}'
        return value

    print(', '.join(f'{key}: {_map(value)}' for key, value in kwargs.items()))

    if _wandb_initialized:
        import wandb
        wandb.log(kwargs)

def type_repr(obj: Any, _globals: Dict[str, Any]) -> str:
    r"""Returns the type hint representation of an object."""
    def _get_name(name: str, module: str) -> str:
        return name if name in _globals else f'{module}.{name}'

    if isinstance(obj, str):
        return obj

    if obj is type(None):
        return 'None'

    if obj is ...:
        return '...'

    if obj.__module__ == 'typing':  # Special logic for `typing.*` types:

        if not hasattr(obj, '_name'):
            return repr(obj)

        name = obj._name
        if name is None:  # In some cases, `_name` is not populated.
            name = str(obj.__origin__).split('.')[-1]

        args = getattr(obj, '__args__', None)
        if args is None or len(args) == 0:
            return _get_name(name, obj.__module__)
        if all(isinstance(arg, typing.TypeVar) for arg in args):
            return _get_name(name, obj.__module__)

        # Convert `Union[*, None]` to `Optional[*]`.
        # This is only necessary for old Python versions, e.g. 3.8.
        # TODO Only convert to `Optional` if `Optional` is importable.
        if (name == 'Union' and len(args) == 2
                and any([arg is type(None) for arg in args])):
            name = 'Optional'

        if name == 'Optional':  # Remove `None` from `Optional` arguments:
            args = [arg for arg in obj.__args__ if arg is not type(None)]

        args_repr = ', '.join([type_repr(arg, _globals) for arg in args])
        return f'{_get_name(name, obj.__module__)}[{args_repr}]'

    if obj.__module__ == 'builtins':
        return obj.__qualname__

    return _get_name(obj.__qualname__, obj.__module__)

def split(content: str, sep: str) -> List[str]:
    r"""Splits :obj:`content` based on :obj:`sep`.
    :obj:`sep` inside parentheses or square brackets are ignored.
    """
    assert len(sep) == 1
    outs: List[str] = []

    start = depth = 0
    for end, char in enumerate(content):
        if char == '[' or char == '(':
            depth += 1
        elif char == ']' or char == ')':
            depth -= 1
        elif char == sep and depth == 0:
            outs.append(content[start:end].strip())
            start = end + 1
    if start != len(content):  # Respect dangling `sep`:
        outs.append(content[start:].strip())
    return outs

def _get_modules(self, cls: Type) -> List[str]:
    from torch_geometric.nn import MessagePassing

    modules: List[str] = []
    for base_cls in cls.__bases__:
        if base_cls not in {object, torch.nn.Module, MessagePassing}:
            modules.extend(self._get_modules(base_cls))

    modules.append(cls.__module__)
    return modules

def get_signature(
    self,
    func: Union[Callable, str],
    exclude: Optional[List[str]] = None,
) -> Signature:
    r"""Returns the function signature of the inspected function
    :obj:`func`.

    Args:
        func (callabel or str): The function.
        exclude (list[str], optional): The parameter names to exclude.
            (default: :obj:`None`)
    """
    func_name = func if isinstance(func, str) else func.__name__
    signature = self._signature_dict.get(func_name)
    if signature is None:
        raise IndexError(f"Could not access signature for function "
                         f"'{func_name}'. Did you forget to inspect it?")

    if exclude is None:
        return signature

    param_dict = {
        name: param
        for name, param in signature.param_dict.items()
        if name not in exclude
    }
    return Signature(
        param_dict=param_dict,
        return_type=signature.return_type,
        return_type_repr=signature.return_type_repr,

def collect_param_data(
    self,
    func: Union[Callable, str],
    kwargs: Dict[str, Any],
) -> Dict[str, Any]:
    r"""Collects the input data of the inspected function :obj:`func`
    according to its function signature from a data blob.

    Args:
        func (callable or str): The function.
        kwargs (dict[str, Any]): The data blob which may serve as inputs.
    """
    out_dict: Dict[str, Any] = {}
    for param in self.get_params(func):
        if param.name not in kwargs:
            if param.default is inspect._empty:
                raise TypeError(f"Parameter '{param.name}' is required")
            out_dict[param.name] = param.default
        else:
            out_dict[param.name] = kwargs[param.name]
    return out_dict

def set_tuple_item(
    values: Tuple[Any, ...],
    dim: int,
    value: Any,
) -> Tuple[Any, ...]:
    if dim < -len(values) or dim >= len(values):
        raise IndexError("tuple index out of range")

    dim = dim + len(values) if dim < 0 else dim
    return values[:dim] + (value, ) + values[dim + 1:]

def maybe_add(
    value: Sequence[Optional[int]],
    other: Union[int, Sequence[Optional[int]]],
    alpha: int = 1,
) -> Tuple[Optional[int], ...]:

    if isinstance(other, int):
        return tuple(v + alpha * other if v is not None else None
                     for v in value)

    assert len(value) == len(other)
    return tuple(v + alpha * o if v is not None and o is not None else None
                 for v, o in zip(value, other))

def maybe_sub(
    value: Sequence[Optional[int]],
    other: Union[int, Sequence[Optional[int]]],
    alpha: int = 1,
) -> Tuple[Optional[int], ...]:

    if isinstance(other, int):
        return tuple(v - alpha * other if v is not None else None
                     for v in value)

    assert len(value) == len(other)
    return tuple(v - alpha * o if v is not None and o is not None else None
                 for v, o in zip(value, other))

def assert_two_dimensional(tensor: Tensor) -> None:
    if tensor.dim() != 2:
        raise ValueError(f"'EdgeIndex' needs to be two-dimensional "
                         f"(got {tensor.dim()} dimensions)")
    if not torch.jit.is_tracing() and tensor.size(0) != 2:
        raise ValueError(f"'EdgeIndex' needs to have a shape of "
                         f"[2, *] (got {list(tensor.size())})")

def apply_(
    tensor: EdgeIndex,
    fn: Callable,
    *args: Any,
    **kwargs: Any,
) -> Union[EdgeIndex, Tensor]:

    data = fn(tensor._data, *args, **kwargs)

    if data.dtype not in INDEX_DTYPES:
        return data

    if tensor._data.data_ptr() != data.data_ptr():
        out = EdgeIndex(data)
    else:  # In-place:
        tensor._data = data
        out = tensor

    # Copy metadata:
    out._sparse_size = tensor._sparse_size
    out._sort_order = tensor._sort_order
    out._is_undirected = tensor._is_undirected
    out._cat_metadata = tensor._cat_metadata

    # Convert cache (but do not consider `_value`):
    if tensor._indptr is not None:
        out._indptr = fn(tensor._indptr, *args, **kwargs)

    if tensor._T_perm is not None:
        out._T_perm = fn(tensor._T_perm, *args, **kwargs)

    _T_row, _T_col = tensor._T_index
    if _T_row is not None:
        _T_row = fn(_T_row, *args, **kwargs)
    if _T_col is not None:
        _T_col = fn(_T_col, *args, **kwargs)
    out._T_index = (_T_row, _T_col)

    if tensor._T_indptr is not None:
        out._T_indptr = fn(tensor._T_indptr, *args, **kwargs)

    return out

def _index_select(
    input: EdgeIndex,
    dim: int,
    index: Tensor,
) -> Union[EdgeIndex, Tensor]:

    out = aten.index_select.default(input._data, dim, index)

    if dim == 1 or dim == -1:
        out = EdgeIndex(out)
        out._sparse_size = input.sparse_size()

    return out

def _slice(
    input: EdgeIndex,
    dim: int,
    start: Optional[int] = None,
    end: Optional[int] = None,
    step: int = 1,
) -> Union[EdgeIndex, Tensor]:

    if ((start is None or start == 0 or start <= -input.size(dim))
            and (end is None or end > input.size(dim)) and step == 1):
        return input._shallow_copy()  # No-op.

    out = aten.slice.Tensor(input._data, dim, start, end, step)

    if dim == 1 or dim == -1:
        if step != 1:
            out = out.contiguous()

        out = EdgeIndex(out)
        out._sparse_size = input.sparse_size()
        # NOTE We could potentially maintain `rowptr`/`colptr` attributes here,
        # but it is not really clear if this is worth it. The most important
        # information, the sort order, needs to be maintained though:
        if step >= 0:
            out._sort_order = input._sort_order
        else:
            if input._sort_order == SortOrder.ROW:
                out._sort_order = SortOrder.COL
            elif input._sort_order == SortOrder.COL:
                out._sort_order = SortOrder.ROW

    return out

def _index(
    input: Union[EdgeIndex, Tensor],
    indices: List[Optional[Union[Tensor, EdgeIndex]]],
) -> Union[EdgeIndex, Tensor]:

    if not isinstance(input, EdgeIndex):
        indices = pytree.tree_map_only(EdgeIndex, lambda x: x._data, indices)
        return aten.index.Tensor(input, indices)

    out = aten.index.Tensor(input._data, indices)

    if len(indices) != 2 or indices[0] is not None:
        return out

    index = indices[1]
    assert isinstance(index, Tensor)

    out = EdgeIndex(out)

    # 1. `edge_index[:, mask]` or `edge_index[..., mask]`.
    if index.dtype in (torch.bool, torch.uint8):
        out._sparse_size = input.sparse_size()
        out._sort_order = input._sort_order

    else:  # 2. `edge_index[:, index]` or `edge_index[..., index]`.
        out._sparse_size = input.sparse_size()

    return out

def _select(input: EdgeIndex, dim: int, index: int) -> Union[Tensor, Index]:
    out = aten.select.int(input._data, dim, index)

    if dim == 0 or dim == -2:
        out = Index(out)

        if index == 0 or index == -2:  # Row-select:
            out._dim_size = input.sparse_size(0)
            out._is_sorted = input.is_sorted_by_row
            if input.is_sorted_by_row:
                out._indptr = input._indptr

        else:  # Col-select:
            assert index == 1 or index == -1
            out._dim_size = input.sparse_size(1)
            out._is_sorted = input.is_sorted_by_col
            if input.is_sorted_by_col:
                out._indptr = input._indptr

    return out

def _unbind(
    input: EdgeIndex,
    dim: int = 0,
) -> Union[List[Index], List[Tensor]]:

    if dim == 0 or dim == -2:
        row = input[0]
        assert isinstance(row, Index)
        col = input[1]
        assert isinstance(col, Index)
        return [row, col]

    return aten.unbind.int(input._data, dim)

def _spmm(
    input: EdgeIndex,
    other: Tensor,
    value: Optional[Tensor] = None,
    reduce: ReduceType = 'sum',
    transpose: bool = False,
) -> Tensor:

    if reduce not in get_args(ReduceType):
        raise ValueError(f"`reduce='{reduce}'` is not a valid reduction")

    if not transpose and not input.is_sorted_by_row:
        cls_name = input.__class__.__name__
        raise ValueError(f"'matmul(..., transpose=False)' requires "
                         f"'{cls_name}' to be sorted by rows")

    if transpose and not input.is_sorted_by_col:
        cls_name = input.__class__.__name__
        raise ValueError(f"'matmul(..., transpose=True)' requires "
                         f"'{cls_name}' to be sorted by columns")

    if (torch_geometric.typing.WITH_TORCH_SPARSE and not is_compiling()
            and other.is_cuda):  # pragma: no cover
        return _torch_sparse_spmm(input, other, value, reduce, transpose)

    if value is not None and value.requires_grad:
        if torch_geometric.typing.WITH_TORCH_SPARSE and not is_compiling():
            return _torch_sparse_spmm(input, other, value, reduce, transpose)
        return _scatter_spmm(input, other, value, reduce, transpose)

    if torch_geometric.typing.WITH_PT20:
        if reduce == 'sum' or reduce == 'add':
            return _TorchSPMM.apply(input, other, value, 'sum', transpose)

        if reduce == 'mean':
            out = _TorchSPMM.apply(input, other, value, 'sum', transpose)
            count = input.get_indptr().diff()
            return out / count.clamp_(min=1).to(out.dtype).view(-1, 1)

        if not other.is_cuda and not other.requires_grad:
            return _TorchSPMM.apply(input, other, value, reduce, transpose)

    if torch_geometric.typing.WITH_TORCH_SPARSE and not is_compiling():
        return _torch_sparse_spmm(input, other, value, reduce, transpose)

    return _scatter_spmm(input, other, value, reduce, transpose)

def sparse_resize_(  # type: ignore
    self,
    num_rows: Optional[int],
    num_cols: Optional[int],
) -> 'EdgeIndex':
    r"""Assigns or re-assigns the size of the underlying sparse matrix.

    Args:
        num_rows (int, optional): The number of rows.
        num_cols (int, optional): The number of columns.
    """
    if self.is_undirected:
        if num_rows is not None and num_cols is None:
            num_cols = num_rows
        elif num_cols is not None and num_rows is None:
            num_rows = num_cols

        if num_rows is not None and num_rows != num_cols:
            raise ValueError(f"'EdgeIndex' is undirected but received a "
                             f"non-symmetric size "
                             f"(got [{num_rows}, {num_cols}])")

    def _modify_ptr(
        ptr: Optional[Tensor],
        size: Optional[int],
    ) -> Optional[Tensor]:

        if ptr is None or size is None:
            return None

        if ptr.numel() - 1 >= size:
            return ptr[:size + 1]

        fill_value = ptr.new_full(
            (size - ptr.numel() + 1, ),
            fill_value=ptr[-1],  # type: ignore
        )
        return torch.cat([ptr, fill_value], dim=0)

    if self.is_sorted_by_row:
        self._indptr = _modify_ptr(self._indptr, num_rows)
        self._T_indptr = _modify_ptr(self._T_indptr, num_cols)

    if self.is_sorted_by_col:
        self._indptr = _modify_ptr(self._indptr, num_cols)
        self._T_indptr = _modify_ptr(self._T_indptr, num_rows)

    self._sparse_size = (num_rows, num_cols)

    return self

def get_csr(self) -> Tuple[Tuple[Tensor, Tensor], Optional[Tensor]]:
    r"""Returns the compressed CSR representation
    :obj:`(rowptr, col), perm` in case :class:`EdgeIndex` is sorted.
    """
    if self.is_sorted_by_row:
        return (self.get_indptr(), self._data[1]), None

    assert self.is_sorted_by_col
    (row, col), perm = self._sort_by_transpose()

    if self._T_indptr is not None:
        rowptr = self._T_indptr
    elif self.is_undirected and self._indptr is not None:
        rowptr = self._indptr
    else:
        rowptr = self._T_indptr = index2ptr(row, self.get_num_rows())

    return (rowptr, col), perm

def get_csc(self) -> Tuple[Tuple[Tensor, Tensor], Optional[Tensor]]:
    r"""Returns the compressed CSC representation
    :obj:`(colptr, row), perm` in case :class:`EdgeIndex` is sorted.
    """
    if self.is_sorted_by_col:
        return (self.get_indptr(), self._data[0]), None

    assert self.is_sorted_by_row
    (row, col), perm = self._sort_by_transpose()

    if self._T_indptr is not None:
        colptr = self._T_indptr
    elif self.is_undirected and self._indptr is not None:
        colptr = self._indptr
    else:
        colptr = self._T_indptr = index2ptr(col, self.get_num_cols())

    return (colptr, row), perm

def _get_value(self, dtype: Optional[torch.dtype] = None) -> Tensor:
    if self._value is not None:
        if (dtype or torch.get_default_dtype()) == self._value.dtype:
            return self._value

    # Expanded tensors are not yet supported in all PyTorch code paths :(
    # value = torch.ones(1, dtype=dtype, device=self.device)
    # value = value.expand(self.size(1))
    self._value = torch.ones(self.size(1), dtype=dtype, device=self.device)

    return self._value

def share_memory_(self) -> 'EdgeIndex':
    """"""  # noqa: D419
    self._data.share_memory_()
    if self._indptr is not None:
        self._indptr.share_memory_()
    if self._T_perm is not None:
        self._T_perm.share_memory_()
    if self._T_index[0] is not None:
        self._T_index[0].share_memory_()
    if self._T_index[1] is not None:
        self._T_index[1].share_memory_()
    if self._T_indptr is not None:
        self._T_indptr.share_memory_()
    if self._value is not None:
        self._value.share_memory_()
    return self

def to_sparse(  # type: ignore
    self,
    *,
    layout: torch.layout = torch.sparse_coo,
    value: Optional[Tensor] = None,
) -> Tensor:
    r"""Converts :class:`EdgeIndex` into a
    :pytorch:`null` :class:`torch.sparse` tensor.

    Args:
        layout (torch.layout, optional): The desired sparse layout. One of
            :obj:`torch.sparse_coo`, :obj:`torch.sparse_csr`, or
            :obj:`torch.sparse_csc`. (default: :obj:`torch.sparse_coo`)
        value (torch.Tensor, optional): The values for non-zero elements.
            If not specified, non-zero elements will be assigned a value of
            :obj:`1.0`. (default: :obj:`None`)
    """
    if layout is None or layout == torch.sparse_coo:
        return self.to_sparse_coo(value)
    if layout == torch.sparse_csr:
        return self.to_sparse_csr(value)
    if layout == torch.sparse_csc:
        return self.to_sparse_csc(value)

    raise ValueError(f"Unexpected tensor layout (got '{layout}')")

def __tensor_flatten__(self) -> Tuple[List[str], Tuple[Any, ...]]:
    attrs = ['_data']
    if self._indptr is not None:
        attrs.append('_indptr')
    if self._T_perm is not None:
        attrs.append('_T_perm')
    # TODO We cannot save `_T_index` for now since it is stored as tuple.
    if self._T_indptr is not None:
        attrs.append('_T_indptr')

    ctx = (
        self._sparse_size,
        self._sort_order,
        self._is_undirected,
        self._cat_metadata,
    )

    return attrs, ctx

def backward(
    ctx: Any,
    *grad_outputs: Any,
) -> Tuple[None, Optional[Tensor], None, None, None]:

    grad_out, = grad_outputs

    other_grad: Optional[Tensor] = None
    if ctx.needs_input_grad[1]:
        input, value = ctx.saved_tensors
        assert ctx.reduce == 'sum'

        if not ctx.transpose:
            if value is None and input.is_undirected:
                adj = input.to_sparse_csr(value)
            else:
                (colptr, row), perm = input.get_csc()
                if value is not None and perm is not None:
                    value = value[perm]
                else:
                    value = input._get_value()
                adj = torch.sparse_csr_tensor(
                    crow_indices=colptr,
                    col_indices=row,
                    values=value,
                    size=input.get_sparse_size()[::-1],
                    device=input.device,
                )
        else:
            if value is None and input.is_undirected:
                adj = input.to_sparse_csc(value).t()
            else:
                (rowptr, col), perm = input.get_csr()
                if value is not None and perm is not None:
                    value = value[perm]
                else:
                    value = input._get_value()
                adj = torch.sparse_csr_tensor(
                    crow_indices=rowptr,
                    col_indices=col,
                    values=value,
                    size=input.get_sparse_size()[::-1],
                    device=input.device,
                )

        other_grad = adj @ grad_out

    if ctx.needs_input_grad[2]:
        raise NotImplementedError("Gradient computation for 'value' not "
                                  "yet supported")

    return None, other_grad, None, None, None

def __new__(cls, *args: Any) -> 'EdgeTypeStr':
    if isinstance(args[0], (list, tuple)):
        # Unwrap `EdgeType((src, rel, dst))` and `EdgeTypeStr((src, dst))`:
        args = tuple(args[0])

    if len(args) == 1 and isinstance(args[0], str):
        arg = args[0]  # An edge type string was passed.
        edge_type = tuple(arg.split(EDGE_TYPE_STR_SPLIT))
        if len(edge_type) != 3:
            raise ValueError(f"Cannot convert the edge type '{arg}' to a "
                             f"tuple since it holds invalid characters")

    elif len(args) == 2 and all(isinstance(arg, str) for arg in args):
        # A `(src, dst)` edge type was passed - add `DEFAULT_REL`:
        edge_type = (args[0], DEFAULT_REL, args[1])
        arg = EDGE_TYPE_STR_SPLIT.join(edge_type)

    elif len(args) == 3 and all(isinstance(arg, str) for arg in args):
        # A `(src, rel, dst)` edge type was passed:
        edge_type = tuple(args)
        arg = EDGE_TYPE_STR_SPLIT.join(args)

    else:
        raise ValueError(f"Encountered invalid edge type '{args}'")

    out = str.__new__(cls, arg)
    out.edge_type = edge_type  # type: ignore
    return out

def resolver(
    classes: List[Any],
    class_dict: Dict[str, Any],
    query: Union[Any, str],
    base_cls: Optional[Any],
    base_cls_repr: Optional[str],
    *args: Any,
    **kwargs: Any,
) -> Any:

    if not isinstance(query, str):
        return query

    query_repr = normalize_string(query)
    if base_cls_repr is None:
        base_cls_repr = base_cls.__name__ if base_cls else ''
    base_cls_repr = normalize_string(base_cls_repr)

    for key_repr, cls in class_dict.items():
        if query_repr == key_repr:
            if inspect.isclass(cls):
                obj = cls(*args, **kwargs)
                return obj
            return cls

    for cls in classes:
        cls_repr = normalize_string(cls.__name__)
        if query_repr in [cls_repr, cls_repr.replace(base_cls_repr, '')]:
            if inspect.isclass(cls):
                obj = cls(*args, **kwargs)
                return obj
            return cls

    choices = {cls.__name__ for cls in classes} | set(class_dict.keys())
    raise ValueError(f"Could not resolve '{query}' among choices {choices}")

def as_key_tensor(
    key: Any,
    *,
    device: Optional[torch.device] = None,
) -> Tensor:
    try:
        key = torch.as_tensor(key, device=device)
    except Exception:
        device = device or torch.get_default_device()
        key = torch.tensor(
            [xxhash.xxh64(x).intdigest() & 0x7FFFFFFFFFFFFFFF for x in key],
            dtype=torch.int64, device=device)

    if key.element_size() == 1:
        key = key.view(torch.uint8)
    elif key.element_size() == 2:
        key = key.view(torch.int16)
    elif key.element_size() == 4:
        key = key.view(torch.int32)
    elif key.element_size() == 8:
        key = key.view(torch.int64)
    else:
        raise ValueError(f"Received invalid dtype '{key.dtype}' with "
                         f"{key.element_size()} bytes")

    return key

def get_hash_map(key: Tensor) -> Union[CPUHashMap, CUDAHashMap]:
    if torch_geometric.typing.WITH_CUDA_HASH_MAP and key.is_cuda:
        return CUDAHashMap(key, 0.5)

    if key.is_cuda:
        warnings.warn(
            "Fallback to CPU-based mapping algorithm which may "
            "cause slowdowns and device synchronization. Please "
            "install 'pyg-lib' for an accelerated 'HashTensor' "
            "implementation.", stacklevel=2)

    if torch_geometric.typing.WITH_CPU_HASH_MAP:
        return CPUHashMap(key.cpu(), -1)

    import pandas as pd

    return pd.CategoricalDtype(
        categories=key.cpu().numpy(),
        ordered=True,

def _squeeze_default(tensor: HashTensor) -> HashTensor:
    if tensor._value is None:
        return tensor._shallow_copy()

    value = tensor.as_tensor()
    for d in range(tensor.dim() - 1, 0, -1):
        value = value.squeeze(d)

    return tensor._from_data(
        tensor._map,
        value,
        tensor._min_key,
        tensor._max_key,
        num_keys=tensor.size(0),
        dtype=tensor.dtype,

def _squeeze_dim(
    tensor: HashTensor,
    dim: Union[int, List[int]],
) -> HashTensor:
    if isinstance(dim, int):
        dim = [dim]

    for d in dim:
        if d < -tensor.dim() or d >= tensor.dim():
            raise IndexError(f"Dimension out of range (expected to be in "
                             f"range of [{-tensor.dim()}, {tensor.dim()-1}], "
                             f"but got {d})")

    if tensor._value is None:
        return tensor._shallow_copy()

    value = tensor.as_tensor()
    for d in dim[::-1]:
        if d != 0 and d != -tensor.dim():
            value = value.squeeze(d)

    return tensor._from_data(
        tensor._map,
        value,
        tensor._min_key,
        tensor._max_key,
        num_keys=tensor.size(0),
        dtype=tensor.dtype,

def _slice(
    tensor: HashTensor,
    dim: int,
    start: Optional[int] = None,
    end: Optional[int] = None,
    step: int = 1,
) -> HashTensor:

    if dim == 0 or dim == -tensor.dim():
        copy = start is None or start == 0 or start <= -tensor.size(0)
        copy &= end is None or end > tensor.size(0)
        copy &= step == 1
        if copy:
            return tensor._shallow_copy()

        key = aten.slice.Tensor(tensor._key, 0, start, end, step)
        value = aten.slice.Tensor(tensor.as_tensor(), 0, start, end, step)
        return tensor.__class__(key, value)

    return tensor._from_data(
        tensor._map,
        aten.slice.Tensor(tensor.as_tensor(), dim, start, end, step),
        tensor._min_key,
        tensor._max_key,
        num_keys=tensor.size(0),
        dtype=tensor.dtype,

def _new_index_select(
    input: Tensor,
    dim: Union[int, str],
    index: Tensor,
    out: Optional[Tensor] = None,
) -> Tensor:

    if isinstance(dim, int) and (dim < -input.dim() or dim >= input.dim()):
        raise IndexError(f"Dimension out of range (expected to be in range of "
                         f"[{-input.dim()}, {input.dim()-1}], but got {dim})")

    # We convert any index tensor in the first dimension into a tensor. This
    # means that downstream handling (i.e. in `aten.index_select.default`)
    # needs to take this pre-conversion into account.
    if (not torch.jit.is_scripting() and isinstance(input, HashTensor)
            and isinstance(dim, int) and (dim == 0 or dim == -input.dim())):
        index = as_key_tensor(index, device=input.device)

    if isinstance(dim, int):  # Type narrowing...
        if out is None:
            return _old_index_select(input, dim, index)
        else:
            return _old_index_select(input, dim, index, out=out)
    else:
        if out is None:
            return _old_index_select(input, dim, index)
        else:
            return _old_index_select(input, dim, index, out=out)

def _index_select(
    tensor: HashTensor,
    dim: int,
    index: Tensor,
) -> Union[HashTensor, Tensor]:

    if dim == 0 or dim == -tensor.dim():
        return tensor._get(index)

    return tensor._from_data(
        tensor._map,
        aten.index_select.default(tensor.as_tensor(), dim, index),
        tensor._min_key,
        tensor._max_key,
        num_keys=tensor.size(0),
        dtype=tensor.dtype,

def _new_select(
    input: Tensor,
    dim: Union[int, str],
    index: int,
) -> Tensor:

    if isinstance(dim, int) and (dim < -input.dim() or dim >= input.dim()):
        raise IndexError(f"Dimension out of range (expected to be in range of "
                         f"[{-input.dim()}, {input.dim()-1}], but got {dim})")

    # We convert any index in the first dimension into an integer. This means
    # that downstream handling (i.e. in `aten.select.int`) needs to take this
    # pre-conversion into account.
    if (not torch.jit.is_scripting() and isinstance(input, HashTensor)
            and isinstance(dim, int) and (dim == 0 or dim == -input.dim())):
        index = int(as_key_tensor([index]))

    if isinstance(dim, int):  # Type narrowing...
        return _old_select(input, dim, index)
    else:
        return _old_select(input, dim, index)

def _select(
    tensor: HashTensor,
    dim: int,
    index: int,
) -> Union[HashTensor, Tensor]:

    if dim == 0 or dim == -tensor.dim():
        key = torch.tensor(
            [index],
            dtype=tensor._min_key.dtype,
            device=tensor.device,
        )
        return tensor._get(key).squeeze(0)

    return tensor._from_data(
        tensor._map,
        aten.select.int(tensor.as_tensor(), dim, index),
        tensor._min_key,
        tensor._max_key,
        num_keys=tensor.size(0),
        dtype=tensor.dtype,

def _key(self) -> Tensor:
    if isinstance(self._map, Tensor):
        mask = self._map >= 0
        key = mask.nonzero().view(-1) - 1
        key = key[self._map[mask]]
    elif (torch_geometric.typing.WITH_CUDA_HASH_MAP
          or torch_geometric.typing.WITH_CPU_HASH_MAP):
        key = self._map.keys().to(self.device)
    else:
        key = torch.from_numpy(self._map.categories.to_numpy())

    return key.to(self.device)

def _get(self, query: Tensor) -> Tensor:
    if isinstance(self._map, Tensor):
        index = query.long() - (self._min_key.long() - 1)
        index = self._map[index.clamp_(min=0, max=self._map.numel() - 1)]
    elif torch_geometric.typing.WITH_CUDA_HASH_MAP and query.is_cuda:
        index = self._map.get(query)
    elif torch_geometric.typing.WITH_CPU_HASH_MAP:
        index = self._map.get(query.cpu())
    else:
        import pandas as pd

        ser = pd.Series(query.cpu().numpy(), dtype=self._map)
        index = torch.from_numpy(ser.cat.codes.to_numpy().copy()).long()

    index = index.to(self.device)

    if self._value is None:
        return index.to(self.dtype)

    out = self._value[index]

    mask = index != -1
    mask = mask.view([-1] + [1] * (out.dim() - 1))
    fill_value = float('NaN') if out.is_floating_point() else -1
    if torch_geometric.typing.WITH_PT20:
        other: Union[int, float, Tensor] = fill_value
    else:
        other = torch.full_like(out, fill_value)

    return out.where(mask, other)

def __torch_dispatch__(  # type: ignore
    cls: Type,
    func: Callable[..., Any],
    types: Iterable[Type[Any]],
    args: Iterable[Tuple[Any, ...]] = (),
    kwargs: Optional[Dict[Any, Any]] = None,
) -> Any:
    # Hold a number of `HANDLED_FUNCTIONS` that implement specific
    # functions for valid `HashTensor` routines.
    if func in HANDLED_FUNCTIONS:
        return HANDLED_FUNCTIONS[func](*args, **(kwargs or {}))

    # For all other PyTorch functions, we treat them as vanilla tensors.
    args = pytree.tree_map_only(HashTensor, lambda x: x.as_tensor(), args)
    if kwargs is not None:
        kwargs = pytree.tree_map_only(HashTensor, lambda x: x.as_tensor(),
                                      kwargs)
    return func(*args, **(kwargs or {}))

def share_memory_(self) -> 'HashTensor':
    """"""  # noqa: D419
    if isinstance(self._map, Tensor):
        self._map.share_memory_()
    if self._value is not None:
        self._value.share_memory_()
    self._min_key.share_memory_()
    self._max_key.share_memory_()
    return self

def __getitem__(self, indices: Any) -> Union['HashTensor', Tensor]:
    if not isinstance(indices, tuple):
        indices = (indices, )
    assert len(indices) > 0

    # We convert any index tensor in the first dimension into a tensor.
    # This means that downstream handling (i.e. in `aten.index.Tensor`)
    # needs to take this pre-conversion into account. However, detecting
    # whether the first dimension is indexed can be tricky at times:
    # * We need to take into account `Ellipsis`
    # * We need to take any unsqueezing into account
    if indices[0] is Ellipsis and len(indices) > 1:
        nonempty_indices = [i for i in indices[1:] if i is not None]
        if len(nonempty_indices) == self.dim():
            indices = indices[1:]

    if isinstance(indices[0], (int, bool)):
        index: Union[int, Tensor] = int(as_key_tensor([indices[0]]))
        indices = (index, ) + indices[1:]
    elif isinstance(indices[0], (Tensor, list, np.ndarray)):
        index = as_key_tensor(indices[0], device=self.device)
        indices = (index, ) + indices[1:]

    indices = indices[0] if len(indices) == 1 else indices

    return super().__getitem__(indices)

def is_mps_available() -> bool:
    r"""Returns a bool indicating if MPS is currently available."""
    if hasattr(torch.backends, 'mps') and torch.backends.mps.is_available():
        try:  # Github CI may not have access to MPS hardware. Confirm:
            torch.empty(1, device='mps')
            return True
        except Exception:
            return False
    return False

def is_xpu_available() -> bool:
    r"""Returns a bool indicating if XPU is currently available."""
    if hasattr(torch, 'xpu') and torch.xpu.is_available():
        return True
    try:
        import intel_extension_for_pytorch as ipex
        return ipex.xpu.is_available()
    except ImportError:
        return False

def device(device: Any) -> torch.device:
    r"""Returns a :class:`torch.device`.

    If :obj:`"auto"` is specified, returns the optimal device depending on
    available hardware.
    """
    if device != 'auto':
        return torch.device(device)
    if torch.cuda.is_available():
        return torch.device('cuda')
    if is_mps_available():
        return torch.device('mps')
    if is_xpu_available():
        return torch.device('xpu')
    return torch.device('cpu')

def get_node(cls: Union[str, Any]) -> Optional[Any]:
    if (not isinstance(cls, str)
            and cls.__module__ in {'builtins', 'typing'}):
        return None

    def _get_candidates(repo: Dict[str, Any]) -> List[Any]:
        outs: List[Any] = []
        for key, value in repo.items():
            if isinstance(value, dict):
                outs.extend(_get_candidates(value))
            elif getattr(value.node._metadata, 'object_type', None) == cls:
                outs.append(value.node)
            elif getattr(value.node._metadata, 'orig_type', None) == cls:
                outs.append(value.node)
            elif isinstance(cls, str) and key == f'{cls}.yaml':
                outs.append(value.node)

        return outs

    candidates = _get_candidates(get_config_store().repo)

    if len(candidates) > 1:
        raise ValueError(f"Found multiple entries in the configuration "
                         f"store for the same node '{candidates[0].name}'")

    return candidates[0] if len(candidates) == 1 else None

def get_node(cls: Union[str, Any]) -> Optional[ConfigNode]:
    if (not isinstance(cls, str)
            and cls.__module__ in {'builtins', 'typing'}):
        return None

    def _get_candidates(repo: Dict[str, Any]) -> List[ConfigNode]:
        outs: List[ConfigNode] = []
        for key, value in repo.items():
            if isinstance(value, dict):
                outs.extend(_get_candidates(value))
            elif value.node == cls:
                outs.append(value)
            elif value._metadata.orig_type == cls:
                outs.append(value)
            elif isinstance(cls, str) and key == cls:
                outs.append(value)

        return outs

    candidates = _get_candidates(get_config_store().repo)

    if len(candidates) > 1:
        raise ValueError(f"Found multiple entries in the configuration "
                         f"store for the same node '{candidates[0].name}'")

    return candidates[0] if len(candidates) == 1 else None

def clear_config_store() -> ConfigStore:
    r"""Clears the global configuration store."""
    config_store = get_config_store()
    for key in list(config_store.repo.keys()):
        if key != 'hydra' and not key.endswith('.yaml'):
            del config_store.repo[key]
    return config_store

def fill_config_store() -> None:
    import torch_geometric

    config_store = get_config_store()

    # Register `torch_geometric.transforms` ###################################
    transforms = torch_geometric.transforms
    for cls_name in set(transforms.__all__) - {
            'BaseTransform',
            'Compose',
            'ComposeFilters',
            'LinearTransformation',
            'AddMetaPaths',  # TODO
    }:
        cls = to_dataclass(getattr(transforms, cls_name), base_cls=Transform)
        # We use an explicit additional nesting level inside each config to
        # allow for applying multiple transformations.
        # See: hydra.cc/docs/patterns/select_multiple_configs_from_config_group
        config_store.store(cls_name, group='transform', node={cls_name: cls})

    # Register `torch_geometric.datasets` #####################################
    datasets = torch_geometric.datasets
    map_dataset_args: Dict[str, Any] = {
        'transform': (Dict[str, Transform], field(default_factory=dict)),
        'pre_transform': (Dict[str, Transform], field(default_factory=dict)),
    }

    for cls_name in set(datasets.__all__) - set():
        cls = to_dataclass(getattr(datasets, cls_name), base_cls=Dataset,
                           map_args=map_dataset_args,
                           exclude_args=['pre_filter'])
        config_store.store(cls_name, group='dataset', node=cls)

    # Register `torch_geometric.models` #######################################
    models = torch_geometric.nn.models.basic_gnn
    for cls_name in set(models.__all__) - set():
        cls = to_dataclass(getattr(models, cls_name), base_cls=Model)
        config_store.store(cls_name, group='model', node=cls)

    # Register `torch.optim.Optimizer` ########################################
    for cls_name in {
            key
            for key, cls in torch.optim.__dict__.items()
            if inspect.isclass(cls) and issubclass(cls, torch.optim.Optimizer)
    } - {
            'Optimizer',
    }:
        cls = to_dataclass(getattr(torch.optim, cls_name), base_cls=Optimizer,
                           exclude_args=['params'])
        config_store.store(cls_name, group='optimizer', node=cls)

    # Register `torch.optim.lr_scheduler` #####################################
    for cls_name in {
            key
            for key, cls in torch.optim.lr_scheduler.__dict__.items()
            if inspect.isclass(cls)
    } - {
            'Optimizer',
            '_LRScheduler',
            'Counter',
            'SequentialLR',
            'ChainedScheduler',
    }:
        cls = to_dataclass(getattr(torch.optim.lr_scheduler, cls_name),
                           base_cls=LRScheduler, exclude_args=['optimizer'])
        config_store.store(cls_name, group='lr_scheduler', node=cls)

    # Register global schema ##################################################
    config_store.store('config', node=Config)

def shutdown_rpc(id: str = None, graceful: bool = True,
                 timeout: float = 240.0):
    with _rpc_init_lock:
        if rpc_is_initialized():
            logging.info(f"Shutdown RPC in {id}"
                         f"{' gracefully' if graceful else ''}")
            rpc.shutdown(graceful, timeout)
        else:
            logging.info(f'RPC in {id} not initialized.')

def __init__(self, partition_to_workers: List[List[str]]):
    for rpc_worker_list in partition_to_workers:
        if len(rpc_worker_list) == 0:
            raise ValueError('No RPC worker is in worker list')
    self.partition_to_workers = partition_to_workers
    self.rpc_worker_indices = [0 for _ in range(len(partition_to_workers))]

def wait_all(self):
    r"""Wait for all pending tasks to be finished."""
    for _ in range(self._concurrency):
        self._sem.acquire()
    for _ in range(self._concurrency):
        self._sem.release()

def load_partition_info(
    root_dir: str,
    partition_idx: int,
) -> Tuple[Dict, int, int, torch.Tensor, torch.Tensor]:
    # load the partition with PyG format (graphstore/featurestore)
    with open(osp.join(root_dir, 'META.json'), 'rb') as infile:
        meta = json.load(infile)
    num_partitions = meta['num_parts']
    assert partition_idx >= 0
    assert partition_idx < num_partitions
    partition_dir = osp.join(root_dir, f'part_{partition_idx}')
    assert osp.exists(partition_dir)

    if meta['is_hetero'] is False:
        node_pb = fs.torch_load(osp.join(root_dir, 'node_map.pt'))
        edge_pb = fs.torch_load(osp.join(root_dir, 'edge_map.pt'))

        return (meta, num_partitions, partition_idx, node_pb, edge_pb)
    else:
        node_pb_dict = {}
        node_pb_dir = osp.join(root_dir, 'node_map')
        for ntype in meta['node_types']:
            node_pb_dict[ntype] = fs.torch_load(
                osp.join(node_pb_dir, f'{pyg_dist.utils.as_str(ntype)}.pt'))

        edge_pb_dict = {}
        edge_pb_dir = osp.join(root_dir, 'edge_map')
        for etype in meta['edge_types']:
            edge_pb_dict[tuple(etype)] = fs.torch_load(
                osp.join(edge_pb_dir, f'{pyg_dist.utils.as_str(etype)}.pt'))

        return (meta, num_partitions, partition_idx, node_pb_dict,
                edge_pb_dict)

def is_node_level_time(self) -> bool:
    if 'time' not in self.data:
        return False

    if self.is_hetero:
        return any(['time' in store for store in self.data.node_stores])

    return self.data.is_node_attr('time')

def is_edge_level_time(self) -> bool:
    if 'edge_time' in self.data:
        return True

    if 'time' not in self.data:
        return False

    if self.is_hetero:
        return any(['time' in store for store in self.data.edge_stores])

    return self.data.is_edge_attr('time')

def as_str(inputs: Union[NodeType, EdgeType]) -> str:
    if isinstance(inputs, NodeType):
        return inputs
    elif isinstance(inputs, (list, tuple)) and len(inputs) == 3:
        return '__'.join(inputs)
    return ''

def reverse_edge_type(etype: EdgeType) -> EdgeType:
    src, rel, dst = etype
    if src != dst:
        if rel.split('_', 1)[0] == 'rev':
            # undirected edge with `rev_` prefix.
            rel = rel.split('_', 1)[1]
        else:
            rel = 'rev_' + rel

    return dst, rel, src

def __init__(self, node_types, num_hops):
    self.src: Dict[NodeType, List[Tensor]] = {
        k: (num_hops + 1) * [torch.empty(0, dtype=torch.int64)]
        for k in node_types
    }
    self.with_dupl: Dict[NodeType, Tensor] = {
        k: torch.empty(0, dtype=torch.int64)
        for k in node_types
    }
    self.out: Dict[NodeType, Tensor] = {
        k: torch.empty(0, dtype=torch.int64)
        for k in node_types
    }
    self.seed_time: Dict[NodeType, List[Tensor]] = {
        k: num_hops * [torch.empty(0, dtype=torch.int64)]
        for k in node_types

def __init__(self, node_types, num_hops):
    self.src: Dict[NodeType, List[Tensor]] = {
        k: (num_hops + 1) * [torch.empty(0, dtype=torch.int64)]
        for k in node_types
    }
    self.with_dupl: Dict[NodeType, Tensor] = {
        k: torch.empty(0, dtype=torch.int64)
        for k in node_types
    }
    self.out: Dict[NodeType, Tensor] = {
        k: torch.empty(0, dtype=torch.int64)
        for k in node_types

def __exit__(self, *args) -> None:
    if self.channel:
        self.reset_channel()
    if self._iterator:
        del self._iterator
        torch.distributed.barrier()
        self._iterator = None
        self.prefetch_factor = self._prefetch_old

def _get_tensor(self, attr: TensorAttr) -> Optional[Tensor]:
    tensor = self._feat.get(self.key(attr))

    if tensor is None:
        return None

    if attr.index is None:  # Empty indices return the full tensor:
        return tensor

    return tensor[attr.index]

def set_rpc_router(self, rpc_router: RPCRouter):
    self.rpc_router = rpc_router

    if not self.local_only:
        if self.rpc_router is None:
            raise ValueError("An RPC router must be provided")
        rpc_call = RPCCallFeatureLookup(self)
        self.rpc_call_id = rpc_register(rpc_call)
    else:
        self.rpc_call_id = None

def has_edge_attr(self) -> bool:
    has_edge_attr = False
    for k in [key for key in self._feat.keys() if 'edge_attr' in key]:
        try:
            self.get_tensor(k[0], 'edge_attr')
            has_edge_attr = True
        except KeyError:
            pass
    return has_edge_attr

def _remote_lookup_features(
    self,
    index: Tensor,
    is_node_feat: bool = True,
    input_type: Optional[Union[NodeType, EdgeType]] = None,
) -> torch.futures.Future:
    r"""Fetch the remote features with the remote node/edge IDs."""
    pb = self.node_feat_pb if is_node_feat else self.edge_feat_pb

    input_order = torch.arange(index.size(0), dtype=torch.long)
    if self.meta['is_hetero']:
        partition_ids = pb[input_type][index]
    else:
        partition_ids = pb[index]

    futs, indexes = [], []
    for pidx in range(0, self.num_partitions):
        if pidx == self.partition_idx:
            continue
        remote_mask = partition_ids == pidx
        remote_ids = index[remote_mask]
        if remote_ids.shape[0] > 0:
            to_worker = self.rpc_router.get_to_worker(pidx)
            futs.append(
                rpc_async(
                    to_worker,
                    self.rpc_call_id,
                    args=(remote_ids.cpu(), is_node_feat, input_type),
                ))
            indexes.append(torch.masked_select(input_order, remote_mask))
    collect_fut = torch.futures.collect_all(futs)
    res_fut = torch.futures.Future()

    def when_finish(*_):
        try:
            fut_list = collect_fut.wait()
            result = []
            for i, fut in enumerate(fut_list):
                result.append((fut.wait(), indexes[i]))
        except Exception as e:
            res_fut.set_exception(e)
        else:
            res_fut.set_result(result)

    collect_fut.add_done_callback(when_finish)
    return res_fut

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:
    for store in data.node_stores:
        if self.key is not None and not hasattr(store, self.key):
            continue

        train_masks, val_masks, test_masks = zip(
            *[self._split(store) for _ in range(self.num_splits)])

        store.train_mask = torch.stack(train_masks, dim=-1).squeeze(-1)
        store.val_mask = torch.stack(val_masks, dim=-1).squeeze(-1)
        store.test_mask = torch.stack(test_masks, dim=-1).squeeze(-1)

    return data

def __init__(
    self,
    values: Dict[Any, Union[int, float, Padding]],
    default: Union[int, float] = 0.0,
):
    if not isinstance(values, dict):
        raise ValueError(f"Expected 'values' to be a dictionary "
                         f"(got '{type(values)}'")

    self.values = {
        key: UniformPadding(val) if isinstance(val, (int, float)) else val
        for key, val in values.items()
    }
    self.default = UniformPadding(default)

    for key, value in self.values.items():
        self.validate_key_value(key, value)

def validate_key_value(self, key: Any, value: Any) -> None:
    if not isinstance(key, str):
        raise ValueError(f"Expected the attribute name '{key}' to be a "
                         f"string (got '{type(key)}')")

    if not isinstance(value, UniformPadding):
        raise ValueError(f"Expected the value of '{key}' to be of "
                         f"type 'UniformPadding' (got '{type(value)}')")

def validate_key_value(self, key: Any, value: Any) -> None:
    if not isinstance(key, str):
        raise ValueError(f"Expected the node type '{key}' to be a string "
                         f"(got '{type(key)}')")

    if not isinstance(value, (UniformPadding, AttrNamePadding)):
        raise ValueError(f"Expected the value of '{key}' to be of "
                         f"type 'UniformPadding' or 'AttrNamePadding' "
                         f"(got '{type(value)}')")

def validate_key_value(self, key: Any, value: Any) -> None:
    if not isinstance(key, tuple):
        raise ValueError(f"Expected the edge type '{key}' to be a tuple "
                         f"(got '{type(key)}')")

    if len(key) != 3:
        raise ValueError(f"Expected the edge type '{key}' to hold exactly "
                         f"three elements (got {len(key)})")

    if not isinstance(value, (UniformPadding, AttrNamePadding)):
        raise ValueError(f"Expected the value of '{key}' to be of "
                         f"type 'UniformPadding' or 'AttrNamePadding' "
                         f"(got '{type(value)}')")

def get_value(self, key: Optional[NodeType] = None) -> Optional[int]:
    if self.value is None or isinstance(self.value, int):
        return self.value
    assert isinstance(key, str)
    return self.value[key]

def __init__(
    self,
    value: Union[int, Dict[EdgeType, int], None],
    num_nodes: _NumNodes,
) -> None:

    if value is None:
        if isinstance(num_nodes.value, int):
            value = num_nodes.value * num_nodes.value
        else:
            value = {}

    self.value = value
    self.num_nodes = num_nodes

def get_value(self, key: Optional[EdgeType] = None) -> Optional[int]:
    if self.value is None or isinstance(self.value, int):
        return self.value

    assert isinstance(key, tuple) and len(key) == 3
    if key not in self.value:
        num_src_nodes = self.num_nodes.get_value(key[0])
        num_dst_nodes = self.num_nodes.get_value(key[-1])
        assert num_src_nodes is not None and num_dst_nodes is not None
        self.value[key] = num_src_nodes * num_dst_nodes

    return self.value[key]

def __should_pad_node_attr(self, attr_name: str) -> bool:
    if attr_name in self.node_additional_attrs_pad:
        return True
    if self.exclude_keys is None or attr_name not in self.exclude_keys:
        return True
    return False

def __should_pad_edge_attr(self, attr_name: str) -> bool:
    if self.max_num_edges.value is None:
        return False
    if attr_name == 'edge_index':
        return True
    if self.exclude_keys is None or attr_name not in self.exclude_keys:
        return True
    return False

def __pad_edge_store(
    self,
    store: EdgeStorage,
    get_dim_fn: Callable,
    num_nodes: Union[int, Tuple[int, int]],
    edge_type: Optional[EdgeType] = None,
) -> None:

    attrs_to_pad = {
        attr
        for attr in store.keys()
        if store.is_edge_attr(attr) and self.__should_pad_edge_attr(attr)
    }
    if not attrs_to_pad:
        return
    num_target_edges = self.max_num_edges.get_value(edge_type)
    assert num_target_edges is not None
    assert num_target_edges >= store.num_edges, \
        f'The number of edges after padding ({num_target_edges}) cannot ' \
        f'be lower than the number of edges in the data object ' \
        f'({store.num_edges}).'
    num_pad_edges = num_target_edges - store.num_edges

    if self.add_pad_mask:
        pad_edge_mask = torch.ones(num_target_edges, dtype=torch.bool)
        pad_edge_mask[store.num_edges:] = False
        store.pad_edge_mask = pad_edge_mask

    if isinstance(num_nodes, tuple):
        src_pad_value, dst_pad_value = num_nodes
    else:
        src_pad_value = dst_pad_value = num_nodes

    for attr_name in attrs_to_pad:
        attr = store[attr_name]
        dim = get_dim_fn(attr_name, attr)
        if attr_name == 'edge_index':
            store[attr_name] = self._pad_edge_index(
                attr, num_pad_edges, src_pad_value, dst_pad_value)
        else:
            pad_value = self.__get_edge_padding(attr_name, edge_type)
            store[attr_name] = self._pad_tensor_dim(
                attr, dim, num_pad_edges, pad_value)

def forward(self, data: Data) -> Data:
    num_nodes = data.num_nodes
    assert num_nodes is not None

    if self.replace:
        choice = torch.from_numpy(
            np.random.choice(num_nodes, self.num, replace=True)).long()
    elif not self.allow_duplicates:
        choice = torch.randperm(num_nodes)[:self.num]
    else:
        choice = torch.cat([
            torch.randperm(num_nodes)
            for _ in range(math.ceil(self.num / num_nodes))
        ], dim=0)[:self.num]

    for key, value in data.items():
        if key == 'num_nodes':
            data.num_nodes = choice.size(0)
        elif bool(re.search('edge', key)):
            continue
        elif (isinstance(value, Tensor) and value.size(0) == num_nodes
              and value.size(0) != 1):
            data[key] = value[choice]

    return data

def __init__(self, alpha: float = 0.5, p: float = 1.0) -> None:
    if alpha < 0. or alpha > 1.:
        raise ValueError(f"Interpolation factor has to be between 0 and 1 "
                         f"(got '{alpha}'")
    if p < 0. or p > 1.:
        raise ValueError(f"Ratio of half-hopped edges has to be between "
                         f"0 and 1 (got '{p}'")

    self.p = p
    self.alpha = alpha

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:
    for store in data.node_stores:
        if hasattr(store, 'pos'):
            store.pos = store.pos - store.pos.mean(dim=-2, keepdim=True)
    return data

def forward(self, data: Data) -> Data:
    for i, transform in enumerate(self.transforms):
        try:
            return transform.forward(data)
        except ImportError as e:
            if i == len(self.transforms) - 1:
                raise e
    return data

def forward(self, data: Data) -> Data:
    assert data.pos is not None
    device = data.pos.device

    if data.pos.size(0) < 2:
        data.edge_index = torch.empty(2, 0, dtype=torch.long,
                                      device=device)
    elif data.pos.size(0) == 2:
        data.edge_index = torch.tensor([[0, 1], [1, 0]], device=device)
    elif data.pos.size(0) == 3:
        data.face = torch.tensor([[0], [1], [2]], device=device)
    else:
        data = self._transform.forward(data)

    return data

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:

    for store in data.edge_stores:
        if 'edge_index' not in store:
            continue

        keys, values = [], []
        for key, value in store.items():
            if key in {'edge_index', 'edge_label', 'edge_label_index'}:
                continue

            if store.is_edge_attr(key):
                keys.append(key)
                values.append(value)

        store.edge_index, values = sort_edge_index(
            store.edge_index,
            values,
            sort_by_row=False,
        )

        for key, value in zip(keys, values):
            store[key] = value

        layout = self.layout
        size = store.size()[::-1]
        edge_weight: Optional[Tensor] = None
        if self.attr is not None and self.attr in store:
            edge_weight = store[self.attr]

        if layout is None and torch_geometric.typing.WITH_TORCH_SPARSE:
            store.adj_t = SparseTensor(
                row=store.edge_index[1],
                col=store.edge_index[0],
                value=edge_weight,
                sparse_sizes=size,
                is_sorted=True,
                trust_data=True,
            )

        # TODO Multi-dimensional edge attributes only supported for COO.
        elif ((edge_weight is not None and edge_weight.dim() > 1)
              or layout == torch.sparse_coo):
            assert size[0] is not None and size[1] is not None
            store.adj_t = to_torch_coo_tensor(
                store.edge_index.flip([0]),
                edge_attr=edge_weight,
                size=size,
            )

        elif layout is None or layout == torch.sparse_csr:
            assert size[0] is not None and size[1] is not None
            store.adj_t = to_torch_csr_tensor(
                store.edge_index.flip([0]),
                edge_attr=edge_weight,
                size=size,
            )

        if self.remove_edge_index:
            del store['edge_index']
            if self.attr is not None and self.attr in store:
                del store[self.attr]

        if self.fill_cache and isinstance(store.adj_t, SparseTensor):
            # Pre-process some important attributes.
            store.adj_t.storage.rowptr()
            store.adj_t.storage.csr2csc()

    return data

def postprocess(
    data: HeteroData,
    edge_types: List[EdgeType],
    drop_orig_edge_types: bool,
    keep_same_node_type: bool,
    drop_unconnected_node_types: bool,
) -> None:

    if drop_orig_edge_types:
        for i in edge_types:
            if keep_same_node_type and i[0] == i[-1]:
                continue
            else:
                del data[i]

    # Remove nodes not connected by any edge type:
    if drop_unconnected_node_types:
        new_edge_types = data.edge_types
        node_types = data.node_types
        connected_nodes = set()
        for i in new_edge_types:
            connected_nodes.add(i[0])
            connected_nodes.add(i[-1])
        for node in node_types:
            if node not in connected_nodes:
                del data[node]

def forward(self, data: HeteroData) -> HeteroData:
    edge_types = data.edge_types  # Save original edge types.
    data.metapath_dict = {}

    for j, metapath in enumerate(self.metapaths):
        for edge_type in metapath:
            assert data._to_canonical(edge_type) in edge_types

        edge_type = metapath[0]
        edge_index, edge_weight = self._edge_index(data, edge_type)

        if self.max_sample is not None:
            edge_index, edge_weight = self._sample(edge_index, edge_weight)

        for edge_type in metapath[1:]:
            edge_index2, edge_weight2 = self._edge_index(data, edge_type)

            edge_index, edge_weight = edge_index.matmul(
                edge_index2, edge_weight, edge_weight2)

            if not self.weighted:
                edge_weight = None

            if self.max_sample is not None:
                edge_index, edge_weight = self._sample(
                    edge_index, edge_weight)

        new_edge_type = (metapath[0][0], f'metapath_{j}', metapath[-1][-1])
        data[new_edge_type].edge_index = edge_index.as_tensor()
        if self.weighted:
            data[new_edge_type].edge_weight = edge_weight
        data.metapath_dict[new_edge_type] = metapath

    postprocess(data, edge_types, self.drop_orig_edge_types,
                self.keep_same_node_type, self.drop_unconnected_node_types)

    return data

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:
    for store in data.edge_stores:
        if store.is_bipartite() or 'edge_index' not in store:
            continue

        store.edge_index, store[self.attr] = add_self_loops(
            store.edge_index,
            edge_attr=store.get(self.attr, None),
            fill_value=self.fill_value,
            num_nodes=store.size(0),
        )

    return data

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:
    for store in data.stores:
        for key, value in store.items(*self.attrs):
            if value.numel() > 0:
                value = value - value.min()
                value.div_(value.sum(dim=-1, keepdim=True).clamp_(min=1.))
                store[key] = value
    return data

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:

    for store in data.node_stores:
        if self.node_types is None or store._key in self.node_types:
            num_nodes = store.num_nodes
            assert num_nodes is not None
            c = torch.full((num_nodes, 1), self.value, dtype=torch.float)

            if hasattr(store, 'x') and self.cat:
                x = store.x.view(-1, 1) if store.x.dim() == 1 else store.x
                store.x = torch.cat([x, c.to(x.device, x.dtype)], dim=-1)
            else:
                store.x = c

    return data

def __init__(
    self,
    degrees: Union[Tuple[float, float], float],
    axis: int = 0,
) -> None:
    if isinstance(degrees, (int, float)):
        degrees = (-abs(degrees), abs(degrees))
    assert isinstance(degrees, (tuple, list)) and len(degrees) == 2
    self.degrees = degrees
    self.axis = axis

def forward(self, data: Data) -> Data:
    assert data.pos is not None

    degree = math.pi * random.uniform(*self.degrees) / 180.0
    sin, cos = math.sin(degree), math.cos(degree)

    if data.pos.size(-1) == 2:
        matrix = [[cos, sin], [-sin, cos]]
    else:
        if self.axis == 0:
            matrix = [[1, 0, 0], [0, cos, sin], [0, -sin, cos]]
        elif self.axis == 1:
            matrix = [[cos, 0, -sin], [0, 1, 0], [sin, 0, cos]]
        else:
            matrix = [[cos, sin, 0], [-sin, cos, 0], [0, 0, 1]]

    return LinearTransformation(torch.tensor(matrix))(data)

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:
    for transform in self.transforms:
        if isinstance(data, (list, tuple)):
            data = [transform(d) for d in data]
        else:
            data = transform(data)
    return data

def __call__(
    self,
    data: Union[Data, HeteroData],
) -> bool:
    for filter_fn in self.filters:
        if isinstance(data, (list, tuple)):
            if not all([filter_fn(d) for d in data]):
                return False
        elif not filter_fn(data):
            return False
    return True

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:
    # Gather all nodes that occur in at least one edge (across all types):
    n_ids_dict = defaultdict(list)
    for edge_store in data.edge_stores:
        if 'edge_index' not in edge_store:
            continue

        if edge_store._key is None:
            src = dst = None
        else:
            src, _, dst = edge_store._key

        n_ids_dict[src].append(edge_store.edge_index[0])
        n_ids_dict[dst].append(edge_store.edge_index[1])

    n_id_dict = {k: torch.cat(v).unique() for k, v in n_ids_dict.items()}

    n_map_dict = {}
    for node_store in data.node_stores:
        if node_store._key not in n_id_dict:
            n_id_dict[node_store._key] = torch.empty(0, dtype=torch.long)

        idx = n_id_dict[node_store._key]
        assert data.num_nodes is not None
        mapping = idx.new_zeros(data.num_nodes)
        mapping[idx] = torch.arange(idx.numel(), device=mapping.device)
        n_map_dict[node_store._key] = mapping

    for edge_store in data.edge_stores:
        if 'edge_index' not in edge_store:
            continue

        if edge_store._key is None:
            src = dst = None
        else:
            src, _, dst = edge_store._key

        row = n_map_dict[src][edge_store.edge_index[0]]
        col = n_map_dict[dst][edge_store.edge_index[1]]
        edge_store.edge_index = torch.stack([row, col], dim=0)

    old_data = copy.copy(data)
    for out, node_store in zip(data.node_stores, old_data.node_stores):
        for key, value in node_store.items():
            if key == 'num_nodes':
                out.num_nodes = n_id_dict[node_store._key].numel()
            elif node_store.is_node_attr(key):
                out[key] = value[n_id_dict[node_store._key]]

    return data

def __inc__(self, key: str, value: Any, *args: Any, **kwargs: Any) -> Any:
    if key == 'sub_edge_index':
        return self.n_id.size(0)
    if key in ['n_sub_batch', 'e_sub_batch']:
        return 1 + int(self.n_sub_batch[-1])
    elif key == 'n_id':
        return self.num_nodes
    elif key == 'e_id':
        assert self.edge_index is not None
        return self.edge_index.size(1)
    return super().__inc__(key, value, *args, **kwargs)

def map_data(self) -> Data:
    # Maps all feature information of the :class:`Data` object to each
    # rooted subgraph.
    data = copy.copy(self)

    for key, value in self.items():
        if key in ['sub_edge_index', 'n_id', 'e_id', 'e_sub_batch']:
            del data[key]
        elif key == 'n_sub_batch':
            continue
        elif key == 'num_nodes':
            data.num_nodes = self.n_id.size(0)
        elif key == 'edge_index':
            data.edge_index = self.sub_edge_index
        elif self.is_node_attr(key):
            dim = self.__cat_dim__(key, value)
            data[key] = value.index_select(dim, self.n_id)
        elif self.is_edge_attr(key):
            dim = self.__cat_dim__(key, value)
            data[key] = value.index_select(dim, self.e_id)

    return data

def extract(
    self,
    data: Data,
) -> Tuple[Tensor, Tensor, Tensor, Tensor, Tensor]:

    assert data.edge_index is not None
    num_nodes = data.num_nodes
    assert num_nodes is not None

    adj_t = to_torch_csc_tensor(data.edge_index, size=data.size()).t()
    n_mask = torch.eye(num_nodes, device=data.edge_index.device)
    for _ in range(self.num_hops):
        n_mask += adj_t @ n_mask

    return self.map(data, n_mask > 0)

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:
    for store in data.edge_stores:
        if 'edge_index' not in store:
            continue

        nnz = store.edge_index.size(1)

        if isinstance(data, HeteroData) and (store.is_bipartite()
                                             or not self.merge):
            src, rel, dst = store._key

            # Just reverse the connectivity and add edge attributes:
            row, col = store.edge_index
            rev_edge_index = torch.stack([col, row], dim=0)

            inv_store = data[dst, f'rev_{rel}', src]
            inv_store.edge_index = rev_edge_index
            for key, value in store.items():
                if key == 'edge_index':
                    continue
                if isinstance(value, Tensor) and value.size(0) == nnz:
                    inv_store[key] = value

        else:
            keys, values = [], []
            for key, value in store.items():
                if key == 'edge_index':
                    continue

                if store.is_edge_attr(key):
                    keys.append(key)
                    values.append(value)

            store.edge_index, values = to_undirected(
                store.edge_index, values, reduce=self.reduce)

            for key, value in zip(keys, values):
                store[key] = value

    return data

def forward(self, data: Data) -> Data:
    num_nodes = data.num_nodes

    assert data.pos is not None
    c = torch_geometric.nn.voxel_grid(data.pos, self.size, data.batch,
                                      self.start, self.end)
    c, perm = torch_geometric.nn.pool.consecutive.consecutive_cluster(c)

    for key, item in data.items():
        if bool(re.search('edge', key)):
            raise ValueError(f"'{self.__class__.__name__}' does not "
                             f"support coarsening of edges")

        if torch.is_tensor(item) and item.size(0) == num_nodes:
            if key == 'y':
                item = scatter(one_hot(item), c, dim=0, reduce='sum')
                data[key] = item.argmax(dim=-1)
            elif key == 'batch':
                data[key] = item[perm]
            else:
                data[key] = scatter(item, c, dim=0, reduce='mean')

    return data

def add_node_attr(
    data: Data,
    value: Any,
    attr_name: Optional[str] = None,
) -> Data:
    # TODO Move to `BaseTransform`.
    if attr_name is None:
        if data.x is not None:
            x = data.x.view(-1, 1) if data.x.dim() == 1 else data.x
            data.x = torch.cat([x, value.to(x.device, x.dtype)], dim=-1)
        else:
            data.x = value
    else:
        data[attr_name] = value

    return data

def _split(
    self,
    store: EdgeStorage,
    index: Tensor,
    is_undirected: bool,
    rev_edge_type: Optional[EdgeType],
) -> EdgeStorage:

    edge_attrs = {key for key in store.keys() if store.is_edge_attr(key)}
    for key, value in store.items():
        if key == 'edge_index':
            continue

        if key in edge_attrs:
            value = value[index]
            if is_undirected:
                value = torch.cat([value, value], dim=0)
            store[key] = value

    edge_index = store.edge_index[:, index]
    if is_undirected:
        edge_index = torch.cat([edge_index, edge_index.flip([0])], dim=-1)
    store.edge_index = edge_index

    if rev_edge_type is not None:
        rev_store = store._parent()[rev_edge_type]
        for key in rev_store.keys():
            if key not in store:
                del rev_store[key]  # We delete all outdated attributes.
            elif key == 'edge_index':
                rev_store.edge_index = store.edge_index.flip([0])
            else:
                rev_store[key] = store[key]

    return store

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:
    for store in data.edge_stores:
        if store.is_bipartite() or 'edge_index' not in store:
            continue

        store.edge_index, store[self.attr] = add_remaining_self_loops(
            store.edge_index,
            edge_attr=store.get(self.attr, None),
            fill_value=self.fill_value,
            num_nodes=store.size(0),
        )

    return data

def get_attrs_with_suffix(
    attrs: Optional[List[str]],
    store: BaseStorage,
    suffix: str,
) -> List[str]:
    if attrs is not None:
        return attrs
    return [key for key in store.keys() if key.endswith(suffix)]

def get_mask_size(
    attr: str,
    store: BaseStorage,
    size: Optional[int],
) -> Optional[int]:
    if size is not None:
        return size
    return store.num_edges if store.is_edge_attr(attr) else store.num_nodes

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:
    for store in data.stores:
        attrs = get_attrs_with_suffix(self.attrs, store, '_index')

        sizes: Sequence[Optional[int]]
        if isinstance(self.sizes, int):
            sizes = [self.sizes] * len(attrs)
        elif isinstance(self.sizes, (list, tuple)):
            if len(attrs) != len(self.sizes):
                raise ValueError(
                    f"The number of attributes (got {len(attrs)}) must "
                    f"match the number of sizes provided "
                    f"(got {len(self.sizes)})")
            sizes = self.sizes
        else:
            sizes = [None] * len(attrs)

        for attr, size in zip(attrs, sizes):
            if 'edge_index' in attr:
                continue
            if attr not in store:
                continue
            size = get_mask_size(attr, store, size)
            mask = index_to_mask(store[attr], size=size)
            store[f'{attr[:-6]}_mask'] = mask
            if self.replace:
                del store[attr]

    return data

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:
    for store in data.stores:
        attrs = get_attrs_with_suffix(self.attrs, store, '_mask')

        for attr in attrs:
            if attr not in store:
                continue
            index = mask_to_index(store[attr])
            store[f'{attr[:-5]}_index'] = index
            if self.replace:
                del store[attr]

    return data

def __init__(
    self,
    key: Optional[Union[str, List[str]]] = None,
    reduce: str = "add",
) -> None:
    key = key or ['edge_attr', 'edge_weight']

    if isinstance(key, str):
        key = [key]

    self.keys = key
    self.reduce = reduce

def forward(
    self,
    data: Union[Data, HeteroData],
) -> Union[Data, HeteroData]:
    for store in data.edge_stores:
        if store.is_bipartite() or 'edge_index' not in store:
            continue

        store.edge_index, store[self.attr] = remove_self_loops(
            store.edge_index,
            edge_attr=store.get(self.attr, None),
        )

    return data

def __collate__(self, n_id):
    n_id = torch.tensor(n_id)

    rowptr, col, value = self.adj_t.csr()
    out = torch.ops.torch_sparse.ego_k_hop_sample_adj(
        rowptr, col, n_id, self.depth, self.num_neighbors, self.replace)
    rowptr, col, n_id, e_id, ptr, root_n_id = out

    adj_t = SparseTensor(rowptr=rowptr, col=col,
                         value=value[e_id] if value is not None else None,
                         sparse_sizes=(n_id.numel(), n_id.numel()),
                         is_sorted=True, trust_data=True)

    batch = Batch(batch=torch.ops.torch_sparse.ptr2ind(ptr, n_id.numel()),
                  ptr=ptr)
    batch.root_n_id = root_n_id

    if self.is_sparse_tensor:
        batch.adj_t = adj_t
    else:
        row, col, e_id = adj_t.t().coo()
        batch.edge_index = torch.stack([row, col], dim=0)

    for k, v in self.data:
        if k in ['edge_index', 'adj_t', 'num_nodes', 'batch', 'ptr']:
            continue
        if k == 'y' and v.size(0) == self.data.num_nodes:
            batch[k] = v[n_id][root_n_id]
        elif isinstance(v, Tensor) and v.size(0) == self.data.num_nodes:
            batch[k] = v[n_id]
        elif isinstance(v, Tensor) and v.size(0) == self.data.num_edges:
            batch[k] = v[e_id]
        else:
            batch[k] = v

    return batch

def __init__(
    self,
    dataset: Union[Dataset, Data, List[Data], Tensor],
    input_nodes: Optional[Tensor] = None,
    num_samples: Optional[int] = None,
):

    if isinstance(dataset, Data):
        y = dataset.y.view(-1)
        assert dataset.num_nodes == y.numel()
        y = y[input_nodes] if input_nodes is not None else y

    elif isinstance(dataset, Tensor):
        y = dataset.view(-1)
        y = y[input_nodes] if input_nodes is not None else y

    elif isinstance(dataset, InMemoryDataset):
        y = dataset.y.view(-1)
        assert len(dataset) == y.numel()

    else:
        ys = [data.y for data in dataset]
        if isinstance(ys[0], Tensor):
            y = torch.cat(ys, dim=0).view(-1)
        else:
            y = torch.tensor(ys).view(-1)
        assert len(dataset) == y.numel()

    assert y.dtype == torch.long  # Require classification.

    num_samples = y.numel() if num_samples is None else num_samples

    class_weight = 1. / y.bincount()
    weight = class_weight[y]

    return super().__init__(weight, num_samples, replacement=True)

def collate_fn(data_list: List[Data]) -> Batch:
    batch = Batch()
    for key in data_list[0].keys():
        batch[key] = default_collate([data[key] for data in data_list])
    return batch

def get_pair_wise_distance(
    ys: List,
    num_classes: int,
    dist_type: str = 'kl',
) -> np.ndarray:
    num_batches = len(ys)

    counts = np.zeros((num_batches, num_classes), dtype=np.int32)
    for i in range(num_batches):
        unique, count = np.unique(ys[i], return_counts=True)
        counts[i, unique] = count

    counts += 1
    counts = counts / counts.sum(1).reshape(-1, 1)
    pairwise_dist = np.zeros((num_batches, num_batches), dtype=np.float64)

    for i in range(0, num_batches - 1):
        for j in range(i + 1, num_batches):
            if dist_type == 'l1':
                pairwise_dist[i, j] = np.sum(np.abs(counts[i] - counts[j]))
            elif dist_type == 'kl':

                def kl_divergence(p: np.ndarray, q: np.ndarray):
                    return (p * np.log(p / q)).sum()

                pairwise_dist[i, j] = kl_divergence(counts[i],
                                                    counts[j]) + kl_divergence(
                                                        counts[j], counts[i])
            else:
                raise ValueError

    pairwise_dist += pairwise_dist.T
    pairwise_dist += 1e-5  # for numerical stability
    np.fill_diagonal(pairwise_dist, 0.)

    return pairwise_dist

def define_sampler(
    batch_order: str,
    ys: List[Union[Tensor, np.ndarray, List]],
    num_classes: int,
    dist_type: str = 'kl',
):
    if batch_order == 'rand':
        logging.info("Running with random order")
        sampler = torch.utils.data.RandomSampler(ys)
    elif batch_order in ['order', 'sample']:
        kl_div = get_pair_wise_distance(ys, num_classes, dist_type=dist_type)
        if batch_order == 'order':
            from python_tsp.heuristics import solve_tsp_simulated_annealing
            best_perm, _ = solve_tsp_simulated_annealing(kl_div)
            logging.info(f"Running with given order: {best_perm}")
            sampler = IBMBOrderedSampler(best_perm)
        else:
            logging.info("Running with weighted sampling")
            sampler = IBMBWeightedSampler(kl_div)
    else:
        raise ValueError

    return sampler

def prime_orient_merge(
    ppr_pairs: np.ndarray,
    primes_per_batch: int,
    num_nodes: int,
):
    if not WITH_NUMBA:  # pragma: no cover
        raise ImportError("'prime_orient_merge' requires the 'numba' package")

    global _prime_orient_merge_numba
    if _prime_orient_merge_numba is None:
        _prime_orient_merge_numba = numba.njit(cache=True)(_prime_orient_merge)

    return _prime_orient_merge_numba(ppr_pairs, primes_per_batch, num_nodes)

def _prime_orient_merge(
    ppr_pairs: np.ndarray,
    primes_per_batch: int,
    num_nodes: int,
):
    id_primes_list = list(np.arange(num_nodes, dtype=np.int32).reshape(-1, 1))
    node_id_list = np.arange(num_nodes, dtype=np.int32)
    placeholder = np.zeros(0, dtype=np.int32)

    for i, j in ppr_pairs:
        id1, id2 = node_id_list[i], node_id_list[j]
        if id1 > id2:
            id1, id2 = id2, id1

        if id1 != id2 and len(id_primes_list[id1]) + len(
                id_primes_list[id2]) <= primes_per_batch:
            id_primes_list[id1] = np.concatenate(
                (id_primes_list[id1], id_primes_list[id2]))
            node_id_list[id_primes_list[id2]] = id1
            id_primes_list[id2] = placeholder

    prime_lst = list()
    ids = np.unique(node_id_list)

    for _id in ids:
        prime_lst.append(list(id_primes_list[_id]))

    return list(prime_lst)

def get_numa_nodes_cores() -> Dict[str, Any]:
    """Parses numa nodes information into a dictionary.

    ..code-block::

        {<node_id>: [(<core_id>, [<sibling_thread_id_0>, <sibling_thread_id_1>
        ...]), ...], ...}

        # For example:
        {0: [(0, [0, 4]), (1, [1, 5])], 1: [(2, [2, 6]), (3, [3, 7])]}

    If not available, returns an empty dictionary.
    """
    numa_node_paths = glob.glob('/sys/devices/system/node/node[0-9]*')

    if not numa_node_paths:
        return {}

    nodes = {}
    try:
        for node_path in numa_node_paths:
            numa_node_id = int(osp.basename(node_path)[4:])

            thread_siblings = {}
            for cpu_dir in glob.glob(osp.join(node_path, 'cpu[0-9]*')):
                cpu_id = int(osp.basename(cpu_dir)[3:])
                if cpu_id > 0:
                    with open(osp.join(cpu_dir, 'online')) as core_online_file:
                        core_online = int(
                            core_online_file.read().splitlines()[0])
                else:
                    core_online = 1  # cpu0 is always online (special case)
                if core_online == 1:
                    with open(osp.join(cpu_dir, 'topology',
                                       'core_id')) as core_id_file:
                        core_id = int(core_id_file.read().strip())
                        if core_id in thread_siblings:
                            thread_siblings[core_id].append(cpu_id)
                        else:
                            thread_siblings[core_id] = [cpu_id]

            nodes[numa_node_id] = sorted([(k, sorted(v))
                                          for k, v in thread_siblings.items()])

    except (OSError, ValueError, IndexError):
        Warning('Failed to read NUMA info')
        return {}

    return nodes

def _aff_init_fn(self, worker_id: int) -> None:
    try:
        worker_cores = self.loader_cores[worker_id]
        if not isinstance(worker_cores, List):
            worker_cores = [worker_cores]

        if torch.multiprocessing.get_context()._name == 'spawn':
            torch.set_num_threads(len(worker_cores))

        psutil.Process().cpu_affinity(worker_cores)

    except IndexError as e:
        raise ValueError(f"Cannot use CPU affinity for worker ID "
                         f"{worker_id} on CPU {self.loader_cores}") from e

    # Chain worker init functions:
    self._old_worker_init_fn(worker_id)

def to_device(inputs: Any, device: Optional[torch.device] = None) -> Any:
    if hasattr(inputs, 'to'):
        return inputs.to(device)
    elif isinstance(inputs, Mapping):
        return {key: to_device(value, device) for key, value in inputs.items()}
    elif isinstance(inputs, tuple) and hasattr(inputs, '_fields'):
        return type(inputs)(*(to_device(s, device) for s in zip(*inputs)))
    elif isinstance(inputs, Sequence) and not isinstance(inputs, str):
        return [to_device(s, device) for s in zip(*inputs)]

    return inputs

def __iter__(self) -> Any:
    if len(self._cache):
        for batch in self._cache:
            yield batch
        return

    for batch in self.loader:

        if self.transform is not None:
            batch = self.transform(batch)

        batch = to_device(batch, self.device)

        self._cache.append(batch)

        yield batch

def _metis(self, edge_index: Tensor, num_nodes: int) -> Tensor:
    # Computes a node-level partition assignment vector via METIS.
    if self.sparse_format == 'csr':  # Calculate CSR representation:
        row, index = sort_edge_index(edge_index, num_nodes=num_nodes)
        indptr = index2ptr(row, size=num_nodes)
    else:  # Calculate CSC representation:
        index, col = sort_edge_index(edge_index, num_nodes=num_nodes,
                                     sort_by_row=False)
        indptr = index2ptr(col, size=num_nodes)

    # Compute METIS partitioning:
    cluster: Optional[Tensor] = None

    if torch_geometric.typing.WITH_TORCH_SPARSE:
        try:
            cluster = torch.ops.torch_sparse.partition(
                indptr.cpu(),
                index.cpu(),
                None,
                self.num_parts,
                self.recursive,
            ).to(edge_index.device)
        except (AttributeError, RuntimeError):
            pass

    if cluster is None and torch_geometric.typing.WITH_METIS:
        cluster = pyg_lib.partition.metis(
            indptr.cpu(),
            index.cpu(),
            self.num_parts,
            recursive=self.recursive,
        ).to(edge_index.device)

    if cluster is None:
        raise ImportError(f"'{self.__class__.__name__}' requires either "
                          f"'pyg-lib' or 'torch-sparse'")

    return cluster

def _permute_data(self, data: Data, partition: Partition) -> Data:
    # Permute node-level and edge-level attributes according to the
    # calculated permutations in `Partition`:
    out = copy.copy(data)
    for key, value in data.items():
        if key == 'edge_index':
            continue
        elif data.is_node_attr(key):
            cat_dim = data.__cat_dim__(key, value)
            out[key] = select(value, partition.node_perm, dim=cat_dim)
        elif data.is_edge_attr(key):
            cat_dim = data.__cat_dim__(key, value)
            out[key] = select(value, partition.edge_perm, dim=cat_dim)
    out.edge_index = None

    return out

def collate_fn(self, index):
    if not isinstance(index, Tensor):
        index = torch.tensor(index)

    if isinstance(self.data, Data):
        return self.data.subgraph(index)

    elif isinstance(self.data, HeteroData):
        node_dict = {
            key: index[(index >= start) & (index < end)] - start
            for key, (start, end) in self.node_dict.items()
        }
        return self.data.subgraph(node_dict)

def filter_node_store_(store: NodeStorage, out_store: NodeStorage,
                       index: Tensor):
    # Filters a node storage object to only hold the nodes in `index`:
    for key, value in store.items():
        if key == 'num_nodes':
            out_store.num_nodes = index.numel()

        elif store.is_node_attr(key):
            if isinstance(value, (Tensor, TensorFrame)):
                index = index.to(value.device)
            elif isinstance(value, np.ndarray):
                index = index.cpu()
            dim = store._parent().__cat_dim__(key, value, store)
            out_store[key] = index_select(value, index, dim=dim)

def get_input_nodes(
    data: Union[Data, HeteroData, Tuple[FeatureStore, GraphStore]],
    input_nodes: Union[InputNodes, TensorAttr],
    input_id: Optional[Tensor] = None,
) -> Tuple[Optional[str], Tensor, Optional[Tensor]]:
    def to_index(nodes, input_id) -> Tuple[Tensor, Optional[Tensor]]:
        if isinstance(nodes, Tensor) and nodes.dtype == torch.bool:
            nodes = nodes.nonzero(as_tuple=False).view(-1)
            if input_id is not None:
                assert input_id.numel() == nodes.numel()
            else:
                input_id = nodes
            return nodes, input_id

        if not isinstance(nodes, Tensor):
            nodes = torch.tensor(nodes, dtype=torch.long)

        if input_id is not None:
            assert input_id.numel() == nodes.numel()

        return nodes, input_id

    if isinstance(data, Data):
        if input_nodes is None:
            return None, torch.arange(data.num_nodes), None
        return None, *to_index(input_nodes, input_id)

    elif isinstance(data, HeteroData):
        assert input_nodes is not None

        if isinstance(input_nodes, str):
            return input_nodes, torch.arange(data[input_nodes].num_nodes), None

        assert isinstance(input_nodes, (list, tuple))
        assert len(input_nodes) == 2
        assert isinstance(input_nodes[0], str)

        node_type, input_nodes = input_nodes
        if input_nodes is None:
            return node_type, torch.arange(data[node_type].num_nodes), None
        return node_type, *to_index(input_nodes, input_id)

    else:  # Tuple[FeatureStore, GraphStore]
        feature_store, graph_store = data
        assert input_nodes is not None

        if isinstance(input_nodes, Tensor):
            return None, *to_index(input_nodes, input_id)

        if isinstance(input_nodes, str):
            num_nodes = remote_backend_utils.num_nodes(  #
                feature_store, graph_store, input_nodes)
            return input_nodes, torch.arange(num_nodes), None

        if isinstance(input_nodes, (list, tuple)):
            assert len(input_nodes) == 2
            assert isinstance(input_nodes[0], str)

            node_type, input_nodes = input_nodes
            if input_nodes is None:
                num_nodes = remote_backend_utils.num_nodes(  #
                    feature_store, graph_store, input_nodes)
                return node_type, torch.arange(num_nodes), None

            return node_type, *to_index(input_nodes, input_id)

def get_edge_label_index(
    data: Union[Data, HeteroData, Tuple[FeatureStore, GraphStore]],
    edge_label_index: InputEdges,
) -> Tuple[Optional[str], Tensor]:
    edge_type = None
    if isinstance(data, Data):
        if edge_label_index is None:
            return None, data.edge_index
        return None, edge_label_index

    assert edge_label_index is not None
    assert isinstance(edge_label_index, (list, tuple))

    if isinstance(data, HeteroData):
        if isinstance(edge_label_index[0], str):
            edge_type = edge_label_index
            edge_type = data._to_canonical(*edge_type)
            assert edge_type in data.edge_types
            return edge_type, data[edge_type].edge_index

        assert len(edge_label_index) == 2

        edge_type, edge_label_index = edge_label_index
        edge_type = data._to_canonical(*edge_type)

        if edge_label_index is None:
            return edge_type, data[edge_type].edge_index

        return edge_type, edge_label_index

    else:  # Tuple[FeatureStore, GraphStore]
        _, graph_store = data

        # Need the edge index in COO for LinkNeighborLoader:
        def _get_edge_index(edge_type):
            row_dict, col_dict, _ = graph_store.coo([edge_type])
            row = list(row_dict.values())[0]
            col = list(col_dict.values())[0]
            return torch.stack((row, col), dim=0)

        if isinstance(edge_label_index[0], str):
            edge_type = edge_label_index
            return edge_type, _get_edge_index(edge_type)

        assert len(edge_label_index) == 2
        edge_type, edge_label_index = edge_label_index

        if edge_label_index is None:
            return edge_type, _get_edge_index(edge_type)

        return edge_type, edge_label_index

def __iter__(self) -> Iterator[List[int]]:
    if self.shuffle:
        indices = torch.randperm(len(self.dataset)).tolist()
    else:
        indices = range(len(self.dataset))

    samples: List[int] = []
    current_num: int = 0
    num_steps: int = 0
    num_processed: int = 0

    while (num_processed < len(self.dataset)
           and num_steps < self.max_steps):

        for i in indices[num_processed:]:
            data = self.dataset[i]
            num = data.num_nodes if self.mode == 'node' else data.num_edges

            if current_num + num > self.max_num:
                if current_num == 0:
                    if self.skip_too_big:
                        continue
                else:  # Mini-batch filled:
                    break

            samples.append(i)
            num_processed += 1
            current_num += num

        yield samples
        samples: List[int] = []
        current_num = 0
        num_steps += 1

def non_blocking_transfer(self, batch: Any) -> Any:
    if not self.device_helper.is_gpu:
        return batch
    if isinstance(batch, (list, tuple)):
        return [self.non_blocking_transfer(v) for v in batch]
    if isinstance(batch, dict):
        return {k: self.non_blocking_transfer(v) for k, v in batch.items()}

    batch = batch.pin_memory()
    return batch.to(self.device_helper.device, non_blocking=True)

def _collate(self, data_list):
    assert len(data_list) == 1
    node_idx, adj = data_list[0]

    data = self.data.__class__()
    data.num_nodes = node_idx.size(0)
    row, col, edge_idx = adj.coo()
    data.edge_index = torch.stack([row, col], dim=0)

    for key, item in self.data:
        if key in ['edge_index', 'num_nodes']:
            continue
        if isinstance(item, torch.Tensor) and item.size(0) == self.N:
            data[key] = item[node_idx]
        elif isinstance(item, torch.Tensor) and item.size(0) == self.E:
            data[key] = item[edge_idx]
        else:
            data[key] = item

    if self.sample_coverage > 0:
        data.node_norm = self.node_norm[node_idx]
        data.edge_norm = self.edge_norm[edge_idx]

    return data

def __call__(self, batch: List[Any]) -> Any:
    elem = batch[0]
    if isinstance(elem, BaseData):
        return Batch.from_data_list(
            batch,
            follow_batch=self.follow_batch,
            exclude_keys=self.exclude_keys,
        )
    elif isinstance(elem, torch.Tensor):
        return default_collate(batch)
    elif isinstance(elem, TensorFrame):
        return torch_frame.cat(batch, dim=0)
    elif isinstance(elem, float):
        return torch.tensor(batch, dtype=torch.float)
    elif isinstance(elem, int):
        return torch.tensor(batch)
    elif isinstance(elem, str):
        return batch
    elif isinstance(elem, Mapping):
        return {key: self([data[key] for data in batch]) for key in elem}
    elif isinstance(elem, tuple) and hasattr(elem, '_fields'):
        return type(elem)(*(self(s) for s in zip(*batch)))
    elif isinstance(elem, Sequence) and not isinstance(elem, str):
        return [self(s) for s in zip(*batch)]

    raise TypeError(f"DataLoader found invalid type: '{type(elem)}'")

