def process(self) -> None:
    with open(self.raw_paths[1]) as f:
        manifest = json.load(f)
    total = manifest['full_train'] + manifest['full_test']
    partial = set(manifest[f'{self.task}_{self.split}'])

    data_list = []
    raw_data = fs.torch_load(self.raw_paths[0])
    for k, s in enumerate(total):
        if s in partial:
            data = Data(**raw_data[k])

            if self.pre_filter is not None and not self.pre_filter(data):
                continue
            if self.pre_transform is not None:
                data = self.pre_transform(data)

            data_list.append(data)

    self.save(data_list, self.processed_paths[0])

def __init__(
    self,
    root: str,
    split: Optional[str] = None,
    transform: Optional[Callable] = None,
    pre_transform: Optional[Callable] = None,
    pre_filter: Optional[Callable] = None,
    force_reload: bool = False,
) -> None:
    if split not in {'train', 'val', 'trainval', 'test', None}:
        raise ValueError(f'Split "{split}" found, but expected either '
                         f'"train", "val", "trainval", "test" or None')
    super().__init__(root, transform, pre_transform, pre_filter,
                     force_reload=force_reload)
    self.load(self.processed_paths[0])

    if split is not None:
        split_slices = fs.torch_load(self.processed_paths[1])
        if split == 'train':
            self._indices = range(split_slices[0], split_slices[1])
        elif split == 'val':
            self._indices = range(split_slices[1], split_slices[2])
        elif split == 'trainval':
            self._indices = range(split_slices[0], split_slices[2])
        elif split == 'test':
            self._indices = range(split_slices[2], split_slices[3])

def processed_file_names(self) -> str:
    sids = '_'.join([sid[-2:] for sid in self.subjects])
    cats = '_'.join([
        ''.join([w[0] for w in cat.split('_')]) for cat in self.categories
    ])
    return f'{sids}_{cats}.pt'

def process(self) -> None:
    import h5py

    fm = h5py.File(self.raw_paths[0], 'r')
    ff = h5py.File(self.raw_paths[1], 'r')

    face = torch.from_numpy(fm['faces'][()]).to(torch.long)
    face = face.t().contiguous()

    data_list = []
    for (sid, cat) in product(self.subjects, self.categories):
        idx = f'{sid}_{cat}'
        if idx in fm:
            pos = torch.from_numpy(fm[idx][()])
        elif idx in ff:
            pos = torch.from_numpy(ff[idx][()])
        else:
            continue
        pos = pos.permute(2, 0, 1).contiguous()
        data_list.append(Data(pos=pos, face=face, num_nodes=pos.size(1)))

    if self.pre_filter is not None:
        data_list = [d for d in data_list if self.pre_filter(d)]

    if self.pre_transform is not None:
        data_list = [self.pre_transform(d) for d in data_list]

    self.save(data_list, self.processed_paths[0])

def _get_trips(self) -> Iterator[TripletLike]:
    # Iterate over each element's graph in each split of the dataset
    # Using chain to lazily iterate without storing all trips in memory
    split_iterators = []

    for split in self.required_splits:
        # Create an iterator for each element's graph in the current split
        split_graphs = (element['graph']
                        for element in self.raw_dataset[split])
        split_iterators.append(chain.from_iterable(split_graphs))

    # Chain all split iterators together
    return chain.from_iterable(split_iterators)

def __init__(
    self,
    root: str,
    split: str = "train",
    force_reload: bool = False,
    verbose: bool = False,
    use_pcst: bool = True,
    load_dataset_kwargs: Optional[Dict[str, Any]] = None,
    retrieval_kwargs: Optional[Dict[str, Any]] = None,
) -> None:
    load_dataset_kwargs = load_dataset_kwargs or {}
    retrieval_kwargs = retrieval_kwargs or {}
    # Modify these paramters if running into memory/compute issues
    default_retrieval_kwargs = {
        'max_batch_size': 250,  # Lower batch size to reduce memory usage
        'num_workers':
        None,  # Use all available workers, or set to number of threads
    }
    retrieval_kwargs = {**default_retrieval_kwargs, **retrieval_kwargs}
    dataset_name = 'rmanluo/RoG-webqsp'
    super().__init__(dataset_name, root, split, force_reload, verbose,
                     use_pcst, load_dataset_kwargs=load_dataset_kwargs,
                     retrieval_kwargs=retrieval_kwargs)

def _process_pdb2(self, t: Dict[str, Any]) -> Dict[str, Any]:
    init_alphabet = list(
        'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz')
    extra_alphabet = [str(item) for item in list(np.arange(300))]
    chain_alphabet = init_alphabet + extra_alphabet
    my_dict: Dict[str, Union[str, int, Dict[str, Any], List[Any]]] = {}
    concat_seq = ''
    mask_list = []
    visible_list = []
    for idx in list(np.unique(t['idx'])):
        letter = chain_alphabet[idx]
        res = np.argwhere(t['idx'] == idx)
        initial_sequence = "".join(list(
            np.array(list(t['seq']))[res][
                0,
            ]))
        if initial_sequence[-6:] == "HHHHHH":
            res = res[:, :-6]
        if initial_sequence[0:6] == "HHHHHH":
            res = res[:, 6:]
        if initial_sequence[-7:-1] == "HHHHHH":
            res = res[:, :-7]
        if initial_sequence[-8:-2] == "HHHHHH":
            res = res[:, :-8]
        if initial_sequence[-9:-3] == "HHHHHH":
            res = res[:, :-9]
        if initial_sequence[-10:-4] == "HHHHHH":
            res = res[:, :-10]
        if initial_sequence[1:7] == "HHHHHH":
            res = res[:, 7:]
        if initial_sequence[2:8] == "HHHHHH":
            res = res[:, 8:]
        if initial_sequence[3:9] == "HHHHHH":
            res = res[:, 9:]
        if initial_sequence[4:10] == "HHHHHH":
            res = res[:, 10:]
        if res.shape[1] >= 4:
            chain_seq = "".join(list(np.array(list(t['seq']))[res][0]))
            my_dict[f'seq_chain_{letter}'] = chain_seq
            concat_seq += chain_seq
            if idx in t['masked']:
                mask_list.append(letter)
            else:
                visible_list.append(letter)
            coords_dict_chain = {}
            all_atoms = np.array(t['xyz'][res])[0]  # [L, 14, 3]
            for i, c in enumerate(['N', 'CA', 'C', 'O']):
                coords_dict_chain[
                    f'{c}_chain_{letter}'] = all_atoms[:, i, :].tolist()
            my_dict[f'coords_chain_{letter}'] = coords_dict_chain
    my_dict['name'] = t['label']
    my_dict['masked_list'] = mask_list
    my_dict['visible_list'] = visible_list
    my_dict['num_of_chains'] = len(mask_list) + len(visible_list)
    my_dict['seq'] = concat_seq
    return my_dict

def select_clusters(
    self,
    clusters: Optional[Union[int, List[int]]],
) -> None:
    if self.name is not None:
        clusters = self._validate_name(clusters)

    self._partitions = [self._create_partitions(f) for f in self.raw_paths]

    if clusters is None:
        return

    clusters = [clusters] if isinstance(clusters, int) else clusters

    def is_valid_cluster(x: Union[int, List[int]]) -> bool:
        return isinstance(x, int) and x >= 3 and x <= 30

    if not all([is_valid_cluster(x) for x in clusters]):
        raise ValueError(
            "Selected clusters must be an integer in the range [3, 30]")

    self._partitions = [self._partitions[c - 3] for c in clusters]

def _validate_name(
    self,
    clusters: Optional[Union[int, List[int]]],
) -> List[int]:
    if clusters is not None:
        raise ValueError("'name' and 'clusters' are mutually exclusive")

    if self.name not in ['small', 'medium']:
        raise ValueError(f"Invalid subset name '{self.name}'. "
                         f"Must be either 'small' or 'medium'")

    return list(range(3, 26))

def get(self, idx: int) -> Data:
    self._load()

    if self._data_list[idx] is not None:
        cached_data = self._data_list[idx]
        assert isinstance(cached_data, Data)
        return copy.copy(cached_data)

    data = Data(
        z=torch.from_numpy(self.z[idx, :]),
        pos=torch.from_numpy(self.pos[idx, :, :]),
        y=torch.tensor(self.y[idx]),
    )

    if self.pre_transform is not None:
        data = self.pre_transform(data)

    self._data_list[idx] = copy.copy(data)
    return data

def _safe_auto_tokenizer(model_name: str) -> PreTrainedTokenizerBase:
    try:
        from transformers import AutoTokenizer
        return AutoTokenizer.from_pretrained(model_name)
    except ValueError as err:
        if "bert" in model_name:
            from transformers import BertTokenizer
            return BertTokenizer.from_pretrained(model_name)
        elif "gpt2" in model_name:
            from transformers import GPT2Tokenizer
            return GPT2Tokenizer.from_pretrained(model_name)
        else:
            raise RuntimeError(
                f"Unsupported legacy model: {model_name}") from err

