        if tv.tag_size not in range(4, 16 + 1, 2) and "Parameter 'mac_len'" in str(e):
            assert not tv.valid
            return
        raise e

    cipher.update(tv.aad)
    try:
        pt = cipher.decrypt_and_verify(tv.ct, tv.tag)
