def config_initiated(app, config):
    theme_options = config.html_theme_options or {}
    if theme_options.get('canonical_url'):
        logger.warning(
            _('The canonical_url option is deprecated, use the html_baseurl option from Sphinx instead.')
        )

    if theme_options.get("analytics_id"):
        logger.warning(
            _('The analytics_id option is deprecated, use the sphinxcontrib-googleanalytics extension instead.')
        )

    if theme_options.get("analytics_anonymize_ip"):
        logger.warning(
            _('The analytics_anonymize_ip option is deprecated, use the sphinxcontrib-googleanalytics extension instead.')
        )

    if "extra_css_files" in config.html_context:
        logger.warning(
            _('The extra_css_file option is deprecated, use the html_css_files option from Sphinx instead.')

def extend_html_context(app, pagename, templatename, context, doctree):
     # Add ``sphinx_version_info`` tuple for use in Jinja templates
     context['sphinx_version_info'] = sphinx_version

     # Inject all the Read the Docs environment variables in the context:
     # https://docs.readthedocs.io/en/stable/reference/environment-variables.html
     context['READTHEDOCS'] = os.environ.get("READTHEDOCS", False) == "True"
     if context['READTHEDOCS']:
         for key, value in os.environ.items():
             if key.startswith("READTHEDOCS_"):
                 context[key] = value

def add(X1, Y1, X2, Y2):
    if X1 == 0 and Y1 == 0:
        return (X2, Y2)
    if X1 == X2 and Y1 == Y2:
        return double(X1, Y1)
    if X1 == X2 and (Y1 + Y2) % p == 0:
        return (0, 0)

    u = Y2 - Y1
    uu = pow(u, 2, p)
    v = X2 - X1
    vv = pow(v, 2, p)
    vvv = v * vv % p
    R = vv * X1 % p
    A = uu - vvv - 2 * R
    X3 = v * A % p
    Y3 = (u * (R - A) - vvv * Y1) % p
    Z3 = vvv

    Z3inv = pow(Z3, p - 2, p)
    x3 = X3 * Z3inv % p
    y3 = Y3 * Z3inv % p
    return (x3, y3)

def get64(z, words):
    """Return a C string with the number encoded into 64-bit words"""

    # Convert to Montgomery form, but only if it's not P521
    if words != 9:
        R = 2**(words * 64)
        x = z * R % p
    else:
        x = z

    result = []
    for _ in range(words):
        masked = x & ((1 << 64) - 1)
        result.append("0x%016XULL" % masked)
        x >>= 64
    return ",".join(result)

def _get_locales(prefix: str | None, normalize: bool) -> tuple[str, ...]:
    if platform.system() in ("Linux", "Darwin"):
        raw_locales = subprocess.check_output(["locale", "-a"])
        # raw_locales is "\n" separated list of locales
        # it may contain non-decodable parts, so split
        # extract what we can and then rejoin.
        out_locales = []
        for raw_locale in raw_locales.split(b"\n"):
            try:
                out_locales.append(
                    str(raw_locale, encoding=cast("str", options.display.encoding))
                )
            except UnicodeError:
                # 'locale -a' is used to populated 'raw_locales' and on
                # Redhat 7 Linux (and maybe others) prints locale names
                # using windows-1252 encoding.  Bug only triggered by
                # a few special characters and when there is an
                # extensive list of installed locales.
                out_locales.append(str(raw_locale, encoding="windows-1252"))
    elif platform.system() == "Windows":
        # Note: is_platform_windows causes circular import here
        out_locales = _WINDOWS_LOCALES
        # These are already spelled the way the CRT wants them; running them
        #  through the POSIX alias table would rename them ("ar-SA" -> "ar_AA").
        normalize = False
    else:
        return ()

    if prefix is None:
        return tuple(_valid_locales(out_locales, normalize))

    pattern = re.compile(f"{prefix}.*")
    found = pattern.findall("\n".join(out_locales))
    return tuple(_valid_locales(found, normalize))

def _get_single_key(pat: str, warn: bool = True, extra_stacklevel: int = 0) -> str:
    keys = _select_options(pat)
    if len(keys) == 0:
        if warn:
            _warn_if_deprecated(pat, extra_stacklevel=extra_stacklevel)
        raise OptionError(f"No such keys(s): {pat!r}")
    if len(keys) > 1:
        raise OptionError("Pattern matched multiple keys")
    key = keys[0]

    if warn:
        _warn_if_deprecated(key, extra_stacklevel=extra_stacklevel)

    key = _translate_key(key)

    return key

def _set_option_impl(*args: Any, warn: bool = True, extra_stacklevel: int = 0) -> None:
    # GH#63235: `warn` and `extra_stacklevel` let option_context warn exactly
    # once, aimed at the caller rather than at contextlib.
    # Handle dictionary input
    if len(args) == 1 and isinstance(args[0], dict):
        args = tuple(kv for item in args[0].items() for kv in item)

    nargs = len(args)
    if not nargs or nargs % 2 != 0:
        raise ValueError("Must provide an even number of non-keyword arguments")

    for k, v in zip(args[::2], args[1::2], strict=True):
        key = _get_single_key(k, warn=warn, extra_stacklevel=extra_stacklevel)

        opt = _get_registered_option(key)
        if opt and opt.validator:
            opt.validator(v)

        # walk the nested dict
        root, k_root = _get_root(key)
        root[k_root] = v

        if opt is not None and opt.cb:
            opt.cb(key)

def _get_deprecated_option(key: str) -> DeprecatedOption | None:
    """
    Retrieves the metadata for a deprecated option, if `key` is deprecated.

    Returns
    -------
    DeprecatedOption (namedtuple) if key is deprecated, None otherwise
    """
    try:
        d = _deprecated_options[key]
    except KeyError:
        return None
    else:
        return d

def _translate_key(key: str) -> str:
    """
    if `key` is deprecated and a replacement key defined, will return the
    replacement key, otherwise returns `key` as-is
    """
    d = _get_deprecated_option(key)
    if d:
        return d.rkey or key
    else:
        return key

def is_one_of_factory(legal_values: Sequence) -> Callable[[Any], None]:
    callables = [c for c in legal_values if callable(c)]
    legal_values = [c for c in legal_values if not callable(c)]

    def inner(x: object) -> None:
        if x not in legal_values:
            if not any(c(x) for c in callables):
                uvals = [str(lval) for lval in legal_values]
                pp_values = "|".join(uvals)
                msg = f"Value must be one of {pp_values}"
                if len(callables):
                    msg += " or a callable"
                raise ValueError(msg)

    return inner

def __setattr__(self, key: str, val: Any) -> None:
    prefix = object.__getattribute__(self, "prefix")
    if prefix:
        prefix += "."
    prefix += key
    # you can't set new keys
    # can you can't overwrite subtrees
    if key in self.d and not isinstance(self.d[key], dict):
        set_option(prefix, val)
    else:
        raise OptionError("You can only set the value of existing options")

def __getattr__(self, key: str) -> Any:
    prefix = object.__getattribute__(self, "prefix")
    if prefix:
        prefix += "."
    prefix += key
    try:
        v = object.__getattribute__(self, "d")[key]
    except KeyError as err:
        raise OptionError("No such option") from err
    if isinstance(v, dict):
        return DictWrapper(v, prefix)
    else:
        return get_option(prefix)

def infer_freq_str(
    index: DatetimeIndex | TimedeltaIndex | Series | DatetimeLikeArrayMixin,
) -> str | None:
    """
    Internal version of infer_freq that returns a string without
    emitting a deprecation warning.
    """
    from pandas.core.api import DatetimeIndex

    if isinstance(index, ABCSeries):
        values = index._values

        if isinstance(index.dtype, ArrowDtype):
            import pyarrow as pa

            if pa.types.is_timestamp(values.dtype.pyarrow_dtype):
                # GH#58403
                values = values._to_datetimearray()

        if not (
            lib.is_np_dtype(values.dtype, "mM")
            or isinstance(values.dtype, DatetimeTZDtype)
            or values.dtype == object
        ):
            raise TypeError(
                "cannot infer freq from a non-convertible dtype "
                f"on a Series of {index.dtype}"
            )
        index = values

    inferer: _FrequencyInferer

    if not hasattr(index, "dtype"):
        pass
    elif isinstance(index.dtype, PeriodDtype):
        raise TypeError(
            "PeriodIndex given. Check the `freq` attribute instead of using infer_freq."
        )
    elif lib.is_np_dtype(index.dtype, "m"):
        # Allow TimedeltaIndex and TimedeltaArray
        inferer = _TimedeltaFrequencyInferer(index)
        return inferer.get_freq()

    elif is_numeric_dtype(index.dtype):
        raise TypeError(
            f"cannot infer freq from a non-convertible index of dtype {index.dtype}"
        )

    if not isinstance(index, DatetimeIndex):
        index = DatetimeIndex(index, copy=False)

    inferer = _FrequencyInferer(index)
    return inferer.get_freq()

def _maybe_add_count(base: str, count: float) -> str:
    if count != 1:
        assert count == int(count)
        count = int(count)
        return f"{count}{base}"
    else:
        return base

def is_subperiod(source, target) -> bool:
    """
    Returns True if downsampling is possible between source and target
    frequencies

    Parameters
    ----------
    source : str or DateOffset
        Frequency converting from
    target : str or DateOffset
        Frequency converting to

    Returns
    -------
    bool
    """
    if target is None or source is None:
        return False
    source = _maybe_coerce_freq(source)
    target = _maybe_coerce_freq(target)

    if _is_annual(target):
        if _is_annual(source):
            return get_rule_month(source) == get_rule_month(target)
        if _is_quarterly(source):
            return _quarter_months_conform(
                get_rule_month(source), get_rule_month(target)
            )
        return source in {"D", "C", "B", "M", "h", "min", "s", "ms", "us", "ns"}
    elif _is_quarterly(target):
        if _is_quarterly(source):
            return _quarter_months_conform(
                get_rule_month(source), get_rule_month(target)
            )
        return source in {"D", "C", "B", "M", "h", "min", "s", "ms", "us", "ns"}
    elif _is_monthly(target):
        return source in {target, "D", "C", "B", "h", "min", "s", "ms", "us", "ns"}
    elif _is_weekly(target):
        return source in {target, "D", "C", "B", "h", "min", "s", "ms", "us", "ns"}
    elif target == "B":
        return source in {"B", "h", "min", "s", "ms", "us", "ns"}
    elif target == "C":
        return source in {"C", "h", "min", "s", "ms", "us", "ns"}
    elif target == "D":
        return source in {"D", "h", "min", "s", "ms", "us", "ns"}
    elif target == "h":
        return source in {"h", "min", "s", "ms", "us", "ns"}
    elif target == "min":
        return source in {"min", "s", "ms", "us", "ns"}
    elif target == "s":
        return source in {"s", "ms", "us", "ns"}
    elif target == "ms":
        return source in {"ms", "us", "ns"}
    elif target == "us":
        return source in {"us", "ns"}
    elif target == "ns":
        return source in {"ns"}
    else:
        return False

def is_superperiod(source, target) -> bool:
    """
    Returns True if upsampling is possible between source and target
    frequencies

    Parameters
    ----------
    source : str or DateOffset
        Frequency converting from
    target : str or DateOffset
        Frequency converting to

    Returns
    -------
    bool
    """
    if target is None or source is None:
        return False
    source = _maybe_coerce_freq(source)
    target = _maybe_coerce_freq(target)

    if _is_annual(source):
        if _is_annual(target):
            return get_rule_month(source) == get_rule_month(target)

        if _is_quarterly(target):
            smonth = get_rule_month(source)
            tmonth = get_rule_month(target)
            return _quarter_months_conform(smonth, tmonth)
        return target in {"D", "C", "B", "M", "h", "min", "s", "ms", "us", "ns"}
    elif _is_quarterly(source):
        if _is_quarterly(target):
            return _quarter_months_conform(
                get_rule_month(source), get_rule_month(target)
            )
        return target in {"D", "C", "B", "M", "h", "min", "s", "ms", "us", "ns"}
    elif _is_monthly(source):
        return target in {source, "D", "C", "B", "h", "min", "s", "ms", "us", "ns"}
    elif _is_weekly(source):
        return target in {source, "D", "C", "B", "h", "min", "s", "ms", "us", "ns"}
    elif source == "B":
        return target in {"D", "C", "B", "h", "min", "s", "ms", "us", "ns"}
    elif source == "C":
        return target in {"D", "C", "B", "h", "min", "s", "ms", "us", "ns"}
    elif source == "D":
        return target in {"D", "C", "B", "h", "min", "s", "ms", "us", "ns"}
    elif source == "h":
        return target in {"h", "min", "s", "ms", "us", "ns"}
    elif source == "min":
        return target in {"min", "s", "ms", "us", "ns"}
    elif source == "s":
        return target in {"s", "ms", "us", "ns"}
    elif source == "ms":
        return target in {"ms", "us", "ns"}
    elif source == "us":
        return target in {"us", "ns"}
    elif source == "ns":
        return target in {"ns"}
    else:
        return False

def __init__(self, index) -> None:
    self.index = index
    self.i8values = index.asi8

    # For get_unit_from_dtype we need the dtype to the underlying ndarray,
    #  which for tz-aware is not the same as index.dtype
    if isinstance(index, ABCIndex):
        # error: Item "ndarray[Any, Any]" of "Union[ExtensionArray,
        # ndarray[Any, Any]]" has no attribute "_ndarray"
        self._creso = get_unit_from_dtype(
            index._data._ndarray.dtype  # type: ignore[union-attr]
        )
    else:
        # otherwise we have DTA/TDA
        self._creso = get_unit_from_dtype(index._ndarray.dtype)

    # This moves the values, which are implicitly in UTC, to the
    # the timezone so they are in local time
    if hasattr(index, "tz"):
        if index.tz is not None:
            self.i8values = tz_convert_from_utc(
                self.i8values, index.tz, reso=self._creso
            )

    if len(index) < 3:
        raise ValueError("Need at least 3 dates to infer frequency")

    self.is_monotonic = (
        self.index._is_monotonic_increasing or self.index._is_monotonic_decreasing

def get_freq(self) -> str | None:
    """
    Find the appropriate frequency string to describe the inferred
    frequency of self.i8values

    Returns
    -------
    str or None
    """
    if not self.is_monotonic or not self.index._is_unique:
        return None

    delta = self.deltas[0]
    ppd = periods_per_day(self._creso)
    if delta and _is_multiple(delta, ppd):
        return self._infer_daily_rule()

    # Business hourly, maybe. 17: one day / 65: one weekend
    if self.hour_deltas in ([1, 17], [1, 65], [1, 17, 65]):
        return "bh"

    # Possibly intraday frequency.  Here we use the
    # original .asi8 values as the modified values
    # will not work around DST transitions.  See #8772
    if not self.is_unique_asi8:
        return None

    delta = self.deltas_asi8[0]
    pph = ppd // 24
    ppm = pph // 60
    pps = ppm // 60
    if _is_multiple(delta, pph):
        # Hours
        return _maybe_add_count("h", delta / pph)
    elif _is_multiple(delta, ppm):
        # Minutes
        return _maybe_add_count("min", delta / ppm)
    elif _is_multiple(delta, pps):
        # Seconds
        return _maybe_add_count("s", delta / pps)
    elif _is_multiple(delta, (pps // 1000)):
        # Milliseconds
        return _maybe_add_count("ms", delta / (pps // 1000))
    elif _is_multiple(delta, (pps // 1_000_000)):
        # Microseconds
        return _maybe_add_count("us", delta / (pps // 1_000_000))
    else:
        # Nanoseconds
        return _maybe_add_count("ns", delta)

def _infer_daily_rule(self) -> str | None:
    annual_rule = self._get_annual_rule()
    if annual_rule:
        nyears = self.ydiffs[0]
        month = MONTH_ALIASES[self.rep_stamp.month]
        alias = f"{annual_rule}-{month}"
        return _maybe_add_count(alias, nyears)

    quarterly_rule = self._get_quarterly_rule()
    if quarterly_rule:
        nquarters = self.mdiffs[0] / 3
        if quarterly_rule in ("QS", "BQS"):
            # GH#36939 the anchor month is only known up to mod 3; use the
            #  first-calendar-quarter representative so that to_period on
            #  e.g. Jan/Apr/Jul/Oct starts (QS-JAN) keeps the calendar
            #  convention Q-DEC
            mod_dict = {1: 1, 2: 2, 0: 3}
        else:
            mod_dict = {0: 12, 2: 11, 1: 10}
        month = MONTH_ALIASES[mod_dict[self.rep_stamp.month % 3]]
        alias = f"{quarterly_rule}-{month}"
        return _maybe_add_count(alias, nquarters)

    monthly_rule = self._get_monthly_rule()
    if monthly_rule:
        return _maybe_add_count(monthly_rule, self.mdiffs[0])

    if self.is_unique:
        return self._get_daily_rule()

    if self._is_business_daily():
        return "B"

    wom_rule = self._get_wom_rule()
    if wom_rule:
        return wom_rule

    return None

def _get_annual_rule(self) -> str | None:
    if len(self.ydiffs) > 1:
        return None

    if len(np.unique(self.fields["M"])) > 1:
        return None

    pos_check = self.month_position_check()

    if pos_check is None:
        return None
    else:
        return {"cs": "YS", "bs": "BYS", "ce": "YE", "be": "BYE"}.get(pos_check)

def _get_quarterly_rule(self) -> str | None:
    if len(self.mdiffs) > 1:
        return None

    if not self.mdiffs[0] % 3 == 0:
        return None

    pos_check = self.month_position_check()

    if pos_check is None:
        return None
    else:
        return {"cs": "QS", "bs": "BQS", "ce": "QE", "be": "BQE"}.get(pos_check)

def _get_monthly_rule(self) -> str | None:
    if len(self.mdiffs) > 1:
        return None
    pos_check = self.month_position_check()

    if pos_check is None:
        return None
    else:
        return {"cs": "MS", "bs": "BMS", "ce": "ME", "be": "BME"}.get(pos_check)

def __repr__(self) -> str:
    info = ""
    if self.year is not None:
        info += f"year={self.year}, "
    info += f"month={self.month}, day={self.day}, "

    if self.offset is not None:
        info += f"offset={self.offset}"

    if self.observance is not None:
        info += f"observance={self.observance}"

    repr = f"Holiday: {self.name} ({info})"
    return repr

def __init__(self, name: str = "", rules=None) -> None:
    super().__init__()
    if not name:
        name = type(self).__name__
    self.name = name

    if rules is not None:
        self.rules = rules

def assert_class_equal(
    left: Any, right: Any, exact: bool | str = True, obj: str = "Input"
) -> None:
    """
    Checks classes are equal.
    """
    __tracebackhide__ = True

    def repr_class(x: Any) -> Any:
        if isinstance(x, Index):
            # return Index as it is to include values in the error message
            return x

        return type(x).__name__

    def is_class_equiv(idx: Index) -> bool:
        """Classes that are a RangeIndex (sub-)instance or exactly an `Index` .

        This only checks class equivalence. There is a separate check that the
        dtype is int64.
        """
        return type(idx) is Index or isinstance(idx, RangeIndex)

    if type(left) == type(right):
        return

    if exact == "equiv":
        if is_class_equiv(left) and is_class_equiv(right):
            return

    msg = f"{obj} classes are different"
    raise_assert_detail(obj, msg, repr_class(left), repr_class(right))

def assert_is_sorted(seq: Index | Series | np.ndarray | ExtensionArray) -> None:
    """Assert that the sequence is sorted."""
    if isinstance(seq, (Index, Series)):
        seq = seq._values
    # sorting does not change precisions
    if isinstance(seq, np.ndarray):
        assert_numpy_array_equal(seq, np.sort(np.array(seq)))
    else:
        assert_extension_array_equal(seq, seq[seq.argsort()])

def raise_assert_detail(
    obj: Any,
    message: str,
    left: Any,
    right: Any,
    diff: Any = None,
    first_diff: Any = None,
    index_values: Index | np.ndarray | None = None,
) -> NoReturn:
    __tracebackhide__ = True

    msg = f"""{obj} are different

{message}"""

    if isinstance(index_values, Index):
        index_values = np.asarray(index_values)

    if isinstance(index_values, np.ndarray):
        msg += f"\n[index]: {pprint_thing(index_values)}"

    if isinstance(left, np.ndarray):
        left = pprint_thing(left)
    elif isinstance(left, (CategoricalDtype, StringDtype, NumpyEADtype)):
        left = repr(left)

    if isinstance(right, np.ndarray):
        right = pprint_thing(right)
    elif isinstance(right, (CategoricalDtype, StringDtype, NumpyEADtype)):
        right = repr(right)

    msg += f"""
[left]:  {left}
[right]: {right}"""

    if diff is not None:
        msg += f"\n[diff]: {diff}"

    if first_diff is not None:
        msg += f"\n{first_diff}"

    raise AssertionError(msg)

def assert_equal(left: Any, right: Any, **kwargs: Any) -> None:
    """
    Wrapper for tm.assert_*_equal to dispatch to the appropriate test function.

    Parameters
    ----------
    left, right : Index, Series, DataFrame, ExtensionArray, or np.ndarray
        The two items to be compared.
    **kwargs
        All keyword arguments are passed through to the underlying assert method.
    """
    __tracebackhide__ = True

    if isinstance(left, Index):
        # retain the long-standing hard freq check for datetimelike Index;
        #  the check_freq deprecation in assert_index_equal only warns by
        #  default. GH#51920
        if isinstance(left, (DatetimeIndex, TimedeltaIndex)):
            kwargs.setdefault("check_freq", True)
        assert_index_equal(left, right, **kwargs)
    elif isinstance(left, Series):
        assert_series_equal(left, right, **kwargs)
    elif isinstance(left, DataFrame):
        assert_frame_equal(left, right, **kwargs)
    elif isinstance(left, IntervalArray):
        assert_interval_array_equal(left, right, **kwargs)
    elif isinstance(left, PeriodArray):
        assert_period_array_equal(left, right, **kwargs)
    elif isinstance(left, DatetimeArray):
        assert_datetime_array_equal(left, right, **kwargs)
    elif isinstance(left, TimedeltaArray):
        assert_timedelta_array_equal(left, right, **kwargs)
    elif isinstance(left, ExtensionArray):
        assert_extension_array_equal(left, right, **kwargs)
    elif isinstance(left, np.ndarray):
        assert_numpy_array_equal(left, right, **kwargs)
    elif isinstance(left, str):
        assert kwargs == {}
        assert left == right
    else:
        assert kwargs == {}
        assert_almost_equal(left, right)

