def _assert_caught_expected_warnings(
    *,
    caught_warnings: Sequence[warnings.WarningMessage],
    expected_warning: type[Warning] | tuple[type[Warning], ...],
    match: str | None,
    check_stacklevel: bool,
) -> None:
    """Assert that there was the expected warning among the caught warnings."""
    saw_warning = False
    matched_message = False
    unmatched_messages = []
    warning_name = (
        tuple(x.__name__ for x in expected_warning)
        if isinstance(expected_warning, tuple)
        else expected_warning.__name__
    )

    for actual_warning in caught_warnings:
        if issubclass(actual_warning.category, expected_warning):
            saw_warning = True

            if check_stacklevel:
                _assert_raised_with_correct_stacklevel(actual_warning)

            if match is not None:
                if re.search(match, str(actual_warning.message)):
                    matched_message = True
                else:
                    unmatched_messages.append(actual_warning.message)

    if not saw_warning:
        raise AssertionError(f"Did not see expected warning of class {warning_name!r}")

    if match and not matched_message:
        raise AssertionError(
            f"Did not see warning {warning_name!r} "
            f"matching '{match}'. The emitted warning messages are "
            f"{unmatched_messages}"

def _assert_caught_no_extra_warnings(
    *,
    caught_warnings: Sequence[warnings.WarningMessage],
    expected_warning: type[Warning] | bool | tuple[type[Warning], ...] | None,
) -> None:
    """Assert that no extra warnings apart from the expected ones are caught."""
    extra_warnings = []

    for actual_warning in caught_warnings:
        if _is_unexpected_warning(actual_warning, expected_warning):
            # GH#38630 pytest.filterwarnings does not suppress these.
            if actual_warning.category == ResourceWarning:
                # GH 44732: Don't make the CI flaky by filtering SSL-related
                # ResourceWarning from dependencies
                if "unclosed <ssl.SSLSocket" in str(actual_warning.message):
                    continue
                # GH 44844: Matplotlib leaves font files open during the entire process
                # upon import. Don't make CI flaky if ResourceWarning raised
                # due to these open files.
                if any("matplotlib" in mod for mod in sys.modules):
                    continue
            if actual_warning.category == EncodingWarning:
                # EncodingWarnings are checked in the CI
                # pyproject.toml errors on EncodingWarnings in pandas
                # Ignore EncodingWarnings from other libraries
                continue
            extra_warnings.append(
                (
                    actual_warning.category.__name__,
                    actual_warning.message,
                    actual_warning.filename,
                    actual_warning.lineno,
                )
            )

    if extra_warnings:
        raise AssertionError(f"Caused unexpected warning(s): {extra_warnings!r}")

def _is_unexpected_warning(
    actual_warning: warnings.WarningMessage,
    expected_warning: type[Warning] | bool | tuple[type[Warning], ...] | None,
) -> bool:
    """Check if the actual warning issued is unexpected."""
    if actual_warning and not expected_warning:
        return True
    expected_warning = cast("type[Warning]", expected_warning)
    return bool(not issubclass(actual_warning.category, expected_warning))

def raises_chained_assignment_error(
    extra_warnings: tuple[type[Warning], ...] = (),
    extra_match: tuple[str | None, ...] = (),
) -> AbstractContextManager:
    from pandas._testing import assert_produces_warning

    if CHAINED_WARNING_DISABLED:
        if not extra_warnings:
            from contextlib import nullcontext

            return nullcontext()
        else:
            return assert_produces_warning(
                extra_warnings,
                match=extra_match,
            )
    else:
        warning = ChainedAssignmentError
        match = (
            "A value is being set on a copy of a DataFrame or Series "
            "through chained assignment"
        )
        if extra_warnings:
            warning = (warning, *extra_warnings)  # type: ignore[assignment]
        return assert_produces_warning(
            warning,
            match=(match, *extra_match),

def box_expected(expected: Any, box_cls: Any, transpose: bool = True) -> Any:
    """
    Helper function to wrap the expected output of a test in a given box_class.

    Parameters
    ----------
    expected : np.ndarray, Index, Series
    box_cls : {Index, Series, DataFrame}

    Returns
    -------
    subclass of box_cls
    """
    if box_cls is pd.array:
        if isinstance(expected, RangeIndex):
            # pd.array would return an IntegerArray
            expected = NumpyExtensionArray(np.asarray(expected._values))
        else:
            expected = pd.array(expected, copy=False)
    elif box_cls is Index:
        expected = Index(expected, copy=False)
    elif box_cls is Series:
        expected = Series(expected)
    elif box_cls is DataFrame:
        expected = Series(expected).to_frame()
        if transpose:
            # for vector operations, we need a DataFrame to be a single-row,
            #  not a single-column, in order to operate against non-DataFrame
            #  vectors of the same length. But convert to two rows to avoid
            #  single-row special cases in datetime arithmetic
            expected = expected.T
            expected = pd.concat([expected] * 2, ignore_index=True)
    elif box_cls is np.ndarray or box_cls is np.array:
        expected = np.array(expected)
    elif box_cls is to_array:
        expected = to_array(expected)
    else:
        raise NotImplementedError(box_cls)
    return expected

def _pa_buffer_addresses(pa_data: pa.ChunkedArray) -> set[int]:
    """
    Addresses of the non-empty buffers backing a pyarrow ChunkedArray.

    Zero-length buffers are excluded because distinct empty arrays can be
    handed out the same address, which would look like sharing.
    """
    return {
        buf.address
        for chunk in pa_data.iterchunks()
        for buf in chunk.buffers()
        if buf is not None and buf.size > 0

def shares_memory(left: Any, right: Any) -> bool:
    """
    Pandas-compat for np.shares_memory.
    """
    if isinstance(left, np.ndarray) and isinstance(right, np.ndarray):
        return np.shares_memory(left, right)
    elif isinstance(left, np.ndarray):
        # Call with reversed args to get to unpacking logic below.
        return shares_memory(right, left)

    if isinstance(left, RangeIndex):
        return False
    if isinstance(left, MultiIndex):
        return any(shares_memory(codes, right) for codes in left._codes)
    if isinstance(left, (Index, Series)):
        if isinstance(right, (Index, Series)):
            return shares_memory(left._values, right._values)
        return shares_memory(left._values, right)

    if isinstance(left, NDArrayBackedExtensionArray):
        return shares_memory(left._ndarray, right)
    if isinstance(left, pd.core.arrays.SparseArray):
        return shares_memory(left.sp_values, right)
    if isinstance(left, pd.core.arrays.IntervalArray):
        return shares_memory(left._left, right) or shares_memory(left._right, right)

    if isinstance(left, ArrowExtensionArray):
        if isinstance(right, ArrowExtensionArray):
            # https://github.com/pandas-dev/pandas/pull/43930#discussion_r736862669
            left_addrs = _pa_buffer_addresses(left._pa_array)
            right_addrs = _pa_buffer_addresses(right._pa_array)
            return not left_addrs.isdisjoint(right_addrs)
        else:
            # if we have one ArrowExtensionArray and one other array, assume
            # they can only share memory if they share the same numpy buffer
            return np.shares_memory(left, right)

    if isinstance(left, BaseMaskedArray):
        # By convention, we'll say these share memory if they share *either*
        #  the _data or the _mask
        if isinstance(right, BaseMaskedArray):
            return shares_memory(left._data, right._data) or shares_memory(
                left._mask, right._mask
            )
        return shares_memory(left._data, right) or shares_memory(left._mask, right)

    if isinstance(left, DataFrame) and len(left._mgr.blocks) == 1:
        arr = left._mgr.blocks[0].values
        return shares_memory(arr, right)

    raise NotImplementedError(type(left), type(right))

def run_multithreaded(
    closure: Callable,
    max_workers: int,
    arguments: Iterable | None = None,
    pass_barrier: bool = False,
) -> None:
    with ThreadPoolExecutor(max_workers=max_workers) as tpe:
        if arguments is None:
            arguments = []
        else:
            arguments = list(arguments)

        if pass_barrier:
            barrier = threading.Barrier(max_workers)
            arguments.append(barrier)

        try:
            futures = []
            for _ in range(max_workers):
                futures.append(tpe.submit(closure, *arguments))  # noqa: PERF401
        except RuntimeError as e:
            import pytest

            pytest.skip(
                f"Spawning {max_workers} threads failed with "
                f"error {e!r} (likely due to resource limits on the "
                "system running the tests)"
            )
        finally:
            if len(futures) < max_workers and pass_barrier:
                barrier.abort()
        for f in futures:
            f.result()

def _validate_sharex(sharex: bool | None, ax, by) -> bool:
    if sharex is None:
        # if by is defined, subplots are used and sharex should be False
        if ax is None and by is None:
            sharex = True
        else:
            # if we get an axis, the users should do the visibility
            # setting...
            sharex = False
    elif not is_bool(sharex):
        raise TypeError("sharex must be a bool or None")
    return bool(sharex)

def _validate_log_kwd(
    cls,
    kwd: str,
    value: bool | Literal["sym"] | None,
) -> bool | Literal["sym"] | None:
    if (
        value is None
        or isinstance(value, bool)
        or (isinstance(value, str) and value == "sym")
    ):
        return value
    raise ValueError(
        f"keyword '{kwd}' should be bool, None, or 'sym', not '{value}'"

def _validate_color_args(self, color, colormap):
    if color is lib.no_default:
        # It was not provided by the user
        if "colors" in self.kwds and colormap is not None:
            warnings.warn(
                "'color' and 'colormap' cannot be used simultaneously. "
                "Using 'color'",
                stacklevel=find_stack_level(),
            )
        return None
    if self.nseries == 1 and color is not None and not is_list_like(color):
        # support series.plot(color='green')
        color = [color]

    if isinstance(color, tuple) and self.nseries == 1 and len(color) in (3, 4):
        # support RGB and RGBA tuples in series plot
        color = [color]

    if colormap is not None:
        warnings.warn(
            "'color' and 'colormap' cannot be used simultaneously. Using 'color'",
            stacklevel=find_stack_level(),
        )

    if self.style is not None:
        if isinstance(self.style, dict):
            styles = [self.style[col] for col in self.columns if col in self.style]  # type: ignore[union-attr]  # pyright: ignore[reportOptionalIterable]
        elif is_list_like(self.style):
            styles = self.style
        else:
            styles = [self.style]
        # need only a single match
        for s in styles:
            if _color_in_style(s):
                raise ValueError(
                    "Cannot pass 'style' string with a color symbol and "
                    "'color' keyword argument. Please use one or the "
                    "other or pass 'style' without a color symbol"
                )
    return color

def _get_nseries(self, data: Series | DataFrame) -> int:
    # When `by` is explicitly assigned, grouped data size will be defined, and
    # this will determine number of subplots to have, aka `self.nseries`
    if data.ndim == 1:
        return 1
    elif self.by is not None and self._kind == "hist":
        return len(self._grouped)
    elif self.by is not None and self._kind == "box":
        return len(self.columns)  # type: ignore[arg-type]
    else:
        return data.shape[1]

def _maybe_right_yaxis(self, ax: Axes, axes_num: int) -> Axes:
    if not self.on_right(axes_num):
        # secondary axes may be passed via ax kw
        return self._get_ax_layer(ax)

    if hasattr(ax, "right_ax"):
        # if it has right_ax property, ``ax`` must be left axes
        return ax.right_ax
    elif hasattr(ax, "left_ax"):
        # if it has left_ax property, ``ax`` must be right axes
        return ax
    else:
        # otherwise, create twin axes
        orig_ax, new_ax = ax, ax.twinx()
        # TODO: use Matplotlib public API when available
        new_ax._get_lines = orig_ax._get_lines  # type: ignore[attr-defined]
        # TODO #54485
        new_ax._get_patches_for_fill = (  # type: ignore[attr-defined]
            orig_ax._get_patches_for_fill  # type: ignore[attr-defined]
        )
        # TODO #54485
        orig_ax.right_ax, new_ax.left_ax = (  # type: ignore[attr-defined]
            new_ax,
            orig_ax,
        )

        if not self._has_plotted_object(orig_ax):  # no data on left y
            orig_ax.get_yaxis().set_visible(False)

        if self.logy is True or self.loglog is True:
            new_ax.set_yscale("log")
        elif self.logy == "sym" or self.loglog == "sym":
            new_ax.set_yscale("symlog")
        return new_ax

def _axes_and_fig(self) -> tuple[Sequence[Axes], Figure]:
    import matplotlib.pyplot as plt

    if self.subplots:
        naxes = (
            self.nseries if isinstance(self.subplots, bool) else len(self.subplots)
        )
        fig, axes = create_subplots(
            naxes=naxes,
            sharex=self.sharex,
            sharey=self.sharey,
            figsize=self.figsize,
            ax=self.ax,
            layout=self.layout,
            layout_type=self._layout_type,
        )
    elif self.ax is None:
        fig = plt.figure(figsize=self.figsize)
        axes = fig.add_subplot(111)
    else:
        fig = self.ax.get_figure()
        if self.figsize is not None:
            fig.set_size_inches(self.figsize)
        axes = self.ax

    axes = np.fromiter(flatten_axes(axes), dtype=object)

    if self.logx is True or self.loglog is True:
        [a.set_xscale("log") for a in axes]
    elif self.logx == "sym" or self.loglog == "sym":
        [a.set_xscale("symlog") for a in axes]

    if self.logy is True or self.loglog is True:
        [a.set_yscale("log") for a in axes]
    elif self.logy == "sym" or self.loglog == "sym":
        [a.set_yscale("symlog") for a in axes]

    axes_seq = cast("Sequence[Axes]", axes)
    return axes_seq, fig

def result(self):
    """
    Return result axes
    """
    if self.subplots:
        if self.layout is not None and not is_list_like(self.ax):
            # error: "Sequence[Any]" has no attribute "reshape"
            return self.axes.reshape(*self.layout)  # type: ignore[attr-defined]
        else:
            return self.axes
    else:
        sec_true = isinstance(self.secondary_y, bool) and self.secondary_y
        # error: Argument 1 to "len" has incompatible type "Union[bool,
        # Tuple[Any, ...], List[Any], ndarray[Any, Any]]"; expected "Sized"
        all_sec = (
            is_list_like(self.secondary_y) and len(self.secondary_y) == self.nseries  # type: ignore[arg-type]
        )
        if sec_true or all_sec:
            # if all data is plotted on secondary, return right axes
            return self._get_ax_layer(self.axes[0], primary=False)
        else:
            return self.axes[0]

def _convert_to_ndarray(data):
    # GH31357: categorical columns are processed separately
    if isinstance(data.dtype, CategoricalDtype):
        return data

    # GH32073: cast to float if values contain nulled integers
    if (
        is_integer_dtype(data.dtype)
        or is_float_dtype(data.dtype)
        or is_bool_dtype(data.dtype)
    ) and isinstance(data.dtype, ExtensionDtype):
        return data.to_numpy(dtype="float", na_value=np.nan)

    # GH25587: cast ExtensionArray of pandas (IntegerArray, etc.) to
    # np.ndarray before plot.
    if len(data) > 0:
        return np.asarray(data)

    return data

def _ensure_frame(self, data) -> DataFrame:
    if isinstance(data, ABCSeries):
        label = self.label
        if label is None and data.name is None:
            label = ""
        if label is None:
            # We'll end up with columns of [0] instead of [None]
            data = data.to_frame()
        else:
            data = data.to_frame(name=label)
    elif self._kind in ("hist", "box"):
        cols = self.columns if self.by is None else self.columns + self.by  # type: ignore[operator]
        data = data.loc[:, cols]
    return data

def _add_table(self) -> None:
    if self.table is False:
        return
    elif self.table is True:
        data = self.data.transpose()
    else:
        data = self.table
    ax = self._get_ax(0)
    tools.table(ax, data)

def _post_plot_logic_common(self, ax: Axes) -> None:
    """Common post process for each axes"""
    if self.orientation == "vertical" or self.orientation is None:
        type(self)._apply_axis_properties(
            ax.xaxis, rot=self.rot, fontsize=self.fontsize
        )
        type(self)._apply_axis_properties(ax.yaxis, fontsize=self.fontsize)

        if hasattr(ax, "right_ax"):
            type(self)._apply_axis_properties(
                ax.right_ax.yaxis, fontsize=self.fontsize
            )

    elif self.orientation == "horizontal":
        type(self)._apply_axis_properties(
            ax.yaxis, rot=self.rot, fontsize=self.fontsize
        )
        type(self)._apply_axis_properties(ax.xaxis, fontsize=self.fontsize)

        if hasattr(ax, "right_ax"):
            type(self)._apply_axis_properties(
                ax.right_ax.yaxis, fontsize=self.fontsize
            )
    else:  # pragma no cover
        raise ValueError

def _adorn_subplots(self, fig: Figure) -> None:
    """Common post process unrelated to data"""
    if len(self.axes) > 0:
        all_axes = self._get_subplots(fig)
        nrows, ncols = self._get_axes_layout(fig)
        handle_shared_axes(
            axarr=all_axes,
            nplots=len(all_axes),
            naxes=nrows * ncols,
            nrows=nrows,
            ncols=ncols,
            sharex=self.sharex,
            sharey=self.sharey,
        )

    for ax in self.axes:
        ax = getattr(ax, "right_ax", ax)
        if self.yticks is not None:
            ax.set_yticks(self.yticks)

        if self.xticks is not None:
            ax.set_xticks(self.xticks)

        if self.ylim is not None:
            ax.set_ylim(self.ylim)

        if self.xlim is not None:
            ax.set_xlim(self.xlim)

        # GH9093, currently Pandas does not show ylabel, so if users provide
        # ylabel will set it as ylabel in the plot.
        if self.ylabel is not None:
            ax.set_ylabel(pprint_thing(self.ylabel))

        ax.grid(self.grid)

    if self.title:
        if self.subplots:
            if is_list_like(self.title):
                if not isinstance(self.subplots, bool):
                    if len(self.subplots) != len(self.title):
                        raise ValueError(
                            f"The number of titles ({len(self.title)}) must equal "
                            f"the number of subplots ({len(self.subplots)})."
                        )
                elif len(self.title) != self.nseries:
                    raise ValueError(
                        "The length of `title` must equal the number "
                        "of columns if using `title` of type `list` "
                        "and `subplots=True`.\n"
                        f"length of title = {len(self.title)}\n"
                        f"number of columns = {self.nseries}"
                    )

                for ax, title in zip(self.axes, self.title, strict=False):
                    ax.set_title(title)
            else:
                fig.suptitle(self.title)
        else:
            if is_list_like(self.title):
                msg = (
                    "Using `title` of type `list` is not supported "
                    "unless `subplots=True` is passed"
                )
                raise ValueError(msg)
            self.axes[0].set_title(self.title)

def _apply_axis_properties(
    axis: Axis, rot=None, fontsize: int | None = None
) -> None:
    """
    Tick creation within matplotlib is reasonably expensive and is
    internally deferred until accessed as Ticks are created/destroyed
    multiple times per draw. It's therefore beneficial for us to avoid
    accessing unless we will act on the Tick.
    """
    if rot is not None or fontsize is not None:
        # rot=0 is a valid setting, hence the explicit None check
        labels = axis.get_majorticklabels() + axis.get_minorticklabels()
        for label in labels:
            if rot is not None:
                label.set_rotation(rot)
            if fontsize is not None:
                label.set_fontsize(fontsize)

def legend_title(self) -> str | None:
    if not isinstance(self.data.columns, ABCMultiIndex):
        name = self.data.columns.name
        if name is not None:
            name = pprint_thing(name)
        return name
    else:
        stringified = map(pprint_thing, self.data.columns.names)
        return ",".join(stringified)

def _make_legend(self) -> None:
    ax, leg = self._get_ax_legend(self.axes[0])

    handles = []
    labels = []
    title = ""

    if not self.subplots:
        if leg is not None:
            title = leg.get_title().get_text()
            # Replace leg.legend_handles because it misses marker info
            handles = leg.legend_handles
            labels = [x.get_text() for x in leg.get_texts()]

        if self.legend:
            if self.legend == "reverse":
                handles += reversed(self.legend_handles)
                labels += reversed(self.legend_labels)
            else:
                handles += self.legend_handles
                labels += self.legend_labels

            if self.legend_title is not None:
                title = self.legend_title

        if len(handles) > 0:
            ax.legend(handles, labels, loc="best", title=title)

    elif self.subplots and self.legend:
        for ax in self.axes:
            if ax.get_visible():
                with warnings.catch_warnings():
                    warnings.filterwarnings(
                        "ignore",
                        "No artists with labels found to put in legend.",
                        UserWarning,
                    )
                    ax.legend(loc="best")

def _plot(
    cls, ax: Axes, x, y: np.ndarray, style=None, is_errorbar: bool = False, **kwds
):
    mask = isna(y)
    if mask.any():
        y = np.ma.array(y)
        y = np.ma.masked_where(mask, y)

    if isinstance(x, ABCIndex):
        x = x._mpl_repr()

    if is_errorbar:
        if "xerr" in kwds:
            kwds["xerr"] = np.array(kwds.get("xerr"))
        if "yerr" in kwds:
            kwds["yerr"] = np.array(kwds.get("yerr"))
        return ax.errorbar(x, y, **kwds)
    else:
        # prevent style kwarg from going to errorbar, where it is unsupported
        args = (x, y, style) if style is not None else (x, y)
        return ax.plot(*args, **kwds)

def _get_index_name(self) -> str | None:
    if isinstance(self.data.index, ABCMultiIndex):
        name = self.data.index.names
        if com.any_not_none(*name):
            name = ",".join([pprint_thing(x) for x in name])
        else:
            name = None
    else:
        name = self.data.index.name
        if name is not None:
            name = pprint_thing(name)

    # GH 45145, override the default axis label if one is provided.
    index_name = self._get_custom_index_name()
    if index_name is not None:
        name = pprint_thing(index_name)

    return name

def _col_idx_to_axis_idx(self, col_idx: int) -> int:
    """Return the index of the axis where the column at col_idx should be plotted"""
    if isinstance(self.subplots, list):
        # Subplots is a list: some columns will be grouped together in the same ax
        return next(
            group_idx
            for (group_idx, group) in enumerate(self.subplots)
            if col_idx in group
        )
    else:
        # subplots is True: one ax per column
        return col_idx

def on_right(self, i: int) -> bool:
    if isinstance(self.secondary_y, bool):
        return self.secondary_y

    if isinstance(self.secondary_y, (tuple, list, np.ndarray, ABCIndex)):
        return self.data.columns[i] in self.secondary_y

def _apply_style_colors(
    self, colors, kwds: dict[str, Any], col_num: int, label: str
):
    """
    Manage style and color based on column number and its label.
    Returns tuple of appropriate style and kwds which "color" may be added.
    """
    style = None
    if self.style is not None:
        if isinstance(self.style, list):
            try:
                style = self.style[col_num]
            except IndexError:
                pass
        elif isinstance(self.style, dict):
            style = self.style.get(label, style)
        else:
            style = self.style

    has_color = "color" in kwds or self.colormap is not None
    nocolor_style = style is None or not _color_in_style(style)
    if (has_color or self.subplots) and nocolor_style:
        if isinstance(colors, dict):
            kwds["color"] = colors[label]
        else:
            kwds["color"] = colors[col_num % len(colors)]
    return style, kwds

def _get_colors(
    self,
    num_colors: int | None = None,
    color_kwds: str = "color",
):
    if num_colors is None:
        num_colors = self.nseries
    if color_kwds == "color":
        color = self.color
    else:
        color = self.kwds.get(color_kwds)
    return get_standard_colors(
        num_colors=num_colors,
        colormap=self.colormap,
        color=color,

def _get_errorbars(
    self, label=None, index=None, xerr: bool = True, yerr: bool = True
) -> dict[str, Any]:
    errors = {}

    for kw, flag in zip(["xerr", "yerr"], [xerr, yerr], strict=True):
        if flag:
            err = self.errors[kw]
            # user provided label-matched dataframe of errors
            if isinstance(err, (ABCDataFrame, dict)):
                if label is not None and label in err.keys():
                    err = err[label]
                else:
                    err = None
            elif index is not None and err is not None:
                err = err[index]

            if err is not None:
                errors[kw] = err
    return errors

def _get_subplots(self, fig: Figure) -> list[Axes]:
    return [
        ax
        for ax in fig.get_axes()
        if (isinstance(ax, mpl.axes.Axes) and ax.get_subplotspec() is not None)

def __init__(self, data, x, y, **kwargs) -> None:
    MPLPlot.__init__(self, data, **kwargs)
    if x is None or y is None:
        raise ValueError(self._kind + " requires an x and y column")
    if is_integer(x) and not holds_integer(self.data.columns):
        x = self.data.columns[x]
    if is_integer(y) and not holds_integer(self.data.columns):
        y = self.data.columns[y]

    self.x = x
    self.y = y

def _get_c_values(self, color, color_by_categorical: bool, c_is_column: bool):
    c = self.c
    if c is not None and color is not None:
        raise TypeError("Specify exactly one of `c` and `color`")
    if c is None and color is None:
        c_values = mpl.rcParams["patch.facecolor"]
    elif color is not None:
        c_values = color
    elif color_by_categorical:
        c_values = self.data[c].cat.codes
    elif c_is_column:
        c_values = self.data[c]._values
    else:
        c_values = c
    return c_values

def _are_valid_colors(self, c_values: Series) -> bool:
    # check if c_values contains strings and if these strings are valid mpl colors.
    # no need to check numerics as these (and mpl colors) will be validated for us
    # in .Axes.scatter._parse_scatter_color_args(...)
    unique = np.unique(c_values)
    try:
        if len(c_values) and all(isinstance(c, str) for c in unique):
            mpl.colors.to_rgba_array(unique)

        return True

    except (TypeError, ValueError) as _:
        return False

def __init__(self, data, x, y, C=None, *, colorbar: bool = True, **kwargs) -> None:
    super().__init__(data, x, y, **kwargs)
    if is_integer(C) and not holds_integer(self.data.columns):
        C = self.data.columns[C]
    self.C = C

    self.colorbar = colorbar

    # Scatter plot allows to plot objects data
    if len(self.data[self.x]._get_numeric_data()) == 0:
        raise ValueError(self._kind + " requires x column to be numeric")
    if len(self.data[self.y]._get_numeric_data()) == 0:
        raise ValueError(self._kind + " requires y column to be numeric")

def _initialize_stacker(cls, ax: Axes, stacking_id, n: int) -> None:
    if stacking_id is None:
        return
    if not hasattr(ax, "_stacker_pos_prior"):
        # TODO #54485
        ax._stacker_pos_prior = {}  # type: ignore[attr-defined]
    if not hasattr(ax, "_stacker_neg_prior"):
        # TODO #54485
        ax._stacker_neg_prior = {}  # type: ignore[attr-defined]
    # TODO #54485
    ax._stacker_pos_prior[stacking_id] = np.zeros(n)  # type: ignore[attr-defined]
    # TODO #54485
    ax._stacker_neg_prior[stacking_id] = np.zeros(n)  # type: ignore[attr-defined]

def _get_stacked_values(
    cls, ax: Axes, stacking_id: int | None, values: np.ndarray, label
) -> np.ndarray:
    if stacking_id is None:
        return values
    if not hasattr(ax, "_stacker_pos_prior"):
        # stacker may not be initialized for subplots
        cls._initialize_stacker(ax, stacking_id, len(values))

    if (values >= 0).all():
        # TODO #54485
        return (
            ax._stacker_pos_prior[stacking_id]  # type: ignore[attr-defined]
            + values
        )
    elif (values <= 0).all():
        # TODO #54485
        return (
            ax._stacker_neg_prior[stacking_id]  # type: ignore[attr-defined]
            + values
        )

    raise ValueError(
        "When stacked is True, each column must be either "
        "all positive or all negative. "
        f"Column '{label}' contains both positive and negative values"

def _update_stacker(cls, ax: Axes, stacking_id: int | None, values) -> None:
    if stacking_id is None:
        return
    if (values >= 0).all():
        # TODO #54485
        ax._stacker_pos_prior[stacking_id] += values  # type: ignore[attr-defined]
    elif (values <= 0).all():
        # TODO #54485
        ax._stacker_neg_prior[stacking_id] += values  # type: ignore[attr-defined]

def _post_plot_logic(self, ax: Axes, data) -> None:
    def get_label(i):
        if is_float(i) and i.is_integer():
            i = int(i)
        try:
            return pprint_thing(data.index[i])
        except Exception:
            return ""

    if self._need_to_set_index:
        xticks = ax.get_xticks()
        xticklabels = [get_label(x) for x in xticks]
        # error: Argument 1 to "FixedLocator" has incompatible type "ndarray[Any,
        # Any]"; expected "Sequence[float]"
        ax.xaxis.set_major_locator(mpl.ticker.FixedLocator(xticks))  # type: ignore[arg-type]
        ax.set_xticklabels(xticklabels)

    # If the index is an irregular time series, then by default
    # we rotate the tick labels. The exception is if there are
    # subplots which don't share their x-axes, in which we case
    # we don't rotate the ticklabels as by default the subplots
    # would be too close together.
    condition = (
        not self._use_dynamic_x()
        and (data.index._is_all_dates and self.use_index)
        and (not self.subplots or (self.subplots and self.sharex))
    )

    index_name = self._get_index_name()

    if condition:
        # irregular TS rotated 30 deg. by default
        # probably a better place to check / set this.
        if not self._rot_set:
            self.rot = 30
        format_date_labels(ax, rot=self.rot)

    if index_name is not None and self.use_index:
        ax.set_xlabel(index_name)

def __init__(self, data, **kwargs) -> None:
    kwargs.setdefault("stacked", True)
    data = data.fillna(value=0)
    LinePlot.__init__(self, data, **kwargs)

    if not self.stacked:
        # use smaller alpha to distinguish overlap
        self.kwds.setdefault("alpha", 0.5)

    if self.logy or self.loglog:
        raise ValueError("Log-y scales are not supported in area plot")

def _post_plot_logic(self, ax: Axes, data) -> None:
    LinePlot._post_plot_logic(self, ax, data)

    is_shared_y = len(ax.get_shared_y_axes().get_siblings(ax)) > 1
    # do not override the default axis behaviour in case of shared y axes
    if self.ylim is None and not is_shared_y:
        if (data >= 0).all().all():
            ax.set_ylim(0, None)
        elif (data <= 0).all().all():
            ax.set_ylim(None, 0)

def tickoffset(self):
    if self.stacked or self.subplots:
        return self.bar_width * self._position
    elif self._align == "edge":
        w = self.bar_width / self.nseries
        return self.bar_width * (self._position - 0.5) + w * 0.5
    else:
        return self.bar_width * self._position

def lim_offset(self):
    if self.stacked or self.subplots:
        if self._align == "edge":
            return self.bar_width / 2
        else:
            return 0
    elif self._align == "edge":
        w = self.bar_width / self.nseries
        return w * 0.5
    else:
        return 0

def _decorate_ticks(
    self,
    ax: Axes,
    name: str | None,
    ticklabels: list[str],
    start_edge: float,
    end_edge: float,
) -> None:
    ax.set_xlim((start_edge, end_edge))

    if self.xticks is not None:
        ax.set_xticks(np.array(self.xticks))
    else:
        ax.set_xticks(self.tick_pos)
        ax.set_xticklabels(ticklabels)

    if name is not None and self.use_index:
        ax.set_xlabel(name)

def __init__(self, data: Series | DataFrame, kind=None, **kwargs) -> None:
    data = data.fillna(value=0)
    if isinstance(data, ABCDataFrame) and (data < 0).any().any():
        raise ValueError(f"{self._kind} plot doesn't allow negative values")
    elif isinstance(data, ABCSeries) and (data < 0).any():
        raise ValueError(f"{self._kind} plot doesn't allow negative values")
    MPLPlot.__init__(self, data, kind=kind, **kwargs)

def _make_plot(self, fig: Figure) -> None:
    colors = self._get_colors(num_colors=len(self.data), color_kwds="colors")
    self.kwds.setdefault("colors", colors)

    for i, (label, y) in enumerate(self._iter_data(data=self.data)):
        ax = self._get_ax(i)

        kwds = self.kwds.copy()

        def blank_labeler(label, value):
            if value == 0:
                return ""
            else:
                return label

        idx = [pprint_thing(v) for v in self.data.index]
        labels = kwds.pop("labels", idx)
        # labels is used for each wedge's labels
        # Blank out labels for values of 0 so they don't overlap
        # with nonzero wedges
        if labels is not None:
            blabels = [
                blank_labeler(left, value)
                for left, value in zip(labels, y, strict=True)
            ]
        else:
            blabels = None
        # Any: pie returns a 2- or 3-tuple and matplotlib's return type
        # for it differs across versions
        results: Any = ax.pie(y, labels=blabels, **kwds)

        if kwds.get("autopct", None) is not None:
            patches, texts, autotexts = results
        else:
            patches, texts = results
            autotexts = []

        if self.fontsize is not None:
            for t in texts + autotexts:
                t.set_fontsize(self.fontsize)

        # leglabels is used for legend labels
        leglabels = labels if labels is not None else idx
        for _patch, _leglabel in zip(patches, leglabels, strict=True):
            self._append_legend_handles_labels(_patch, _leglabel)

def maybe_color_bp(bp, color_tup, **kwds) -> None:
    # GH#30346, when users specifying those arguments explicitly, our defaults
    # for these four kwargs should be overridden; if not, use Pandas settings
    if not kwds.get("boxprops"):
        mpl.artist.setp(bp["boxes"], color=color_tup[0], alpha=1)
    if not kwds.get("whiskerprops"):
        mpl.artist.setp(bp["whiskers"], color=color_tup[1], alpha=1)
    if not kwds.get("medianprops"):
        mpl.artist.setp(bp["medians"], color=color_tup[2], alpha=1)
    if not kwds.get("capprops"):
        mpl.artist.setp(bp["caps"], color=color_tup[3], alpha=1)

def __init__(self, data, return_type: str = "axes", **kwargs) -> None:
    if return_type not in self._valid_return_types:
        raise ValueError("return_type must be {None, 'axes', 'dict', 'both'}")

    self.return_type = return_type
    # Do not call LinePlot.__init__ which may fill nan
    MPLPlot.__init__(self, data, **kwargs)

    if self.subplots:
        # Disable label ax sharing. Otherwise, all subplots shows last
        # column label
        if self.orientation == "vertical":
            self.sharex = False
        else:
            self.sharey = False

def _plot(  # type: ignore[override]
    cls, ax: Axes, y: np.ndarray, column_num=None, return_type: str = "axes", **kwds
):
    ys: np.ndarray | list[np.ndarray]
    if y.ndim == 2:
        ys = [remove_na_arraylike(v) for v in y]
        # Boxplot fails with empty arrays, so need to add a NaN
        #   if any cols are empty
        # GH 8181
        ys = [v if v.size > 0 else np.array([np.nan]) for v in ys]
    else:
        ys = remove_na_arraylike(y)
    bp = ax.boxplot(ys, **kwds)

    if return_type == "dict":
        return bp, bp
    elif return_type == "both":
        return cls.BP(ax=ax, lines=bp), bp
    else:
        return ax, bp

def _validate_color_args(self, color, colormap):
    if color is lib.no_default:
        return None

    if colormap is not None:
        warnings.warn(
            "'color' and 'colormap' cannot be used simultaneously. Using 'color'",
            stacklevel=find_stack_level(),
        )

    if isinstance(color, dict):
        valid_keys = ["boxes", "whiskers", "medians", "caps"]
        for key in color:
            if key not in valid_keys:
                raise ValueError(
                    f"color dict contains invalid key '{key}'. "
                    f"The key must be either {valid_keys}"
                )
    return color

def _post_plot_logic(self, ax: Axes, data) -> None:
    # GH 45465: make sure that the boxplot doesn't ignore xlabel/ylabel
    if self.xlabel:
        ax.set_xlabel(pprint_thing(self.xlabel))
    if self.ylabel:
        ax.set_ylabel(pprint_thing(self.ylabel))

def _get_cmap_instance(colormap: str | Colormap) -> Colormap:
    """Get instance of matplotlib colormap."""
    if isinstance(colormap, str):
        cmap = colormap
        colormap = mpl.colormaps[colormap]
        if colormap is None:
            raise ValueError(f"Colormap {cmap} is not recognized")
    return colormap

def _get_colors_from_color(
    color: Color | Collection[Color],
) -> list[Color]:
    """Get colors from user input color."""
    if len(color) == 0:
        raise ValueError(f"Invalid color argument: {color}")

    if _is_single_color(color):
        color = cast("Color", color)
        return [color]

    color = cast("Collection[Color]", color)
    return list(_gen_list_of_colors_from_iterable(color))

def _gen_list_of_colors_from_iterable(color: Collection[Color]) -> Iterator[Color]:
    """
    Yield colors from string of several letters or from collection of colors.
    """
    for x in color:
        if _is_single_color(x):
            yield x
        else:
            raise ValueError(f"Invalid color {x}")

def _is_floats_color(color: Color | Collection[Color]) -> bool:
    """Check if color comprises a sequence of floats representing color."""
    return bool(
        is_list_like(color)
        and (len(color) == 3 or len(color) == 4)
        and all(isinstance(x, (int, float)) for x in color)

def _get_colors_from_color_type(color_type: str, num_colors: int) -> list[Color]:
    """Get colors from user input color type."""
    if color_type == "default":
        prop_cycle = mpl.rcParams["axes.prop_cycle"]
        return [
            c["color"]
            for c in itertools.islice(prop_cycle, min(num_colors, len(prop_cycle)))
        ]
    elif color_type == "random":
        return np.random.default_rng(num_colors).random((num_colors, 3)).tolist()
    else:
        raise ValueError("color_type must be either 'default' or 'random'")

def register() -> None:
    pairs = get_pairs()
    for type_, cls in pairs:
        # Cache previous converter if present
        if type_ in munits.registry and not isinstance(munits.registry[type_], cls):
            previous = munits.registry[type_]
            _mpl_units[type_] = previous
        # Replace with pandas converter
        munits.registry[type_] = cls()

def deregister() -> None:
    # Renamed in pandas.plotting.__init__
    for type_, cls in get_pairs():
        # We use type to catch our classes directly, no inheritance
        if type(munits.registry.get(type_)) is cls:
            munits.registry.pop(type_)

    # restore the old keys
    for unit, formatter in _mpl_units.items():
        if type(formatter) not in {DatetimeConverter, PeriodConverter, TimeConverter}:
            # make it idempotent by excluding ours.
            munits.registry[unit] = formatter

def time2num(d):
    if isinstance(d, str):
        parsed = Timestamp(d)
        return _to_ordinalf(parsed.time())
    if isinstance(d, pydt.time):
        return _to_ordinalf(d)
    return d

def _get_datevalue(date, freq):
    if isinstance(date, Period):
        freq_obj = to_offset(freq, is_period=True)
        dtype_code = freq_obj._period_dtype_code
        if FreqGroup.from_period_dtype_code(dtype_code) == FreqGroup.FR_BUS:
            # Avoid creating deprecated Period[B] via asfreq.  If the Period
            # is already BDay, its ordinal IS the business-day count; otherwise
            # convert via timestamp.
            if date.freqstr == "B":
                return date.ordinal
            return bday_count(date.to_timestamp())
        return date.asfreq(freq).ordinal
    elif isinstance(date, (str, datetime, pydt.date, np.datetime64)):
        freq_obj = to_offset(freq, is_period=True)
        dtype_code = freq_obj._period_dtype_code
        if FreqGroup.from_period_dtype_code(dtype_code) == FreqGroup.FR_BUS:
            # Avoid creating deprecated Period[B]; use numpy business-day count.
            return bday_count(date)
        return Period(date, freq).ordinal  # pyright: ignore[reportAttributeAccessIssue]
    elif is_integer(date) or is_float(date):
        return date
    elif date is None:
        return None
    raise ValueError(f"Unrecognizable date '{date}'")

def _get_default_annual_spacing(nyears) -> tuple[int, int]:
    """
    Returns a default spacing between consecutive ticks for annual data.
    """
    if nyears < 11:
        (min_spacing, maj_spacing) = (1, 1)
    elif nyears < 20:
        (min_spacing, maj_spacing) = (1, 2)
    elif nyears < 50:
        (min_spacing, maj_spacing) = (1, 5)
    elif nyears < 100:
        (min_spacing, maj_spacing) = (5, 10)
    elif nyears < 200:
        (min_spacing, maj_spacing) = (5, 25)
    elif nyears < 600:
        (min_spacing, maj_spacing) = (10, 50)
    else:
        factor = nyears // 1000 + 1
        (min_spacing, maj_spacing) = (factor * 20, factor * 100)
    return (min_spacing, maj_spacing)

def _period_break_mask(
    dates: PeriodIndex | DatetimeIndex, period: str
) -> npt.NDArray[np.bool_]:
    # DatetimeIndex has no .week attribute; use .isocalendar().week instead
    if period == "week" and isinstance(dates, DatetimeIndex):
        current = dates.isocalendar().week.values
        previous = (dates - 1 * dates.freq).isocalendar().week.values  # type: ignore[operator]
    else:
        current = getattr(dates, period)
        previous = getattr(dates - 1 * dates.freq, period)  # type: ignore[operator]
    return current != previous

def has_level_label(label_flags: npt.NDArray[np.intp], vmin: float) -> bool:
    """
    Returns true if the ``label_flags`` indicate there is at least one label
    for this level.

    if the minimum view limit is not an exact integer, then the first tick
    label won't be shown, so we must adjust for that.
    """
    if label_flags.size == 0 or (
        label_flags.size == 1 and label_flags[0] == 0 and vmin % 1 > 0.0
    ):
        return False
    else:
        return True

def convert(value, unit, axis):
    valid_types = (str, pydt.time)
    if isinstance(value, valid_types) or is_integer(value) or is_float(value):
        return time2num(value)
    if isinstance(value, Index):
        return value.map(time2num)
    if isinstance(value, (list, tuple, np.ndarray, Index)):
        return [time2num(x) for x in value]
    return value

def convert_from_freq(values, freq: BaseOffset):
    if is_nested_list_like(values):
        values = [PeriodConverter._convert_1d(v, freq) for v in values]
    else:
        values = PeriodConverter._convert_1d(values, freq)
    return values

def _convert_1d(values, freq: BaseOffset):
    # error: "BaseOffset" has no attribute "_period_dtype_code"
    dtype_code = freq._period_dtype_code  # type: ignore[attr-defined]
    is_bday = FreqGroup.from_period_dtype_code(dtype_code) == FreqGroup.FR_BUS

    valid_types = (str, datetime, Period, pydt.date, np.datetime64)
    if isinstance(values, valid_types) or is_integer(values) or is_float(values):
        return _get_datevalue(values, freq)
    elif isinstance(values, PeriodIndex):
        if is_bday:
            # Return ordinals directly; asfreq would create Period[B].
            return values.asi8
        return values.asfreq(freq).asi8
    elif isinstance(values, Index):
        return values.map(lambda x: _get_datevalue(x, freq))
    elif isinstance(values, np.ndarray) and values.dtype.kind in "iuf":
        # Already ordinal-numeric (e.g. from PeriodIndex._mpl_repr);
        # nothing to convert.  GH#10578
        return values
    elif lib.infer_dtype(values, skipna=False) == "period":
        # https://github.com/pandas-dev/pandas/issues/24304
        # convert ndarray[period] -> ordinals
        if is_bday:
            return np.array([p.ordinal for p in values], dtype=np.int64)
        return PeriodIndex(values, freq=freq).asi8
    elif isinstance(values, (list, tuple, np.ndarray)):
        return [_get_datevalue(x, freq) for x in values]
    return values

def convert(values, unit, axis: Axis):
    # Reached via e.g. `ax.set_xlim`

    # In tests as of 2025-09-24, unit is always None except for 3 tests
    #  that directly call this with unit="";
    #  axis is always specifically a matplotlib.axis.XAxis

    # values might be a 1-d array, or a list-like of arrays.
    if is_nested_list_like(values):
        values = [DatetimeConverter._convert_1d(v, unit, axis) for v in values]
    else:
        values = DatetimeConverter._convert_1d(values, unit, axis)
    return values

def _convert_1d(values, unit, axis):
    def try_parse(values):
        try:
            return mdates.date2num(tools.to_datetime(values))
        except Exception:
            return values

    if isinstance(values, (datetime, pydt.date, np.datetime64, pydt.time)):
        return mdates.date2num(values)
    elif is_integer(values) or is_float(values):
        return values
    elif isinstance(values, str):
        return try_parse(values)
    elif isinstance(values, (list, tuple, np.ndarray, Index, Series)):
        if isinstance(values, Series):
            # https://github.com/matplotlib/matplotlib/issues/11391
            # Series was skipped. Convert to DatetimeIndex to get asi8
            values = Index(values)
        if isinstance(values, Index):
            values = values._values
        if not isinstance(values, np.ndarray):
            values = com.asarray_tuplesafe(values)

        if is_integer_dtype(values) or is_float_dtype(values):
            return values

        try:
            values = tools.to_datetime(values)
        except Exception:
            pass

        values = mdates.date2num(values)

    return values

def _set_default_format(self, vmin, vmax):
    """Returns the default ticks spacing."""
    info = self.finder(vmin, vmax, self.freq, self.anchor)

    if self.isminor:
        format = np.compress(info["min"] & np.logical_not(info["maj"]), info)
    else:
        format = np.compress(info["maj"], info)
    self.formatdict = {x: f for (x, _, _, f) in format}
    return self.formatdict

def __call__(self, x, pos: int | None = 0) -> str:
    if self.formatdict is None:
        return ""
    else:
        fmt = self.formatdict.pop(x, "")
        if isinstance(fmt, np.bytes_):
            fmt = fmt.decode("utf-8")
        # error: "BaseOffset" has no attribute "_period_dtype_code"
        dtype_code = self.freq._period_dtype_code  # type: ignore[attr-defined]
        freq_group = FreqGroup.from_period_dtype_code(dtype_code)
        if freq_group == FreqGroup.FR_BUS:
            # Use bday_to_datetime to avoid (deprecated) Period[B]
            return bday_to_datetime(int(x)).strftime(fmt)
        period = Period(ordinal=int(x), freq=self.freq)
        assert isinstance(period, Period)
        return period.strftime(fmt)

def format_date_labels(ax: Axes, rot) -> None:
    # mini version of autofmt_xdate
    for label in ax.get_xticklabels():
        label.set_horizontalalignment("right")
        label.set_rotation(rot)
    fig = ax.get_figure()
    if fig is not None:
        # should always be a Figure but can technically be None
        maybe_adjust_figure(fig, bottom=0.2)  # type: ignore[arg-type]

def table(
    ax, data: DataFrame | Series, rowLabels=None, colLabels=None, **kwargs
) -> Table:
    if isinstance(data, ABCSeries):
        data = data.to_frame()
    elif isinstance(data, ABCDataFrame):
        pass
    else:
        raise ValueError("Input data must be DataFrame or Series")

    if rowLabels is None:
        rowLabels = data.index

    if colLabels is None:
        colLabels = data.columns

    cellText = data.values

    # error: Argument "cellText" to "table" has incompatible type "ndarray[Any,
    # Any]"; expected "Sequence[Sequence[str]] | None"
    return mpl.table.table(
        ax,
        cellText=cellText,  # type: ignore[arg-type]
        rowLabels=rowLabels,
        colLabels=colLabels,
        **kwargs,

def _get_layout(
    nplots: int,
    layout: tuple[int, int] | None = None,
    layout_type: str = "box",
) -> tuple[int, int]:
    if layout is not None:
        if not isinstance(layout, (tuple, list)) or len(layout) != 2:
            raise ValueError("Layout must be a tuple of (rows, columns)")

        nrows, ncols = layout

        if nrows == -1 and ncols > 0:
            layout = (ceil(nplots / ncols), ncols)
        elif ncols == -1 and nrows > 0:
            layout = (nrows, ceil(nplots / nrows))
        elif ncols <= 0 and nrows <= 0:
            msg = "At least one dimension of layout must be positive"
            raise ValueError(msg)

        nrows, ncols = layout
        if nrows * ncols < nplots:
            raise ValueError(
                f"Layout of {nrows}x{ncols} must be larger than required size {nplots}"
            )

        return layout

    if layout_type == "single":
        return (1, 1)
    elif layout_type == "horizontal":
        return (1, nplots)
    elif layout_type == "vertical":
        return (nplots, 1)

    layouts = {1: (1, 1), 2: (1, 2), 3: (2, 2), 4: (2, 2)}
    try:
        return layouts[nplots]
    except KeyError:
        k = 1
        while k**2 < nplots:
            k += 1

        if (k - 1) * k >= nplots:
            return k, (k - 1)
        else:
            return k, k

def _remove_labels_from_axis(axis: Axis) -> None:
    for t in axis.get_majorticklabels():
        t.set_visible(False)

    # set_visible will not be effective if
    # minor axis has NullLocator and NullFormatter (default)
    if isinstance(axis.get_minor_locator(), mpl.ticker.NullLocator):
        axis.set_minor_locator(mpl.ticker.AutoLocator())
    if isinstance(axis.get_minor_formatter(), mpl.ticker.NullFormatter):
        axis.set_minor_formatter(mpl.ticker.FormatStrFormatter(""))
    for t in axis.get_minorticklabels():
        t.set_visible(False)

    axis.get_label().set_visible(False)

def handle_shared_axes(
    axarr: Iterable[Axes],
    nplots: int,
    naxes: int,
    nrows: int,
    ncols: int,
    sharex: bool,
    sharey: bool,
) -> None:
    if nplots > 1:
        row_num = lambda x: x.get_subplotspec().rowspan.start
        col_num = lambda x: x.get_subplotspec().colspan.start

        is_first_col = lambda x: x.get_subplotspec().is_first_col()

        if nrows > 1:
            try:
                # first find out the ax layout,
                # so that we can correctly handle 'gaps"
                layout = np.zeros((nrows + 1, ncols + 1), dtype=np.bool_)
                for ax in axarr:
                    layout[row_num(ax), col_num(ax)] = ax.get_visible()

                for ax in axarr:
                    # only the last row of subplots should get x labels -> all
                    # other off layout handles the case that the subplot is
                    # the last in the column, because below is no subplot/gap.
                    if not layout[row_num(ax) + 1, col_num(ax)]:
                        continue
                    if sharex or _has_externally_shared_axis(ax, "x"):
                        _remove_labels_from_axis(ax.xaxis)

            except IndexError:
                # if gridspec is used, ax.rowNum and ax.colNum may different
                # from layout shape. in this case, use last_row logic
                is_last_row = lambda x: x.get_subplotspec().is_last_row()
                for ax in axarr:
                    if is_last_row(ax):
                        continue
                    if sharex or _has_externally_shared_axis(ax, "x"):
                        _remove_labels_from_axis(ax.xaxis)

        if ncols > 1:
            for ax in axarr:
                # only the first column should get y labels -> set all other to
                # off as we only have labels in the first column and we always
                # have a subplot there, we can skip the layout test
                if is_first_col(ax):
                    continue
                if sharey or _has_externally_shared_axis(ax, "y"):
                    _remove_labels_from_axis(ax.yaxis)

def flatten_axes(axes: Axes | Iterable[Axes]) -> Generator[Axes]:
    if not is_list_like(axes):
        yield axes  # type: ignore[misc]
    elif isinstance(axes, (np.ndarray, ABCIndex)):
        yield from np.asarray(axes).reshape(-1)
    else:
        yield from axes  # type: ignore[misc]

def set_ticks_props(
    axes: Axes | Iterable[Axes],
    xlabelsize: int | None = None,
    xrot=None,
    ylabelsize: int | None = None,
    yrot=None,
):
    for ax in flatten_axes(axes):
        if xlabelsize is not None:
            mpl.artist.setp(ax.get_xticklabels(), fontsize=xlabelsize)  # type: ignore[arg-type]
        if xrot is not None:
            mpl.artist.setp(ax.get_xticklabels(), rotation=xrot)  # type: ignore[arg-type]
        if ylabelsize is not None:
            mpl.artist.setp(ax.get_yticklabels(), fontsize=ylabelsize)  # type: ignore[arg-type]
        if yrot is not None:
            mpl.artist.setp(ax.get_yticklabels(), rotation=yrot)  # type: ignore[arg-type]
    return axes

def get_all_lines(ax: Axes) -> list[Line2D]:
    lines = ax.get_lines()

    if hasattr(ax, "right_ax"):
        lines += ax.right_ax.get_lines()

    if hasattr(ax, "left_ax"):
        lines += ax.left_ax.get_lines()

    return lines

def _asfreq_plotting(index: Index, freq: str | BaseOffset) -> Index:
    """
    Re-express a time-series plotting index at frequency ``freq``.

    ``index`` is either a PeriodIndex or a plain int64 index of business-day
    ordinals -- the representation used for BDay data to avoid the deprecated
    Period[B].  Returns int64 business-day ordinals when ``freq`` is
    business-daily, otherwise a PeriodIndex at ``freq``.
    """
    if _get_period_alias(freq) == "B":
        if is_integer_dtype(index):
            # already business-day ordinals
            return index
        # PeriodIndex -> timestamps -> business-day ordinals
        dti = index.to_timestamp()  # type: ignore[attr-defined]
        return Index(bday_count_array(dti.values), dtype=np.int64)
    if is_integer_dtype(index):
        # business-day ordinals -> timestamps -> PeriodIndex at freq
        dt64 = bday_offset_array(np.asarray(index, dtype=np.int64))
        return DatetimeIndex(dt64).to_period(freq)
    return index.asfreq(freq, how="S")  # type: ignore[attr-defined]

def _upsample_others(ax: Axes, freq: BaseOffset, kwargs: dict[str, Any]) -> None:
    legend = ax.get_legend()
    lines, labels = _replot_ax(ax, freq)
    _replot_ax(ax, freq)

    other_ax = None
    if hasattr(ax, "left_ax"):
        other_ax = ax.left_ax
    if hasattr(ax, "right_ax"):
        other_ax = ax.right_ax

    if other_ax is not None:
        rlines, rlabels = _replot_ax(other_ax, freq)
        lines.extend(rlines)
        labels.extend(rlabels)

    if legend is not None and kwargs.get("legend", True) and len(lines) > 0:
        title: str | None = legend.get_title().get_text()
        if title == "None":
            title = None
        ax.legend(lines, labels, loc="best", title=title)

def _get_ax_freq(ax: Axes):
    """
    Get the freq attribute of the ax object if set.
    Also checks shared axes (eg when using secondary yaxis, sharex=True
    or twinx)
    """
    ax_freq = getattr(ax, "freq", None)
    if ax_freq is None:
        # check for left/right ax in case of secondary yaxis
        if hasattr(ax, "left_ax"):
            ax_freq = getattr(ax.left_ax, "freq", None)
        elif hasattr(ax, "right_ax"):
            ax_freq = getattr(ax.right_ax, "freq", None)
    if ax_freq is None:
        # check if a shared ax (sharex/twinx) has already freq set
        shared_axes = ax.get_shared_x_axes().get_siblings(ax)
        if len(shared_axes) > 1:
            for shared_ax in shared_axes:
                ax_freq = getattr(shared_ax, "freq", None)
                if ax_freq is not None:
                    break
    return ax_freq

def maybe_convert_index(ax: Axes, data: NDFrameT) -> tuple[NDFrameT, str | None]:
    # Convert DatetimeIndex to ordinal-integer index for plotting, so the
    # x-axis uses consecutive integers rather than matplotlib date2num floats.
    # This ensures evenly-spaced points: for BDay freq, Fri→Mon is a 1-unit
    # step rather than a 3-unit gap.  See GH#1482.
    # Also return the freq alias used for the conversion, or None if the index
    # is not datetime-like: the int64 ordinal index produced for "B" carries
    # no freq of its own, so callers cannot re-derive it from the result.
    freq_str: str | None = None
    if isinstance(data.index, (ABCDatetimeIndex, ABCPeriodIndex)):
        freq = _get_index_freq(data.index)

        if freq is None:
            freq = _get_ax_freq(ax)

        if freq is None:
            raise ValueError("Could not get frequency alias for plotting")

        freq_str = _get_period_alias(freq)

        if isinstance(data.index, ABCDatetimeIndex):
            if freq_str == "B":
                # Avoid creating deprecated Period[B]; use numpy business-day
                # arithmetic to map each timestamp to its business-day ordinal.
                data = data.copy(deep=False)
                data.index = Index(
                    bday_count_array(data.index.tz_localize(None).values),
                    dtype=np.int64,
                )
            else:
                data = data.tz_localize(None).to_period(freq=freq_str)
        elif isinstance(data.index, ABCPeriodIndex):
            if freq_str == "B":
                # Extract the existing Period[B] ordinals as plain int64 to
                # avoid creating new (deprecated) Period[B] objects.
                data = data.copy(deep=False)
                data.index = Index(data.index.asi8, dtype=np.int64)
            else:
                data.index = data.index.asfreq(freq=freq_str, how="start")
    return data, freq_str

def prepare_ts_data(
    series: Series, ax: Axes, kwargs: dict[str, Any], index_freq: str | None = None
) -> tuple[BaseOffset | str, Series]:
    freq, data = maybe_resample(series, ax, kwargs, index_freq)

    # Set ax with freq info
    decorate_axes(ax, freq)
    # digging deeper
    if hasattr(ax, "left_ax"):
        decorate_axes(ax.left_ax, freq)
    if hasattr(ax, "right_ax"):
        decorate_axes(ax.right_ax, freq)

    return freq, data

def _adjust_bins(self, bins: int | np.ndarray | list[np.ndarray]):
    if is_integer(bins):
        if self.by is not None:
            by_modified = unpack_single_str_list(self.by)
            grouped = self.data.groupby(by_modified)[self.columns]
            bins = [self._calculate_bins(group, bins) for key, group in grouped]
        else:
            bins = self._calculate_bins(self.data, bins)
    return bins

def _get_column_weights(weights, i: int, y):
    # We allow weights to be a multi-dimensional array, e.g. a (10, 2) array,
    # and each sub-array (10,) will be called in each iteration. If users only
    # provide 1D array, we assume the same weights is used for all iterations
    if weights is not None:
        if np.ndim(weights) != 1 and np.shape(weights)[-1] != 1:
            try:
                weights = weights[:, i]
            except IndexError as err:
                raise ValueError(
                    "weights must have the same shape as data, "
                    "or be a single column"
                ) from err
        weights = weights[~isna(y)]
    return weights

def _post_plot_logic(self, ax: Axes, data) -> None:
    if self.orientation == "horizontal":
        # error: Argument 1 to "set_xlabel" of "_AxesBase" has incompatible
        # type "Hashable"; expected "str"
        ax.set_xlabel(
            "Frequency" if self.xlabel is None else self.xlabel  # type: ignore[arg-type]
        )
        ax.set_ylabel(self.ylabel)  # type: ignore[arg-type]
    else:
        ax.set_xlabel(self.xlabel)  # type: ignore[arg-type]
        ax.set_ylabel(
            "Frequency" if self.ylabel is None else self.ylabel  # type: ignore[arg-type]

def _conv(self, data: pd.DataFrame | pd.Series) -> pd.DataFrame:
    """
    Convert each input to appropriate format for table output.
    """
    if isinstance(data, pd.Series):
        if data.name is None:
            data = data.to_frame(name="")
        else:
            data = data.to_frame()
    data = data.astype(object).fillna("NaN")
    return data

def _insert_index(self, data: pd.DataFrame) -> pd.DataFrame:
    # insert is destructive
    data = data.copy()
    idx_nlevels = data.index.nlevels
    if idx_nlevels == 1:
        data.insert(0, "Index", data.index)
    else:
        for i in range(idx_nlevels):
            data.insert(i, f"Index{i}", data.index._get_level_values(i))

    col_nlevels = data.columns.nlevels
    if col_nlevels > 1:
        col = data.columns._get_level_values(0)
        values = [
            data.columns._get_level_values(i)._values for i in range(1, col_nlevels)
        ]
        col_df = pd.DataFrame(values)
        data.columns = col_df.columns
        data = pd.concat([col_df, data])
        data.columns = col
    return data

def indent(text: str | None, indents: int = 1) -> str:
    if not text or not isinstance(text, str):
        return ""
    jointext = "".join(["\n"] + ["    "] * indents)
    return jointext.join(text.split("\n"))

def __init__(self, *args: object, **kwargs: object) -> None:
    from pandas.errors import Pandas4Warning

    warnings.warn(
        "Substitution is deprecated and will be removed in a future version.",
        Pandas4Warning,
        stacklevel=find_stack_level(),
    )
    if args and kwargs:
        raise AssertionError("Only positional or keyword args are allowed")

    self.params: tuple[object, ...] | dict[str, object] = args or kwargs

def __call__(self, func: T) -> T:
    func.__doc__ = func.__doc__ if func.__doc__ else ""
    self.addendum = self.addendum if self.addendum else ""
    docitems = [func.__doc__, self.addendum]
    func.__doc__ = dedent(self.join.join(docitems))
    return func

def __getattr__(key: str) -> object:
    # These imports need to be lazy to avoid circular import errors
    if key == "hash_array":
        from pandas.core.util.hashing import hash_array

        return hash_array
    if key == "hash_pandas_object":
        from pandas.core.util.hashing import hash_pandas_object

        return hash_pandas_object
    if key == "Appender":
        from pandas.util._decorators import Appender

        return Appender
    if key == "Substitution":
        from pandas.util._decorators import Substitution

        return Substitution

    if key == "cache_readonly":
        from pandas.util._decorators import cache_readonly

        return cache_readonly

    raise AttributeError(f"module 'pandas.util' has no attribute '{key}'")

def validate_ascending(
    ascending: bool | int | Sequence[BoolishT],
) -> bool | int | list[BoolishT]:
    """Validate ``ascending`` kwargs for ``sort_index`` method."""
    kwargs = {"none_allowed": False, "int_allowed": True}
    if not isinstance(ascending, Sequence):
        return validate_bool_kwarg(ascending, "ascending", **kwargs)

    return [validate_bool_kwarg(item, "ascending", **kwargs) for item in ascending]

def validate_insert_loc(loc: int, length: int) -> int:
    """
    Check that we have an integer between -length and length, inclusive.

    Standardize negative loc to within [0, length].

    The exceptions we raise on failure match np.insert.
    """
    if not is_integer(loc):
        raise TypeError(f"loc must be an integer between -{length} and {length}")

    if loc < 0:
        loc += length
    if not 0 <= loc <= length:
        raise IndexError(f"loc must be an integer between -{length} and {length}")
    return loc  # pyright: ignore[reportReturnType]

def check_dtype_backend(dtype_backend: DtypeBackend | lib.NoDefault) -> None:
    if dtype_backend is not lib.no_default:
        if dtype_backend not in ["numpy_nullable", "pyarrow"]:
            raise ValueError(
                f"dtype_backend {dtype_backend} is invalid, only 'numpy_nullable' and "

def rewrite_exception(old_name: str, new_name: str) -> Generator[None]:
    """
    Rewrite the message of an exception.
    """
    try:
        yield
    except Exception as err:
        if not err.args:
            raise
        msg = str(err.args[0])
        msg = msg.replace(old_name, new_name)
        args: tuple[Any, ...] = (msg,)
        if len(err.args) > 1:
            args = args + err.args[1:]
        err.args = args
        raise

def _parse_letter_version(
    letter: str | None, number: str | bytes | SupportsInt | None
) -> tuple[str, int] | None:
    if letter:
        # We consider there to be an implicit 0 in a pre-release if there is
        # not a numeral associated with it.
        if number is None:
            number = 0

        # We normalize any letters to their lower case form
        letter = letter.lower()

        # We consider some words to be alternate spellings of other words and
        # in those cases we want to normalize the spellings to our preferred
        # spelling.
        if letter == "alpha":
            letter = "a"
        elif letter == "beta":
            letter = "b"
        elif letter in ["c", "pre", "preview"]:
            letter = "rc"
        elif letter in ["rev", "r"]:
            letter = "post"

        return letter, int(number)
    if not letter and number:
        # We assume if we are given a number, but we are not given a letter
        # then this is using the implicit post release syntax (e.g. 1.0-1)
        letter = "post"

        return letter, int(number)

    return None

def _parse_local_version(local: str | None) -> LocalType | None:
    if local is not None:
        return tuple(
            part.lower() if not part.isdigit() else int(part)
            for part in _local_version_separators.split(local)
        )
    return None

def __str__(self) -> str:
    parts = []

    # Epoch
    if self.epoch != 0:
        parts.append(f"{self.epoch}!")

    # Release segment
    parts.append(".".join(str(x) for x in self.release))

    # Pre-release
    if self.pre is not None:
        parts.append("".join(str(x) for x in self.pre))

    # Post-release
    if self.post is not None:
        parts.append(f".post{self.post}")

    # Development release
    if self.dev is not None:
        parts.append(f".dev{self.dev}")

    # Local version segment
    if self.local is not None:
        parts.append(f"+{self.local}")

    return "".join(parts)

def local(self) -> str | None:
    if self._version.local:
        return ".".join(str(x) for x in self._version.local)
    else:
        return None

def base_version(self) -> str:
    parts = []

    # Epoch
    if self.epoch != 0:
        parts.append(f"{self.epoch}!")

    # Release segment
    parts.append(".".join(str(x) for x in self.release))

    return "".join(parts)

def arrow_table_to_pandas(
    table: pyarrow.Table,
    dtype_backend: DtypeBackend | Literal["numpy"] | lib.NoDefault = lib.no_default,
    null_to_int64: bool = False,
    to_pandas_kwargs: dict[str, Any] | None = None,
    dtype: DtypeArg | None = None,
    names: Sequence[Hashable] | None = None,
) -> pd.DataFrame:
    pa = import_optional_dependency("pyarrow")

    to_pandas_kwargs = {} if to_pandas_kwargs is None else to_pandas_kwargs

    types_mapper: (
        type[pd.ArrowDtype] | Callable[[pyarrow.DataType], ExtensionDtype | None] | None
    )
    if dtype_backend == "numpy_nullable":
        mapping = _arrow_dtype_mapping()
        if null_to_int64:
            # Modify the default mapping to also map null to Int64
            # (to match other engines - only for CSV parser)
            mapping[pa.null()] = pd.Int64Dtype()
        types_mapper = mapping.get
    elif dtype_backend == "pyarrow":
        types_mapper = pd.ArrowDtype
    elif using_string_dtype():
        if pa_version_under19p0:
            types_mapper = _arrow_string_types_mapper()
        elif dtype is not None:
            # GH#56136 Avoid lossy conversion to float64
            # We'll convert to numpy below if
            types_mapper = {
                pa.int8(): pd.Int8Dtype(),
                pa.int16(): pd.Int16Dtype(),
                pa.int32(): pd.Int32Dtype(),
                pa.int64(): pd.Int64Dtype(),
            }.get
        else:
            types_mapper = None
    elif dtype_backend is lib.no_default or dtype_backend == "numpy":
        if dtype is not None:
            # GH#56136 Avoid lossy conversion to float64
            # We'll convert to numpy below if
            types_mapper = {
                pa.int8(): pd.Int8Dtype(),
                pa.int16(): pd.Int16Dtype(),
                pa.int32(): pd.Int32Dtype(),
                pa.int64(): pd.Int64Dtype(),
            }.get
        else:
            types_mapper = None
    else:
        raise NotImplementedError

    df = table.to_pandas(types_mapper=types_mapper, **to_pandas_kwargs)
    df = _post_convert_dtypes(df, dtype_backend, dtype, names)
    df = _normalize_timezone_dtypes(df)
    return df

def _maybe_convert_string_to_object(
    data: pd.Series | pd.Index,
) -> pd.Series | pd.Index | None:
    if isinstance(data.dtype, pd.StringDtype) and data.dtype.na_value is np.nan:
        return data.astype("object").fillna(None)
    elif isinstance(data.dtype, pd.CategoricalDtype):
        cat_dtype = data.dtype.categories.dtype
        if isinstance(cat_dtype, pd.StringDtype) and cat_dtype.na_value is np.nan:
            # not astype: for ordered categoricals CategoricalDtype.__eq__
            #  ignores the categories' dtype, so astype would no-op
            cat_arr = cast("pd.Categorical", data._values)
            new_arr = cat_arr.set_categories(data.dtype.categories.astype("object"))
            if isinstance(data, pd.Index):
                return pd.CategoricalIndex(new_arr, name=data.name)
            return pd.Series(new_arr, index=data.index, name=data.name, copy=False)

    # no conversion needed
    return None

def _maybe_convert_string_index_to_object(index: pd.Index) -> pd.Index | None:
    if isinstance(index, pd.MultiIndex):
        if any(
            isinstance(level.dtype, pd.StringDtype) and level.dtype.na_value is np.nan
            for level in index.levels
        ):
            new_levels = []
            for level in index.levels:
                new_level = _maybe_convert_string_to_object(level)
                if new_level is not None:
                    new_levels.append(new_level)
                else:
                    new_levels.append(level)
            return index.set_levels(new_levels)
        return None

    else:
        return cast("pd.Index | None", _maybe_convert_string_to_object(index))

def _normalize_pytz_timezone(tz: dt.tzinfo) -> dt.tzinfo:
    """
    If the input tz is a pytz timezone, attempt to convert it to "default"
    tzinfo object (zoneinfo or datetime.timezone).
    """
    if not type(tz).__module__.startswith("pytz"):
        # isinstance(col.dtype.tz, pytz.BaseTzInfo) does not included
        # fixed offsets
        return tz

    if timezones.is_utc(tz):
        return dt.UTC

    if tz.zone is not None:  # type: ignore[attr-defined]
        try:
            return zoneinfo.ZoneInfo(tz.zone)  # type: ignore[attr-defined]
        except Exception:
            # some pytz timezones might not be available for zoneinfo
            pass

    if timezones.is_fixed_offset(tz):
        # Convert pytz fixed offset to datetime.timezone
        try:
            offset = tz.utcoffset(None)
            if offset is not None:
                return dt.timezone(offset)
        except Exception:
            pass

    return tz

def _normalize_timezone_index(index: pd.Index) -> pd.Index:
    if isinstance(index, pd.MultiIndex):
        if any(isinstance(level.dtype, pd.DatetimeTZDtype) for level in index.levels):
            levels = [_normalize_timezone_index(level) for level in index.levels]
            return index.set_levels(levels)

        return index

    if isinstance(index.dtype, pd.DatetimeTZDtype):
        normalized_tz = _normalize_pytz_timezone(index.dtype.tz)
        if normalized_tz is not index.dtype.tz:
            return index.tz_convert(normalized_tz)  # type: ignore[attr-defined]

    return index

def _normalize_timezone_dtypes(df: pd.DataFrame) -> pd.DataFrame:
    """
    PyArrow below version 25 uses pytz by default for timezones, but pandas uses
    zoneinfo / datetime.timezone since pandas 3.0.

    Can be dropped once the minimum supported pyarrow is 25, which uses zoneinfo
    itself (https://github.com/apache/arrow/pull/49694).
    """
    if pytz is not None and pa_version_under25p0:
        # Convert any pytz timezones to zoneinfo / fixed offset timezones
        if any(
            isinstance(dtype, pd.DatetimeTZDtype)
            for dtype in df._mgr.get_unique_dtypes()
        ):
            col_indices = df._select_dtypes_indices(pd.DatetimeTZDtype)
            for i in col_indices:
                col = df.iloc[:, i]
                normalized_tz = _normalize_pytz_timezone(col.dtype.tz)
                if normalized_tz is not col.dtype.tz:
                    df.isetitem(i, col.dt.tz_convert(normalized_tz))

        df.index = _normalize_timezone_index(df.index)
        df.columns = _normalize_timezone_index(df.columns)

    return df

def _process_parse_dates_argument(parse_dates):
    """Process parse_dates argument for read_sql functions"""
    # handle non-list entries for parse_dates gracefully
    if parse_dates is True or parse_dates is None or parse_dates is False:
        parse_dates = []

    elif not hasattr(parse_dates, "__iter__"):
        parse_dates = [parse_dates]
    return parse_dates

def _handle_date_column(
    col, utc: bool = False, format: str | dict[str, Any] | None = None
):
    if isinstance(format, dict):
        # GH35185 Allow custom error values in parse_dates argument of
        # read_sql like functions.
        # Format can take on custom to_datetime argument values such as
        # {"errors": "coerce"} or {"dayfirst": True}
        if format.get("format") is not None and col.dtype.kind in "iuf":
            col = _warn_and_stringify_numeric_column(col)
        return to_datetime(col, **format)
    else:
        # Allow passing of formatting string for integers
        # GH17855
        if format is None and (
            issubclass(col.dtype.type, np.floating)
            or issubclass(col.dtype.type, np.integer)
        ):
            format = "s"
        if format in ["D", "d", "h", "m", "s", "ms", "us", "ns"]:
            return to_datetime(col, errors="coerce", unit=format, utc=utc)
        elif isinstance(col.dtype, DatetimeTZDtype):
            # coerce to UTC timezone
            # GH11216
            return to_datetime(col, utc=True)
        else:
            if format is not None and col.dtype.kind in "iuf":
                col = _warn_and_stringify_numeric_column(col)
            return to_datetime(col, errors="coerce", format=format, utc=utc)

def _convert_arrays_to_dataframe(
    data,
    columns,
    coerce_float: bool = True,
    dtype_backend: DtypeBackend | Literal["numpy"] = "numpy",
) -> DataFrame:
    if data and is_dict_like(data[0]):
        # DBAPI cursors returning dict rows, e.g. pymysql's DictCursor. Use
        # values() rather than lookup by column name, since such cursors may
        # rename duplicate columns (GH#53028)
        data = [tuple(row.values()) for row in data]
    content = lib.to_object_array_tuples(data)
    idx_len = content.shape[0]
    arrays = convert_object_array(
        list(content.T),
        dtype=None,
        coerce_float=coerce_float,
        dtype_backend=dtype_backend,
    )
    if dtype_backend == "pyarrow":
        pa = import_optional_dependency("pyarrow")

        result_arrays = []
        for arr in arrays:
            pa_array = pa.array(arr, from_pandas=True)
            if arr.dtype == "string":
                # TODO: Arrow still infers strings arrays as regular strings instead
                # of large_string, which is what we preserver everywhere else for
                # dtype_backend="pyarrow". We may want to reconsider this
                pa_array = pa_array.cast(pa.string())
            result_arrays.append(ArrowExtensionArray(pa_array))
        arrays = result_arrays  # type: ignore[assignment]
    if arrays:
        return DataFrame._from_arrays(
            arrays, columns=columns, index=range(idx_len), verify_integrity=False
        )
    else:
        return DataFrame(columns=columns)

def pandasSQL_builder(
    con,
    schema: str | None = None,
    need_transaction: bool = False,
) -> PandasSQL:
    """
    Convenience function to return the correct PandasSQL subclass based on the
    provided parameters.  Also creates a sqlalchemy connection and transaction
    if necessary.
    """
    import sqlite3

    if isinstance(con, sqlite3.Connection) or con is None:
        return SQLiteDatabase(con)

    sqlalchemy = import_optional_dependency("sqlalchemy", errors="ignore")

    if isinstance(con, str) and sqlalchemy is None:
        raise ImportError(
            "Using a URI string requires 'sqlalchemy' version "
            f"'{VERSIONS['sqlalchemy']}' or newer."
        )

    if sqlalchemy is not None and isinstance(con, (str, sqlalchemy.engine.Connectable)):
        return SQLDatabase(con, schema, need_transaction)

    adbc = import_optional_dependency("adbc_driver_manager.dbapi", errors="ignore")
    if adbc and isinstance(con, adbc.Connection):
        return ADBCDatabase(con)

    warnings.warn(
        "pandas only supports SQLAlchemy connectable (engine/connection) or "
        "database string URI or sqlite3 DBAPI2 connection. Other DBAPI2 "
        "objects are not tested. Please consider using SQLAlchemy.",
        UserWarning,
        stacklevel=find_stack_level(),
    )
    return SQLiteDatabase(con)

def get_engine(engine: str) -> BaseEngine:
    """return our implementation"""
    if engine == "auto":
        engine = config["io"]["sql"]["engine"]

    if engine == "auto":
        # try engines in this order
        engine_classes = [SQLAlchemyEngine]

        error_msgs = ""
        for engine_class in engine_classes:
            try:
                return engine_class()
            except ImportError as err:
                error_msgs += "\n - " + str(err)

        raise ImportError(
            "Unable to find a usable engine; "
            "tried using: 'sqlalchemy'.\n"
            "A suitable version of "
            "sqlalchemy is required for sql I/O "
            "support.\n"
            "Trying to import the above resulted in these errors:"
            f"{error_msgs}"
        )

    if engine == "sqlalchemy":
        return SQLAlchemyEngine()

    raise ValueError("engine must be one of 'auto', 'sqlalchemy'")

def create(self) -> None:
    if self.exists():
        if self.if_exists == "fail":
            raise ValueError(f"Table '{self.name}' already exists.")
        elif self.if_exists == "replace":
            self.pd_sql.drop_table(self.name, self.schema)
            self._execute_create()
        elif self.if_exists == "append":
            pass
        elif self.if_exists == "delete_rows":
            self.pd_sql.delete_rows(self.name, self.schema)
        else:
            raise ValueError(f"'{self.if_exists}' is not valid for if_exists")
    else:
        self._execute_create()

def insert_data(self) -> tuple[list[str], list[np.ndarray]]:
    if self.index is not None:
        temp = self.frame.copy(deep=False)
        temp.index.names = self.index
        try:
            temp = temp.reset_index()
        except ValueError as err:
            raise ValueError(f"duplicate name in index/columns: {err}") from err
    else:
        temp = self.frame

    column_names = list(map(str, temp.columns))
    ncols = len(column_names)
    # this just pre-allocates the list: None's will be replaced with ndarrays
    # error: List item 0 has incompatible type "None"; expected "ndarray"
    data_list: list[np.ndarray] = [None] * ncols  # type: ignore[list-item]

    for i, (_, ser) in enumerate(temp.items()):
        if ser.dtype.kind == "M":
            if isinstance(ser._values, ArrowExtensionArray):
                import pyarrow as pa

                if pa.types.is_date(ser.dtype.pyarrow_dtype):
                    # GH#53854 to_pydatetime not supported for pyarrow date dtypes
                    d = ser._values.to_numpy(dtype=object)
                else:
                    d = ser.dt.to_pydatetime()._values
            else:
                d = ser._values.to_pydatetime()
        elif ser.dtype.kind == "m":
            vals = ser._values
            if isinstance(vals, ArrowExtensionArray):
                vals = vals.to_numpy(dtype=np.dtype("m8[ns]"))
            # store as integers, see GH#6921, GH#7076
            d = vals.view("i8").astype(object)
        else:
            d = ser._values.astype(object)

        assert isinstance(d, np.ndarray), type(d)

        if ser._can_hold_na:
            # Note: this will miss timedeltas since they are converted to int
            mask = isna(d)
            d[mask] = None

        data_list[i] = d

    return column_names, data_list

def insert(
    self,
    chunksize: int | None = None,
    method: Literal["multi"] | Callable | None = None,
) -> int | None:
    # set insert method
    if method is None:
        exec_insert = self._execute_insert
    elif method == "multi":
        exec_insert = self._execute_insert_multi
    elif callable(method):
        exec_insert = partial(method, self)
    else:
        raise ValueError(f"Invalid parameter `method`: {method}")

    keys, data_list = self.insert_data()

    nrows = len(self.frame)

    if nrows == 0:
        return 0

    if chunksize is None:
        chunksize = nrows
    elif chunksize == 0:
        raise ValueError("chunksize argument should be non-zero")

    chunks = (nrows // chunksize) + 1
    total_inserted = None
    with self.pd_sql.run_transaction() as conn:
        for i in range(chunks):
            start_i = i * chunksize
            end_i = min((i + 1) * chunksize, nrows)
            if start_i >= end_i:
                break

            chunk_iter = zip(
                *(arr[start_i:end_i] for arr in data_list), strict=True
            )
            num_inserted = exec_insert(conn, keys, chunk_iter)
            # GH 46891
            if num_inserted is not None:
                if total_inserted is None:
                    total_inserted = num_inserted
                else:
                    total_inserted += num_inserted
    return total_inserted

def read(
    self,
    exit_stack: ExitStack,
    coerce_float: bool = True,
    parse_dates=None,
    columns=None,
    chunksize: int | None = None,
    dtype_backend: DtypeBackend | Literal["numpy"] = "numpy",
) -> DataFrame | Iterator[DataFrame]:
    from sqlalchemy import select

    if columns is not None and len(columns) > 0:
        cols = [self.table.c[n] for n in columns]
        if self.index is not None:
            for idx in self.index[::-1]:
                cols.insert(0, self.table.c[idx])
        sql_select = select(*cols)
    else:
        sql_select = select(self.table)
    result = self.pd_sql.execute(sql_select)
    column_names = result.keys()

    if chunksize is not None:
        return self._query_iterator(
            result,
            exit_stack,
            chunksize,
            column_names,
            coerce_float=coerce_float,
            parse_dates=parse_dates,
            dtype_backend=dtype_backend,
        )
    else:
        data = result.fetchall()
        self.frame = _convert_arrays_to_dataframe(
            data, column_names, coerce_float, dtype_backend
        )

        self._harmonize_columns(
            parse_dates=parse_dates, dtype_backend=dtype_backend
        )

        if self.index is not None:
            self.frame = self.frame.set_index(self.index)

        return self.frame

def _index_name(self, index, index_label):
    # for writing: index=True to include index in sql table
    if index is True:
        nlevels = self.frame.index.nlevels
        # if index_label is specified, set this as index name(s)
        if index_label is not None:
            if not isinstance(index_label, list):
                index_label = [index_label]
            if len(index_label) != nlevels:
                raise ValueError(
                    "Length of 'index_label' should match number of "
                    f"levels, which is {nlevels}"
                )
            return index_label
        # return the used column labels for the index columns
        if (
            nlevels == 1
            and "index" not in self.frame.columns
            and self.frame.index.name is None
        ):
            return ["index"]
        else:
            return com.fill_missing_names(self.frame.index.names)

    # for reading: index=(list of) string to specify column to set as index
    elif isinstance(index, str):
        return [index]
    elif isinstance(index, list):
        return index
    else:
        return None

def _get_column_names_and_types(self, dtype_mapper):
    column_names_and_types = []
    if self.index is not None:
        for i, idx_label in enumerate(self.index):
            idx_type = dtype_mapper(self.frame.index._get_level_values(i))
            column_names_and_types.append((str(idx_label), idx_type, True))

    column_names_and_types += [
        (str(self.frame.columns[i]), dtype_mapper(self.frame.iloc[:, i]), False)
        for i in range(len(self.frame.columns))
    ]

    return column_names_and_types

def _create_table_setup(self):
    from sqlalchemy import (
        Column,
        PrimaryKeyConstraint,
        Table,
    )
    from sqlalchemy.schema import MetaData

    column_names_and_types = self._get_column_names_and_types(self._sqlalchemy_type)

    columns: list[Any] = [
        Column(name, typ, index=is_index)
        for name, typ, is_index in column_names_and_types
    ]

    if self.keys is not None:
        if not is_list_like(self.keys):
            keys = [self.keys]
        else:
            keys = self.keys
        pkc = PrimaryKeyConstraint(*keys, name=self.name + "_pk")
        columns.append(pkc)

    schema = self.schema or self.pd_sql.meta.schema

    # At this point, attach to new metadata, only attach to self.meta
    # once table is created.
    meta = MetaData()
    return Table(self.name, meta, *columns, schema=schema)

def _sqlalchemy_type(self, col: Index | Series):
    dtype: DtypeArg = self.dtype or {}
    if is_dict_like(dtype):
        dtype = cast("dict", dtype)
        if col.name in dtype:
            return dtype[col.name]

    # Infer type of column, while ignoring missing values.
    # Needed for inserting typed data containing NULLs, GH 8778.
    col_type = lib.infer_dtype(col, skipna=True)

    from sqlalchemy.types import (
        TIMESTAMP,
        BigInteger,
        Boolean,
        Date,
        DateTime,
        Float,
        Integer,
        SmallInteger,
        Text,
        Time,
    )

    if col_type in ("datetime64", "datetime"):
        # GH 9086: TIMESTAMP is the suggested type if the column contains
        # timezone information
        try:
            # error: Item "Index" of "Union[Index, Series]" has no attribute "dt"
            if col.dt.tz is not None:  # type: ignore[union-attr]
                return TIMESTAMP(timezone=True)
        except AttributeError:
            # The column is actually a DatetimeIndex
            # GH 26761 or an Index with date-like data e.g. 9999-01-01
            if getattr(col, "tz", None) is not None:
                return TIMESTAMP(timezone=True)
        return DateTime
    if col_type == "timedelta64":
        warnings.warn(
            "the 'timedelta' type is not supported, and will be "
            "written as integer values (ns frequency) to the database.",
            UserWarning,
            stacklevel=find_stack_level(),
        )
        return BigInteger
    elif col_type == "floating":
        if col.dtype == "float32":
            return Float(precision=23)
        else:
            return Float(precision=53)
    elif col_type == "integer":
        # GH35076 Map pandas integer to optimal SQLAlchemy integer type
        if col.dtype.name.lower() in ("int8", "uint8", "int16"):
            return SmallInteger
        elif col.dtype.name.lower() in ("uint16", "int32"):
            return Integer
        elif col.dtype.name.lower() == "uint64":
            raise ValueError("Unsigned 64 bit integer datatype is not supported")
        else:
            return BigInteger
    elif col_type == "boolean":
        return Boolean
    elif col_type == "date":
        return Date
    elif col_type == "time":
        return Time
    elif col_type == "complex":
        raise ValueError("Complex datatypes not supported")

    return Text

def _get_dtype(self, sqltype):
    from sqlalchemy.types import (
        TIMESTAMP,
        Boolean,
        Date,
        DateTime,
        Float,
        Integer,
        String,
    )

    if isinstance(sqltype, Float):
        return float
    elif isinstance(sqltype, Integer):
        # TODO: Refine integer size.
        return np.dtype("int64")
    elif isinstance(sqltype, TIMESTAMP):
        # we have a timezone capable type
        if not sqltype.timezone:
            return datetime
        return DatetimeTZDtype
    elif isinstance(sqltype, DateTime):
        # Caution: np.datetime64 is also a subclass of np.number.
        return datetime
    elif isinstance(sqltype, Date):
        return date
    elif isinstance(sqltype, Boolean):
        return bool
    elif isinstance(sqltype, String):
        if using_string_dtype():
            return StringDtype(na_value=np.nan)

    return object

def execute(self, sql: str | Select | TextClause | Delete, params=None):
    """Simple passthrough to SQLAlchemy connectable"""
    from sqlalchemy.exc import SQLAlchemyError

    args = [] if params is None else [params]
    if isinstance(sql, str):
        execute_function = self.con.exec_driver_sql
    else:
        execute_function = self.con.execute

    try:
        return execute_function(sql, *args)
    except SQLAlchemyError as exc:
        raise DatabaseError(f"Execution failed on sql '{sql}': {exc}") from exc

def get_table(self, table_name: str, schema: str | None = None) -> Table:
    from sqlalchemy import (
        Numeric,
        Table,
    )

    schema = schema or self.meta.schema
    tbl = Table(table_name, self.meta, autoload_with=self.con, schema=schema)
    for column in tbl.columns:
        if isinstance(column.type, Numeric):
            column.type.asdecimal = False
    return tbl

def drop_table(self, table_name: str, schema: str | None = None) -> None:
    schema = schema or self.meta.schema
    if self.has_table(table_name, schema):
        self.meta.reflect(
            bind=self.con, only=[table_name], schema=schema, views=True
        )
        with self.run_transaction():
            self.get_table(table_name, schema).drop(bind=self.con)
        self.meta.clear()

def delete_rows(self, table_name: str, schema: str | None = None) -> None:
    schema = schema or self.meta.schema
    if self.has_table(table_name, schema):
        self.meta.reflect(
            bind=self.con, only=[table_name], schema=schema, views=True
        )
        table = self.get_table(table_name, schema)
        self.execute(table.delete()).close()
        self.meta.clear()

def execute(self, sql: str | Select | TextClause, params=None):
    from adbc_driver_manager import Error

    if not isinstance(sql, str):
        raise TypeError("Query must be a string unless using sqlalchemy.")
    args = [] if params is None else [params]
    cur = self.con.cursor()
    try:
        cur.execute(sql, *args)
        return cur
    except Error as exc:
        try:
            self.con.rollback()
        except Error as inner_exc:  # pragma: no cover
            ex = DatabaseError(
                f"Execution failed on sql: {sql}\n{exc}\nunable to rollback"
            )
            raise ex from inner_exc

        ex = DatabaseError(f"Execution failed on sql '{sql}': {exc}")
        raise ex from exc

def has_table(self, name: str, schema: str | None = None) -> bool:
    meta = self.con.adbc_get_objects(
        depth="tables", db_schema_filter=schema, table_name_filter=name
    ).read_all()

    for catalog_schema in meta["catalog_db_schemas"].to_pylist():
        if not catalog_schema:
            continue
        for schema_record in catalog_schema:
            if not schema_record:
                continue

            for table_record in schema_record["db_schema_tables"]:
                if table_record["table_name"] == name:
                    return True

    return False

def delete_rows(self, name: str, schema: str | None = None) -> None:
    quoted_table_name = _quote_identifier(name)
    if schema:
        quoted_schema = _quote_identifier(schema)
        quoted_table_name = f"{quoted_schema}.{quoted_table_name}"

    if self.has_table(name, schema):
        self.execute(f"DELETE FROM {quoted_table_name}").close()

def _sql_type_name(self, col):
    dtype: DtypeArg = self.dtype or {}
    if is_dict_like(dtype):
        dtype = cast("dict", dtype)
        if col.name in dtype:
            return dtype[col.name]

    # Infer type of column, while ignoring missing values.
    # Needed for inserting typed data containing NULLs, GH 8778.
    col_type = lib.infer_dtype(col, skipna=True)

    if col_type == "timedelta64":
        warnings.warn(
            "the 'timedelta' type is not supported, and will be "
            "written as integer values (ns frequency) to the database.",
            UserWarning,
            stacklevel=find_stack_level(),
        )
        col_type = "integer"

    elif col_type == "datetime64":
        col_type = "datetime"

    elif col_type == "empty":
        col_type = "string"

    elif col_type == "complex":
        raise ValueError("Complex datatypes not supported")

    if col_type not in _SQL_TYPES:
        col_type = "string"

    return _SQL_TYPES[col_type]

def _data_to_frame(**kwargs):
    head, body, foot = kwargs.pop("data")
    header = kwargs.pop("header")
    kwargs["skiprows"] = _get_skiprows(kwargs["skiprows"])
    if head:
        body = head + body

        # Infer header when there is a <thead> or top <th>-only rows
        if header is None:
            if len(head) == 1:
                header = 0
            else:
                # ignore all-empty-text rows
                header = [i for i, row in enumerate(head) if any(text for text in row)]

    if foot:
        body += foot

    # fill out elements of body that are "ragged"
    _expand_elements(body)
    with TextParser(body, header=header, **kwargs) as tp:
        return tp.read()

def _validate_flavor(flavor):
    if flavor is None:
        flavor = "lxml", "bs4"
    elif isinstance(flavor, str):
        flavor = (flavor,)
    elif isinstance(flavor, abc.Iterable):
        if not all(isinstance(flav, str) for flav in flavor):
            raise TypeError(
                f"Object of type {type(flavor).__name__!r} "
                f"is not an iterable of strings"
            )
    else:
        msg = repr(flavor) if isinstance(flavor, str) else str(flavor)
        msg += " is not a valid flavor"
        raise ValueError(msg)

    flavor = tuple(flavor)
    valid_flavors = set(_valid_parsers)
    flavor_set = set(flavor)

    if not flavor_set & valid_flavors:
        raise ValueError(
            f"{_print_as_set(flavor_set)} is not a valid set of flavors, valid "
            f"flavors are {_print_as_set(valid_flavors)}"
        )
    return flavor

def _parse_tables(self, document, match, attrs):
    element_name = "table"
    tables = document.find_all(element_name, attrs=attrs)
    if not tables:
        raise ValueError("No tables found")

    result = []
    unique_tables = set()
    tables = self._handle_hidden_tables(tables, "attrs")

    for table in tables:
        if self.displayed_only:
            for elem in table.find_all("style"):
                elem.decompose()

            for elem in table.find_all(style=re.compile(r"display:\s*none")):
                elem.decompose()

        if table not in unique_tables and table.find(string=match) is not None:
            result.append(table)
        unique_tables.add(table)
    if not result:
        raise ValueError(f"No tables found matching pattern {match.pattern!r}")
    return result

def _build_doc(self):
    from bs4 import BeautifulSoup

    bdoc = self._setup_build_doc()
    if isinstance(bdoc, bytes) and self.encoding is not None:
        udoc = bdoc.decode(self.encoding)
        from_encoding = None
    else:
        udoc = bdoc
        from_encoding = self.encoding

    soup = BeautifulSoup(udoc, features="html5lib", from_encoding=from_encoding)

    for br in soup.find_all("br"):
        br.replace_with("\n" + br.text)

    return soup

def _parse_tables(self, document, match, kwargs):
    pattern = match.pattern

    # 1. check all descendants for the given pattern and only search tables
    # GH 49929
    xpath_expr = f"//table[.//text()[re:test(., {pattern!r})]]"

    # if any table attributes were given build an xpath expression to
    # search for them
    if kwargs:
        xpath_expr += _build_xpath_expr(kwargs)

    tables = document.xpath(xpath_expr, namespaces=_re_namespace)

    tables = self._handle_hidden_tables(tables, "attrib")
    if self.displayed_only:
        for table in tables:
            # lxml utilizes XPATH 1.0 which does not have regex
            # support. As a result, we find all elements with a style
            # attribute and iterate them to check for display:none
            for elem in table.xpath(".//style"):
                elem.drop_tree()
            for elem in table.xpath(".//*[@style]"):
                if "display:none" in elem.attrib.get("style", "").replace(" ", ""):
                    elem.drop_tree()
    if not tables:
        raise ValueError(f"No tables found matching regex {pattern!r}")
    return tables

def _set_endianness(endianness: str) -> str:
    if endianness.lower() in ["<", "little"]:
        return "<"
    elif endianness.lower() in [">", "big"]:
        return ">"
    else:  # pragma : no cover
        raise ValueError(f"Endianness {endianness} not understood")

def _maybe_convert_to_int_keys(
    convert_dates: dict[Hashable, str], varlist: list[Hashable]
) -> dict[Hashable, str]:
    new_dict: dict[Hashable, str] = {}
    for key, value in convert_dates.items():
        if not value.startswith("%"):  # make sure proper fmts
            convert_dates[key] = "%" + value
        if key in varlist:
            new_dict[varlist.index(key)] = convert_dates[key]
        else:
            if not isinstance(key, int):
                raise ValueError("convert_dates key must be a column or an integer")
            new_dict[key] = convert_dates[key]
    return new_dict

def _dtype_to_default_stata_fmt(
    dtype: np.dtype, column: Series, dta_version: int = 114, force_strl: bool = False
) -> str:
    """
    Map numpy dtype to stata's default format for this type. Not terribly
    important since users can change this in Stata. Semantics are

    object  -> "%DDs" where DD is the length of the string.  If not a string,
                raise ValueError
    float64 -> "%10.0g"
    float32 -> "%9.0g"
    int64   -> "%9.0g"
    int32   -> "%12.0g"
    int16   -> "%8.0g"
    int8    -> "%8.0g"
    strl    -> "%9s"
    """
    # TODO: Refactor to combine type with format
    # TODO: expand this to handle a default datetime format?
    if dta_version < 117:
        max_str_len = 244
    else:
        max_str_len = 2045
        if force_strl:
            return "%9s"
    if dtype.type is np.object_:
        itemsize = max_len_string_array(ensure_object(column._values))
        if itemsize > max_str_len:
            if dta_version >= 117:
                return "%9s"
            else:
                raise ValueError(excessive_string_length_error.format(column.name))
        return "%" + str(max(itemsize, 1)) + "s"
    elif dtype == np.float64:
        return "%10.0g"
    elif dtype == np.float32:
        return "%9.0g"
    elif dtype == np.int32:
        return "%12.0g"
    elif dtype in (np.int8, np.int16):
        return "%8.0g"
    else:  # pragma : no cover
        raise NotImplementedError(f"Data type {dtype} not supported.")

def __eq__(self, other: object) -> bool:
    return (
        isinstance(other, type(self))
        and self.string == other.string
        and self.value == other.value

def get_base_missing_value(cls, dtype: np.dtype) -> float:
    if dtype.type is np.int8:
        value = cls.BASE_MISSING_VALUES["int8"]
    elif dtype.type is np.int16:
        value = cls.BASE_MISSING_VALUES["int16"]
    elif dtype.type is np.int32:
        value = cls.BASE_MISSING_VALUES["int32"]
    elif dtype.type is np.float32:
        value = cls.BASE_MISSING_VALUES["float32"]
    elif dtype.type is np.float64:
        value = cls.BASE_MISSING_VALUES["float64"]
    else:
        raise ValueError("Unsupported dtype")
    return value

def _get_dtypes(
    self, seek_vartypes: int
) -> tuple[list[int | str], list[str | np.dtype]]:
    self._path_or_buf.seek(seek_vartypes)
    typlist = []
    dtyplist = []
    for _ in range(self._nvar):
        typ = self._read_uint16()
        if typ <= 2045:
            typlist.append(typ)
            dtyplist.append(str(typ))
        else:
            try:
                typlist.append(self.TYPE_MAP_XML[typ])  # type: ignore[arg-type]
                dtyplist.append(self.DTYPE_MAP_XML[typ])  # type: ignore[arg-type]
            except KeyError as err:
                raise ValueError(f"cannot convert stata types [{typ}]") from err

    return typlist, dtyplist  # type: ignore[return-value]

def _get_fmtlist(self) -> list[str]:
    if self._format_version >= 118:
        b = 57
    elif self._format_version > 113:
        b = 49
    elif self._format_version > 104:
        b = 12
    else:
        b = 7

    return [self._decode(self._path_or_buf.read(b)) for _ in range(self._nvar)]

def _get_lbllist(self) -> list[str]:
    if self._format_version >= 118:
        b = 129
    elif self._format_version > 108:
        b = 33
    else:
        b = 9
    return [self._decode(self._path_or_buf.read(b)) for _ in range(self._nvar)]

def _get_variable_labels(self) -> list[str]:
    if self._format_version >= 118:
        vlblist = [
            self._decode(self._path_or_buf.read(321)) for _ in range(self._nvar)
        ]
    elif self._format_version > 105:
        vlblist = [
            self._decode(self._path_or_buf.read(81)) for _ in range(self._nvar)
        ]
    else:
        vlblist = [
            self._decode(self._path_or_buf.read(32)) for _ in range(self._nvar)
        ]
    return vlblist

def _get_nobs(self) -> int:
    if self._format_version >= 118:
        return self._read_uint64()
    elif self._format_version >= 103:
        return self._read_uint32()
    else:
        return self._read_uint16()

def _get_data_label(self) -> str:
    if self._format_version >= 118:
        strlen = self._read_uint16()
        return self._decode(self._path_or_buf.read(strlen))
    elif self._format_version == 117:
        strlen = self._read_int8()
        return self._decode(self._path_or_buf.read(strlen))
    elif self._format_version > 105:
        return self._decode(self._path_or_buf.read(81))
    else:
        return self._decode(self._path_or_buf.read(32))

def _get_time_stamp(self) -> str:
    if self._format_version >= 118:
        strlen = self._read_int8()
        return self._path_or_buf.read(strlen).decode("utf-8")
    elif self._format_version == 117:
        strlen = self._read_int8()
        return self._decode(self._path_or_buf.read(strlen))
    elif self._format_version > 104:
        return self._decode(self._path_or_buf.read(18))
    else:
        raise ValueError

def _get_seek_variable_labels(self) -> int:
    if self._format_version == 117:
        self._path_or_buf.read(8)  # <variable_labels>, throw away
        # Stata 117 data files do not follow the described format.  This is
        # a work around that uses the previous label, 33 bytes for each
        # variable, 20 for the closing tag and 17 for the opening tag
        return self._seek_value_label_names + (33 * self._nvar) + 20 + 17
    elif self._format_version >= 118:
        return self._read_int64() + 17
    else:
        raise ValueError

def _read_old_header(self, first_char: bytes) -> None:
    self._format_version = int(first_char[0])
    if self._format_version not in _old_format_versions:
        raise ValueError(_version_error.format(version=self._format_version))
    self._set_encoding()
    # Note 102 format will have a zero in this header position, so support
    # relies on little-endian being set whenever this value isn't one,
    # even though for later releases strictly speaking the value should
    # be either one or two to be valid
    self._byteorder = ">" if self._read_int8() == 0x1 else "<"
    self._filetype = self._read_int8()
    self._path_or_buf.read(1)  # unused

    self._nvar = self._read_uint16()
    self._nobs = self._get_nobs()

    self._data_label = self._get_data_label()

    if self._format_version >= 105:
        self._time_stamp = self._get_time_stamp()

    # descriptors
    if self._format_version >= 111:
        typlist = [int(c) for c in self._path_or_buf.read(self._nvar)]
    else:
        buf = self._path_or_buf.read(self._nvar)
        typlistb = np.frombuffer(buf, dtype=np.uint8)
        typlist = []
        for tp in typlistb:
            if tp in self.OLD_TYPE_MAPPING:
                typlist.append(self.OLD_TYPE_MAPPING[tp])  # type: ignore[index]
            else:
                typlist.append(tp - 127)  # type: ignore[arg-type]

    try:
        self._typlist = [self.TYPE_MAP[typ] for typ in typlist]
    except ValueError as err:
        invalid_types = ",".join([str(x) for x in typlist])
        raise ValueError(f"cannot convert stata types [{invalid_types}]") from err
    try:
        self._dtyplist = [self.DTYPE_MAP[typ] for typ in typlist]
    except ValueError as err:
        invalid_dtypes = ",".join([str(x) for x in typlist])
        raise ValueError(f"cannot convert stata dtypes [{invalid_dtypes}]") from err

    if self._format_version > 108:
        self._varlist = [
            self._decode(self._path_or_buf.read(33)) for _ in range(self._nvar)
        ]
    else:
        self._varlist = [
            self._decode(self._path_or_buf.read(9)) for _ in range(self._nvar)
        ]
    self._srtlist = self._read_int16_count(self._nvar + 1)[:-1]

    self._fmtlist = self._get_fmtlist()

    self._lbllist = self._get_lbllist()

    self._variable_labels = self._get_variable_labels()

    # ignore expansion fields (Format 105 and later)
    # When reading, read five bytes; the last four bytes now tell you
    # the size of the next read, which you discard.  You then continue
    # like this until you read 5 bytes of zeros.

    if self._format_version > 104:
        while True:
            data_type = self._read_int8()
            if self._format_version > 108:
                data_len = self._read_int32()
            else:
                data_len = self._read_int16()
            if data_type == 0:
                break
            self._path_or_buf.read(data_len)

    # necessary data to continue parsing
    self._data_location = self._path_or_buf.tell()

def _setup_dtype(self) -> np.dtype:
    """Map between numpy and state dtypes"""
    if self._dtype is not None:
        return self._dtype

    dtypes = []  # Convert struct data types to numpy data type
    for i, typ in enumerate(self._typlist):
        if typ in self.NUMPY_TYPE_MAP:
            dtypes.append((f"s{i}", f"{self._byteorder}{self.NUMPY_TYPE_MAP[typ]}"))
        else:
            dtypes.append((f"s{i}", f"S{typ}"))
    self._dtype = np.dtype(dtypes)

    return self._dtype

def _read_new_value_labels(self) -> None:
    """Reads value labels with variable length strings (108 and later format)"""
    if self._format_version >= 117:
        self._path_or_buf.seek(self._seek_value_labels)
    else:
        assert self._dtype is not None
        offset = self._nobs * self._dtype.itemsize
        self._path_or_buf.seek(self._data_location + offset)

    while True:
        if self._format_version >= 117:
            if self._path_or_buf.read(5) == b"</val":  # <lbl>
                break  # end of value label table

        slength = self._path_or_buf.read(4)
        if not slength:
            break  # end of value label table (format < 117), or end-of-file
        if self._format_version == 108:
            labname = self._decode(self._path_or_buf.read(9))
        elif self._format_version <= 117:
            labname = self._decode(self._path_or_buf.read(33))
        else:
            labname = self._decode(self._path_or_buf.read(129))
        self._path_or_buf.read(3)  # padding

        n = self._read_uint32()
        txtlen = self._read_uint32()
        off = np.frombuffer(
            self._path_or_buf.read(4 * n), dtype=f"{self._byteorder}i4", count=n
        )
        val = np.frombuffer(
            self._path_or_buf.read(4 * n), dtype=f"{self._byteorder}i4", count=n
        )
        ii = np.argsort(off)
        off = off[ii]
        val = val[ii]
        txt = self._path_or_buf.read(txtlen)
        self._value_label_dict[labname] = {}
        for i in range(n):
            end = off[i + 1] if i < n - 1 else txtlen
            self._value_label_dict[labname][val[i]] = self._decode(
                txt[off[i] : end]
            )

        if self._format_version >= 117:
            self._path_or_buf.read(6)  # </lbl>

def _read_value_labels(self) -> None:
    self._ensure_open()
    if self._value_labels_read:
        # Don't read twice
        return

    if self._format_version >= 108:
        self._read_new_value_labels()
    else:
        self._read_old_value_labels()
    self._value_labels_read = True

def _read_strls(self) -> None:
    self._path_or_buf.seek(self._seek_strls)
    # Wrap v_o in a string to allow uint64 values as keys on 32bit OS
    self.GSO = {"0": ""}
    while True:
        if self._path_or_buf.read(3) != b"GSO":
            break

        if self._format_version == 117:
            v_o = self._read_uint64()
        else:
            buf = self._path_or_buf.read(12)
            # Only tested on little endian machine.
            v_size = 2 if self._format_version == 118 else 3
            if self._byteorder == "<":
                buf = buf[0:v_size] + buf[4 : (12 - v_size)]
            else:
                buf = buf[4 - v_size : 4] + buf[(4 + v_size) :]
            v_o = struct.unpack(f"{self._byteorder}Q", buf)[0]
        typ = self._read_uint8()
        length = self._read_uint32()
        va = self._path_or_buf.read(length)
        if typ == 130:
            decoded_va = va[0:-1].decode(self._encoding)
        else:
            # Stata says typ 129 can be binary, so use str
            decoded_va = str(va)
            # Wrap v_o in a string to allow uint64 values as keys on 32bit OS
        self.GSO[str(v_o)] = decoded_va

def _do_convert_missing(self, data: DataFrame, convert_missing: bool) -> DataFrame:
    # missing code for double was different in version 105 and prior
    old_missingdouble = float.fromhex("0x1.0p333")

    # Check for missing values, and replace if found
    replacements = {}
    for i in range(len(data.columns)):
        fmt = self._typlist[i]
        # recode instances of the old missing code to the currently used value
        if self._format_version <= 105 and fmt == "d":
            data.iloc[:, i] = data.iloc[:, i].replace(
                old_missingdouble, self.MISSING_VALUES["d"]
            )

        if self._format_version <= 111:
            if fmt not in self.OLD_VALID_RANGE:
                continue

            nmin, nmax = self.OLD_VALID_RANGE[fmt]
        else:
            if fmt not in self.VALID_RANGE:
                continue

            nmin, nmax = self.VALID_RANGE[fmt]
        series = data.iloc[:, i]

        # appreciably faster to do this with ndarray instead of Series
        svals = series._values
        missing = (svals < nmin) | (svals > nmax)

        if not missing.any():
            continue

        if convert_missing:  # Replacement follows Stata notation
            missing_loc = np.nonzero(np.asarray(missing))[0]
            umissing, umissing_loc = np.unique(series[missing], return_inverse=True)
            replacement = Series(series, dtype=object)
            for j, um in enumerate(umissing):
                if self._format_version <= 111:
                    missing_value = StataMissingValue(
                        float(self.MISSING_VALUES[fmt])
                    )
                else:
                    missing_value = StataMissingValue(um)

                loc = missing_loc[umissing_loc == j]
                replacement.iloc[loc] = missing_value
        else:  # All replacements are identical
            dtype = series.dtype
            if dtype not in (np.float32, np.float64):
                dtype = np.float64
            replacement = Series(series, dtype=dtype)
            # Note: operating on ._values is much faster than directly
            # TODO: can we fix that?
            replacement._values[missing] = np.nan
        replacements[i] = replacement
    if replacements:
        for idx, value in replacements.items():
            data.isetitem(idx, value)
    return data

def _insert_strls(self, data: DataFrame) -> DataFrame:
    if not hasattr(self, "GSO") or len(self.GSO) == 0:
        return data
    for i, typ in enumerate(self._typlist):
        if typ != "Q":
            continue
        # Wrap v_o in a string to allow uint64 values as keys on 32bit OS
        data.isetitem(i, [self.GSO[str(k)] for k in data.iloc[:, i]])
    return data

def _prepare_non_cat_value_labels(
    self, data: DataFrame
) -> list[StataNonCatValueLabel]:
    """
    Check for value labels provided for non-categorical columns. Value
    labels
    """
    non_cat_value_labels: list[StataNonCatValueLabel] = []
    if self._non_cat_value_labels is None:
        return non_cat_value_labels

    for labname, labels in self._non_cat_value_labels.items():
        if labname in self._converted_names:
            colname = self._converted_names[labname]
        elif labname in data.columns:
            colname = str(labname)
        else:
            raise KeyError(
                f"Can't create value labels for {labname}, it wasn't "
                "found in the dataset."
            )

        if not is_numeric_dtype(data[colname].dtype):
            # Labels should not be passed explicitly for categorical
            # columns that will be converted to int
            raise ValueError(
                f"Can't create value labels for {labname}, value labels "
                "can only be applied to numeric columns."
            )
        svl = StataNonCatValueLabel(colname, labels, self._encoding)
        non_cat_value_labels.append(svl)
    return non_cat_value_labels

def _prepare_categoricals(self, data: DataFrame) -> DataFrame:
    """
    Check for categorical columns, retain categorical information for
    Stata file and convert categorical data to int
    """
    is_cat = [isinstance(dtype, CategoricalDtype) for dtype in data.dtypes]
    if not any(is_cat):
        return data

    self._has_value_labels |= np.array(is_cat)

    get_base_missing_value = StataMissingValue.get_base_missing_value
    data_formatted = []
    for col, col_is_cat in zip(data, is_cat, strict=True):
        if col_is_cat:
            svl = StataValueLabel(data[col], encoding=self._encoding)
            self._value_labels.append(svl)
            dtype = data[col].cat.codes.dtype
            if dtype == np.int64:
                raise ValueError(
                    "It is not possible to export "
                    "int64-based categorical data to Stata."
                )
            values = data[col].cat.codes._values.copy()

            # Upcast if needed so that correct missing values can be set
            if values.max() >= get_base_missing_value(dtype):
                if dtype == np.int8:
                    dtype = np.dtype(np.int16)
                elif dtype == np.int16:
                    dtype = np.dtype(np.int32)
                else:
                    dtype = np.dtype(np.float64)
                values = np.array(values, dtype=dtype)

            # Replace missing values with Stata missing value for type
            values[values == -1] = get_base_missing_value(dtype)
            data_formatted.append((col, values))
        else:
            data_formatted.append((col, data[col]))
    return DataFrame.from_dict(dict(data_formatted))

def _replace_nans(self, data: DataFrame) -> DataFrame:
    # return data
    """
    Checks floating point data columns for nans, and replaces these with
    the generic Stata for missing value (.)
    """
    for c in data:
        dtype = data[c].dtype
        if dtype in (np.float32, np.float64):
            if dtype == np.float32:
                replacement = self.MISSING_VALUES["f"]
            else:
                replacement = self.MISSING_VALUES["d"]
            data[c] = data[c].fillna(replacement)

    return data

def _write_variable_labels(self) -> None:
    # Missing labels are 80 blank characters plus null termination
    blank = _pad_bytes("", 81)

    if self._variable_labels is None:
        for i in range(self.nvar):
            self._write(blank)
        return

    for col in self.data:
        if col in self._variable_labels:
            label = self._variable_labels[col]
            if len(label) > 80:
                raise ValueError("Variable labels must be 80 characters or fewer")
            is_latin1 = all(ord(c) < 256 for c in label)
            if not is_latin1:
                raise ValueError(
                    "Variable labels must contain only characters that "
                    "can be encoded in Latin-1"
                )
            self._write(_pad_bytes(label, 81))
        else:
            self._write(blank)

def _prepare_data(self) -> np.rec.recarray:
    data = self.data
    typlist = self.typlist
    convert_dates = self._convert_dates
    # 1. Convert dates
    if self._convert_dates is not None:
        for i, col in enumerate(data):
            if i in convert_dates:
                data[col] = _datetime_to_stata_elapsed_vec(
                    data[col], self.fmtlist[i]
                )
    # 2. Convert strls
    data = self._convert_strls(data)

    # 3. Convert bad string data to '' and pad to correct length
    dtypes = {}
    native_byteorder = self._byteorder == _set_endianness(sys.byteorder)
    for i, col in enumerate(data):
        typ = typlist[i]
        if typ <= self._max_string_length:
            dc = data[col].fillna("")
            data[col] = dc.apply(_pad_bytes, args=(typ,))
            stype = f"S{typ}"
            dtypes[col] = stype
            data[col] = data[col].astype(stype)
        else:
            dtype = data[col].dtype
            if not native_byteorder:
                dtype = dtype.newbyteorder(self._byteorder)
            dtypes[col] = dtype

    return data.to_records(index=False, column_dtypes=dtypes)

def _write_variable_labels(self) -> None:
    # Missing labels are 80 blank characters plus null termination
    self._update_map("variable_labels")
    bio = BytesIO()
    # 118 scales by 4 to accommodate utf-8 data worst case encoding
    vl_len = 80 if self._dta_version == 117 else 320
    blank = _pad_bytes_new("", vl_len + 1)

    if self._variable_labels is None:
        for _ in range(self.nvar):
            bio.write(blank)
        self._write_bytes(self._tag(bio.getvalue(), "variable_labels"))
        return

    for col in self.data:
        if col in self._variable_labels:
            label = self._variable_labels[col]
            if len(label) > 80:
                raise ValueError("Variable labels must be 80 characters or fewer")
            try:
                encoded = label.encode(self._encoding)
            except UnicodeEncodeError as err:
                raise ValueError(
                    "Variable labels must contain only characters that "
                    f"can be encoded in {self._encoding}"
                ) from err

            bio.write(_pad_bytes_new(encoded, vl_len + 1))
        else:
            bio.write(blank)
    self._write_bytes(self._tag(bio.getvalue(), "variable_labels"))

def _update_strl_names(self) -> None:
    """
    Update column names for conversion to strl if they might have been
    changed to comply with Stata naming rules
    """
    # Update convert_strl if names changed
    for orig, new in self._converted_names.items():
        if orig in self._convert_strl:
            idx = self._convert_strl.index(orig)
            self._convert_strl[idx] = new

def _is_metadata_of(group: Node, parent_group: Node) -> bool:
    """Check if a given group is a metadata group for a given parent_group."""
    if group._v_depth <= parent_group._v_depth:
        return False

    current = group
    while current._v_depth > 1:
        parent = current._v_parent
        if parent == parent_group and current._v_name == "meta":
            return True
        current = current._v_parent
    return False

def _reindex_axis(
    obj: DataFrame, axis: AxisInt, labels: Index, other=None
) -> DataFrame:
    ax = obj._get_axis(axis)
    labels = ensure_index(labels)

    # try not to reindex even if other is provided
    # if it equals our current index
    if other is not None:
        other = ensure_index(other)
    if (other is None or labels.equals(other)) and labels.equals(ax):
        return obj

    labels = ensure_index(labels.unique())
    if other is not None:
        labels = ensure_index(other.unique()).intersection(labels, sort=False)
    if not labels.equals(ax):
        slicer: list[slice | Index] = [slice(None, None)] * obj.ndim
        slicer[axis] = labels
        obj = obj.loc[tuple(slicer)]
    return obj

def _check_tz_conflict(
    name: str, existing_tz: str | tzinfo | None, tz: str | tzinfo | None
) -> None:
    """
    Raise if an append would add or drop the timezone of a stored column.

    The read path localizes the whole stored column with this single tz, so
    changing it reinterprets the rows already written. update_info raises only
    when both sides are set, leaving the None cases silent. GH#68583
    """
    if existing_tz is None and tz is not None:
        raise TypeError(f"cannot append tz-aware data to tz-naive col [{name}]")
    if existing_tz is not None and tz is None:
        raise TypeError(f"cannot append tz-naive data to tz-aware col [{name}]")

def _unconvert_index(
    data, kind: str, encoding: str, errors: str, nan_rep=None
) -> np.ndarray | Index:
    index: Index | np.ndarray

    if kind.startswith("datetime64"):
        if kind == "datetime64":
            # created before we stored resolution information
            index = DatetimeIndex(data, copy=False)
        else:
            index = DatetimeIndex(data.view(kind), copy=False)
    elif kind.startswith("timedelta64"):
        if kind == "timedelta64":
            # created before we stored resolution information
            index = TimedeltaIndex(data, copy=False)
        else:
            index = TimedeltaIndex(data.view(kind), copy=False)
    elif kind == "date":
        try:
            index = np.asarray([date.fromordinal(v) for v in data], dtype=object)
        except ValueError:
            index = np.asarray([date.fromtimestamp(v) for v in data], dtype=object)
    elif kind in ("integer", "float", "bool"):
        index = np.asarray(data)
    elif kind in ("string"):
        index = _unconvert_string_array(
            data, nan_rep=nan_rep, encoding=encoding, errors=errors
        )
    elif kind == "object":
        index = np.asarray(data[0])
    else:  # pragma: no cover
        raise ValueError(f"unrecognized index type {kind}")
    return index

def _maybe_convert(
    values: np.ndarray, val_kind: str, encoding: str, errors: str, nan_rep=None
):
    assert isinstance(val_kind, str), type(val_kind)
    if _need_convert(val_kind):
        conv = _get_converter(val_kind, encoding, errors, nan_rep)
        values = conv(values)
    return values

def _get_converter(kind: str, encoding: str, errors: str, nan_rep=None):
    if kind == "datetime64":
        return lambda x: np.asarray(x, dtype="M8[ns]")
    elif "datetime64" in kind:
        return lambda x: np.asarray(x, dtype=kind)
    elif kind == "string":
        return lambda x: _unconvert_string_array(
            x, nan_rep=nan_rep, encoding=encoding, errors=errors
        )
    else:  # pragma: no cover
        raise ValueError(f"invalid kind {kind}")

def _dtype_to_kind(dtype_str: str) -> str:
    """
    Find the "kind" string describing the given dtype name.
    """
    if dtype_str.startswith(("string", "bytes")):
        kind = "string"
    elif dtype_str.startswith("float"):
        kind = "float"
    elif dtype_str.startswith("complex"):
        kind = "complex"
    elif dtype_str.startswith(("int", "uint")):
        kind = "integer"
    elif dtype_str.startswith("datetime64"):
        kind = dtype_str
    elif dtype_str.startswith("timedelta"):
        kind = dtype_str
    elif dtype_str.startswith("bool"):
        kind = "bool"
    elif dtype_str.startswith("category"):
        kind = "category"
    elif dtype_str.startswith("period"):
        # We store the `freq` attr so we can restore from integers
        kind = "integer"
    elif dtype_str == "object":
        kind = "object"
    elif dtype_str == "str":
        kind = "str"
    else:
        raise ValueError(f"cannot interpret dtype of [{dtype_str}]")

    return kind

def _get_data_and_dtype_name(data: ArrayLike):
    """
    Convert the passed data into a storable form and a dtype string.
    """
    if isinstance(data, Categorical):
        data = data.codes

    if isinstance(data.dtype, DatetimeTZDtype):
        # For datetime64tz we need to drop the TZ in tests TODO: why?
        dtype_name = f"datetime64[{data.dtype.unit}]"
    else:
        dtype_name = data.dtype.name

    if data.dtype.kind in "mM":
        data = np.asarray(data.view("i8"))
        # TODO: we used to reshape for the dt64tz case, but no longer
        #  doing that doesn't seem to break anything.  why?

    elif isinstance(data, (PeriodIndex, PeriodArray)):
        data = data.asi8

    data = np.asarray(data)
    return data, dtype_name

def get_node(self, key: str) -> Node | None:
    """return the node with the key or None if it does not exist"""
    self._check_if_open()
    if not key.startswith("/"):
        key = "/" + key

    assert self._handle is not None
    assert _table_mod is not None  # for mypy
    try:
        node = self._handle.get_node(self.root, key)
    except _table_mod.exceptions.NoSuchNodeError:
        return None

    assert isinstance(node, _table_mod.Node), type(node)
    return node

def __iter__(self) -> Iterator:
    # iterate
    if not self._called_get_result:
        raise ValueError("Cannot iterate until get_result is called.")
    current = self.start
    while current < self.stop:
        stop = min(current + self.chunksize, self.stop)
        if self.coordinates is None:
            # no `where` filter: iterate by (start, stop) directly so we
            # don't materialize an np.arange(0, nrows) coordinate array,
            # which can exhaust memory on very large tables (GH#15937)
            value = self.func(current, stop, None)
        else:
            value = self.func(None, None, self.coordinates[current:stop])
        current = stop
        if value is None or not len(value):
            continue

        yield value

    self.close()

def set_pos(self, pos: int) -> None:
    """set the position of this column in the Table"""
    self.pos = pos
    if pos is not None and self.typ is not None:
        self.typ._v_pos = pos

def maybe_set_size(self, min_itemsize=None) -> None:
    """
    maybe set a string col itemsize:
        min_itemsize can be an integer or a dict with this columns name
        with an integer size
    """
    if self.kind == "string":
        if isinstance(min_itemsize, dict):
            min_itemsize = min_itemsize.get(self.name)

        if min_itemsize is not None and self.typ.itemsize < min_itemsize:
            self.typ = _tables().StringCol(itemsize=min_itemsize, pos=self.pos)

def validate_col(self, itemsize=None):
    """validate this column: return the compared against itemsize"""
    # validate this column for string truncation (or reset to the max size)
    if self.kind == "string":
        c = self.col
        if c is not None:
            if itemsize is None:
                itemsize = self.itemsize
            if c.itemsize < itemsize:
                raise ValueError(
                    f"Trying to store a string with len [{itemsize}] in "
                    f"[{self.cname}] column but\nthis column has a limit of "
                    f"[{c.itemsize}]!\nConsider using min_itemsize to "
                    "preset the sizes on these columns"
                )
            return c.itemsize

    return None

def validate_attr(self, append: bool) -> None:
    # check for backwards incompatibility
    if append:
        existing_kind = getattr(self.attrs, self.kind_attr, None)
        if existing_kind is None:
            # brand new table, nothing to be incompatible with
            return
        if existing_kind != self.kind:
            raise TypeError(
                f"incompatible kind in col [{existing_kind} - {self.kind}]"
            )
        existing_meta = getattr(self.attrs, self.meta_attr, None)
        if existing_meta != self.meta:
            # A CategoricalIndex stores its codes, so both sides are kind
            # "integer" and the check above passes; without this the append
            # silently reinterprets codes as labels or vice versa. GH#65576
            if self.meta == "category":
                raise TypeError(
                    "cannot append a categorical index to a non-categorical index"
                )
            raise TypeError(
                "cannot append a non-categorical index to a categorical index"

def validate_metadata(self, handler: AppendableTable) -> None:
    """validate that kind=category does not change the categories"""
    if self.meta == "category":
        new_metadata = self.metadata
        cur_metadata = handler.read_metadata(self.cname)
        if (
            new_metadata is not None
            and cur_metadata is not None
            and not array_equivalent(
                new_metadata, cur_metadata, strict_nan=True, dtype_equal=True
            )
        ):
            raise ValueError(
                "cannot append a categorical with different categories "

def _get_atom(cls, values: ArrayLike) -> Col:
    """
    Get an appropriately typed and shaped pytables.Col object for values.
    """
    dtype = values.dtype
    # GH#26144, GH#38305, GH#42070. CategoricalDtype/DatetimeTZDtype have
    # working code paths below; PeriodDtype is handled in a separate effort.
    if isinstance(dtype, ExtensionDtype) and not isinstance(
        dtype, (CategoricalDtype, DatetimeTZDtype, PeriodDtype)
    ):
        raise NotImplementedError(
            f"Cannot store a column with dtype {dtype} in an HDF5 file. "
            "HDFStore supports NumPy dtypes, datetime64 with timezone, "
            "categorical, and string extension types."
        )
    itemsize = dtype.itemsize

    shape = values.shape
    if values.ndim == 1:
        # EA, use block shape pretending it is 2D
        # TODO(EA2D): not necessary with 2D EAs
        shape = (1, values.size)

    if isinstance(values, Categorical):
        codes = values.codes
        atom = cls.get_atom_data(shape, kind=codes.dtype.name)
    elif lib.is_np_dtype(dtype, "M") or isinstance(dtype, DatetimeTZDtype):
        atom = cls.get_atom_datetime64(shape)
    elif lib.is_np_dtype(dtype, "m"):
        atom = cls.get_atom_timedelta64(shape)
    elif is_complex_dtype(dtype):
        atom = _tables().ComplexCol(itemsize=itemsize, shape=shape[0])
    elif is_string_dtype(dtype):
        atom = cls.get_atom_string(shape, itemsize)
    else:
        atom = cls.get_atom_data(shape, kind=dtype.name)

    return atom

def get_atom_coltype(cls, kind: str) -> type[Col]:
    """return the PyTables column class for this column"""
    if kind.startswith("uint"):
        k4 = kind[4:]
        col_name = f"UInt{k4}Col"
    elif kind.startswith("period"):
        # we store as integer
        col_name = "Int64Col"
    else:
        kcap = kind.capitalize()
        col_name = f"{kcap}Col"

    return getattr(_tables(), col_name)

def validate_attr(self, append) -> None:
    """validate that we have the same order as the existing & same dtype"""
    if append:
        existing_fields = getattr(self.attrs, self.kind_attr, None)
        if existing_fields is not None and existing_fields != list(self.values):
            raise ValueError("appended items do not match existing items in table!")

        existing_dtype = getattr(self.attrs, self.dtype_attr, None)
        if existing_dtype is not None and existing_dtype != self.dtype:
            raise ValueError(
                "appended items dtype do not match existing items dtype in table!"

def __repr__(self) -> str:
    """return a pretty representation of myself"""
    self.infer_axes()
    s = self.shape
    if s is not None:
        if isinstance(s, (list, tuple)):
            jshape = ",".join([pprint_thing(x) for x in s])
            s = f"[{jshape}]"
        return f"{self.pandas_type:12.12} (shape->{s})"
    return self.pandas_type

def validate_read(self, columns, where) -> None:
    """
    raise if any keywords are passed which are not-None
    """
    if columns is not None:
        raise TypeError(
            "cannot pass a column specification when reading "
            "a Fixed format store. this store must be selected in its entirety"
        )
    if where is not None:
        raise TypeError(
            "cannot pass a where specification when reading "

def read_array(self, key: str, start: int | None = None, stop: int | None = None):
    """read an array for the specified node (off of group"""
    import tables

    node = getattr(self.group, key)
    attrs = node._v_attrs

    transposed = getattr(attrs, "transposed", False)

    if isinstance(node, tables.VLArray):
        ret = node[0][start:stop]
        dtype = getattr(attrs, "value_type", None)
        if dtype is not None:
            ret = pd_array(ret, dtype=dtype)
    else:
        dtype = getattr(attrs, "value_type", None)
        shape = getattr(attrs, "shape", None)

        if shape is not None:
            # length 0 axis
            ret = np.empty(shape, dtype=dtype)
        else:
            ret = node[start:stop]

        if dtype and dtype.startswith("datetime64"):
            # reconstruct a timezone if indicated
            if dtype == "datetime64":
                dtype = "datetime64[ns]"
            tz = getattr(attrs, "tz", None)
            ret = _set_tz(ret, tz, dtype)

        elif dtype and dtype.startswith("timedelta64"):
            if dtype == "timedelta64":
                # This was written back before we started writing
                # timedelta64 units
                ret = np.asarray(ret, dtype="m8[ns]")
            else:
                ret = np.asarray(ret, dtype=dtype)

        elif dtype and dtype.startswith("period"):
            pdtype = PeriodDtype.construct_from_string(dtype)
            ret = PeriodArray._simple_new(np.asarray(ret, dtype="i8"), dtype=pdtype)

    if transposed:
        return ret.T
    else:
        return ret

def read_index(
    self, key: str, start: int | None = None, stop: int | None = None
) -> Index:
    variety = getattr(self.attrs, f"{key}_variety")

    if variety == "multi":
        return self.read_multi_index(key, start=start, stop=stop)
    elif variety == "regular":
        node = getattr(self.group, key)
        index = self.read_index_node(node, start=start, stop=stop)
        return index
    else:  # pragma: no cover
        raise TypeError(f"unrecognized index variety: {variety}")

def shape(self) -> tuple[int] | None:
    try:
        node = self.group.values
        if "shape" in node._v_attrs:
            # GH#37235 an empty array is stored as a length-1 sentinel
            # (see write_array_empty); the true shape is in this attr.
            return tuple(node._v_attrs.shape)
        return (len(node),)
    except (TypeError, AttributeError):
        return None

def shape(self) -> list[int] | None:
    try:
        ndim = self.ndim

        # items
        items = 0
        for i in range(self.nblocks):
            node = getattr(self.group, f"block{i}_items")
            shape = getattr(node, "shape", None)
            if shape is not None:
                items += shape[0]

        # data shape
        node = self.group.block0_values
        data_shape: tuple[Any, ...] | None
        if "shape" in node._v_attrs:
            # GH#37235 an empty block is stored un-transposed as a
            # (1,)*ndim sentinel (see write_array_empty), with the true
            # shape in this attr. Reverse it to match the transposed
            # layout used for non-empty blocks.
            data_shape = tuple(reversed(node._v_attrs.shape))
        else:
            data_shape = getattr(node, "shape", None)
        if data_shape is not None:
            shape = list(data_shape[0 : (ndim - 1)])
        else:
            shape = []

        shape.append(items)

        return shape
    except AttributeError:
        return None

def __getitem__(self, c: str):
    """return the axis for c"""
    for a in self.axes:
        if c == a.name:
            return a
    return None

def validate_multiindex(
    self, obj: DataFrame | Series
) -> tuple[DataFrame, list[Hashable]]:
    """
    validate that we can store the multi-index; reset and return the
    new object
    """
    levels = com.fill_missing_names(obj.index.names)
    if "index" in levels:
        # GH#6208 'index' is reserved as the implicit row-index name
        # in the table format and collides with a level named 'index'.
        raise ValueError(
            "cannot store a MultiIndex with a level named 'index' as a "
            "table; 'index' is reserved for the implicit row index"
        )
    try:
        reset_obj = obj.reset_index()
    except ValueError as err:
        raise ValueError(
            "duplicate names/columns in the multi-index when storing as a table"
        ) from err
    assert isinstance(reset_obj, DataFrame)  # for mypy
    return reset_obj, levels

def data_orientation(self) -> tuple[int, ...]:
    """return a tuple of my permutated axes, non_indexable at the front"""
    return tuple(
        itertools.chain(
            [int(a[0]) for a in self.non_index_axes],
            [int(a.axis) for a in self.index_axes],

def queryables(self) -> dict[str, Any]:
    """return a dict of the kinds allowable columns for this object"""
    # mypy doesn't recognize DataFrame._AXIS_NAMES, so we re-write it here
    axis_names = {0: "index", 1: "columns"}

    # compute the values_axes queryables
    d1 = [(a.cname, a) for a in self.index_axes]
    d2 = [(axis_names[axis], None) for axis, values in self.non_index_axes]
    d3 = [
        (v.cname, v) for v in self.values_axes if v.name in set(self.data_columns)
    ]

    return dict(d1 + d2 + d3)

def validate_min_itemsize(self, min_itemsize) -> None:
    """
    validate the min_itemsize doesn't contain items that are not in the
    axes this needs data_columns to be defined
    """
    if min_itemsize is None:
        return
    if not isinstance(min_itemsize, dict):
        return

    q = self.queryables()
    for k in min_itemsize:
        # ok, apply generally
        if k == "values":
            continue
        if k not in q:
            raise ValueError(
                f"min_itemsize has the key [{k}] which is not an axis or "

def validate_data_columns(
    self, data_columns, min_itemsize, non_index_axes, index_cnames=()
) -> list:
    """
    take the input data_columns and min_itemize and create a data
    columns spec
    """
    if not len(non_index_axes):
        return []

    axis, axis_labels = non_index_axes[0]
    info = self.info.get(axis, {})
    if info.get("type") == "MultiIndex":
        if data_columns:
            raise ValueError(
                f"cannot use a multi-index on axis [{axis}] with "
                f"data_columns {data_columns}"
            )
        if isinstance(min_itemsize, dict):
            # GH#12154 'values' sizes every string column and the index
            # cname(s) size the row index; both are legal here. Only
            # per-column keys are unsupported for MultiIndex columns.
            allowed = {"values", *index_cnames}
            mi_keys = [k for k in min_itemsize if k not in allowed]
            if mi_keys:
                raise ValueError(
                    f"cannot use min_itemsize keys {mi_keys} on axis "
                    f"[{axis}] with a MultiIndex; per-column "
                    "min_itemsize requires data_columns, which are not "
                    "supported with MultiIndex columns. Use "
                    "min_itemsize={'values': N} to apply a single "
                    "min_itemsize across all string columns."
                )

    # evaluate the passed data_columns, True == use all columns
    # take only valid axis labels
    if data_columns is True:
        data_columns = list(axis_labels)
    elif data_columns is None:
        data_columns = []

    # if min_itemsize is a dict, add the keys (exclude 'values')
    if isinstance(min_itemsize, dict):
        existing_data_columns = set(data_columns)
        data_columns = list(data_columns)  # ensure we do not modify
        data_columns.extend(
            [
                k
                for k in min_itemsize.keys()
                if k != "values" and k not in existing_data_columns
            ]
        )

    # return valid columns in the order of our axis
    return [c for c in data_columns if c in axis_labels]

def create_description(
    self,
    complib,
    complevel: int | None,
    fletcher32: bool,
    expectedrows: int | None,
) -> dict[str, Any]:
    """create the description of the table from the axes & values"""
    # provided expected rows if its passed
    if expectedrows is None:
        expectedrows = max(self.nrows_expected, 10000)

    d = {"name": "table", "expectedrows": expectedrows}

    # description from the axes & values
    d["description"] = {a.cname: a.typ for a in self.axes}

    if complib:
        if complevel is None:
            complevel = self._complevel or 9
        filters = _tables().Filters(
            complevel=complevel,
            complib=complib,
            fletcher32=fletcher32 or self._fletcher32,
        )
        d["filters"] = filters
    elif self._filters is not None:
        d["filters"] = self._filters

    return d

def read(
    self,
    where=None,
    columns=None,
    start: int | None = None,
    stop: int | None = None,
) -> Series:
    is_multi_index = self.is_multi_index
    if columns is not None and is_multi_index:
        assert isinstance(self.levels, list)  # needed for mypy
        for n in self.levels:
            if n not in columns:
                columns.insert(0, n)
    s = super().read(where=where, columns=columns, start=start, stop=stop)
    if is_multi_index:
        s = s.set_index(self.levels)

    s = s.iloc[:, 0]

    # remove the default name
    if s.name == "values":
        s.name = None
    return s

def write(self, obj, data_columns=None, **kwargs) -> None:  # type: ignore[override]
    if data_columns is None:
        data_columns = []
    elif data_columns is True:
        data_columns = obj.columns.tolist()
    obj, self.levels = self.validate_multiindex(obj)
    assert isinstance(self.levels, list)  # for mypy
    for n in self.levels:
        if n not in data_columns:
            data_columns.insert(0, n)
    super().write(obj=obj, data_columns=data_columns, **kwargs)

def generate(self, where: dict | list | tuple | str | None) -> PyTablesExpr | None:
    """where can be a : dict,list,tuple,string"""
    if where is None:
        return None

    q = self.table.queryables()
    try:
        return PyTablesExpr(where, queryables=q, encoding=self.table.encoding)
    except NameError as err:
        # raise a nice message, suggesting that the user should use
        # data_columns
        qkeys = ",".join(q.keys())
        msg = dedent(
            f"""\
            The passed where expression: {where}
                        contains an invalid variable reference
                        all of the variable references must be a reference to
                        an axis (e.g. 'index' or 'columns'), or a data_column
                        The currently defined references are: {qkeys}
            """
        )
        raise ValueError(msg) from err

def select(self):
    """
    generate the selection
    """
    if self.condition is not None:
        self._warn_if_unreliable_or()
        try:
            return self.table.table.read_where(
                self.condition.format(), start=self.start, stop=self.stop
            )
        except ValueError as err:
            # GH#39752 PyTables queries indexed columns by combining one
            # boolean array per comparison term in a single numexpr call,
            # capped at NPY_MAXARGS-1 inputs (a numexpr build-time
            # constant, 32 or 64 depending on the targeted numpy).
            # Translate the opaque numexpr error into actionable guidance.
            if "too many inputs" not in str(err):
                raise
            raise ValueError(
                "The passed where expression has too many comparisons "
                "for a query against indexed columns (a numexpr "
                "limitation). Reduce the number of comparisons, or store "
                "the table with 'index=False' (e.g. "
                "DataFrame.to_hdf(..., index=False)) so the query does "
                "not use the column index."
            ) from err
    elif self.coordinates is not None:
        return self.table.table.read_coordinates(self.coordinates)
    return self.table.table.read(start=self.start, stop=self.stop)

def parse_data(self) -> list[dict[str, str | None]]:
    from xml.etree.ElementTree import iterparse

    if self.stylesheet is not None:
        raise ValueError(
            "To use stylesheet, you need lxml installed and selected as parser."
        )

    elems: list[Any] = []
    if self.iterparse is None:
        self.xml_doc = self._parse_doc(self.path_or_buffer)
        elems = self._validate_path()

    self._validate_names()

    xml_dicts: list[dict[str, str | None]] = (
        self._parse_nodes(elems)
        if self.iterparse is None
        else self._iterparse_nodes(iterparse)
    )

    return xml_dicts

def _validate_path(self) -> list[Any]:
    """
    Notes
    -----
    ``etree`` supports limited ``XPath``. If user attempts a more complex
    expression syntax error will raise.
    """
    msg = (
        "xpath does not return any nodes or attributes. "
        "Be sure to specify in `xpath` the parent nodes of "
        "children and attributes to parse. "
        "If document uses namespaces denoted with "
        "xmlns, be sure to define namespaces and "
        "use them in xpath."
    )
    try:
        elems = self.xml_doc.findall(  # type: ignore[union-attr]
            self.xpath, namespaces=self.namespaces
        )
        children = [ch for el in elems for ch in el.findall("*")]
        attrs = {k: v for el in elems for k, v in el.attrib.items()}

        if elems is None:
            raise ValueError(msg)

        if elems is not None:
            if self.elems_only and children == []:
                raise ValueError(msg)
            if self.attrs_only and attrs == {}:
                raise ValueError(msg)
            if children == [] and attrs == {}:
                raise ValueError(msg)

    except (KeyError, SyntaxError) as err:
        raise SyntaxError(
            "You have used an incorrect or unsupported XPath "
            "expression for etree library or you used an "
            "undeclared namespace prefix."
        ) from err

    return elems  # pyright: ignore[reportReturnType]

def _validate_names(self) -> None:
    children: list[Any]

    if self.names:
        if self.iterparse:
            children = self.iterparse[next(iter(self.iterparse))]
        else:
            parent = self.xml_doc.find(  # type: ignore[union-attr]
                self.xpath, namespaces=self.namespaces
            )
            children = parent.findall("*") if parent is not None else []

        if is_list_like(self.names):
            if len(self.names) < len(children):
                raise ValueError(
                    "names does not match length of child elements in xpath."
                )
        else:
            raise TypeError(
                f"{type(self.names).__name__} is not a valid type for names"

def _validate_path(self) -> list[Any]:
    msg = (
        "xpath does not return any nodes or attributes. "
        "Be sure to specify in `xpath` the parent nodes of "
        "children and attributes to parse. "
        "If document uses namespaces denoted with "
        "xmlns, be sure to define namespaces and "
        "use them in xpath."
    )

    elems = self.xml_doc.xpath(  # type: ignore[union-attr]
        self.xpath, namespaces=self.namespaces
    )
    children = [ch for el in elems for ch in el.xpath("*")]
    attrs = {k: v for el in elems for k, v in el.attrib.items()}

    if elems == []:
        raise ValueError(msg)

    if elems != []:
        if self.elems_only and children == []:
            raise ValueError(msg)
        if self.attrs_only and attrs == {}:
            raise ValueError(msg)
        if children == [] and attrs == {}:
            raise ValueError(msg)

    return elems

def _validate_names(self) -> None:
    children: list[Any]

    if self.names:
        if self.iterparse:
            children = self.iterparse[next(iter(self.iterparse))]
        else:
            children = self.xml_doc.xpath(  # type: ignore[union-attr]
                self.xpath + "[1]/*", namespaces=self.namespaces
            )

        if is_list_like(self.names):
            if len(self.names) < len(children):
                raise ValueError(
                    "names does not match length of child elements in xpath."
                )
        else:
            raise TypeError(
                f"{type(self.names).__name__} is not a valid type for names"

def _parse_doc(
    self, raw_doc: FilePath | ReadBuffer[bytes] | ReadBuffer[str]
) -> etree._Element:
    from lxml.etree import (
        XMLParser,
        fromstring,
        parse,
    )

    handle_data = get_data_from_filepath(
        filepath_or_buffer=raw_doc,
        encoding=self.encoding,
        compression=self.compression,
        storage_options=self.storage_options,
    )

    with handle_data as xml_data:
        curr_parser = XMLParser(encoding=self.encoding)

        if isinstance(xml_data, io.StringIO):
            if self.encoding is None:
                raise TypeError(
                    "Can not pass encoding None when input is StringIO."
                )

            document = fromstring(
                xml_data.getvalue().encode(self.encoding), parser=curr_parser
            )
        else:
            document = parse(xml_data, parser=curr_parser)

    return document

def validate_header_arg(header: object) -> None:
    if header is None:
        return
    if is_integer(header):
        header = cast("int", header)
        if header < 0:
            # GH 27779
            raise ValueError(
                "Passing negative integer to header is invalid. "
                "For no header, use header=None instead"
            )
        return
    if is_list_like(header, allow_sets=False):
        header = cast("Sequence[int]", header)
        if not all(map(is_integer, header)):
            raise ValueError("header must be integer or list of integers")
        if any(i < 0 for i in header):
            raise ValueError("cannot specify multi-index header with negative integers")
        return
    if is_bool(header):
        raise TypeError(
            "Passing a bool to header is invalid. Use header=None for no header or "
            "header=int or list-like of ints to specify "
            "the row(s) making up the column names"
        )
    # GH 16338
    raise ValueError("header must be integer or list of integers")

def file_exists(filepath_or_buffer: FilePath | BaseBuffer) -> bool:
    """Test whether file exists."""
    exists = False
    filepath_or_buffer = stringify_path(filepath_or_buffer)
    if not isinstance(filepath_or_buffer, str):
        return exists
    try:
        exists = os.path.exists(filepath_or_buffer)
        # gh-5874: if the filepath is too long will raise here
    except (TypeError, ValueError):
        pass
    return exists

def _is_binary_mode(handle: FilePath | BaseBuffer, mode: str) -> bool:
    """Whether the handle is opened in binary mode"""
    # specified by user
    if "t" in mode or "b" in mode:
        return "b" in mode

    # exceptions
    text_classes = (
        # classes that expect string but have 'b' in mode
        codecs.StreamWriter,
        codecs.StreamReader,
        codecs.StreamReaderWriter,
        TextIOBase,
    )
    if issubclass(type(handle), text_classes):
        return False

    if isinstance(handle, _get_binary_io_classes()):
        return True

    if hasattr(handle, "mode"):
        return "b" in handle.mode

    # GH#52252 buffers without a "mode" attribute that are not covered by the
    # classes above, e.g. mmap.mmap and botocore's StreamingBody, which is an
    # IOBase subclass without being a Raw/BufferedIOBase subclass.
    return isinstance(handle, (mmap.mmap, IOBase))

def close(self) -> None:
    if self.closed:
        # already closed
        return
    if self.getbuffer().nbytes:
        # write to buffer
        self.seek(0)
        with self.buffer:
            self.write_to_buffer()
    else:
        self.buffer.close()
    super().close()

def extend_mode(self, mode: str) -> str:
    mode = mode.replace("b", "")
    if mode != "w":
        return mode
    if self.name is not None:
        suffix = Path(self.name).suffix
        if suffix in (".gz", ".xz", ".bz2"):
            mode = f"{mode}:{suffix[1:]}"
    return mode

def infer_filename(self) -> str | None:
    """
    If an explicit archive_name is not given, we still want the file inside the zip
    file not to be named something.tar, because that causes confusion (GH39465).
    """
    if self.name is None:
        return None

    filename = Path(self.name)
    if filename.suffix == ".tar":
        return filename.with_suffix("").name
    elif filename.suffix in (".tar.gz", ".tar.bz2", ".tar.xz"):
        return filename.with_suffix("").with_suffix("").name
    return filename.name

def get_engine(engine: str) -> BaseImpl:
    """return our implementation"""
    if engine == "auto":
        engine = config["io"]["parquet"]["engine"]

    if engine == "auto":
        # try engines in this order
        engine_classes = [PyArrowImpl, FastParquetImpl]

        error_msgs = ""
        for engine_class in engine_classes:
            try:
                return engine_class()
            except ImportError as err:
                error_msgs += "\n - " + str(err)

        raise ImportError(
            "Unable to find a usable engine; "
            "tried using: 'pyarrow', 'fastparquet'.\n"
            "A suitable version of "
            "pyarrow or fastparquet is required for parquet "
            "support.\n"
            "Trying to import the above resulted in these errors:"
            f"{error_msgs}"
        )

    if engine == "pyarrow":
        return PyArrowImpl()
    elif engine == "fastparquet":
        warnings.warn(
            "The 'fastparquet' engine is deprecated and will be removed in a "
            "future version. Use 'pyarrow' instead.",
            Pandas4Warning,
            stacklevel=find_stack_level(),
        )
        return FastParquetImpl()

    raise ValueError("engine must be one of 'pyarrow', 'fastparquet'")

def read(
    self,
    path,
    columns=None,
    filters=None,
    storage_options: StorageOptions | None = None,
    filesystem=None,
    to_pandas_kwargs: dict[str, Any] | None = None,
    **kwargs,
) -> DataFrame:
    parquet_kwargs: dict[str, Any] = {}
    dtype_backend = kwargs.pop("dtype_backend", lib.no_default)
    # We are disabling nullable dtypes for fastparquet pending discussion
    parquet_kwargs["pandas_nulls"] = False
    if dtype_backend is not lib.no_default:
        raise ValueError(
            "The 'dtype_backend' argument is not supported for the "
            "fastparquet engine"
        )
    if filesystem is not None:
        raise NotImplementedError(
            "filesystem is not implemented for the fastparquet engine."
        )
    if to_pandas_kwargs is not None:
        raise NotImplementedError(
            "to_pandas_kwargs is not implemented for the fastparquet engine."
        )
    path = stringify_path(path)
    handles = None
    if is_fsspec_url(path):
        fsspec = import_optional_dependency("fsspec")

        parquet_kwargs["fs"] = fsspec.open(path, "rb", **(storage_options or {})).fs
    elif isinstance(path, str) and not os.path.isdir(path):
        # use get_handle only when we are very certain that it is not a directory
        # fsspec resources can also point to directories
        # this branch is used for example when reading from non-fsspec URLs
        handles = get_handle(
            path, "rb", is_text=False, storage_options=storage_options
        )
        path = handles.handle

    try:
        parquet_file = self.api.ParquetFile(path, **parquet_kwargs)
        with catch_warnings():
            filterwarnings(
                "ignore",
                "make_block is deprecated",
                Pandas4Warning,
            )
            return parquet_file.to_pandas(
                columns=columns, filters=filters, **kwargs
            )
    finally:
        if handles is not None:
            handles.close()

def set_default_names(data):
    """Sets index names to 'index' for regular, or 'level_x' for Multi"""
    if com.all_not_none(*data.index.names):
        nms = data.index.names
        if len(nms) == 1 and data.index.name == "index":
            warnings.warn(
                "Index name of 'index' is not round-trippable.",
                stacklevel=find_stack_level(),
            )
        elif len(nms) > 1 and any(x.startswith("level_") for x in nms):
            warnings.warn(
                "Index names beginning with 'level_' are not round-trippable.",
                stacklevel=find_stack_level(),
            )
        return data

    data = data.copy(deep=False)
    if data.index.nlevels > 1:
        data.index.names = com.fill_missing_names(data.index.names)
    else:
        data.index.name = data.index.name or "index"
    return data

def convert_pandas_type_to_json_field(arr) -> dict[str, JSONSerializable]:
    dtype = arr.dtype
    name: JSONSerializable
    if arr.name is None:
        name = "values"
    else:
        name = arr.name
    field: dict[str, JSONSerializable] = {
        "name": name,
        "type": as_json_table_type(dtype),
    }

    if isinstance(dtype, CategoricalDtype):
        cats = dtype.categories
        ordered = dtype.ordered

        field["constraints"] = {"enum": list(cats)}
        field["ordered"] = ordered
    elif isinstance(dtype, PeriodDtype):
        field["freq"] = dtype.freq.freqstr
    elif isinstance(dtype, DatetimeTZDtype):
        if timezones.is_utc(dtype.tz):
            field["tz"] = "UTC"
        else:
            zone = timezones.get_timezone(dtype.tz)
            if isinstance(zone, str):
                field["tz"] = zone
            elif isinstance(zone, timezone):
                # fixed-offset stdlib timezone, e.g. timezone(timedelta(hours=1));
                # str gives a round-trippable "UTC+HH:MM" (GH#39537)
                field["tz"] = str(zone)
    elif isinstance(dtype, ExtensionDtype):
        field["extDtype"] = dtype.name
    return field

def _should_convert_dates(
    convert_dates: bool | list[str],
    keep_default_dates: bool,
    col: Hashable,
) -> bool:
    """
    Return bool whether a DataFrame column should be cast to datetime.
    """
    if convert_dates is False:
        # convert_dates=True means follow keep_default_dates
        return False
    elif not isinstance(convert_dates, bool) and col in set(convert_dates):
        return True
    elif not keep_default_dates:
        return False
    elif not isinstance(col, str):
        return False
    col_lower = col.lower()
    if (
        col_lower.endswith(("_at", "_time"))
        or col_lower in {"modified", "date", "datetime"}
        or col_lower.startswith("timestamp")
    ):
        return True
    return False

def write(self) -> str:
    iso_dates = self.date_format == "iso"
    try:
        return ujson_dumps(
            self.obj_to_write,
            orient=self.orient,
            double_precision=self.double_precision,
            ensure_ascii=self.ensure_ascii,
            date_unit=self.date_unit,
            iso_dates=iso_dates,
            default_handler=self.default_handler,
            indent=self.indent,
        )
    except OverflowError as err:
        # GH#36211 the C encoder recurses without bound on object types it
        #  does not understand.
        if "Maximum recursion level reached" not in str(err):
            raise
        raise ValueError(
            "Unable to serialize object to JSON: encountered an "
            "unsupported object type; convert the column to a supported "
            "type (e.g. str) before calling to_json."
        ) from err

def obj_to_write(self) -> NDFrame | Mapping[IndexLabel, Any]:
    if not self.index and self.orient == "split":
        return {"name": self.obj.name, "data": self.obj.values}
    else:
        return self.obj

def obj_to_write(self) -> NDFrame | Mapping[IndexLabel, Any]:
    if not self.index and self.orient == "split":
        obj_to_write = self.obj.to_dict(orient="split")
        del obj_to_write["index"]
    else:
        obj_to_write = self.obj
    return obj_to_write

def _format_axes(self) -> None:
    """
    Try to format axes if they are datelike.
    """
    if not self.obj.index.is_unique and self.orient in ("index", "columns"):
        raise ValueError(
            f"DataFrame index must be unique for orient='{self.orient}'."
        )
    if not self.obj.columns.is_unique and self.orient in (
        "index",
        "columns",
        "records",
    ):
        raise ValueError(
            f"DataFrame columns must be unique for orient='{self.orient}'."

def _combine_lines(self, lines) -> str:
    """
    Combines a list of JSON objects into one JSON object.
    """
    return (
        f"[{','.join([line for line in (line.strip() for line in lines) if line])}]"

def _read_ujson(self) -> DataFrame | Series:
    """
    Read JSON using the ujson engine.
    """
    obj: DataFrame | Series
    if self.lines:
        if self.chunksize:
            chunks = list(self)
            if chunks:
                obj = concat(chunks)
            else:
                obj = self._get_object_parser(self._combine_lines([]))
        elif self.nrows is not None:
            lines = list(islice(self.data, self.nrows))
            lines_json = self._combine_lines(lines)
            obj = self._get_object_parser(lines_json)
        else:
            data = ensure_str(self.data)
            data_lines = data.split("\n")
            obj = self._get_object_parser(self._combine_lines(data_lines))
    else:
        obj = self._get_object_parser(self.data)
    if self.dtype_backend is not lib.no_default:
        with option_context("future.distinguish_nan_and_na", False):
            return obj.convert_dtypes(dtype_backend=self.dtype_backend)
    else:
        return obj

def _get_object_parser(self, json: str) -> DataFrame | Series:
    """
    Parses a json document into a pandas object.
    """
    typ = self.typ
    dtype = self.dtype
    kwargs = {
        "orient": self.orient,
        "dtype": self.dtype,
        "convert_axes": self.convert_axes,
        "convert_dates": self.convert_dates,
        "keep_default_dates": self.keep_default_dates,
        "precise_float": self.precise_float,
        "date_unit": self.date_unit,
        "dtype_backend": self.dtype_backend,
    }
    if typ == "frame":
        return FrameParser(json, **kwargs).parse()
    elif typ == "series":
        if not isinstance(dtype, bool):
            kwargs["dtype"] = dtype
        return SeriesParser(json, **kwargs).parse()
    else:
        raise ValueError(f"{typ=} must be 'frame' or 'series'.")

def __next__(self) -> DataFrame | Series:
    chunk_size: int | None
    if self.nrows is not None:
        remaining = self.nrows - self.nrows_seen
        if remaining <= 0:
            self.close()
            raise StopIteration
        if self.chunksize is None:
            chunk_size = remaining
        else:
            chunk_size = min(self.chunksize, remaining)
    else:
        chunk_size = self.chunksize

    lines = list(islice(self.data, chunk_size))
    if not lines:
        self.close()
        raise StopIteration

    try:
        lines_json = self._combine_lines(lines)
        obj = self._get_object_parser(lines_json)

        # Make sure that the returned objects have the right index.
        obj.index = range(self.nrows_seen, self.nrows_seen + len(obj))
        self.nrows_seen += len(obj)
    except Exception as ex:
        self.close()
        raise ex

    if self.dtype_backend is not lib.no_default:
        with option_context("future.distinguish_nan_and_na", False):
            return obj.convert_dtypes(dtype_backend=self.dtype_backend)
    else:
        return obj

def _parse(self) -> Series:
    data = ujson_loads(self.json, precise_float=self.precise_float)

    if self.orient == "split":
        decoded = {str(k): v for k, v in data.items()}
        self.check_keys_split(decoded)
        return Series(**decoded)
    else:
        return Series(data)

def _parse(self) -> DataFrame:
    json = self.json
    orient = self.orient

    if orient == "split":
        decoded = {
            str(k): v
            for k, v in ujson_loads(json, precise_float=self.precise_float).items()
        }
        self.check_keys_split(decoded)
        orig_names = [
            (tuple(col) if isinstance(col, list) else col)
            for col in decoded["columns"]
        ]
        decoded["columns"] = dedup_names(
            orig_names,
            is_potential_multi_index(orig_names, None),
        )
        return DataFrame(dtype=None, **decoded)
    elif orient == "index":
        return DataFrame.from_dict(
            ujson_loads(json, precise_float=self.precise_float),
            dtype=None,
            orient="index",
        )
    elif orient == "table":
        return parse_table_schema(json, precise_float=self.precise_float)
    else:
        # includes orient == "columns"
        return DataFrame(
            ujson_loads(json, precise_float=self.precise_float), dtype=None

def convert_to_line_delimits(s: str) -> str:
    """
    Helper function that converts JSON lists to line delimited JSON.
    """
    # Determine we have a JSON list to turn to lines otherwise just return the
    # json object, only lists can
    if not s[0] == "[" and s[-1] == "]":
        return s
    s = s[1:-1]

    return convert_json_to_lines(s)

def _validate_meta(meta: str | list[str | list[str]] | None) -> None:
    """
    Validate that meta parameter contains only strings or lists of strings.
    Parameters
    ----------
    meta : str or list of str or list of list of str or None
        The meta parameter to validate.
    Raises
    ------
    TypeError
        If meta contains elements that are not strings or lists of strings.
    """
    if meta is None:
        return
    if isinstance(meta, str):
        return
    for item in meta:
        if isinstance(item, list):
            for subitem in item:
                if not isinstance(subitem, str):
                    raise TypeError(
                        "All elements in nested meta paths must be strings. "
                        f"Found {type(subitem).__name__}: {subitem!r}"
                    )
        elif not isinstance(item, str):
            raise TypeError(
                "All elements in 'meta' must be strings or lists of strings. "
                f"Found {type(item).__name__}: {item!r}"

def init_qt_clipboard():
    global QApplication
    # $DISPLAY should exist

    # Try to import from qtpy, but if that fails try PyQt5 then PyQt4
    try:
        from qtpy.QtWidgets import QApplication
    except ImportError:
        try:
            from PyQt5.QtWidgets import QApplication
        except ImportError:
            from PyQt4.QtGui import QApplication

    app = QApplication.instance()
    if app is None:
        # GH#44625 QApplication calls setlocale(LC_ALL, "") without restoring
        #  it, changing e.g. LC_TIME and LC_NUMERIC for the rest of the
        #  process. Nothing else in pandas alters the process locale, so put
        #  it back the way we found it.
        with set_locale(locale.setlocale(locale.LC_ALL)):
            app = QApplication([])

    def copy_qt(text):
        text = _stringifyText(text)  # Converts non-str values to str.
        cb = app.clipboard()
        cb.setText(text)

    def paste_qt() -> str:
        cb = app.clipboard()
        return str(cb.text())

    return copy_qt, paste_qt

def determine_clipboard():
    """
    Determine the OS/platform and set the copy() and paste() functions
    accordingly.
    """
    global Foundation, AppKit, qtpy, PyQt4, PyQt5

    # Setup for the CYGWIN platform:
    if (
        "cygwin" in platform.system().lower()
    ):  # Cygwin has a variety of values returned by platform.system(),
        # such as 'CYGWIN_NT-6.1'
        # Cygwin uses /dev/clipboard; upstream pyperclip#55 was closed in 2017
        # as "mostly works" -- known imperfections are warned about per-call
        # in copy_dev_clipboard.
        if os.path.exists("/dev/clipboard"):
            warnings.warn(
                "Pyperclip's support for Cygwin is not perfect, "
                "see https://github.com/asweigart/pyperclip/issues/55",
                stacklevel=find_stack_level(),
            )
            return init_dev_clipboard_clipboard()

    # Setup for the WINDOWS platform:
    elif os.name == "nt" or platform.system() == "Windows":
        return init_windows_clipboard()

    if platform.system() == "Linux":
        if _executable_exists("wslconfig.exe"):
            return init_wsl_clipboard()

    # Setup for the macOS platform:
    if os.name == "mac" or platform.system() == "Darwin":
        try:
            import AppKit
            import Foundation  # check if pyobjc is installed
        except ImportError:
            return init_osx_pbcopy_clipboard()
        else:
            return init_osx_pyobjc_clipboard()

    # Setup for the LINUX platform:
    if HAS_DISPLAY:
        if os.environ.get("WAYLAND_DISPLAY") and _executable_exists("wl-copy"):
            return init_wl_clipboard()
        if _executable_exists("xsel"):
            return init_xsel_clipboard()
        if _executable_exists("xclip"):
            return init_xclip_clipboard()
        if _executable_exists("klipper") and _executable_exists("qdbus"):
            return init_klipper_clipboard()

        try:
            # qtpy is a small abstraction layer that lets you write applications
            # using a single api call to either PyQt or PySide.
            # https://pypi.python.org/project/QtPy
            import qtpy  # check if qtpy is installed
        except ImportError:
            # If qtpy isn't installed, fall back on importing PyQt4.
            try:
                import PyQt5  # check if PyQt5 is installed
            except ImportError:
                try:
                    import PyQt4  # check if PyQt4 is installed
                except ImportError:
                    pass  # We want to fail fast for all non-ImportError exceptions.
                else:
                    return init_qt_clipboard()
            else:
                return init_qt_clipboard()
        else:
            return init_qt_clipboard()

    return init_no_clipboard()

def __call__(self, *args):
    ret = self.f(*args)
    if not ret and get_errno():
        raise PyperclipWindowsException("Error calling " + self.f.__name__)
    return ret

def __next__(self) -> DataFrame:
    da = self.read(nrows=self.chunksize or 1)
    if da.empty:
        self.close()
        raise StopIteration
    return da

def _read_float(self, offset: int, width: int) -> float:
    assert self._cached_page is not None
    if width == 4:
        return read_float_with_byteswap(
            self._cached_page, offset, self.need_byteswap
        )
    elif width == 8:
        return read_double_with_byteswap(
            self._cached_page, offset, self.need_byteswap
        )
    else:
        self.close()
        raise ValueError("invalid float width")

def _read_uint(self, offset: int, width: int) -> int:
    assert self._cached_page is not None
    if width == 1:
        return self._read_bytes(offset, 1)[0]
    elif width == 2:
        return read_uint16_with_byteswap(
            self._cached_page, offset, self.need_byteswap
        )
    elif width == 4:
        return read_uint32_with_byteswap(
            self._cached_page, offset, self.need_byteswap
        )
    elif width == 8:
        return read_uint64_with_byteswap(
            self._cached_page, offset, self.need_byteswap
        )
    else:
        self.close()
        raise ValueError("invalid int width")

def _read_bytes(self, offset: int, length: int):
    assert self._cached_page is not None
    if offset + length > len(self._cached_page):
        self.close()
        raise ValueError("The cached page is too small.")
    return self._cached_page[offset : offset + length]

def _parse_metadata(self) -> None:
    done = False
    while not done:
        self._cached_page = self._path_or_buf.read(self._page_length)
        if len(self._cached_page) <= 0:
            break
        if len(self._cached_page) != self._page_length:
            raise ValueError("Failed to read a meta data page from the SAS file.")
        done = self._process_page_meta()

    self._column_convert_types: list[str | None] = []
    for j in range(self.column_count):
        if self._column_types[j] == b"d" and self.convert_dates:
            fmt = self.column_formats[j]
            if fmt in const.sas_date_formats:
                self._column_convert_types.append("d")
            elif fmt in const.sas_datetime_formats:
                self._column_convert_types.append("s")
            else:
                self._column_convert_types.append(None)
        else:
            self._column_convert_types.append(None)

    # The default also governs header text, which is decoded either way, so
    #  a numeric-only file with non-ascii column names changes too
    if not self._encoding_specified and (
        (self.convert_text and b"s" in self._column_types)
        or self._non_ascii_header_text
    ):
        warnings.warn(
            "The default value of 'encoding' in read_sas is deprecated. In a "
            "future version the default will change from None to 'infer', and "
            "text will be decoded using the encoding recorded in the file "
            "rather than returned as bytes. Pass encoding='infer' to adopt "
            "the future behavior, or encoding=None to keep the current one.",
            Pandas4Warning,
            stacklevel=find_stack_level(),

def _process_page_meta(self) -> bool:
    self._read_page_header()
    pt = [*const.page_meta_types, const.page_amd_type, const.page_mix_type]
    if self._current_page_type in pt:
        self._process_page_metadata()
    is_data_page = self._current_page_type == const.page_data_type
    is_mix_page = self._current_page_type == const.page_mix_type
    return bool(is_data_page or is_mix_page or self._data_subheader_count > 0)

def _process_columntext_subheader(self, offset: int, length: int) -> None:
    offset += self._int_length
    text_block_size = self._read_uint(offset, const.text_block_size_length)

    buf = self._read_bytes(offset, text_block_size)
    cname_raw = buf[0:text_block_size].rstrip(b"\x00 ")
    self.column_names_raw.append(cname_raw)

    if len(self.column_names_raw) == 1:
        compression_literal = b""
        for cl in const.compression_literals:
            if cl in cname_raw:
                compression_literal = cl
        self.compression = compression_literal
        offset -= self._int_length

        offset1 = offset + 16
        if self.U64:
            offset1 += 4

        buf = self._read_bytes(offset1, self._lcp)
        compression_literal = buf.rstrip(b"\x00")
        if compression_literal == b"":
            self._lcs = 0
            offset1 = offset + 32
            if self.U64:
                offset1 += 4
            buf = self._read_bytes(offset1, self._lcp)
            self.creator_proc = buf[0 : self._lcp]
        elif compression_literal == const.rle_compression:
            offset1 = offset + 40
            if self.U64:
                offset1 += 4
            buf = self._read_bytes(offset1, self._lcp)
            self.creator_proc = buf[0 : self._lcp]
        elif self._lcs > 0:
            self._lcp = 0
            offset1 = offset + 16
            if self.U64:
                offset1 += 4
            buf = self._read_bytes(offset1, self._lcs)
            self.creator_proc = buf[0 : self._lcp]
        if hasattr(self, "creator_proc"):
            self.creator_proc = self._convert_header_text(self.creator_proc)  # pyright: ignore[reportArgumentType]

def _string_mode(
    self, ns: int
) -> tuple[int, tuple[np.ndarray, np.ndarray, bool] | None]:
    """
    Pick how the Cython parser should emit string cells for this chunk.

    Returns ``(mode, table)``; see the string modes in sas_constants.py. The
    pyarrow modes require that the result actually be a pyarrow-backed str
    column, and that the source encoding translate byte by byte to utf-8.
    """
    if ns == 0 or not self.convert_text or self.encoding is None:
        # Nothing to decode: string cells stay raw bytes.
        return const.string_mode_object, None
    if not (using_string_dtype() and HAS_PYARROW):
        return const.string_mode_object, None
    if StringDtype(na_value=np.nan).storage != "pyarrow":
        # mode.string_storage is pinned to "python"; building an Arrow
        # array here would only have to be converted back.
        return const.string_mode_object, None

    try:
        canonical = codecs.lookup(self.encoding).name
    except LookupError:
        # Leave the error to the per-cell decode, which words it better.
        return const.string_mode_object, None
    if canonical == "utf-8":
        return const.string_mode_utf8, None
    table = _utf8_translation_table(canonical)
    if table is None:
        # Multi-byte encoding (shift_jis, big5, ...): no per-byte mapping.
        return const.string_mode_object, None
    return const.string_mode_table, table

def _read_next_page(self):
    done = self._read_page_data()
    if done:
        return True

    self._read_page_header()
    if self._current_page_type in const.page_meta_types:
        self._process_page_metadata()

    if self._current_page_type not in [
        *const.page_meta_types,
        const.page_data_type,
        const.page_mix_type,
    ]:
        return self._read_next_page()

    return False

def _chunk_to_dataframe(self) -> DataFrame:
    n = self._current_row_in_chunk_index
    m = self._current_row_in_file_index
    ix = range(m - n, m)
    rslt = {}

    js, jb = 0, 0
    infer_string = using_string_dtype()
    for j in range(self.column_count):
        name = self.column_names[j]

        if self._column_types[j] == b"d":
            col_arr = self._byte_chunk[jb, :].view(dtype=self.byte_order + "d")
            rslt[name] = pd.Series(col_arr, dtype=np.float64, index=ix, copy=False)
            convert_type = self._column_convert_types[j]
            if convert_type is not None:
                rslt[name] = _convert_datetimes(rslt[name], convert_type)
            jb += 1
        elif self._column_types[j] == b"s":
            if self._str_mode != const.string_mode_object:
                rslt[name] = pd.Series(
                    self._string_column(js), index=ix, copy=False
                )
            else:
                rslt[name] = pd.Series(
                    self._string_chunk[js, :], index=ix, copy=False
                )
                if self.convert_text and (self.encoding is not None):
                    rslt[name] = self._decode_string(rslt[name].str)
                    if infer_string:
                        rslt[name] = rslt[name].astype("str")

            js += 1
        else:
            self.close()
            raise ValueError(f"unknown column type {self._column_types[j]!r}")

    df = DataFrame(rslt, columns=self.column_names, index=ix, copy=False)
    return df

def _convert_header_text(self, b: bytes) -> str | bytes:
    if self.convert_header_text:
        if not b.isascii():
            # latin-1 and the file's own encoding disagree only here
            self._non_ascii_header_text = True
        return self._decode_string(b)
    else:
        return b

def _initialize_index_label(self, index_label: IndexLabel | None) -> IndexLabel:
    if index_label is not False:
        if index_label is None:
            return self._get_index_label_from_obj()
        elif not isinstance(index_label, (list, tuple, np.ndarray, ABCIndex)):
            # given a string for a DF with Index
            return [index_label]
    return index_label

def _initialize_columns(
    self, cols: Iterable[Hashable] | None
) -> npt.NDArray[np.object_]:
    # validate mi options
    if self.has_mi_columns:
        if cols is not None:
            msg = "cannot specify cols with a MultiIndex on the columns"
            raise TypeError(msg)

    if cols is not None:
        if isinstance(cols, ABCIndex):
            cols = cols._get_values_for_csv(**self._number_format)
        else:
            cols = list(cols)
        self.obj = self.obj.loc[:, cols]

    # update columns to include possible multiplicity of dupes
    # and make sure cols is just a list of labels
    new_cols = self.obj.columns
    return new_cols._get_values_for_csv(**self._number_format)

def data_index(self) -> Index:
    data_index = self.obj.index
    if (
        isinstance(data_index, (ABCDatetimeIndex, ABCPeriodIndex))
        and self.date_format is not None
    ):
        data_index = Index(
            [x.strftime(self.date_format) if notna(x) else "" for x in data_index]
        )
    elif isinstance(data_index, ABCMultiIndex):
        data_index = data_index.remove_unused_levels()
    return data_index

def write_cols(self) -> SequenceNotStr[Hashable]:
    if self._has_aliases:
        assert not isinstance(self.header, bool)
        if len(self.header) != len(self.cols):
            raise ValueError(
                f"Writing {len(self.cols)} cols but got {len(self.header)} aliases"
            )
        return self.header
    else:
        # self.cols is an ndarray derived from Index._get_values_for_csv,
        #  so its entries are strings, i.e. hashable
        return cast("SequenceNotStr[Hashable]", self.cols)

def encoded_labels(self) -> list[Hashable]:
    encoded_labels: list[Hashable] = []

    if self.index and self.index_label:
        assert isinstance(self.index_label, Sequence)
        encoded_labels = list(self.index_label)

    if not self.has_mi_columns or self._has_aliases:
        encoded_labels += list(self.write_cols)

    return encoded_labels

def _save_header(self) -> None:
    if not self.has_mi_columns or self._has_aliases:
        self.writer.writerow(self.encoded_labels)
    else:
        for row in self._generate_multiindex_header_rows():
            self.writer.writerow(row)

def _save_body(self) -> None:
    nrows = len(self.data_index)
    chunks = (nrows // self.chunksize) + 1
    for i in range(chunks):
        start_i = i * self.chunksize
        end_i = min(start_i + self.chunksize, nrows)
        if start_i >= end_i:
            break
        self._save_chunk(start_i, end_i)

def size_qualifier(self) -> str:
    size_qualifier = ""
    if self.memory_usage:
        if self.memory_usage != "deep":
            # size_qualifier is just a best effort; not guaranteed to catch
            # all cases (e.g., it misses categorical data even with object
            # categories)
            if (
                "object" in self.dtype_counts
                or self.data.index._is_memory_usage_qualified
            ):
                size_qualifier = "+"
    return size_qualifier

def _initialize_show_counts(self, show_counts: bool | None) -> bool:
    if show_counts is None:
        return bool(not self.exceeds_info_cols and not self.exceeds_info_rows)
    else:
        return show_counts

def _create_table_builder(self) -> _DataFrameTableBuilder:
    """
    Create instance of table builder based on verbosity and display settings.
    """
    if self.verbose:
        return _DataFrameTableBuilderVerbose(
            info=self.info,
            with_counts=self.show_counts,
        )
    elif self.verbose is False:  # specifically set to False, not necessarily None
        return _DataFrameTableBuilderNonVerbose(info=self.info)
    elif self.exceeds_info_cols:
        return _DataFrameTableBuilderNonVerbose(info=self.info)
    else:
        return _DataFrameTableBuilderVerbose(
            info=self.info,
            with_counts=self.show_counts,

def _create_table_builder(self) -> _SeriesTableBuilder:
    """
    Create instance of table builder based on verbosity.
    """
    if self.verbose or self.verbose is None:
        return _SeriesTableBuilderVerbose(
            info=self.info,
            with_counts=self.show_counts,
        )
    else:
        return _SeriesTableBuilderNonVerbose(info=self.info)

def add_body_lines(self) -> None:
    for row in self.strrows:
        body_line = self.SPACING.join(
            [
                self._ljust(col, gross_colwidth)
                for col, gross_colwidth in zip(
                    row, self.gross_column_widths, strict=True
                )
            ]
        )
        self._lines.append(body_line)

def _get_string_representation(self) -> str:
    if self.fmt.frame.empty:
        return self._empty_info_line

    strcols = self._get_strcols()

    if self.line_width is None:
        # no need to wrap around just print the whole frame
        return self.adj.adjoin(1, *strcols)

    if self._need_to_wrap_around:
        return self._join_multiline(strcols)

    return self._fit_strcols_to_terminal_width(strcols)

def _insert_dot_separators(self, strcols: list[list[str]]) -> list[list[str]]:
    index_length = len(strcols[0])

    if self.fmt.is_truncated_horizontally:
        strcols = self._insert_dot_separator_horizontal(strcols, index_length)

    if self.fmt.is_truncated_vertically:
        strcols = self._insert_dot_separator_vertical(strcols, index_length)

    return strcols

def _insert_dot_separator_vertical(
    self, strcols: list[list[str]], index_length: int
) -> list[list[str]]:
    n_header_rows = index_length - len(self.fmt.tr_frame)
    row_num = self.fmt.tr_row_num
    for ix, col in enumerate(strcols):
        cwidth = self.adj.len(col[row_num])

        if self.fmt.is_truncated_horizontally:
            is_dot_col = ix == self._adjusted_tr_col_num
        else:
            is_dot_col = False

        if cwidth > 3 or is_dot_col:
            dots = "..."
        else:
            dots = ".."

        if ix == 0 and self.fmt.index:
            dot_mode = "left"
        elif is_dot_col:
            cwidth = 4
            dot_mode = "right"
        else:
            dot_mode = "right"

        dot_str = self.adj.justify([dots], cwidth, mode=dot_mode)[0]
        col.insert(row_num + n_header_rows, dot_str)
    return strcols

def _join_multiline(self, strcols_input: Iterable[list[str]]) -> str:
    lwidth = self.line_width
    adjoin_width = 1
    strcols = list(strcols_input)

    if self.fmt.index:
        idx = strcols.pop(0)
        lwidth -= np.array([self.adj.len(x) for x in idx]).max() + adjoin_width

    col_widths = [
        np.array([self.adj.len(x) for x in col]).max() if len(col) > 0 else 0
        for col in strcols
    ]

    assert lwidth is not None
    col_bins = _binify(col_widths, lwidth)
    nbins = len(col_bins)

    str_lst = []
    start = 0
    for i, end in enumerate(col_bins):
        row = strcols[start:end]
        if self.fmt.index:
            row.insert(0, idx)
        if nbins > 1:
            nrows = len(row[-1])
            if end <= len(strcols) and i < nbins - 1:
                row.append([" \\"] + ["  "] * (nrows - 1))
            else:
                row.append([" "] * nrows)
        str_lst.append(self.adj.adjoin(adjoin_width, *row))
        start = end
    return "\n\n".join(str_lst)

def in_interactive_session() -> bool:
    """
    Check if we're running in an interactive shell.

    Returns
    -------
    bool
        True if running under python/ipython interactive shell.
    """
    from pandas._config.config import _global_config as config

    def check_main() -> bool:
        try:
            import __main__ as main
        except ModuleNotFoundError:
            return config["mode"]["sim_interactive"]
        return not hasattr(main, "__file__") or config["mode"]["sim_interactive"]

    try:
        # error: Name '__IPYTHON__' is not defined
        return __IPYTHON__ or check_main()  # type: ignore[name-defined]
    except NameError:
        return check_main()

def to_string(self) -> str:
    lines = self.render()
    if any(isinstance(x, str) for x in lines):
        lines = [str(x) for x in lines]
    return "\n".join(lines)

def _write_cell(
    self, s: Any, kind: str = "td", indent: int = 0, tags: str | None = None
) -> None:
    if tags is not None:
        start_tag = f"<{kind} {tags}>"
    else:
        start_tag = f"<{kind}>"

    if self.escape:
        # escape & first to prevent double escaping of &
        esc = {"&": r"&amp;", "<": r"&lt;", ">": r"&gt;"}
    else:
        esc = {}

    rs = pprint_thing(s, escape_chars=esc).strip()
    # replace spaces between strings with non-breaking spaces
    rs = rs.replace("  ", "&nbsp;&nbsp;")

    if self.render_links and is_url(rs):
        rs_unescaped = pprint_thing(s, escape_chars={}).strip()
        start_tag += f'<a href="{rs_unescaped}" target="_blank">'
        end_a = "</a>"
    else:
        end_a = ""

    self.write(f"{start_tag}{rs}{end_a}</{kind}>", indent)

def write_tr(
    self,
    line: Iterable[Hashable],
    indent: int = 0,
    indent_delta: int = 0,
    header: bool = False,
    align: str | None = None,
    tags: dict[int, str] | None = None,
    nindex_levels: int = 0,
) -> None:
    if tags is None:
        tags = {}

    if align is None:
        self.write("<tr>", indent)
    else:
        self.write(f'<tr style="text-align: {align};">', indent)
    indent += indent_delta

    for i, s in enumerate(line):
        val_tag = tags.get(i, None)
        if header or (self.bold_rows and i < nindex_levels):
            self.write_th(s, indent=indent, header=header, tags=val_tag)
        else:
            self.write_td(s, indent, tags=val_tag)

    indent -= indent_delta
    self.write("</tr>", indent)

def _write_table(self, indent: int = 0) -> None:
    _classes = ["dataframe"]  # Default class.
    use_mathjax = config["display"]["html"]["use_mathjax"]
    if not use_mathjax:
        _classes.append("tex2jax_ignore")
        _classes.append("mathjax_ignore")
    if self.classes is not None:
        if isinstance(self.classes, str):
            self.classes = self.classes.split()
        if not isinstance(self.classes, (list, tuple)):
            raise TypeError(
                "classes must be a string, list, "
                f"or tuple, not {type(self.classes)}"
            )
        _classes.extend(self.classes)

    if self.table_id is None:
        id_section = ""
    else:
        id_section = f' id="{self.table_id}"'

    if self.border is None:
        border_attr = ""
    else:
        border_attr = f' border="{self.border}"'

    self.write(
        f'<table{border_attr} class="{" ".join(_classes)}"{id_section}>',
        indent,
    )

    if self.fmt.header or self.show_row_idx_names:
        self._write_header(indent + self.indent_delta)

    self._write_body(indent + self.indent_delta)

    self.write("</table>", indent)

def _write_row_header(self, indent: int) -> None:
    is_truncated_horizontally = self.fmt.is_truncated_horizontally
    row = [format_name(x) for x in self.frame.index.names] + [""] * (
        self.ncols + (1 if is_truncated_horizontally else 0)
    )
    self.write_tr(row, indent, self.indent_delta, header=True)

def _write_header(self, indent: int) -> None:
    self.write("<thead>", indent)

    if self.fmt.header:
        self._write_col_header(indent + self.indent_delta)

    if self.show_row_idx_names:
        self._write_row_header(indent + self.indent_delta)

    self.write("</thead>", indent)

def _write_body(self, indent: int) -> None:
    self.write("<tbody>", indent)
    fmt_values = self._get_formatted_values()

    # write values
    if self.fmt.index and isinstance(self.frame.index, MultiIndex):
        self._write_hierarchical_rows(fmt_values, indent + self.indent_delta)
    else:
        self._write_regular_rows(fmt_values, indent + self.indent_delta)

    self.write("</tbody>", indent)

def write_style(self) -> None:
    # We use the "scoped" attribute here so that the desired
    # style properties for the data frame are not then applied
    # throughout the entire notebook.
    template_first = """\
        <style scoped>"""
    template_last = """\
        </style>"""
    template_select = """\
            .dataframe %s {
                %s: %s;
            }"""
    element_props = [
        ("tbody tr th:only-of-type", "vertical-align", "middle"),
        ("tbody tr th", "vertical-align", "top"),
    ]
    if isinstance(self.columns, MultiIndex):
        element_props.append(("thead tr th", "text-align", "left"))
        if self.show_row_idx_names:
            element_props.append(
                ("thead tr:last-of-type th", "text-align", "right")
            )
    else:
        element_props.append(("thead th", "text-align", "right"))
    template_mid = "\n\n".join(template_select % t for t in element_props)
    template = dedent(f"{template_first}\n{template_mid}\n{template_last}")
    self.write(template)

def _update_initial(
    self,
    props: dict[str, str],
    inherited: dict[str, str],
) -> dict[str, str]:
    # 1. resolve inherited, initial
    for prop, val in inherited.items():
        if prop not in props:
            props[prop] = val

    new_props = props.copy()
    for prop, val in props.items():
        if val == "inherit":
            val = inherited.get(prop, "initial")

        if val in ("initial", None):
            # we do not define a complete initial stylesheet
            del new_props[prop]
        else:
            new_props[prop] = val
    return new_props

def _update_other_units(self, props: dict[str, str]) -> dict[str, str]:
    font_size = self._get_font_size(props)
    # 3. TODO: resolve other font-relative units
    for side in self.SIDES:
        prop = f"border-{side}-width"
        if prop in props:
            props[prop] = self.size_to_pt(
                props[prop],
                em_pt=font_size,
                conversions=self.BORDER_WIDTH_RATIOS,
            )

        for prop in [f"margin-{side}", f"padding-{side}"]:
            if prop in props:
                # TODO: support %
                props[prop] = self.size_to_pt(
                    props[prop],
                    em_pt=font_size,
                    conversions=self.MARGIN_RATIOS,
                )
    return props

def size_to_pt(
    self,
    in_val: str,
    em_pt: float | None = None,
    conversions: dict[str, tuple[str, float]] = UNIT_RATIOS,
) -> str:
    def _error() -> str:
        warnings.warn(
            f"Unhandled size: {in_val!r}",
            CSSWarning,
            stacklevel=find_stack_level(),
        )
        return self.size_to_pt("1!!default", conversions=conversions)

    match = re.match(r"^(\S*?)([a-zA-Z%!].*)", in_val)
    if match is None:
        return _error()

    val, unit = match.groups()
    if val == "":
        # hack for 'large' etc.
        val = 1
    else:
        try:
            val = float(val)
        except ValueError:
            return _error()

    while unit != "pt":
        if unit == "em":
            if em_pt is None:
                unit = "rem"
            else:
                val *= em_pt
                unit = "pt"
            continue

        try:
            unit, mul = conversions[unit]
        except KeyError:
            return _error()
        val *= mul

    val = round(val, 5)
    if int(val) == val:
        size_fmt = f"{int(val):d}pt"
    else:
        size_fmt = f"{val:f}pt"
    return size_fmt

def atomize(
    self, declarations: Iterable[tuple[str, str]]
) -> Generator[tuple[str, str]]:
    for prop, value in declarations:
        prop = prop.lower()
        value = _lowercase_css_values(value)
        if prop in self.CSS_EXPANSIONS:
            expand = self.CSS_EXPANSIONS[prop]
            yield from expand(self, prop, value)
        else:
            yield prop, value

def _handle_indexes(self) -> None:
    """
    Handle indexes.

    This method will add indexes into attr_cols or elem_cols.
    """

    if not self.index:
        return

    first_key = next(iter(self.frame_dicts))
    indexes: list[str] = [
        x for x in self.frame_dicts[first_key].keys() if x not in self.orig_cols
    ]

    if self.attr_cols:
        self.attr_cols = indexes + self.attr_cols

    if self.elem_cols:
        self.elem_cols = indexes + self.elem_cols

def _other_namespaces(self) -> dict[str, str]:
    """
    Define other namespaces.

    This method will build dictionary of namespaces attributes
    for root element, conditionally with optional namespaces and
    prefix.
    """

    nmsp_dict: dict[str, str] = {}
    if self.namespaces:
        nmsp_dict = {
            f"xmlns{p if p == '' else f':{p}'}": n
            for p, n in self.namespaces.items()
            if n != self.prefix_uri[1:-1]
        }

    return nmsp_dict

def _build_attribs(self, d: dict[str, Any], elem_row: Any) -> Any:
    """
    Create attributes of row.

    This method adds attributes using attr_cols to row element and
    works with tuples for multindex or hierarchical columns.
    """

    if not self.attr_cols:
        return elem_row

    for col in self.attr_cols:
        attr_name = self._get_flat_col_name(col)
        try:
            if not isna(d[col]):
                elem_row.attrib[attr_name] = str(d[col])
        except KeyError as err:
            raise KeyError(f"no valid column, {col}") from err
    return elem_row

def _get_flat_col_name(self, col: str | tuple[Hashable, ...]) -> str:
    flat_col = col
    if isinstance(col, tuple):
        flat_col = (
            "".join([str(c) for c in col]).strip()
            if "" in col
            else "_".join([str(c) for c in col]).strip()
        )
    return f"{self.prefix_uri}{flat_col}"

def _build_elems(self, d: dict[str, Any], elem_row: Any) -> None:
    """
    Create child elements of row.

    This method adds child elements using elem_cols to row element and
    works with tuples for multindex or hierarchical columns.
    """
    sub_element_cls = self._sub_element_cls

    if not self.elem_cols:
        return

    for col in self.elem_cols:
        elem_name = self._get_flat_col_name(col)
        try:
            val = None if isna(d[col]) or d[col] == "" else str(d[col])
            sub_element_cls(elem_row, elem_name).text = val
        except KeyError as err:
            raise KeyError(f"no valid column, {col}") from err

def _build_tree(self) -> bytes:
    from xml.etree.ElementTree import (
        Element,
        SubElement,
        tostring,
    )

    self.root = Element(
        f"{self.prefix_uri}{self.root_name}", attrib=self._other_namespaces()
    )

    for d in self.frame_dicts.values():
        elem_row = SubElement(self.root, f"{self.prefix_uri}{self.row_name}")

        if not self.attr_cols and not self.elem_cols:
            self.elem_cols = list(d.keys())
            self._build_elems(d, elem_row)

        else:
            elem_row = self._build_attribs(d, elem_row)
            self._build_elems(d, elem_row)

    self.out_xml = tostring(
        self.root,
        method="xml",
        encoding=self.encoding,
        xml_declaration=self.xml_declaration,
    )

    if self.pretty_print:
        self.out_xml = self._prettify_tree()

    if self.stylesheet is not None:
        raise ValueError(
            "To use stylesheet, you need lxml installed and selected as parser."
        )

    return self.out_xml

def _get_prefix_uri(self) -> str:
    from xml.etree.ElementTree import register_namespace

    uri = ""
    if self.namespaces:
        for p, n in self.namespaces.items():
            if isinstance(p, str) and isinstance(n, str):
                register_namespace(p, n)
        if self.prefix:
            try:
                uri = f"{{{self.namespaces[self.prefix]}}}"
            except KeyError as err:
                raise KeyError(
                    f"{self.prefix} is not included in namespaces"
                ) from err
        elif "" in self.namespaces:
            uri = f"{{{self.namespaces['']}}}"
        else:
            uri = ""

    return uri

def _get_prefix_uri(self) -> str:
    uri = ""
    if self.namespaces:
        if self.prefix:
            try:
                uri = f"{{{self.namespaces[self.prefix]}}}"
            except KeyError as err:
                raise KeyError(
                    f"{self.prefix} is not included in namespaces"
                ) from err
        elif "" in self.namespaces:
            uri = f"{{{self.namespaces['']}}}"
        else:
            uri = ""

    return uri

def _get_buffer(
    buf: FilePath | WriteBuffer[str] | None, encoding: str | None = None
) -> Generator[WriteBuffer[str]] | Generator[StringIO]:
    """
    Context manager to open, yield and close buffer for filenames or Path-like
    objects, otherwise yield buf unchanged.
    """
    if buf is not None:
        buf = stringify_path(buf)
    else:
        buf = StringIO()

    if encoding is None:
        encoding = "utf-8"
    elif not isinstance(buf, str):
        raise ValueError("buf is not a file name and encoding is specified.")

    if hasattr(buf, "write"):
        # Incompatible types in "yield" (actual type "Union[str, WriteBuffer[str],
        # StringIO]", expected type "Union[WriteBuffer[str], StringIO]")
        yield buf  # type: ignore[misc]
    elif isinstance(buf, str):
        check_parent_directory(str(buf))
        with open(buf, "w", encoding=encoding, newline="") as f:
            # GH#30034 open instead of codecs.open prevents a file leak
            #  if we have an invalid encoding argument.
            # newline="" is needed to roundtrip correctly on
            #  windows test_to_latex_filename
            yield f
    else:
        raise TypeError("buf is not a file name and it has no write method")

def format_name(name: Hashable) -> str:
    """
    Render an Index or Series name for display.

    Float names follow ``display.precision`` like float values do (GH#25917).
    """
    if name is None:
        return ""
    if lib.is_float(name) and not isna(name):
        return format_array(np.array([name]), None, leading_space=False)[0]
    return printing.pprint_thing(name, escape_chars=("\t", "\r", "\n"))

def _format_datetime64_dateonly(
    x: NaTType | Timestamp,
    na_rep: str = "NaT",
    date_format: str | None = None,
) -> str:
    if isinstance(x, NaTType):
        return na_rep

    if date_format:
        return x.strftime(date_format)
    else:
        # Timestamp._date_repr relies on string formatting (faster than strftime)
        return x._date_repr

def get_format_timedelta64(
    values: TimedeltaArray,
    na_rep: str | float = "NaT",
    box: bool = False,
) -> Callable:
    """
    Return a formatter function for a range of timedeltas.
    These will all have the same format argument

    If box, then show the return in quotes
    """
    if values._is_dates_only:
        format = None
    else:
        i8 = values.asi8
        vals = i8[i8 != iNaT]
        if vals.size == 0 or not (vals % periods_per_second(values._creso)).any():
            format = "long"
        elif NpyDatetimeUnit.NPY_FR_ns.value == values._creso and (vals % 1_000).any():
            format = "all"  # nanosecond precision → 9 digits
        else:
            format = "us"  # microsecond precision → 6 digits

    def _formatter(x):
        if x is None or (is_scalar(x) and isna(x)):
            return na_rep

        if not isinstance(x, Timedelta):
            x = Timedelta(x)

        # Timedelta._repr_base uses string formatting (faster than strftime)
        result = x._repr_base(format=format)
        if box:
            result = f"'{result}'"
        return result

    return _formatter

def _make_fixed_width(
    strings: list[str],
    justify: str = "right",
    minimum: int | None = None,
    adj: printing._TextAdjustment | None = None,
) -> tuple[list[str], int]:
    if adj is None:
        adjustment = printing.get_adjustment()
    else:
        adjustment = adj

    if len(strings) == 0 or justify == "all":
        max_len = max(adjustment.len(x) for x in strings) if strings else 0
        return strings, max_len

    max_len = max(adjustment.len(x) for x in strings)

    if minimum is not None:
        max_len = max(minimum, max_len)

    conf_max = config["display"]["max_colwidth"]
    if conf_max is not None and max_len > conf_max:
        max_len = conf_max

    if conf_max is not None:
        # When the column is too narrow to hold any text alongside the "..."
        # placeholder, show as much of the placeholder as fits (GH#16097).
        keep = max(max_len - 3, 0)
        placeholder = "..."[: max_len - keep]
        strings = [
            x[:keep] + placeholder if adjustment.len(x) > max_len else x
            for x in strings
        ]

    result = adjustment.justify(strings, max_len, mode=justify)
    return result, max_len

def _trim_zeros_float(
    str_floats: ArrayLike | list[str], decimal: str = "."
) -> list[str]:
    """
    Trims the maximum number of trailing zeros equally from
    all numbers containing decimals, leaving just one if
    necessary.
    """
    if decimal != ".":
        number_regex = re.compile(rf"^\s*[+-]?[0-9]+\{decimal}[0-9]*$")
    else:
        number_regex = _NUMBER_WITH_DECIMAL_RE

    # Identify which elements are decimal numbers once, up front
    is_number = [number_regex.match(x) is not None for x in str_floats]

    if not any(is_number):
        return list(str_floats)

    trimmed = list(str_floats)

    # Trim trailing zeros from all decimal numbers equally
    while True:
        # Check if all decimal numbers end in "0"
        if not all(
            x.endswith("0")
            for x, is_num in zip(trimmed, is_number, strict=True)
            if is_num
        ):
            break
        trimmed = [
            x[:-1] if is_num else x
            for x, is_num in zip(trimmed, is_number, strict=True)
        ]

    # Leave one 0 after the decimal point if needed
    result = [
        x + "0" if is_num and x.endswith(decimal) else x
        for x, is_num in zip(trimmed, is_number, strict=True)
    ]
    return result

def _get_footer(self) -> str:
    name = self.series.name
    footer = ""

    index = self.series.index
    if (
        isinstance(index, (DatetimeIndex, PeriodIndex, TimedeltaIndex))
        and index.freq is not None
    ):
        footer += f"Freq: {index.freqstr}"

    if self.name is not False and name is not None:
        if footer:
            footer += ", "

        footer += f"Name: {format_name(name)}"

    if self.length is True or (
        self.length == "truncate" and self.is_truncated_vertically
    ):
        if footer:
            footer += ", "
        footer += f"Length: {len(self.series)}"

    if self.dtype is not False and self.dtype is not None:
        dtype_name = getattr(self.tr_series.dtype, "name", None)
        if dtype_name:
            if footer:
                footer += ", "
            footer += f"dtype: {printing.pprint_thing(dtype_name)}"

    # level infos are added to the end and in a new line, like it is done
    # for Categoricals
    if isinstance(self.tr_series.dtype, CategoricalDtype):
        level_info = self.tr_series._values._get_repr_footer()
        if footer:
            footer += "\n"
        footer += level_info

    return str(footer)

def to_string(self) -> str:
    series = self.tr_series
    footer = self._get_footer()

    if len(series) == 0:
        return f"{type(self.series).__name__}([], {footer})"

    index = series.index
    have_header = _has_names(index)
    if isinstance(index, MultiIndex):
        fmt_index = index._format_multi(include_names=True, sparsify=None)
        adj = printing.get_adjustment()
        fmt_index = adj.adjoin(2, *fmt_index).split("\n")
    else:
        fmt_index = index._format_flat(include_name=True)
    fmt_values = self._get_formatted_values()

    if self.is_truncated_vertically:
        n_header_rows = 0
        row_num = self.tr_row_num
        row_num = cast("int", row_num)
        width = self.adj.len(fmt_values[row_num - 1])
        if width > 3:
            dot_str = "..."
        else:
            dot_str = ".."
        # Series uses mode=center because it has single value columns
        # DataFrame uses mode=left
        dot_str = self.adj.justify([dot_str], width, mode="center")[0]
        fmt_values.insert(row_num + n_header_rows, dot_str)
        fmt_index.insert(row_num + 1, "")

    if self.index:
        result = self.adj.adjoin(3, *[fmt_index[1:], fmt_values])
    else:
        result = self.adj.adjoin(3, fmt_values)

    if self.header and have_header:
        result = fmt_index[0] + "\n" + result

    if footer:
        result += "\n" + footer

    return str("".join(result))

def _initialize_formatters(
    self, formatters: FormattersType | None
) -> FormattersType:
    if formatters is None:
        return {}
    elif len(self.frame.columns) == len(formatters) or isinstance(formatters, dict):
        return formatters
    else:
        raise ValueError(
            f"Formatters length({len(formatters)}) should match "
            f"DataFrame number of columns({len(self.frame.columns)})"

def _initialize_colspace(self, col_space: ColspaceArgType | None) -> ColspaceType:
    result: ColspaceType

    if col_space is None:
        result = {}
    elif isinstance(col_space, (int, str)):
        result = {"": col_space}
        result.update(dict.fromkeys(self.frame.columns, col_space))
    elif isinstance(col_space, Mapping):
        for column in col_space.keys():
            if column not in self.frame.columns and column != "":
                raise ValueError(
                    f"Col_space is defined for an unknown column: {column}"
                )
        result = col_space
    else:
        if len(self.frame.columns) != len(col_space):
            raise ValueError(
                f"Col_space length({len(col_space)}) should match "
                f"DataFrame number of columns({len(self.frame.columns)})"
            )
        result = dict(zip(self.frame.columns, col_space, strict=True))
    return result

def _calc_max_cols_fitted(self) -> int | None:
    """Number of columns fitting the screen."""
    if not self._is_in_terminal():
        return self.max_cols

    width, _ = get_terminal_size()
    if self._is_screen_narrow(width):
        return width
    else:
        return self.max_cols

def _calc_max_rows_fitted(self) -> int | None:
    """Number of rows with data fitting the screen."""
    max_rows: int | None

    if self._is_in_terminal():
        _, height = get_terminal_size()
        if self.max_rows == 0:
            # rows available to fill with actual data
            return height - self._get_number_of_auxiliary_rows()

        if self._is_screen_short(height):
            max_rows = height
        else:
            max_rows = self.max_rows
    else:
        max_rows = self.max_rows

    return self._adjust_max_rows(max_rows)

def _get_number_of_auxiliary_rows(self) -> int:
    """Get number of rows occupied by prompt, dots and dimension info."""
    dot_row = 1
    prompt_row = 1
    num_rows = dot_row + prompt_row

    if self.show_dimensions:
        num_rows += len(self.dimensions_info.splitlines())

    if self.header:
        num_rows += 1

    return num_rows

def truncate(self) -> None:
    """
    Check whether the frame should be truncated. If so, slice the frame up.
    """
    if self.is_truncated_horizontally:
        self._truncate_horizontally()

    if self.is_truncated_vertically:
        self._truncate_vertically()

def _get_strcols_without_index(self) -> list[list[str]]:
    strcols: list[list[str]] = []

    if not is_list_like(self.header) and not self.header:
        for i, c in enumerate(self.tr_frame):
            fmt_values = self.format_col(i)
            fmt_values, _ = _make_fixed_width(
                strings=fmt_values,
                justify=self.justify,
                minimum=int(self.col_space.get(c, 0)),
                adj=self.adj,
            )
            strcols.append(fmt_values)
        return strcols

    if is_list_like(self.header):
        # cast here since can't be bool if is_list_like
        self.header = cast("list[str]", self.header)
        if len(self.header) != len(self.columns):
            raise ValueError(
                f"Writing {len(self.columns)} cols "
                f"but got {len(self.header)} aliases"
            )
        str_columns = [[label] for label in self.header]
    else:
        str_columns = self._get_formatted_column_labels(self.tr_frame)

    if self.show_row_idx_names:
        for x in str_columns:
            x.append("")

    for i, c in enumerate(self.tr_frame):
        cheader = str_columns[i]
        header_colwidth = max(
            int(self.col_space.get(c, 0)), *(self.adj.len(x) for x in cheader)
        )
        fmt_values = self.format_col(i)
        fmt_values, max_len = _make_fixed_width(
            fmt_values, self.justify, minimum=header_colwidth, adj=self.adj
        )
        max_len = max(max_len, header_colwidth)
        cheader = self.adj.justify(cheader, max_len, mode=self.justify)
        strcols.append(cheader + fmt_values)

    return strcols

def _get_formatter(self, i: str | int) -> Callable | None:
    if isinstance(self.formatters, (list, tuple)):
        if is_integer(i):
            i = cast("int", i)
            return self.formatters[i]
        else:
            return None
    else:
        if is_integer(i):
            i = self.tr_frame.columns[i]
        return self.formatters.get(i, None)

def _get_formatted_column_labels(self, frame: DataFrame) -> list[list[str]]:
    from pandas.core.indexes.multi import sparsify_labels

    columns = frame.columns

    if isinstance(columns, MultiIndex):
        fmt_columns = columns._format_multi(sparsify=False, include_names=False)
        if self.sparsify and len(fmt_columns):
            fmt_columns = sparsify_labels(fmt_columns)

        str_columns = [list(x) for x in zip(*fmt_columns, strict=True)]
    else:
        fmt_columns = columns._format_flat(include_name=False)
        str_columns = [
            [
                " " + x
                if not self._get_formatter(i) and is_numeric_dtype(dtype)
                else x
            ]
            for i, (x, dtype) in enumerate(
                zip(fmt_columns, self.frame.dtypes, strict=False)
            )
        ]
    return str_columns

def _get_formatted_index(self, frame: DataFrame) -> list[str]:
    # Note: this is only used by to_string() and to_latex(), not by
    # to_html(). so safe to cast col_space here.
    col_space = {k: cast("int", v) for k, v in self.col_space.items()}
    index = frame.index
    columns = frame.columns
    fmt = self._get_formatter("__index__")

    if isinstance(index, MultiIndex):
        fmt_index = index._format_multi(
            sparsify=self.sparsify,
            include_names=self.show_row_idx_names,
            formatter=fmt,
        )
    else:
        fmt_index = [
            index._format_flat(include_name=self.show_row_idx_names, formatter=fmt)
        ]

    fmt_index = [
        tuple(
            _make_fixed_width(
                list(x), justify="left", minimum=col_space.get("", 0), adj=self.adj
            )[0]
        )
        for x in fmt_index
    ]

    adjoined = self.adj.adjoin(1, *fmt_index).split("\n")

    # empty space for columns
    if self.show_col_idx_names:
        col_header = [format_name(x) for x in self._get_column_name_list()]
    else:
        col_header = [""] * columns.nlevels

    if self.header:
        return col_header + adjoined
    else:
        return adjoined

def _validate_float_format(
    self, fmt: FloatFormatType | None
) -> FloatFormatType | None:
    """
    Validates and processes the float_format argument.
    Converts new-style format strings to callables.
    """
    if fmt is None or callable(fmt):
        return fmt

    if isinstance(fmt, str):
        if "%" in fmt:
            # Keeps old-style format strings as they are (C code handles them)
            return fmt
        else:
            try:
                _ = fmt.format(1.0)  # Test with an arbitrary float
                return fmt.format
            except (ValueError, KeyError, IndexError) as e:
                raise ValueError(f"Invalid new-style format string {fmt!r}") from e

    raise ValueError("float_format must be a string or callable")

def __init__(self, *args, **kwargs) -> None:
    super().__init__(*args, **kwargs)

    # float_format is expected to be a string
    # formatter should be used to pass a function
    if self.float_format is not None and self.formatter is None:
        # GH21625, GH22270
        self.fixed_width = False
        if callable(self.float_format):
            self.formatter = self.float_format
            self.float_format = None

def _value_formatter(
    self,
    float_format: FloatFormatType | None = None,
    threshold: float | None = None,
) -> Callable:
    """Returns a function to be applied on each value to format it"""
    # the float_format parameter supersedes self.float_format
    if float_format is None:
        float_format = self.float_format

    # we are going to compose different functions, to first convert to
    # a string, then replace the decimal symbol, and finally chop according
    # to the threshold

    # when there is no float_format, we use str instead of '%g'
    # because str(0.0) = '0.0' while '%g' % 0.0 = '0'
    if float_format:

        def base_formatter(v):  # pyright: ignore[reportRedeclaration]
            assert float_format is not None  # for mypy
            # error: "str" not callable
            # error: Unexpected keyword argument "value" for "__call__" of
            # "EngFormatter"
            return (
                float_format(value=v)  # type: ignore[operator,call-arg]
                if notna(v)
                else self.na_rep
            )

    else:

        def base_formatter(v):
            return str(v) if notna(v) else self.na_rep

    if self.decimal != ".":

        def decimal_formatter(v):
            return base_formatter(v).replace(".", self.decimal, 1)

    else:
        decimal_formatter = base_formatter

    if threshold is None:
        return decimal_formatter

    def formatter(value):
        if notna(value):
            if abs(value) > threshold:
                return decimal_formatter(value)
            else:
                return decimal_formatter(0.0)
        else:
            return self.na_rep

    return formatter

def _format_strings(self) -> list[str]:
    if self.leading_space is False:
        formatter_str = lambda x: f"{x:d}"
    else:
        formatter_str = lambda x: f"{x: d}"
    formatter = self.formatter or formatter_str
    fmt_values = [formatter(x) for x in self.values]
    return fmt_values

def _format_strings(self) -> list[str]:
    values = self.values

    if self.formatter is not None:
        return [self.formatter(x) for x in values]

    fmt_values = values._format_native_types(
        na_rep=self.na_rep, date_format=self.date_format
    )
    return fmt_values.tolist()

def _format_strings(self) -> list[str]:
    formatter = self.formatter or get_format_timedelta64(
        self.values, na_rep=self.na_rep, box=False
    )
    return [formatter(x) for x in self.values]

def _highlight_between(
    data: NDFrame,
    props: str,
    left: Scalar | Sequence | np.ndarray | NDFrame | None = None,
    right: Scalar | Sequence | np.ndarray | NDFrame | None = None,
    inclusive: bool | str = True,
) -> np.ndarray:
    """
    Return an array of css props based on condition of data values within given range.
    """
    if np.iterable(left) and not isinstance(left, str):
        left = _validate_apply_axis_arg(left, "left", None, data)

    if np.iterable(right) and not isinstance(right, str):
        right = _validate_apply_axis_arg(right, "right", None, data)

    # get ops with correct boundary attribution
    if inclusive == "both":
        ops = (operator.ge, operator.le)
    elif inclusive == "neither":
        ops = (operator.gt, operator.lt)
    elif inclusive == "left":
        ops = (operator.ge, operator.lt)
    elif inclusive == "right":
        ops = (operator.gt, operator.le)
    else:
        raise ValueError(
            f"'inclusive' values can be 'both', 'left', 'right', or 'neither' "
            f"got {inclusive}"
        )

    g_left = (
        # error: Argument 2 to "ge" has incompatible type "Union[str, float,
        # Period, Timedelta, Interval[Any], datetime64, timedelta64, datetime,
        # Sequence[Any], ndarray[Any, Any], NDFrame]"; expected "Union
        # [SupportsDunderLE, SupportsDunderGE, SupportsDunderGT, SupportsDunderLT]"
        ops[0](data, left)  # type: ignore[arg-type]
        if left is not None
        else np.full(data.shape, True, dtype=bool)
    )
    if isinstance(g_left, (DataFrame, Series)):
        g_left = g_left.where(pd.notna(g_left), False)
    l_right = (
        # error: Argument 2 to "le" has incompatible type "Union[str, float,
        # Period, Timedelta, Interval[Any], datetime64, timedelta64, datetime,
        # Sequence[Any], ndarray[Any, Any], NDFrame]"; expected "Union
        # [SupportsDunderLE, SupportsDunderGE, SupportsDunderGT, SupportsDunderLT]"
        ops[1](data, right)  # type: ignore[arg-type]
        if right is not None
        else np.full(data.shape, True, dtype=bool)
    )
    if isinstance(l_right, (DataFrame, Series)):
        l_right = l_right.where(pd.notna(l_right), False)
    return np.where(g_left & l_right, props, "")

def _apply(
    self,
    func: Callable,
    axis: Axis | None = 0,
    subset: Subset | None = None,
    **kwargs,
) -> Styler:
    subset = slice(None) if subset is None else subset
    subset = non_reducing_slice(subset)
    data = self.data.loc[subset]
    if data.empty:
        result = DataFrame()
    elif axis is None:
        result = func(data, **kwargs)
        if not isinstance(result, DataFrame):
            if not isinstance(result, np.ndarray):
                raise TypeError(
                    f"Function {func!r} must return a DataFrame or ndarray "
                    f"when passed to `Styler.apply` with axis=None"
                )
            if data.shape != result.shape:
                raise ValueError(
                    f"Function {func!r} returned ndarray with wrong shape.\n"
                    f"Result has shape: {result.shape}\n"
                    f"Expected shape: {data.shape}"
                )
            result = DataFrame(result, index=data.index, columns=data.columns)
    else:
        axis = self.data._get_axis_number(axis)
        if axis == 0:
            result = data.apply(func, axis=0, **kwargs)
        else:
            result = data.T.apply(func, axis=0, **kwargs).T  # see GH 42005

    if isinstance(result, Series):
        raise ValueError(
            f"Function {func!r} resulted in the apply method collapsing to a "
            f"Series.\nUsually, this is the result of the function returning a "
            f"single value, instead of list-like."
        )
    msg = (
        f"Function {func!r} created invalid {{0}} labels.\nUsually, this is "
        f"the result of the function returning a "
        f"{'Series' if axis is not None else 'DataFrame'} which contains invalid "
        f"labels, or returning an incorrectly shaped, list-like object which "
        f"cannot be mapped to labels, possibly due to applying the function along "
        f"the wrong axis.\n"
        f"Result {{0}} has shape: {{1}}\n"
        f"Expected {{0}} shape:   {{2}}"
    )
    if not all(result.index.isin(data.index)):
        raise ValueError(msg.format("index", result.index.shape, data.index.shape))
    if not all(result.columns.isin(data.columns)):
        raise ValueError(
            msg.format("columns", result.columns.shape, data.columns.shape)
        )
    self._update_ctx(result)
    return self

def _adj_justify(texts: Iterable[str], max_len: int, mode: str = "right") -> list[str]:
    """
    Perform ljust, center, rjust against string or list-like
    """
    if mode == "left":
        return [x.ljust(max_len) for x in texts]
    elif mode == "center":
        return [x.center(max_len) for x in texts]
    else:
        return [x.rjust(max_len) for x in texts]

def _pprint_seq(
    seq: ListLike, _nest_lvl: int = 0, max_seq_items: int | None = None, **kwds: Any
) -> str:
    """
    internal. pprinter for iterables. you should probably use pprint_thing()
    rather than calling this directly.

    bounds length of printed sequence, depending on options
    """
    if isinstance(seq, set):
        fmt = "{{{body}}}"
    elif isinstance(seq, frozenset):
        fmt = "frozenset()" if not seq else "frozenset({{{body}}})"
    else:
        fmt = "[{body}]" if hasattr(seq, "__setitem__") else "({body})"

    if max_seq_items is False:
        max_items = None
    else:
        max_items = max_seq_items or config["display"]["max_seq_items"] or len(seq)

    s = iter(seq)
    # handle sets, no slicing
    r = []
    max_items_reached = False
    for i, item in enumerate(s):
        if (max_items is not None) and (i >= max_items):
            max_items_reached = True
            break
        if is_float(item) and notna(item):
            # GH#60503
            from pandas.io.formats.format import _trim_zeros_single_float

            precision = config["display"]["precision"]
            item = _trim_zeros_single_float(f"{item:.{precision}f}")
        r.append(pprint_thing(item, _nest_lvl + 1, max_seq_items=max_seq_items, **kwds))
    body = ", ".join(r)

    if max_items_reached:
        body += ", ..."
    elif isinstance(seq, tuple) and len(seq) == 1:
        body += ","

    return fmt.format(body=body)

def _pprint_dict(
    seq: Mapping[Any, Any],
    _nest_lvl: int = 0,
    max_seq_items: int | None = None,
    **kwds: Any,
) -> str:
    """
    internal. pprinter for iterables. you should probably use pprint_thing()
    rather than calling this directly.
    """
    fmt = "{{{things}}}"
    pairs = []

    pfmt = "{key}: {val}"

    if max_seq_items is False:
        nitems = len(seq)
    else:
        nitems = max_seq_items or config["display"]["max_seq_items"] or len(seq)

    for k, v in list(seq.items())[:nitems]:
        pairs.append(
            pfmt.format(
                key=pprint_thing(k, _nest_lvl + 1, max_seq_items=max_seq_items, **kwds),
                val=pprint_thing(v, _nest_lvl + 1, max_seq_items=max_seq_items, **kwds),
            )
        )

    if nitems < len(seq):
        return fmt.format(things=", ".join(pairs) + ", ...")
    else:
        return fmt.format(things=", ".join(pairs))

def _as_escaped_string(
    thing: Any, escape_chars: EscapeChars | None, default_escapes: bool
) -> str:
    translate = {"\t": r"\t", "\n": r"\n", "\r": r"\r", "'": r"\'"}
    if isinstance(escape_chars, Mapping):
        if default_escapes:
            translate.update(escape_chars)
        else:
            translate = escape_chars  # type: ignore[assignment]
        escape_chars = list(escape_chars.keys())
    else:
        escape_chars = escape_chars or ()

    result = str(thing)
    for c in escape_chars:
        result = result.replace(c, translate[c])
    return result

def justify(self, texts: Any, max_len: int, mode: str = "right") -> list[str]:
    """
    Perform ljust, center, rjust against string or list-like
    """
    if mode == "left":
        return [x.ljust(max_len) for x in texts]
    elif mode == "center":
        return [x.center(max_len) for x in texts]
    else:
        return [x.rjust(max_len) for x in texts]

def len(self, text: str) -> int:
    """
    Calculate display width considering unicode East Asian Width
    """
    if not isinstance(text, str):
        return len(text)

    return sum(
        self._EAW_MAP.get(east_asian_width(c), self.ambiguous_width) for c in text

def justify(
    self, texts: Iterable[str], max_len: int, mode: str = "right"
) -> list[str]:
    # re-calculate padding space per str considering East Asian Width
    def _get_pad(t: str) -> int:
        return max_len - self.len(t) + len(t)

    if mode == "left":
        return [x.ljust(_get_pad(x)) for x in texts]
    elif mode == "center":
        return [x.center(_get_pad(x)) for x in texts]
    else:
        return [x.rjust(_get_pad(x)) for x in texts]

def _border_style(
    self, style: str | None, width: str | None, color: str | None
) -> str | None:
    # convert styles and widths to openxml, one of:
    #       'dashDot'
    #       'dashDotDot'
    #       'dashed'
    #       'dotted'
    #       'double'
    #       'hair'
    #       'medium'
    #       'mediumDashDot'
    #       'mediumDashDotDot'
    #       'mediumDashed'
    #       'slantDashDot'
    #       'thick'
    #       'thin'
    if width is None and style is None:
        if color is None:
            # Return None will remove "border" from style dictionary
            return None
        else:
            # Return "none" will keep "border" in style dictionary
            return "none"

    if style in ("none", "hidden"):
        return "none"

    width_name = self._get_width_name(width)
    if width_name is None:
        return "none"

    if style in (None, "groove", "ridge", "inset", "outset", "solid"):
        # not handled
        return width_name

    if style == "double":
        return "double"
    if style == "dotted":
        if width_name in ("hair", "thin"):
            return "dotted"
        return "mediumDashDotDot"
    if style == "dashed":
        if width_name in ("hair", "thin"):
            return "dashed"
        return "mediumDashed"
    elif style in self.BORDER_STYLE_MAP:
        # Excel-specific styles
        return self.BORDER_STYLE_MAP[style]
    else:
        warnings.warn(
            f"Unhandled border style format: {style!r}",
            CSSWarning,
            stacklevel=find_stack_level(),
        )
        return "none"

def _get_width_name(self, width_input: str | None) -> str | None:
    width = self._width_to_float(width_input)
    if width < 1e-5:
        return None
    elif width < 1.3:
        return "thin"
    elif width < 2.8:
        return "medium"
    return "thick"

def _get_font_names(self, props: Mapping[str, str]) -> Sequence[str]:
    font_names_tmp = re.findall(
        r"""(?x)
        (
        "(?:[^"]|\\")+"
        |
        '(?:[^']|\\')+'
        |
        [^'",]+
        )(?=,|\s*$)
    """,
        props.get("font-family", ""),
    )

    font_names = []
    for name in font_names_tmp:
        if name[:1] == '"':
            name = name[1:-1].replace('\\"', '"')
        elif name[:1] == "'":
            name = name[1:-1].replace("\\'", "'")
        else:
            name = name.strip()
        if name:
            font_names.append(name)
    return font_names

def _select_font_family(self, font_names: Sequence[str]) -> int | None:
    family = None
    for name in font_names:
        family = self.FAMILY_MAP.get(name)
        if family:
            break

    return family

def color_to_excel(self, val: str | None) -> str | None:
    if val is None:
        return None

    if self._is_hex_color(val):
        return self._convert_hex_to_excel(val)

    try:
        return self.NAMED_COLORS[val]
    except KeyError:
        warnings.warn(
            f"Unhandled color format: {val!r}",
            CSSWarning,
            stacklevel=find_stack_level(),
        )
    return None

def _is_shorthand_color(self, color_string: str) -> bool:
    """Check if color code is shorthand.

    #FFF is a shorthand as opposed to full #FFFFFF.
    """
    code = color_string.lstrip("#")
    if len(code) == 3:
        return True
    elif len(code) == 6:
        return False
    else:
        raise ValueError(f"Unexpected color {color_string}")

def _format_value(self, val):
    if is_scalar(val) and missing.isna(val):
        val = self.na_rep
    elif is_float(val):
        if missing.isposinf_scalar(val):
            val = self.inf_rep
        elif missing.isneginf_scalar(val):
            val = f"-{self.inf_rep}"
        elif self.float_format is not None:
            val = float(self.float_format % val)
    if getattr(val, "tzinfo", None) is not None:
        raise ValueError(
            "Excel does not support datetimes with "
            "timezones. Please ensure that datetimes "
            "are timezone unaware before writing to Excel."
        )
    return val

def _format_header_mi(self) -> Iterable[ExcelCell]:
    if self.columns.nlevels > 1:
        if not self.index:
            raise NotImplementedError(
                "Writing to Excel with MultiIndex columns and no "
                "index ('index'=False) is not yet implemented."
            )

    if not (self._has_aliases or self.header):
        return

    columns = self.columns
    merge_columns = self.merge_cells in {True, "columns"}
    level_strs = columns._format_multi(sparsify=merge_columns, include_names=False)
    level_lengths = get_level_lengths(level_strs)
    coloffset = 0
    lnum = 0

    if self.index and isinstance(self.df.index, MultiIndex):
        coloffset = self.df.index.nlevels - 1

    for lnum, name in enumerate(columns.names):
        yield ExcelCell(
            row=lnum,
            col=coloffset,
            val=name,
            style=None,
        )

    for lnum, (spans, levels, level_codes) in enumerate(
        zip(level_lengths, columns.levels, columns.codes, strict=True)
    ):
        values = levels.take(level_codes)
        for i, span_val in spans.items():
            mergestart, mergeend = None, None
            if merge_columns and span_val > 1:
                mergestart, mergeend = lnum, coloffset + i + span_val
            yield CssExcelCell(
                row=lnum,
                col=coloffset + i + 1,
                val=values[i],
                style=None,
                css_styles=getattr(self.styler, "ctx_columns", None),
                css_row=lnum,
                css_col=i,
                css_converter=self.style_converter,
                mergestart=mergestart,
                mergeend=mergeend,
            )
    self.rowcounter = lnum

def _format_header_regular(self) -> Iterable[ExcelCell]:
    if self._has_aliases or self.header:
        coloffset = 0

        if self.index:
            coloffset = 1
            if isinstance(self.df.index, MultiIndex):
                coloffset = len(self.df.index.names)

        colnames = self.columns
        if self._has_aliases:
            self.header = cast("Sequence", self.header)
            if len(self.header) != len(self.columns):
                raise ValueError(
                    f"Writing {len(self.columns)} cols "
                    f"but got {len(self.header)} aliases"
                )
            colnames = self.header

        for colindex, colname in enumerate(colnames):
            yield CssExcelCell(
                row=self.rowcounter,
                col=colindex + coloffset,
                val=colname,
                style=None,
                css_styles=getattr(self.styler, "ctx_columns", None),
                css_row=0,
                css_col=colindex,
                css_converter=self.style_converter,

def _format_header(self) -> Iterable[ExcelCell]:
    gen: Iterable[ExcelCell]

    if isinstance(self.columns, MultiIndex):
        gen = self._format_header_mi()
    else:
        gen = self._format_header_regular()

    gen2: Iterable[ExcelCell] = ()

    if self.df.index.names:
        row = [x if x is not None else "" for x in self.df.index.names] + [
            ""
        ] * len(self.columns)
        if functools.reduce(lambda x, y: x and y, (x != "" for x in row)):
            gen2 = (
                ExcelCell(self.rowcounter, colindex, val, None)
                for colindex, val in enumerate(row)
            )
            self.rowcounter += 1
    return itertools.chain(gen, gen2)

def _format_regular_rows(self) -> Iterable[ExcelCell]:
    if self._has_aliases or self.header:
        self.rowcounter += 1

    # output index and index_label?
    if self.index:
        # check aliases
        # if list only take first as this is not a MultiIndex
        if self.index_label and isinstance(
            self.index_label, (list, tuple, np.ndarray, Index)
        ):
            index_label = self.index_label[0]
        # if string good to go
        elif self.index_label and isinstance(self.index_label, str):
            index_label = self.index_label
        else:
            index_label = self.df.index.names[0]

        if isinstance(self.columns, MultiIndex):
            self.rowcounter += 1

        if index_label and self.header is not False:
            yield ExcelCell(self.rowcounter - 1, 0, index_label, None)

        # write index_values
        index_values = self.df.index
        if isinstance(self.df.index, PeriodIndex):
            index_values = self.df.index.to_timestamp()

        for idx, idxval in enumerate(index_values):
            yield CssExcelCell(
                row=self.rowcounter + idx,
                col=0,
                val=idxval,
                style=None,
                css_styles=getattr(self.styler, "ctx_index", None),
                css_row=idx,
                css_col=0,
                css_converter=self.style_converter,
            )
        coloffset = 1
    else:
        coloffset = 0

    yield from self._generate_body(coloffset)

def _str_escape(x, escape):
    """if escaping: only use on str, else return input"""
    if isinstance(x, str):
        if escape == "html":
            return escape_html(x)
        elif escape == "latex":
            return _escape_latex(x)
        elif escape == "latex-math":
            return _escape_latex_math(x)
        else:
            raise ValueError(
                f"`escape` only permitted in {{'html', 'latex', 'latex-math'}}, \
got {escape}"
            )
    return x

def _render_href(x, format):
    """uses regex to detect a common URL pattern and converts to href tag in format."""
    if isinstance(x, str):
        if format == "html":
            href = '<a href="{0}" target="_blank">{0}</a>'
        elif format == "latex":
            href = r"\href{{{0}}}{{{0}}}"
        else:
            raise ValueError("``hyperlinks`` format can only be 'html' or 'latex'")
        pat = r"((http|ftp)s?:\/\/|www.)[\w/\-?=%.:@]+\.[\w/\-&?=%.,':;~!@#$*()\[\]]+"
        return re.sub(pat, lambda m: href.format(m.group(0)), x)
    return x

def _maybe_wrap_formatter(
    formatter: BaseFormatter | None = None,
    na_rep: str | None = None,
    precision: int | None = None,
    decimal: str = ".",
    thousands: str | None = None,
    escape: str | None = None,
    hyperlinks: str | None = None,
) -> Callable:
    """
    Allows formatters to be expressed as str, callable or None, where None returns
    a default formatting function. wraps with na_rep, and precision where they are
    available.
    """
    # Get initial func from input string, input callable, or from default factory
    if isinstance(formatter, str):
        func_0 = lambda x: formatter.format(x)
    elif callable(formatter):
        func_0 = formatter
    elif formatter is None:
        precision = (
            config["styler"]["format"]["precision"] if precision is None else precision
        )
        func_0 = partial(
            _default_formatter, precision=precision, thousands=(thousands is not None)
        )
    else:
        raise TypeError(f"'formatter' expected str or callable, got {type(formatter)}")

    # Replace chars if escaping
    if escape is not None:
        func_1 = lambda x: func_0(_str_escape(x, escape=escape))
    else:
        func_1 = func_0

    # Replace decimals and thousands if non-standard inputs detected
    if decimal != "." or (thousands is not None and thousands != ","):
        func_2 = _wrap_decimal_thousands(func_1, decimal=decimal, thousands=thousands)
    else:
        func_2 = func_1

    # Render links
    if hyperlinks is not None:
        func_3 = lambda x: func_2(_render_href(x, format=hyperlinks))
    else:
        func_3 = func_2

    # Replace missing values if na_rep
    if na_rep is None:
        return func_3
    else:
        return lambda x: na_rep if (isna(x) is True) else func_3(x)

def non_reducing_slice(slice_: Subset):
    """
    Ensure that a slice doesn't reduce to a Series or Scalar.

    Any user-passed `subset` should have this called on it
    to make sure we're always working with DataFrames.
    """
    # default to column slice, like DataFrame
    # ['A', 'B'] -> IndexSlices[:, ['A', 'B']]
    kinds = (ABCSeries, np.ndarray, Index, list, str)
    if isinstance(slice_, kinds):
        slice_ = IndexSlice[:, slice_]

    def pred(part) -> bool:
        """
        Returns
        -------
        bool
            True if slice does *not* reduce,
            False if `part` is a tuple.
        """
        # true when slice does *not* reduce, False when part is a tuple,
        # i.e. MultiIndex slice
        if isinstance(part, tuple):
            # GH#39421 check for sub-slice:
            return any((isinstance(s, slice) or is_list_like(s)) for s in part)
        else:
            return isinstance(part, slice) or is_list_like(part)

    if not is_list_like(slice_):
        if not isinstance(slice_, slice):
            # a 1-d slice, like df.loc[1]
            slice_ = [[slice_]]
        else:
            # slice(a, b, c)
            slice_ = [slice_]  # to tuplize later
    else:
        # error: Item "slice" of "Union[slice, Sequence[Any]]" has no attribute
        # "__iter__" (not iterable) -> is specifically list_like in conditional
        slice_ = [p if pred(p) else [p] for p in slice_]  # type: ignore[union-attr]
    return tuple(slice_)

def _escape_latex_math(s: str) -> str:
    r"""
    All characters in LaTeX math mode are preserved.

    The substrings in LaTeX math mode, which either are surrounded
    by two characters ``$`` or start with the character ``\(`` and end with ``\)``,
    are preserved without escaping. Otherwise regular LaTeX escaping applies.

    Parameters
    ----------
    s : str
        Input to be escaped

    Return
    ------
    str :
        Escaped string
    """
    s = s.replace(r"\$", r"rt8§=§7wz")
    ps_d = re.compile(r"\$.*?\$").search(s, 0)
    ps_p = re.compile(r"\(.*?\)").search(s, 0)
    mode = []
    if ps_d:
        mode.append(ps_d.span()[0])
    if ps_p:
        mode.append(ps_p.span()[0])
    if len(mode) == 0:
        return _escape_latex(s.replace(r"rt8§=§7wz", r"\$"))
    if s[mode[0]] == r"$":
        return _math_mode_with_dollar(s.replace(r"rt8§=§7wz", r"\$"))
    if s[mode[0] - 1 : mode[0] + 1] == r"\(":
        return _math_mode_with_parentheses(s.replace(r"rt8§=§7wz", r"\$"))
    else:
        return _escape_latex(s.replace(r"rt8§=§7wz", r"\$"))

def _render_typst(
    self,
    sparse_index: bool,
    sparse_columns: bool,
    max_rows: int | None = None,
    max_cols: int | None = None,
    **kwargs,
) -> str:
    """
    Render a Styler in typst format
    """
    d = self._render(sparse_index, sparse_columns, max_rows, max_cols)
    index_levels = self.index.nlevels
    visible_index_levels = max(1, index_levels - sum(self.hide_index_))
    column_header_rows = (
        self.columns.nlevels - sum(self.hide_columns_) if len(self.columns) else 0
    )
    hidden_columns_set = set(self.hidden_columns)
    for r, row in enumerate(d["head"]):
        if r < column_header_rows:
            # Keep sparse column placeholders, but remove explicitly hidden columns.
            d["head"][r] = [
                cell for cell in row[:visible_index_levels] if cell["is_visible"]
            ] + [
                cell
                for c, cell in enumerate(row[visible_index_levels:])
                if cell["is_visible"] or c not in hidden_columns_set
            ]
        else:
            d["head"][r] = [cell for cell in row if cell["is_visible"]]
    d["body"] = [
        [
            cell
            for c, cell in enumerate(row[:index_levels])
            if not self.hide_index_[c]
        ]
        + [cell for cell in row[index_levels:] if cell["is_visible"]]
        for row in d["body"]
    ]
    d.update(kwargs)
    return self.template_typst.render(**d)

def _read(
    filepath_or_buffer: FilePath | ReadCsvBuffer[bytes] | ReadCsvBuffer[str], kwds
) -> DataFrame | TextFileReader:
    """Generic reader of line files."""
    # before the `iterator` peek below, which reads it for truthiness
    _validate_bool_kwargs(kwds)

    # if we pass a date_format and parse_dates=False, we should not parse the
    # dates GH#44366
    if kwds.get("parse_dates", None) is None:
        if kwds.get("date_format", None) is None:
            kwds["parse_dates"] = False
        else:
            kwds["parse_dates"] = True

    # Extract some of the arguments (pass chunksize on).
    iterator = kwds.get("iterator", False)
    chunksize = kwds.get("chunksize", None)

    # Check type of encoding_errors
    errors = kwds.get("encoding_errors", "strict")
    if not isinstance(errors, str):
        raise ValueError(
            f"encoding_errors must be a string, got {type(errors).__name__}"
        )

    if kwds.get("engine") == "pyarrow":
        if iterator:
            raise ValueError(
                "The 'iterator' option is not supported with the 'pyarrow' engine"
            )

        if chunksize is not None:
            raise ValueError(
                "The 'chunksize' option is not supported with the 'pyarrow' engine"
            )
    else:
        chunksize = validate_integer("chunksize", chunksize, 1)

    nrows = kwds.get("nrows", None)

    # Check for duplicates in names.
    _validate_names(kwds.get("names", None))

    if kwds.get("float_precision") is not None:
        warnings.warn(
            "The 'float_precision' argument is deprecated. "
            "Use the default float precision instead.",
            Pandas4Warning,
            stacklevel=find_stack_level(),
        )

    # For large local uncompressed files with the C engine, attempt parallel reading.
    # Each worker gets its own file handle and TextReader so the GIL-free tokenisation
    # and type-conversion code in parsers.pyx runs truly in parallel.
    if not iterator and chunksize is None and nrows is None:
        _n_workers = _default_n_workers()
        if _n_workers > 1 and _can_parallelize_csv(filepath_or_buffer, kwds):
            _filepath = stringify_path(filepath_or_buffer)
            assert isinstance(_filepath, str)  # guaranteed by _can_parallelize_csv
            try:
                result = _read_csv_parallel(_filepath, kwds, _n_workers)
            except (ParserError, UnicodeDecodeError, OverflowError):
                # e.g. a chunk boundary landed inside a quoted field containing
                # an embedded newline, or a chunk of only huge ints converted
                # where the mixed whole-file column would have stayed a string
                # (GH#66259).  The serial path below handles anything the
                # parallel path cannot -- and raises in turn if it too fails.
                # Other exceptions propagate: they signal a parallel-path bug,
                # not ineligible input.
                result = None
            if result is not None:
                return result

    # Create the parser.
    parser = TextFileReader(filepath_or_buffer, **kwds)

    if chunksize or iterator:
        return parser

    with parser:
        return parser.read(nrows)

def _find_data_start_offset(
    filepath: str,
    header: int | None,
    skiprows: int,
) -> int:
    """
    Return the byte offset of the first data row in *filepath*.

    Reads ``int(skiprows) + (header + 1 if header is not None else 0)``
    physical lines from the start of the file and returns the position after
    the last preamble byte.  This is the byte from which each non-first chunk
    must begin.
    """
    if header is None:
        header_lines = 0
    else:
        header_lines = int(header) + 1  # header=0 → 1 header line

    preamble_lines = int(skiprows) + header_lines
    with open(filepath, "rb") as fd:
        for _ in range(preamble_lines):
            if not fd.readline():
                break
        return fd.tell()

def _clean_na_values(na_values, keep_default_na: bool = True, floatify: bool = True):
    na_fvalues: set | dict
    if na_values is None:
        if keep_default_na:
            na_values = STR_NA_VALUES
        else:
            na_values = set()
        na_fvalues = set()
    elif isinstance(na_values, dict):
        old_na_values = na_values.copy()
        na_values = {}  # Prevent aliasing.

        # Convert the values in the na_values dictionary
        # into array-likes for further use. This is also
        # where we append the default NaN values, provided
        # that `keep_default_na=True`.
        for k, v in old_na_values.items():
            if not is_list_like(v):
                v = [v]

            if keep_default_na:
                v = set(v) | STR_NA_VALUES

            na_values[k] = _stringify_na_values(v, floatify)
        na_fvalues = {k: _floatify_na_values(v) for k, v in na_values.items()}
    else:
        if not is_list_like(na_values):
            na_values = [na_values]
        na_values = _stringify_na_values(na_values, floatify)
        if keep_default_na:
            na_values = na_values | STR_NA_VALUES

        na_fvalues = _floatify_na_values(na_values)

    return na_values, na_fvalues

def _floatify_na_values(na_values) -> set[float]:
    # create float versions of the na_values
    result = set()
    for v in na_values:
        try:
            v = float(v)
            if not np.isnan(v):
                result.add(v)
        except (TypeError, ValueError, OverflowError):
            pass
    return result

def _stringify_na_values(na_values, floatify: bool) -> set[str | float]:
    """return a stringified and numeric for these values"""
    result: list[str | float] = []
    for x in na_values:
        result.append(str(x))
        result.append(x)
        try:
            v = float(x)

            # we are like 999 here
            if v == int(v):
                v = int(v)
                result.append(f"{v}.0")
                result.append(str(v))

            if floatify:
                result.append(v)
        except (TypeError, ValueError, OverflowError):
            pass
        if floatify:
            try:
                result.append(int(x))
            except (TypeError, ValueError, OverflowError):
                pass
    return set(result)

def _get_options_with_defaults(self, engine: CSVEngine) -> dict[str, Any]:
    kwds = self.orig_options

    options = {}
    default: object | None

    for argname, default in parser_defaults.items():
        value = kwds.get(argname, default)

        # see gh-12935
        if (
            engine == "pyarrow"
            and argname in _pyarrow_unsupported
            and value != default
            and value != getattr(value, "value", default)
        ):
            raise ValueError(
                f"The {argname!r} option is not supported with the 'pyarrow' engine"
            )
        options[argname] = value

    for argname, default in _c_parser_defaults.items():
        if argname in kwds:
            value = kwds[argname]

            if engine != "c" and value != default:
                # TODO: Refactor this logic, its pretty convoluted
                if "python" in engine and argname not in _python_unsupported:
                    pass
                elif "pyarrow" in engine and argname not in _pyarrow_unsupported:
                    pass
                else:
                    raise ValueError(
                        f"The {argname!r} option is not supported with the "
                        f"{engine!r} engine"
                    )
        else:
            value = default
        options[argname] = value

    if engine == "python-fwf":
        for argname, default in _fwf_defaults.items():
            options[argname] = kwds.get(argname, default)

    return options

def _check_file_or_buffer(self, f, engine: CSVEngine) -> None:
    if hasattr(f, "encoding"):
        file_encoding = f.encoding
        orig_reader_enc = self.orig_options.get("encoding", None)
        any_none = file_encoding is None or orig_reader_enc is None
        if file_encoding != orig_reader_enc and not any_none:
            file_path = getattr(f, "name", None)
            raise ValueError(
                f"The specified reader encoding {orig_reader_enc} is different "
                f"from the encoding {file_encoding} of file {file_path}."

def _make_engine(
    self,
    f: FilePath | ReadCsvBuffer[bytes] | ReadCsvBuffer[str] | list | IO,
    engine: CSVEngine = "c",
) -> ParserBase:
    mapping: dict[str, type[ParserBase]] = {
        "c": CParserWrapper,
        "python": PythonParser,
        "pyarrow": ArrowParserWrapper,
        "python-fwf": FixedWidthFieldParser,
    }

    if engine not in mapping:
        raise ValueError(
            f"Unknown engine: {engine} (valid options are {mapping.keys()})"
        )
    if not isinstance(f, list):
        # open file here
        # The c and pyarrow engines can decode utf-8 bytes natively;
        # wrapping in TextIOWrapper makes them slower, especially for
        # memory_map and remote file-like objects (GH#46823).
        is_text = engine in ("python", "python-fwf") or (
            engine == "c"
            and self.options.get("encoding", "utf-8") not in (None, "utf-8")
        )
        mode = "r" if is_text else "rb"
        self.handles = get_handle(
            f,
            mode,
            encoding=self.options.get("encoding", None),
            compression=self.options.get("compression", None),
            memory_map=self.options.get("memory_map", False),
            is_text=is_text,
            errors=self.options.get("encoding_errors", "strict"),
            storage_options=self.options.get("storage_options", None),
        )
        assert self.handles is not None
        f = self.handles.handle

    elif engine != "python":
        msg = f"Invalid file path or buffer object type: {type(f)}"
        raise ValueError(msg)

    try:
        return mapping[engine](f, **self.options)
    except Exception:
        if self.handles is not None:
            self.handles.close()
        raise

def _should_parse_dates(self, i: int) -> bool:
    if isinstance(self.parse_dates, bool):
        return self.parse_dates
    else:
        if self.index_names is not None:
            name = self.index_names[i]
        else:
            name = None
        j = i if self.index_col is None else self.index_col[i]

        return (j in self.parse_dates) or (
            name is not None and name in self.parse_dates

def _make_index(
    self, alldata, columns, indexnamerow: list[Scalar] | None = None
) -> tuple[Index | None, Sequence[Hashable] | MultiIndex]:
    index: Index | None
    if isinstance(self.index_col, list) and len(self.index_col):
        to_remove = []
        indexes = []
        for idx in self.index_col:
            if isinstance(idx, str):
                raise ValueError(f"Index {idx} invalid")
            to_remove.append(idx)
            indexes.append(alldata[idx])
        # remove index items from content and columns, don't pop in
        # loop
        for i in sorted(to_remove, reverse=True):
            alldata.pop(i)
            if not self._implicit_index:
                columns.pop(i)
        index = self._agg_index(indexes)

        # add names for the index
        if indexnamerow:
            coffset = len(indexnamerow) - len(columns)
            index = index.set_names(indexnamerow[:coffset])
    else:
        index = None

    # maybe create a mi on the columns
    columns = self._maybe_make_multi_index_columns(columns, self.col_names)

    return index, columns

def _clean_mapping(self, mapping):
    """converts col numbers to names"""
    if not isinstance(mapping, dict):
        return mapping
    clean = {}
    # for mypy
    assert self.orig_names is not None

    for col, v in mapping.items():
        if isinstance(col, int) and col not in self.orig_names:
            col = self.orig_names[col]
        clean[col] = v
    if isinstance(mapping, defaultdict):
        remaining_cols = set(self.orig_names) - set(clean.keys())
        clean.update({col: mapping[col] for col in remaining_cols})
    return clean

def _agg_index(self, index) -> Index:
    arrays = []
    converters = self._clean_mapping(self.converters)
    clean_dtypes = self._clean_mapping(self.dtype)

    if self.index_names is not None:
        names: Iterable = self.index_names
        zip_strict = True
    else:
        names = itertools.cycle([None])
        zip_strict = False
    for i, (arr, name) in enumerate(zip(index, names, strict=zip_strict)):
        if self._should_parse_dates(i):
            arr = date_converter(
                arr,
                col=self.index_names[i] if self.index_names is not None else None,
                dayfirst=self.dayfirst,
                cache_dates=self.cache_dates,
                date_format=self.date_format,
            )

        if self.na_filter:
            col_na_values = self.na_values
            col_na_fvalues = self.na_fvalues
        else:
            col_na_values = set()
            col_na_fvalues = set()

        if isinstance(self.na_values, dict):
            assert self.index_names is not None
            col_name = self.index_names[i]
            if col_name is not None:
                col_na_values, col_na_fvalues = get_na_values(
                    col_name, self.na_values, self.na_fvalues, self.keep_default_na
                )
            else:
                col_na_values, col_na_fvalues = set(), set()

        cast_type = None
        index_converter = False
        if self.index_names is not None:
            if isinstance(clean_dtypes, dict):
                cast_type = clean_dtypes.get(self.index_names[i], None)

            if isinstance(converters, dict):
                index_converter = converters.get(self.index_names[i]) is not None

        try_num_bool = not (
            (cast_type and is_string_dtype(cast_type)) or index_converter
        )

        arr, _ = self._infer_types(
            arr, col_na_values | col_na_fvalues, cast_type is None, try_num_bool
        )
        if cast_type is not None:
            # Don't perform RangeIndex inference
            idx = Index(arr, name=name, dtype=cast_type, copy=False)
        else:
            idx = ensure_index_from_sequences([arr], [name])
        arrays.append(idx)

    if len(arrays) == 1:
        return arrays[0]
    else:
        return MultiIndex.from_arrays(arrays)

def _do_date_conversions(
    self,
    names: Sequence[Hashable] | Index,
    data: Mapping[Hashable, ArrayLike] | DataFrame,
) -> Mapping[Hashable, ArrayLike] | DataFrame:
    if not isinstance(self.parse_dates, list):
        return data
    for colspec in self.parse_dates:
        if isinstance(colspec, int) and colspec not in data:
            colspec = names[colspec]
        if (isinstance(self.index_col, list) and colspec in self.index_col) or (
            isinstance(self.index_names, list) and colspec in self.index_names
        ):
            continue
        result = date_converter(
            data[colspec],
            col=colspec,
            dayfirst=self.dayfirst,
            cache_dates=self.cache_dates,
            date_format=self.date_format,
        )
        # error: Unsupported target for indexed assignment
        # ("Mapping[Hashable, ExtensionArray | ndarray[Any, Any]] | DataFrame")
        data[colspec] = result  # type: ignore[index]

    return data

def _clean_index_names(self, columns, index_col) -> tuple[list | None, list, list]:
    if not is_index_col(index_col):
        return None, columns, index_col

    columns = list(columns)

    # In case of no rows and multiindex columns we have to set index_names to
    # list of Nones GH#38292
    if not columns:
        return [None] * len(index_col), columns, index_col

    cp_cols = list(columns)
    index_names: list[str | int | None] = []

    # don't mutate
    index_col = list(index_col)

    for i, c in enumerate(index_col):
        if isinstance(c, str):
            index_names.append(c)
            for j, name in enumerate(cp_cols):
                if name == c:
                    index_col[i] = j
                    columns.remove(name)
                    break
        else:
            name = cp_cols[c]
            columns.remove(name)
            index_names.append(name)

    # Only clean index names that were placeholders.
    for i, name in enumerate(index_names):
        if isinstance(name, str) and name in self.unnamed_cols:
            index_names[i] = None

    return index_names, columns, index_col

def _get_convert_options(self):
    pyarrow_csv = import_optional_dependency("pyarrow.csv")

    try:
        convert_options = pyarrow_csv.ConvertOptions(**self.convert_options)
    except TypeError as err:
        include = self.convert_options.get("include_columns", None)
        if include is not None:
            self._validate_usecols(include)

        nulls = self.convert_options.get("null_values", set())
        if not lib.is_list_like(nulls) or not all(
            isinstance(x, str) for x in nulls
        ):
            raise TypeError(
                "The 'pyarrow' engine requires all na_values to be strings"
            ) from err

        raise

    return convert_options

def _finalize_index(self, frame: DataFrame, multi_index_named: bool) -> DataFrame:
    if self.index_col is None and self._implicit_index_count:
        self.index_col = list(range(self._implicit_index_count))
    if self.index_col is not None:
        index_to_set = self.index_col.copy()
        for i, item in enumerate(self.index_col):
            if is_integer(item):
                col_name = frame.columns[item]
                index_to_set[i] = col_name
                position = int(item)
            # String case
            elif item not in frame.columns:
                raise ValueError(f"Index {item} invalid")
            else:
                col_name = item
                position = cast("int", frame.columns.get_loc(item))

            # parse_dates for index columns: the other engines parse these
            # while building the index, but the pyarrow path sets the index
            # after reading, so do the conversion here.
            if self._index_col_should_parse_dates(col_name, position):
                frame[col_name] = date_converter(
                    frame[col_name],
                    col=col_name,
                    dayfirst=self.dayfirst,
                    cache_dates=self.cache_dates,
                    date_format=self.date_format,
                )

            # Process dtype for index_col and drop from dtypes
            if isinstance(self.dtype, dict):
                key, new_dtype = (
                    (item, self.dtype.get(item))
                    if self.dtype.get(item) is not None
                    else (frame.columns[item], self.dtype.get(frame.columns[item]))
                )
                if new_dtype is not None:
                    frame[key] = frame[key].astype(new_dtype)
                    del self.dtype[key]

        if self.dtype is not None and not isinstance(self.dtype, dict):
            # GH#45801 match the c engine: an index column left as object
            #  by the scalar dtype (i.e. the dtype resolved to object) is
            #  re-inferred, as if no dtype had been passed
            for key in index_to_set:
                if frame[key].dtype == object:
                    new_values, _ = self._infer_types(
                        frame[key].to_numpy(copy=True),
                        set(),
                        no_dtype_specified=True,
                    )
                    frame[key] = new_values
                    frame[key] = frame[key].infer_objects()

        frame = frame.set_index(index_to_set, drop=True)
        # Clear names if no name given for the padded leading columns
        if not multi_index_named:
            frame.index.names = [None] * len(frame.index.names)
        elif self.unnamed_cols:
            # GH#13017 match other engines: empty header fields used as
            # an index produce an unnamed index level
            frame.index.names = [
                None if name in self.unnamed_cols else name
                for name in frame.index.names
            ]

    return frame

def _finalize_dtype(self, frame: DataFrame) -> DataFrame:
    if self.dtype is not None:
        # Ignore non-existent columns from dtype mapping
        # like other parsers do
        if isinstance(self.dtype, dict):
            self.dtype = {
                k: pandas_dtype(v)
                for k, v in self.dtype.items()
                if k in frame.columns
            }
        else:
            # GH#34066 a scalar dtype must not clobber the dtype produced by
            # date parsing, so exclude parse_dates columns from the cast.
            scalar_dtype = pandas_dtype(self.dtype)
            parse_dates_cols = (
                set(self.parse_dates)
                if isinstance(self.parse_dates, list)
                else set()
            )
            self.dtype = {
                col: scalar_dtype
                for col in frame.columns
                if col not in parse_dates_cols
            }
        try:
            frame = frame.astype(self.dtype)
        except TypeError as err:
            # GH#44901 reraise to keep api consistent
            raise ValueError(str(err)) from err
    return frame

def _maybe_restore_string_dtype(self, frame: DataFrame) -> DataFrame:
    # When parse_dates fails to parse a column it falls back to the original
    # strings; keep the default string dtype rather than object, matching
    # the other engines.
    if not (using_string_dtype() and isinstance(self.parse_dates, list)):
        return frame
    for col in self.parse_dates:
        if col in frame.columns and frame[col].dtype == object:
            frame[col] = frame[col].astype("str")
    return frame

def _validate_usecols(self, usecols) -> None:
    if lib.is_list_like(usecols) and not all(isinstance(x, str) for x in usecols):
        raise ValueError(
            "The pyarrow engine does not allow 'usecols' to be integer "
            "column positions. Pass a list of string column names instead."
        )
    elif callable(usecols):
        raise ValueError(
            "The pyarrow engine does not allow 'usecols' to be a callable."

def _filter_usecols(usecols, names: SequenceT) -> SequenceT | list[Hashable]:
    # hackish
    usecols = evaluate_callable_usecols(usecols, names)
    if usecols is not None and len(names) != len(usecols):
        return [name for i, name in enumerate(names) if i in usecols or name in usecols]
    return names

def _pa_arrays_to_ea(arrs) -> ArrayLike:
    """
    Build one ExtensionArray from the pending string columns returned by
    the deferred TextReader string fast path (``defer_pa_wrap``).

    The fast path emits ``large_string`` for the default string dtype and
    ``string`` for ``dtype_backend="pyarrow"``, so the arrow type determines
    the target ExtensionArray.
    """
    import pyarrow as pa

    chunked = pa.chunked_array([pending.materialize() for pending in arrs])
    if pa.types.is_large_string(chunked.type):
        return ArrowStringArray(chunked, dtype=StringDtype(na_value=np.nan))
    return ArrowExtensionArray(chunked)

def ensure_dtype_objs(
    dtype: DtypeArg | dict[Hashable, DtypeArg] | None,
) -> DtypeObj | dict[Hashable, DtypeObj] | None:
    """
    Ensure we have either None, a dtype object, or a dictionary mapping to
    dtype objects.
    """
    if isinstance(dtype, defaultdict):
        # "None" not callable  [misc]
        default_dtype = pandas_dtype(dtype.default_factory())  # type: ignore[misc]
        dtype_converted: defaultdict[Hashable, DtypeObj] = defaultdict(
            lambda: default_dtype
        )
        for key in dtype.keys():
            dtype_converted[key] = pandas_dtype(dtype[key])
        return dtype_converted
    elif isinstance(dtype, dict):
        return {k: pandas_dtype(dtype[k]) for k in dtype}
    elif dtype is not None:
        return pandas_dtype(dtype)
    return dtype

def _validate_integer_cast(
    original: ArrayLike, casted: ArrayLike, cast_type: np.dtype, column
) -> None:
    """
    Raise if casting to an integer dtype wrapped around (GH#55232).
    """
    if cast_type.kind not in "iu" or original.dtype.kind not in "iuf":
        return
    values = np.asarray(original)
    if np.can_cast(values.dtype, cast_type):
        return
    if values.dtype.kind == "f":
        # discarding a float's fractional part is not wraparound and stays
        #  allowed (see test_read_fwf.py::test_dtype)
        values = np.trunc(values)
    if (np.asarray(casted) != values).any():
        raise ValueError(
            f"cannot safely convert passed user dtype of "
            f"{cast_type} for {values.dtype.name} dtyped data in "
            f"column {column}"

def _exclude_implicit_index(
    self,
    alldata: list[np.ndarray],
) -> tuple[Mapping[Hashable, np.ndarray], Sequence[Hashable]]:
    # error: Cannot determine type of 'index_col'
    names = dedup_names(
        self.orig_names,
        is_potential_multi_index(
            self.orig_names,
            self.index_col,
        ),
    )

    offset = 0
    if self._implicit_index:
        offset = len(self.index_col)

    len_alldata = len(alldata)
    self._check_data_length(names, alldata)

    return {
        name: alldata[i + offset] for i, name in enumerate(names) if i < len_alldata
    }, names

def _convert_data(
    self,
    data: Mapping[Hashable, np.ndarray],
) -> Mapping[Hashable, ArrayLike]:
    # apply converters
    clean_conv = self._clean_mapping(self.converters)
    clean_dtypes = self._clean_mapping(self.dtype)

    # Apply NA values.
    clean_na_values = {}
    clean_na_fvalues = {}

    if isinstance(self.na_values, dict):
        for col in self.na_values:
            if col is not None:
                na_value = self.na_values[col]
                na_fvalue = self.na_fvalues[col]

                if isinstance(col, int) and col not in self.orig_names:
                    col = self.orig_names[col]

                clean_na_values[col] = na_value
                clean_na_fvalues[col] = na_fvalue
    else:
        clean_na_values = self.na_values
        clean_na_fvalues = self.na_fvalues

    return self._convert_to_ndarrays(
        data,
        clean_na_values,
        clean_na_fvalues,
        clean_conv,
        clean_dtypes,

def _have_mi_columns(self) -> bool:
    if self.header is None:
        return False

    header = self.header
    if isinstance(header, (list, tuple, np.ndarray)):
        return len(header) > 1
    else:
        return False

def _header_line(self):
    # Store line for reuse in _get_index_name
    if self.header is not None:
        return None

    try:
        line = self._buffered_line()
    except StopIteration as err:
        if not self.names:
            raise EmptyDataError("No columns to parse from file") from err

        line = self.names[:]
    return line

def _handle_usecols(
    self,
    columns: list[list[Scalar | None]],
    usecols_key: list[Scalar | None],
    num_original_columns: int,
) -> list[list[Scalar | None]]:
    """
    Sets self._col_indices

    usecols_key is used if there are string usecols.
    """
    col_indices: set[int] | list[int]
    if self.usecols is not None:
        if callable(self.usecols):
            col_indices = evaluate_callable_usecols(self.usecols, usecols_key)
        elif any(isinstance(u, str) for u in self.usecols):
            if len(columns) > 1:
                raise ValueError(
                    "If using multiple headers, usecols must be integers."
                )
            col_indices = []

            for col in self.usecols:
                if isinstance(col, str):
                    try:
                        col_indices.append(usecols_key.index(col))
                    except ValueError:
                        self._validate_usecols_names(self.usecols, usecols_key)
                else:
                    col_indices.append(col)
        else:
            missing_usecols = [
                col for col in self.usecols if col >= num_original_columns
            ]
            if missing_usecols:
                raise ParserError(
                    "Defining usecols with out-of-bounds indices is not allowed. "
                    f"{missing_usecols} are out-of-bounds.",
                )
            col_indices = self.usecols

        columns = [
            [n for i, n in enumerate(column) if i in col_indices]
            for column in columns
        ]
        self._col_indices = sorted(col_indices)
    return columns

def _next_line(self) -> list[Scalar]:
    if isinstance(self.data, list):
        while self.skipfunc(self.pos):
            if self.pos >= len(self.data):
                break
            self.pos += 1

        while True:
            try:
                line = self._check_comments([self.data[self.pos]])[0]
                self.pos += 1
                # either uncommented or blank to begin with
                if not self.skip_blank_lines and (
                    self._is_line_empty(self.data[self.pos - 1]) or line
                ):
                    break
                if self.skip_blank_lines:
                    ret = self._remove_empty_lines([line])
                    if ret:
                        line = ret[0]
                        break
            except IndexError as err:
                raise StopIteration from err
    else:
        while self.skipfunc(self.pos):
            # consume first: on an exhausted file this raises and self.pos must
            # not advance past the last line, or skipfooter trims from the wrong
            # end (GH#36827)
            next(self.data)
            self.pos += 1

        while True:
            orig_line = self._next_iter_line(row_num=self.pos + 1)
            self.pos += 1

            if orig_line is not None:
                line = self._check_comments([orig_line])[0]

                if self.skip_blank_lines:
                    ret = self._remove_empty_lines([line])

                    if ret:
                        line = ret[0]
                        break
                elif self._is_line_empty(orig_line) or line:
                    break

    # This was the first line of the file,
    # which could contain the BOM at the
    # beginning of it.
    if self.pos == 1:
        line = self._check_for_bom(line)

    self.line_pos += 1
    self.buf.append(line)
    self.buf_pos.append(self.pos - 1)
    return line

def _check_comments(self, lines: list[list[Scalar]]) -> list[list[Scalar]]:
    if self.comment is None:
        return lines
    ret = []
    for line in lines:
        rl = []
        for x in line:
            if (
                not isinstance(x, str)
                or self.comment not in x
                or x in self.na_values
            ):
                rl.append(x)
            else:
                x = x[: x.find(self.comment)]
                if len(x) > 0:
                    rl.append(x)
                break
        ret.append(rl)
    return ret

def _search_replace_num_columns(
    self, lines: list[list[Scalar]], search: str, replace: str
) -> list[list[Scalar]]:
    ret = []
    for line in lines:
        rl = []
        for i, x in enumerate(line):
            if (
                not isinstance(x, str)
                or search not in x
                or i in self._no_thousands_columns
                or not self.num.search(x.strip())
            ):
                rl.append(x)
            else:
                rl.append(x.replace(search, replace))
        ret.append(rl)
    return ret

def _remove_skipped_rows(self, new_rows: list[list[Scalar]]) -> list[list[Scalar]]:
    if self.skiprows:
        return [
            row for i, row in enumerate(new_rows) if not self.skipfunc(i + self.pos)
        ]
    return new_rows

def _set_no_thousand_columns(self) -> set[int]:
    no_thousands_columns: set[int] = set()
    if self.columns and self.parse_dates:
        assert self._col_indices is not None
        no_thousands_columns = self._set_noconvert_dtype_columns(
            self._col_indices, self.columns
        )
    if self.columns and self.dtype:
        assert self._col_indices is not None
        for i, col in zip(self._col_indices, self.columns, strict=True):
            if not isinstance(self.dtype, dict) and not is_numeric_dtype(
                self.dtype
            ):
                no_thousands_columns.add(i)
            if (
                isinstance(self.dtype, dict)
                and col in self.dtype
                and (
                    not is_numeric_dtype(self.dtype[col])
                    or is_bool_dtype(self.dtype[col])
                )
            ):
                no_thousands_columns.add(i)
    return no_thousands_columns

def __init__(
    self,
    f: IO[str] | ReadCsvBuffer[str],
    colspecs: list[tuple[int, int]] | Literal["infer"],
    delimiter: str | None,
    comment: str | None,
    skiprows: set[int] | None = None,
    infer_nrows: int = 100,
) -> None:
    self.f = f
    self.buffer: Iterator | None = None
    self.delimiter = "\r\n" + delimiter if delimiter else "\n\r\t "
    self.comment = comment
    if colspecs == "infer":
        self.colspecs = self.detect_colspecs(
            infer_nrows=infer_nrows, skiprows=skiprows
        )
    else:
        self.colspecs = colspecs

    if not isinstance(self.colspecs, (tuple, list)):
        raise TypeError(
            "column specifications must be a list or tuple, "
            f"input was a {type(colspecs).__name__}"
        )

    for colspec in self.colspecs:
        if not (
            isinstance(colspec, (tuple, list))
            and len(colspec) == 2
            and isinstance(colspec[0], (int, np.integer, type(None)))
            and isinstance(colspec[1], (int, np.integer, type(None)))
        ):
            raise TypeError(
                "Each column specification must be "

def __next__(self) -> list[str]:
    if self.buffer is not None:
        try:
            line = next(self.buffer)
        except StopIteration:
            self.buffer = None
            line = next(self.f)  # type: ignore[arg-type]
    else:
        line = next(self.f)  # type: ignore[arg-type]
    # Note: 'colspecs' is a sequence of half-open intervals.
    return [line[from_:to].strip(self.delimiter) for (from_, to) in self.colspecs]

def __init__(
    self,
    filepath_or_buffer,
    storage_options: StorageOptions | None = None,
    engine_kwargs: dict | None = None,
) -> None:
    if engine_kwargs is None:
        engine_kwargs = {}

    self.handles = IOHandles(
        handle=filepath_or_buffer, compression={"method": None}
    )
    if not isinstance(filepath_or_buffer, (ExcelFile, self._workbook_class)):
        self.handles = get_handle(
            filepath_or_buffer, "rb", storage_options=storage_options, is_text=False
        )

    if isinstance(self.handles.handle, self._workbook_class):
        self.book = self.handles.handle
    elif hasattr(self.handles.handle, "read"):
        # N.B. xlrd.Book has a read attribute too
        self.handles.handle.seek(0)
        try:
            self.book = self.load_workbook(self.handles.handle, engine_kwargs)
        except Exception:
            self.close()
            raise
    else:
        raise ValueError(
            "Must explicitly set engine if not passing in buffer or path for io."

def close(self) -> None:
    if hasattr(self, "book"):
        if hasattr(self.book, "close"):
            # pyxlsb: opens a TemporaryFile
            # openpyxl: https://stackoverflow.com/questions/31416842/
            #     openpyxl-does-not-close-excel-workbook-in-read-only-mode
            self.book.close()
        elif hasattr(self.book, "release_resources"):
            # xlrd
            # https://github.com/python-excel/xlrd/blob/2.0.1/xlrd/book.py#L548
            self.book.release_resources()
    self.handles.close()

def __new__(
    cls,
    path: FilePath | WriteExcelBuffer | ExcelWriter,
    engine: str | None = None,
    date_format: str | None = None,
    datetime_format: str | None = None,
    mode: str = "w",
    storage_options: StorageOptions | None = None,
    if_sheet_exists: ExcelWriterIfSheetExists | None = None,
    engine_kwargs: dict | None = None,
) -> Self:
    # only switch class if generic(ExcelWriter)
    if cls is ExcelWriter:
        if engine is None or (isinstance(engine, str) and engine == "auto"):
            if isinstance(path, str):
                ext = os.path.splitext(path)[-1][1:]
            else:
                ext = "xlsx"

            try:
                engine = config["io"]["excel"][ext]["writer"]
                if engine == "auto":
                    engine = get_default_engine(ext, mode="writer")
            except KeyError as err:
                raise ValueError(f"No engine for filetype: '{ext}'") from err

        # for mypy
        assert engine is not None
        #  error: Incompatible types in assignment (expression has type
        #  "type[ExcelWriter[Any]]", variable has type "type[Self]")
        cls = get_writer(engine)  # type: ignore[assignment]

    return object.__new__(cls)

def __init__(
    self,
    path: FilePath | WriteExcelBuffer | ExcelWriter,
    engine: str | None = None,
    date_format: str | None = None,
    datetime_format: str | None = None,
    mode: str = "w",
    storage_options: StorageOptions | None = None,
    if_sheet_exists: ExcelWriterIfSheetExists | None = None,
    engine_kwargs: dict[str, Any] | None = None,
) -> None:
    # validate that this engine can handle the extension
    if isinstance(path, str):
        ext = os.path.splitext(path)[-1]
        self.check_extension(ext)

    # use mode to open the file
    if "b" not in mode:
        mode += "b"
    # use "a" for the user to append data to excel but internally use "r+" to let
    # the excel backend first read the existing file and then write any data to it
    mode = mode.replace("a", "r+")

    if if_sheet_exists not in (None, "error", "new", "replace", "overlay"):
        raise ValueError(
            f"'{if_sheet_exists}' is not valid for if_sheet_exists. "
            "Valid options are 'error', 'new', 'replace' and 'overlay'."
        )
    if if_sheet_exists and "r+" not in mode:
        raise ValueError("if_sheet_exists is only valid in append mode (mode='a')")
    if if_sheet_exists is None:
        if_sheet_exists = "error"
    self._if_sheet_exists = if_sheet_exists

    # cast ExcelWriter to avoid adding 'if self._handles is not None'
    self._handles = IOHandles(
        cast("IO[bytes]", path), compression={"compression": None}
    )
    if not isinstance(path, ExcelWriter):
        self._handles = get_handle(
            path, mode, storage_options=storage_options, is_text=False
        )
    self._cur_sheet = None

    if date_format is None:
        self._date_format = "YYYY-MM-DD"
    else:
        self._date_format = date_format
    if datetime_format is None:
        self._datetime_format = "YYYY-MM-DD HH:MM:SS"
    else:
        self._datetime_format = datetime_format

    self._mode = mode

def _get_sheet_name(self, sheet_name: str | None) -> str:
    if sheet_name is None:
        sheet_name = self._cur_sheet
    if sheet_name is None:  # pragma: no cover
        raise ValueError("Must pass explicit sheet_name or set _cur_sheet property")
    return sheet_name

def check_extension(cls, ext: str) -> Literal[True]:
    """
    checks that path's extension against the Writer's supported
    extensions.  If it isn't supported, raises UnsupportedFiletypeError.
    """
    if ext.startswith("."):
        ext = ext[1:]
    if not any(ext in extension for extension in cls._supported_extensions):
        raise ValueError(f"Invalid extension for engine '{cls.engine}': '{ext}'")
    return True

def validate_freeze_panes(
    freeze_panes: tuple[int, int] | None,
) -> TypeGuard[tuple[int, int]]:
    if freeze_panes is not None:
        if len(freeze_panes) == 2 and all(
            isinstance(item, int) for item in freeze_panes
        ):
            return True

        raise ValueError(
            "freeze_panes must be of form (row, column) "
            "where row and column are integers"
        )

    # freeze_panes wasn't specified, return False so it won't be applied
    # to output sheet
    return False

def get_sheet_by_name(self, name: str):
    from odf.table import Table

    self.raise_if_bad_sheet_by_name(name)
    tables = self.book.getElementsByType(Table)

    for table in tables:
        if table.getAttribute("name") == name:
            return table

    self.close()
    raise ValueError(f"sheet {name} not found")

def get_sheet_data(
    self, sheet, file_rows_needed: int | None = None
) -> list[list[Scalar | NaTType]]:
    """
    Parse an ODF Table into a list of lists
    """
    from odf.namespaces import OFFICENS
    from odf.table import (
        CoveredTableCell,
        TableCell,
        TableRow,
    )

    covered_cell_name = CoveredTableCell().qname
    table_cell_name = TableCell().qname
    cell_names = {covered_cell_name, table_cell_name}

    sheet_rows = sheet.getElementsByType(TableRow)
    empty_rows = 0
    max_row_len = 0

    table: list[list[Scalar | NaTType]] = []

    for sheet_row in sheet_rows:
        empty_cells = 0
        table_row: list[Scalar | NaTType] = []

        for sheet_cell in sheet_row.childNodes:
            if hasattr(sheet_cell, "qname") and sheet_cell.qname in cell_names:
                value: Scalar | NaTType
                if (
                    sheet_cell.qname == covered_cell_name
                    and (OFFICENS, "value") not in sheet_cell.attributes
                ):
                    value = self.empty_value
                else:
                    value = self._get_cell_value(sheet_cell)

                column_repeat = self._get_column_repeat(sheet_cell)

                # Queue up empty values, writing only if content succeeds them
                if value == self.empty_value:
                    empty_cells += column_repeat
                else:
                    table_row.extend([self.empty_value] * empty_cells)
                    empty_cells = 0
                    table_row.extend([value] * column_repeat)

        if max_row_len < len(table_row):
            max_row_len = len(table_row)

        row_repeat = self._get_row_repeat(sheet_row)
        if len(table_row) == 0:
            empty_rows += row_repeat
        else:
            # add blank rows to our table
            table.extend([[self.empty_value]] * empty_rows)
            empty_rows = 0
            table.extend(table_row for _ in range(row_repeat))
        if file_rows_needed is not None and len(table) >= file_rows_needed:
            break

    # Make our table square
    for row in table:
        if len(row) < max_row_len:
            row.extend([self.empty_value] * (max_row_len - len(row)))

    return table

def _get_cell_value(self, cell) -> Scalar | NaTType:
    from odf.namespaces import OFFICENS

    if str(cell) == "#N/A":
        return np.nan

    cell_type = cell.attributes.get((OFFICENS, "value-type"))
    if cell_type == "boolean":
        if str(cell) == "TRUE":
            return True
        return False
    if cell_type is None:
        return self.empty_value
    elif cell_type == "float":
        # GH5394
        cell_value = float(cell.attributes.get((OFFICENS, "value")))
        val = int(cell_value)
        if val == cell_value:
            return val
        return cell_value
    elif cell_type == "percentage":
        cell_value = cell.attributes.get((OFFICENS, "value"))
        return float(cell_value)
    elif cell_type == "string":
        return self._get_cell_string_value(cell)
    elif cell_type == "currency":
        cell_value = cell.attributes.get((OFFICENS, "value"))
        return float(cell_value)
    elif cell_type == "date":
        cell_value = cell.attributes.get((OFFICENS, "date-value"))
        return pd.Timestamp(cell_value)
    elif cell_type == "time":
        stamp = pd.Timestamp(str(cell))
        # cast needed here because Scalar doesn't include datetime.time
        return cast("Scalar", stamp.time())
    else:
        self.close()
        raise ValueError(f"Unrecognized type {cell_type}")

def _get_cell_string_value(self, cell) -> str:
    """
    Find and decode OpenDocument text:s tags that represent
    a run length encoded sequence of space characters.
    """
    from odf.element import Element
    from odf.namespaces import (
        OFFICENS,
        TEXTNS,
    )

    # NB: built as plain tuples rather than from odf element instances,
    # since this runs once per cell.
    office_annotation = (OFFICENS, "annotation")
    text_s = (TEXTNS, "s")
    text_p = (TEXTNS, "p")
    text_line_break = (TEXTNS, "line-break")

    value = []
    seen_paragraph = False

    for fragment in cell.childNodes:
        if isinstance(fragment, Element):
            if fragment.qname == text_s:
                spaces = int(fragment.attributes.get((TEXTNS, "c"), 1))
                value.append(" " * spaces)
            elif fragment.qname == text_line_break:
                # GH#55728: an explicit line break within a paragraph.
                value.append("\n")
            elif fragment.qname == office_annotation:
                continue
            else:
                if fragment.qname == text_p:
                    # GH#53924: a cell holding several paragraphs shows them
                    # on separate lines, which is how LibreOffice and Excel
                    # store a multi-line cell.
                    if seen_paragraph:
                        value.append("\n")
                    seen_paragraph = True
                # recursive impl needed in case of nested fragments
                # with multiple spaces
                # https://github.com/pandas-dev/pandas/pull/36175#discussion_r484639704
                value.append(self._get_cell_string_value(fragment))
        else:
            value.append(str(fragment).strip("\n"))
    return "".join(value)

def _write_cells(
    self,
    cells,
    sheet_name: str | None = None,
    startrow: int = 0,
    startcol: int = 0,
    freeze_panes: tuple[int, int] | None = None,
    autofilter_range: str | None = None,
) -> None:
    # Write the frame cells using xlsxwriter.
    sheet_name = self._get_sheet_name(sheet_name)

    wks = self.book.get_worksheet_by_name(sheet_name)
    if wks is None:
        wks = self.book.add_worksheet(sheet_name)

    style_dict = {"null": None}

    if validate_freeze_panes(freeze_panes):
        wks.freeze_panes(*(freeze_panes))

    for cell in cells:
        val, fmt = self._value_with_fmt(cell.val)

        stylekey = json.dumps(cell.style)
        if fmt:
            stylekey += fmt

        if stylekey in style_dict:
            style = style_dict[stylekey]
        else:
            style = self.book.add_format(_XlsxStyler.convert(cell.style, fmt))
            style_dict[stylekey] = style

        if cell.mergestart is not None and cell.mergeend is not None:
            wks.merge_range(
                startrow + cell.row,
                startcol + cell.col,
                startrow + cell.mergestart,
                startcol + cell.mergeend,
                val,
                style,
            )
        else:
            wks.write(startrow + cell.row, startcol + cell.col, val, style)

    if autofilter_range:
        wks.autofilter(autofilter_range)

def get_sheet_data(
    self, sheet: CalamineSheet, file_rows_needed: int | None = None
) -> list[list[Scalar | NaTType | time]]:
    def _convert_cell(value: _CellValue) -> Scalar | NaTType | time:
        if isinstance(value, float):
            # GH#54564 - is_integer() returns False for NaN/Inf,
            # so this safely avoids int() on non-finite values
            if value.is_integer():
                return int(value)
            return value
        elif isinstance(value, (datetime, timedelta)):
            # Return as-is to match openpyxl behavior (GH#59186)
            return value
        elif isinstance(value, date):
            # Convert date to datetime to match openpyxl behavior (GH#59186)
            return datetime(value.year, value.month, value.day)
        elif isinstance(value, time):
            return value

        return value

    rows: list[list[_CellValue]] = sheet.to_python(
        skip_empty_area=False, nrows=file_rows_needed
    )
    data = [[_convert_cell(cell) for cell in row] for row in rows]

    return data

def _convert_cell(self, cell: Any) -> Scalar:
    # TODO: there is no way to distinguish between floats and datetimes in pyxlsb
    # This means that there is no way to read datetime types from an xlsb file yet
    if cell.v is None:
        return ""  # Prevents non-named columns from not showing up as Unnamed: i
    if isinstance(cell.v, float):
        val = int(cell.v)
        if val == cell.v:
            return val
        else:
            return float(cell.v)

    return cell.v

def get_sheet_data(
    self, sheet, file_rows_needed: int | None = None
) -> list[list[Scalar]]:
    from xlrd import (
        XL_CELL_BOOLEAN,
        XL_CELL_DATE,
        XL_CELL_ERROR,
        XL_CELL_NUMBER,
        xldate,
    )

    epoch1904 = self.book.datemode

    def _parse_cell(cell_contents, cell_typ):
        """
        converts the contents of the cell into a pandas appropriate object
        """
        if cell_typ == XL_CELL_DATE:
            # Use the newer xlrd datetime handling.
            try:
                cell_contents = xldate.xldate_as_datetime(cell_contents, epoch1904)
            except OverflowError:
                return cell_contents

            # Excel doesn't distinguish between dates and time,
            # so we treat dates on the epoch as times only.
            # Also, Excel supports 1900 and 1904 epochs.
            year = (cell_contents.timetuple())[0:3]
            if (not epoch1904 and year == (1899, 12, 31)) or (
                epoch1904 and year == (1904, 1, 1)
            ):
                cell_contents = time(
                    cell_contents.hour,
                    cell_contents.minute,
                    cell_contents.second,
                    cell_contents.microsecond,
                )

        elif cell_typ == XL_CELL_ERROR:
            cell_contents = np.nan
        elif cell_typ == XL_CELL_BOOLEAN:
            cell_contents = bool(cell_contents)
        elif cell_typ == XL_CELL_NUMBER:
            # GH5394 - Excel 'numbers' are always floats
            # it's a minimal perf hit and less surprising
            if math.isfinite(cell_contents):
                # GH54564 - don't attempt to convert NaN/Inf
                val = int(cell_contents)
                if val == cell_contents:
                    cell_contents = val
        return cell_contents

    nrows = sheet.nrows
    if file_rows_needed is not None:
        nrows = min(nrows, file_rows_needed)
    return [
        [
            _parse_cell(value, typ)
            for value, typ in zip(
                sheet.row_values(i), sheet.row_types(i), strict=True
            )
        ]
        for i in range(nrows)

def _write_cells(
    self,
    cells: list[ExcelCell],
    sheet_name: str | None = None,
    startrow: int = 0,
    startcol: int = 0,
    freeze_panes: tuple[int, int] | None = None,
    autofilter_range: str | None = None,
) -> None:
    """
    Write the frame cells using odf
    """

    if autofilter_range:
        raise ValueError("Autofilter is not supported with odf!")

    from odf.table import (
        Table,
        TableCell,
        TableRow,
    )
    from odf.text import (
        LineBreak,
        P,
    )

    sheet_name = self._get_sheet_name(sheet_name)
    assert sheet_name is not None

    if sheet_name in self.sheets:
        wks = self.sheets[sheet_name]
    else:
        wks = Table(name=sheet_name)
        self.book.spreadsheet.addElement(wks)

    if validate_freeze_panes(freeze_panes):
        self._create_freeze_panes(sheet_name, freeze_panes)

    for _ in range(startrow):
        wks.addElement(TableRow())

    rows: defaultdict[int, TableRow] = defaultdict(TableRow)
    col_count: defaultdict[int, int] = defaultdict(int)

    for cell in sorted(cells, key=lambda cell: (cell.row, cell.col)):
        # only add empty cells if the row is still empty
        if not col_count[cell.row]:
            for _ in range(startcol):
                rows[cell.row].addElement(TableCell())

        # fill with empty cells if needed
        for _ in range(cell.col - col_count[cell.row]):
            rows[cell.row].addElement(TableCell())
            col_count[cell.row] += 1

        pvalue, tc = self._make_table_cell(cell)
        rows[cell.row].addElement(tc)
        col_count[cell.row] += 1
        if isinstance(pvalue, str) and "\n" in pvalue:
            # GH#55728: a newline inside the paragraph text is collapsed to
            # a space by ODF consumers, so each line break is written as a
            # <text:line-break/> element instead.
            lines = pvalue.split("\n")
            p = P(text=lines[0])
            for line in lines[1:]:
                p.addElement(LineBreak())
                p.addText(line)
        else:
            p = P(text=pvalue)
        tc.addElement(p)

    # add all rows to the sheet
    if len(rows) > 0:
        for row_nr in range(max(rows.keys()) + 1):
            wks.addElement(rows[row_nr])

def _process_style(self, style: dict[str, Any] | None) -> str | None:
    """Convert a style dictionary to an OpenDocument style sheet

    Parameters
    ----------
    style : Dict
        Style dictionary

    Returns
    -------
    style_key : str
        Unique style key for later reference in sheet
    """
    from odf.style import (
        ParagraphProperties,
        Style,
        TableCellProperties,
        TextProperties,
    )

    if style is None:
        return None
    style_key = json.dumps(style)
    if style_key in self._style_dict:
        return self._style_dict[style_key]
    name = f"pd{len(self._style_dict) + 1}"
    self._style_dict[style_key] = name
    odf_style = Style(name=name, family="table-cell")
    if "font" in style:
        font = style["font"]
        if font.get("bold", False):
            odf_style.addElement(TextProperties(fontweight="bold"))
    if "borders" in style:
        borders = style["borders"]
        for side, thickness in borders.items():
            thickness_translation = {"thin": "0.75pt solid #000000"}
            odf_style.addElement(
                TableCellProperties(
                    attributes={f"border{side}": thickness_translation[thickness]}
                )
            )
    if "alignment" in style:
        alignment = style["alignment"]
        horizontal = alignment.get("horizontal")
        if horizontal:
            odf_style.addElement(ParagraphProperties(textalign=horizontal))
        vertical = alignment.get("vertical")
        if vertical:
            odf_style.addElement(TableCellProperties(verticalalign=vertical))
    self.book.styles.addElement(odf_style)
    return name

def _convert_to_fill(cls, fill_dict: dict[str, Any]) -> Fill:
    """
    Convert ``fill_dict`` to an openpyxl v2 Fill object.

    Parameters
    ----------
    fill_dict : dict
        A dict with one or more of the following keys (or their synonyms),
            'fill_type' ('patternType', 'patterntype')
            'start_color' ('fgColor', 'fgcolor')
            'end_color' ('bgColor', 'bgcolor')
        or one or more of the following keys (or their synonyms).
            'type' ('fill_type')
            'degree'
            'left'
            'right'
            'top'
            'bottom'
            'stop'

    Returns
    -------
    fill : openpyxl.styles.Fill
    """
    from openpyxl.styles import (
        GradientFill,
        PatternFill,
    )

    _pattern_fill_key_map = {
        "patternType": "fill_type",
        "patterntype": "fill_type",
        "fgColor": "start_color",
        "fgcolor": "start_color",
        "bgColor": "end_color",
        "bgcolor": "end_color",
    }

    _gradient_fill_key_map = {"fill_type": "type"}

    pfill_kwargs = {}
    gfill_kwargs = {}
    for k, v in fill_dict.items():
        pk = _pattern_fill_key_map.get(k)
        gk = _gradient_fill_key_map.get(k)
        if pk in ["start_color", "end_color"]:
            v = cls._convert_to_color(v)
        if gk == "stop":
            v = cls._convert_to_stop(v)
        if pk:
            pfill_kwargs[pk] = v
        elif gk:
            gfill_kwargs[gk] = v
        else:
            pfill_kwargs[k] = v
            gfill_kwargs[k] = v

    try:
        return PatternFill(**pfill_kwargs)
    except TypeError:
        return GradientFill(**gfill_kwargs)

def _convert_to_side(cls, side_spec):
    """
    Convert ``side_spec`` to an openpyxl v2 Side object.

    Parameters
    ----------
    side_spec : str, dict
        A string specifying the border style, or a dict with zero or more
        of the following keys (or their synonyms).
            'style' ('border_style')
            'color'

    Returns
    -------
    side : openpyxl.styles.Side
    """
    from openpyxl.styles import Side

    _side_key_map = {"border_style": "style"}

    if isinstance(side_spec, str):
        return Side(style=side_spec)

    side_kwargs = {}
    for k, v in side_spec.items():
        k = _side_key_map.get(k, k)
        if k == "color":
            v = cls._convert_to_color(v)
        side_kwargs[k] = v

    return Side(**side_kwargs)

def _write_cells_normal(
    self,
    cells,
    wks,
    startrow: int,
    startcol: int,
    freeze_panes: tuple[int, int] | None,
    autofilter_range: str | None,
    _style_cache: dict[str, dict[str, Serialisable]],
) -> None:
    if validate_freeze_panes(freeze_panes):
        wks.freeze_panes = wks.cell(
            row=freeze_panes[0] + 1, column=freeze_panes[1] + 1
        )

    for cell in cells:
        xcell = wks.cell(
            row=startrow + cell.row + 1, column=startcol + cell.col + 1
        )
        xcell.value, fmt = self._value_with_fmt(cell.val)
        if fmt:
            xcell.number_format = fmt

        style_kwargs: dict[str, Serialisable] | None = {}
        if cell.style:
            key = str(cell.style)
            style_kwargs = _style_cache.get(key)
            if style_kwargs is None:
                style_kwargs = self._convert_to_style_kwargs(cell.style)
                _style_cache[key] = style_kwargs

        if style_kwargs:
            for attr, value in style_kwargs.items():
                setattr(xcell, attr, value)

        if cell.mergestart is not None and cell.mergeend is not None:
            wks.merge_cells(
                start_row=startrow + cell.row + 1,
                start_column=startcol + cell.col + 1,
                end_column=startcol + cell.mergeend + 1,
                end_row=startrow + cell.mergestart + 1,
            )

            # When cells are merged only the top-left cell is preserved
            # The behaviour of the other cells in a merged range is
            # undefined
            if style_kwargs:
                first_row = startrow + cell.row + 1
                last_row = startrow + cell.mergestart + 1
                first_col = startcol + cell.col + 1
                last_col = startcol + cell.mergeend + 1

                for row in range(first_row, last_row + 1):
                    for col in range(first_col, last_col + 1):
                        if row == first_row and col == first_col:
                            # Ignore first cell. It is already handled.
                            continue
                        xcell = wks.cell(column=col, row=row)
                        for attr, value in style_kwargs.items():
                            setattr(xcell, attr, value)

    if autofilter_range:
        wks.auto_filter.ref = autofilter_range

def _convert_cell(self, cell) -> Scalar:
    from openpyxl.cell.cell import (
        TYPE_ERROR,
        TYPE_NUMERIC,
    )

    if cell.value is None:
        return ""  # compat with xlrd
    elif cell.data_type == TYPE_ERROR:
        return np.nan
    elif cell.data_type == TYPE_NUMERIC:
        val = int(cell.value)
        if val == cell.value:
            return val
        return float(cell.value)

    return cell.value

def get_sheet_data(
    self, sheet, file_rows_needed: int | None = None
) -> list[list[Scalar]]:
    saved_dimensions: tuple[int | None, int | None] | None = None
    if self.book.read_only:
        # Declared sheet dimensions can be incorrect, so have openpyxl
        # infer the real extent while iterating (GH 39486); save them to
        # restore the user's worksheet handle afterwards (GH 63010)
        saved_dimensions = (sheet.max_row, sheet.max_column)
        sheet.reset_dimensions()

    data: list[list[Scalar]] = []
    last_row_with_data = -1
    try:
        for row_number, row in enumerate(sheet.rows):
            converted_row = [self._convert_cell(cell) for cell in row]
            while converted_row and converted_row[-1] == "":
                # trim trailing empty elements
                converted_row.pop()
            if converted_row:
                last_row_with_data = row_number
            data.append(converted_row)
            if file_rows_needed is not None and len(data) >= file_rows_needed:
                break
    finally:
        if saved_dimensions is not None:
            # max_row/max_column of a read-only worksheet have no setters
            sheet._max_row, sheet._max_column = saved_dimensions

    # Trim trailing empty rows
    data = data[: last_row_with_data + 1]

    if len(data) > 0:
        # extend rows to max width
        max_width = max(len(data_row) for data_row in data)
        if min(len(data_row) for data_row in data) < max_width:
            empty_cell: list[Scalar] = [""]
            data = [
                data_row + (max_width - len(data_row)) * empty_cell
                for data_row in data
            ]

    return data

def _from_nested_dict(
    data: Mapping[HashableT, Mapping[HashableT2, T]],
) -> collections.defaultdict[HashableT2, dict[HashableT, T]]:
    new_data: collections.defaultdict[HashableT2, dict[HashableT, T]] = (
        collections.defaultdict(dict)
    )
    for index, s in data.items():
        for col, v in s.items():
            new_data[col][index] = v
    return new_data

def _reindex_for_setitem(
    value: DataFrame | Series, index: Index
) -> tuple[ArrayLike, BlockValuesRefs | None]:
    # reindex if necessary

    if value.index.equals(index) or not len(index):
        if isinstance(value, Series):
            return value._values, value._references
        return value._values.copy(), None

    # GH#4107
    try:
        reindexed_value = value.reindex(index)._values
    except ValueError as err:
        # raised in MultiIndex.from_tuples, see test_insert_error_msmgs
        if not value.index.is_unique:
            # duplicate axis
            raise err

        raise TypeError(
            "incompatible index of inserted column with frame index"
        ) from err
    return reindexed_value, None

def __rmatmul__(self, other) -> DataFrame:
    """
    Matrix multiplication using binary `@` operator.
    """
    try:
        return self.T.dot(np.transpose(other)).T
    except ValueError as err:
        if "shape mismatch" not in str(err):
            raise
        # GH#21581 give exception message for original shapes
        msg = f"shapes {np.shape(other)} and {self.shape} not aligned"
        raise ValueError(msg) from err

def __getitem__(self, key):
    check_dict_or_set_indexers(key)
    key = lib.item_from_zerodim(key)
    key = com.apply_if_callable(key, self)

    if is_hashable(key, allow_slice=False) and not is_iterator(key):
        # is_iterator to exclude generator e.g. test_getitem_listlike
        # As of Python 3.12, slice is hashable which breaks MultiIndex (GH#57500)

        # Shortcut: return single column as Series when key refers to one column.
        # Previously we used "key in self.columns.drop_duplicates(keep=False)",
        # which built a new Index on every access when columns had duplicates.
        # Using get_loc(key) instead: it returns int iff key appears exactly once,
        # so we get the same behavior without extra allocation (GH#45316).
        is_mi = isinstance(self.columns, MultiIndex)
        if not is_mi:
            try:
                loc = self.columns.get_loc(key)
            except (KeyError, InvalidIndexError):
                # Key missing or invalid; fall through to list/slice/other paths.
                pass
            else:
                # int: key unique; slice/array: key duplicated (fall through).
                if isinstance(loc, int):
                    return self._get_item(key)
        elif is_mi and self.columns.is_unique and key in self.columns:
            return self._getitem_multilevel(key)

    # Do we have a slicer (on rows)?
    if isinstance(key, slice):
        return self._getitem_slice(key)

    # Do we have a (boolean) DataFrame?
    if isinstance(key, DataFrame):
        return self.where(key)

    # Do we have a (boolean) 1d indexer?
    if com.is_bool_indexer(key):
        return self._getitem_bool_array(key)

    # We are left with two options: a single key, and a collection of keys,
    # We interpret tuples as collections only for non-MultiIndex
    is_single_key = isinstance(key, tuple) or not is_list_like(key)

    if is_single_key:
        if self.columns.nlevels > 1:
            return self._getitem_multilevel(key)
        indexer = self.columns.get_loc(key)
        if is_integer(indexer):
            indexer = [indexer]  # type: ignore[assignment]
    else:
        if is_iterator(key):
            key = list(key)
        indexer = self.columns._get_indexer_strict(key, "columns")[1]

    # take() does not accept boolean indexers
    if getattr(indexer, "dtype", None) == bool:
        indexer = np.where(indexer)[0]  # type: ignore[arg-type, assignment]

    if isinstance(indexer, slice):
        return self._slice(indexer, axis=1)

    data = self.take(indexer, axis=1)

    if is_single_key:
        # What does looking for a single key in a non-unique index return?
        # The behavior is inconsistent. It returns a Series, except when
        # - the key itself is repeated (test on data.shape, #9519), or
        # - we have a MultiIndex on columns (test on self.columns, #21309)
        if data.shape[1] == 1 and not isinstance(self.columns, MultiIndex):
            # GH#26490 using data[key] can cause RecursionError
            return data._get_item(key)

    return data

def _getitem_bool_array(self, key):
    # also raises Exception if object array with NA values
    # warning here just in case -- previously __setitem__ was
    # reindexing but __getitem__ was not; it seems more reasonable to
    # go with the __setitem__ behavior since that is more consistent
    # with all other indexing behavior
    if isinstance(key, Series) and not key.index.equals(self.index):
        warnings.warn(
            "Boolean Series key will be reindexed to match DataFrame index.",
            UserWarning,
            stacklevel=find_stack_level(),
        )
    elif len(key) != len(self.index):
        raise ValueError(
            f"Item wrong length {len(key)} instead of {len(self.index)}."
        )

    # check_bool_indexer will throw exception if Series key cannot
    # be reindexed to match DataFrame rows
    key = check_bool_indexer(self.index, key)

    if key.all():
        return self.copy(deep=False)

    indexer = key.nonzero()[0]
    return self.take(indexer, axis=0)

def _setitem_array(self, key, value) -> None:
    # also raises Exception if object array with NA values
    if com.is_bool_indexer(key):
        # bool indexer is indexing along rows
        if len(key) != len(self.index):
            raise ValueError(
                f"Item wrong length {len(key)} instead of {len(self.index)}!"
            )
        key = check_bool_indexer(self.index, key)
        indexer = key.nonzero()[0]
        if isinstance(value, DataFrame):
            # GH#39931 reindex since iloc does not align
            value = value.reindex(self.index.take(indexer))
        self.iloc[indexer] = value

    # Note: unlike self.iloc[:, indexer] = value, this will
    #  never try to overwrite values inplace

    elif isinstance(value, DataFrame):
        check_key_length(self.columns, key, value)
        for k1, k2 in zip(key, value.columns, strict=False):
            self[k1] = value[k2]

    elif not is_list_like(value):
        for col in key:
            self[col] = value

    elif isinstance(value, np.ndarray) and value.ndim == 2:
        self._iset_not_inplace(key, value)

    elif np.ndim(value) > 1:
        # list of lists
        value = DataFrame(value).values
        self._setitem_array(key, value)

    else:
        self._iset_not_inplace(key, value)

def _iset_not_inplace(self, key, value) -> None:
    # GH#39510 when setting with df[key] = obj with a list-like key and
    #  list-like value, we iterate over those listlikes and set columns
    #  one at a time.  This is different from dispatching to
    #  `self.loc[:, key]= value`  because loc.__setitem__ may overwrite
    #  data inplace, whereas this will insert new arrays.

    def igetitem(obj, i: int):
        # Note: we catch DataFrame obj before getting here, but
        #  hypothetically would return obj.iloc[:, i]
        if isinstance(obj, np.ndarray):
            return obj[..., i]
        else:
            return obj[i]

    if self.columns.is_unique:
        if np.shape(value)[-1] != len(key):
            raise ValueError("Columns must be same length as key")

        for i, col in enumerate(key):
            self[col] = igetitem(value, i)

    else:
        ilocs = self.columns.get_indexer_non_unique(key)[0]
        if lib.has_sentinel(ilocs, -1):
            # key entries not in self.columns
            raise NotImplementedError

        if np.shape(value)[-1] != len(ilocs):
            raise ValueError("Columns must be same length as key")

        assert np.ndim(value) <= 2

        orig_columns = self.columns

        # Using self.iloc[:, i] = ... may set values inplace, which
        #  by convention we do not do in __setitem__
        try:
            self.columns = Index(range(len(self.columns)))
            for i, iloc in enumerate(ilocs):
                self[iloc] = igetitem(value, i)
        finally:
            self.columns = orig_columns

def _setitem_frame(self, key, value) -> None:
    # support boolean setting with DataFrame input, e.g.
    # df[df > df2] = 0
    if isinstance(key, np.ndarray):
        if key.shape != self.shape:
            raise ValueError("Array conditional must be same shape as self")
        key = self._constructor(key, **self._construct_axes_dict(), copy=False)

    if key.size and not all(is_bool_dtype(dtype) for dtype in key._blk_dtypes):
        raise TypeError(
            "Must pass DataFrame or 2-d ndarray with boolean values only"
        )

    try:
        self._where(-key, value, inplace=True)
    except ValueError as err:
        # GH#45593 restate putmask_without_repeat's message with the
        #  mismatched lengths.
        if "mismatch length to masked array" not in str(err):
            raise
        num_true = int(key.to_numpy(dtype=bool, na_value=False).sum())
        num_values = len(value) if is_list_like(value) else 1
        raise ValueError(
            f"Cannot set with a boolean DataFrame mask: the number of "
            f"values ({num_values}) does not match the number of True "
            f"entries in the mask ({num_true}). Provide a scalar or a "
            f"value matching the mask."
        ) from err

def _set_item_frame_value(self, key, value: DataFrame) -> None:
    self._ensure_valid_index(value)

    # align columns
    if key in self.columns:
        loc = self.columns.get_loc(key)
        cols = self.columns[loc]
        len_cols = 1 if is_scalar(cols) or isinstance(cols, tuple) else len(cols)
        if len_cols != len(value.columns):
            raise ValueError("Columns must be same length as key")

        # align right-hand-side columns if self.columns
        # is multi-index and self[key] is a sub-frame
        if isinstance(self.columns, MultiIndex) and isinstance(
            loc, (slice, Series, np.ndarray, Index)
        ):
            cols_droplevel = maybe_droplevels(cols, key)
            if len(cols_droplevel) and not cols_droplevel.equals(value.columns):
                if (
                    not isinstance(cols_droplevel, MultiIndex)
                    and is_string_dtype(cols_droplevel.dtype)
                    and (cols_droplevel == "").all()
                ):
                    # if cols_droplevel contains only empty strings,
                    # value.reindex(cols_droplevel, axis=1) would be full of NaNs
                    # see GH#62518 and GH#61841
                    value = value.copy(deep=False)
                    value.columns = cols_droplevel
                else:
                    value = value.reindex(cols_droplevel, axis=1)

            if not cols_droplevel.equals(cols):
                # Levels were actually dropped, so we can safely use
                # key-based indexing without re-entering this method.
                for col, col_droplevel in zip(cols, cols_droplevel, strict=True):
                    self[col] = value[col_droplevel]
                return
            # If cols_droplevel == cols (key matched all levels),
            # fall through to positional isetitem to avoid
            # infinite recursion (GH#53498).

        if is_scalar(cols):
            self[cols] = value[value.columns[0]]
            return

        locs: np.ndarray | list
        if isinstance(loc, slice):
            locs = np.arange(loc.start, loc.stop, loc.step)
        elif is_scalar(loc):
            locs = [loc]
        else:
            locs = loc.nonzero()[0]  # type: ignore[union-attr]

        return self.isetitem(locs, value)

    if len(value.columns) > 1:
        raise ValueError(
            "Cannot set a DataFrame with multiple columns to the single "
            f"column {key}"
        )
    elif len(value.columns) == 0:
        raise ValueError(
            f"Cannot set a DataFrame without columns to the column {key}"
        )

    self[key] = value[value.columns[0]]

def _set_item_mgr(
    self, key, value: ArrayLike, refs: BlockValuesRefs | None = None
) -> None:
    try:
        loc = self._info_axis.get_loc(key)
    except KeyError:
        # This item wasn't present, just insert at end
        self._mgr.insert(len(self._info_axis), key, value, refs)
    else:
        self._iset_item_mgr(loc, value, refs=refs)

def _ensure_valid_index(self, value) -> None:
    """
    Ensure that if we don't have an index, that we can create one from the
    passed value.
    """
    # GH5632, make sure that we are a Series convertible
    if not len(self.index) and is_list_like(value) and len(value):
        if not isinstance(value, DataFrame):
            try:
                value = Series(value)
            except (ValueError, NotImplementedError, TypeError) as err:
                raise ValueError(
                    "Cannot set a frame with no defined index "
                    "and a value that cannot be converted to a Series"
                ) from err

        # GH31368 preserve name of index
        index_copy = value.index.copy()
        if self.index.name is not None:
            index_copy.name = self.index.name

        self._mgr = self._mgr.reindex_axis(index_copy, axis=1, fill_value=np.nan)

def _flex_arith_method(
    self, other, op, *, axis: Axis = "columns", level=None, fill_value=None
):
    axis = self._get_axis_number(axis) if axis is not None else 1

    if self._should_reindex_frame_op(other, op, axis, fill_value, level):
        return self._arith_method_with_reindex(other, op)

    other = ops.maybe_prepare_scalar_for_op(other, self.shape)
    self, other = self._align_for_op(other, axis, flex=True, level=level)

    with np.errstate(all="ignore"):
        if isinstance(other, DataFrame):
            # Another DataFrame
            new_data = self._combine_frame(other, op, fill_value)

        elif isinstance(other, Series):
            new_data = self._dispatch_frame_op(other, op, axis=axis)
        else:
            # in this case we always have `np.ndim(other) == 0`
            if fill_value is not None:
                self = self.fillna(fill_value)

            new_data = self._dispatch_frame_op(other, op)

    return self._construct_result(new_data, other=other)

def _get_agg_axis(self, axis_num: int) -> Index:
    """
    Let's be explicit about this.
    """
    if axis_num == 0:
        return self.columns
    elif axis_num == 1:
        return self.index
    else:
        raise ValueError(f"Axis must be 0 or 1 (got {axis_num!r})")

def from_columns(cls, columns: Index) -> _DuplicateColumnRecorder:
    # _get_cleaned_column_resolvers keys on the cleaned name and lets the
    # last label win, and clean_column_name is not injective, so work out
    # which label each name resolves to before asking whether that one is
    # duplicated.
    resolved = dict(
        zip(
            (clean_column_name(label) for label in columns),
            columns.duplicated(keep=False),
            strict=True,
        )
    )
    return cls({name for name, is_duplicated in resolved.items() if is_duplicated})

def nargminmax(
    values: ExtensionArray, method: str, axis: AxisInt = 0
) -> int | np.ndarray:
    """
    Implementation of np.argmin/argmax but for ExtensionArray and which
    handles missing values.

    Parameters
    ----------
    values : ExtensionArray
    method : {"argmax", "argmin"}
    axis : int, default 0

    Returns
    -------
    int
    """
    assert method in {"argmax", "argmin"}
    func = np.argmax if method == "argmax" else np.argmin

    mask = np.asarray(isna(values))
    arr_values = values._values_for_argsort()

    if arr_values.ndim > 1:
        if mask.any():
            if axis == 1:
                zipped = zip(arr_values, mask, strict=True)
            else:
                zipped = zip(arr_values.T, mask.T, strict=True)
            return np.array([_nanargminmax(v, m, func) for v, m in zipped])
        return func(arr_values, axis=axis)

    return _nanargminmax(arr_values, mask, func)

def ensure_key_mapped(
    values: ArrayLike | Index | Series,
    key: Callable | None,
    levels: Level | list[Level] | None = None,
) -> ArrayLike | Index | Series:
    """
    Applies a callable key function to the values function and checks
    that the resulting value has the same shape. Can be called on Index
    subclasses, Series, DataFrames, or ndarrays.

    Parameters
    ----------
    values : Series, DataFrame, Index subclass, or ndarray
    key : Optional[Callable], key to be called on the values array
    levels : Optional[List], if values is a MultiIndex, list of levels to
    apply the key to.
    """
    from pandas.core.indexes.api import Index

    if not key:
        return values

    if isinstance(values, ABCMultiIndex):
        return _ensure_key_mapped_multiindex(values, key, level=levels)

    result = key(values.copy())
    if len(result) != len(values):
        raise ValueError(
            "User-provided `key` function must not change the shape of the array."
        )

    try:
        if isinstance(
            values, Index
        ):  # convert to a new Index subclass, not necessarily the same
            result = Index(result, tupleize_cols=False)
        else:
            # try to revert to original type otherwise
            type_of_values = type(values)
            #  error: Too many arguments for "ExtensionArray"
            result = type_of_values(result)  # type: ignore[call-arg]
    except TypeError as err:
        raise TypeError(
            f"User-provided `key` function returned an invalid type {type(result)} \
            which could not be converted to {type(values)}."
        ) from err

    return result

def preprocess_weights(
    obj: NDFrame, weights: str | ListLike, axis: AxisInt
) -> np.ndarray:
    """
    Process and validate the `weights` argument to `NDFrame.sample` and
    `.GroupBy.sample`.

    Returns `weights` as an ndarray[np.float64], validated except for normalizing
    weights (because that must be done groupwise in groupby sampling).
    """
    # If a series, align with frame
    if isinstance(weights, ABCSeries):
        weights = weights.reindex(obj.axes[axis])

    # Strings acceptable if a dataframe and axis = 0
    if isinstance(weights, str):
        if isinstance(obj, ABCDataFrame):
            if axis == 0:
                try:
                    weights = obj[weights]
                except KeyError as err:
                    raise KeyError(
                        "String passed to weights not a valid column"
                    ) from err
            else:
                raise ValueError(
                    "Strings can only be passed to "
                    "weights when sampling from rows on "
                    "a DataFrame"
                )
        else:
            raise ValueError(
                "Strings cannot be passed as weights when sampling from a Series."
            )

    if isinstance(obj, ABCSeries):
        func = obj._constructor
    else:
        func = obj._constructor_sliced

    weights_arr = np.asarray(func(weights, dtype="float64")._values, dtype=np.float64)

    if len(weights_arr) != obj.shape[axis]:
        raise ValueError("Weights and axis to be sampled must be of same length")

    if lib.has_infs(weights_arr):
        raise ValueError("weights vector may not include `inf` values")

    if (weights_arr < 0).any():
        raise ValueError("weights vector may not include negative values")

    missing = np.isnan(weights_arr)
    if missing.any():
        # Don't modify weights in place
        weights_arr = weights_arr.copy()
        weights_arr[missing] = 0
    return weights_arr

def process_sampling_size(
    n: int | None, frac: float | None, replace: bool
) -> int | None:
    """
    Process and validate the `n` and `frac` arguments to `NDFrame.sample` and
    `.GroupBy.sample`.

    Returns None if `frac` should be used (variable sampling sizes), otherwise returns
    the constant sampling size.
    """
    # If no frac or n, default to n=1.
    if n is None and frac is None:
        n = 1
    elif n is not None and frac is not None:
        raise ValueError("Please enter a value for `frac` OR `n`, not both")
    elif n is not None:
        if n < 0:
            raise ValueError(
                "A negative number of rows requested. Please provide `n` >= 0."
            )
        if n % 1 != 0:
            raise ValueError("Only integers accepted as `n` values")
    else:
        assert frac is not None  # for mypy
        if frac > 1 and not replace:
            raise ValueError(
                "Replace has to be set to `True` when "
                "upsampling the population `frac` > 1."
            )
        if frac < 0:
            raise ValueError(
                "A negative number of rows requested. Please provide `frac` >= 0."
            )

    return n

def _dir_additions(self) -> set[str]:
    """
    Add additional __dir__ for this object.
    """
    return {accessor for accessor in self._accessors if hasattr(self, accessor)}

def _add_delegate_accessors(
    cls,
    delegate,
    accessors: list[str],
    typ: str,
    overwrite: bool = False,
    accessor_mapping: Callable[[str], str] = lambda x: x,
    raise_on_missing: bool = True,
) -> None:
    """
    Add accessors to cls from the delegate class.

    Parameters
    ----------
    cls
        Class to add the methods/properties to.
    delegate
        Class to get methods/properties and docstrings.
    accessors : list of str
        List of accessors to add.
    typ : {'property', 'method'}
    overwrite : bool, default False
        Overwrite the method/property in the target class if it exists.
    accessor_mapping: Callable, default lambda x: x
        Callable to map the delegate's function to the cls' function.
    raise_on_missing: bool, default True
        Raise if an accessor does not exist on delegate.
        False skips the missing accessor.
    """

    def _create_delegator_property(name: str):
        def _getter(self):
            return self._delegate_property_get(name)

        def _setter(self, new_values):
            return self._delegate_property_set(name, new_values)

        _getter.__name__ = name
        _setter.__name__ = name

        return property(
            fget=_getter,
            fset=_setter,
            doc=getattr(delegate, accessor_mapping(name)).__doc__,
        )

    def _create_delegator_method(name: str):
        method = getattr(delegate, accessor_mapping(name))

        @functools.wraps(method)
        def f(self, *args, **kwargs):
            return self._delegate_method(name, *args, **kwargs)

        return f

    for name in accessors:
        if (
            not raise_on_missing
            and getattr(delegate, accessor_mapping(name), None) is None
        ):
            continue

        if typ == "property":
            f = _create_delegator_property(name)
        else:
            f = _create_delegator_method(name)

        # don't overwrite existing methods/properties
        if overwrite or not hasattr(cls, name):
            setattr(cls, name, f)

def _pretty_print_args_kwargs(*args: Any, **kwargs: Any) -> str:
    inputs_repr = ", ".join(repr(arg) for arg in args)
    kwargs_repr = ", ".join(f"{k}={v!r}" for k, v in kwargs.items())

    all_args = []
    if inputs_repr:
        all_args.append(inputs_repr)
    if kwargs_repr:
        all_args.append(kwargs_repr)

    return ", ".join(all_args)

def _maybe_wrap_parentheses(self, other: Any) -> tuple[str, str]:
    if self._needs_parentheses:
        self_repr = f"({self!r})"
    else:
        self_repr = f"{self!r}"
    if isinstance(other, Expression) and other._needs_parentheses:
        other_repr = f"({other!r})"
    else:
        other_repr = f"{other!r}"
    return self_repr, other_repr

def ensure_wrapped_if_datetimelike(arr):
    """
    Wrap datetime64 and timedelta64 ndarrays in DatetimeArray/TimedeltaArray.
    """
    if isinstance(arr, np.ndarray):
        if arr.dtype.kind == "M":
            from pandas.core.arrays import DatetimeArray

            dtype = get_supported_dtype(arr.dtype)
            return DatetimeArray._from_sequence(arr, dtype=dtype)

        elif arr.dtype.kind == "m":
            from pandas.core.arrays import TimedeltaArray

            dtype = get_supported_dtype(arr.dtype)
            return TimedeltaArray._from_sequence(arr, dtype=dtype)

    return arr

def range_to_ndarray(rng: range) -> np.ndarray:
    """
    Cast a range object to ndarray.
    """
    # GH#30171 perf avoid realizing range as a list in np.array
    try:
        arr = np.arange(rng.start, rng.stop, rng.step, dtype="int64")
    except OverflowError:
        # GH#30173 handling for ranges that overflow int64
        if (rng.start >= 0 and rng.step > 0) or (rng.step < 0 <= rng.stop):
            try:
                arr = np.arange(rng.start, rng.stop, rng.step, dtype="uint64")
            except OverflowError:
                arr = construct_1d_object_array_from_listlike(list(rng))
        else:
            arr = construct_1d_object_array_from_listlike(list(rng))
    return arr

def _sanitize_str_dtypes(
    result: np.ndarray, data, dtype: np.dtype | None, copy: bool
) -> np.ndarray:
    """
    Ensure we have a dtype that is supported by pandas.
    """

    # This is to prevent mixed-type Series getting all casted to
    # NumPy string type, e.g. NaN --> '-1#IND'.
    if issubclass(result.dtype.type, str):
        # GH#16605
        # If not empty convert the data to dtype
        # GH#19853: If data is a scalar, result has already the result
        if not lib.is_scalar(data):
            if not np.all(isna(data)):
                data = np.asarray(data, dtype=dtype)
            if not copy:
                result = np.asarray(data, dtype=object)
            else:
                result = np.array(data, dtype=object, copy=copy)
    return result

def _maybe_repeat(arr: ArrayLike, index: Index | None) -> ArrayLike:
    """
    If we have a length-1 array and an index describing how long we expect
    the result to be, repeat the array.
    """
    if index is not None:
        if 1 == len(arr) != len(index):
            arr = arr.repeat(len(index))
    return arr

def _try_cast(
    arr: list | np.ndarray,
    dtype: np.dtype,
    copy: bool,
) -> ArrayLike:
    """
    Convert input to numpy ndarray and optionally cast to a given dtype.

    Parameters
    ----------
    arr : ndarray or list
        Excludes: ExtensionArray, Series, Index.
    dtype : np.dtype
    copy : bool
        If False, don't copy the data if not needed.

    Returns
    -------
    np.ndarray or ExtensionArray
    """
    is_ndarray = isinstance(arr, np.ndarray)

    if dtype == object:
        if not is_ndarray:
            subarr = construct_1d_object_array_from_listlike(arr)
            return subarr
        return ensure_wrapped_if_datetimelike(arr).astype(dtype, copy=copy)

    elif dtype.kind == "U":
        # TODO: test cases with arr.dtype.kind in "mM"
        if is_ndarray:
            arr = cast("np.ndarray", arr)
            shape = arr.shape
            if arr.ndim > 1:
                arr = arr.ravel()
        else:
            shape = (len(arr),)
        return lib.ensure_string_array(arr, convert_na_value=False, copy=copy).reshape(
            shape
        )

    elif dtype.kind in "mM":
        if is_ndarray:
            arr = cast("np.ndarray", arr)
            if arr.ndim == 2 and arr.shape[1] == 1:
                # GH#60081: DataFrame Constructor converts 1D data to array of
                # shape (N, 1), but maybe_cast_to_datetime assumes 1D input
                return maybe_cast_to_datetime(arr[:, 0], dtype).reshape(arr.shape)
        return maybe_cast_to_datetime(arr, dtype)

    # GH#15832: Check if we are requesting a numeric dtype and
    # that we can convert the data to the requested dtype.
    elif dtype.kind in "iu":
        # this will raise if we have e.g. floats

        subarr = maybe_cast_to_integer_array(arr, dtype)
    elif not copy:
        subarr = np.asarray(arr, dtype=dtype)
    else:
        subarr = np.array(arr, dtype=dtype, copy=copy)

    return subarr

def allows_duplicate_labels(self, value: bool) -> None:
    value = bool(value)
    obj = self._obj()
    if obj is None:
        raise ValueError("This flag's object has been deleted.")

    if not value:
        for ax in obj.axes:
            ax._maybe_check_unique()

    self._allows_duplicate_labels = value

def maybe_convert_ix(*args):
    """
    We likely want to take the cross-product.
    """
    for arg in args:
        if not isinstance(arg, (np.ndarray, list, ABCSeries, Index)):
            return args
    return np.ix_(*args)

def is_nested_tuple(tup, labels) -> bool:
    """
    Returns
    -------
    bool
    """
    # check for a compatible nested tuple and multiindexes among the axes
    if not isinstance(tup, tuple):
        return False

    for k in tup:
        if is_list_like(k) or isinstance(k, slice):
            return isinstance(labels, MultiIndex)

    return False

def check_dict_or_set_indexers(key) -> None:
    """
    Check if the indexer is or contains a dict or set, which is no longer allowed.
    """
    if isinstance(key, set) or (
        isinstance(key, tuple) and any(isinstance(x, set) for x in key)
    ):
        raise TypeError(
            "Passing a set as an indexer is not supported. Use a list instead."
        )

    if isinstance(key, dict) or (
        isinstance(key, tuple) and any(isinstance(x, dict) for x in key)
    ):
        raise TypeError(
            "Passing a dict as an indexer is not supported. Use a list instead."

def _get_setitem_indexer(self, key):
    """
    Convert a potentially-label-based key into a positional indexer.
    """
    if self.name == "loc":
        # always holds here bc iloc overrides _get_setitem_indexer
        self._ensure_listlike_indexer(key, axis=self.axis)

    if isinstance(key, tuple):
        for x in key:
            check_dict_or_set_indexers(x)

    if self.axis is not None:
        key = _tupleize_axis_indexer(self.ndim, self.axis, key)

    ax = self.obj._get_axis(0)

    if (
        isinstance(ax, MultiIndex)
        and self.name != "iloc"
        and is_hashable(key, allow_slice=False)
    ):
        with suppress(KeyError, InvalidIndexError):
            # TypeError e.g. passed a bool
            return ax.get_loc(key)

    if isinstance(key, tuple):
        with suppress(IndexingError):
            # suppress "Too many indexers"
            return self._convert_tuple(key)

    if isinstance(key, range):
        # GH#45479 test_loc_setitem_range_key
        key = list(key)

    return self._convert_to_indexer(key, axis=0)

def _maybe_mask_setitem_value(self, indexer, value):
    """
    If we have obj.iloc[mask] = series_or_frame and series_or_frame has the
    same length as obj, we treat this as obj.iloc[mask] = series_or_frame[mask],
    similar to Series.__setitem__.

    Note this is only for loc, not iloc.
    """

    if (
        isinstance(indexer, tuple)
        and len(indexer) == 2
        and isinstance(value, (ABCSeries, ABCDataFrame))
    ):
        pi, icols = indexer
        ndim = value.ndim
        if com.is_bool_indexer(pi) and len(value) == len(pi):
            newkey = pi.nonzero()[0]

            if is_scalar_indexer(icols, self.ndim - 1) and ndim == 1:
                # e.g. test_loc_setitem_boolean_mask_allfalse
                if len(newkey) == 0:
                    value = value.iloc[:0]
                else:
                    # test_loc_setitem_ndframe_values_alignment
                    value = self.obj.iloc._align_series(indexer, value)
                indexer = (newkey, icols)

            elif (
                isinstance(icols, np.ndarray)
                and icols.dtype.kind == "i"
                and len(icols) == 1
            ):
                if ndim == 1:
                    # We implicitly broadcast, though numpy does not, see
                    # github.com/pandas-dev/pandas/pull/45501#discussion_r789071825
                    # test_loc_setitem_ndframe_values_alignment
                    value = self.obj.iloc._align_series(indexer, value)
                    indexer = (newkey, icols)

                elif ndim == 2 and value.shape[1] == 1:
                    if len(newkey) == 0:
                        value = value.iloc[:0]
                    else:
                        # test_loc_setitem_ndframe_values_alignment
                        value = self.obj.iloc._align_frame(indexer, value)
                    indexer = (newkey, icols)
    elif com.is_bool_indexer(indexer):
        indexer = indexer.nonzero()[0]

    return indexer, value

def __setitem__(self, key, value) -> None:
    if not CHAINED_WARNING_DISABLED:
        if sys.getrefcount(self.obj) <= REF_COUNT_IDX:
            warnings.warn(
                _chained_assignment_msg, ChainedAssignmentError, stacklevel=2
            )

    check_dict_or_set_indexers(key)
    if isinstance(key, tuple):
        key = (list(x) if is_iterator(x) else x for x in key)
        key = tuple(com.apply_if_callable(x, self.obj) for x in key)
    else:
        maybe_callable = com.apply_if_callable(key, self.obj)
        key = self._raise_callable_usage(key, maybe_callable)
    # Capture the row count before _get_setitem_indexer which may add
    # columns (but not rows).
    orig_nrows = self.obj.shape[0]
    indexer = self._get_setitem_indexer(key)  # may alter self.obj
    self._has_valid_setitem_indexer(key)

    # Capture dtype info cheaply between potential column expansion
    # (above) and potential row expansion (below).
    if self.obj.ndim == 1:
        orig_dtype_info = self.obj.dtype
        orig_columns = None
    else:
        orig_dtype_info = self.obj._mgr.get_dtypes()
        orig_columns = self.obj.columns

    iloc: _iLocIndexer = (
        cast("_iLocIndexer", self) if self.name == "iloc" else self.obj.iloc
    )
    iloc._setitem_with_indexer(indexer, value, self.name)

    if self.obj.shape[0] != orig_nrows:
        self._post_expansion_casting(orig_dtype_info, orig_columns)

def _validate_tuple_indexer(self, key: tuple) -> tuple:
    """
    Check the key for valid keys across my indexer.
    """
    key = self._validate_key_length(key)
    key = self._expand_ellipsis(key)
    for i, k in enumerate(key):
        try:
            self._validate_key(k, i)
        except ValueError as err:
            raise ValueError(
                f"Location based indexing can only have [{self._valid_types}] types"
            ) from err
    return key

def _is_nested_tuple_indexer(self, tup: tuple) -> bool:
    """
    Returns
    -------
    bool
    """
    if any(isinstance(ax, MultiIndex) for ax in self.obj.axes):
        return any(is_nested_tuple(tup, ax) for ax in self.obj.axes)
    return False

def _validate_key_length(self, key: tuple) -> tuple:
    if len(key) > self.ndim:
        if key[0] is Ellipsis:
            # e.g. Series.iloc[..., 3] reduces to just Series.iloc[3]
            key = key[1:]
            if Ellipsis in key:
                raise IndexingError(_one_ellipsis_message)
            return self._validate_key_length(key)
        raise IndexingError("Too many indexers")
    return key

def _raise_callable_usage(self, key: Any, maybe_callable: T) -> T:
    # GH53533
    if self.name == "iloc" and callable(key) and isinstance(maybe_callable, tuple):
        raise ValueError(
            "Returning a tuple from a callable with iloc is not allowed.",
        )
    return maybe_callable

def __getitem__(self, key):
    check_dict_or_set_indexers(key)
    if type(key) is tuple:
        key = (list(x) if is_iterator(x) else x for x in key)
        key = tuple(com.apply_if_callable(x, self.obj) for x in key)
        if self._is_scalar_access(key):
            return self.obj._get_value(*key, takeable=self._takeable)
        return self._getitem_tuple(key)
    else:
        # we by definition only have the 0th axis
        axis = self.axis or 0

        maybe_callable = com.apply_if_callable(key, self.obj)
        maybe_callable = self._raise_callable_usage(key, maybe_callable)
        return self._getitem_axis(maybe_callable, axis=axis)

def _handle_lowerdim_multi_index_axis0(self, tup: tuple):
    # we have an axis0 multi-index, handle or raise
    axis = self.axis or 0
    try:
        # fast path for series or for tup devoid of slices
        return self._get_label(tup, axis=axis)

    except KeyError as ek:
        # raise KeyError if number of indexers match
        # else IndexingError will be raised
        if self.ndim < len(tup) <= self.obj.index.nlevels:
            raise ek
        raise IndexingError("No label returned") from ek

def _getitem_axis(self, key, axis: AxisInt):
    key = item_from_zerodim(key)
    if is_iterator(key):
        key = list(key)
    if key is Ellipsis:
        key = slice(None)

    labels = self.obj._get_axis(axis)

    if isinstance(key, tuple) and isinstance(labels, MultiIndex):
        key = tuple(key)

    if isinstance(key, slice):
        self._validate_key(key, axis)
        return self._get_slice_axis(key, axis=axis)
    elif com.is_bool_indexer(key):
        return self._getbool_axis(key, axis=axis)
    elif is_list_like_indexer(key):
        # an iterable multi-selection
        if not (isinstance(key, tuple) and isinstance(labels, MultiIndex)):
            if hasattr(key, "ndim") and key.ndim > 1:
                raise ValueError("Cannot index with multidimensional key")

            return self._getitem_iterable(key, axis=axis)

        # nested tuple slicing
        if is_nested_tuple(key, labels):
            locs = labels.get_locs(key)
            indexer: list[slice | npt.NDArray[np.intp]] = [slice(None)] * self.ndim
            indexer[axis] = locs
            result = self.obj.iloc[tuple(indexer)]

            # GH#18631 Drop levels that were indexed with scalars,
            # but only when the key has no slices or bool indexers.
            # Dropping scalar levels in the presence of slices would
            # be correct in principle, but many internal operations
            # (e.g. stack/unstack) rely on the current behavior.
            has_slice_or_mask = any(
                isinstance(k, slice) or com.is_bool_indexer(k) for k in key
            )
            if not has_slice_or_mask:
                levels_to_drop = []
                for idx, k in enumerate(key):
                    if not is_list_like(k):
                        levels_to_drop.append(idx)
                    elif isinstance(k, tuple):
                        # GH#27591 A tuple might be a single label
                        # in this level rather than a sequence of labels
                        try:
                            labels.levels[idx].get_loc(k)
                            levels_to_drop.append(idx)
                        except KeyError:
                            pass
                if levels_to_drop:
                    if len(levels_to_drop) >= labels.nlevels:
                        # All levels are scalar-indexed; reduce
                        # dimensionality instead of droplevel (which
                        # cannot remove every level).
                        result = result._ixs(0, axis=axis)
                    else:
                        result = result.droplevel(levels_to_drop, axis=axis)

            return result

    # fall thru to straight lookup
    self._validate_key(key, axis)
    return self._get_label(key, axis=axis)

def _get_slice_axis(self, slice_obj: slice, axis: AxisInt):
    """
    This is pretty simple as we just have to deal with labels.
    """
    # caller is responsible for ensuring non-None axis
    obj = self.obj
    if not need_slice(slice_obj):
        return obj.copy(deep=False)

    labels = obj._get_axis(axis)
    indexer = labels.slice_indexer(slice_obj.start, slice_obj.stop, slice_obj.step)

    if isinstance(indexer, slice):
        return self.obj._slice(indexer, axis=axis)
    else:
        # DatetimeIndex overrides Index.slice_indexer and may
        #  return a DatetimeIndex instead of a slice object.
        return self.obj.take(indexer, axis=axis)

def _validate_key(self, key, axis: AxisInt) -> None:
    if com.is_bool_indexer(key):
        if hasattr(key, "index") and isinstance(key.index, Index):
            if key.index.inferred_type == "integer":
                return
            raise ValueError(
                "iLocation based boolean indexing cannot use an indexable as a mask"
            )
        return

    if isinstance(key, slice):
        return
    elif is_integer(key):
        self._validate_integer(key, axis)
    elif isinstance(key, tuple):
        # a tuple should already have been caught by this point
        # so don't treat a tuple as a valid indexer
        raise IndexingError("Too many indexers")
    elif is_list_like_indexer(key):
        if isinstance(key, ABCSeries):
            arr = key._values
        elif is_array_like_deprecate_non_pandas(key):
            arr = key
        else:
            arr = np.array(key)
        len_axis = len(self.obj._get_axis(axis))

        # check that the key has a numeric dtype
        if not is_numeric_dtype(arr.dtype):
            raise IndexError(f".iloc requires numeric indexers, got {arr}")

        if len(arr):
            if isinstance(arr.dtype, ExtensionDtype):
                arr_max = arr._reduce("max")
                arr_min = arr._reduce("min")
            else:
                arr_max = np.max(arr)
                arr_min = np.min(arr)

            # check that the key does not exceed the maximum size
            if arr_max >= len_axis or arr_min < -len_axis:
                raise IndexError("positional indexers are out-of-bounds")
    else:
        raise ValueError(f"Can only index by location with a [{self._valid_types}]")

def _has_valid_setitem_indexer(self, indexer) -> bool:
    """
    Validate that a positional indexer cannot enlarge its target
    will raise if needed, does not modify the indexer externally.

    Returns
    -------
    bool
    """
    if isinstance(indexer, dict):
        raise IndexError("iloc cannot enlarge its target object")

    if isinstance(indexer, ABCDataFrame):
        raise TypeError(
            "DataFrame indexer for .iloc is not supported. "
            "Consider using .loc with a DataFrame indexer for automatic alignment.",
        )

    if not isinstance(indexer, tuple):
        indexer = _tuplify(self.ndim, indexer)

    for ax, i in zip(self.obj.axes, indexer, strict=False):
        if isinstance(i, slice):
            # should check the stop slice?
            pass
        elif is_list_like_indexer(i):
            # should check the elements?
            pass
        elif is_integer(i):
            if i >= len(ax):
                raise IndexError("iloc cannot enlarge its target object")
        elif isinstance(i, dict):
            raise IndexError("iloc cannot enlarge its target object")

    return True

def _getitem_axis(self, key, axis: AxisInt):
    if key is Ellipsis:
        key = slice(None)
    elif isinstance(key, ABCDataFrame):
        raise IndexError(
            "DataFrame indexer is not allowed for .iloc\n"
            "Consider using .loc for automatic alignment."
        )

    if isinstance(key, slice):
        return self._get_slice_axis(key, axis=axis)

    if is_iterator(key):
        key = list(key)

    if isinstance(key, list):
        key = np.asarray(key)

    if com.is_bool_indexer(key):
        self._validate_key(key, axis)
        return self._getbool_axis(key, axis=axis)

    # a list of integers
    elif is_list_like_indexer(key):
        return self._get_list_axis(key, axis=axis)

    # a single integer
    else:
        key = item_from_zerodim(key)
        if not is_integer(key):
            raise TypeError("Cannot index by location index with a non-integer key")

        # validate the location
        self._validate_integer(key, axis)

        return self.obj._ixs(key, axis=axis)

def _get_setitem_indexer(self, key):
    # GH#32257 Fall through to let numpy do validation
    if is_iterator(key):
        key = list(key)

    if self.axis is not None:
        key = _tupleize_axis_indexer(self.ndim, self.axis, key)

    return key

def _setitem_with_indexer_split_path(self, indexer, value, name: str):
    """
    Setitem column-wise.
    """
    # Above we only set take_split_path to True for 2D cases
    assert self.ndim == 2

    if not isinstance(indexer, tuple):
        indexer = _tuplify(self.ndim, indexer)
    if len(indexer) > self.ndim:
        raise IndexError("too many indices for array")
    if isinstance(indexer[0], np.ndarray) and indexer[0].ndim > 2:
        raise ValueError(r"Cannot set values with ndim > 2")

    if (isinstance(value, ABCSeries) and name != "iloc") or isinstance(value, dict):
        from pandas import Series

        value = self._align_series(indexer, Series(value))

    # Ensure we have something we can iterate over
    info_axis = indexer[1]
    ilocs = self._ensure_iterable_column_indexer(info_axis)

    pi = indexer[0]
    lplane_indexer = length_of_indexer(pi, self.obj.index)
    # lplane_indexer gives the expected length of obj[indexer[0]]

    # we need an iterable, with an ndim of at least 1
    # eg. don't pass through np.array(0)
    if is_list_like_indexer(value) and getattr(value, "ndim", 1) > 0:
        if isinstance(value, ABCDataFrame):
            self._setitem_with_indexer_frame_value(indexer, value, name)

        elif _is_2d_value_for_columns(value, len(ilocs)):
            self._setitem_with_indexer_2d_value(indexer, value)

        elif len(ilocs) == 1 and lplane_indexer == len(value) and not is_scalar(pi):
            # We are setting multiple rows in a single column.
            self._setitem_single_column(ilocs[0], value, pi)

        elif self._is_scalar_access(indexer) and is_object_dtype(
            self.obj.dtypes._values[ilocs[0]]
        ):
            # We are setting nested data into a single cell,
            # only possible for object dtype. Bypasses length checks.
            self._setitem_single_column(ilocs[0], value, pi)

        elif len(ilocs) == 1 and 0 != lplane_indexer != len(value):
            # We are trying to set N values into M entries of a single
            #  column, which is invalid for N != M
            # Exclude zero-len for e.g. boolean masking that is all-false

            if len(value) == 1 and not is_integer(info_axis):
                # This is a case like df.iloc[:3, [1]] = [0]
                #  where we treat as df.iloc[:3, 1] = 0
                return self._setitem_with_indexer((pi, info_axis[0]), value[0])

            raise ValueError(
                "Must have equal len keys and value when setting with an iterable"
            )

        elif lplane_indexer == 0 and len(value) == len(self.obj.index):
            # We get here in one case via .loc with an all-False mask
            pass

        elif len(ilocs) == len(value):
            # We are setting multiple columns in a single row.
            for loc, v in zip(ilocs, value, strict=True):
                self._setitem_single_column(loc, v, pi)

        elif len(ilocs) == 1 and com.is_null_slice(pi) and len(self.obj) == 0:
            # This is a setitem-with-expansion, see
            #  test_loc_setitem_empty_append_expands_rows_mixed_dtype
            # e.g. df = DataFrame(columns=["x", "y"])
            #  df["x"] = df["x"].astype(np.int64)
            #  df.loc[:, "x"] = [1, 2, 3]
            self._setitem_single_column(ilocs[0], value, pi)

        else:
            raise ValueError(
                "Must have equal len keys and value when setting with an iterable"
            )

    else:
        # scalar value
        for loc in ilocs:
            self._setitem_single_column(loc, value, pi)

def _setitem_with_indexer_2d_value(self, indexer, value) -> None:
    # We get here with a 2D value (array-like or list-of-lists),
    # excluding DataFrame which goes through _setitem_with_indexer_frame_value
    pi = indexer[0]
    ilocs = self._ensure_iterable_column_indexer(indexer[1])

    if not isinstance(value, list) and not is_array_like_deprecate_non_pandas(
        value
    ):
        value = np.asarray(value)

    msg = "Must have equal len keys and value when setting with an ndarray"
    if isinstance(value, list):
        nkeys = len(ilocs)
        rows = []
        for row in value:
            if len(row) != nkeys:
                raise ValueError(msg)
            if type(row) is not list:
                row = _positional_row(row)
            rows.append(row)
        value = rows
    elif value.shape[1] != len(ilocs):
        raise ValueError(msg)

    for i, loc in enumerate(ilocs):
        if isinstance(value, list):
            value_col = [row[i] for row in value]
        else:
            value_col = value[:, i]
            if is_object_dtype(value_col.dtype):
                value_col = value_col.tolist()
        self._setitem_single_column(loc, value_col, pi)

def _setitem_with_indexer_frame_value(
    self, indexer, value: DataFrame, name: str
) -> None:
    ilocs = self._ensure_iterable_column_indexer(indexer[1])

    sub_indexer = list(indexer)
    pi = indexer[0]

    multiindex_indexer = isinstance(self.obj.columns, MultiIndex)

    unique_cols = value.columns.is_unique

    # We do not want to align the value in case of iloc GH#37728
    if name == "iloc":
        for i, loc in enumerate(ilocs):
            val = value.iloc[:, i]
            self._setitem_single_column(loc, val, pi)

    elif not unique_cols and value.columns.equals(self.obj.columns):
        # We assume we are already aligned, see
        # test_iloc_setitem_frame_duplicate_columns_multiple_blocks
        for loc in ilocs:
            item = self.obj.columns[loc]
            if item in value:
                sub_indexer[1] = item
                val = self._align_series(
                    tuple(sub_indexer),
                    value.iloc[:, loc],
                    multiindex_indexer,
                )
            else:
                val = np.nan

            self._setitem_single_column(loc, val, pi)

    elif not unique_cols:
        raise ValueError("Setting with non-unique columns is not allowed.")

    else:
        for loc in ilocs:
            item = self.obj.columns[loc]
            if item in value:
                sub_indexer[1] = item
                ser = value[item]
                val = self._align_series(
                    tuple(sub_indexer),
                    ser,
                    multiindex_indexer,
                )
                # If _align_series did not need to reindex, pass the
                # original Series so that _setitem_single_column can
                # preserve CoW ref tracking through isetitem.
                if val is ser._values:
                    val = ser
            else:
                val = np.nan

            self._setitem_single_column(loc, val, pi)

def _ensure_iterable_column_indexer(self, column_indexer):
    """
    Ensure that our column indexer is something that can be iterated over.
    """
    ilocs: Sequence[int | np.integer] | np.ndarray | range
    if is_integer(column_indexer):
        ilocs = [column_indexer]
    elif isinstance(column_indexer, slice):
        ilocs = range(len(self.obj.columns))[column_indexer]
    elif com.is_bool_indexer(column_indexer):
        ilocs = np.arange(len(column_indexer))[
            np.asarray(column_indexer, dtype=bool)
        ]
    else:
        ilocs = column_indexer
    return ilocs

def _align_frame(self, indexer, df: DataFrame) -> DataFrame:
    is_frame = self.ndim == 2

    if isinstance(indexer, tuple):
        idx, cols = None, None
        sindexers = []
        for i, ix in enumerate(indexer):
            ax = self.obj.axes[i]
            if is_sequence(ix) or isinstance(ix, slice):
                if isinstance(ix, np.ndarray):
                    ix = ix.reshape(-1)
                if idx is None:
                    idx = ax[ix]
                elif cols is None:
                    cols = ax[ix]
                else:
                    break
            else:
                sindexers.append(i)

        if idx is not None and cols is not None:
            if df.index.equals(idx) and df.columns.equals(cols):
                val = df.copy()
            else:
                val = df.reindex(idx, columns=cols)
            return val

    elif (isinstance(indexer, slice) or is_list_like_indexer(indexer)) and is_frame:
        ax = self.obj.index[indexer]
        if df.index.equals(ax):
            val = df.copy()
        else:
            # we have a multi-index and are trying to align
            # with a particular, level GH3738
            if (
                isinstance(ax, MultiIndex)
                and isinstance(df.index, MultiIndex)
                and ax.nlevels != df.index.nlevels
            ):
                raise TypeError(
                    "cannot align on a multi-index with out "
                    "specifying the join levels"
                )

            val = df.reindex(index=ax)
        return val

    raise ValueError("Incompatible indexer with DataFrame")

def __getitem__(self, key):
    if not isinstance(key, tuple):
        # we could have a convertible item here (e.g. Timestamp)
        if not is_list_like_indexer(key):
            key = (key,)
        else:
            raise ValueError("Invalid call for scalar access (getting)!")

    key = self._convert_key(key)
    return self.obj._get_value(*key, takeable=self._takeable)

def __setitem__(self, key, value) -> None:
    if isinstance(key, tuple):
        key = tuple(com.apply_if_callable(x, self.obj) for x in key)
    else:
        # scalar callable may return tuple
        key = com.apply_if_callable(key, self.obj)

    if not isinstance(key, tuple):
        key = _tuplify(self.ndim, key)
    key = list(self._convert_key(key))
    if len(key) != self.ndim:
        raise ValueError("Not enough indexers for scalar access (setting)!")

    self.obj._set_value(*key, value=value, takeable=self._takeable)

def _warn_if_expanding(self, key) -> None:
    """
    GH#48323 - Warn if .at setitem would expand the object.
    """
    if self.ndim == 2:
        if not isinstance(key, tuple) or len(key) != 2:
            return
        checks = [(key[0], self.obj.index), (key[1], self.obj.columns)]
    else:
        check_key = key
        if isinstance(key, tuple) and len(key) == 1:
            check_key = key[0]
        checks = [(check_key, self.obj.index)]

    for check_key, axis in checks:
        # Only check for scalar-like keys (including tuples for MultiIndex).
        # Slices and list-likes are invalid for .at and will raise elsewhere.
        if isinstance(check_key, slice) or is_list_like_indexer(check_key):
            if not isinstance(check_key, tuple):
                continue

        try:
            is_expanding = check_key not in axis
        except (TypeError, InvalidIndexError):
            continue

        if is_expanding:
            obj_type = "DataFrame" if self.ndim == 2 else "Series"
            warnings.warn(
                f"Setting a value on a {obj_type} via .at with a key "
                "that does not exist in the index is deprecated "
                "and will raise a KeyError in a future version. "
                "Use .loc instead.",
                Pandas4Warning,
                stacklevel=find_stack_level(),
            )
            return

def __getitem__(self, key):
    if self.ndim == 2 and not self._axes_are_unique:
        # GH#33041 fall back to .loc
        if not isinstance(key, tuple) or not all(is_scalar(x) for x in key):
            raise ValueError("Invalid call for scalar access (getting)!")
        return self.obj.loc[key]

    return super().__getitem__(key)

def __setitem__(self, key, value) -> None:
    if not CHAINED_WARNING_DISABLED:
        if sys.getrefcount(self.obj) <= REF_COUNT_IDX:
            warnings.warn(
                _chained_assignment_msg, ChainedAssignmentError, stacklevel=2
            )

    # GH#48323 - deprecate .at setitem with expansion
    self._warn_if_expanding(key)

    if self.ndim == 2 and not self._axes_are_unique:
        # GH#33041 fall back to .loc
        if not isinstance(key, tuple) or not all(is_scalar(x) for x in key):
            raise ValueError("Invalid call for scalar access (setting)!")

        self.obj.loc[key] = value
        return

    return super().__setitem__(key, value)

def _convert_key(self, key):
    """
    Require integer args. (and convert to label arguments)
    """
    for i in key:
        if not is_integer(i):
            raise ValueError("iAt based indexing can only have integer indexers")
    return key

def __setitem__(self, key, value) -> None:
    if not CHAINED_WARNING_DISABLED:
        if sys.getrefcount(self.obj) <= REF_COUNT_IDX:
            warnings.warn(
                _chained_assignment_msg, ChainedAssignmentError, stacklevel=2
            )

    return super().__setitem__(key, value)

def dispatch_ufunc_with_out(self, ufunc: np.ufunc, method: str, *inputs, **kwargs):
    """
    If we have an `out` keyword, then call the ufunc without `out` and then
    set the result into the given `out`.
    """

    # Note: we assume _standardize_out_kwarg has already been called.
    out = kwargs.pop("out")
    where = kwargs.pop("where", None)

    result = getattr(ufunc, method)(*inputs, **kwargs)

    if result is NotImplemented:
        return NotImplemented

    if isinstance(result, tuple):
        # i.e. np.divmod, np.modf, np.frexp
        if not isinstance(out, tuple) or len(out) != len(result):
            raise NotImplementedError

        for arr, res in zip(out, result, strict=True):
            _assign_where(arr, res, where)

        return out

    if isinstance(out, tuple):
        if len(out) == 1:
            out = out[0]
        else:
            raise NotImplementedError

    _assign_where(out, result, where)
    return out

def _ensure_data(values: ArrayLike) -> np.ndarray:
    """
    routine to ensure that our data is of the correct
    input dtype for lower-level routines

    This will coerce:
    - ints -> int64
    - uint -> uint64
    - bool -> uint8
    - datetimelike -> i8
    - datetime64tz -> i8 (in local tz)
    - categorical -> codes

    Parameters
    ----------
    values : np.ndarray or ExtensionArray

    Returns
    -------
    np.ndarray
    """

    if not isinstance(values, ABCMultiIndex):
        # extract_array would raise
        values = extract_array(values, extract_numpy=True)

    if is_object_dtype(values.dtype):
        return ensure_object(np.asarray(values))

    elif isinstance(values.dtype, BaseMaskedDtype):
        # i.e. BooleanArray, FloatingArray, IntegerArray
        values = cast("BaseMaskedArray", values)
        if not values._hasna:
            # No pd.NAs -> We can avoid an object-dtype cast (and copy) GH#41816
            #  recurse to avoid re-implementing logic for eg bool->uint8
            return _ensure_data(values._data)
        return np.asarray(values)

    elif isinstance(values.dtype, CategoricalDtype):
        # NB: cases that go through here should NOT be using _reconstruct_data
        #  on the back-end.
        values = cast("Categorical", values)
        return values.codes

    elif is_bool_dtype(values.dtype):
        if isinstance(values, np.ndarray):
            # i.e. actually dtype == np.dtype("bool")
            return np.asarray(values).view("uint8")
        else:
            # e.g. Sparse[bool, False], see test_mode_sparse_bool
            return np.asarray(values).astype("uint8", copy=False)

    elif is_integer_dtype(values.dtype):
        return np.asarray(values)

    elif is_float_dtype(values.dtype):
        # itemsize comes off the values, not the dtype: an ExtensionDtype
        # (e.g. Sparse[float64]) may not have one.
        # Note: checking `values.dtype == "float128"` raises on Windows and 32bit
        float_values = np.asarray(values)
        if float_values.dtype.itemsize in [2, 12, 16]:
            # we dont (yet) have float128 hashtable support
            return ensure_float64(float_values)
        return float_values

    elif is_complex_dtype(values.dtype):
        # NumpyExtensionArray needs to be unwrapped to the underlying ndarray
        # so the hashtable fused-type dispatch works (GH#54761)
        return np.asarray(values)

    # datetimelike
    elif needs_i8_conversion(values.dtype):
        npvalues = values.view("i8")
        npvalues = cast("np.ndarray", npvalues)
        return npvalues

    # we have failed, return object
    values = np.asarray(values, dtype=object)
    return ensure_object(values)

def _ensure_arraylike(values, func_name: str) -> ArrayLike:
    """
    ensure that we are arraylike if not already
    """
    if not isinstance(
        values,
        (ABCIndex, ABCSeries, ABCExtensionArray, np.ndarray, ABCNumpyExtensionArray),
    ):
        # GH#52986
        if func_name != "isin-targets":
            # Make an exception for the comps argument in isin.
            raise TypeError(
                f"{func_name} requires a Series, Index, "
                f"ExtensionArray, np.ndarray or NumpyExtensionArray "
                f"got {type(values).__name__}."
            )

        inferred = lib.infer_dtype(values, skipna=False)
        if inferred in ["mixed", "string", "mixed-integer"]:
            # "mixed-integer" to ensure we do not cast ["ss", 42] to str GH#22160
            if isinstance(values, tuple):
                values = list(values)
            values = construct_1d_object_array_from_listlike(values)
        else:
            values = np.asarray(values)
    return values

def unique_with_mask(values, mask: npt.NDArray[np.bool_] | None = None):
    """See algorithms.unique for docs. Takes a mask for masked arrays."""
    values = _ensure_arraylike(values, func_name="unique")

    if isinstance(values.dtype, ExtensionDtype):
        # Dispatch to extension dtype's unique.
        return values.unique()

    if isinstance(values, ABCIndex):
        # Dispatch to Index's unique.
        return values.unique()

    original = values
    hashtable, values = _get_hashtable_algo(values)

    table = hashtable(len(values))
    if mask is None:
        uniques = table.unique(values)
        uniques = _reconstruct_data(uniques, original.dtype, original)
        return uniques

    else:
        uniques, mask = table.unique(values, mask=mask)
        uniques = _reconstruct_data(uniques, original.dtype, original)
        assert mask is not None  # for mypy
        return uniques, mask.astype("bool")

def check_value_size(value, mask: npt.NDArray[np.bool_], length: int):
    """
    Validate the size of the values passed to ExtensionArray.fillna.
    """
    if isinstance(value, dict):
        raise TypeError(
            "ExtensionArray.fillna does not support filling with a dict. "
            "Use Series.fillna instead."
        )
    if is_array_like_deprecate_non_pandas(value):
        if len(value) != length:
            raise ValueError(
                f"Length of 'value' does not match. Got ({len(value)}) "
                f" expected {length}"
            )
        value = value[mask]

    return value

def clean_fill_method(
    method: Literal["ffill", "pad", "bfill", "backfill", "nearest"],
    *,
    allow_nearest: bool = False,
) -> Literal["pad", "backfill", "nearest"]:
    if isinstance(method, str):
        # error: Incompatible types in assignment (expression has type "str", variable
        # has type "Literal['ffill', 'pad', 'bfill', 'backfill', 'nearest']")
        method = method.lower()  # type: ignore[assignment]
        if method == "ffill":
            method = "pad"
        elif method == "bfill":
            method = "backfill"

    valid_methods = ["pad", "backfill"]
    expecting = "pad (ffill) or backfill (bfill)"
    if allow_nearest:
        valid_methods.append("nearest")
        expecting = "pad (ffill), backfill (bfill) or nearest"
    if method not in valid_methods:
        raise ValueError(f"Invalid fill method. Expecting {expecting}. Got {method}")
    return method

def clean_interp_method(method: str, index: Index, **kwargs) -> str:
    order = kwargs.get("order")

    if method in ("spline", "polynomial") and order is None:
        raise ValueError("You must specify the order of the spline or polynomial.")

    valid = NP_METHODS + SP_METHODS
    if method not in valid:
        raise ValueError(f"method must be one of {valid}. Got '{method}' instead.")

    if method in ("krogh", "piecewise_polynomial", "pchip"):
        if not index.is_monotonic_increasing:
            raise ValueError(
                f"{method} interpolation requires that the index be monotonic."
            )

    return method

def validate_limit_area(limit_area: str | None) -> Literal["inside", "outside"] | None:
    if limit_area is not None:
        valid_limit_areas = ["inside", "outside"]
        limit_area = limit_area.lower()
        if limit_area not in valid_limit_areas:
            raise ValueError(
                f"Invalid limit_area: expecting one of {valid_limit_areas}, got "
                f"{limit_area}."
            )
    # error: Incompatible return value type (got "Optional[str]", expected
    # "Optional[Literal['inside', 'outside']]")
    return limit_area  # type: ignore[return-value]

def infer_limit_direction(
    limit_direction: Literal["backward", "forward", "both"] | None, method: str
) -> Literal["backward", "forward", "both"]:
    # Set `limit_direction` depending on `method`
    if limit_direction is None:
        if method in ("backfill", "bfill"):
            limit_direction = "backward"
        else:
            limit_direction = "forward"
    else:
        if method in ("pad", "ffill") and limit_direction != "forward":
            raise ValueError(
                f"`limit_direction` must be 'forward' for method `{method}`"
            )
        if method in ("backfill", "bfill") and limit_direction != "backward":
            raise ValueError(
                f"`limit_direction` must be 'backward' for method `{method}`"
            )
    return limit_direction

def get_interp_index(method, index: Index) -> Index:
    # create/use the index
    if method == "linear":
        # prior default
        from pandas import RangeIndex

        index = RangeIndex(len(index))
    else:
        methods = {"index", "values", "nearest", "time"}
        is_numeric_or_datetime = (
            is_numeric_dtype(index.dtype)
            or isinstance(index.dtype, DatetimeTZDtype)
            or lib.is_np_dtype(index.dtype, "mM")
        )
        valid = NP_METHODS + SP_METHODS
        if method in valid:
            if method not in methods and not is_numeric_or_datetime:
                raise ValueError(
                    "Index column must be numeric or datetime type when "
                    f"using {method} method other than linear. "
                    "Try setting a numeric or datetime index column before "
                    "interpolating."
                )
        else:
            raise ValueError(f"Can not interpolate with method={method}.")

    if isna(index).any():
        raise NotImplementedError(
            "Interpolation with NaNs in the index "
            "has not been implemented. Try filling "
            "those NaNs before interpolating."
        )
    return index

def _index_to_interp_indices(index: Index, method: str) -> np.ndarray:
    """
    Convert Index to ndarray of indices to pass to NumPy/SciPy.
    """
    xarr = index._values
    if needs_i8_conversion(xarr.dtype):
        # GH#1646 for dt64tz
        xarr = xarr.view("i8")
    elif is_arrow_temporal_dtype(xarr.dtype):
        xarr = _arrow_temporal_to_i8(xarr)

    if method == "linear":
        inds = xarr
        inds = cast("np.ndarray", inds)
    else:
        inds = np.asarray(xarr)

        if method in ("values", "index"):
            if inds.dtype == np.object_:
                inds = lib.maybe_convert_objects(inds)

    return inds

def _pad_2d(
    values: np.ndarray,
    limit: int | None = None,
    limit_area: Literal["inside", "outside"] | None = None,
    mask: npt.NDArray[np.bool_] | None = None,
) -> tuple[np.ndarray, npt.NDArray[np.bool_]]:
    mask = _fillna_prep(values, mask)
    if limit_area is not None:
        _fill_limit_area_2d(mask, limit_area)

    if values.size:
        algos.pad_2d_inplace(values, mask, limit=limit)
    return values, mask

def _backfill_2d(
    values,
    limit: int | None = None,
    limit_area: Literal["inside", "outside"] | None = None,
    mask: npt.NDArray[np.bool_] | None = None,
):
    mask = _fillna_prep(values, mask)
    if limit_area is not None:
        _fill_limit_area_2d(mask, limit_area)

    if values.size:
        algos.backfill_2d_inplace(values, mask, limit=limit)
    else:
        # for test coverage
        pass
    return values, mask

def _take_new_index(
    obj: DataFrame | Series,
    indexer: npt.NDArray[np.intp],
    new_index: Index,
) -> DataFrame | Series:
    if isinstance(obj, ABCSeries):
        new_values = algos.take_nd(obj._values, indexer)
        return obj._constructor(new_values, index=new_index, name=obj.name)
    elif isinstance(obj, ABCDataFrame):
        new_mgr = obj._mgr.reindex_indexer(new_axis=new_index, indexer=indexer, axis=1)
        return obj._constructor_from_mgr(new_mgr, axes=new_mgr.axes)
    else:
        raise ValueError("'obj' should be either a Series or a DataFrame")

def asfreq(
    obj: NDFrameT,
    freq,
    method=None,
    how=None,
    normalize: bool = False,
    fill_value=None,
) -> NDFrameT:
    """
    Utility frequency conversion method for Series/DataFrame.

    See :meth:`pandas.NDFrame.asfreq` for full documentation.
    """
    if isinstance(obj.index, PeriodIndex):
        if method is not None:
            raise NotImplementedError("'method' argument is not supported")

        if how is None:
            how = "E"

        if isinstance(freq, BaseOffset):
            if hasattr(freq, "_period_dtype_code"):
                freq = PeriodDtype(freq)._freqstr

        new_obj = obj.copy()
        new_obj.index = obj.index.asfreq(freq, how=how)

    elif len(obj.index) == 0:
        new_obj = obj.copy()

        new_obj.index = _asfreq_compat(obj.index, freq)
    else:
        unit: TimeUnit = "ns"
        if isinstance(obj.index, DatetimeIndex):
            # TODO: should we disallow non-DatetimeIndex?
            unit = obj.index.unit
        dti = date_range(obj.index.min(), obj.index.max(), freq=freq, unit=unit)
        dti.name = obj.index.name
        new_obj = obj.reindex(dti, method=method, fill_value=fill_value)
        if normalize:
            new_obj.index = new_obj.index.normalize()

    return new_obj

def __getattr__(self, attr: str):
    if attr in self._internal_names_set:
        return object.__getattribute__(self, attr)
    if attr in self._attributes:
        return getattr(self._timegrouper, attr)
    if attr in self.obj:
        return self[attr]

    return object.__getattribute__(self, attr)

def _apply(self, f, *args, **kwargs):
    """
    Dispatch to _upsample; we are stripping all of the _upsample kwargs and
    performing the original function call on the grouped object.
    """

    def func(x):
        x = self._resampler_cls(x, timegrouper=self._timegrouper, gpr_index=self.ax)

        if isinstance(f, str):
            return getattr(x, f)(**kwargs)

        return x.apply(f, *args, **kwargs)

    result = self._groupby.apply(func)

    # GH 47705
    if (
        isinstance(result, ABCDataFrame)
        and len(result) == 0
        and not isinstance(result.index, PeriodIndex)
    ):
        result = result.set_index(
            _asfreq_compat(self.obj.index[:0], freq=self.freq), append=True
        )

    return self._wrap_result(result)

def _wrap_result(self, result):
    result = super()._wrap_result(result)

    # we may have a different kind that we were asked originally
    # convert if needed
    if isinstance(self.ax, PeriodIndex) and not isinstance(
        result.index, PeriodIndex
    ):
        if isinstance(result.index, MultiIndex):
            # GH 24103 - e.g. groupby resample
            if not isinstance(result.index.levels[-1], PeriodIndex):
                new_level = result.index.levels[-1].to_period(self.freq)
                result.index = result.index.set_levels(new_level, level=-1)
        else:
            result.index = result.index.to_period(self.freq)
    return result

def _get_time_delta_bins(self, ax: TimedeltaIndex):
    if not isinstance(ax, TimedeltaIndex):
        raise TypeError(
            "axis must be a TimedeltaIndex, but got "
            f"an instance of {type(ax).__name__}"
        )

    if not isinstance(self.freq, (Tick, Day)):
        # GH#51896
        raise ValueError(
            "Resampling on a TimedeltaIndex requires fixed-duration `freq`, "
            f"e.g. '24h' or '3D', not {self.freq}"
        )

    if not len(ax):
        binner = labels = TimedeltaIndex(data=[], freq=self.freq, name=ax.name)
        return binner, [], labels

    start, end = ax.min(), ax.max()

    if self.closed == "right":
        end += self.freq  # type: ignore[operator]

    labels = binner = timedelta_range(
        start=start, end=end, freq=self.freq, name=ax.name
    )

    end_stamps = labels
    if self.closed == "left":
        end_stamps += self.freq

    bins = ax.searchsorted(end_stamps, side=self.closed)

    if self.offset:
        # GH 10530 & 31809
        labels += self.offset

    return binner, bins, labels

def _get_time_period_bins(self, ax: DatetimeIndex):
    if not isinstance(ax, DatetimeIndex):
        raise TypeError(
            "axis must be a DatetimeIndex, but got "
            f"an instance of {type(ax).__name__}"
        )

    freq = self.freq

    if len(ax) == 0:
        binner = labels = PeriodIndex(
            data=[], freq=freq, name=ax.name, dtype=ax.dtype
        )
        return binner, [], labels

    labels = binner = period_range(start=ax[0], end=ax[-1], freq=freq, name=ax.name)

    end_stamps = (labels + freq).asfreq(freq, "s").to_timestamp()
    if ax.tz:
        end_stamps = end_stamps.tz_localize(ax.tz)
    bins = ax.searchsorted(end_stamps, side="left")

    return binner, bins, labels

def _set_grouper(
    self, obj: NDFrameT, sort: bool = False, *, gpr_index: Index | None = None
) -> tuple[NDFrameT, Index, npt.NDArray[np.intp] | None]:
    obj, ax, indexer = super()._set_grouper(obj, sort, gpr_index=gpr_index)
    if isinstance(ax.dtype, ArrowDtype) and ax.dtype.kind in "Mm":
        self._arrow_dtype = ax.dtype
        ax = Index(
            cast("ArrowExtensionArray", ax.array)._maybe_convert_datelike_array(),
            name=ax.name,
        )
    return obj, ax, indexer

def _is_positive_int_or_none(value: Any) -> None:
    if value is None:
        return
    if isinstance(value, int) and value >= 1:
        return
    raise ValueError("Value must be a positive integer or None")

def agg(self) -> DataFrame | Series | None:
    """
    Provide an implementation for the aggregators.

    Returns
    -------
    Result of aggregation, or None if agg cannot be performed by
    this method.
    """
    func = self.func

    if isinstance(func, str):
        return self.apply_str()

    if is_dict_like(func):
        return self.agg_dict_like()
    elif is_list_like(func):
        # we require a list, but not a 'str'
        return self.agg_list_like()

    # caller can react
    return None

def transform(self) -> DataFrame | Series:
    """
    Transform a DataFrame or Series.

    Returns
    -------
    DataFrame or Series
        Result of applying ``func`` along the given axis of the
        Series or DataFrame.

    Raises
    ------
    ValueError
        If the transform function fails or does not transform.
    """
    obj = self.obj
    func = self.func
    axis = self.axis
    args = self.args
    kwargs = self.kwargs

    is_series = obj.ndim == 1

    if obj._get_axis_number(axis) == 1:
        assert not is_series
        return obj.T.transform(func, 0, *args, **kwargs).T

    if is_list_like(func) and not is_dict_like(func):
        func = cast("list[AggFuncTypeBase]", func)
        # GH#54929 - raise if duplicate function names are passed
        if len(func) > len(set(func)):
            raise SpecificationError(
                "Function names must be unique if there is no new column names "
                "assigned"
            )
        # Convert func equivalent dict
        if is_series:
            func = {com.get_callable_name(v) or v: v for v in func}
        else:
            func = dict.fromkeys(obj, func)

    if is_dict_like(func):
        func = cast("AggFuncTypeDict", func)
        return self.transform_dict_like(func)

    # func is either str or callable
    func = cast("AggFuncTypeBase", func)
    try:
        result = self.transform_str_or_callable(func)
    except TypeError:
        raise
    except Exception as err:
        raise ValueError("Transform function failed") from err

    # Functions that transform may return empty Series/DataFrame
    # when the dtype is not appropriate
    if (
        isinstance(result, (ABCSeries, ABCDataFrame))
        and result.empty
        and not obj.empty
    ):
        raise ValueError("Transform function failed")
    if not isinstance(result, (ABCSeries, ABCDataFrame)) or not result.index.equals(
        obj.index
    ):
        raise ValueError("Function did not transform")

    return result

def transform_dict_like(self, func) -> DataFrame:
    """
    Compute transform in the case of a dict-like func
    """

    obj = self.obj
    args = self.args
    kwargs = self.kwargs

    # transform is currently only for Series/DataFrame
    assert isinstance(obj, ABCNDFrame)

    if len(func) == 0:
        raise ValueError("No transform functions were provided")

    func = self.normalize_dictlike_arg("transform", obj, func)

    results: dict[Hashable, DataFrame | Series] = {}
    for name, how in func.items():
        colg = obj._gotitem(name, ndim=1)
        results[name] = colg.transform(how, 0, *args, **kwargs)
    return concat(results, axis=1)

def transform_str_or_callable(self, func) -> DataFrame | Series:
    """
    Compute transform in the case of a string or callable func
    """
    obj = self.obj
    args = self.args
    kwargs = self.kwargs

    if isinstance(func, str):
        return self._apply_str(obj, func, *args, **kwargs)

    # Two possible ways to use a UDF - apply or call directly
    try:
        return obj.apply(func, args=args, **kwargs)
    except Exception:
        return func(obj, *args, **kwargs)

def wrap_results_list_like(
    self, keys: Iterable[Hashable], results: list[Series | DataFrame]
):
    from pandas import Index
    from pandas.core.groupby.groupby import BaseGroupBy

    obj = self.obj

    if not results:
        # GH#39609
        if isinstance(obj, ABCSeries):
            return obj._constructor(index=Index([]), name=obj.name)
        elif isinstance(obj, BaseGroupBy) and obj._selected_obj.ndim == 1:
            return obj._selected_obj._constructor_expanddim(
                index=_groupby_result_index(obj), columns=Index([])
            )

    try:
        return concat(results, keys=keys, axis=1, sort=False)
    except TypeError as err:
        # we are concatting non-NDFrame objects,
        # e.g. a list of scalars
        from pandas import Series

        result = Series(results, index=keys, name=obj.name)
        if is_nested_object(result):
            raise ValueError(
                "cannot combine transform and aggregation operations"
            ) from err
        return result

def wrap_results_dict_like(
    self,
    selected_obj: Series | DataFrame,
    result_index: list[Hashable],
    result_data: list,
):
    from pandas import Index
    from pandas.core.groupby.groupby import BaseGroupBy

    obj = self.obj

    if not result_data:
        # GH#39609
        if isinstance(obj, ABCSeries):
            return obj._constructor(index=Index([]), name=obj.name)
        elif isinstance(obj, ABCDataFrame):
            return obj._constructor(index=Index([]), columns=obj.columns[:0])
        elif isinstance(obj, BaseGroupBy):
            index = _groupby_result_index(obj)
            if selected_obj.ndim == 2:
                frame = cast("DataFrame", selected_obj)
                return frame._constructor(index=index, columns=frame.columns[:0])
            return selected_obj._constructor_expanddim(
                index=index, columns=Index([])
            )

    # Avoid making two isinstance calls in all and any below
    is_ndframe = [isinstance(r, ABCNDFrame) for r in result_data]

    if all(is_ndframe):
        results = [result for result in result_data if not result.empty]
        keys_to_use: Iterable[Hashable]
        keys_to_use = [
            k for k, v in zip(result_index, result_data, strict=True) if not v.empty
        ]
        # Have to check, if at least one DataFrame is not empty.
        if keys_to_use == []:
            keys_to_use = result_index
            results = result_data

        if selected_obj.ndim == 2:
            # keys are columns, so we can preserve names
            ktu = Index(keys_to_use)
            ktu._set_names(selected_obj.columns.names)
            keys_to_use = ktu

        axis: AxisInt = 0 if isinstance(obj, ABCSeries) else 1
        result = concat(
            results,
            axis=axis,
            keys=keys_to_use,
            sort=False,
        )
    elif any(is_ndframe):
        # There is a mix of NDFrames and scalars
        raise ValueError(
            "cannot perform both aggregation "
            "and transformation operations "
            "simultaneously"
        )
    else:
        from pandas import Series

        # we have a list of scalars
        # GH 36212 use name only if obj is a series
        if obj.ndim == 1:
            obj = cast("Series", obj)
            name = obj.name
        else:
            name = None

        result = Series(result_data, index=result_index, name=name)

    return result

def apply_str(self) -> DataFrame | Series:
    """
    Compute apply in case of a string.

    Returns
    -------
    result: Series or DataFrame
    """
    # Caller is responsible for checking isinstance(self.f, str)
    func = cast("str", self.func)

    obj = self.obj

    from pandas.core.groupby.generic import (
        DataFrameGroupBy,
        SeriesGroupBy,
    )

    # Support for `frame.transform('method')`
    # Some methods (shift, etc.) require the axis argument, others
    # don't, so inspect and insert if necessary.
    method = getattr(obj, func, None)
    if callable(method):
        sig = inspect.getfullargspec(method)
        arg_names = (*sig.args, *sig.kwonlyargs)
        if self.axis != 0 and (
            "axis" not in arg_names or func in ("corrwith", "skew")
        ):
            raise ValueError(f"Operation {func} does not support axis=1")
        if "axis" in arg_names and not isinstance(
            obj, (SeriesGroupBy, DataFrameGroupBy)
        ):
            self.kwargs["axis"] = self.axis
    return self._apply_str(obj, func, *self.args, **self.kwargs)

def _apply_str(self, obj, func: str, *args, **kwargs):
    """
    if arg is a string, then try to operate on it:
    - try to find a function (or attribute) on obj
    - try to find a numpy function
    - raise
    """
    assert isinstance(func, str)

    if hasattr(obj, func):
        f = getattr(obj, func)
        if callable(f):
            return f(*args, **kwargs)

        # people may aggregate on a non-callable attribute
        # but don't let them think they can pass args to it
        assert len(args) == 0
        assert not any(kwarg == "axis" for kwarg in kwargs)
        return f
    elif hasattr(np, func) and hasattr(obj, "__array__"):
        # in particular exclude Window
        f = getattr(np, func)
        return f(obj, *args, **kwargs)
    else:
        msg = f"'{func}' is not a valid function for '{type(obj).__name__}' object"
        raise AttributeError(msg)

def agg_or_apply_list_like(
    self, op_name: Literal["agg", "apply"]
) -> DataFrame | Series:
    obj = self.obj
    kwargs = self.kwargs

    if op_name == "apply":
        if isinstance(self, FrameApply):
            by_row = self.by_row

        elif isinstance(self, SeriesApply):
            by_row = "_compat" if self.by_row else False
        else:
            by_row = False
        kwargs = {**kwargs, "by_row": by_row}

    if getattr(obj, "axis", 0) == 1:
        raise NotImplementedError("axis other than 0 is not supported")

    if op_name == "agg" and isinstance(self, FrameApply):
        result = self._agg_list_like_frame_reductions()
        if result is not None:
            return result

    keys, results = self.compute_list_like(op_name, obj, kwargs)
    result = self.wrap_results_list_like(keys, results)
    return result

def agg_or_apply_dict_like(
    self, op_name: Literal["agg", "apply"]
) -> DataFrame | Series:
    assert op_name in ["agg", "apply"]
    obj = self.obj

    kwargs = {}
    if op_name == "apply":
        by_row = "_compat" if self.by_row else False
        kwargs.update({"by_row": by_row})

    if getattr(obj, "axis", 0) == 1:
        raise NotImplementedError("axis other than 0 is not supported")

    selection = None
    result_index, result_data = self.compute_dict_like(
        op_name, obj, selection, kwargs
    )
    result = self.wrap_results_dict_like(obj, result_index, result_data)
    return result

def validate_values_for_numba(self) -> None:
    # Validate column dtypes all OK
    for colname, dtype in self.obj.dtypes.items():
        if not is_numeric_dtype(dtype):
            raise ValueError(
                f"Column {colname} must have a numeric dtype. "
                f"Found '{dtype}' instead"
            )
        if is_extension_array_dtype(dtype):
            raise ValueError(
                f"Column {colname} is backed by an extension array, "

def apply(self) -> DataFrame | Series:
    """compute the results"""

    # dispatch to handle list-like or dict-like
    if is_list_like(self.func):
        if self.engine == "numba":
            raise NotImplementedError(
                "the 'numba' engine doesn't support lists of callables yet"
            )
        return self.apply_list_or_dict_like()

    # all empty
    if len(self.columns) == 0 and len(self.index) == 0:
        return self.apply_empty_result()

    # string dispatch
    if isinstance(self.func, str):
        if self.engine == "numba":
            raise NotImplementedError(
                "the 'numba' engine doesn't support using "
                "a string as the callable function"
            )
        return self.apply_str()

    # ufunc
    elif isinstance(self.func, np.ufunc):
        if self.engine == "numba":
            raise NotImplementedError(
                "the 'numba' engine doesn't support "
                "using a numpy ufunc as the callable function"
            )
        with np.errstate(all="ignore"):
            results = self.obj._mgr.apply("apply", func=self.func)
        # _constructor will retain self.index and self.columns
        return self.obj._constructor_from_mgr(results, axes=results.axes)

    # broadcasting
    if self.result_type == "broadcast":
        if self.engine == "numba":
            raise NotImplementedError(
                "the 'numba' engine doesn't support result_type='broadcast'"
            )
        return self.apply_broadcast(self.obj)

    # one axis empty
    elif not all(self.obj.shape):
        return self.apply_empty_result()

    # raw
    elif self.raw:
        return self.apply_raw(engine=self.engine, engine_kwargs=self.engine_kwargs)

    return self.apply_standard()

def apply_empty_result(self):
    """
    we have an empty result; at least 1 axis is 0

    we will try to apply the function to an empty
    series in order to see if this is a reduction function
    """
    assert callable(self.func)

    # we are not asked to reduce or infer reduction
    # so just return a copy of the existing object
    if self.result_type not in ["reduce", None]:
        return self.obj.copy()

    # we may need to infer
    should_reduce = self.result_type == "reduce"

    from pandas import Series

    if not should_reduce:
        try:
            if self.axis == 0:
                r = self.func(
                    Series([], dtype=np.float64), *self.args, **self.kwargs
                )
            else:
                r = self.func(
                    Series(index=self.columns, dtype=np.float64),
                    *self.args,
                    **self.kwargs,
                )
        except Exception:
            pass
        else:
            should_reduce = not isinstance(r, Series)

    if should_reduce:
        if len(self.agg_axis):
            r = self.func(Series([], dtype=np.float64), *self.args, **self.kwargs)
        else:
            r = np.nan

        return self.obj._constructor_sliced(r, index=self.agg_axis)
    else:
        return self.obj.copy()

def apply_series_generator(self) -> tuple[ResType, Index]:
    assert callable(self.func)

    series_gen = self.series_generator
    res_index = self.result_index

    results = {}

    for i, v in enumerate(series_gen):
        results[i] = self.func(v, *self.args, **self.kwargs)
        if isinstance(results[i], ABCSeries):
            # If we have a view on v, we need to make a copy because
            #  series_generator will swap out the underlying data
            results[i] = results[i].copy(deep=False)

    return results, res_index

def apply_series_numba(self):
    if self.engine_kwargs.get("parallel", False):
        raise NotImplementedError(
            "Parallel apply is not supported when raw=False and engine='numba'"
        )
    if not self.obj.index.is_unique or not self.columns.is_unique:
        raise NotImplementedError(
            "The index/columns must be unique when raw=False and engine='numba'"
        )
    self.validate_values_for_numba()
    results = self.apply_with_numba()
    return results, self.result_index

def wrap_results(self, results: ResType, res_index: Index) -> DataFrame | Series:
    from pandas import Series

    # see if we can infer the results
    if len(results) > 0 and 0 in results and is_sequence(results[0]):
        return self.wrap_results_for_axis(results, res_index)

    # dict of scalars

    # the default dtype of an empty Series is `object`, but this
    # code can be hit by df.mean() where the result should have dtype
    # float64 even if it's an empty Series.
    constructor_sliced = self.obj._constructor_sliced
    if len(results) == 0 and constructor_sliced is Series:
        result = constructor_sliced(results, dtype=np.float64)
    else:
        result = constructor_sliced(results)
    result.index = res_index

    return result

def wrap_results_for_axis(
    self, results: ResType, res_index: Index
) -> DataFrame | Series:
    """return the results for the rows"""

    if self.result_type == "reduce":
        # e.g. test_apply_dict GH#8735
        res = self.obj._constructor_sliced(results)
        res.index = res_index
        return res

    elif self.result_type is None and all(
        isinstance(x, dict) for x in results.values()
    ):
        # Our operation was a to_dict op e.g.
        #  test_apply_dict GH#8735, test_apply_reduce_to_dict GH#25196 #37544
        res = self.obj._constructor_sliced(results)
        res.index = res_index
        return res

    try:
        result = self.obj._constructor(data=results)
    except ValueError as err:
        if "All arrays must be of the same length" in str(err):
            # e.g. result = [[2, 3], [1.5], ['foo', 'bar']]
            #  see test_agg_listlike_result GH#29587
            res = self.obj._constructor_sliced(results)
            res.index = res_index
            return res
        else:
            raise

    if not isinstance(results[0], ABCSeries):
        if len(result.index) == len(self.res_columns):
            result.index = self.res_columns

    if len(result.columns) == len(res_index):
        result.columns = res_index

    return result

def _make_ea_row_builder(
    col_arrays: list, dtype: ExtensionDtype, cls: type[ExtensionArray]
) -> Callable[[int], ExtensionArray]:
    """Build a callable that constructs an EA row for a given row index.

    Special-cases BaseMaskedArray and ArrowExtensionArray to avoid the
    overhead of _from_sequence per row. The fast paths require all columns
    to share ``dtype``; mixed-dtype frames fall through to the generic
    ``_from_sequence`` path (GH#65097).
    """
    homogeneous = all(col_arr.dtype == dtype for col_arr in col_arrays)

    if homogeneous and isinstance(dtype, BaseMaskedDtype):
        col_data = [col_arr._data for col_arr in col_arrays]
        col_masks = [col_arr._mask for col_arr in col_arrays]
        np_dtype = dtype.numpy_dtype
        masked_cls = cast("type[BaseMaskedArray]", cls)

        def build_row(row_idx: int) -> ExtensionArray:
            data = np.array([cd[row_idx] for cd in col_data], dtype=np_dtype)
            mask = np.array([cm[row_idx] for cm in col_masks], dtype=np.bool_)
            return masked_cls._simple_new(data, mask)

    elif homogeneous and isinstance(dtype, ArrowDtype):
        import pyarrow as pa

        pa_arrays = [col_arr._pa_array for col_arr in col_arrays]
        pa_type = dtype.pyarrow_dtype
        arrow_cls = cast("type[ArrowExtensionArray]", cls)

        def build_row(row_idx: int) -> ExtensionArray:
            pa_scalars = [pa_col[row_idx] for pa_col in pa_arrays]
            return arrow_cls(pa.array(pa_scalars, type=pa_type))

    else:

        def build_row(row_idx: int) -> ExtensionArray:
            row_data = np.array(
                [col_arr[row_idx] for col_arr in col_arrays], dtype=object
            )
            return cls._from_sequence(row_data, dtype=dtype)

    return build_row

def wrap_results_for_axis(
    self, results: ResType, res_index: Index
) -> DataFrame | Series:
    """return the results for the columns"""
    result: DataFrame | Series

    # we have requested to expand
    if self.result_type == "expand":
        result = self.infer_to_same_shape(results, res_index)

    # we have a non-series and don't want inference
    elif not isinstance(results[0], ABCSeries):
        result = self.obj._constructor_sliced(results)
        result.index = res_index

    # we may want to infer results
    else:
        result = self.infer_to_same_shape(results, res_index)

    return result

def apply(self) -> DataFrame | Series:
    obj = self.obj

    if len(obj) == 0:
        return self.apply_empty_result()

    # dispatch to handle list-like or dict-like
    if is_list_like(self.func):
        return self.apply_list_or_dict_like()

    if isinstance(self.func, str):
        # if we are a string, try to dispatch
        return self.apply_str()

    if self.by_row == "_compat":
        return self.apply_compat()

    # self.func is Callable
    return self.apply_standard()

def apply_compat(self):
    """compat apply method for funcs in listlikes and dictlikes.

     Used for each callable when giving listlikes and dictlikes of callables to
     apply. Needed for compatibility with Pandas < v2.1.

    .. versionadded:: 2.1.0
    """
    obj = self.obj
    func = self.func

    if callable(func):
        f = com.get_cython_func(func)
        if f and not self.args and not self.kwargs:
            return obj.apply(func, by_row=False)

    try:
        result = obj.apply(func, by_row="compat")
    except (ValueError, AttributeError, TypeError):
        result = obj.apply(func, by_row=False)
    return result

def apply_standard(self) -> DataFrame | Series:
    # caller is responsible for ensuring that f is Callable
    func = cast("Callable", self.func)
    obj = self.obj

    if isinstance(func, np.ufunc):
        with np.errstate(all="ignore"):
            return func(obj, *self.args, **self.kwargs)
    elif not self.by_row:
        return func(obj, *self.args, **self.kwargs)

    if self.args or self.kwargs:
        # _map_values does not support args/kwargs
        def curried(x):
            return func(x, *self.args, **self.kwargs)

    else:
        curried = func
    mapped = obj._map_values(mapper=curried)

    if len(mapped) and isinstance(mapped[0], ABCSeries):
        # GH#43986 Need to do list(mapped) in order to get treated as nested
        #  See also GH#25959 regarding EA support
        return obj._constructor_expanddim(list(mapped), index=obj.index)
    else:
        return obj._constructor(mapped, index=obj.index).__finalize__(
            obj, method="apply"

def agg_or_apply_list_like(
    self, op_name: Literal["agg", "apply"]
) -> DataFrame | Series:
    obj = self.obj
    kwargs = self.kwargs
    if op_name == "apply":
        kwargs = {**kwargs, "by_row": False}

    if getattr(obj, "axis", 0) == 1:
        raise NotImplementedError("axis other than 0 is not supported")

    if obj._selected_obj.ndim == 1:
        # For SeriesGroupBy this matches _obj_with_exclusions
        selected_obj = obj._selected_obj
    else:
        selected_obj = obj._obj_with_exclusions

    # Only set as_index=True on groupby objects, not Window or Resample
    # that inherit from this class.
    with com.temp_setattr(
        obj, "as_index", True, condition=hasattr(obj, "as_index")
    ):
        keys, results = self.compute_list_like(op_name, selected_obj, kwargs)
    result = self.wrap_results_list_like(keys, results)
    return result

def agg_or_apply_dict_like(
    self, op_name: Literal["agg", "apply"]
) -> DataFrame | Series:
    from pandas.core.groupby.generic import (
        DataFrameGroupBy,
        SeriesGroupBy,
    )

    assert op_name in ["agg", "apply"]

    obj = self.obj
    kwargs: dict[str, Any] = {}
    if op_name == "apply":
        by_row = "_compat" if self.by_row else False
        kwargs.update({"by_row": by_row})

    if getattr(obj, "axis", 0) == 1:
        raise NotImplementedError("axis other than 0 is not supported")

    selected_obj = obj._selected_obj
    selection = obj._selection

    is_groupby = isinstance(obj, (DataFrameGroupBy, SeriesGroupBy))

    # Numba Groupby engine/engine-kwargs passthrough
    if is_groupby:
        engine = self.kwargs.get("engine", None)
        engine_kwargs = self.kwargs.get("engine_kwargs", None)
        kwargs.update({"engine": engine, "engine_kwargs": engine_kwargs})

    with com.temp_setattr(
        obj, "as_index", True, condition=hasattr(obj, "as_index")
    ):
        result_index, result_data = self.compute_dict_like(
            op_name, selected_obj, selection, kwargs
        )
    result = self.wrap_results_dict_like(selected_obj, result_index, result_data)
    return result

def _has_infs(result) -> bool:
    if isinstance(result, np.ndarray):
        if result.dtype in ("f8", "f4"):
            # Note: outside of a nanops-specific test, we always have
            #  result.ndim == 1, so there is no risk of this ravel making a copy.
            return lib.has_infs(result.ravel("K"))
    try:
        return np.isinf(result).any()
    except (TypeError, NotImplementedError):
        # if it doesn't support infs, then it can't have infs
        return False

def _get_fill_value(
    dtype: DtypeObj, fill_value: Scalar | None = None, fill_value_typ=None
):
    """return the correct fill value for the dtype of the values"""
    if fill_value is not None:
        return fill_value
    if _na_ok_dtype(dtype):
        if fill_value_typ is None:
            return np.nan
        elif fill_value_typ == "+inf":
            return np.inf
        else:
            return -np.inf
    elif dtype.kind == "u":
        # Unsigned ints: use a uint64 sentinel so np.where keeps the values
        # unsigned.  An int64 fill would force a uint64/int64 mix to promote to
        # float64, losing precision for values above 2**53 and giving the wrong
        # idxmin/idxmax/min/max (GH#64478).  u8max/0 also bracket the full
        # uint64 range, unlike i8max which real values can exceed.
        if fill_value_typ == "+inf":
            return np.uint64(lib.u8max)
        return np.uint64(0)
    elif fill_value_typ == "+inf":
        # need the max int here
        # Return as np.int64 so that np.where promotes the dtype
        # instead of raising OverflowError (numpy 2.5+) when the
        # value doesn't fit in the array's dtype (e.g. int8).
        return np.int64(lib.i8max)
    else:
        return np.int64(iNaT)

def _get_dtype_max(dtype: np.dtype) -> np.dtype:
    # return a platform independent precision dtype
    dtype_max = dtype
    if dtype.kind in "bi":
        dtype_max = np.dtype(np.int64)
    elif dtype.kind == "u":
        dtype_max = np.dtype(np.uint64)
    elif dtype.kind == "f":
        dtype_max = np.dtype(np.float64)
    return dtype_max

def _wrap_results(result, dtype: np.dtype, fill_value=None, result_mask=None):
    """wrap our results if needed"""
    if result is NaT:
        pass

    elif dtype.kind == "M":
        if fill_value is None:
            # GH#24293
            fill_value = iNaT
        if not isinstance(result, np.ndarray):
            assert not isna(fill_value), "Expected non-null fill_value"
            if result == fill_value:
                result = np.nan

            if isna(result):
                result = np.datetime64("NaT", "ns").astype(dtype)
            else:
                result = np.int64(result).view(dtype)
            # retain original unit
            result = result.astype(dtype, copy=False)
        else:
            # If we have float dtype, taking a view will give the wrong result
            result = result.astype(dtype)
    elif dtype.kind == "m":
        if not isinstance(result, np.ndarray):
            if result_mask or result == fill_value or np.isnan(result):
                unit = np.datetime_data(dtype)[0]
                result = np.timedelta64("NaT", unit)  # type: ignore[call-overload]

            elif np.fabs(result) > lib.i8max:
                # GH#43178: raise if the result is too large for the dtype's unit
                raise OutOfBoundsTimedelta("overflow in timedelta operation")
            else:
                # return a timedelta64 with the original unit
                result = np.int64(result).astype(dtype, copy=False)

        else:
            overflow = np.abs(result) > lib.i8max
            if result_mask is not None:
                # GH#43178: positions that will be set to NaT (skipna=False) are
                #  exempt from the overflow check and must not trip the cast below
                overflow &= ~result_mask
                result = np.where(result_mask, 0, result)
            if overflow.any():
                # GH#43178: raise if any result is too large for the dtype's unit
                raise OutOfBoundsTimedelta("overflow in timedelta operation")
            result = result.astype("m8[ns]").view(dtype)

    return result

def _first_unconvertible(values: np.ndarray) -> object:
    """
    Return the element responsible for a failed `_ensure_numeric` conversion.
    """
    for val in values.ravel():
        if not _complex_castable(val):
            return val
    # numpy balked at something complex() accepts; report the values as a whole
    return values

def _mask_datetimelike_result(
    result: np.ndarray | np.datetime64 | np.timedelta64,
    axis: AxisInt | None,
    mask: npt.NDArray[np.bool_],
    orig_values: np.ndarray,
) -> np.ndarray | np.datetime64 | np.timedelta64 | NaTType:
    if isinstance(result, np.ndarray):
        # we need to apply the mask
        result = result.astype("i8").view(orig_values.dtype)
        axis_mask = mask.any(axis=axis)
        result[axis_mask] = iNaT
    elif mask.any():
        return np.int64(iNaT).view(orig_values.dtype)
    return result

def _maybe_fix_arg_at_na(
    result: np.ndarray,
    mask: npt.NDArray[np.bool_] | None,
    axis: AxisInt | None,
) -> np.ndarray:
    # helper function for nanargmin/nanargmax.  Masked positions carry either
    # the +/-inf sentinel or, for object dtype, the value at the first unmasked
    # position (GH#4147).  Either way an argmin/argmax landing on a masked
    # position means the fill is the extremum, so the first unmasked position
    # holds it and is the correct result (GH#64478)
    if mask is None or not mask.any():
        return result
    if axis is None or mask.ndim == 1:
        if mask.ravel()[result] and not mask.all():
            # error: Incompatible return value type (got "signedinteger[_32Bit
            # | _64Bit]", expected "ndarray[tuple[Any, ...], dtype[Any]]")
            return (~mask).ravel().argmax()  # type: ignore[return-value]
    else:
        indexer = np.expand_dims(result, axis)
        arg_is_na = np.take_along_axis(mask, indexer, axis).squeeze(axis)
        if arg_is_na.any():
            result = np.where(arg_is_na, (~mask).argmax(axis), result)
    return result

def _maybe_arg_null_out(
    result: np.ndarray,
    axis: AxisInt | None,
    mask: npt.NDArray[np.bool_] | None,
    skipna: bool,
) -> np.ndarray | int:
    # helper function for nanargmin/nanargmax
    if mask is None:
        return result

    if axis is None or not getattr(result, "ndim", False):
        if skipna and mask.all():
            raise ValueError("Encountered all NA values")
        elif not skipna and mask.any():
            raise ValueError("Encountered an NA value with skipna=False")
    elif skipna and mask.all(axis).any():
        raise ValueError("Encountered all NA values")
    elif not skipna and mask.any(axis).any():
        raise ValueError("Encountered an NA value with skipna=False")
    return result

def _get_counts(
    values_shape: Shape,
    mask: npt.NDArray[np.bool_] | None,
    axis: AxisInt | None,
    dtype: np.dtype[np.floating] = np.dtype(np.float64),
) -> np.floating | npt.NDArray[np.floating]:
    """
    Get the count of non-null values along an axis

    Parameters
    ----------
    values_shape : tuple of int
        shape tuple from values ndarray, used if mask is None
    mask : Optional[ndarray[bool]]
        locations in values that should be considered missing
    axis : Optional[int]
        axis to count along
    dtype : type, optional
        type to use for count

    Returns
    -------
    count : scalar or array
    """
    if axis is None:
        if mask is not None:
            n = mask.size - mask.sum()
        else:
            n = np.prod(values_shape)
        return dtype.type(n)

    if mask is not None:
        count = mask.shape[axis] - mask.sum(axis)
    else:
        count = values_shape[axis]

    if is_integer(count):
        return dtype.type(count)
    return count.astype(dtype, copy=False)

def _maybe_null_out(
    result: np.ndarray | np.int64 | float | NaTType,
    axis: AxisInt | None,
    mask: npt.NDArray[np.bool_] | None,
    shape: tuple[int, ...],
    min_count: int = 1,
    datetimelike: bool = False,
) -> np.ndarray | np.int64 | float | NaTType:
    """
    Returns
    -------
    Dtype
        The product of all elements on a given axis. ( NaNs are treated as 1)
    """
    if min_count <= 0:
        # min_count <= 0 never nulls out; short-circuit
        return result

    if axis is not None and isinstance(result, np.ndarray):
        if mask is not None:
            null_mask = (mask.shape[axis] - mask.sum(axis) - min_count) < 0
        else:
            # we have no nulls, kept mask=None in _maybe_get_mask
            below_count = shape[axis] - min_count < 0
            new_shape = shape[:axis] + shape[axis + 1 :]
            null_mask = np.broadcast_to(below_count, new_shape)

        if np.any(null_mask):
            if datetimelike:
                # GH#60646 For datetimelike, no need to cast to float
                result[null_mask] = iNaT
            elif is_numeric_dtype(result):
                if np.iscomplexobj(result):
                    result = result.astype("c16")
                elif not is_float_dtype(result):
                    result = result.astype("f8", copy=False)
                result[null_mask] = np.nan
            else:
                # GH12941, use None to auto cast null
                result[null_mask] = None
    elif result is not NaT:
        if check_below_min_count(shape, mask, min_count):
            result_dtype = getattr(result, "dtype", None)
            if is_float_dtype(result_dtype):
                # error: Item "None" of "Optional[Any]" has no attribute "type"
                result = result_dtype.type("nan")  # type: ignore[union-attr]
            else:
                result = np.nan

    return result

def get_corr_func(
    method: CorrelationMethod,
) -> Callable[[np.ndarray, np.ndarray], float]:
    if method == "kendall":
        from scipy.stats import kendalltau

        def func(a, b):  # pyright: ignore[reportRedeclaration]
            return kendalltau(a, b)[0]

        return func
    elif method == "spearman":
        from scipy.stats import spearmanr

        def func(a, b):  # pyright: ignore[reportRedeclaration]
            return spearmanr(a, b)[0]

        return func
    elif method == "pearson":

        def func(a, b):
            return _pearson_corr(a, b)

        return func
    elif callable(method):
        return method

    raise ValueError(
        f"Unknown method '{method}', expected one of "

def nancov(
    a: np.ndarray,
    b: np.ndarray,
    *,
    min_periods: int | None = None,
    ddof: int | None = 1,
) -> float:
    if len(a) != len(b):
        raise AssertionError("Operands to nancov must have same size")

    if min_periods is None:
        min_periods = 1

    valid = notna(a) & notna(b)
    if not valid.all():
        a = a[valid]
        b = b[valid]

    if len(a) < min_periods:
        return np.nan

    a = _ensure_numeric(a)
    b = _ensure_numeric(b)

    return np.cov(a, b, ddof=ddof)[0, 1]

def __call__(self, alt: F) -> F:
    bn_name = self.name or alt.__name__

    try:
        bn_func = getattr(bn, bn_name)
    except (AttributeError, NameError):  # pragma: no cover
        bn_func = None

    @functools.wraps(alt)
    def f(
        values: np.ndarray,
        *,
        axis: AxisInt | None = None,
        skipna: bool = True,
        **kwds,
    ):
        if len(self.kwargs) > 0:
            for k, v in self.kwargs.items():
                if k not in kwds:
                    kwds[k] = v

        # GH#18976 bottleneck's nanmin/nanmax raise on empty input; skip it
        #  and let each nanops function return the NA for its own dtype.
        if (
            _USE_BOTTLENECK
            and skipna
            and values.size > 0
            and _bn_ok_dtype(values.dtype, bn_name)
        ):
            if kwds.get("mask", None) is None:
                # `mask` is not recognised by bottleneck, would raise
                #  TypeError if called
                kwds.pop("mask", None)
                result = bn_func(values, axis=axis, **kwds)  # pyright: ignore[reportOptionalCall]

                # prefer to treat inf/-inf as NA, but must compute the func
                # twice :(
                if _has_infs(result):
                    result = alt(values, axis=axis, skipna=skipna, **kwds)
            else:
                result = alt(values, axis=axis, skipna=skipna, **kwds)
        else:
            result = alt(values, axis=axis, skipna=skipna, **kwds)

        return result

    return cast("F", f)

def consensus_name_attr(objs: list[Series | DataFrame]) -> Hashable | None:
    name = objs[0].name
    for obj in objs[1:]:
        try:
            if obj.name != name:
                name = None
                break
        except ValueError:
            name = None
            break
    return name

def not_none(*args: object) -> Generator[object]:
    """
    Returns a generator consisting of the arguments that are not None.
    """
    return (arg for arg in args if arg is not None)

def asarray_tuplesafe(values: Iterable, dtype: NpDtype | None = None) -> ArrayLike:
    if not (isinstance(values, (list, tuple)) or hasattr(values, "__array__")):
        values = list(values)
    elif isinstance(values, ABCIndex):
        return values._values
    elif isinstance(values, ABCSeries):
        return values._values

    if isinstance(values, list) and dtype in [np.object_, object]:
        return construct_1d_object_array_from_listlike(values)

    try:
        result = np.asarray(values, dtype=dtype)
    except ValueError:
        # Using try/except since it's more performant than checking is_list_like
        # over each element
        # error: Argument 1 to "construct_1d_object_array_from_listlike"
        # has incompatible type "Iterable[Any]"; expected "Sized"
        return construct_1d_object_array_from_listlike(values)  # type: ignore[arg-type]

    if issubclass(result.dtype.type, str):
        result = np.asarray(values, dtype=object)

    if result.ndim == 2:
        # Avoid building an array of arrays:
        values = [tuple(x) for x in values]
        result = construct_1d_object_array_from_listlike(values)

    return result

def maybe_iterable_to_list(obj: Iterable[T] | T) -> Collection[T] | T:
    """
    If obj is Iterable but not list-like, consume into list.
    """
    if isinstance(obj, abc.Iterable) and not isinstance(obj, abc.Sized):
        return list(obj)
    obj = cast("Collection", obj)
    return obj

def is_true_slices(line: abc.Iterable) -> abc.Generator[bool, None, None]:
    """
    Find non-trivial slices in "line": yields a bool.
    """
    for k in line:
        yield isinstance(k, slice) and not is_null_slice(k)

def get_callable_name(obj: object) -> str | None:
    # typical case has name
    if hasattr(obj, "__name__"):
        return obj.__name__  # pyright: ignore[reportAttributeAccessIssue]
    # some objects don't; could recurse
    if isinstance(obj, partial):
        return get_callable_name(obj.func)
    # fall back to class name
    if callable(obj):
        return type(obj).__name__
    # everything failed (probably because the argument
    # wasn't actually callable); we return None
    # instead of the empty string in this case to allow
    # distinguishing between no name and a name of ''
    return None

def apply_if_callable(maybe_callable: Any, obj: Any, **kwargs: Any) -> Any:
    """
    Evaluate possibly callable input using obj and kwargs if it is callable,
    otherwise return as it is.

    Parameters
    ----------
    maybe_callable : possibly a callable
    obj : NDFrame
    **kwargs
    """
    if isinstance(maybe_callable, Expression):
        return maybe_callable._eval_expression(obj, **kwargs)
    elif callable(maybe_callable):
        return maybe_callable(obj, **kwargs)

    return maybe_callable

def convert_to_list_like(
    values: Hashable | Iterable | AnyArrayLike,
) -> list | AnyArrayLike:
    """
    Convert list-like or scalar input to list-like. List, numpy and pandas array-like
    inputs are returned unmodified whereas others are converted to list.
    """
    if isinstance(values, (list, np.ndarray, ABCIndex, ABCSeries, ABCExtensionArray)):
        return values
    elif isinstance(values, abc.Iterable) and not isinstance(values, str):
        return list(values)

    return [values]

def __getitem__(self, key):
    check_dict_or_set_indexers(key)
    key = com.apply_if_callable(key, self)

    if key is Ellipsis:
        return self.copy(deep=False)

    key_is_scalar = is_scalar(key)
    if isinstance(key, (list, tuple)):
        key = unpack_1tuple(key)

    elif key_is_scalar:
        # Note: GH#50617 in 3.0 we changed int key to always be treated as
        #  a label, matching DataFrame behavior.
        return self._get_value(key)

    # Convert generator to list before going through hashable part
    # (We will iterate through the generator there to check for slices)
    if is_iterator(key):
        key = list(key)

    if is_hashable(key, allow_slice=False):
        # Otherwise index.get_value will raise InvalidIndexError
        try:
            # For labels that don't resolve as scalars like tuples and frozensets
            result = self._get_value(key)

            return result

        except (KeyError, TypeError, InvalidIndexError):
            # InvalidIndexError for e.g. generator
            #  see test_series_getitem_corner_generator
            if isinstance(key, tuple) and isinstance(self.index, MultiIndex):
                # We still have the corner case where a tuple is a key
                # in the first level of our MultiIndex
                return self._get_values_tuple(key)

    if isinstance(key, slice):
        # Do slice check before somewhat-costly is_bool_indexer
        return self._getitem_slice(key)

    if com.is_bool_indexer(key):
        key = check_bool_indexer(self.index, key)
        key = np.asarray(key, dtype=bool)
        return self._get_rows_with_mask(key)

    return self._get_with(key)

def _get_with(self, key):
    # other: fancy integer or otherwise
    if isinstance(key, ABCDataFrame):
        raise TypeError(
            "Indexing a Series with DataFrame is not "
            "supported, use the appropriate DataFrame column"
        )
    elif isinstance(key, tuple):
        return self._get_values_tuple(key)

    return self.loc[key]

def _get_values_tuple(self, key: tuple):
    # mpl hackaround
    if com.any_none(*key):
        # mpl compat if we look up e.g. ser[:, np.newaxis];
        #  see tests.series.timeseries.test_mpl_compat_hack
        # the asarray is needed to avoid returning a 2D DatetimeArray
        result = np.asarray(self._values[key])
        disallow_ndim_indexing(result)
        return result

    if not isinstance(self.index, MultiIndex):
        raise KeyError("key of type tuple not found and not a MultiIndex")

    # If key is contained, would have returned by now
    indexer, new_index = self.index.get_loc_level(key)
    new_ser = self._constructor(self._values[indexer], index=new_index, copy=False)
    if isinstance(indexer, slice):
        new_ser._mgr.add_references(self._mgr)
    return new_ser.__finalize__(self)

def _get_value(self, label, takeable: bool = False):
    """
    Quickly retrieve single value at passed index label.

    Parameters
    ----------
    label : object
    takeable : interpret the index as indexers, default False

    Returns
    -------
    scalar value
    """
    if takeable:
        return self._ixs(label)

    # Similar to Index.get_value, but we do not fall back to positional
    loc = self.index.get_loc(label)

    if is_integer(loc):
        return self._ixs(loc)

    if isinstance(self.index, MultiIndex):
        mi = self.index
        new_values = self._values[loc]
        if len(new_values) == 1 and mi.nlevels == 1:
            # If more than one level left, we can not return a scalar
            return maybe_unbox_numpy_scalar(
                new_values[0], object_with_dtype=new_values
            )

        new_index = mi[loc]
        new_index = maybe_droplevels(new_index, label)
        new_ser = self._constructor(
            new_values, index=new_index, name=self.name, copy=False
        )
        if isinstance(loc, slice):
            new_ser._mgr.add_references(self._mgr)
        return new_ser.__finalize__(self)

    else:
        return self.iloc[loc]

def __setitem__(self, key, value) -> None:
    if not CHAINED_WARNING_DISABLED:
        # the cheaper opcode check is deliberately last: on Python 3.14
        # a plain `df[col] = value` reaches the refcount check, and
        # is_local_in_caller_frame already short-circuits it there
        if (
            sys.getrefcount(self) <= REF_COUNT
            and not com.is_local_in_caller_frame(self)
            and com.is_setitem_syntax_in_caller_frame()
        ):
            warnings.warn(
                _chained_assignment_msg, ChainedAssignmentError, stacklevel=2
            )

    check_dict_or_set_indexers(key)
    key = com.apply_if_callable(key, self)

    if key is Ellipsis:
        key = slice(None)

    if isinstance(key, slice):
        indexer = self.index._convert_slice_indexer(key, kind="getitem")
        return self._set_values(indexer, value)

    try:
        self._set_with_engine(key, value)
    except KeyError:
        # We have a scalar (or for MultiIndex or object-dtype, scalar-like)
        #  key that is not present in self.index.
        # GH#12862 adding a new key to the Series
        self.loc[key] = value

    except (TypeError, ValueError, LossySetitemError):
        # The key was OK, but we cannot set the value losslessly
        indexer = self.index.get_loc(key)  # type: ignore[assignment]
        self._set_values(indexer, value)

    except InvalidIndexError as err:
        if isinstance(key, tuple) and not isinstance(self.index, MultiIndex):
            # cases with MultiIndex don't get here bc they raise KeyError
            # e.g. test_basic_getitem_setitem_corner
            raise KeyError(
                "key of type tuple not found and not a MultiIndex"
            ) from err

        if com.is_bool_indexer(key):
            key = check_bool_indexer(self.index, key)
            key = np.asarray(key, dtype=bool)

            if (
                is_list_like(value)
                and len(value) != len(self)
                and not isinstance(value, Series)
                and not is_object_dtype(self.dtype)
            ):
                # Series will be reindexed to have matching length inside
                #  _where call below
                # GH#44265
                indexer = key.nonzero()[0]
                self._set_values(indexer, value)
                return

            # otherwise with listlike other we interpret series[mask] = other
            #  as series[mask] = other[mask]
            try:
                self._where(~key, value, inplace=True)
            except InvalidIndexError:
                # test_where_dups
                self.iloc[key] = value
            return

        else:
            self._set_with(key, value)

def _reindex_indexer(
    self,
    new_index: Index | None,
    indexer: npt.NDArray[np.intp] | None,
) -> Series:
    # Note: new_index is None iff indexer is None
    # if not None, indexer is np.intp
    if indexer is None and (
        new_index is None or new_index.names == self.index.names
    ):
        return self.copy(deep=False)

    new_values = algorithms.take_nd(
        self._values, indexer, allow_fill=True, fill_value=None
    )
    return self._constructor(new_values, index=new_index, copy=False)

def _cmp_method(self, other, op) -> Series:
    res_name = ops.get_op_result_name(self, other)

    if isinstance(other, Series) and not self._indexed_same(other):
        raise ValueError("Can only compare identically-labeled Series objects")

    lvalues = self._values
    if not isinstance(lvalues, ExtensionArray) and lvalues.dtype != object:
        # For EA-backed values the warning is emitted by the EA's own
        # _cmp_method; object dtype already treats a non-standard listlike
        # as scalar-like, so it needs no warning either (GH#62423).
        ops.maybe_warn_listlike(other)
    rvalues = extract_array(other, extract_numpy=True, extract_range=True)

    res_values = ops.comparison_op(lvalues, rvalues, op)

    return self._construct_result(res_values, name=res_name, other=other)

def _align_for_op(self, right, align_asobject: bool = False):
    """align lhs and rhs Series"""
    # TODO: Different from DataFrame._align_for_op, list, tuple and ndarray
    # are not coerced here
    # because Series has inconsistencies described in GH#13637
    left = self

    if isinstance(right, Series):
        # avoid repeated alignment
        if not left.index.equals(right.index):
            if align_asobject:
                if left.dtype not in (object, np.bool_) or right.dtype not in (
                    object,
                    np.bool_,
                ):
                    pass
                    # GH#52538 no longer cast in these cases
                else:
                    # to keep original value's dtype for bool ops
                    left = left.astype(object)
                    right = right.astype(object)

            left, right = left.align(right)

    return left, right

def _flex_method(
    self, other, op, *, level=None, fill_value=None, axis: Axis = 0
) -> Series:
    if axis is not None:
        self._get_axis_number(axis)

    res_name = ops.get_op_result_name(self, other)

    if isinstance(other, Series):
        return self._binop(other, op, level=level, fill_value=fill_value)
    elif (isinstance(other, np.ndarray) and other.ndim > 0) or isinstance(
        other, (list, tuple, ExtensionArray)
    ):
        if isinstance(other, tuple):
            op_name = op.__name__.strip("_")
            warnings.warn(
                f"Series.{op_name} with a tuple is deprecated and will be "
                "treated as scalar-like in a future version. "
                "Explicitly wrap in a numpy array instead.",
                Pandas4Warning,
                stacklevel=find_stack_level(),
            )
        if len(other) != len(self):
            raise ValueError("Lengths must be equal")
        other = self._constructor(other, self.index, copy=False)
        result = self._binop(other, op, level=level, fill_value=fill_value)
        result._name = res_name
        return result
    elif isinstance(other, ABCDataFrame):
        # GH#46179
        raise TypeError(
            f"Series.{op.__name__.strip('_')} does not support a DataFrame "
            f"`other`. Use df.{op.__name__.strip('_')}(ser) instead."
        )
    else:
        if fill_value is not None:
            if isna(other):
                return op(self, fill_value)
            self = self.fillna(fill_value)

        return op(self, other)

def _reset_cache(self, key: str | None = None) -> None:
    """
    Reset cached properties. If ``key`` is passed, only clears that key.
    """
    if not hasattr(self, "_cache"):
        return
    if key is None:
        self._cache.clear()
    else:
        self._cache.pop(key, None)

def __sizeof__(self) -> int:
    """
    Generates the total memory usage for an object that returns
    either a value or Series of values
    """
    memory_usage = getattr(self, "memory_usage", None)
    if memory_usage:
        mem = memory_usage(deep=True)
        return int(mem if is_scalar(mem) else mem.sum())

    # no memory_usage attribute, so fall back to object's 'sizeof'
    return super().__sizeof__()

def _selected_obj(self):
    if self._selection is None or isinstance(self.obj, ABCSeries):
        return self.obj
    else:
        return self.obj[self._selection]

def _obj_with_exclusions(self):
    if isinstance(self.obj, ABCSeries):
        return self.obj

    if self._selection is not None:
        return self.obj[self._selection_list]

    if len(self.exclusions) > 0:
        return self.obj._drop_axis(self.exclusions, axis=1)
    else:
        return self.obj

def __getitem__(self, key):
    if self._selection is not None:
        raise IndexError(f"Column(s) {self._selection} already selected")

    if isinstance(key, tuple):
        warnings.warn(
            "Passing a tuple to __getitem__ is deprecated and "
            "will raise a KeyError in a future version. Use a list instead.",
            Pandas4Warning,
            stacklevel=find_stack_level(),
        )
        key = list(key)

    if isinstance(key, (list, ABCSeries, ABCIndex, np.ndarray)):
        if len(self.obj.columns.intersection(key)) != len(set(key)):
            bad_keys = list(set(key).difference(self.obj.columns))
            raise KeyError(f"Columns not found: {str(bad_keys)[1:-1]}")
        return self._gotitem(list(key), ndim=2)

    else:
        if key not in self.obj:
            raise KeyError(f"Column not found: {key}")
        ndim = self.obj[key].ndim
        return self._gotitem(key, ndim=ndim)

def _infer_selection(self, key, subset: Series | DataFrame):
    """
    Infer the `selection` to pass to our constructor in _gotitem.
    """
    # Shared by Rolling and Resample
    selection = None
    if subset.ndim == 2 and (
        (lib.is_scalar(key) and key in subset) or lib.is_list_like(key)
    ):
        selection = key
    elif subset.ndim == 1 and lib.is_scalar(key) and key == subset.name:
        selection = key
    return selection

def _is_np_bool_backed(obj: NDFrame) -> bool:
    """
    Is obj backed entirely by numpy bool arrays?

    Such an object needs neither filling nor casting to be used as a `where`
    condition, so we can skip that machinery altogether (GH#51547).
    """
    if isinstance(obj, ABCDataFrame):
        dtypes: list[DtypeObj] = obj._blk_dtypes
    else:
        dtypes = [obj.dtype]
    return all(lib.is_np_dtype(dtype, "b") for dtype in dtypes)

def _init_mgr(
    cls,
    mgr: Manager,
    axes: dict[Literal["index", "columns"], Axes | None],
    dtype: DtypeObj | None = None,
    copy: bool = False,
) -> Manager:
    """passed a manager and a axes dict"""
    for a, axe in axes.items():
        if axe is not None:
            axe = ensure_index(axe)
            bm_axis = cls._get_block_manager_axis(a)
            mgr = mgr.reindex_axis(axe, axis=bm_axis)

    # make a copy if explicitly requested
    if copy:
        mgr = mgr.copy(deep=True)
    if dtype is not None:
        # avoid further copies if we can
        if (
            isinstance(mgr, BlockManager)
            and len(mgr.blocks) == 1
            and mgr.blocks[0].values.dtype == dtype
        ):
            pass
        else:
            mgr = mgr.astype(dtype=dtype)
    return mgr

def _validate_dtype(cls, dtype) -> DtypeObj | None:
    """validate the passed dtype"""
    if dtype is not None:
        dtype = pandas_dtype(dtype)

        # a compound dtype
        if dtype.kind == "V" and not isinstance(dtype, ExtensionDtype):
            raise NotImplementedError(
                "compound dtypes are not implemented "
                f"in the {cls.__name__} constructor"
            )

    return dtype

def _construct_axes_dict(
    self, axes: Sequence[Axis] | None = None, **kwargs: AxisInt
) -> dict:
    """Return an axes dictionary for myself."""
    d = {a: self._get_axis(a) for a in (axes or self._AXIS_ORDERS)}
    # error: Argument 1 to "update" of "MutableMapping" has incompatible type
    # "Dict[str, Any]"; expected "SupportsKeysAndGetItem[Union[int, str], Any]"
    d.update(kwargs)  # type: ignore[arg-type]
    return d

def _get_index_resolvers(self) -> dict[Hashable, Series | MultiIndex]:
    from pandas.core.computation.parsing import clean_column_name

    d: dict[str, Series | MultiIndex] = {}
    for axis_name in self._AXIS_ORDERS:
        d.update(self._get_axis_resolvers(axis_name))

    return {clean_column_name(k): v for k, v in d.items() if not isinstance(k, int)}

def _get_cleaned_column_resolvers(self) -> dict[Hashable, Series | DataFrame]:
    """
    Return the special character free column resolvers of a DataFrame.

    Column names with special characters are 'cleaned up' so that they can
    be referred to by backtick quoting.
    Used in :meth:`DataFrame.eval`.
    """
    from pandas.core.computation.parsing import clean_column_name

    if isinstance(self, ABCSeries):
        return {clean_column_name(self.name): self}

    return {clean_column_name(k): self[k] for k in self.columns}

def _rename(
    self,
    mapper: Renamer | None = None,
    *,
    index: Renamer | None = None,
    columns: Renamer | None = None,
    axis: Axis | None = None,
    inplace: bool = False,
    level: Level | None = None,
    errors: str = "ignore",
) -> Self | None:
    # called by Series.rename and DataFrame.rename

    if mapper is None and index is None and columns is None:
        raise TypeError("must pass an index to rename")

    if index is not None or columns is not None:
        if axis is not None:
            raise TypeError(
                "Cannot specify both 'axis' and any of 'index' or 'columns'"
            )
        if mapper is not None:
            raise TypeError(
                "Cannot specify both 'mapper' and any of 'index' or 'columns'"
            )
    # use the mapper argument
    elif axis and self._get_axis_number(axis) == 1:
        columns = mapper
    else:
        index = mapper

    self._check_inplace_and_allows_duplicate_labels(inplace)
    result = self if inplace else self.copy(deep=False)

    for axis_no, replacements in enumerate((index, columns)):
        if replacements is None:
            continue

        ax = self._get_axis(axis_no)
        f = common.get_rename_function(replacements)

        if level is not None:
            level = ax._get_level_number(level)

        if isinstance(replacements, ABCSeries) and not replacements.index.is_unique:
            # GH#58621
            raise ValueError("Cannot rename with a Series with non-unique index.")

        # GH 13473
        if not callable(replacements):
            if ax._is_multi and level is not None:
                indexer = ax.get_level_values(level).get_indexer_for(replacements)  # type: ignore[arg-type]
            else:
                indexer = ax.get_indexer_for(replacements)  # type: ignore[arg-type]

            if errors == "raise" and len(indexer[indexer == -1]):
                missing_labels = [
                    label
                    for index, label in enumerate(replacements)
                    if indexer[index] == -1
                ]
                raise KeyError(f"{missing_labels} not found in axis")

        new_index = ax._transform_index(f, level=level)
        result._set_axis_nocheck(new_index, axis=axis_no, inplace=True)

    if inplace:
        self._update_inplace(result)
        return None
    else:
        return result.__finalize__(self, method="rename")

def rename_axis(
    self,
    mapper: IndexLabel | lib.NoDefault = lib.no_default,
    *,
    index=lib.no_default,
    columns=lib.no_default,
    axis: Axis = 0,
    copy: bool | lib.NoDefault = lib.no_default,
    inplace: bool = False,
) -> Self | None:
    self._check_copy_deprecation(copy)
    axes = {"index": index, "columns": columns}

    if axis is not None:
        axis = self._get_axis_number(axis)

    inplace = validate_bool_kwarg(inplace, "inplace")

    if mapper is not lib.no_default:
        # Use v0.23 behavior if a scalar or list
        non_mapper = is_scalar(mapper) or (
            is_list_like(mapper) and not is_dict_like(mapper)
        )
        if non_mapper:
            return self._set_axis_name(mapper, axis=axis, inplace=inplace)
        else:
            raise ValueError("Use `.rename` to alter labels with a mapper.")
    else:
        # Use new behavior.  Means that index and/or columns
        # is specified
        result = self if inplace else self.copy(deep=False)

        for axis in range(self._AXIS_LEN):
            v = axes.get(self._get_axis_name(axis))
            if v is lib.no_default:
                continue
            non_mapper = is_scalar(v) or (is_list_like(v) and not is_dict_like(v))
            if non_mapper:
                newnames = v
            else:
                f = common.get_rename_function(v)
                curnames = self._get_axis(axis).names
                newnames = [f(name) for name in curnames]  # pyright: ignore[reportOptionalCall]
            result._set_axis_name(newnames, axis=axis, inplace=True)
        if not inplace:
            return result
        return None

def __array__(
    self, dtype: npt.DTypeLike | None = None, copy: bool | None = None
) -> np.ndarray:
    if copy is False and not self._mgr.is_single_block and not self.empty:
        # check this manually, otherwise ._values will already return a copy
        # and np.array(values, copy=False) will not raise an error
        raise ValueError(
            "Unable to avoid copy while creating an array as requested."
        )
    values = self._values
    if copy is None:
        # Note: branch avoids `copy=None` for NumPy 1.x support
        arr = np.asarray(values, dtype=dtype)
    else:
        arr = np.array(values, dtype=dtype, copy=copy)

    if (
        copy is not True
        and astype_is_view(values.dtype, arr.dtype)
        and self._mgr.is_single_block
    ):
        # Check if both conversions can be done without a copy
        if astype_is_view(self.dtypes.iloc[0], values.dtype) and astype_is_view(
            values.dtype, arr.dtype
        ):
            arr = arr.view()
            arr.flags.writeable = False
    return arr

def __getstate__(self) -> dict[str, Any]:
    meta = {k: getattr(self, k, None) for k in self._metadata}
    return {
        "_mgr": self._mgr,
        "_typ": self._typ,
        "_metadata": self._metadata,
        "attrs": self.attrs,
        "_flags": {k: self.flags[k] for k in self.flags._keys},
        **meta,

def __setstate__(self, state) -> None:
    if isinstance(state, BlockManager):
        self._mgr = state
    elif isinstance(state, dict):
        if "_data" in state and "_mgr" not in state:
            # compat for older pickles
            state["_mgr"] = state.pop("_data")
        typ = state.get("_typ")
        if typ is not None:
            attrs = state.get("_attrs", {})
            if attrs is None:  # should not happen, but better be on the safe side
                attrs = {}
            object.__setattr__(self, "_attrs", attrs)
            flags = state.get("_flags", {"allows_duplicate_labels": True})
            object.__setattr__(self, "_flags", Flags(self, **flags))

            # set in the order of internal names
            # to avoid definitional recursion
            # e.g. say fill_value needing _mgr to be
            # defined
            meta = set(self._internal_names + self._metadata)
            for k in meta:
                # _metadata is handled below: assigning a pre-2.1 pickle's
                # ["name"] here would mask the class's ["_name"], see GH#61819
                if k in state and k not in ("_flags", "_metadata"):
                    v = state[k]
                    object.__setattr__(self, k, v)

            if "_metadata" in state:
                # merge rather than replace, so a subclass that extends
                # _metadata per instance keeps its entries
                cls_meta = list(self._metadata)
                merged = list(dict.fromkeys(cls_meta + list(state["_metadata"])))
                if merged != cls_meta:
                    object.__setattr__(self, "_metadata", merged)

            for k, v in state.items():
                if k not in meta:
                    object.__setattr__(self, k, v)

        else:
            raise NotImplementedError("Pre-0.12 pickles are no longer supported")
    elif len(state) == 2:
        raise NotImplementedError("Pre-0.12 pickles are no longer supported")

def _getitem_slice(self, key: slice) -> Self:
    """
    __getitem__ for the case where the key is a slice object.
    """
    # _convert_slice_indexer to determine if this slice is positional
    #  or label based, and if the latter, convert to positional
    slobj = self.index._convert_slice_indexer(key, kind="getitem")
    if isinstance(slobj, np.ndarray):
        # reachable with DatetimeIndex
        indexer = lib.maybe_indices_to_slice(slobj.astype(np.intp), len(self))
        if isinstance(indexer, np.ndarray):
            # GH#43223 If we can not convert, use take
            return self.take(indexer, axis=0)
        slobj = indexer
    return self._slice(slobj)

def __delitem__(self, key) -> None:
    """
    Delete item
    """
    deleted = False

    maybe_shortcut = False
    if self.ndim == 2 and isinstance(self.columns, MultiIndex):
        try:
            # By using engine's __contains__ we effectively
            # restrict to same-length tuples
            maybe_shortcut = key not in self.columns._engine
        except TypeError:
            pass

    if maybe_shortcut:
        # Allow shorthand to delete all columns whose first len(key)
        # elements match key:
        if not isinstance(key, tuple):
            key = (key,)
        for col in self.columns:
            if isinstance(col, tuple) and col[: len(key)] == key:
                del self[col]
                deleted = True
    if not deleted:
        # If the above loop ran and didn't delete anything because
        # there was no match, this call should raise the appropriate
        # exception:
        loc = self.axes[-1].get_loc(key)
        self._mgr = self._mgr.idelete(loc)

def drop(
    self,
    labels: IndexLabel | ListLike = None,
    *,
    axis: Axis = 0,
    index: IndexLabel | ListLike = None,
    columns: IndexLabel | ListLike = None,
    level: Level | None = None,
    inplace: bool = False,
    errors: IgnoreRaise = "raise",
) -> Self | None:
    inplace = validate_bool_kwarg(inplace, "inplace")

    if labels is not None:
        if index is not None or columns is not None:
            raise ValueError("Cannot specify both 'labels' and 'index'/'columns'")
        axis_name = self._get_axis_name(axis)
        axes = {axis_name: labels}
    elif index is not None or columns is not None:
        if axis == 1:
            raise ValueError("Cannot specify both 'axis' and 'index'/'columns'")
        axes = {"index": index}
        if self.ndim == 2:
            axes["columns"] = columns
    else:
        raise ValueError(
            "Need to specify at least one of 'labels', 'index' or 'columns'"
        )

    obj = self

    for axis, labels in axes.items():
        if labels is not None:
            obj = obj._drop_axis(labels, axis, level=level, errors=errors)

    if inplace:
        self._update_inplace(obj)
        return None
    else:
        return obj

def sort_index(
    self,
    *,
    axis: Axis = 0,
    level: IndexLabel | None = None,
    ascending: bool | Sequence[bool] = True,
    inplace: bool = False,
    kind: SortKind = "quicksort",
    na_position: NaPosition = "last",
    sort_remaining: bool = True,
    ignore_index: bool = False,
    key: IndexKeyFunc | None = None,
) -> Self | None:
    inplace = validate_bool_kwarg(inplace, "inplace")
    axis = self._get_axis_number(axis)
    ascending = validate_ascending(ascending)

    target = self._get_axis(axis)

    indexer = get_indexer_indexer(
        target, level, ascending, kind, na_position, sort_remaining, key
    )

    if indexer is None:
        if inplace:
            result = self
        else:
            result = self.copy(deep=False)

        if ignore_index:
            if axis == 1:
                result.columns = default_index(len(self.columns))
            else:
                result.index = default_index(len(self))
        if inplace:
            return None
        else:
            return result

    baxis = self._get_block_manager_axis(axis)
    new_data = self._mgr.take(indexer, axis=baxis, verify=False)

    # reconstruct axis if needed
    if not ignore_index:
        new_axis = new_data.axes[baxis]._sort_levels_monotonic()
    else:
        new_axis = default_index(len(indexer))
    new_data.set_axis(baxis, new_axis)

    result = self._constructor_from_mgr(new_data, axes=new_data.axes)

    if inplace:
        return self._update_inplace(result)
    else:
        return result.__finalize__(self, method="sort_index")

def __setattr__(self, name: str, value) -> None:
    """
    After regular attribute access, try setting the name
    This allows simpler access to columns for interactive use.
    """
    # first try regular attribute access via __getattribute__, so that
    # e.g. ``obj.x`` and ``obj.x = 4`` will always reference/modify
    # the same attribute.

    try:
        object.__getattribute__(self, name)
        return object.__setattr__(self, name, value)
    except AttributeError:
        pass

    # if this fails, go on to more involved attribute setting
    # (note that this matches __getattr__, above).
    if name in self._internal_names_set:
        object.__setattr__(self, name, value)
    elif name in self._metadata:
        object.__setattr__(self, name, value)
    else:
        try:
            existing = getattr(self, name)
            if isinstance(existing, Index):
                object.__setattr__(self, name, value)
            elif name in self._info_axis:
                self[name] = value
            else:
                object.__setattr__(self, name, value)
        except (AttributeError, TypeError):
            if isinstance(self, ABCDataFrame) and (is_list_like(value)):
                warnings.warn(
                    "Pandas doesn't allow columns to be "
                    "created via a new attribute name - see "
                    "https://pandas.pydata.org/docs/dev/user_guide/"
                    "indexing.html#attribute-access",
                    stacklevel=find_stack_level(),
                )
            object.__setattr__(self, name, value)

def _is_mixed_type(self) -> bool:
    if self._mgr.is_single_block:
        # Includes all Series cases
        return False

    if self._mgr.any_extension_types:
        # Even if they have the same dtype, we can't consolidate them,
        #  so we pretend this is "mixed'"
        return True

    return self.dtypes.nunique() > 1

def _pad_or_backfill(
    self,
    method: Literal["ffill", "bfill", "pad", "backfill"],
    *,
    axis: Axis | None = None,
    inplace: bool = False,
    limit: int | None = None,
    limit_area: Literal["inside", "outside"] | None = None,
):
    if axis is None:
        axis = 0
    axis = self._get_axis_number(axis)
    method = clean_fill_method(method)

    if axis == 1:
        if not self._mgr.is_single_block and inplace:
            raise NotImplementedError
        # e.g. test_align_fill_method
        result = self.T._pad_or_backfill(
            method=method, limit=limit, limit_area=limit_area
        ).T

        return result

    new_mgr = self._mgr.pad_or_backfill(
        method=method,
        limit=limit,
        limit_area=limit_area,
        inplace=inplace,
    )
    result = self._constructor_from_mgr(new_mgr, axes=new_mgr.axes)
    if inplace:
        self._update_inplace(result)
        return self
    else:
        return result.__finalize__(self, method="fillna")

def _clip_with_scalar(self, lower, upper, inplace: bool = False):
    if (lower is not None and np.any(isna(lower))) or (
        upper is not None and np.any(isna(upper))
    ):
        raise ValueError("Cannot use an NA value as a clip threshold")

    result = self
    mask = self.isna()

    if lower is not None:
        cond = mask | (self >= lower)
        result = result.where(cond, lower, inplace=inplace)
    if upper is not None:
        cond = mask | (self <= upper)
        result = result.where(cond, upper, inplace=inplace)

    return result

def _clip_with_one_bound(self, threshold, method, axis, inplace):
    if axis is not None:
        axis = self._get_axis_number(axis)

    # method is self.le for upper bound and self.ge for lower bound
    if is_scalar(threshold) and is_number(threshold):
        if method.__name__ == "le":
            return self._clip_with_scalar(None, threshold, inplace=inplace)
        return self._clip_with_scalar(threshold, None, inplace=inplace)

    # GH #15390
    # In order for where method to work, the threshold must
    # be transformed to NDFrame from other array like structure.
    if (not isinstance(threshold, ABCSeries)) and is_list_like(threshold):
        if isinstance(self, ABCSeries):
            threshold = self._constructor(threshold, index=self.index)
        else:
            threshold = self._align_for_op(threshold, axis, flex=None)[1]

    # GH 40420
    # Treat missing thresholds as no bounds, not clipping the values
    if is_list_like(threshold):
        fill_value = np.inf if method.__name__ == "le" else -np.inf
        threshold_inf = threshold.fillna(fill_value)
    else:
        threshold_inf = threshold

    subset = method(threshold_inf, axis=axis) | isna(self)

    # GH 40420
    return self.where(subset, threshold, axis=axis, inplace=inplace)

def _align_frame(
    self,
    other: DataFrame,
    join: AlignJoin = "outer",
    axis: Axis | None = None,
    level=None,
    fill_value=None,
) -> tuple[Self, DataFrame, Index | None]:
    # defaults
    join_index, join_columns = None, None
    ilidx, iridx = None, None
    clidx, cridx = None, None

    is_series = isinstance(self, ABCSeries)

    if (axis is None or axis == 0) and not self.index.equals(other.index):
        join_index, ilidx, iridx = self.index.join(
            other.index, how=join, level=level, return_indexers=True
        )

    if (
        (axis is None or axis == 1)
        and not is_series
        and not self.columns.equals(other.columns)
    ):
        join_columns, clidx, cridx = self.columns.join(
            other.columns, how=join, level=level, return_indexers=True
        )

    if is_series:
        reindexers = {0: [join_index, ilidx]}
    else:
        reindexers = {0: [join_index, ilidx], 1: [join_columns, clidx]}

    left = self._reindex_with_indexers(
        reindexers, fill_value=fill_value, allow_dups=True
    )
    # other must be always DataFrame
    right = other._reindex_with_indexers(
        {0: [join_index, iridx], 1: [join_columns, cridx]},
        fill_value=fill_value,
        allow_dups=True,
    )
    return left, right, join_index

def _align_series(
    self,
    other: Series,
    join: AlignJoin = "outer",
    axis: Axis | None = None,
    level=None,
    fill_value=None,
) -> tuple[Self, Series, Index | None]:
    is_series = isinstance(self, ABCSeries)

    if (not is_series and axis is None) or axis not in [None, 0, 1]:
        raise ValueError("Must specify axis=0 or 1")

    if is_series and axis == 1:
        raise ValueError("cannot align series to a series other than axis 0")

    # series/series compat, other must always be a Series
    if not axis:
        # equal
        if self.index.equals(other.index):
            join_index, lidx, ridx = None, None, None
        else:
            join_index, lidx, ridx = self.index.join(
                other.index, how=join, level=level, return_indexers=True
            )

        if is_series:
            left = self._reindex_indexer(join_index, lidx)
        elif lidx is None or join_index is None:
            left = self.copy(deep=False)
        else:
            new_mgr = self._mgr.reindex_indexer(join_index, lidx, axis=1)
            left = self._constructor_from_mgr(new_mgr, axes=new_mgr.axes)

        right = other._reindex_indexer(join_index, ridx)

    else:
        # one has > 1 ndim
        fdata = self._mgr
        join_index = self.axes[1]
        lidx, ridx = None, None
        if not join_index.equals(other.index):
            join_index, lidx, ridx = join_index.join(
                other.index, how=join, level=level, return_indexers=True
            )

        if lidx is not None:
            bm_axis = self._get_block_manager_axis(1)
            fdata = fdata.reindex_indexer(join_index, lidx, axis=bm_axis)

        left = self._constructor_from_mgr(fdata, axes=fdata.axes)

        right = other._reindex_indexer(join_index, ridx)

    # fill
    fill_na = notna(fill_value)
    if fill_na:
        left = left.fillna(fill_value)
        right = right.fillna(fill_value)

    return left, right, join_index

def _shift_with_freq(self, periods: int, axis: int, freq) -> Self:
    # see shift.__doc__
    # when freq is given, index is shifted, data is not
    index = self._get_axis(axis)

    if freq == "infer":
        freq = getattr(index, "freq", None)

        if freq is None:
            freq = getattr(index, "_inferred_freq_str", None)

        if freq is None:
            msg = "Freq was not set in the index hence cannot be inferred"
            raise ValueError(msg)

    elif isinstance(freq, str):
        is_period = isinstance(index, PeriodIndex)
        freq = to_offset(freq, is_period=is_period)

    if isinstance(index, PeriodIndex):
        orig_freq = to_offset(index.freq)
        if freq != orig_freq:
            assert orig_freq is not None  # for mypy
            raise ValueError(
                f"Given freq {PeriodDtype(freq)._freqstr} "
                f"does not match PeriodIndex freq "
                f"{PeriodDtype(orig_freq)._freqstr}"
            )
        new_ax: Index = index.shift(periods)
    else:
        new_ax = index.shift(periods, freq)

    result = self.set_axis(new_ax, axis=axis)
    return result.__finalize__(self, method="shift")

def _logical_func(
    self,
    name: str,
    func,
    axis: Axis | None = 0,
    bool_only: bool = False,
    skipna: bool = True,
    **kwargs,
) -> Series | bool:
    nv.validate_logical_func((), kwargs, fname=name)
    validate_bool_kwarg(skipna, "skipna", none_allowed=False)

    if self.ndim > 1 and axis is None:
        # Reduce along one dimension then the other, to simplify DataFrame._reduce
        res = self._logical_func(
            name, func, axis=0, bool_only=bool_only, skipna=skipna, **kwargs
        )
        # error: Item "bool" of "Series | bool" has no attribute "_logical_func"
        return res._logical_func(  # type: ignore[union-attr]
            name, func, skipna=skipna, **kwargs
        )
    elif axis is None:
        axis = 0

    if (
        self.ndim > 1
        and axis == 1
        and len(self._mgr.blocks) > 1
        # TODO(EA2D): special-case not needed
        and all(block.values.ndim == 2 for block in self._mgr.blocks)
        and not kwargs
    ):
        # Fastpath avoiding potentially expensive transpose
        obj = self
        if bool_only:
            obj = self._get_bool_data()
        return obj._reduce_axis1(name, func, skipna=skipna)

    return self._reduce(
        func,
        name=name,
        axis=axis,
        skipna=skipna,
        numeric_only=bool_only,
        filter_type="bool",

def _accum_func(
    self,
    name: str,
    func,
    axis: Axis | None = None,
    skipna: bool = True,
    *args,
    **kwargs,
):
    skipna = nv.validate_cum_func_with_skipna(skipna, args, kwargs, name)
    if axis is None:
        axis = 0
    else:
        axis = self._get_axis_number(axis)

    if axis == 1:
        return self.T._accum_func(
            name,
            func,
            axis=0,
            skipna=skipna,
            *args,  # noqa: B026
            **kwargs,
        ).T

    def block_accum_func(blk_values):
        values = blk_values.T if hasattr(blk_values, "T") else blk_values

        result: np.ndarray | ExtensionArray
        if isinstance(values, ExtensionArray):
            result = values._accumulate(name, skipna=skipna, **kwargs)
        else:
            result = nanops.na_accum_func(values, func, skipna=skipna)

        result = result.T if hasattr(result, "T") else result
        return result

    result = self._mgr.apply(block_accum_func)

    return self._constructor_from_mgr(result, axes=result.axes).__finalize__(
        self, method=name

def set_numba_data(index: Index):
    numba_data = index._data
    if numba_data.dtype in (object, "string"):
        numba_data = np.asarray(numba_data)
        if not lib.is_string_array(numba_data):
            raise ValueError(
                "The numba engine only supports using string or numeric column names"
            )
        numba_data = numba_data.astype("U")
    try:
        index._numba_data = numba_data
        yield index
    finally:
        del index._numba_data

def copy(self, dtype=None, ndim: int = 1, layout=None) -> Self:
    assert ndim == 1
    if dtype is None:
        dtype = self.dtype
    layout = layout or self.layout
    return type(self)(dtype, layout, self.pyclass)

def copy(self, dtype=None, ndim: int = 1, layout: str = "C") -> Self:
    assert ndim == 1
    assert layout == "C"
    if dtype is None:
        dtype = self.dtype
    return type(self)(dtype, self.index, self.namety)

def make_looper(
    func: Callable,
    result_dtype: np.dtype,
    is_grouped_kernel: bool,
    nogil: bool,
    parallel: bool,
) -> Callable:
    if TYPE_CHECKING:
        import numba
    else:
        numba = import_optional_dependency("numba")

    if is_grouped_kernel:

        @numba.jit(nogil=nogil, parallel=parallel)
        def column_looper(  # pyright: ignore[reportRedeclaration]
            values: np.ndarray,
            labels: np.ndarray,
            ngroups: int,
            min_periods: int,
            *args: Any,
        ) -> tuple[np.ndarray, dict[int, np.ndarray]]:
            result = np.empty((values.shape[0], ngroups), dtype=result_dtype)
            na_positions = {}
            for i in numba.prange(values.shape[0]):  # type: ignore[no-untyped-call,attr-defined]
                output, na_pos = func(
                    values[i], result_dtype, labels, ngroups, min_periods, *args
                )
                result[i] = output
                if len(na_pos) > 0:
                    na_positions[i] = np.array(na_pos)
            return result, na_positions

    else:

        @numba.jit(nogil=nogil, parallel=parallel)
        def column_looper(
            values: np.ndarray,
            start: np.ndarray,
            end: np.ndarray,
            min_periods: int,
            *args: Any,
        ) -> tuple[np.ndarray, dict[int, np.ndarray]]:
            result = np.empty((values.shape[0], len(start)), dtype=result_dtype)
            na_positions = {}
            for i in numba.prange(values.shape[0]):  # type: ignore[no-untyped-call,attr-defined]
                output, na_pos = func(
                    values[i], result_dtype, start, end, min_periods, *args
                )
                result[i] = output
                if len(na_pos) > 0:
                    na_positions[i] = np.array(na_pos)
            return result, na_positions

    return column_looper

def remove_mean(
    val: float, nobs: int, sum_x: float, neg_ct: int, compensation: float
) -> tuple[int, float, int, float]:
    if not np.isnan(val):
        nobs -= 1
        y = -val - compensation
        t = sum_x + y
        compensation = t - sum_x - y
        sum_x = t
        if val < 0:
            neg_ct -= 1
    return nobs, sum_x, neg_ct, compensation

def bisect_left(a: list[Any], x: Any, lo: int = 0, hi: int = -1) -> int:
    """Same as https://docs.python.org/3/library/bisect.html; not in numba yet!"""
    if hi == -1:
        hi = len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def grouped_min_max(
    values: np.ndarray,
    result_dtype: np.dtype,
    labels: npt.NDArray[np.intp],
    ngroups: int,
    min_periods: int,
    is_max: bool,
    skipna: bool = True,
) -> tuple[np.ndarray, list[int]]:
    N = len(labels)
    nobs = np.zeros(ngroups, dtype=np.int64)
    na_pos = []
    output = np.empty(ngroups, dtype=result_dtype)

    for i in range(N):
        lab = labels[i]
        val = values[i]
        if lab < 0 or (not skipna and nobs[lab] >= 1 and np.isnan(output[lab])):
            continue

        if values.dtype.kind == "i" or not np.isnan(val):
            nobs[lab] += 1
        else:
            if not skipna:
                # If skipna is False and we encounter a NaN,
                # both min and max of the group will be NaN
                output[lab] = np.nan
            continue

        if nobs[lab] == 1:
            # First element in group, set output equal to this
            output[lab] = val
            continue

        if is_max:
            if val > output[lab]:
                output[lab] = val
        elif val < output[lab]:
            output[lab] = val

    # Set labels that don't satisfy min_periods as np.nan
    for lab, count in enumerate(nobs):
        if count < min_periods:
            na_pos.append(lab)

    return output, na_pos

def is_monotonic_increasing(bounds: np.ndarray) -> bool:
    """Check if int64 values are monotonically increasing."""
    n = len(bounds)
    if n < 2:
        return True
    prev = bounds[0]
    for i in range(1, n):
        cur = bounds[i]
        if cur < prev:
            return False
        prev = cur
    return True

def str_extractall(arr, pat, flags: int = 0) -> DataFrame:
    regex = re.compile(pat, flags=flags)
    # the regex must contain capture groups.
    if regex.groups == 0:
        raise ValueError("pattern contains no capture groups")

    if isinstance(arr, ABCIndex):
        arr = arr.to_series().reset_index(drop=True).astype(arr.dtype)

    columns = _get_group_names(regex)
    match_list = []
    index_list = []
    is_mi = arr.index.nlevels > 1

    for subject_key, subject in arr.items():
        if isinstance(subject, str):
            if not is_mi:
                subject_key = (subject_key,)

            for match_i, match_tuple in enumerate(regex.findall(subject)):
                if isinstance(match_tuple, str):
                    match_tuple = (match_tuple,)
                na_tuple = [np.nan if group == "" else group for group in match_tuple]
                match_list.append(na_tuple)
                result_key = (*subject_key, match_i)
                index_list.append(result_key)

    from pandas import MultiIndex

    index = MultiIndex.from_tuples(index_list, names=[*arr.index.names, "match"])
    dtype = _result_dtype(arr)

    result = arr._constructor_expanddim(
        match_list, index=index, columns=columns, dtype=dtype
    )
    return result

def _str_map(
    self,
    f,
    na_value=lib.no_default,
    dtype: NpDtype | None = None,
    convert: bool = True,
):
    """
    Map a callable over valid elements of the array.

    Parameters
    ----------
    f : Callable
        A function to call on each non-NA element.
    na_value : Scalar, optional
        The value to set for NA values. Might also be used for the
        fill value if the callable `f` raises an exception.
        This defaults to ``self.dtype.na_value`` which is ``np.nan``
        for object-dtype and Categorical and ``pd.NA`` for StringArray.
    dtype : Dtype, optional
        The dtype of the result array.
    convert : bool, default True
        Whether to call `maybe_convert_objects` on the resulting ndarray
    """
    if dtype is None:
        dtype = np.dtype("object")
    if na_value is lib.no_default:
        na_value = self.dtype.na_value  # type: ignore[attr-defined]

    if not len(self):
        return np.array([], dtype=dtype)

    arr = np.asarray(self, dtype=object)
    mask = isna(arr)
    map_convert = convert and not np.all(mask)
    try:
        result = lib.map_infer_mask(
            arr, f, mask.view(np.uint8), convert=map_convert
        )
    except (TypeError, AttributeError) as err:
        # Reraise the exception if callable `f` got wrong number of args.
        # The user may want to be warned by this, instead of getting NaN
        p_err = (
            r"((takes)|(missing)) (?(2)from \d+ to )?\d+ "
            r"(?(3)required )positional arguments?"
        )

        if len(err.args) >= 1 and re.search(p_err, err.args[0]):
            # NOTE: matches CPython's TypeError when a user-supplied
            # callable (e.g. `repl` in str.replace) is called with the
            # wrong number of positional arguments.
            raise err

        def g(x):
            # This type of fallback behavior can be removed once
            # we remove object-dtype .str accessor.
            try:
                return f(x)
            except (TypeError, AttributeError):
                return na_value

        return self._str_map(g, na_value=na_value, dtype=dtype)
    if not isinstance(result, np.ndarray):
        return result
    if na_value is not np.nan:
        np.putmask(result, mask, na_value)
        if convert and result.dtype == object:
            result = lib.maybe_convert_objects(result)
    return result

def _str_pad(
    self,
    width: int,
    side: Literal["left", "right", "both"] = "left",
    fillchar: str = " ",
):
    if side == "left":
        f = lambda x: x.rjust(width, fillchar)
    elif side == "right":
        f = lambda x: x.ljust(width, fillchar)
    elif side == "both":
        f = lambda x: x.center(width, fillchar)
    else:  # pragma: no cover
        raise ValueError("Invalid side")
    return self._str_map(f)

def _str_contains(
    self,
    pat,
    case: bool = True,
    flags: int = 0,
    na=lib.no_default,
    regex: bool = True,
):
    validate_na_arg(na, name="na")
    if regex:
        if not case:
            flags |= re.IGNORECASE

        pat = re.compile(pat, flags=flags)

        f = lambda x: pat.search(x) is not None
    elif case:
        f = lambda x: pat in x
    else:
        upper_pat = pat.upper()
        f = lambda x: upper_pat in x.upper()
    return self._str_map(f, na, dtype=np.dtype("bool"))

def _str_replace(
    self,
    pat: str | re.Pattern,
    repl: str | Callable,
    n: int = -1,
    case: bool = True,
    flags: int = 0,
    regex: bool = True,
):
    if case is False:
        # add case flag, if provided
        flags |= re.IGNORECASE

    if regex or flags or callable(repl):
        if not isinstance(pat, re.Pattern):
            if regex is False:
                pat = re.escape(pat)
            pat = re.compile(pat, flags=flags)

        n = n if n >= 0 else 0
        f = lambda x: pat.sub(repl=repl, string=x, count=n)
    else:
        f = lambda x: x.replace(pat, repl, n)

    return self._str_map(f, dtype=str)

def _str_repeat(self, repeats: int | Sequence[int]):
    if lib.is_integer(repeats):
        rint = cast("int", repeats)

        def scalar_rep(x):
            try:
                return bytes.__mul__(x, rint)
            except TypeError:
                return str.__mul__(x, rint)

        return self._str_map(scalar_rep, dtype=str)
    else:
        from pandas.core.arrays.string_ import BaseStringArray

        def rep(x, r):
            if x is libmissing.NA:
                return x
            try:
                return bytes.__mul__(x, r)
            except TypeError:
                return str.__mul__(x, r)

        result = libops.vec_binop(
            np.asarray(self),
            np.asarray(repeats, dtype=object),
            rep,
        )
        if not isinstance(self, BaseStringArray):
            return result
        # Not going through map, so we have to do this here.
        return type(self)._from_sequence(result, dtype=self.dtype)

def _str_match(
    self,
    pat: str | re.Pattern,
    case: bool = True,
    flags: int = 0,
    na: Scalar | lib.NoDefault = lib.no_default,
):
    if not case:
        flags |= re.IGNORECASE

    if isinstance(pat, re.Pattern):
        # pat already carries its own flags. IGNORECASE is the only one we
        #  can contribute (via `case`), so it is the only bit we compare,
        #  and only in the direction that would *add* it: a pat that is
        #  already case-insensitive, e.g. via an inline "(?i)", is honored
        #  as written. Comparing the full flag set would reject a pat
        #  compiled with e.g. re.MULTILINE (GH#63108).
        if flags & ~re.IGNORECASE:
            raise ValueError(
                "Cannot pass flags in addition to an already-compiled pat"
            )
        if flags & re.IGNORECASE and not pat.flags & re.IGNORECASE:
            raise ValueError("Cannot pass flags that do not match pat.flags")
        regex = pat
    else:
        regex = re.compile(pat, flags=flags)

    f = lambda x: regex.match(x) is not None
    return self._str_map(f, na_value=na, dtype=np.dtype(bool))

def _str_find_(self, sub, start, end, side):
    if side == "left":
        method = "find"
    elif side == "right":
        method = "rfind"
    else:  # pragma: no cover
        raise ValueError("Invalid side")

    if end is None:
        f = lambda x: getattr(x, method)(sub, start)
    else:
        f = lambda x: getattr(x, method)(sub, start, end)
    return self._str_map(f, dtype="int64")

def _str_split(
    self,
    pat: str | re.Pattern | None = None,
    n=-1,
    expand: bool = False,
    regex: bool | None = None,
):
    if pat is None:
        if n is None or n == 0:
            n = -1
        f = lambda x: x.split(pat, n)
    else:
        new_pat: str | re.Pattern
        if regex is True or isinstance(pat, re.Pattern):
            new_pat = re.compile(pat)
        elif regex is False:
            new_pat = pat
        # regex is None so link to old behavior #43563
        elif len(pat) == 1:
            new_pat = pat
        else:
            new_pat = re.compile(pat)

        if isinstance(new_pat, re.Pattern):
            if n is None or n == -1:
                n = 0
            f = lambda x: new_pat.split(x, maxsplit=n)
        else:
            if n is None or n == 0:
                n = -1
            f = lambda x: x.split(pat, n)
    return self._str_map(f, dtype=object)

def _str_rsplit(self, pat=None, n=-1):
    if pat is not None and not isinstance(pat, str):
        msg = f"expected a string object, not {type(pat).__name__}"
        raise TypeError(msg)
    if n is None or n == 0:
        n = -1
    f = lambda x: x.rsplit(pat, n)
    return self._str_map(f, dtype="object")

def _str_get_dummies(self, sep: str = "|", dtype: NpDtype | None = None):
    from pandas import Series

    if dtype is None:
        dtype = np.int64
    arr = Series(self).fillna("")
    try:
        arr = sep + arr + sep
    except (TypeError, NotImplementedError):
        arr = sep + arr.astype(str) + sep

    tags: set[str] = set()
    for ts in Series(arr, copy=False).str.split(sep):
        tags.update(ts)
    tags2 = sorted(tags - {""})

    _dtype = pandas_dtype(dtype)
    dummies_dtype: NpDtype
    if isinstance(_dtype, np.dtype):
        dummies_dtype = _dtype
    else:
        dummies_dtype = np.bool_
    dummies = np.empty((len(arr), len(tags2)), dtype=dummies_dtype, order="F")

    def _isin(test_elements: str, element: str) -> bool:
        return element in test_elements

    for i, t in enumerate(tags2):
        pat = sep + t + sep
        dummies[:, i] = lib.map_infer(
            arr.to_numpy(), functools.partial(_isin, element=pat)
        )
    return dummies, tags2

def _str_extract(self, pat: str | re.Pattern, flags: int = 0, expand: bool = True):
    regex = re.compile(pat, flags=flags)
    na_value = self.dtype.na_value  # type: ignore[attr-defined]

    if not expand:

        def g(x):
            m = regex.search(x)
            return m.groups()[0] if m else na_value

        return self._str_map(g, convert=False)

    empty_row = [na_value] * regex.groups

    def f(x):
        if not isinstance(x, str):
            return empty_row
        m = regex.search(x)
        if m:
            return [na_value if item is None else item for item in m.groups()]
        else:
            return empty_row

    return [f(val) for val in np.asarray(self)]

def nested_data_to_arrays(
    data: Sequence,
    columns: Index | None,
    index: Index | None,
    dtype: DtypeObj | None,
) -> tuple[list[ArrayLike], Index, Index]:
    """
    Convert a single sequence of arrays to multiple arrays.
    """
    # By the time we get here we have already checked treat_as_nested(data)

    if is_named_tuple(data[0]) and columns is None:
        columns = ensure_index(data[0]._fields)

    arrays, columns = to_arrays(data, columns, dtype=dtype)
    columns = ensure_index(columns)

    if index is None:
        if isinstance(data[0], ABCSeries):
            index = _get_names_from_index(data)
        else:
            index = default_index(len(data))

    return arrays, columns, index

def _prep_ndarraylike(values, copy: bool = True) -> np.ndarray:
    # values is specifically _not_ ndarray, EA, Index, or Series
    # We only get here with `not treat_as_nested(values)`

    if len(values) == 0:
        # TODO: check for length-zero range, in which case return int64 dtype?
        # TODO: reuse anything in try_cast?
        return np.empty((0, 0), dtype=object)
    elif isinstance(values, range):
        arr = range_to_ndarray(values)
        return arr[..., np.newaxis]

    def convert(v):
        if not is_list_like(v) or isinstance(v, ABCDataFrame):
            return v

        v = extract_array(v, extract_numpy=True)
        if isinstance(v, (list, tuple, range)):
            v = construct_1d_object_array_from_listlike(v)
        if isinstance(v, np.ndarray) and v.dtype == object:
            v = lib.maybe_convert_objects(v)
        # We don't do maybe_infer_objects here bc we will end up doing
        #  it column-by-column in ndarray_to_mgr
        return v

    # we could have a 1-dim or 2-dim list here
    # this is equiv of np.asarray, but does object conversion
    # and platform dtype preservation
    # does not convert e.g. [1, "a", True] to ["1", "a", "True"] like
    #  np.asarray would
    if is_list_like(values[0]):
        values = np.array([convert(v) for v in values])
    elif isinstance(values[0], np.ndarray) and values[0].ndim == 0:
        # GH#21861 see test_constructor_list_of_lists
        values = np.array([convert(v) for v in values])
    else:
        values = convert(values)

    return _ensure_2d(values)

def _ensure_2d(values: np.ndarray) -> np.ndarray:
    """
    Reshape 1D values, raise on anything else other than 2D.
    """
    if values.ndim == 1:
        values = values.reshape((values.shape[0], 1))
    elif values.ndim != 2:
        raise ValueError(f"Must pass 2-d input. shape={values.shape}")
    return values

def _homogenize(
    data, index: Index, dtype: DtypeObj | None
) -> tuple[list[ArrayLike], list[Any]]:
    oindex = None
    homogenized = []
    # if the original array-like in `data` is a Series, keep track of this Series' refs
    refs: list[Any] = []

    for val in data:
        if isinstance(val, (ABCSeries, Index)):
            if dtype is not None:
                val = val.astype(dtype)
            if isinstance(val, ABCSeries) and val.index._id is not index._id:
                # Forces alignment. No need to copy data since we
                # are putting it into an ndarray later
                val = val.reindex(index)
            refs.append(val._references)
            val = val._values
        else:
            if isinstance(val, dict):
                # GH#41785 this _should_ be equivalent to (but faster than)
                #  val = Series(val, index=index)._values
                if oindex is None:
                    oindex = index.astype("O")

                if isinstance(index, (DatetimeIndex, TimedeltaIndex)):
                    # see test_constructor_dict_datetime64_index
                    val = dict_compat(val)
                else:
                    # see test_constructor_subclass_dict
                    val = dict(val)

                if not isinstance(index, MultiIndex) and index.hasnans:
                    # GH#63889 Check if dict has missing value keys that need special
                    # handling (i.e. None/np.nan/pd.NA might no longer be matched
                    # when using fast_multiget with processed object index values)
                    from pandas import Series

                    val = Series(val).reindex(index)._values
                else:
                    # Fast path: use lib.fast_multiget for dicts without missing keys
                    val = lib.fast_multiget(val, oindex._values, default=np.nan)  # type: ignore[arg-type]

            val = sanitize_array(val, index, dtype=dtype, copy=False)
            com.require_length_match(val, index)
            refs.append(None)

        homogenized.append(val)

    return homogenized, refs

def _extract_index(data) -> Index:
    """
    Try to infer an Index from the passed data, raise ValueError on failure.
    """
    index: Index
    if len(data) == 0:
        return default_index(0)

    raw_lengths = set()
    indexes: list[list[Hashable] | Index] = []

    have_raw_arrays = False
    have_series = False
    have_dicts = False

    for val in data:
        if isinstance(val, ABCSeries):
            have_series = True
            indexes.append(val.index)
        elif isinstance(val, dict):
            have_dicts = True
            indexes.append(list(val.keys()))
        elif is_list_like(val) and getattr(val, "ndim", 1) == 1:
            have_raw_arrays = True
            raw_lengths.add(len(val))
        elif isinstance(val, np.ndarray) and val.ndim > 1:
            raise ValueError("Per-column arrays must each be 1-dimensional")

    if not indexes and not raw_lengths:
        raise ValueError("If using all scalar values, you must pass an index")

    if have_series:
        index, _ = union_indexes(indexes)
    elif have_dicts:
        index, _ = union_indexes(indexes, sort=False)

    if have_raw_arrays:
        if len(raw_lengths) > 1:
            raise ValueError("All arrays must be of the same length")

        if have_dicts:
            raise ValueError(
                "Mixing dicts with non-Series may lead to ambiguous ordering."
            )
        raw_length = raw_lengths.pop()
        if have_series:
            if raw_length != len(index):
                msg = (
                    f"array length {raw_length} does not match index "
                    f"length {len(index)}"
                )
                raise ValueError(msg)
        else:
            index = default_index(raw_length)

    return ensure_index(index)

def reorder_arrays(
    arrays: list[ArrayLike], arr_columns: Index, columns: Index | None, length: int
) -> tuple[list[ArrayLike], Index]:
    """
    Preemptively (cheaply) reindex arrays with new columns.
    """
    # reorder according to the columns
    if columns is not None:
        if not columns.equals(arr_columns):
            # if they are equal, there is nothing to do
            new_arrays: list[ArrayLike] = []
            indexer = arr_columns.get_indexer(columns)
            for i, k in enumerate(indexer):
                if k == -1:
                    # by convention default is all-NaN object dtype
                    arr = np.empty(length, dtype=object)
                    arr.fill(np.nan)
                else:
                    arr = arrays[k]
                new_arrays.append(arr)

            arrays = new_arrays
            arr_columns = columns

    return arrays, arr_columns

def _get_names_from_index(data) -> Index:
    has_some_name = any(getattr(s, "name", None) is not None for s in data)
    if not has_some_name:
        return default_index(len(data))

    index: list[Hashable] = list(range(len(data)))
    count = 0
    for i, s in enumerate(data):
        n = getattr(s, "name", None)
        if n is not None:
            index[i] = n
        else:
            index[i] = f"Unnamed {count}"
            count += 1

    return Index(index)

def _get_axes(
    N: int, K: int, index: Index | None, columns: Index | None
) -> tuple[Index, Index]:
    # helper to create the axes as indexes
    # return axes or defaults

    if index is None:
        index = default_index(N)
    else:
        index = ensure_index(index)

    if columns is None:
        columns = default_index(K)
    else:
        columns = ensure_index(columns)
    return index, columns

def _list_of_series_to_arrays(
    data: list,
    columns: Index | None,
) -> tuple[np.ndarray, Index]:
    # returned np.ndarray has ndim == 2

    if columns is None:
        # We know pass_data is non-empty because data[0] is a Series
        pass_data = [x for x in data if isinstance(x, (ABCSeries, ABCDataFrame))]
        columns, _ = get_objs_combined_axis(pass_data, sort=False)

    indexer_cache: dict[int, np.ndarray] = {}

    aligned_values = []
    for s in data:
        index = getattr(s, "index", None)
        if index is None:
            index = default_index(len(s))

        if id(index) in indexer_cache:
            indexer = indexer_cache[id(index)]
        else:
            indexer = indexer_cache[id(index)] = index.get_indexer(columns)

        values = extract_array(s, extract_numpy=True)
        aligned_values.append(algorithms.take_nd(values, indexer))

    content = np.vstack(aligned_values)
    return content, columns

def blockwise_all(
    left: BlockManager,
    right: BlockManager,
    op: Callable[[ArrayLike, ArrayLike], bool],
) -> bool:
    """
    Blockwise `all` reduction.
    """
    for info in _iter_block_pairs(left, right):
        res = op(info.lvals, info.rvals)
        if not res:
            return False
    return True

def _is_homogeneous_mgr(mgr: BlockManager, first_dtype: DtypeObj) -> bool:
    """
    Check if this Manager can be treated as a single ndarray.
    """
    if mgr.nblocks != 1:
        return False
    blk = mgr.blocks[0]
    if not (blk.mgr_locs.is_slice_like and blk.mgr_locs.as_slice.step == 1):
        return False

    return blk.dtype == first_dtype

def _get_block_for_concat_plan(
    mgr: BlockManager, bp: BlockPlacement, blkno: int, *, max_len: int
) -> Block:
    blk = mgr.blocks[blkno]
    # Assertions disabled for performance:
    #  assert bp.is_slice_like
    #  assert blkno != -1
    #  assert (mgr.blknos[bp] == blkno).all()

    if len(bp) == len(blk.mgr_locs) and (
        blk.mgr_locs.is_slice_like and blk.mgr_locs.as_slice.step == 1
    ):
        nb = blk
    else:
        ax0_blk_indexer = mgr.blklocs[bp.indexer]

        slc = lib.maybe_indices_to_slice(ax0_blk_indexer, max_len)
        # TODO: in all extant test cases 2023-04-08 we have a slice here.
        #  Will this always be the case?
        if isinstance(slc, slice):
            nb = blk.slice_block_columns(slc)
        else:
            nb = blk.take_block_columns(slc)

    # assert nb.shape == (len(bp), mgr.shape[1])
    return nb

def _dtype_to_na_value(dtype: DtypeObj, has_none_blocks: bool):
    """
    Find the NA value to go with this dtype.
    """
    if isinstance(dtype, ExtensionDtype):
        return dtype.na_value
    elif dtype.kind in "mM":
        return dtype.type("NaT", np.datetime_data(dtype)[0])
    elif dtype.kind in "fc":
        return dtype.type("NaN")
    elif dtype.kind == "b":
        # different from missing.na_value_for_dtype
        return None
    elif dtype.kind in "iu":
        if not has_none_blocks:
            # different from missing.na_value_for_dtype
            return None
        return np.nan
    elif dtype.kind == "O":
        return np.nan
    raise NotImplementedError

def _maybe_infer_ndim(
    values: ArrayLike, placement: BlockPlacement, ndim: int | None
) -> int:
    """
    If `ndim` is not provided, infer it from placement and values.
    """
    if ndim is None:
        # GH#38134 Block constructor now assumes ndim is not None
        if not isinstance(values.dtype, np.dtype):
            if len(placement) != 1:
                ndim = 1
            else:
                ndim = 2
        else:
            ndim = values.ndim
    return ndim

def extract_pandas_array(
    values: ArrayLike, dtype: DtypeObj | None, ndim: int | None
) -> tuple[ArrayLike, DtypeObj | None]:
    """
    Ensure that we don't allow NumpyExtensionArray / NumpyEADtype in internals.
    """
    # For now, blocks should be backed by ndarrays when possible.
    if isinstance(values, ABCNumpyExtensionArray):
        values = values.to_numpy()
        if ndim and ndim > 1:
            # TODO(EA2D): special case not needed with 2D EAs
            values = np.atleast_2d(values)

    if isinstance(dtype, NumpyEADtype):
        dtype = dtype.numpy_dtype

    return values, dtype

def extend_blocks(result, blocks=None) -> list[Block]:
    """return a new extended blocks, given the result"""
    if blocks is None:
        blocks = []
    if isinstance(result, list):
        for r in result:
            if isinstance(r, list):
                blocks.extend(r)
            else:
                blocks.append(r)
    else:
        assert isinstance(result, Block), type(result)
        blocks.append(result)
    return blocks

def make_block(
    self,
    values,
    placement: BlockPlacement | None = None,
    refs: BlockValuesRefs | None = None,
) -> Block:
    """
    Create a new block, with type inference propagate any values that are
    not specified
    """
    if placement is None:
        placement = self._mgr_locs
    if self.is_extension:
        values = ensure_block_shape(values, ndim=self.ndim)

    return new_block(values, placement=placement, ndim=self.ndim, refs=refs)

def __repr__(self) -> str:
    # don't want to print out all of the items here
    name = type(self).__name__
    if self.ndim == 1:
        result = f"{name}: {len(self)} dtype: {self.dtype}"
    else:
        shape = " x ".join([str(s) for s in self.shape])
        result = f"{name}: {self.mgr_locs.indexer}, {shape}, dtype: {self.dtype}"

    return result

def getitem_block_columns(
    self, slicer: slice, new_mgr_locs: BlockPlacement, ref_inplace_op: bool = False
) -> Self:
    """
    Perform __getitem__-like, return result as block.

    Only supports slices that preserve dimensionality.
    """
    new_values = self._slice(slicer)
    refs = self.refs if not ref_inplace_op or self.refs.has_reference() else None
    return type(self)(new_values, new_mgr_locs, self.ndim, refs=refs)

def reduce(self, func) -> Block:
    # We will apply the function and reshape the result into a single-row
    #  Block with the same mgr_locs; squeezing will be done at a higher level
    assert self.ndim == 2

    result = func(self.values)

    if self.values.ndim == 1:
        res_values = result
    else:
        res_values = result.reshape(-1, 1)

    return self.make_block(res_values)

def copy(self, *, deep: bool) -> Self:
    """copy constructor"""
    values = self.values
    refs: BlockValuesRefs | None
    if deep:
        if isinstance(values, np.ndarray):
            # "K" preserves memory layout; default "C" flips contiguity
            # for non-C-order blocks (GH#60469).
            values = values.copy(order="K")
        else:
            values = values.copy()
        refs = None
    else:
        values = values.view()
        refs = self.refs
    return type(self)(values, placement=self._mgr_locs, ndim=self.ndim, refs=refs)

def _get_refs_and_copy(self, inplace: bool):
    refs = None
    copy = not inplace
    if inplace:
        if self.refs.has_reference():
            copy = True
        else:
            refs = self.refs
    return copy, refs

def take_nd(
    self,
    indexer: npt.NDArray[np.intp],
    axis: AxisInt,
    new_mgr_locs: BlockPlacement | None = None,
    fill_value=lib.no_default,
) -> Block:
    """
    Take values according to indexer and return them as a block.
    """
    values = self.values

    if fill_value is lib.no_default:
        fill_value = self.fill_value
        allow_fill = False
    else:
        allow_fill = True

    # Note: algos.take_nd has upcast logic similar to coerce_to_target_dtype
    new_values = algos.take_nd(
        values, indexer, axis=axis, allow_fill=allow_fill, fill_value=fill_value
    )

    # Called from three places in managers, all of which satisfy
    #  these assertions
    if isinstance(self, ExtensionBlock):
        # NB: in this case, the 'axis' kwarg will be ignored in the
        #  algos.take_nd call above.
        assert not (self.ndim == 1 and new_mgr_locs is None)
    assert not (axis == 0 and new_mgr_locs is None)

    if new_mgr_locs is None:
        new_mgr_locs = self._mgr_locs

    if new_values.dtype != self.dtype:
        return self.make_block(new_values, new_mgr_locs)
    else:
        return self.make_block_same_class(new_values, new_mgr_locs)

def where(self, other, cond) -> list[Block]:
    arr = self.values.T

    cond = extract_bool_array(cond)

    orig_other = other
    orig_cond = cond
    other = self._maybe_squeeze_arg(other)
    cond = self._maybe_squeeze_arg(cond)

    if other is lib.no_default:
        other = self.fill_value

    icond, noop = validate_putmask(arr, ~cond)
    if noop:
        # GH#44181, GH#45135
        # Avoid a) raising for Interval/PeriodDtype and b) unnecessary object upcast
        return [self.copy(deep=False)]

    try:
        res_values = arr._where(cond, other).T
    except OutOfBoundsDatetime:
        raise
    except (ValueError, TypeError):
        if self.ndim == 1 or self.shape[0] == 1:
            if isinstance(self.dtype, (IntervalDtype, StringDtype)):
                # TestSetitemFloatIntervalWithIntIntervalValues
                blk = self.coerce_to_target_dtype(orig_other, raise_on_upcast=False)
                if (
                    self.ndim == 2
                    and isinstance(orig_cond, np.ndarray)
                    and orig_cond.ndim == 1
                    and not is_1d_only_ea_dtype(blk.dtype)
                ):
                    orig_cond = orig_cond[:, None]
                return blk.where(orig_other, orig_cond)

            elif isinstance(self, NDArrayBackedExtensionBlock):
                # NB: not (yet) the same as
                #  isinstance(values, NDArrayBackedExtensionArray)
                blk = self.coerce_to_target_dtype(orig_other, raise_on_upcast=False)
                return blk.where(orig_other, orig_cond)

            else:
                raise

        else:
            # Same pattern we use in Block.putmask
            is_array = isinstance(orig_other, (np.ndarray, ExtensionArray))

            res_blocks = []
            for i, nb in enumerate(self._split()):
                n = orig_other
                if is_array:
                    # we have a different value per-column
                    n = orig_other[:, i : i + 1]

                submask = orig_cond[:, i : i + 1]
                rbs = nb.where(n, submask)
                res_blocks.extend(rbs)
            return res_blocks

    nb = self.make_block_same_class(res_values)
    return [nb]

def delete(self, loc) -> list[Block]:
    # This will be unnecessary if/when __array_function__ is implemented
    if self.ndim == 1:
        values = self.values.delete(loc)
        mgr_locs = self._mgr_locs.delete(loc)
        return [type(self)(values, placement=mgr_locs, ndim=self.ndim)]
    elif self.values.ndim == 1:
        # We get here through to_stata
        return []
    return super().delete(loc)

def pad_or_backfill(
    self,
    *,
    method: FillnaOptions,
    inplace: bool = False,
    limit: int | None = None,
    limit_area: Literal["inside", "outside"] | None = None,
) -> list[Block]:
    values = self.values

    kwargs: dict[str, Any] = {"method": method, "limit": limit}
    if "limit_area" in inspect.signature(values._pad_or_backfill).parameters:
        kwargs["limit_area"] = limit_area
    elif limit_area is not None:
        raise NotImplementedError(
            f"{type(values).__name__} does not implement limit_area "
            "(added in pandas 2.2). 3rd-party ExtensionArray authors "
            "need to add this argument to _pad_or_backfill."
        )

    if values.ndim == 2:
        # NDArrayBackedExtensionArray.fillna assumes axis=0
        new_values = values.T._pad_or_backfill(**kwargs).T
    else:
        new_values = values._pad_or_backfill(**kwargs)
    return [self.make_block_same_class(new_values)]

def _unwrap_setitem_indexer(self, indexer):
    """
    Adapt a 2D-indexer to our 1D values.

    This is intended for 'setitem', not 'iget' or '_slice'.
    """
    # TODO: ATM this doesn't work for iget/_slice, can we change that?

    if isinstance(indexer, tuple) and len(indexer) == 2:
        # TODO(EA2D): not needed with 2D EAs
        #  Should never have length > 2.  Caller is responsible for checking.
        #  Length 1 is reached vis setitem_single_block and setitem_single_column
        #  each of which pass indexer=(pi,)
        if all(isinstance(x, np.ndarray) and x.ndim == 2 for x in indexer):
            # GH#44703 went through indexing.maybe_convert_ix
            first, second = indexer
            if not (
                second.size == 1 and (second == 0).all() and first.shape[1] == 1
            ):
                raise NotImplementedError(
                    "This should not be reached. Please report a bug at "
                    "github.com/pandas-dev/pandas/"
                )
            indexer = first[:, 0]

        elif lib.is_integer(indexer[1]) and indexer[1] == 0:
            # reached via setitem_single_block passing the whole indexer
            indexer = indexer[0]

        elif com.is_null_slice(indexer[1]):
            indexer = indexer[0]

        elif com.is_bool_indexer(indexer[1]) and len(indexer[1]) == 1:
            if indexer[1][0]:
                indexer = indexer[0]
            else:
                indexer = []

        elif is_list_like(indexer[1]) and indexer[1][0] == 0:
            indexer = indexer[0]

        else:
            raise NotImplementedError(
                "This should not be reached. Please report a bug at "
                "github.com/pandas-dev/pandas/"
            )
    return indexer

def ensure_np_dtype(dtype: DtypeObj) -> np.dtype:
    # TODO: https://github.com/pandas-dev/pandas/issues/22791
    # Give EAs some input on what happens here. Sparse needs this.
    if isinstance(dtype, SparseDtype):
        dtype = dtype.subtype
        dtype = cast("np.dtype", dtype)
    elif isinstance(dtype, ExtensionDtype):
        dtype = np.dtype("object")
    elif dtype == np.dtype(str):
        dtype = np.dtype("object")
    return dtype

def _form_blocks(arrays: list[ArrayLike], consolidate: bool, refs: list) -> list[Block]:
    tuples = enumerate(arrays)

    if not consolidate:
        return _tuples_to_blocks_no_consolidate(tuples, refs)

    # when consolidating, we can ignore refs (either stacking always copies,
    # or the EA is already copied in the calling dict_to_mgr)

    groups: dict[Hashable, list[tuple[int, ArrayLike]]] = {}
    for i, arr in tuples:
        dtype = arr.dtype
        # Extension dtypes each get their own block regardless, so use id()
        # to avoid a potentially expensive __hash__ (e.g. CategoricalDtype
        # hashes all categories).
        key = dtype if isinstance(dtype, np.dtype) else id(dtype)
        try:
            groups[key].append((i, arr))
        except KeyError:
            groups[key] = [(i, arr)]

    nbs: list[Block] = []
    for tup_block in groups.values():
        dtype = tup_block[0][1].dtype
        block_type = get_block_type(dtype)

        if isinstance(dtype, np.dtype):
            is_dtlike = dtype.kind in "mM"

            if issubclass(dtype.type, (str, bytes)):
                dtype = np.dtype(object)

            values, placement = _stack_arrays(tup_block, dtype)
            if is_dtlike:
                values = ensure_wrapped_if_datetimelike(values)
            blk = block_type(values, placement=BlockPlacement(placement), ndim=2)
            nbs.append(blk)

        elif is_1d_only_ea_dtype(dtype):
            dtype_blocks = [
                block_type(x[1], placement=BlockPlacement(x[0]), ndim=2)
                for x in tup_block
            ]
            nbs.extend(dtype_blocks)

        else:
            dtype_blocks = [
                block_type(
                    ensure_block_shape(x[1], 2), placement=BlockPlacement(x[0]), ndim=2
                )
                for x in tup_block
            ]
            nbs.extend(dtype_blocks)
    return nbs

def _preprocess_slice_or_indexer(
    slice_or_indexer: slice | np.ndarray, length: int, allow_fill: bool
):
    if isinstance(slice_or_indexer, slice):
        return (
            "slice",
            slice_or_indexer,
            libinternals.slice_len(slice_or_indexer, length),
        )
    else:
        if (
            not isinstance(slice_or_indexer, np.ndarray)
            or slice_or_indexer.dtype.kind != "i"
        ):
            dtype = getattr(slice_or_indexer, "dtype", None)
            raise TypeError(type(slice_or_indexer), dtype)

        indexer = ensure_platform_int(slice_or_indexer)
        if not allow_fill:
            indexer = maybe_convert_indices(indexer, length)
        return "fancy", indexer, len(indexer)

def make_na_array(dtype: DtypeObj, shape: Shape, fill_value) -> ArrayLike:
    if isinstance(dtype, DatetimeTZDtype):
        # NB: exclude e.g. pyarrow[dt64tz] dtypes
        ts = Timestamp(fill_value).as_unit(dtype.unit)
        i8values = np.full(shape, ts._value)
        dt64values = i8values.view(f"M8[{dtype.unit}]")
        return DatetimeArray._simple_new(dt64values, dtype=dtype)

    elif is_1d_only_ea_dtype(dtype):
        dtype = cast("ExtensionDtype", dtype)
        cls = dtype.construct_array_type()

        missing_arr = cls._from_sequence([], dtype=dtype)
        ncols, nrows = shape
        assert ncols == 1, ncols
        empty_arr = -1 * np.ones((nrows,), dtype=np.intp)
        return missing_arr.take(empty_arr, allow_fill=True, fill_value=fill_value)
    elif isinstance(dtype, ExtensionDtype):
        # TODO: no tests get here, a handful would if we disabled
        #  the dt64tz special-case above (which is faster)
        cls = dtype.construct_array_type()
        missing_arr = cls._empty(shape=shape, dtype=dtype)
        missing_arr[:] = fill_value
        return missing_arr
    else:
        # NB: we should never get here with dtype integer or bool;
        #  if we did, the missing_arr.fill would cast to gibberish
        missing_arr_np = np.empty(shape, dtype=dtype)
        missing_arr_np.fill(fill_value)

        if dtype.kind in "mM":
            missing_arr_np = ensure_wrapped_if_datetimelike(missing_arr_np)
        return missing_arr_np

def make_empty(self, axes=None) -> Self:
    """return an empty BlockManager with the items axis of len 0"""
    if axes is None:
        # TODO shallow copy remaining axis?
        axes = [default_index(0), *self.axes[1:]]

    # preserve dtype if possible
    if self.ndim == 1:
        assert isinstance(self, SingleBlockManager)  # for mypy
        blk = self.blocks[0]
        arr = blk.values[:0]
        bp = BlockPlacement(slice(0, 0))
        nb = blk.make_block_same_class(arr, placement=bp)
        blocks = [nb]
    else:
        blocks = []
    return type(self).from_blocks(blocks, axes)

def get_dtypes(self) -> npt.NDArray[np.object_]:
    cache = self._dtypes_cache
    if cache is None:
        blocks = self.blocks
        dtypes = np.array([blk.dtype for blk in blocks], dtype=object)
        cache = dtypes.take(self.blknos)
        # An invalidating write that landed while we computed has already
        # cleared the cache, so storing now would leave the stale array for good.
        if blocks is self.blocks:
            self._dtypes_cache = cache
    return cache.copy()

def __repr__(self) -> str:
    output = type(self).__name__
    for i, ax in enumerate(self.axes):
        if i == 0:
            output += f"\nItems: {ax}"
        else:
            output += f"\nAxis {i}: {ax}"

    for block in self.blocks:
        output += f"\n{block}"
    return output

def equals(self, other: object) -> bool:
    """
    Implementation for DataFrame.equals
    """
    if not isinstance(other, type(self)):
        return False

    self_axes, other_axes = self.axes, other.axes
    if len(self_axes) != len(other_axes):
        return False
    if not all(
        ax1.equals(ax2) for ax1, ax2 in zip(self_axes, other_axes, strict=True)
    ):
        return False

    return self._equal_values(other)

def setitem(self, indexer, value) -> Self:
    """
    Set values with indexer.

    For SingleBlockManager, this backs s[indexer] = value
    """
    if isinstance(indexer, np.ndarray) and indexer.ndim > self.ndim:
        raise ValueError(f"Cannot set values with ndim > {self.ndim}")

    if not self._has_no_reference(0):
        # this method is only called if there is a single block -> hardcoded 0
        # Split blocks to only copy the columns we want to modify
        if self.ndim == 2 and isinstance(indexer, tuple):
            blk_loc = self.blklocs[indexer[1]]
            if is_list_like(blk_loc) and blk_loc.ndim == 2:
                blk_loc = np.squeeze(blk_loc, axis=0)
            elif not is_list_like(blk_loc):
                # Keep dimension and copy data later
                blk_loc = [blk_loc]  # type: ignore[assignment]
            if len(blk_loc) == 0:
                return self.copy(deep=False)

            values = self.blocks[0].values
            if values.ndim == 2:
                # Block.delete in _iset_split_block requires sorted unique
                # locs; inverse maps the requested column order onto the
                # new block (GH#65446)
                blk_loc, inverse = np.unique(blk_loc, return_inverse=True)
                values = values[blk_loc]
                # "T" has no attribute "_iset_split_block"
                self._iset_split_block(  # type: ignore[attr-defined]
                    0, blk_loc, values
                )

                indexer = list(indexer)
                # first block equals values we are setting to -> set to all columns
                if lib.is_integer(indexer[1]):
                    col_indexer = 0
                elif len(inverse) > 1 and lib.is_range_indexer(
                    inverse, len(blk_loc)
                ):
                    col_indexer = slice(None)  # type: ignore[assignment]
                else:
                    col_indexer = inverse  # type: ignore[assignment]
                indexer[1] = col_indexer

                row_indexer = indexer[0]
                if isinstance(col_indexer, np.ndarray):
                    if (
                        isinstance(row_indexer, np.ndarray)
                        and row_indexer.ndim == 1
                    ):
                        # GH#65446: Make the row indexer 2d to take a cross product
                        row_indexer = row_indexer[:, None]
                elif isinstance(row_indexer, np.ndarray) and row_indexer.ndim == 2:
                    # numpy cannot handle a 2d indexer in combo with a slice
                    row_indexer = np.squeeze(row_indexer, axis=1)
                if isinstance(row_indexer, np.ndarray) and len(row_indexer) == 0:
                    # numpy does not like empty indexer combined with slice
                    # and we are setting nothing anyway
                    return self
                indexer[0] = row_indexer
                self.blocks[0].setitem(tuple(indexer), value)
                return self
        # No need to split if we either set all columns or on a single block
        # manager
        self = self.copy(deep=True)

    return self.apply("setitem", indexer=indexer, value=value)

def get_bool_data(self) -> Self:
    """
    Select blocks that are bool-dtype and columns from object-dtype blocks
    that are all-bool.
    """

    new_blocks = []

    for blk in self.blocks:
        if blk.dtype == bool:
            new_blocks.append(blk)

        elif blk.is_object:
            new_blocks.extend(nb for nb in blk._split() if nb.is_bool)

    return self._combine(new_blocks)

def get_numeric_data(self) -> Self:
    numeric_blocks = [blk for blk in self.blocks if blk.is_numeric]
    if len(numeric_blocks) == len(self.blocks):
        # Avoid somewhat expensive _combine
        # TODO(CoW) need to return a shallow copy here?
        return self
    return self._combine(numeric_blocks)

def _combine(self, blocks: list[Block], index: Index | None = None) -> Self:
    """return a new manager with the blocks"""
    if len(blocks) == 0:
        if self.ndim == 2:
            # retain our own Index dtype
            if index is not None:
                axes = [self.items[:0], index]
            else:
                axes = [self.items[:0], *self.axes[1:]]
            return self.make_empty(axes)
        return self.make_empty()

    indexer = np.sort(np.concatenate([b.mgr_locs.as_array for b in blocks]))
    inv_indexer = lib.get_reverse_indexer(indexer, self.shape[0])

    new_blocks: list[Block] = []
    for b in blocks:
        nb = b.copy(deep=False)
        nb.mgr_locs = BlockPlacement(inv_indexer[nb.mgr_locs.indexer])
        new_blocks.append(nb)

    axes = list(self.axes)
    # TODO shallow copy of axes?
    if index is not None:
        axes[-1] = index
    axes[0] = self.items.take(indexer)

    return type(self).from_blocks(new_blocks, axes)

def _make_na_block(
    self, placement: BlockPlacement, fill_value=None, use_na_proxy: bool = False
) -> Block:
    # Note: we only get here with self.ndim == 2

    if use_na_proxy:
        assert fill_value is None
        shape = (len(placement), self.shape[1])
        vals = np.empty(shape, dtype=np.void)
        nb = NumpyBlock(vals, placement, ndim=2)
        return nb

    if fill_value is None or fill_value is np.nan:
        fill_value = np.nan
        # GH45857 avoid unnecessary upcasting
        dtype = interleaved_dtype([blk.dtype for blk in self.blocks])
        if dtype is not None and np.issubdtype(dtype.type, np.floating):
            fill_value = dtype.type(fill_value)

    shape = (len(placement), self.shape[1])

    dtype, fill_value = infer_dtype_from_scalar(fill_value)
    block_values = make_na_array(dtype, shape, fill_value)
    return new_block_2d(block_values, placement=placement)

def __init__(
    self,
    blocks: Sequence[Block],
    axes: Sequence[Index],
    verify_integrity: bool = True,
) -> None:
    if verify_integrity:
        # Assertion disabled for performance
        # assert all(isinstance(x, Index) for x in axes)

        for block in blocks:
            if self.ndim != block.ndim:
                raise AssertionError(
                    f"Number of Block dimensions ({block.ndim}) must equal "
                    f"number of axes ({self.ndim})"
                )
            # As of 2.0, the caller is responsible for ensuring that
            #  DatetimeTZBlock with block.ndim == 2 has block.values.ndim ==2;
            #  previously there was a special check for fastparquet compat.

        self._verify_integrity()

def _verify_integrity(self) -> None:
    mgr_shape = self.shape
    tot_items = sum(len(x.mgr_locs) for x in self.blocks)
    for block in self.blocks:
        if block.shape[1:] != mgr_shape[1:]:
            raise_construction_error(tot_items, block.shape[1:], self.axes)
    if len(self.items) != tot_items:
        raise AssertionError(
            "Number of manager items must equal union of "
            f"block items\n# manager items: {len(self.items)}, # "
            f"tot_items: {tot_items}"

def __getstate__(self):
    block_values = [b.values for b in self.blocks]
    block_items = [self.items[b.mgr_locs.indexer] for b in self.blocks]
    axes_array = list(self.axes)

    extra_state = {
        "0.14.1": {
            "axes": axes_array,
            "blocks": [
                {"values": b.values, "mgr_locs": b.mgr_locs.indexer}
                for b in self.blocks
            ],
        }
    }

    # First three elements of the state are to maintain forward
    # compatibility with 0.13.1.
    return axes_array, block_values, block_items, extra_state

def __setstate__(self, state) -> None:
    def unpickle_block(values, mgr_locs, ndim: int) -> Block:
        # TODO(EA2D): ndim would be unnecessary with 2D EAs
        # older pickles may store e.g. DatetimeIndex instead of DatetimeArray
        values = extract_array(values, extract_numpy=True)
        if not isinstance(mgr_locs, BlockPlacement):
            mgr_locs = BlockPlacement(mgr_locs)

        values = maybe_coerce_values(values)
        return new_block(values, placement=mgr_locs, ndim=ndim)

    if isinstance(state, tuple) and len(state) >= 4 and "0.14.1" in state[3]:
        state = state[3]["0.14.1"]
        self.axes = [ensure_index(ax) for ax in state["axes"]]
        ndim = len(self.axes)
        self.blocks = tuple(
            unpickle_block(b["values"], b["mgr_locs"], ndim=ndim)
            for b in state["blocks"]
        )
    else:
        raise NotImplementedError("pre-0.14.1 pickles are no longer supported")

    self._post_setstate()

def get_rows_with_mask(self, indexer: npt.NDArray[np.bool_]) -> Self:
    # similar to get_slice, but not restricted to slice indexer
    blk = self._block
    if len(indexer) > 0 and indexer.all():
        return type(self)(blk.copy(deep=False), self.index)
    array = blk.values[indexer]

    if isinstance(indexer, np.ndarray) and indexer.dtype.kind == "b":
        # boolean indexing always gives a copy with numpy
        refs = None
    else:
        # TODO(CoW) in theory only need to track reference if new_array is a view
        refs = blk.refs

    bp = BlockPlacement(slice(0, len(array)))
    block = type(blk)(array, placement=bp, ndim=1, refs=refs)

    new_idx = self.index[indexer]
    return type(self)(block, new_idx)

def get_slice(
    self, slobj: slice, axis: AxisInt = 0, new_index: Index | None = None
) -> SingleBlockManager:
    # Assertion disabled for performance
    # assert isinstance(slobj, slice), type(slobj)
    if axis >= self.ndim:
        raise IndexError("Requested axis not found in manager")

    blk = self._block
    array = blk.values[slobj]
    bp = BlockPlacement(slice(0, len(array)))
    # TODO this method is only used in groupby SeriesSplitter at the moment,
    # so passing refs is not yet covered by the tests
    block = type(blk)(array, placement=bp, ndim=1, refs=blk.refs)
    if new_index is None:
        new_index = self.index._getitem_slice(slobj)
    return type(self)(block, new_index)

def _filter_nodes(superclass, all_nodes=_all_nodes):
    """
    Filter out AST nodes that are subclasses of ``superclass``.
    """
    node_names = (node.__name__ for node in all_nodes if issubclass(node, superclass))
    return frozenset(node_names)

def visit(self, node, **kwargs):
    if isinstance(node, str):
        clean = self.preparser(node)
        try:
            node = ast.fix_missing_locations(ast.parse(clean))
        except SyntaxError as e:
            if any(iskeyword(x) for x in clean.split()):
                e.msg = "Python keyword not valid identifier in numexpr query"
            raise e

    method = f"visit_{type(node).__name__}"
    visitor = getattr(self, method)
    return visitor(node, **kwargs)

def _maybe_transform_eq_ne(self, node, left=None, right=None):
    if left is None:
        left = self.visit(node.left, side="left")
    if right is None:
        right = self.visit(node.right, side="right")
    op, op_class, left, right = self._rewrite_membership_op(node, left, right)
    return op, op_class, left, right

def _maybe_evaluate_binop(
    self,
    op,
    op_class,
    lhs,
    rhs,
    eval_in_python=("in", "not in"),
    maybe_eval_in_python=("==", "!=", "<", ">", "<=", ">="),
):
    res = op(lhs, rhs)

    if res.has_invalid_return_type:
        raise TypeError(
            f"unsupported operand type(s) for {res.op}: "
            f"'{lhs.type}' and '{rhs.type}'"
        )

    if self.engine != "pytables" and (
        (res.op in CMP_OPS_SYMS and getattr(lhs, "is_datetime", False))
        or getattr(rhs, "is_datetime", False)
    ):
        # all date ops must be done in python bc numexpr doesn't work
        # well with NaT
        return self._maybe_eval(res, self.binary_ops)

    if res.op in eval_in_python:
        # "in"/"not in" ops are always evaluated in python
        return self._maybe_eval(res, eval_in_python)
    elif self.engine != "pytables":
        if (
            getattr(lhs, "return_type", None) == object
            or is_string_dtype(getattr(lhs, "return_type", None))
            or getattr(rhs, "return_type", None) == object
            or is_string_dtype(getattr(rhs, "return_type", None))
        ):
            # evaluate "==" and "!=" in python if either of our operands
            # has an object or string return type
            return self._maybe_eval(res, eval_in_python + maybe_eval_in_python)
    return res

def visit_Subscript(self, node, **kwargs) -> Term:
    from pandas import eval as pd_eval

    value = self.visit(node.value)
    if isinstance(node.slice, ast.Tuple):
        # visit_Tuple builds a list, which __getitem__ reads as a single
        #  axis-0 selector rather than a multi-axis key (GH#49905)
        raise NotImplementedError("multi-dimensional subscripts are not supported")
    slobj = self.visit(node.slice)
    if isinstance(slobj, slice):
        # visit_Slice returns a bare slice; re-parsing it would stringify it into
        # a slice(...) call, which is not a supported function (GH#49905)
        result = slobj
    elif is_term(slobj):
        # already resolved; re-parsing pushes it back through numexpr
        result = slobj.value
    else:
        # an Op still needs the engine, which aligns Series operands
        result = pd_eval(
            slobj, local_dict=self.env, engine=self.engine, parser=self.parser
        )
    try:
        # a Term instance
        v = value.value[result]
    except AttributeError:
        # an Op instance
        lhs = pd_eval(
            value, local_dict=self.env, engine=self.engine, parser=self.parser
        )
        v = lhs[result]
    name = self.env.add_tmp(v)
    return self.term_type(name, env=self.env)

def visit_Slice(self, node, **kwargs) -> slice:
    """df.index[slice(4,6)]"""
    lower = node.lower
    if lower is not None:
        lower = self.visit(lower)(self.env)
    upper = node.upper
    if upper is not None:
        upper = self.visit(upper)(self.env)
    step = node.step
    if step is not None:
        step = self.visit(step)(self.env)

    return slice(lower, upper, step)

def visit_Assign(self, node, **kwargs):
    """
    support a single assignment node, like

    c = a + b

    set the assigner at the top level, must be a Name node which
    might or might not exist in the resolvers

    """
    if len(node.targets) != 1:
        raise SyntaxError("can only assign a single expression")
    if not isinstance(node.targets[0], ast.Name):
        raise SyntaxError("left hand side of an assignment must be a single name")
    if self.env.target is None:
        raise ValueError("cannot assign without a target object")

    try:
        assigner = self.visit(node.targets[0], **kwargs)
    except UndefinedVariableError:
        assigner = node.targets[0].id

    self.assigner = getattr(assigner, "name", assigner)
    if self.assigner is None:
        raise SyntaxError(
            "left hand side of an assignment must be a single resolvable name"
        )

    return self.visit(node.value, **kwargs)

def visit_Attribute(self, node, **kwargs):
    attr = node.attr
    value = node.value

    ctx = node.ctx
    if isinstance(ctx, ast.Load):
        # resolve the value
        visited_value = self.visit(value)
        if hasattr(visited_value, "value"):
            resolved = visited_value.value
        else:
            resolved = visited_value(self.env)
        try:
            v = getattr(resolved, attr)
            name = self.env.add_tmp(v)
            return self.term_type(name, self.env)
        except AttributeError:
            # something like datetime.datetime where scope is overridden
            if isinstance(value, ast.Name) and value.id == attr:
                return resolved
            raise

    raise ValueError(f"Invalid Attribute context {type(ctx).__name__}")

def visit_Call(self, node, side=None, **kwargs):
    if isinstance(node.func, ast.Attribute) and node.func.attr != "__call__":
        res = self.visit_Attribute(node.func)
    elif not isinstance(node.func, ast.Name):
        raise TypeError("Only named functions are supported")
    else:
        try:
            res = self.visit(node.func)
        except UndefinedVariableError:
            # Check if this is a supported function name
            try:
                res = FuncNode(node.func.id)
            except ValueError:
                # Raise original error
                raise

    if res is None:
        # error: "expr" has no attribute "id"
        raise ValueError(
            f"Invalid function call {node.func.id}"  # type: ignore[union-attr]
        )
    if hasattr(res, "value"):
        res = res.value

    if isinstance(res, FuncNode):
        new_args = [self.visit(arg) for arg in node.args]

        if node.keywords:
            raise TypeError(
                f'Function "{res.name}" does not support keyword arguments'
            )

        return res(*new_args)

    else:
        new_args = [self.visit(arg)(self.env) for arg in node.args]

        for key in node.keywords:
            if not isinstance(key, ast.keyword):
                # error: Item "Attribute" of "Attribute | Name" has no
                # attribute "id"
                raise ValueError(
                    f"keyword error in function call '{node.func.id}'"  # type: ignore[union-attr]
                )

            if key.arg:
                kwargs[key.arg] = self.visit(key.value)(self.env)

        name = self.env.add_tmp(res(*new_args, **kwargs))
        return self.term_type(name=name, env=self.env)

def visit_Compare(self, node, **kwargs):
    ops = node.ops
    comps = node.comparators

    # base case: we have something like a CMP b
    if len(comps) == 1:
        op = self.translate_In(ops[0])
        # GH#65357: Unroll `in` / `not in` into row-wise comparisons (== / !=)
        # if the RHS tuple contains variables. This prevents passing Series
        # objects to isin(), which strictly expects scalar iterables.
        if isinstance(ops[0], (ast.In, ast.NotIn)) and isinstance(
            comps[0], (ast.Tuple, ast.List)
        ):
            elts = comps[0].elts
            if any(isinstance(e, ast.Name) for e in elts):
                cmp_op = ast.Eq() if isinstance(ops[0], ast.In) else ast.NotEq()
                bool_op = ast.Or() if isinstance(ops[0], ast.In) else ast.And()
                new_values: list[ast.expr] = [
                    ast.Compare(left=node.left, ops=[cmp_op], comparators=[elt])
                    for elt in elts
                ]
                return self.visit(ast.BoolOp(op=bool_op, values=new_values))

        binop = ast.BinOp(op=op, left=node.left, right=comps[0])
        return self.visit(binop)

    # recursive case: we have a chained comparison, a CMP b CMP c, etc.
    left = node.left
    values = []
    for op, comp in zip(ops, comps, strict=True):
        new_node = self.visit(
            ast.Compare(comparators=[comp], left=left, ops=[self.translate_In(op)])
        )
        left = comp
        values.append(new_node)
    return self.visit(ast.BoolOp(op=ast.And(), values=values))

def names(self):
    """
    Get the names in an expression.
    """
    if is_term(self.terms):
        return frozenset([self.terms.name])
    return frozenset(term.name for term in com.flatten(self.terms))

def set_use_numexpr(v: bool = True) -> None:
    # set/unset to use numexpr
    global USE_NUMEXPR
    if NUMEXPR_INSTALLED:
        USE_NUMEXPR = v

    # choose what we are going to do
    global _evaluate, _where

    if USE_NUMEXPR:
        _evaluate = _evaluate_numexpr
        _where = _where_numexpr
    elif v and NUMEXPR_BLOCKED_VERSION is not None:
        _evaluate = _evaluate_blocked
        _where = _where_blocked
    else:
        _evaluate = _evaluate_standard
        _where = _where_standard

def set_numexpr_threads(n=None) -> None:
    # if we are using numexpr, set the threads to n
    # otherwise reset
    if NUMEXPR_INSTALLED and USE_NUMEXPR:
        if n is None:
            n = ne.detect_number_of_cores()
        ne.set_num_threads(n)

def _can_use_numexpr(op, op_str, left_op, right_op, dtype_check) -> bool:
    """return left_op boolean if we WILL be using numexpr"""
    if op_str is not None:
        # required min elements (otherwise we are adding overhead)
        if left_op.size > _MIN_ELEMENTS:
            # check for dtype compatibility
            dtypes: set[str] = set()
            for o in [left_op, right_op]:
                # ndarray and Series Case
                if hasattr(o, "dtype"):
                    dtypes |= {o.dtype.name}

            # allowed are a superset
            if not len(dtypes) or _ALLOWED_DTYPES[dtype_check] >= dtypes:
                return True

    return False

def _evaluate_numexpr(op, op_str, left_op, right_op):
    result = None

    if _can_use_numexpr(op, op_str, left_op, right_op, "evaluate"):
        is_reversed = op.__name__.strip("_").startswith("r")
        if is_reversed:
            # we were originally called by a reversed op method
            left_op, right_op = right_op, left_op

        left_value = left_op
        right_value = right_op

        try:
            result = ne.evaluate(
                f"left_value {op_str} right_value",
                local_dict={"left_value": left_value, "right_value": right_value},
                casting="safe",
            )
            result = normalize_numexpr_result(result)
        except TypeError:
            # numexpr raises eg for array ** array with integers
            # (https://github.com/pydata/numexpr/issues/379)
            pass
        except NotImplementedError:
            if _bool_arith_fallback(op_str, left_op, right_op):
                pass
            else:
                raise

        if is_reversed:
            # reverse order to original for fallback
            left_op, right_op = right_op, left_op

    if _TEST_MODE:
        _store_test_result(result is not None)

    if result is None:
        result = _evaluate_standard(op, op_str, left_op, right_op)

    return result

def _where_numexpr(cond, left_op, right_op):
    # Caller is responsible for extracting ndarray if necessary
    result = None

    if _can_use_numexpr(None, "where", left_op, right_op, "where"):
        result = ne.evaluate(
            "where(cond_value, a_value, b_value)",
            local_dict={"cond_value": cond, "a_value": left_op, "b_value": right_op},
            casting="safe",
        )
        result = normalize_numexpr_result(result)

    if result is None:
        result = _where_standard(cond, left_op, right_op)

    return result

def where(cond, left_op, right_op, use_numexpr: bool = True):
    """
    Evaluate the where condition cond on left_op and right_op.

    Parameters
    ----------
    cond : np.ndarray[bool]
    left_op : return if cond is True
    right_op : return if cond is False
    use_numexpr : bool, default True
        Whether to try to use numexpr.
    """
    assert _where is not None
    if use_numexpr:
        return _where(cond, left_op, right_op)
    else:
        return _where_standard(cond, left_op, right_op)

def __setitem__(self, key: _KT, value: _VT) -> None:
    for mapping in self.maps:
        if key in mapping:
            mapping[key] = value
            return
    self.maps[0][key] = value

def _in(x, y):
    """
    Compute the vectorized membership of ``x in y`` if possible, otherwise
    use Python.
    """
    try:
        return x.isin(y)
    except AttributeError:
        if is_list_like(x):
            try:
                return y.isin(x)
            except AttributeError:
                pass
        return x in y

def _not_in(x, y):
    """
    Compute the vectorized membership of ``x not in y`` if possible,
    otherwise use Python.
    """
    try:
        return ~x.isin(y)
    except AttributeError:
        if is_list_like(x):
            try:
                return ~y.isin(x)
            except AttributeError:
                pass
        return x not in y

def _resolve_name(self):
    local_name = str(self.local_name)
    is_local = self.is_local
    if (
        not str(self.name).startswith(LOCAL_TAG)
        and local_name in self.env.scope
        and isinstance(self.env.scope[local_name], type)
    ):
        is_local = False

    res = self.env.resolve(local_name, is_local=is_local)
    self.update(res)

    if hasattr(res, "ndim") and isinstance(res.ndim, int) and res.ndim > 2:
        raise NotImplementedError(
            "N-dimensional objects, where N > 2, are not supported with eval"
        )
    return res

def type(self):
    try:
        # GH#35247 avoid .values which boxes PeriodArray/IntervalArray
        dtype = self._value.dtype
    except AttributeError:
        try:
            return self._value.values.dtype  # DataFrame
        except AttributeError:
            return type(self._value)  # scalar

    # Match .values.dtype behavior for types that external_values boxes
    if isinstance(dtype, (PeriodDtype, IntervalDtype)):
        return np.dtype("object")
    return dtype

def convert_values(self) -> None:
    """
    Convert datetimes to a comparable value in an expression.
    """

    def stringify(value):
        encoder: Callable[[object], str | bytes]
        if self.encoding is not None:
            encoder = partial(pprint_thing_encoded, encoding=self.encoding)
        else:
            encoder = pprint_thing
        return encoder(value)

    lhs, rhs = self.lhs, self.rhs

    if is_term(lhs) and lhs.is_datetime and is_term(rhs) and rhs.is_scalar:
        v = rhs.value
        if isinstance(v, (int, float)):
            v = stringify(v)
        v = Timestamp(ensure_decoded(v))
        if v.tz is not None:
            v = v.tz_convert("UTC")
        self.rhs.update(v)

    if is_term(rhs) and rhs.is_datetime and is_term(lhs) and lhs.is_scalar:
        v = lhs.value
        if isinstance(v, (int, float)):
            v = stringify(v)
        v = Timestamp(ensure_decoded(v))
        if v.tz is not None:
            v = v.tz_convert("UTC")
        self.lhs.update(v)

def return_type(self) -> np.dtype:
    operand = self.operand
    if operand.return_type == np.dtype("bool"):
        return np.dtype("bool")
    if isinstance(operand, Op) and (
        operand.op in _cmp_ops_dict or operand.op in _bool_ops_dict
    ):
        return np.dtype("bool")
    return np.dtype("int")

def maybe_expression(s) -> bool:
    """loose checking if s is a pytables-acceptable expression"""
    if not isinstance(s, str):
        return False
    operations = PyTablesExprVisitor.binary_ops + PyTablesExprVisitor.unary_ops + ("=",)

    # make sure we have an op at least
    return any(op in s for op in operations)

def _resolve_name(self):
    # must be a queryables
    if self.side == "left":
        # Note: The behavior of __new__ ensures that self.name is a str here
        if self.name not in self.env.queryables:
            raise NameError(f"name {self.name!r} is not defined")
        return self.name

    # resolve the rhs (and allow it to be None)
    try:
        return self.env.resolve(self.name, is_local=False)
    except UndefinedVariableError:
        return self.name

def prune(self, klass):
    if self.op in ARITH_OPS_SYMS:
        # GH#41100: arithmetic in a where-clause is not supported. PyTables
        # support is in maintenance mode, so rather than grow the query
        # grammar we raise with a pointer to a working alternative.
        raise NotImplementedError(
            "arithmetic operations are not supported inside an HDFStore "
            "'where' filter; instead store a precomputed column as a "
            "data_column and query that, or read the data and apply the "
            "filter in pandas (e.g. df[df['A'] % 3 == 0])."
        )

    def pr(left, right):
        """create and return a new specialized BinOp from myself"""
        if left is None:
            return right
        elif right is None:
            return left

        k = klass
        if isinstance(left, ConditionBinOp):
            if isinstance(right, ConditionBinOp):
                k = JointConditionBinOp
            elif isinstance(left, k):
                return left
            elif isinstance(right, k):
                return right

        elif isinstance(left, FilterBinOp):
            if isinstance(right, FilterBinOp):
                k = JointFilterBinOp
            elif isinstance(left, k):
                return left
            elif isinstance(right, k):
                return right

        return k(
            self.op, left, right, queryables=self.queryables, encoding=self.encoding
        ).evaluate()

    left, right = self.lhs, self.rhs

    if is_term(left) and is_term(right):
        res = pr(left, right)
    elif not is_term(left) and is_term(right):
        res = pr(left.prune(klass), right)
    elif is_term(left) and not is_term(right):
        res = pr(left, right.prune(klass))
    elif not (is_term(left) or is_term(right)):
        res = pr(left.prune(klass), right.prune(klass))

    return res

def conform(self, rhs):
    """inplace conform rhs"""
    rhs = rhs.value
    if rhs is None:
        # Guarded here rather than in convert_value so both query paths are
        #  covered; bool(None) is False, Timestamp(None) is NaT. GH#64348
        raise TypeError(f"Cannot compare [{self.lhs.value}] to None")
    if not is_list_like(rhs):
        rhs = [rhs]
    if isinstance(rhs, np.ndarray):
        rhs = rhs.ravel()
    return rhs

def evaluate(self) -> Self | None:  # type: ignore[override]
    if not self.is_valid:
        raise ValueError(f"query term is not valid [{self}]")

    rhs = self.conform(self.rhs)
    values = list(rhs)

    if self.op not in ["==", "!="]:
        if not self.is_in_table:
            raise TypeError(
                f"passing a filterable condition to a non-table indexer [{self}]"
            )
        return None

    if self.is_in_table and len(values) <= self._max_selectors:
        return None
    filter_op = self.generate_filter_op()
    self.filter = (self.lhs.value, filter_op, Index(values))
    return self

def generate_filter_op(self, invert: bool = False):
    if (self.op == "!=" and not invert) or (self.op == "==" and invert):
        return lambda axis, vals: ~axis.isin(vals)
    else:
        return lambda axis, vals: axis.isin(vals)

def prune(self, klass):
    if self.op != "~":
        raise NotImplementedError("UnaryOp only support invert type ops")

    operand = self.operand
    operand = operand.prune(klass)

    if operand is not None and (
        (issubclass(klass, ConditionBinOp) and operand.condition is not None)
        or (
            not issubclass(klass, ConditionBinOp)
            and issubclass(klass, FilterBinOp)
            and operand.filter is not None
        )
    ):
        return operand.invert()
    return None

def visit_UnaryOp(self, node, **kwargs) -> ops.Term | UnaryOp | None:
    if isinstance(node.op, (ast.Not, ast.Invert)):
        return UnaryOp("~", self.visit(node.operand))
    elif isinstance(node.op, ast.USub):
        return self.const_type(-self.visit(node.operand).value, self.env)
    elif isinstance(node.op, ast.UAdd):
        raise NotImplementedError("Unary addition not supported")
    # TODO: return None might never be reached
    return None

def visit_Subscript(self, node, **kwargs) -> ops.Term:
    # only allow simple subscripts

    value = self.visit(node.value)
    slobj = self.visit(node.slice)
    try:
        value = value.value
    except AttributeError:
        pass

    if isinstance(slobj, Term):
        # In py39 np.ndarray lookups with Term containing int raise
        slobj = slobj.value

    try:
        return self.const_type(value[slobj], self.env)
    except TypeError as err:
        raise ValueError(f"cannot subscript {value!r} with {slobj!r}") from err

def visit_Attribute(self, node, **kwargs):
    attr = node.attr
    value = node.value

    ctx = type(node.ctx)
    if ctx == ast.Load:
        # resolve the value
        resolved = self.visit(value)

        # try to get the value to see if we are another expression
        try:
            resolved = resolved.value
        except AttributeError:
            pass

        try:
            return self.term_type(getattr(resolved, attr), self.env)
        except AttributeError:
            # something like datetime.datetime where scope is overridden
            if isinstance(value, ast.Name) and value.id == attr:
                return resolved

    raise ValueError(f"Invalid Attribute context {ctx.__name__}")

def evaluate(self):
    """create and return the numexpr condition and filter"""
    try:
        self.condition = self.terms.prune(ConditionBinOp)
    except AttributeError as err:
        raise ValueError(
            f"cannot process expression [{self.expr}], [{self}] "
            "is not a valid condition"
        ) from err
    try:
        self.filter = self.terms.prune(FilterBinOp)
    except AttributeError as err:
        raise ValueError(
            f"cannot process expression [{self.expr}], [{self}] "
            "is not a valid filter"
        ) from err

    return self.condition, self.filter

def tostring(self, encoding) -> str:
    """quote the string if not encoded else encode and return"""
    if self.kind == "string":
        if encoding is not None:
            return str(self.converted)
        return f'"{self.converted}"'
    elif self.kind == "float":
        return repr(self.converted)
    return str(self.converted)

def _align_core_single_unary_op(
    term,
) -> tuple[partial[np.ndarray] | type[NDFrame], dict[str, Index] | None]:
    typ: partial[np.ndarray] | type[NDFrame]
    axes: dict[str, Index] | None = None

    if isinstance(term.value, np.ndarray):
        typ = partial(np.asanyarray, dtype=term.value.dtype)
    else:
        typ = type(term.value)
        if hasattr(term.value, "axes"):
            axes = _zip_axes_from_type(typ, term.value.axes)

    return typ, axes

def result_type_many(*arrays_and_dtypes: Any) -> DtypeObj:
    """
    Wrapper around numpy.result_type which overcomes the NPY_MAXARGS (32)
    argument limit.
    """
    try:
        return np.result_type(*arrays_and_dtypes)
    except ValueError:
        # we have > NPY_MAXARGS terms in our expression
        return reduce(np.result_type, arrays_and_dtypes)
    except TypeError:
        from pandas.core.dtypes.cast import find_common_type
        from pandas.core.dtypes.common import is_extension_array_dtype

        arr_and_dtypes = list(arrays_and_dtypes)
        ea_dtypes, non_ea_dtypes = [], []
        for arr_or_dtype in arr_and_dtypes:
            if is_extension_array_dtype(arr_or_dtype):
                ea_dtypes.append(arr_or_dtype)
            else:
                non_ea_dtypes.append(arr_or_dtype)

        if non_ea_dtypes:
            try:
                np_dtype = np.result_type(*non_ea_dtypes)
            except ValueError:
                np_dtype = reduce(np.result_type, arrays_and_dtypes)
            return find_common_type([*ea_dtypes, np_dtype])

        return find_common_type(ea_dtypes)

def _check_resolvers(resolvers) -> None:
    if resolvers is not None:
        for resolver in resolvers:
            if not hasattr(resolver, "__getitem__"):
                name = type(resolver).__name__
                raise TypeError(
                    f"Resolver of type '{name}' does not "

def _check_for_locals(expr: str, stack_level: int, parser: str) -> None:
    at_top_of_stack = stack_level == 0
    not_pandas_parser = parser != "pandas"

    if not_pandas_parser:
        msg = "The '@' prefix is only supported by the pandas parser"
    elif at_top_of_stack:
        msg = (
            "The '@' prefix is not allowed in top-level eval calls.\n"
            "please refer to your variables by name without the '@' prefix."
        )

    if at_top_of_stack or not_pandas_parser:
        for toknum, tokval in tokenize_string(expr):
            if toknum == tokenize.OP and tokval == "@":
                raise SyntaxError(msg)

def _is_indexed_like(obj, axes) -> bool:
    if isinstance(obj, Series):
        if len(axes) > 1:
            return False
        return obj.index.equals(axes[0])
    elif isinstance(obj, DataFrame):
        return obj.index.equals(axes[0])

    return False

def _get_cython_function(
    cls, kind: str, how: str, dtype: np.dtype, is_numeric: bool
):
    dtype_str = dtype.name
    ftype = cls._CYTHON_FUNCTIONS[kind][how]

    # see if there is a fused-type version of function
    # only valid for numeric
    if callable(ftype):
        f = ftype
    else:
        f = getattr(libgroupby, ftype)
    if is_numeric:
        return f
    elif dtype == np.dtype(object):
        if how in ["median", "cumprod"]:
            # no fused types -> no __signatures__
            raise NotImplementedError(
                f"function is not implemented for this dtype: "
                f"[how->{how},dtype->{dtype_str}]"
            )
        elif how in ["std", "sem", "idxmin", "idxmax"]:
            # We have a partial object that does not have __signatures__
            return f
        elif how in ["skew", "kurt"]:
            # _get_cython_vals will convert to float64
            pass
        elif "object" not in f.__signatures__:
            # raise NotImplementedError here rather than TypeError later
            raise NotImplementedError(
                f"function is not implemented for this dtype: "
                f"[how->{how},dtype->{dtype_str}]"
            )
        return f
    else:
        raise NotImplementedError(
            "This should not be reached. Please report a bug at "
            "github.com/pandas-dev/pandas/",
            dtype,

def _get_output_shape(self, ngroups: int, values: np.ndarray) -> Shape:
    how = self.how
    kind = self.kind

    arity = self._cython_arity.get(how, 1)

    out_shape: Shape
    if how == "ohlc":
        out_shape = (ngroups, arity)
    elif arity > 1:
        raise NotImplementedError(
            "arity of more than 1 is not supported for the 'how' argument"
        )
    elif kind == "transform":
        out_shape = values.shape
    else:
        out_shape = (ngroups, *values.shape[1:])
    return out_shape

def _get_out_dtype(self, dtype: np.dtype) -> np.dtype:
    how = self.how

    if how == "rank":
        out_dtype = "float64"
    elif how in ["idxmin", "idxmax"]:
        # The Cython implementation only produces the row number; we'll take
        # from the index using this in post processing
        out_dtype = "intp"
    elif dtype.kind in "iufcb":
        out_dtype = f"{dtype.kind}{dtype.itemsize}"
    else:
        out_dtype = "object"
    return np.dtype(out_dtype)

def _get_result_dtype(self, dtype: np.dtype) -> np.dtype:
    """
    Get the desired dtype of a result based on the
    input dtype and how it was computed.

    Parameters
    ----------
    dtype : np.dtype

    Returns
    -------
    np.dtype
        The desired dtype of the result.
    """
    how = self.how

    if how in ["sum", "cumsum", "sum", "prod", "cumprod"]:
        if dtype == np.dtype(bool):
            return np.dtype(np.int64)
    elif how in ["mean", "median", "var", "std", "sem"]:
        if dtype.kind in "fc":
            return dtype
        elif dtype.kind in "iub":
            return np.dtype(np.float64)
    return dtype

def _validate_axis(self, axis: AxisInt, values: ArrayLike) -> None:
    if values.ndim > 2:
        raise NotImplementedError("number of dimensions is currently limited to 2")
    if values.ndim == 2:
        assert axis == 1, axis
    elif not is_1d_only_ea_dtype(values.dtype):

def indices(self) -> dict[Hashable, npt.NDArray[np.intp]]:
    """dict {group name -> group indices}"""
    if len(self.groupings) == 1 and isinstance(self.result_index, CategoricalIndex):
        # This shows unused categories in indices GH#38642
        result = self.groupings[0].indices
    else:
        result_index, ids = self.result_index_and_ids
        values = result_index._values
        categories = Categorical.from_codes(
            ids, categories=range(len(result_index))
        )
        result = {
            # mypy is not aware that group has to be an integer
            values[group]: axis_ilocs  # type: ignore[call-overload]
            for group, axis_ilocs in categories._reverse_indexer().items()
            if len(axis_ilocs)
        }
    if not self.dropna:
        has_mi = isinstance(self.result_index, MultiIndex)
        if not has_mi and self.result_index.hasnans:
            result = {
                np.nan if isna(key) else key: value for key, value in result.items()
            }
        elif has_mi:
            # MultiIndex has no efficient way to tell if there are NAs
            result = {
                # error: "Hashable" has no attribute "__iter__" (not iterable)
                tuple(np.nan if isna(comp) else comp for comp in key): value  # type: ignore[attr-defined]
                for key, value in result.items()
            }

    return result

def size(self) -> Series:
    """
    Compute group sizes.
    """
    ids = self.ids
    ngroups = self.ngroups
    out: np.ndarray | list
    if ngroups:
        if self.has_dropped_na:
            out = np.bincount(ids + 1, minlength=ngroups + 1)[1:]
        else:
            out = np.bincount(ids, minlength=ngroups)
    else:
        out = []
    return Series(out, index=self.result_index, dtype="int64", copy=False)

def groups(self) -> dict[Hashable, Index]:
    """dict {group name -> group labels}"""
    if len(self.groupings) == 1:
        return self.groupings[0].groups
    result_index, ids = self.result_index_and_ids
    values = result_index._values
    categories = Categorical.from_codes(ids, categories=range(len(result_index)))
    result = {
        # mypy is not aware that group has to be an integer
        values[group]: self.axis.take(axis_ilocs)  # type: ignore[call-overload]
        for group, axis_ilocs in categories._reverse_indexer().items()
    }
    return result

def get_group_levels(self) -> Generator[Index]:
    # Note: only called from _insert_inaxis_grouper, which
    #  is only called for BaseGrouper, never for BinGrouper
    result_index = self.result_index
    if len(self.groupings) == 1:
        yield result_index
    else:
        for level in range(result_index.nlevels - 1, -1, -1):
            yield result_index.get_level_values(level)

def groups(self):
    """dict {group name -> group labels}"""
    # this is mainly for compat
    # GH 3881
    result = {
        key: value
        for key, value in zip(self.binlabels, self.bins, strict=True)
        if key is not NaT
    }
    return result

def indices(self):
    indices = collections.defaultdict(list)

    i: np.int64 | int = 0
    for label, bin in zip(self.binlabels, self.bins, strict=True):
        if i < bin:
            if label is not NaT:
                indices[label] = list(range(i, bin))
            i = bin
    return indices

def result_index_and_ids(self):
    result_index = self.binlabels
    if len(self.binlabels) != 0 and isna(self.binlabels[0]):
        result_index = result_index[1:]

    ngroups = len(result_index)
    rep = np.diff(np.r_[0, self.bins])

    rep = ensure_platform_int(rep)
    if ngroups == len(self.bins):
        ids = np.repeat(np.arange(ngroups), rep)
    else:
        ids = np.repeat(np.r_[-1, np.arange(ngroups)], rep)
    ids = ensure_platform_int(ids)

    return result_index, ids

def _make_mask_from_positional_indexer(
    self,
    arg: PositionalIndexer | tuple,
) -> np.ndarray:
    if is_list_like(arg):
        if all(is_integer(i) for i in cast("Iterable", arg)):
            mask = self._make_mask_from_list(cast("Iterable[int]", arg))
        else:
            mask = self._make_mask_from_tuple(cast("tuple", arg))

    elif isinstance(arg, slice):
        mask = self._make_mask_from_slice(arg)
    elif is_integer(arg):
        mask = self._make_mask_from_int(cast("int", arg))
    else:
        raise TypeError(
            f"Invalid index {type(arg)}. "
            "Must be integer, list-like, slice or a tuple of "
            "integers and slices"
        )

    if isinstance(mask, bool):
        if mask:
            mask = self._ascending_count >= 0
        else:
            mask = self._ascending_count < 0

    return cast("np.ndarray", mask)

def _make_mask_from_list(self, args: Iterable[int]) -> bool | np.ndarray:
    positive = [arg for arg in args if arg >= 0]
    negative = [-arg - 1 for arg in args if arg < 0]

    mask: bool | np.ndarray = False

    if positive:
        mask |= np.isin(self._ascending_count, positive)

    if negative:
        mask |= np.isin(self._descending_count, negative)

    return mask

def _make_mask_from_tuple(self, args: tuple) -> bool | np.ndarray:
    mask: bool | np.ndarray = False

    for arg in args:
        if is_integer(arg):
            mask |= self._make_mask_from_int(cast("int", arg))
        elif isinstance(arg, slice):
            mask |= self._make_mask_from_slice(arg)
        else:
            raise ValueError(
                f"Invalid argument {type(arg)}. Should be int or slice."
            )

    return mask

def _make_mask_from_slice(self, arg: slice) -> bool | np.ndarray:
    start = arg.start
    stop = arg.stop
    step = arg.step

    if step is not None and step < 0:
        raise ValueError(f"Invalid step {step}. Must be non-negative")

    mask: bool | np.ndarray = True

    if step is None:
        step = 1

    if start is None:
        if step > 1:
            mask &= self._ascending_count % step == 0

    elif start >= 0:
        mask &= self._ascending_count >= start

        if step > 1:
            mask &= (self._ascending_count - start) % step == 0

    else:
        mask &= self._descending_count < -start

        offset_array = self._descending_count + start + 1
        limit_array = (
            self._ascending_count + self._descending_count + (start + 1)
        ) < 0
        offset_array = np.where(limit_array, self._ascending_count, offset_array)

        mask &= offset_array % step == 0

    if stop is not None:
        if stop >= 0:
            mask &= self._ascending_count < stop
        else:
            mask &= self._descending_count >= -stop

    return mask

def _get_index(self, name):
    """
    Safe get multiple indices, translate keys for
    datelike to underlying repr.
    """

    def get_converter(s):
        # possibly convert to the actual key types
        # in the indices, could be a Timestamp or an np.datetime64
        if isinstance(s, datetime.datetime):
            return lambda key: Timestamp(key)
        elif isinstance(s, np.datetime64):
            return lambda key: Timestamp(key).asm8
        else:
            return lambda key: key

    if isna(name):
        return self.indices.get(np.nan, [])
    if isinstance(name, tuple):
        name = tuple(np.nan if isna(comp) else comp for comp in name)

    if len(self.indices) > 0:
        index_sample = next(iter(self.indices))
    else:
        index_sample = None  # Dummy sample

    if isinstance(index_sample, tuple):
        if not isinstance(name, tuple):
            msg = "must supply a tuple to get_group with multiple grouping keys"
            raise ValueError(msg)
        if not len(name) == len(index_sample):
            try:
                # If the original grouper was a tuple
                return self.indices[name]
            except KeyError as err:
                # turns out it wasn't a tuple
                msg = (
                    "must supply a same-length tuple to get_group "
                    "with multiple grouping keys"
                )
                raise ValueError(msg) from err

        converters = (get_converter(s) for s in index_sample)
        name = tuple(f(n) for f, n in zip(converters, name, strict=True))
    else:
        converter = get_converter(index_sample)
        name = converter(name)

    return self.indices.get(name, [])

def __getattr__(self, attr: str):
    if attr in self._internal_names_set:
        return object.__getattribute__(self, attr)
    if attr in self.obj:
        return self[attr]

    raise AttributeError(
        f"'{type(self).__name__}' object has no attribute '{attr}'"

def _insert_inaxis_grouper(
    self, result: Series | DataFrame, qs: npt.NDArray[np.float64] | None = None
) -> DataFrame:
    if isinstance(result, Series):
        result = result.to_frame()

    n_groupings = len(self._grouper.groupings)

    def full_key(name: Hashable) -> Hashable:
        # GH#17024 expanding MultiIndex columns with a partial key is
        #  deprecated; pad the key to full length ourselves
        if isinstance(result.columns, MultiIndex) and not isinstance(name, tuple):
            return (name,) + ("",) * (result.columns.nlevels - 1)
        return name

    if qs is not None:
        result.insert(
            0, full_key(f"level_{n_groupings}"), np.tile(qs, len(result) // len(qs))
        )

    # zip in reverse so we can always insert at loc 0
    for level, (name, lev) in enumerate(
        zip(
            reversed(self._grouper.names),
            self._grouper.get_group_levels(),
            strict=True,
        )
    ):
        if name is None:
            # Behave the same as .reset_index() when a level is unnamed
            name = (
                "index"
                if n_groupings == 1 and qs is None
                else f"level_{n_groupings - level - 1}"
            )

        # GH #28549
        # When using .apply(-), name will be in columns already
        if name not in result.columns:
            # if in_axis:
            if qs is None:
                result.insert(0, full_key(name), lev)
            else:
                result.insert(
                    0, full_key(name), Index(np.repeat(lev, len(qs)), copy=False)
                )

    return result

def _cython_agg_general(
    self,
    how: str,
    alt: Callable | None = None,
    numeric_only: bool = False,
    min_count: int = -1,
    **kwargs,
):
    # Note: we never get here with how="ohlc" for DataFrameGroupBy;
    #  that goes through SeriesGroupBy

    if not is_bool(numeric_only):
        raise ValueError("numeric_only accepts only Boolean values")

    data = self._get_data_to_aggregate(numeric_only=numeric_only, name=how)

    def array_func(values: ArrayLike) -> ArrayLike:
        # GH#37850 For numpy boolean data, any==max and all==min.
        # The min/max Cython path is faster (fused types, no mask overhead).
        # Excludes nullable BooleanDtype which needs Kleene logic.
        use_bool_fastpath = how in ["any", "all"] and values.dtype == np.dtype(
            "bool"
        )
        if use_bool_fastpath:
            _how = "max" if how == "any" else "min"
        else:
            _how = how
        try:
            result = self._grouper._cython_operation(
                values,
                _how,
                axis=data.ndim - 1,
                min_count=min_count,
                **kwargs,
            )
        except NotImplementedError as err:
            # generally if we have numeric_only=False
            # and non-applicable functions
            # try to python agg
            # TODO: shouldn't min_count matter?
            if alt is None or how in ["any", "all", "std", "sem"]:
                raise TypeError(
                    f"{how} is not supported for {values.dtype} dtype"
                ) from err
        else:
            if use_bool_fastpath and result.dtype.kind == "f":
                fill = 0.0 if how == "any" else 1.0
                result = np.where(
                    np.isnan(result), fill, np.asarray(result)
                ).astype(bool)
            return result

        assert alt is not None
        result = self._agg_py_fallback(how, values, ndim=data.ndim, alt=alt)
        return result

    new_mgr = data.grouped_reduce(array_func)
    res = self._wrap_agged_manager(new_mgr)
    if how in ["idxmin", "idxmax"]:
        # mypy expects how to be Literal["idxmin", "idxmax"].
        res = self._wrap_idxmax_idxmin(res, how=how, skipna=kwargs["skipna"])  # type: ignore[arg-type]
    out = self._wrap_aggregated_output(res)
    return out.__finalize__(self.obj, method="groupby")

def _transform(self, func, *args, engine=None, engine_kwargs=None, **kwargs):
    # optimized transforms
    if not isinstance(func, str):
        return self._transform_general(func, engine, engine_kwargs, *args, **kwargs)

    elif func not in base.transform_kernel_allowlist:
        msg = f"'{func}' is not a valid function name for transform(name)"
        raise ValueError(msg)
    elif func in base.cythonized_kernels or func in base.transformation_kernels:
        # cythonized transform or canned "agg+broadcast"
        if engine is not None:
            kwargs["engine"] = engine
            kwargs["engine_kwargs"] = engine_kwargs
        return getattr(self, func)(*args, **kwargs)

    else:
        # i.e. func in base.reduction_kernels
        if self.observed:
            return self._reduction_kernel_transform(
                func, *args, engine=engine, engine_kwargs=engine_kwargs, **kwargs
            )

        with (
            com.temp_setattr(self, "observed", True),
            com.temp_setattr(self, "_grouper", self._grouper.observed_grouper),
        ):
            return self._reduction_kernel_transform(
                func, *args, engine=engine, engine_kwargs=engine_kwargs, **kwargs

def _reduction_kernel_transform(
    self, func, *args, engine=None, engine_kwargs=None, **kwargs
):
    # GH#30918 Use _transform_fast only when we know func is an aggregation
    # If func is a reduction, we need to broadcast the
    # result to the whole group. Compute func result
    # and deal with possible broadcasting below.
    with com.temp_setattr(self, "as_index", True):
        # GH#49834 - result needs groups in the index for
        # _wrap_transform_fast_result
        if func in ["idxmin", "idxmax"]:
            func = cast("Literal['idxmin', 'idxmax']", func)
            result = self._idxmax_idxmin(func, True, *args, **kwargs)
        else:
            if engine is not None:
                kwargs["engine"] = engine
                kwargs["engine_kwargs"] = engine_kwargs
            result = getattr(self, func)(*args, **kwargs)

    return self._wrap_transform_fast_result(result)

def _apply_filter(self, indices, dropna):
    if len(indices) == 0:
        indices = np.array([], dtype="int64")
    else:
        indices = np.sort(np.concatenate(indices))
    if dropna:
        filtered = self._selected_obj.take(indices, axis=0)
    else:
        mask = np.empty(len(self._selected_obj.index), dtype=bool)
        mask.fill(False)
        mask[indices.astype(int)] = True
        # mask fails to broadcast when passed to where; broadcast manually.
        mask = np.tile(mask, [*self._selected_obj.shape[1:], 1]).T
        filtered = self._selected_obj.where(mask)  # Fill with NaNs.
    return filtered

def _obj_1d_constructor(self) -> Callable:
    # GH28330 preserve subclassed Series/DataFrames
    if isinstance(self.obj, DataFrame):
        return self.obj._constructor_sliced
    assert isinstance(self.obj, Series)
    return self.obj._constructor

def describe(
    self,
    percentiles=None,
    include=None,
    exclude=None,
) -> NDFrameT:
    obj = self._obj_with_exclusions

    if len(obj) == 0:
        described = obj.describe(
            percentiles=percentiles, include=include, exclude=exclude
        )
        if obj.ndim == 1:
            result = described
        else:
            result = described.unstack()
        return result.to_frame().T.iloc[:0]

    with com.temp_setattr(self, "as_index", True):
        result = self._python_apply_general(
            lambda x: x.describe(
                percentiles=percentiles, include=include, exclude=exclude
            ),
            obj,
            not_indexed_same=True,
        )

    # GH#49256 - properly handle the grouping column(s)
    result = result.unstack()
    if not self.as_index:
        result = self._insert_inaxis_grouper(result)
        result.index = default_index(len(result))

    return result

def _wrap_idxmax_idxmin(
    self, res: NDFrameT, how: Literal["idxmax", "idxmin"], skipna: bool
) -> NDFrameT:
    index = self.obj.index
    if res.size == 0:
        result = res.astype(index.dtype)
    elif skipna and res.lt(0).any(axis=None):
        raise ValueError(
            f"{how} with skipna=True encountered all NA values in a group."
        )
    else:
        if isinstance(index, MultiIndex):
            index = index.to_flat_index()
        values = res._values
        assert isinstance(values, np.ndarray)
        na_value = na_value_for_dtype(index.dtype, compat=False)
        if isinstance(res, Series):
            # mypy: expression has type "Series", variable has type "NDFrameT"
            result = res._constructor(  # type: ignore[assignment]
                index.array.take(values, allow_fill=True, fill_value=na_value),
                index=res.index,
                name=res.name,
            )
        else:
            data = {}
            for k, column_values in enumerate(values.T):
                data[k] = index.array.take(
                    column_values, allow_fill=True, fill_value=na_value
                )
            result = self.obj._constructor(data, index=res.index)
            result.columns = res.columns
    return result

def _factorize_monotonic(
    grouping_vector,
    sort: bool,
) -> tuple[npt.NDArray[np.intp], np.ndarray] | None:
    """
    Fast-path factorization for monotonic (sorted) grouping vectors.

    Uses adjacent-element comparison instead of hash table construction.
    Returns (codes, uniques) or None if the fast path is not applicable.

    Since monotonic arrays contain no NA values (NAs break monotonicity
    checks for n >= 2), NA handling is not needed here.
    """
    if isinstance(grouping_vector, (Series, Index)):
        # Bail before np.asarray for extension dtypes (PeriodDtype,
        # DatetimeTZDtype, etc.) — converting them would box every element.
        dtype = grouping_vector.dtype
        if not isinstance(dtype, np.dtype) or dtype.kind not in "iufmMb":
            return None
        if isinstance(grouping_vector, Index) and dtype.kind in "mM":
            # DatetimeIndex/TimedeltaIndex.factorize has its own fastpaths
            # (freq-based and monotonic) that retain freq and Index uniques
            return None
        ascending = grouping_vector.is_monotonic_increasing
        if not ascending and not grouping_vector.is_monotonic_decreasing:
            return None
        arr = np.asarray(grouping_vector)
    elif isinstance(grouping_vector, np.ndarray):
        arr = grouping_vector
        if arr.dtype.kind not in "iufmMb":
            return None
        if len(arr) <= 1:
            return None
        # Quick sample check: compare a few spaced elements to avoid
        # a full O(n) scan on clearly unsorted data.
        sample_idx = np.linspace(0, len(arr) - 1, num=min(8, len(arr)), dtype=np.intp)
        sample = arr[sample_idx]
        if not bool(np.all(sample[1:] >= sample[:-1])):
            if not bool(np.all(sample[1:] <= sample[:-1])):
                return None
        ascending = bool(np.all(arr[1:] >= arr[:-1]))
        if not ascending:
            if not bool(np.all(arr[1:] <= arr[:-1])):
                return None
    else:
        return None

    if len(arr) <= 1:
        return None

    codes, uniques_indexer = algorithms.factorize_monotonic_codes(arr, ascending, sort)
    return codes, arr[uniques_indexer]

def _convert_grouper(axis: Index, grouper):
    if isinstance(grouper, dict):
        return grouper.get
    elif isinstance(grouper, Series):
        if grouper.index.equals(axis):
            return grouper._values
        else:
            return grouper.reindex(axis)._values
    elif isinstance(grouper, MultiIndex):
        return grouper._values
    elif isinstance(grouper, (list, tuple, Index, Categorical, np.ndarray)):
        if len(grouper) != len(axis):
            raise ValueError("Grouper and axis must be same length")

        if isinstance(grouper, (list, tuple)):
            grouper = com.asarray_tuplesafe(grouper)
        return grouper
    else:
        return grouper

def name(self) -> Hashable:
    ilevel = self._ilevel
    if ilevel is not None:
        return self._index.names[ilevel]

    if isinstance(self._orig_grouper, (Index, Series)):
        return self._orig_grouper.name

    elif isinstance(self.grouping_vector, ops.BaseGrouper):
        return self.grouping_vector.result_index.name

    elif isinstance(self.grouping_vector, Index):
        return self.grouping_vector.name

    # otherwise we have ndarray or ExtensionArray -> no name
    return None

def _ilevel(self) -> int | None:
    """
    If necessary, converted index level name to index level position.
    """
    level = self.level
    if level is None:
        return None
    if not isinstance(level, int):
        index = self._index
        if level not in index.names:
            raise AssertionError(f"Level {level} not in index")
        if isinstance(index, MultiIndex) and index.names.count(level) > 1:
            warnings.warn(
                f"Grouping by index level '{level}' which matches multiple "
                f"index levels is ambiguous. Currently the first matching "
                f"level is used. In a future version of pandas, this will "
                f"raise a ValueError. Use the level number instead.",
                Pandas4Warning,
                stacklevel=find_stack_level(),
            )
        return index.names.index(level)
    return level

def groups(self) -> dict[Hashable, Index]:
    codes, uniques = self._codes_and_uniques
    uniques = Index._with_infer(uniques, name=self.name, copy=False)  # type: ignore[assignment]

    r, counts = libalgos.groupsort_indexer(ensure_platform_int(codes), len(uniques))
    counts = ensure_int64(counts).cumsum()
    _result = (r[start:end] for start, end in pairwise(counts))
    # map to the label
    result = {k: self._index.take(v) for k, v in zip(uniques, _result, strict=True)}

    return PrettyDict(result)

def _wrap_transform_general_frame(
    obj: DataFrame, group: DataFrame, res: DataFrame | Series
) -> DataFrame:
    from pandas import concat

    if isinstance(res, Series):
        # we need to broadcast across the
        # other dimension; this will preserve dtypes
        # GH14457
        if res.index.is_(obj.index):
            res_frame = concat([res] * len(group.columns), axis=1, ignore_index=True)
            res_frame.columns = group.columns
            res_frame.index = group.index
        else:
            res_frame = obj._constructor(
                np.tile(res.values, (len(group.index), 1)),
                columns=group.columns,
                index=group.index,
            )
        assert isinstance(res_frame, DataFrame)
        return res_frame
    elif isinstance(res, DataFrame) and not res.index.is_(group.index):
        return res._align_frame(group)[0]
    else:
        return res

def __getitem__(self, key: int) -> Any:
    """Provide backward-compatible tuple-style access."""
    if key == 0:
        return self.column
    elif key == 1:
        return self.aggfunc
    elif key == 2:
        return self.args
    elif key == 3:
        return self.kwargs
    raise IndexError("index out of range")

def _get_data_to_aggregate(
    self, *, numeric_only: bool = False, name: str | None = None
) -> SingleBlockManager:
    ser = self._obj_with_exclusions
    single = ser._mgr
    if numeric_only and not is_numeric_dtype(ser.dtype):
        # GH#41291 match Series behavior
        kwd_name = "numeric_only"
        raise TypeError(
            f"Cannot use {kwd_name}=True with "
            f"{type(self).__name__}.{name} and non-numeric dtypes."
        )
    return single

def _aggregate_multiple_funcs(self, arg, *args, **kwargs) -> DataFrame:
    if isinstance(arg, dict):
        raise SpecificationError("nested renamer is not supported")

    if any(isinstance(x, (tuple, list)) for x in arg):
        arg = ((x, x) if not isinstance(x, (tuple, list)) else x for x in arg)
    else:
        # list of functions / function names
        columns = (com.get_callable_name(f) or f for f in arg)
        arg = zip(columns, arg, strict=True)

    results: dict[base.OutputKey, DataFrame | Series] = {}
    with com.temp_setattr(self, "as_index", True):
        # Combine results using the index, need to adjust index after
        # if as_index=False (GH#50724)
        for idx, (name, func) in enumerate(arg):
            key = base.OutputKey(label=name, position=idx)
            results[key] = self.aggregate(func, *args, **kwargs)

    if any(isinstance(x, DataFrame) for x in results.values()):
        from pandas import concat

        res_df = concat(
            results.values(), axis=1, keys=[key.label for key in results]
        )
        return res_df

    indexed_output = {key.position: val for key, val in results.items()}
    # GH#39609 with no funcs, index by the groups
    index = None if results else self._grouper.result_index
    output = self.obj._constructor_expanddim(indexed_output, index=index)
    output.columns = Index(key.label for key in results)

    return output

def _transform_general(
    self, func: Callable, engine, engine_kwargs, *args, **kwargs
) -> Series:
    """
    Transform with a callable `func`.
    """
    if maybe_use_numba(engine):
        return self._transform_with_numba(
            func, *args, engine_kwargs=engine_kwargs, **kwargs
        )
    assert callable(func)
    klass = type(self.obj)

    results = []
    for name, group in self._grouper.get_iterator(
        self._obj_with_exclusions,
    ):
        # this setattr is needed for test_transform_lambda_with_datetimetz
        object.__setattr__(group, "name", name)
        res = func(group, *args, **kwargs)

        results.append(klass(res, index=group.index))

    # check for empty "results" to avoid concat ValueError
    if results:
        from pandas.core.reshape.concat import concat

        concatenated = concat(results, ignore_index=True)
        result = self._set_result_index_ordered(concatenated)
    else:
        result = self.obj._constructor(dtype=np.float64)

    result.name = self.obj.name
    return result

def _python_agg_general(self, func, *args, **kwargs):
    f = lambda x: func(x, *args, **kwargs)

    obj = self._obj_with_exclusions

    if self.ngroups == 0 or len(obj.columns) == 0:
        res_index = self._grouper.result_index
        res = self.obj._constructor(index=res_index, columns=obj.columns).astype(
            obj.dtypes
        )
    else:
        output: dict[int, ArrayLike] = {
            idx: self._grouper.agg_series(ser, f)
            for idx, (name, ser) in enumerate(obj.items())
        }
        res = self.obj._constructor(output)
        res.columns = obj.columns.copy(deep=False)
    return self._wrap_aggregated_output(res)

def _wrap_applied_output_series(
    self,
    values: list[Series],
    not_indexed_same: bool,
    first_not_none,
    key_index: Index | None,
    is_transform: bool,
) -> DataFrame | Series:
    kwargs = first_not_none._construct_axes_dict()
    backup = Series(**kwargs)
    values = [x if (x is not None) else backup for x in values]

    all_indexed_same = all_indexes_same(x.index for x in values)

    if not all_indexed_same:
        # GH 8467
        return self._concat_objects(
            values,
            not_indexed_same=True,
            is_transform=is_transform,
        )

    # Combine values
    # vstack+constructor is faster than concat and handles MI-columns
    stacked_values = np.vstack([np.asarray(v) for v in values])

    index = key_index
    columns = first_not_none.index.copy()
    if columns.name is None:
        # GH6124 - propagate name of Series when it's consistent
        names = {v.name for v in values}
        if len(names) == 1:
            columns.name = next(iter(names))

    if stacked_values.dtype == object:
        # We'll have the DataFrame constructor do inference
        stacked_values = stacked_values.tolist()
    result = self.obj._constructor(stacked_values, index=index, columns=columns)

    if not self.as_index:
        result = self._insert_inaxis_grouper(result)

    return result.__finalize__(self.obj, method="groupby")

def _transform_general(self, func, engine, engine_kwargs, *args, **kwargs):
    if maybe_use_numba(engine):
        return self._transform_with_numba(
            func, *args, engine_kwargs=engine_kwargs, **kwargs
        )
    from pandas.core.reshape.concat import concat

    applied = []
    obj = self._obj_with_exclusions
    gen = self._grouper.get_iterator(obj)
    fast_path, slow_path = self._define_paths(func, *args, **kwargs)

    # Determine whether to use slow or fast path by evaluating on the first group.
    # Need to handle the case of an empty generator and process the result so that
    # it does not need to be computed again.
    try:
        name, group = next(gen)
    except StopIteration:
        pass
    else:
        # 2023-02-27 No tests broken by disabling this pinning
        object.__setattr__(group, "name", name)
        try:
            path, res = self._choose_path(fast_path, slow_path, group)
        except ValueError as err:
            # e.g. test_transform_with_non_scalar_group
            msg = "transform must return a scalar value for each group"
            raise ValueError(msg) from err
        if group.size > 0:
            res = _wrap_transform_general_frame(self.obj, group, res)
            applied.append(res)

    # Compute and process with the remaining groups
    for name, group in gen:
        if group.size == 0:
            continue
        # 2023-02-27 No tests broken by disabling this pinning
        object.__setattr__(group, "name", name)
        res = path(group)

        res = _wrap_transform_general_frame(self.obj, group, res)
        applied.append(res)

    concat_index = obj.columns
    concatenated = concat(
        applied, axis=0, verify_integrity=False, ignore_index=True
    )
    concatenated = concatenated.reindex(concat_index, axis=1)
    return self._set_result_index_ordered(concatenated)

def _choose_path(self, fast_path: Callable, slow_path: Callable, group: DataFrame):
    path = slow_path
    res = slow_path(group)

    if self.ngroups == 1:
        # no need to evaluate multiple paths when only
        # a single group exists
        return path, res

    # if we make it here, test if we can use the fast path
    try:
        res_fast = fast_path(group)
    except AssertionError:
        raise  # pragma: no cover
    except Exception:
        # GH#29631 For user-defined function, we can't predict what may be
        #  raised; see test_transform.test_transform_fastpath_raises
        return path, res

    # verify fast path returns either:
    # a DataFrame with columns equal to group.columns
    # OR a Series with index equal to group.columns
    if isinstance(res_fast, DataFrame):
        if not res_fast.columns.equals(group.columns):
            return path, res
    elif isinstance(res_fast, Series):
        if not res_fast.index.equals(group.columns):
            return path, res
    else:
        return path, res

    if res_fast.equals(res):
        path = fast_path

    return path, res

def __getitem__(self, key) -> DataFrameGroupBy | SeriesGroupBy:
    # per GH 23566
    if isinstance(key, tuple) and len(key) > 1:
        # if len == 1, then it becomes a SeriesGroupBy and this is actually
        # valid syntax, so don't raise
        raise ValueError(
            "Cannot subset columns with a tuple with more than one element. "
            "Use a list instead."
        )
    return super().__getitem__(key)

def _resolution_obj(self) -> Resolution:
    if isinstance(self.dtype, PeriodDtype):
        return self.dtype._resolution_obj
    elif self.dtype.kind == "M":
        return get_resolution(self.asi8, self.tz, reso=self._data._creso)  # type: ignore[attr-defined,union-attr]
    else:
        return get_resolution(self.asi8, tz=None, reso=self._data._creso)  # type: ignore[union-attr]

def _format_attrs(self):
    """
    Return a list of tuples of the (attr,formatted_value).
    """
    attrs = super()._format_attrs()
    for attrib in self._attributes:
        # iterating over _attributes prevents us from doing this for PeriodIndex
        if attrib == "freq":
            freq = self.freqstr
            if freq is not None:
                freq = repr(freq)  # e.g. D -> 'D'
            attrs.append(("freq", freq))
    return attrs

def _parse_with_reso(self, label: str) -> tuple[datetime, Resolution]:
    # overridden by TimedeltaIndex
    freqstr: str | None
    if self.freq is None:
        freqstr = None
    else:
        try:
            freqstr = self.freq.rule_code
        except NotImplementedError:
            # e.g. a generic DateOffset, which has no rule_code; it also
            #  carries no quarter/month anchor, so None is the right answer
            freqstr = None

    if isinstance(label, np.str_):
        # GH#45580
        label = str(label)

    parsed, reso_str = parsing.parse_datetime_string_with_reso(
        label,
        freqstr,
        warn_quarter=self._warn_quarter,
    )
    reso = Resolution.from_attrname(reso_str)
    return parsed, reso

def _maybe_cast_listlike_indexer(self, keyarr):
    """
    Analogue to maybe_cast_indexer for get_indexer instead of get_loc.
    """
    try:
        res = self._data._validate_listlike(keyarr, allow_object=True)
    except (ValueError, TypeError):
        if not isinstance(keyarr, ExtensionArray):
            # e.g. we don't want to cast DTA to ndarray[object]
            res = com.asarray_tuplesafe(keyarr)
            # TODO: com.asarray_tuplesafe shouldn't cast e.g. DatetimeArray
        else:
            res = keyarr
    return Index(res, dtype=res.dtype)

def freq(self, value) -> None:
    arr = self._data
    if value is not None:
        value = to_offset(value)
        arr._validate_frequency(arr, value)
        if arr.dtype.kind == "m" and not isinstance(value, (Tick, Day)):
            raise TypeError("TimedeltaArray/Index freq must be a Tick")

        if arr.ndim > 1:
            raise ValueError("Cannot set freq with ndim > 1")

    self._freq = value

def _get_arithmetic_result_freq(self, other) -> BaseOffset | None:
    """
    Check if we can preserve self.freq in addition or subtraction.
    """
    if not lib.is_scalar(other):
        return None

    # Normalize scalar types to their pandas equivalents.
    # Array arithmetic methods internally convert Tick/timedelta/
    # np.timedelta64 → Timedelta and datetime/np.datetime64 → Timestamp.
    # Since we receive the original user argument, normalize here.
    if isinstance(other, Tick):
        other = Timedelta(other)
    elif isinstance(other, np.timedelta64):
        other = Timedelta(other)
    elif isinstance(other, np.datetime64):
        other = Timestamp(other)
    elif not isinstance(other, (Timedelta, Timestamp)):
        # Handles datetime.timedelta, datetime.datetime
        try:
            other = Timedelta(other)
        except (ValueError, TypeError, OverflowError):
            try:
                other = Timestamp(other)
            except (ValueError, TypeError, OverflowError):
                return None

    if isinstance(self.freq, Tick):
        return self.freq
    elif self.dtype.kind == "m" and isinstance(other, Timedelta):
        return self.freq
    elif (
        self.dtype.kind == "m"
        and isinstance(other, Timestamp)
        and (other.tz is None or timezones.is_utc(other.tz))
    ):
        return self.freq
    elif (
        lib.is_np_dtype(self.dtype, "M")
        and isinstance(self.freq, Day)
        and isinstance(other, (Timedelta, Timestamp))
    ):
        return self.freq

    return None

def _arith_method(self, other, op):
    result = super()._arith_method(other, op)
    if result is NotImplemented:
        return result
    if op in (operator.add, roperator.radd, operator.sub, roperator.rsub):
        new_freq = self._get_arithmetic_result_freq(other)
        if new_freq is not None and isinstance(result, DatetimeTimedeltaMixin):
            if op is roperator.rsub:
                new_freq = -new_freq
            result._freq = new_freq
    return result

def factorize(
    self,
    sort: bool = False,
    use_na_sentinel: bool = True,
):
    if self.freq is not None:
        # We must be unique, so can short-circuit (and retain freq)
        if sort and self.freq.n < 0:
            codes = np.arange(len(self) - 1, -1, -1, dtype=np.intp)
            uniques = self[::-1]
        else:
            codes = np.arange(len(self), dtype=np.intp)
            uniques = self.copy()
        uniques._name = None
        return codes, uniques
    if len(self) > 1 and (
        self.is_monotonic_increasing or self.is_monotonic_decreasing
    ):
        # Monotonic implies no NaT, so NA handling is not needed
        codes, uniques_indexer = algorithms.factorize_monotonic_codes(
            self._data._ndarray, self.is_monotonic_increasing, sort
        )
        uniques = self[uniques_indexer]
        uniques._name = None
        return codes, uniques
    return super().factorize(sort=sort, use_na_sentinel=use_na_sentinel)

def _with_freq(self, freq):
    # GH#29843
    if freq is None:
        pass
    elif isinstance(freq, BaseOffset):
        if self.dtype.kind == "m" and not isinstance(freq, (Tick, Day)):
            raise TypeError("TimedeltaArray/Index freq must be a Tick")
    elif freq == "infer":
        freq = to_offset(self._inferred_freq_str)
    else:
        raise ValueError(f"Invalid frequency: {freq!r}")

    arr = self._data.view()
    result = type(self)._simple_new(arr, name=self._name)
    result._freq = freq
    return result

def _intersection(self, other: Index, sort: bool = False) -> Index:
    """
    intersection specialized to the case with matching dtypes and both non-empty.
    """
    other = cast("DatetimeTimedeltaMixin", other)

    if self._can_range_setop(other):
        return self._range_intersect(other, sort=sort)

    if not self._can_fast_intersect(other):
        result = Index._intersection(self, other, sort=sort)
        # We need to invalidate the freq because Index._intersection
        #  uses _shallow_copy on a view of self._data, which will preserve
        #  self.freq if we're not careful.
        # At this point we should have result.dtype == self.dtype
        #  and type(result) is type(self._data)
        result = self._wrap_setop_result(other, result)
        # error: "Index" has no attribute "_with_freq"; maybe "_with_infer"?
        return result._with_freq(None)._with_freq("infer")  # type: ignore[attr-defined]

    else:
        return self._fast_intersect(other, sort)

def _union(self, other, sort):
    # We are called by `union`, which is responsible for this validation
    assert isinstance(other, type(self))
    assert self.dtype == other.dtype

    if self._can_range_setop(other):
        return self._range_union(other, sort=sort)

    if self._can_fast_union(other) and (sort is not False or self[0] <= other[0]):
        # the _can_fast_union check ensures that result.freq == self.freq.
        #  With sort=False and self starting after other, the result would
        #  instead be non-monotonic and carry no freq, so we leave that case
        #  to the generic path below.  GH#66322
        return self._fast_union(other)
    else:
        # super()._union can return an ArrayLike; wrap into an Index first
        result = self._wrap_setop_result(other, super()._union(other, sort))
        return result._with_freq("infer")  # type: ignore[attr-defined]

def _searchsorted_monotonic(self, label, side: Literal["left", "right"] = "left"):
    if (
        self.is_monotonic_increasing
        and isinstance(label, (Timestamp, Timedelta))
        and abbrev_to_npy_unit(label.unit) > abbrev_to_npy_unit(self.unit)
    ):
        # For non-matching units we can safely round down (with side=right)
        # This is needed for GH#63262
        if side == "right":
            label = label.as_unit(self.unit)  # this should always be a round-down
        else:
            # round up
            label = label.ceil(self.unit).as_unit(self.unit)

    return super()._searchsorted_monotonic(label, side)

def _get_getitem_freq(self, key) -> BaseOffset | None:
    """
    Find the `freq` attribute to assign to the result of a __getitem__ lookup.
    """
    key = check_array_indexer(self._data, key)  # maybe ndarray[bool] -> slice
    freq = None
    if isinstance(key, slice):
        if self.freq is not None and key.step is not None:
            freq = key.step * self.freq
        else:
            freq = self.freq
    elif key is Ellipsis:
        # GH#21282 indexing with Ellipsis is similar to a full slice,
        #  should preserve `freq` attribute
        freq = self.freq
    elif com.is_bool_indexer(key):
        new_key = lib.maybe_booleans_to_slice(key.view(np.uint8))
        if isinstance(new_key, slice):
            return self._get_getitem_freq(new_key)
    return freq

def _concat(self, to_concat: list[Index], name: Hashable) -> Index:
    result = super()._concat(to_concat, name)

    # GH#3232: If the concat result is evenly spaced, we can retain the
    # original frequency
    obj = cast("DatetimeTimedeltaMixin", to_concat[0])
    to_concat_nonempty = cast(
        "list[DatetimeTimedeltaMixin]",
        [idx for idx in to_concat if len(idx)],
    )
    if (
        isinstance(result, type(self))
        and obj.freq is not None
        and all(idx.freq == obj.freq for idx in to_concat_nonempty)
    ):
        freq = obj.freq
        tz = getattr(self.dtype, "tz", None)
        if (
            isinstance(freq, Tick) or (tz is None and isinstance(freq, Day))
        ) and all(idx.unit == self.unit for idx in to_concat_nonempty):
            # freq is a fixed delta in the stored i8 representation, so we
            # can check boundary continuity without boxing endpoints to
            # Timestamps and doing per-pair offset arithmetic.
            step = Timedelta(freq).as_unit(self.unit)._value
            i8s = [idx._data._ndarray.view("i8") for idx in to_concat_nonempty]
            evenly_spaced = all(a[-1] + step == b[0] for a, b in pairwise(i8s))
        else:
            evenly_spaced = all(
                pair[0][-1] + freq == pair[1][0]
                for pair in pairwise(to_concat_nonempty)
            )
        if evenly_spaced:
            result._freq = freq

    return result

def _get_delete_freq(self, loc: int | slice | Sequence[int]):
    """
    Find the `freq` for self.delete(loc).
    """
    freq = None
    if self.freq is not None:
        if is_integer(loc):
            if loc in (0, -len(self), -1, len(self) - 1):
                freq = self.freq
        else:
            if is_list_like(loc):
                # error: Incompatible types in assignment (expression has
                # type "Union[slice, ndarray]", variable has type
                # "Union[int, slice, Sequence[int]]")
                loc = lib.maybe_indices_to_slice(  # type: ignore[assignment]
                    np.asarray(loc, dtype=np.intp), len(self)
                )
            if isinstance(loc, slice) and loc.step in (1, None):
                if loc.start in (0, None) or loc.stop in (len(self), None):
                    freq = self.freq
    return freq

def _get_insert_freq(self, loc: int, item):
    """
    Find the `freq` for self.insert(loc, item).
    """
    value = self._data._validate_scalar(item)
    item = self._data._box_func(value)

    freq = None
    if self.freq is not None:
        # freq can be preserved on edge cases
        if self.size:
            if item is NaT:
                pass
            elif loc in (0, -len(self)) and item + self.freq == self[0]:
                freq = self.freq
            elif (loc == len(self)) and item - self.freq == self[-1]:
                freq = self.freq
        # Adding a single item to an empty index may preserve freq
        elif isinstance(self.freq, Tick):
            # all TimedeltaIndex cases go through here; is_on_offset
            #  would raise TypeError
            freq = self.freq
        elif self.freq.is_on_offset(item):
            freq = self.freq
    return freq

def __new__(
    cls,
    data=None,
    freq=lib.no_default,
    dtype=None,
    copy: bool | None = None,
    name=None,
):
    name = maybe_extract_name(name, data, cls)

    # GH#63388
    data, copy = cls._maybe_copy_array_input(data, copy, dtype)

    if is_scalar(data):
        cls._raise_scalar_data_error(data)

    if dtype is not None:
        dtype = pandas_dtype(dtype)

    if (
        isinstance(data, TimedeltaArray)
        and freq is lib.no_default
        and (dtype is None or dtype == data.dtype)
    ):
        if copy:
            data = data.copy()
        return cls._simple_new(data, name=name)

    if (
        isinstance(data, TimedeltaIndex)
        and freq is lib.no_default
        and name is None
        and (dtype is None or dtype == data.dtype)
    ):
        if copy:
            return data.copy()
        else:
            return data._view()

    # - Cases checked above all return/raise before reaching here - #

    inferred_freq = data.freq if isinstance(data, TimedeltaIndex) else None

    tdarr = TimedeltaArray._from_sequence(data, dtype=dtype, copy=copy)
    refs = None
    if not copy and isinstance(data, (ABCSeries, Index)):
        refs = data._references

    result = cls._simple_new(tdarr, name=name, refs=refs)
    result._pin_freq(freq, inferred_freq)
    return result

def _arith_method(self, other: object, op: Callable[..., Any]) -> Index:
    result = super()._arith_method(other, op)
    if self.freq is None or not is_scalar(other):
        return result

    new_freq = None
    if isinstance(result, type(self)):
        new_freq = self._get_arith_result_freq(other, op)
    elif (
        getattr(getattr(result, "dtype", None), "kind", None) == "M" and op is rsub
    ):
        # Timestamp/datetime - TDI produces a DatetimeIndex.
        # The array __rsub__ does (-self) + other, losing freq in
        # negation. Compute the freq at the Index level.
        new_freq = self._get_rsub_datetime_result_freq(other)

    if new_freq is not None:
        result._freq = new_freq
    return result

def _inherit_from_data(
    name: str, delegate: type, cache: bool = False, wrap: bool = False
):
    """
    Make an alias for a method of the underlying ExtensionArray.

    Parameters
    ----------
    name : str
        Name of an attribute the class should inherit from its EA parent.
    delegate : class
    cache : bool, default False
        Whether to convert wrapped properties into cache_readonly
    wrap : bool, default False
        Whether to wrap the inherited result in an Index.

    Returns
    -------
    attribute, method, property, or cache_readonly
    """
    attr = getattr(delegate, name)

    if isinstance(attr, property) or type(attr).__name__ == "getset_descriptor":
        # getset_descriptor i.e. property defined in cython class
        if cache:

            def cached(self):
                return getattr(self._data, name)

            cached.__name__ = name
            cached.__doc__ = attr.__doc__
            method = cache_readonly(cached)

        else:

            def fget(self):
                result = getattr(self._data, name)
                if wrap:
                    if isinstance(result, type(self._data)):
                        return type(self)._simple_new(result, name=self.name)
                    elif isinstance(result, ABCDataFrame):
                        return result.set_index(self)
                    return Index(result, name=self.name, dtype=result.dtype, copy=False)
                return result

            def fset(self, value) -> None:
                setattr(self._data, name, value)

            fget.__name__ = name
            fget.__doc__ = attr.__doc__

            method = property(fget, fset)

    elif not callable(attr):
        # just a normal attribute, no wrapping
        method = attr

    else:
        # error: Incompatible redefinition (redefinition with type "Callable[[Any,
        # VarArg(Any), KwArg(Any)], Any]", original type "property")
        def method(self, *args, **kwargs):  # type: ignore[misc]
            if "inplace" in kwargs:
                raise ValueError(f"cannot use inplace with {type(self).__name__}")
            result = attr(self._data, *args, **kwargs)
            if wrap:
                if isinstance(result, type(self._data)):
                    return type(self)._simple_new(result, name=self.name)
                elif isinstance(result, ABCDataFrame):
                    return result.set_index(self)
                return Index(result, name=self.name, dtype=result.dtype, copy=False)
            return result

        method.__name__ = name
        method.__doc__ = attr.__doc__
        method.__signature__ = signature(attr)  # type: ignore[attr-defined]
    return method

def reindex(
    self,
    target: Axes,
    method: ReindexMethod | None = None,
    level: Level | None = None,
    limit: int | None = None,
    tolerance: float | None = None,
) -> tuple[Index, npt.NDArray[np.intp] | None]:
    """
    Create index with target's values (move/add/delete values as necessary)

    Returns
    -------
    new_index : pd.Index
        Resulting index
    indexer : np.ndarray[np.intp] or None
        Indices of output values in original index

    """
    if method is not None:
        raise NotImplementedError(
            "argument method is not implemented for CategoricalIndex.reindex"
        )
    if level is not None:
        raise NotImplementedError(
            "argument level is not implemented for CategoricalIndex.reindex"
        )
    if limit is not None:
        raise NotImplementedError(
            "argument limit is not implemented for CategoricalIndex.reindex"
        )
    return super().reindex(target)

def _maybe_cast_indexer(self, key: Hashable) -> int:
    # GH#41933: we have to do this instead of self._data._validate_scalar
    #  because this will correctly get partial-indexing on Interval categories
    try:
        return self._data._unbox_scalar(key)
    except KeyError:
        if is_valid_na_for_dtype(key, self.categories.dtype):
            return -1
        raise

def _maybe_cast_listlike_indexer(self, values: Axes) -> CategoricalIndex:
    if isinstance(values, CategoricalIndex):
        values = values._data
    if isinstance(values, Categorical):
        # Indexing on codes is more efficient if categories are the same,
        #  so we can apply some optimizations based on the degree of
        #  dtype-matching.
        cat = self._data._encode_with_my_categories(values)
        codes = cat._codes
    else:
        codes = self.categories.get_indexer(values)
        codes = codes.astype(self.codes.dtype, copy=False)
        cat = self._data._from_backing_data(codes)
    return type(self)._simple_new(cat)

def _union(self, other: Index, sort: bool | None) -> Index | ArrayLike | MultiIndex:
    # See _intersection for explanation of GH#55335.
    other = cast("CategoricalIndex", other)
    if not self.ordered and not self.categories.equals(other.categories):
        reordered = other._data.reorder_categories(self.categories)
        other = other._shallow_copy(reordered)
    return super()._union(other, sort)

def _is_comparable_dtype(self, dtype: DtypeObj) -> bool:
    """
    Can we compare values of the given dtype to our own?
    """
    if isinstance(dtype, ArrowDtype):
        # GH#62277
        if dtype.kind != "M":
            return False

        import pyarrow as pa

        pa_dtype = dtype.pyarrow_dtype
        if not pa.types.is_timestamp(pa_dtype):
            # GH#62051 date types (date32, date64) are not
            # comparable with DatetimeIndex
            return False
        if (pa_dtype.tz is None) ^ (self.tz is None):
            return False
        return True

    if self.tz is not None:
        # If we have tz, we can compare to tzaware
        return isinstance(dtype, DatetimeTZDtype)
    # if we dont have tz, we can only compare to tznaive
    return lib.is_np_dtype(dtype, "M")

def _can_range_setop(self, other) -> bool:
    # GH 46702: If self or other have non-UTC tzs, DST transitions prevent
    # range representation due to no singular step
    if (
        self.tz is not None
        and not timezones.is_utc(self.tz)
        and not timezones.is_fixed_offset(self.tz)
    ):
        return False
    if (
        other.tz is not None
        and not timezones.is_utc(other.tz)
        and not timezones.is_fixed_offset(other.tz)
    ):
        return False
    return super()._can_range_setop(other)

def get_loc(self, key):
    """
    Get integer location for requested label

    Returns
    -------
    loc : int
    """
    self._check_indexing_error(key)

    orig_key = key
    if is_valid_na_for_dtype(key, self.dtype):
        key = NaT

    if isinstance(key, self._data._recognized_scalars):
        # needed to localize naive datetimes
        self._disallow_mismatched_indexing(key)
        key = Timestamp(key)

    elif isinstance(key, str):
        try:
            parsed, reso = self._parse_with_reso(key)
        except ValueError as err:
            raise KeyError(key) from err
        self._disallow_mismatched_indexing(parsed)

        if self._can_partial_date_slice(reso):
            try:
                return self._partial_date_slice(reso, parsed)
            except KeyError as err:
                raise KeyError(key) from err

        key = parsed

    elif isinstance(key, dt.timedelta):
        # GH#20464
        raise TypeError(
            f"Cannot index {type(self).__name__} with {type(key).__name__}"
        )

    elif isinstance(key, dt.time):
        return self.indexer_at_time(key)

    else:
        # unrecognized type
        raise KeyError(key)

    try:
        return Index.get_loc(self, key)
    except KeyError as err:
        raise KeyError(orig_key) from err

def slice_indexer(self, start=None, end=None, step=None):
    """
    Return indexer for specified label slice.
    Index.slice_indexer, customized to handle time slicing.

    In addition to functionality provided by Index.slice_indexer, does the
    following:

    - if both `start` and `end` are instances of `datetime.time`, it
      invokes `indexer_between_time`
    - if `start` and `end` are both either string or None perform
      value-based selection in non-monotonic cases.

    """
    # For historical reasons DatetimeIndex supports slices between two
    # instances of datetime.time as if it were applying a slice mask to
    # an array of (self.hour, self.minute, self.seconds, self.microsecond).
    if isinstance(start, dt.time) and isinstance(end, dt.time):
        if step is not None and step != 1:
            raise ValueError("Must have step size of 1 with time slices")
        return self.indexer_between_time(start, end)

    if isinstance(start, dt.time) or isinstance(end, dt.time):
        raise KeyError("Cannot mix time and non-time slice keys")

    def check_str_or_none(point) -> bool:
        return point is not None and not isinstance(point, str)

    # GH#33146 if start and end are combinations of str and None and Index is not
    # monotonic, we can not use Index.slice_indexer because it does not honor the
    # actual elements, is only searching for start and end
    if (
        check_str_or_none(start)
        or check_str_or_none(end)
        or self.is_monotonic_increasing
    ):
        return Index.slice_indexer(self, start, end, step)

    mask = np.array(True)
    in_index = True
    if start is not None:
        start_casted = self._maybe_cast_slice_bound(start, "left")
        mask = start_casted <= self
        in_index &= (start_casted == self).any()

    if end is not None:
        end_casted = self._maybe_cast_slice_bound(end, "right")
        mask = (self <= end_casted) & mask
        in_index &= (end_casted == self).any()

    if not in_index:
        raise KeyError(
            "Value based partial slicing on non-monotonic DatetimeIndexes "
            "with non-existing keys is not allowed.",
        )
    indexer = mask.nonzero()[0][::step]
    if len(indexer) == len(self):
        return slice(None)
    else:
        return indexer

def __new__(
    cls,
    start: int | np.integer | range | RangeIndex | None = None,
    stop: int | np.integer | None = None,
    step: int | np.integer | None = None,
    dtype: Dtype | None = None,
    copy: bool = False,
    name: Hashable | None = None,
) -> Self:
    cls._validate_dtype(dtype)
    name = maybe_extract_name(name, start, cls)

    # RangeIndex
    if isinstance(start, cls):
        return start.copy(name=name)
    elif isinstance(start, range):
        return cls._simple_new(start, name=name)

    # validate the arguments
    if com.all_none(start, stop, step):
        raise TypeError("RangeIndex(...) must be called with integers")

    start = ensure_python_int(start) if start is not None else 0  # type: ignore[arg-type]

    if stop is None:
        start, stop = 0, start
    else:
        stop = ensure_python_int(stop)

    step = ensure_python_int(step) if step is not None else 1
    if step == 0:
        raise ValueError("Step must not be zero")

    rng = range(start, stop, step)
    return cls._simple_new(rng, name=name)

def _validate_dtype(cls, dtype: Dtype | None) -> None:
    if dtype is None:
        return

    validation_func, expected = cls._dtype_validation_metadata
    if not validation_func(dtype):
        raise ValueError(
            f"Incorrect `dtype` passed: expected {expected}, received {dtype}"

def _shallow_copy(  # type: ignore[override]
    self, values: ArrayLike, name: Hashable = no_default
) -> Index:
    """
    Create a new RangeIndex with the same class as the caller, don't copy the
    data, use the same object attributes with passed in attributes taking
    precedence.

    *this is an internal non-public method*

    Parameters
    ----------
    values : the values to create the new RangeIndex, optional
    name : Label, defaults to self.name
    """
    name = self._name if name is no_default else name

    if values.dtype.kind == "f":
        return Index(values, name=name, dtype=np.float64, copy=False)
    if values.dtype.kind == "i" and values.ndim == 1:
        # GH 46675 & 43885: If values is equally spaced, return a
        # more memory-compact RangeIndex instead of Index with 64-bit dtype
        if len(values) == 1:
            start = values[0]
            new_range = range(start, start + self.step, self.step)
            return type(self)._simple_new(new_range, name=name)
        maybe_range = ibase.maybe_sequence_to_range(values)
        if isinstance(maybe_range, range):
            return type(self)._simple_new(maybe_range, name=name)
    return self._constructor._simple_new(values, name=name)

def _wrap_reindex_result(
    self, target: Index, indexer: npt.NDArray[np.intp] | None, preserve_names: bool
) -> Index:
    if not isinstance(target, type(self)) and target.dtype.kind == "i":
        target = self._shallow_copy(target._values, name=target.name)
    return super()._wrap_reindex_result(target, indexer, preserve_names)

def _minmax(self, meth: Literal["min", "max"]) -> int | float:
    no_steps = len(self) - 1
    if no_steps == -1:
        return np.nan
    elif (meth == "min" and self.step > 0) or (meth == "max" and self.step < 0):
        return self.start

    return self.start + self.step * no_steps

def _argminmax(
    self,
    meth: Literal["min", "max"],
    axis: AxisInt | None = None,
    skipna: bool = True,
) -> int:
    nv.validate_minmax_axis(axis)
    if len(self) == 0:
        return getattr(super(), f"arg{meth}")(
            axis=axis,
            skipna=skipna,
        )
    elif meth == "min":
        if self.step > 0:
            return 0
        else:
            return len(self) - 1
    elif meth == "max":
        if self.step > 0:
            return len(self) - 1
        else:
            return 0
    else:
        raise ValueError(f"{meth=} must be max or min")

def factorize(
    self,
    sort: bool = False,
    use_na_sentinel: bool = True,
) -> tuple[npt.NDArray[np.intp], RangeIndex]:
    if sort and self.step < 0:
        codes = np.arange(len(self) - 1, -1, -1, dtype=np.intp)
        uniques = self[::-1]
    else:
        codes = np.arange(len(self), dtype=np.intp)
        uniques = self
    return codes, uniques

def sort_values(
    self,
    *,
    return_indexer: bool = False,
    ascending: bool = True,
    na_position: NaPosition = "last",
    key: Callable | None = None,
) -> Self | tuple[Self, np.ndarray]:
    if key is not None:
        return super().sort_values(
            return_indexer=return_indexer,
            ascending=ascending,
            na_position=na_position,
            key=key,
        )
    else:
        sorted_index = self
        inverse_indexer = False
        if ascending:
            if self.step < 0:
                sorted_index = self[::-1]
                inverse_indexer = True
        elif self.step > 0:
            sorted_index = self[::-1]
            inverse_indexer = True

    if return_indexer:
        if inverse_indexer:
            indexer = np.arange(len(self) - 1, -1, -1, dtype=np.intp)
        else:
            indexer = np.arange(len(self), dtype=np.intp)
        return sorted_index, indexer
    else:
        return sorted_index

def _range_in_self(self, other: range) -> bool:
    """Check if other range is contained in self"""
    # https://stackoverflow.com/a/32481015
    if not other:
        return True
    if not self._range:
        return False
    if len(other) > 1 and other.step % self._range.step:
        return False
    return other.start in self._range and other[-1] in self._range

def _difference(self, other: Index, sort: bool | None = None) -> Index:
    # optimized set operation if we have another RangeIndex
    self._validate_sort_keyword(sort)
    self._assert_can_do_setop(other)
    other, result_name = self._convert_can_do_setop(other)

    if not isinstance(other, RangeIndex):
        return super()._difference(other, sort=sort)

    if sort is not False and self.step < 0:
        return self[::-1]._difference(other)

    res_name = ops.get_op_result_name(self, other)  # type: ignore[no-untyped-call]

    first = self._range[::-1] if self.step < 0 else self._range
    overlap = self.intersection(other)
    if overlap.step < 0:  # type: ignore[attr-defined]
        overlap = overlap[::-1]

    if len(overlap) == 0:
        return self.rename(name=res_name)
    if len(overlap) == len(self):
        return self[:0].rename(res_name)

    # overlap.step will always be a multiple of self.step (see _intersection)

    if len(overlap) == 1:
        if overlap[0] == self[0]:
            return self[1:]

        elif overlap[0] == self[-1]:
            return self[:-1]

        elif len(self) == 3 and overlap[0] == self[1]:
            return self[::2]

        else:
            return super()._difference(other, sort=sort)

    elif len(overlap) == 2 and overlap[0] == first[0] and overlap[-1] == first[-1]:
        # e.g. range(-8, 20, 7) and range(13, -9, -3)
        return self[1:-1]

    if overlap.step == first.step:  # type: ignore[attr-defined]
        if overlap[0] == first.start:
            # The difference is everything after the intersection
            new_rng = range(overlap[-1] + first.step, first.stop, first.step)
        elif overlap[-1] == first[-1]:
            # The difference is everything before the intersection
            new_rng = range(first.start, overlap[0], first.step)
        elif overlap._range == first[1:-1]:  # type: ignore[attr-defined]
            # e.g. range(4) and range(1, 3)
            step = len(first) - 1
            new_rng = first[::step]
        else:
            # The difference is not range-like
            # e.g. range(1, 10, 1) and range(3, 7, 1)
            return super()._difference(other, sort=sort)

    else:
        # We must have len(self) > 1, bc we ruled out above
        #  len(overlap) == 0 and len(overlap) == len(self)
        assert len(self) > 1

        if overlap.step == first.step * 2:  # type: ignore[attr-defined]
            if overlap[0] == first[0] and overlap[-1] in (first[-1], first[-2]):
                # e.g. range(1, 10, 1) and range(1, 10, 2)
                new_rng = first[1::2]

            elif overlap[0] == first[1] and overlap[-1] in (first[-1], first[-2]):
                # e.g. range(1, 10, 1) and range(2, 10, 2)
                new_rng = first[::2]

            else:
                # We can get here with  e.g. range(20) and range(0, 10, 2)
                return super()._difference(other, sort=sort)

        else:
            # e.g. range(10) and range(0, 10, 3)
            return super()._difference(other, sort=sort)

    if first is not self._range:
        new_rng = new_rng[::-1]
    new_index = type(self)._simple_new(new_rng, name=res_name)

    return new_index

def symmetric_difference(
    self, other: Axes, result_name: Hashable | None = None, sort: bool | None = None
) -> Index:
    if not isinstance(other, RangeIndex) or sort is not None:
        return super().symmetric_difference(other, result_name, sort)

    left = self.difference(other)
    right = other.difference(self)
    result = left.union(right)

    if isinstance(result, RangeIndex) and result.step < 0:
        result = result[::-1]

    if result_name is not None:
        result = result.rename(result_name)
    return result

def _join_empty(
    self, other: Index, how: JoinHow, sort: bool
) -> tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    if not isinstance(other, RangeIndex) and other.dtype.kind == "i":
        other = self._shallow_copy(other._values, name=other.name)
    return super()._join_empty(other, how=how, sort=sort)

def delete(  # type: ignore[override]
    self, loc: int | np.integer | list[int] | npt.NDArray[np.integer]
) -> Index:
    # In some cases we can retain RangeIndex, see also
    #  DatetimeTimedeltaMixin._get_delete_Freq
    if is_integer(loc):
        if loc in (0, -len(self)):
            return self[1:]
        if loc in (-1, len(self) - 1):
            return self[:-1]
        if len(self) == 3 and loc in (1, -2):
            return self[::2]

    elif lib.is_list_like(loc):
        slc = lib.maybe_indices_to_slice(np.asarray(loc, dtype=np.intp), len(self))

        if isinstance(slc, slice):
            # defer to RangeIndex._difference, which is optimized to return
            #  a RangeIndex whenever possible
            other = self[slc]
            return self.difference(other, sort=False)

    return super().delete(loc)

def insert(self, loc: int, item: Hashable) -> Index:
    if is_integer(item) or is_float(item):
        # We can retain RangeIndex is inserting at the beginning or end,
        #  or right in the middle.
        if len(self) == 0 and loc == 0 and is_integer(item):
            new_rng = range(item, item + self.step, self.step)
            return type(self)._simple_new(new_rng, name=self._name)
        elif len(self):
            rng = self._range
            if loc == 0 and item == self[0] - self.step:
                new_rng = range(rng.start - rng.step, rng.stop, rng.step)
                return type(self)._simple_new(new_rng, name=self._name)

            elif loc == len(self) and item == self[-1] + self.step:
                new_rng = range(rng.start, rng.stop + rng.step, rng.step)
                return type(self)._simple_new(new_rng, name=self._name)

            elif len(self) == 2 and item == self[0] + self.step / 2:
                # e.g. inserting 1 into [0, 2]
                step = int(self.step / 2)
                new_rng = range(self.start, self.stop, step)
                return type(self)._simple_new(new_rng, name=self._name)

    return super().insert(loc, item)

def __getitem__(self, key: Any) -> Any:
    """
    Conserve RangeIndex type for scalar and slice keys.
    """
    key = lib.item_from_zerodim(key)
    if key is Ellipsis:
        key = slice(None)
    if isinstance(key, slice):
        return self._getitem_slice(key)
    elif is_integer(key):
        new_key = int(key)
        try:
            return self._range[new_key]
        except IndexError as err:
            raise IndexError(
                f"index {key} is out of bounds for axis 0 with size {len(self)}"
            ) from err
    elif is_scalar(key):
        raise IndexError(
            "only integers, slices (`:`), "
            "ellipsis (`...`), numpy.newaxis (`None`) "
            "and integer or boolean "
            "arrays are valid indices"
        )
    elif com.is_bool_indexer(key):
        if isinstance(getattr(key, "dtype", None), ExtensionDtype):
            key = key.to_numpy(dtype=bool, na_value=False)
        else:
            key = np.asarray(key, dtype=bool)
        check_array_indexer(self._range, key)  # type: ignore[arg-type]
        key = np.flatnonzero(key)
    try:
        return self.take(key)
    except (TypeError, ValueError):
        return super().__getitem__(key)

def __floordiv__(self, other: object) -> Index:  # type: ignore[override]
    if is_integer(other) and other != 0:
        if len(self) == 0 or (self.start % other == 0 and self.step % other == 0):
            start = self.start // other
            step = self.step // other
            stop = start + len(self) * step
            new_range = range(start, stop, step or 1)
            return self._simple_new(new_range, name=self._name)
        if len(self) == 1:
            start = self.start // other
            new_range = range(start, start + 1, 1)
            return self._simple_new(new_range, name=self._name)

    return super().__floordiv__(other)

def __abs__(self) -> Self | Index:
    if len(self) == 0 or self.min() >= 0:
        return self.copy()
    elif self.max() <= 0:
        return -self
    else:
        return super().__abs__()

def take(  # type: ignore[override]
    self,
    indices: Sequence[int] | np.ndarray,
    axis: Axis = 0,
    allow_fill: bool | lib.NoDefault = no_default,
    fill_value: object = no_default,
    **kwargs: Any,
) -> Self | Index:
    if kwargs:
        nv.validate_take((), kwargs)
    if is_scalar(indices):
        raise TypeError("Expected indices to be array-like")
    indices = ensure_platform_int(indices)

    if allow_fill is no_default:
        if fill_value is None:
            # GH#65210: preserve pre-3.1 wrap behavior for this case, but
            # warn since the sentinel-based default would otherwise flip
            # it into fill-with-NA semantics.
            warnings.warn(
                "Passing fill_value=None without allow_fill previously "
                "used numpy-style wrapping of negative indices. In a "
                "future version this will trigger fill semantics "
                "(filling -1 entries with the dtype's NA value). Pass "
                "allow_fill=False to keep wrapping behavior, or "
                "allow_fill=True to opt into fill semantics.",
                Pandas4Warning,
                stacklevel=find_stack_level(),
            )
            allow_fill = False
        else:
            # Default: opt into fill semantics only if fill_value is
            # explicit.
            allow_fill = fill_value is not no_default

    if allow_fill:
        # RangeIndex can't hold NA natively; delegate to Index.take which
        # will promote dtype as needed.
        return super().take(
            indices, axis=axis, allow_fill=True, fill_value=fill_value
        )

    if len(indices) == 0:
        return type(self)(_empty_range, name=self.name)
    else:
        ind_max = indices.max()
        if ind_max >= len(self):
            raise IndexError(
                f"index {ind_max} is out of bounds for axis 0 with size {len(self)}"
            )
        ind_min = indices.min()
        if ind_min < -len(self):
            raise IndexError(
                f"index {ind_min} is out of bounds for axis 0 with size {len(self)}"
            )
        taken = indices.astype(self.dtype, casting="safe")
        if ind_min < 0:
            taken %= len(self)
        if self.step != 1:
            taken *= self.step
        if self.start != 0:
            taken += self.start

    return self._shallow_copy(taken, name=self.name)

def value_counts(
    self,
    normalize: bool = False,
    sort: bool = True,
    ascending: bool = False,
    bins: int | None = None,
    dropna: bool = True,
) -> Series:
    from pandas import Series

    if bins is not None:
        return super().value_counts(
            normalize=normalize,
            sort=sort,
            ascending=ascending,
            bins=bins,
            dropna=dropna,
        )
    name = "proportion" if normalize else "count"
    data: npt.NDArray[np.floating] | npt.NDArray[np.signedinteger] = np.ones(
        len(self), dtype=np.int64
    )
    if normalize:
        data = data / len(self)
    return Series(data, index=self.copy(), name=name)

def searchsorted(
    self,
    value: NumpyValueArrayLike | ExtensionArray,
    side: Literal["left", "right"] = "left",
    sorter: NumpySorter | None = None,
) -> npt.NDArray[np.intp] | np.intp:
    if side not in {"left", "right"} or sorter is not None:
        return super().searchsorted(value=value, side=side, sorter=sorter)

    was_scalar = False
    if is_scalar(value):
        was_scalar = True
        array_value = np.array([value])
    else:
        array_value = np.asarray(value)
    if array_value.dtype.kind not in "iu":
        return super().searchsorted(value=value, side=side, sorter=sorter)

    if flip := (self.step < 0):
        rng = self._range[::-1]
        start = rng.start
        step = rng.step
        shift = side == "right"
    else:
        start = self.start
        step = self.step
        shift = side == "left"
    result = (array_value - start - int(shift)) // step + 1
    if flip:
        result = len(self) - result
    result = np.maximum(np.minimum(result, len(self)), 0)
    if was_scalar:
        return maybe_unbox_numpy_scalar(np.intp(result.item()))
    return result.astype(np.intp, copy=False)

def _get_next_label(label):
    # see test_slice_locs_with_ints_and_floats_succeeds
    dtype = getattr(label, "dtype", type(label))
    if isinstance(label, (Timestamp, Timedelta)):
        dtype = "datetime64[ns]"
    dtype = pandas_dtype(dtype)

    if lib.is_np_dtype(dtype, "mM") or isinstance(dtype, DatetimeTZDtype):
        return label + np.timedelta64(1, "ns")
    elif is_integer_dtype(dtype):
        return label + 1
    elif is_float_dtype(dtype):
        return np.nextafter(label, np.inf)
    else:
        raise TypeError(f"cannot determine next label for type {type(label)!r}")

def _get_prev_label(label):
    # see test_slice_locs_with_ints_and_floats_succeeds
    dtype = getattr(label, "dtype", type(label))
    if isinstance(label, (Timestamp, Timedelta)):
        dtype = "datetime64[ns]"
    dtype = pandas_dtype(dtype)

    if lib.is_np_dtype(dtype, "mM") or isinstance(dtype, DatetimeTZDtype):
        return label - np.timedelta64(1, "ns")
    elif is_integer_dtype(dtype):
        return label - 1
    elif is_float_dtype(dtype):
        return np.nextafter(label, -np.inf)
    else:
        raise TypeError(f"cannot determine next label for type {type(label)!r}")

def _searchsorted_monotonic(self, label, side: Literal["left", "right"] = "left"):
    if not self.is_non_overlapping_monotonic:
        raise KeyError(
            "can only get slices from an IntervalIndex if bounds are "
            "non-overlapping and all monotonic increasing or decreasing"
        )

    if isinstance(label, (IntervalMixin, IntervalIndex)):
        raise NotImplementedError("Interval objects are not currently supported")

    # GH 20921: "not is_monotonic_increasing" for the second condition
    # instead of "is_monotonic_decreasing" to account for single element
    # indexes being both increasing and decreasing
    if (side == "left" and self.left.is_monotonic_increasing) or (
        side == "right" and not self.left.is_monotonic_increasing
    ):
        sub_idx = self.right
        if self.open_right:
            label = _get_next_label(label)
    else:
        sub_idx = self.left
        if self.open_left:
            label = _get_prev_label(label)

    return sub_idx._searchsorted_monotonic(label, side)

def _get_indexer(
    self,
    target: Index,
    method: str | None = None,
    limit: int | None = None,
    tolerance: Any | None = None,
) -> npt.NDArray[np.intp]:
    if isinstance(target, IntervalIndex):
        # We only get here with not self.is_overlapping
        # -> at most one match per interval in target
        # want exact matches -> need both left/right to match, so defer to
        # left/right get_indexer, compare elementwise, equality -> match
        if self.left.is_unique and self.right.is_unique:
            indexer = self._get_indexer_unique_sides(target)
        else:
            indexer = self._get_indexer_pointwise(target)[0]

    elif not (is_object_dtype(target.dtype) or is_string_dtype(target.dtype)):
        # homogeneous scalar index
        # we should always have self._should_partial_index(target) here
        if self.is_monotonic_increasing and self.right.is_monotonic_increasing:
            # GH#47614 - use searchsorted for O(n*log(m)) instead of
            # IntervalTree which scales poorly for large target arrays.
            # right is checked too: an empty interval can nest inside
            # another without overlapping it (GH#26893)
            indexer = self._get_indexer_monotonic(target)
        else:
            target = self._maybe_convert_i8(target)
            indexer = self._engine.get_indexer(cast("np.ndarray", target.values))
    else:
        # heterogeneous scalar index: defer elementwise to get_loc
        # we should always have self._should_partial_index(target) here
        return self._get_indexer_pointwise(target)[0]

    return ensure_platform_int(indexer)

def _get_indexer_pointwise(
    self, target: Index
) -> tuple[npt.NDArray[np.intp], npt.NDArray[np.intp]]:
    """
    pointwise implementation for get_indexer and get_indexer_non_unique.
    """
    indexer, missing = [], []
    for i, key in enumerate(target):
        try:
            locs = self.get_loc(key)
            if isinstance(locs, slice):
                # Only needed for get_indexer_non_unique
                locs = np.arange(locs.start, locs.stop, locs.step, dtype="intp")
            elif lib.is_integer(locs):
                locs = np.array(locs, ndmin=1)
            else:
                # otherwise we have ndarray[bool]
                locs = np.where(locs)[0]  # type: ignore[arg-type]
        except KeyError:
            missing.append(i)
            locs = np.array([-1])
        except InvalidIndexError:
            # i.e. non-scalar key e.g. a tuple.
            # see test_append_different_columns_types_raises
            missing.append(i)
            locs = np.array([-1])

        indexer.append(locs)

    concatenated_indexer = np.concatenate(indexer)
    return ensure_platform_int(concatenated_indexer), ensure_platform_int(missing)

def _convert_slice_indexer(self, key: slice, kind: Literal["loc", "getitem"]):
    if not (key.step is None or key.step == 1):
        # GH#31658 if label-based, we require step == 1,
        #  if positional, we disallow float start/stop
        msg = "label-based slicing with step!=1 is not supported for IntervalIndex"
        if kind == "loc":
            raise ValueError(msg)
        if kind == "getitem":
            if not is_valid_positional_slice(key):
                # i.e. this cannot be interpreted as a positional slice
                raise ValueError(msg)

    return super()._convert_slice_indexer(key, kind)

def _lexsort_depth(codes: list[np.ndarray], nlevels: int) -> int:
    """Count depth (up to a maximum of `nlevels`) with which codes are lexsorted."""
    int64_codes = [ensure_int64(level_codes) for level_codes in codes]
    for k in range(nlevels, 0, -1):
        if libalgos.is_lexsorted(int64_codes[:k]):
            return k
    return 0

def sparsify_labels(label_list, start: int = 0, sentinel: object = ""):
    pivoted = list(zip(*label_list, strict=True))
    k = len(label_list)

    result = pivoted[: start + 1]
    prev = pivoted[start]

    for cur in pivoted[start + 1 :]:
        sparse_cur = []

        for i, (p, t) in enumerate(zip(prev, cur, strict=True)):
            if i == k - 1:
                sparse_cur.append(t)
                result.append(sparse_cur)  # type: ignore[arg-type]
                break

            if p == t:
                sparse_cur.append(sentinel)
            else:
                sparse_cur.extend(cur[i:])
                result.append(sparse_cur)  # type: ignore[arg-type]
                break

        prev = cur

    return list(zip(*result, strict=True))

def _require_listlike(level, arr, arrname: str):
    """
    Ensure that level is either None or listlike, and arr is list-of-listlike.
    """
    if level is not None and not is_list_like(level):
        if not is_list_like(arr):
            raise TypeError(f"{arrname} must be list-like")
        if len(arr) > 0 and is_list_like(arr[0]):
            raise TypeError(f"{arrname} must be list-like, not a list of list-likes")
        level = [level]
        arr = [arr]
    elif level is None or is_list_like(level):
        if not is_list_like(arr) or (len(arr) > 0 and not is_list_like(arr[0])):
            raise TypeError(f"{arrname} must be list of lists-like")
    return level, arr

def _set_levels(
    self,
    levels,
    *,
    level=None,
    copy: bool = False,
    validate: bool = True,
    verify_integrity: bool = False,
) -> None:
    # This is NOT part of the levels property because it should be
    # externally not allowed to set levels. User beware if you change
    # _levels directly
    if validate:
        if len(levels) == 0:
            raise ValueError("Must set non-zero number of levels.")
        if level is None and len(levels) != self.nlevels:
            raise ValueError("Length of levels must match number of levels.")
        if level is not None and len(levels) != len(level):
            raise ValueError("Length of levels must match length of level.")

    if level is None:
        new_levels = FrozenList(
            ensure_index(lev, copy=copy)._view() for lev in levels
        )
        level_numbers: range | list[int] = range(len(new_levels))
    else:
        level_numbers = [self._get_level_number(lev) for lev in level]
        new_levels_list = list(self._levels)
        for lev_num, lev in zip(level_numbers, levels, strict=True):
            new_levels_list[lev_num] = ensure_index(lev, copy=copy)._view()
        new_levels = FrozenList(new_levels_list)

    if verify_integrity:
        new_codes = self._verify_integrity(
            levels=new_levels, levels_to_verify=level_numbers
        )
        self._codes = new_codes

    names = self.names
    self._levels = new_levels
    if any(names):
        self._set_names(names)

    self._reset_cache()

def _set_codes(
    self,
    codes,
    *,
    level=None,
    copy: bool = False,
    validate: bool = True,
    verify_integrity: bool = False,
) -> None:
    if validate:
        if level is None and len(codes) != self.nlevels:
            raise ValueError("Length of codes must match number of levels")
        if level is not None and len(codes) != len(level):
            raise ValueError("Length of codes must match length of levels.")

    level_numbers: list[int] | range
    if level is None:
        new_codes = FrozenList(
            _coerce_indexer_frozen(level_codes, lev, copy=copy).view()
            for lev, level_codes in zip(self._levels, codes, strict=True)
        )
        level_numbers = range(len(new_codes))
    else:
        level_numbers = [self._get_level_number(lev) for lev in level]
        new_codes_list = list(self._codes)
        for lev_num, level_codes in zip(level_numbers, codes, strict=True):
            lev = self.levels[lev_num]
            new_codes_list[lev_num] = _coerce_indexer_frozen(
                level_codes, lev, copy=copy
            )
        new_codes = FrozenList(new_codes_list)

    if verify_integrity:
        new_codes = self._verify_integrity(
            codes=new_codes, levels_to_verify=level_numbers
        )

    self._codes = new_codes

    self._reset_cache()

def _engine(self):
    # Calculate the number of bits needed to represent labels in each
    # level, as log2 of their sizes:
    # NaN values are shifted to 1 and missing values in other while
    # calculating the indexer are shifted to 0
    sizes = np.ceil(
        np.log2(
            [len(level) + libindex.multiindex_nulls_shift for level in self.levels]
        )
    )

    # Sum bit counts, starting from the _right_....
    lev_bits = np.cumsum(sizes[::-1])[::-1]

    # ... in order to obtain offsets such that sorting the combination of
    # shifted codes (one for each level, resulting in a unique integer) is
    # equivalent to sorting lexicographically the codes themselves. Notice
    # that each level needs to be shifted by the number of bits needed to
    # represent the _previous_ ones:
    offsets = np.concatenate([lev_bits[1:], [0]])
    # Downcast the type if possible, to prevent upcasting when shifting codes:
    offsets = offsets.astype(np.min_scalar_type(int(offsets[0])))

    # Check the total number of bits needed for our representation:
    if lev_bits[0] > 64:
        # The levels would overflow a 64 bit uint - use Python integers:
        return MultiIndexPyIntEngine(self.levels, self.codes, offsets)
    if lev_bits[0] > 32:
        # The levels would overflow a 32 bit uint - use uint64
        return MultiIndexUInt64Engine(self.levels, self.codes, offsets)
    if lev_bits[0] > 16:
        # The levels would overflow a 16 bit uint - use uint8
        return MultiIndexUInt32Engine(self.levels, self.codes, offsets)
    if lev_bits[0] > 8:
        # The levels would overflow an 8 bit uint - use uint16
        return MultiIndexUInt16Engine(self.levels, self.codes, offsets)
    # The levels fit in an 8 bit uint - use uint8
    return MultiIndexUInt8Engine(self.levels, self.codes, offsets)

def __array__(self, dtype=None, copy=None) -> np.ndarray:
    """the array interface, return my values"""
    if copy is False:
        # self.values is always a newly construct array, so raise.
        raise ValueError(
            "Unable to avoid copy while creating an array as requested."
        )
    if copy is True:
        # explicit np.array call to ensure a copy is made and unique objects
        # are returned, because self.values is cached
        return np.array(self.values, dtype=dtype)
    return self.values

def _format_multi(
    self,
    *,
    include_names: bool,
    sparsify: bool | lib.NoDefault | None,
    formatter: Callable | None = None,
) -> list:
    if len(self) == 0:
        return []

    from pandas.io.formats.format import format_name

    stringified_levels = []
    for lev, level_codes in zip(self.levels, self.codes, strict=True):
        na = _get_na_rep(lev.dtype)

        if len(lev) > 0:
            taken = formatted = lev.take(level_codes)
            formatted = taken._format_flat(include_name=False, formatter=formatter)

            # we have some NA
            mask = level_codes == -1
            if mask.any():
                formatted = np.array(formatted, dtype=object)
                formatted[mask] = na
                formatted = formatted.tolist()

        else:
            # weird all NA case
            formatted = [
                pprint_thing(na if isna(x) else x, escape_chars=("\t", "\r", "\n"))
                for x in algos.take_nd(lev._values, level_codes)
            ]
        stringified_levels.append(formatted)

    result_levels = []
    for lev, lev_name in zip(stringified_levels, self.names, strict=True):
        level = []

        if include_names:
            level.append(format_name(lev_name))

        level.extend(np.array(lev, dtype=object))
        result_levels.append(level)

    if sparsify is None:
        sparsify = config["display"]["multi_sparse"]

    if sparsify:
        sentinel: Literal[""] | bool | lib.NoDefault = ""
        # GH3547 use value of sparsify as sentinel if it's "Falsey"
        assert isinstance(sparsify, bool) or sparsify is lib.no_default
        if sparsify is lib.no_default:
            sentinel = sparsify
        # little bit of a kludge job for #1217
        result_levels = sparsify_labels(
            result_levels, start=int(include_names), sentinel=sentinel
        )

    return result_levels

def _get_level_number(self, level) -> int:
    count = self.names.count(level)
    if (count > 1) and not is_integer(level):
        raise ValueError(
            f"The name {level} occurs multiple times, use a level number"
        )
    try:
        level = self.names.index(level)
    except ValueError as err:
        if not is_integer(level):
            raise KeyError(f"Level {level} not found") from err
        if level < 0:
            level += self.nlevels
            if level < 0:
                orig_level = level - self.nlevels
                raise IndexError(
                    f"Too many levels: Index has only {self.nlevels} levels, "
                    f"{orig_level} is not a valid level number"
                ) from err
        # Note: levels are zero-based
        elif level >= self.nlevels:
            raise IndexError(
                f"Too many levels: Index has only {self.nlevels} levels, "
                f"not {level + 1}"
            ) from err
    return level

def __getitem__(self, key):
    key = lib.item_from_zerodim(key)
    if is_scalar(key):
        key = com.cast_scalar_indexer(key)

        retval = []
        for lev, level_codes in zip(self.levels, self.codes, strict=True):
            if level_codes[key] == -1:
                retval.append(np.nan)
            else:
                retval.append(lev[level_codes[key]])

        return tuple(retval)
    else:
        # in general cannot be sure whether the result will be sorted
        sortorder = None
        if com.is_bool_indexer(key):
            key = np.asarray(key, dtype=bool)
            sortorder = self.sortorder
        elif isinstance(key, slice):
            if key.step is None or key.step > 0:
                sortorder = self.sortorder
        elif isinstance(key, Index):
            key = np.asarray(key)

        new_codes = [level_codes[key] for level_codes in self.codes]

        return MultiIndex(
            levels=self.levels,
            codes=new_codes,
            names=self.names,
            sortorder=sortorder,
            verify_integrity=False,

def _reorder_ilevels(self, order) -> MultiIndex:
    if len(order) != self.nlevels:
        raise AssertionError(
            f"Length of order must be same as number of levels ({self.nlevels}), "
            f"got {len(order)}"
        )
    new_levels = [self.levels[i] for i in order]
    new_codes = [self.codes[i] for i in order]
    new_names = [self.names[i] for i in order]

    return MultiIndex(
        levels=new_levels, codes=new_codes, names=new_names, verify_integrity=False

def _recode_for_new_levels(
    self, new_levels, *, copy: bool
) -> Generator[np.ndarray]:
    if len(new_levels) > self.nlevels:
        raise AssertionError(
            f"Length of new_levels ({len(new_levels)}) "
            f"must be <= self.nlevels ({self.nlevels})"
        )
    for i in range(len(new_levels)):
        yield recode_for_categories(
            self.codes[i], self.levels[i], new_levels[i], copy=copy

def _wrap_reindex_result(self, target, indexer, preserve_names: bool):
    if not isinstance(target, MultiIndex):
        if indexer is None:
            target = self
        elif (indexer >= 0).all():
            target = self.take(indexer)
        else:
            try:
                target = MultiIndex.from_tuples(target)
            except (TypeError, ValueError):
                # not all tuples, see test_constructor_dict_multiindex_reindex_flat
                # ValueError: non-object target dtype (e.g. int), so the
                #  entries can't be tuples (GH#26460)
                return target

    target = self._maybe_preserve_names(target, preserve_names)
    return target

def _maybe_preserve_names(self, target: IndexT, preserve_names: bool) -> IndexT:
    if (
        preserve_names
        and target.nlevels == self.nlevels
        and target.names != self.names
    ):
        target = target.copy(deep=False)
        target.names = self.names
    return target

def _get_indexer_strict(
    self, key, axis_name: str
) -> tuple[Index, npt.NDArray[np.intp]]:
    keyarr = key
    if not isinstance(keyarr, Index):
        keyarr = com.asarray_tuplesafe(keyarr)

    if len(keyarr) and not isinstance(keyarr[0], tuple):
        indexer = self._get_indexer_level_0(keyarr)

        self._raise_if_missing(key, indexer, axis_name)
        return self[indexer], indexer

    return super()._get_indexer_strict(key, axis_name)

def _raise_if_missing(self, key, indexer, axis_name: str) -> None:
    keyarr = key
    if not isinstance(key, Index):
        keyarr = com.asarray_tuplesafe(key)

    if len(keyarr) and not isinstance(keyarr[0], tuple):
        # i.e. same condition for special case in MultiIndex._get_indexer_strict

        mask = indexer == -1
        if mask.any():
            check = self.levels[0].get_indexer(keyarr)
            cmask = check == -1
            if cmask.any():
                raise KeyError(f"{keyarr[cmask]} not in index")
            # We get here when levels still contain values which are not
            # actually in Index anymore
            raise KeyError(f"{keyarr} not in index")
    else:
        return super()._raise_if_missing(key, indexer, axis_name)

def _partial_tup_index(self, tup: tuple, side: Literal["left", "right"] = "left"):
    if len(tup) > self.nlevels:
        # GH#45762 no amount of sorting brings a key this deep into range,
        #  so the lexsort complaint below would be blaming the wrong thing
        _raise_key_length_error(len(tup), self.nlevels)
    if len(tup) > self._lexsort_depth:
        raise UnsortedIndexError(
            f"Key length ({len(tup)}) was greater than MultiIndex lexsort depth "
            f"({self._lexsort_depth})"
        )

    n = len(tup)
    start, end = 0, len(self)
    zipped = zip(tup, self.levels, self.codes, strict=True)
    for k, (lab, lev, level_codes) in enumerate(zipped):
        section = level_codes[start:end]

        loc: npt.NDArray[np.intp] | np.intp | int
        if lab not in lev and not isna(lab):
            # short circuit
            if isinstance(lab, str) and is_numeric_dtype(lev.dtype):
                # GH#60104 - numpy searchsorted gives wrong results for
                # string vs numeric comparisons; raise early
                raise TypeError(f"Level type mismatch: {lab}")
            try:
                loc = algos.searchsorted(lev, lab, side=side)
            except TypeError as err:
                # non-comparable e.g. test_slice_locs_with_type_mismatch
                raise TypeError(f"Level type mismatch: {lab}") from err
            if not is_integer(loc):
                # non-comparable level, e.g. test_groupby_example
                raise TypeError(f"Level type mismatch: {lab}")
            if side == "right" and loc >= 0:
                loc -= 1
            return start + algos.searchsorted(section, loc, side=side)

        idx = self._get_loc_single_level_index(lev, lab)
        if isinstance(idx, slice) and k < n - 1:
            # Get start and end value from slice, necessary when a non-integer
            # interval is given as input GH#37707
            start = idx.start
            end = idx.stop
        elif k < n - 1:
            # error: Incompatible types in assignment (expression has type
            # "Union[ndarray[Any, dtype[signedinteger[Any]]]
            end = start + algos.searchsorted(  # type: ignore[assignment]
                section, idx, side="right"
            )
            # error: Incompatible types in assignment (expression has type
            # "Union[ndarray[Any, dtype[signedinteger[Any]]]
            start = start + algos.searchsorted(  # type: ignore[assignment]
                section, idx, side="left"
            )
        elif isinstance(idx, slice):
            idx = idx.start
            return start + algos.searchsorted(section, idx, side=side)
        else:
            return start + algos.searchsorted(section, idx, side=side)

def equals(self, other: object) -> bool:
    """
    Determines if two MultiIndex objects have the same labeling information
    (the levels themselves do not necessarily have to be the same)

    See Also
    --------
    equal_levels
    """
    if self.is_(other):  # type: ignore[arg-type]
        return True

    if not isinstance(other, Index):
        return False

    if len(self) != len(other):
        return False

    if not isinstance(other, MultiIndex):
        # d-level MultiIndex can equal d-tuple Index
        if not self._should_compare(other):
            # object Index or Categorical[object] may contain tuples
            return False
        return array_equivalent(self._values, other._values)

    if self.nlevels != other.nlevels:
        return False

    for i in range(self.nlevels):
        self_codes = self.codes[i]
        other_codes = other.codes[i]
        self_mask = self_codes == -1
        other_mask = other_codes == -1
        if not lib.array_equivalent_bytes(self_mask, other_mask):
            return False
        self_level = self.levels[i]
        other_level = other.levels[i]
        new_codes = recode_for_categories(
            other_codes, other_level, self_level, copy=False
        )
        if not array_equivalent(self_codes, new_codes):
            return False
        if not self_level[:0].equals(other_level[:0]):
            # e.g. Int64 != int64
            return False
    return True

def equal_levels(self, other: MultiIndex) -> bool:
    """
    Return True if the levels of both MultiIndex objects are the same

    """
    if self.nlevels != other.nlevels:
        return False

    for i in range(self.nlevels):
        if not self.levels[i].equals(other.levels[i]):
            return False
    return True

def _union(self, other, sort) -> MultiIndex:
    other, result_names = self._convert_can_do_setop(other)
    if other.has_duplicates:
        # This is only necessary if other has dupes,
        # otherwise difference is faster
        result = super(MultiIndex, self.rename(result_names))._union(
            other.rename(result_names), sort
        )

        if isinstance(result, MultiIndex):
            return result
        return MultiIndex.from_arrays(
            zip(*result, strict=True), sortorder=None, names=result_names
        )

    else:
        right_missing = other.difference(self, sort=False)
        if len(right_missing):
            result = self.append(right_missing)
        else:
            result = self._get_reconciled_name_object(other)

        if sort is not False:
            try:
                result = result.sort_values()
            except TypeError:
                if sort is True:
                    raise
                warnings.warn(
                    "The values in the array are unorderable. "
                    "Pass `sort=False` to suppress this warning.",
                    RuntimeWarning,
                    stacklevel=find_stack_level(),
                )
        return result

def _maybe_match_names(self, other):
    """
    Try to find common names to attach to the result of an operation between
    a and b. Return a consensus list of names if they match at least partly
    or list of None if they have completely different names.
    """
    if len(self.names) != len(other.names):
        return [None] * len(self.names)
    names = []
    for a_name, b_name in zip(self.names, other.names, strict=True):
        if a_name == b_name:
            names.append(a_name)
        else:
            # TODO: what if they both have np.nan for their names?
            names.append(None)
    return names

def _convert_can_do_setop(self, other):
    result_names = self.names

    if not isinstance(other, Index):
        if len(other) == 0:
            return self[:0], self.names
        else:
            msg = "other must be a MultiIndex or a list of tuples"
            try:
                other = MultiIndex.from_tuples(other, names=self.names)
            except (ValueError, TypeError) as err:
                # ValueError raised by tuples_to_object_array if we
                #  have non-object dtype
                raise TypeError(msg) from err
    else:
        result_names = get_unanimous_names(self, other)

    return other, result_names

def _validate_fill_value(self, item):
    if isinstance(item, MultiIndex):
        # GH#43212
        if item.nlevels != self.nlevels:
            raise ValueError("Item must have length equal to number of levels.")
        return item._values
    elif not isinstance(item, tuple):
        # Pad the key with empty strings if lower levels of the key
        # aren't specified:
        item = (item,) + ("",) * (self.nlevels - 1)
    elif len(item) != self.nlevels:
        raise ValueError("Item must have length equal to number of levels.")
    return item

def _get_values(self):
    data = self._parent
    if lib.is_np_dtype(data.dtype, "M"):
        return DatetimeIndex(data, copy=False, name=self.name)

    elif isinstance(data.dtype, DatetimeTZDtype):
        return DatetimeIndex(data, copy=False, name=self.name)

    elif lib.is_np_dtype(data.dtype, "m"):
        return TimedeltaIndex(data, copy=False, name=self.name)

    elif isinstance(data.dtype, PeriodDtype):
        return PeriodArray(data, copy=False)

    raise TypeError(
        f"cannot convert an object of type {type(data)} to a datetimelike index"

def _delegate_property_get(self, name: str):
    from pandas import Series

    values = self._get_values()

    result = getattr(values, name)

    # maybe need to upcast (ints)
    if isinstance(result, np.ndarray):
        if is_integer_dtype(result):
            result = result.astype("int64")
    elif not is_list_like(result):
        return result

    result = np.asarray(result)

    if self.orig is not None:
        index = self.orig.index
    else:
        index = self._parent.index
    # return the result as a Series
    return Series(result, index=index, name=self.name).__finalize__(self._parent)

def _delegate_property_get(self, name: str):
    if not hasattr(self._parent.array, f"_dt_{name}"):
        raise NotImplementedError(
            f"dt.{name} is not supported for {self._parent.dtype}"
        )
    result = getattr(self._parent.array, f"_dt_{name}")

    if not is_list_like(result):
        return result

    if self._orig is not None:
        index = self._orig.index
    else:
        index = self._parent.index
    # return the result as a Series, which is by definition a copy
    result = type(self._parent)(
        result, index=index, name=self._parent.name
    ).__finalize__(self._parent)

    return result

def _delegate_method(self, name: str, *args, **kwargs):
    if not hasattr(self._parent.array, f"_dt_{name}"):
        raise NotImplementedError(
            f"dt.{name} is not supported for {self._parent.dtype}"
        )

    result = getattr(self._parent.array, f"_dt_{name}")(*args, **kwargs)

    if self._orig is not None:
        index = self._orig.index
    else:
        index = self._parent.index
    # return the result as a Series, which is by definition a copy
    result = type(self._parent)(
        result, index=index, name=self._parent.name
    ).__finalize__(self._parent)

    return result

def __new__(cls, data: Series):  # pyright: ignore[reportInconsistentConstructor]
    # CombinedDatetimelikeProperties isn't really instantiated. Instead
    # we need to choose which parent (datetime or timedelta) is
    # appropriate. Since we're checking the dtypes anyway, we'll just
    # do all the validation here.

    if not isinstance(data, ABCSeries):
        raise TypeError(
            f"cannot convert an object of type {type(data)} to a datetimelike index"
        )

    orig = data if isinstance(data.dtype, CategoricalDtype) else None
    if orig is not None:
        data = data._constructor(
            orig.array,
            name=orig.name,
            copy=False,
            dtype=orig._values.categories.dtype,
            index=orig.index,
        )

    if isinstance(data.dtype, ArrowDtype) and data.dtype.kind in "Mm":
        return ArrowTemporalProperties(data, orig)
    if lib.is_np_dtype(data.dtype, "M"):
        return DatetimeProperties(data, orig)
    elif isinstance(data.dtype, DatetimeTZDtype):
        return DatetimeProperties(data, orig)
    elif lib.is_np_dtype(data.dtype, "m"):
        return TimedeltaProperties(data, orig)
    elif isinstance(data.dtype, PeriodDtype):
        return PeriodProperties(data, orig)

    raise AttributeError("Can only use .dt accessor with datetimelike values")

def safe_sort_index(index: Index) -> Index:
    """
    Returns the sorted index

    We keep the dtypes and the name attributes.

    Parameters
    ----------
    index : an Index

    Returns
    -------
    Index
    """
    if index.is_monotonic_increasing:
        return index

    try:
        array_sorted = safe_sort(index)
    except TypeError:
        pass
    else:
        if isinstance(array_sorted, Index):
            return array_sorted

        array_sorted = cast("np.ndarray", array_sorted)
        if isinstance(index, MultiIndex):
            index = MultiIndex.from_tuples(array_sorted, names=index.names)
        else:
            index = Index(array_sorted, name=index.name, dtype=index.dtype)

    return index

def _sanitize_and_check(indexes):
    """
    Verify the type of indexes and convert lists to Index.

    Cases:

    - [list, list, ...]: Return ([list, list, ...], 'list')
    - [list, Index, ...]: Return _sanitize_and_check([Index, Index, ...])
        Lists are sorted and converted to Index.
    - [Index, Index, ...]: Return ([Index, Index, ...], TYPE)
        TYPE = 'special' if at least one special type, 'array' otherwise.

    Parameters
    ----------
    indexes : list of Index or list objects

    Returns
    -------
    sanitized_indexes : list of Index or list objects
    type : {'list', 'array', 'special'}
    """
    kinds = {type(index) for index in indexes}

    if list in kinds:
        if len(kinds) > 1:
            indexes = [
                Index(list(x)) if not isinstance(x, Index) else x for x in indexes
            ]
            kinds -= {list}
        else:
            return indexes, "list"

    if len(kinds) > 1 or Index not in kinds:
        return indexes, "special"
    else:
        return indexes, "array"

def __new__(
    cls,
    data=None,
    freq=None,
    dtype: Dtype | None = None,
    copy: bool | None = None,
    name: Hashable | None = None,
) -> Self:
    refs = None
    if not copy and isinstance(data, (Index, ABCSeries)):
        refs = data._references
    if dtype is not None:
        dtype = pandas_dtype(dtype)

    name = maybe_extract_name(name, data, cls)

    if freq is not None:
        freq = to_offset(freq, is_period=True)
    dtype2 = PeriodDtype(freq) if freq is not None else None
    dtype = validate_dtype_freq(dtype, dtype2)
    if dtype is not None:
        freq = dtype._freq

    # GH#63388
    data, copy = cls._maybe_copy_array_input(data, copy, dtype)

    data = period_array(data=data, dtype=dtype)

    if copy:
        data = data.copy()

    return cls._simple_new(data, name=name, refs=refs)

def asof_locs(self, where: Index, mask: npt.NDArray[np.bool_]) -> np.ndarray:
    """
    where : array of timestamps
    mask : np.ndarray[bool]
        Array of booleans where data is not NA.
    """
    if isinstance(where, DatetimeIndex):
        where = PeriodIndex(where._values, freq=self.freq, copy=False)
    elif not isinstance(where, PeriodIndex):
        raise TypeError("asof_locs `where` must be DatetimeIndex or PeriodIndex")

    return super().asof_locs(where, mask)

def get_loc(self, key):
    """
    Get integer location for requested label.

    Parameters
    ----------
    key : Period, NaT, str, or datetime
        String or datetime key must be parsable as Period.

    Returns
    -------
    loc : int or ndarray[int64]

    Raises
    ------
    KeyError
        Key is not present in the index.
    TypeError
        If key is listlike or otherwise not hashable.
    """
    orig_key = key

    self._check_indexing_error(key)

    if is_valid_na_for_dtype(key, self.dtype):
        key = NaT

    elif isinstance(key, str):
        try:
            parsed, reso = self._parse_with_reso(key)
        except ValueError as err:
            # A string with invalid format
            raise KeyError(f"Cannot interpret '{key}' as period") from err

        if self._can_partial_date_slice(reso):
            try:
                return self._partial_date_slice(reso, parsed)
            except KeyError as err:
                raise KeyError(key) from err

        if reso == self._resolution_obj:
            # the reso < self._resolution_obj case goes
            #  through _get_string_slice
            key = self._cast_partial_indexing_scalar(parsed)
        else:
            raise KeyError(key)

    elif isinstance(key, Period):
        self._disallow_mismatched_indexing(key)

    elif isinstance(key, datetime):
        key = self._cast_partial_indexing_scalar(key)

    else:
        # in particular integer, which Period constructor would cast to string
        raise KeyError(key)

    try:
        return Index.get_loc(self, key)
    except KeyError as err:
        raise KeyError(orig_key) from err

def maybe_sequence_to_range(sequence: Axes) -> Axes:
    """
    Convert a 1D, non-pandas sequence to a range if possible.

    Returns the input if not possible.

    Parameters
    ----------
    sequence : 1D sequence

    Returns
    -------
    Any : input or range
    """
    if isinstance(sequence, (range, ExtensionArray)):
        return sequence
    elif len(sequence) == 1 or lib.infer_dtype(sequence, skipna=False) != "integer":
        return sequence
    elif isinstance(sequence, (ABCSeries, Index)) and not (
        isinstance(sequence.dtype, np.dtype) and sequence.dtype.kind == "i"
    ):
        return sequence
    if len(sequence) == 0:
        return range(0)
    try:
        np_sequence = np.asarray(sequence, dtype=np.int64)
    except OverflowError:
        return sequence
    if (
        isinstance(sequence, np.ndarray)
        and sequence.dtype.kind == "u"
        and (np_sequence < 0).any()
    ):
        # GH#64148: uint64 values above INT64_MAX wrapped negative in the cast
        return sequence
    # GH#64148: use python ints so widely-separated values (e.g. INT64_MIN and
    # INT64_MAX) don't overflow the int64 domain RangeIndex relies on.
    first = int(np_sequence[0])
    diff = int(np_sequence[1]) - first
    if diff == 0 or not -(2**63) <= diff < 2**63:
        return sequence
    if len(sequence) != 2 and not lib.is_sequence_range(np_sequence, diff):
        return sequence
    stop = int(np_sequence[-1]) + diff
    if not -(2**63) <= stop < 2**63:
        return sequence
    # is_sequence_range matches modularly, so a sequence that wraps past
    # INT64_MAX can slip through; such a match has the wrong length.
    candidate = range(first, stop, diff)
    if len(candidate) == len(sequence):
        return candidate
    return sequence

def ensure_index(index_like: Axes, copy: bool = False) -> Index:
    """
    Ensure that we have an index from some index-like object.

    Parameters
    ----------
    index_like : sequence
        An Index or other sequence
    copy : bool, default False

    Returns
    -------
    index : Index or MultiIndex

    See Also
    --------
    ensure_index_from_sequences

    Examples
    --------
    >>> ensure_index(["a", "b"])
    Index(['a', 'b'], dtype='str')

    >>> ensure_index([("a", "a"), ("b", "c")])
    Index([('a', 'a'), ('b', 'c')], dtype='object')

    >>> ensure_index([["a", "a"], ["b", "c"]])
    MultiIndex([('a', 'b'),
            ('a', 'c')],
           )
    """
    if isinstance(index_like, Index):
        if copy:
            index_like = index_like.copy()
        return index_like

    if isinstance(index_like, ABCSeries):
        name = index_like.name
        return Index(index_like, name=name, copy=copy)

    if is_iterator(index_like):
        index_like = list(index_like)

    if isinstance(index_like, list):
        if type(index_like) is not list:
            # must check for exactly list here because of strict type
            # check in clean_index_list
            index_like = list(index_like)

        if index_like and lib.is_all_arraylike(index_like):
            from pandas.core.indexes.multi import MultiIndex

            return MultiIndex.from_arrays(index_like)
        else:
            return Index(index_like, copy=copy, tupleize_cols=False)
    else:
        return Index(index_like, copy=copy)

def _maybe_try_sort(result: Index | ArrayLike, sort: bool | None) -> Index | ArrayLike:
    if sort is not False:
        try:
            # error: Incompatible types in assignment (expression has type
            # "Union[ExtensionArray, ndarray[Any, Any], Index, Series,
            # Tuple[Union[Union[ExtensionArray, ndarray[Any, Any]], Index, Series],
            # ndarray[Any, Any]]]", variable has type "Union[Index,
            # Union[ExtensionArray, ndarray[Any, Any]]]")
            result = algos.safe_sort(result)  # type: ignore[assignment]
        except TypeError as err:
            if sort is True:
                raise
            warnings.warn(
                f"{err}, sort order is undefined for incomparable objects.",
                RuntimeWarning,
                stacklevel=find_stack_level(),
            )
    return result

def _dtype_to_subclass(cls, dtype: DtypeObj) -> type[Index]:
    # Delay import for perf. https://github.com/pandas-dev/pandas/pull/31423

    if isinstance(dtype, ExtensionDtype):
        return dtype.index_class

    if dtype.kind == "M":
        from pandas import DatetimeIndex

        return DatetimeIndex

    elif dtype.kind == "m":
        from pandas import TimedeltaIndex

        return TimedeltaIndex

    elif dtype.kind == "O":
        # NB: assuming away MultiIndex
        return Index

    elif issubclass(dtype.type, str) or is_numeric_dtype(dtype):
        return Index

    raise NotImplementedError(dtype)

def _engine(
    self,
) -> libindex.IndexEngine | libindex.ExtensionEngine | libindex.MaskedIndexEngine:
    # For base class (object dtype) we get ObjectEngine
    dtype = self.dtype
    target_values = self._get_engine_target()

    if isinstance(dtype, ArrowDtype) and dtype.kind in "Mm":
        import pyarrow as pa

        values = self._values
        pa_type = values._pa_array.type  # type: ignore[union-attr]
        if pa.types.is_timestamp(pa_type):
            target_values = values._to_datetimearray()  # type: ignore[union-attr]
            return libindex.DatetimeEngine(target_values._ndarray)
        elif pa.types.is_duration(pa_type):
            target_values = values._to_timedeltaarray()  # type: ignore[union-attr]
            return libindex.TimedeltaEngine(target_values._ndarray)

    if isinstance(target_values, ExtensionArray):
        if isinstance(target_values, (BaseMaskedArray, ArrowExtensionArray)):
            try:
                return _masked_engines[target_values.dtype.name](target_values)
            except KeyError:
                # Not supported yet e.g. decimal
                pass
        elif self._engine_type is libindex.ObjectEngine:
            return libindex.ExtensionEngine(target_values)

    # to avoid a reference cycle, bind `target_values` to a local variable, so
    # `self` is not passed into the lambda.
    if target_values.dtype == bool:
        return libindex.BoolEngine(target_values)  # type: ignore[arg-type]
    elif target_values.dtype == np.complex64:
        return libindex.Complex64Engine(target_values)  # type: ignore[arg-type]
    elif target_values.dtype == np.complex128:
        return libindex.Complex128Engine(target_values)  # type: ignore[arg-type]
    elif needs_i8_conversion(dtype):
        # We need to keep M8/m8 dtype when initializing the Engine,
        #  but don't want to change _get_engine_target bc it is used
        #  elsewhere
        # error: Item "ExtensionArray" of "Union[ExtensionArray,
        # ndarray[Any, Any]]" has no attribute "_ndarray"  [union-attr]
        target_values = self._data._ndarray  # type: ignore[union-attr]
    elif isinstance(dtype, StringDtype):
        return libindex.StringObjectEngine(target_values, dtype.na_value)

    # error: Argument 1 to "ExtensionEngine" has incompatible type
    # "ndarray[Any, Any]"; expected "ExtensionArray"
    return self._engine_type(target_values)  # type: ignore[arg-type]

def _dir_additions_for_owner(self) -> set[str_t]:
    """
    Add the string-like labels to the owner dataframe/series dir output.

    If this is a MultiIndex, it's first level values are used.
    """
    max_items = config["display"]["max_dir_items"]
    # GH#18587 avoid hashing the entire Index in the common case where
    # only the first ``max_items`` unique values are needed. Examining a
    # bounded prefix suffices when it already contains enough uniques;
    # otherwise fall back to the full unique() call.
    if max_items is not None and len(self) > max_items * 10:
        prefix_uniq = self[: max_items * 10].unique(level=0)
        if len(prefix_uniq) >= max_items:
            return {
                c
                for c in prefix_uniq[:max_items]
                if isinstance(c, str) and c.isidentifier()
            }
    return {
        c
        for c in self.unique(level=0)[:max_items]
        if isinstance(c, str) and c.isidentifier()

def __array_ufunc__(
    self, ufunc: np.ufunc, method: str_t, *inputs: Any, **kwargs: Any
) -> Any:
    if any(isinstance(other, (ABCSeries, ABCDataFrame)) for other in inputs):
        return NotImplemented

    # self._values only reaches the ExtensionArray guard when it is an EA, so a
    #  bool Index against datetimelike data needs this here
    ops.disallow_datetimelike_logical_ufunc(ufunc, inputs)

    result = arraylike.maybe_dispatch_ufunc_to_dunder_op(
        self, ufunc, method, *inputs, **kwargs
    )
    if result is not NotImplemented:
        return result

    if "out" in kwargs:
        # e.g. test_dti_isub_tdi
        return arraylike.dispatch_ufunc_with_out(
            self, ufunc, method, *inputs, **kwargs
        )

    if method == "reduce":
        result = arraylike.dispatch_reduction_ufunc(
            self, ufunc, method, *inputs, **kwargs
        )
        if result is not NotImplemented:
            return result

    new_inputs = [x if x is not self else x._values for x in inputs]
    result = getattr(ufunc, method)(*new_inputs, **kwargs)
    if ufunc.nout == 2:
        # i.e. np.divmod, np.modf, np.frexp
        return tuple(self.__array_wrap__(x) for x in result)
    elif method == "reduce":
        result = lib.item_from_zerodim(result)
        return maybe_unbox_numpy_scalar(result, object_with_dtype=self)
    elif is_scalar(result):
        # e.g. matmul
        return maybe_unbox_numpy_scalar(result, object_with_dtype=self)

    if result.dtype == np.float16:
        result = result.astype(np.float32)

    return self.__array_wrap__(result)

def _format_attrs(self) -> list[tuple[str_t, str_t | int | bool | None]]:
    """
    Return a list of tuples of the (attr,formatted_value).
    """
    attrs: list[tuple[str_t, str_t | int | bool | None]] = []

    if not self._is_multi:
        attrs.append(("dtype", f"'{self.dtype}'"))

    if self.name is not None:
        attrs.append(("name", default_pprint(self.name)))
    elif self._is_multi and any(x is not None for x in self.names):
        attrs.append(("names", default_pprint(self.names)))

    max_seq_items = config["display"]["max_seq_items"] or len(self)
    if len(self) > max_seq_items:
        attrs.append(("length", len(self)))
    return attrs

def _get_level_names(self) -> range | Sequence[Hashable]:
    """
    Return a name or list of names with None replaced by the level number.
    """
    if self._is_multi:
        return maybe_sequence_to_range(  # type: ignore[return-value]
            [
                level if name is None else name
                for level, name in enumerate(self.names)
            ]
        )
    else:
        return range(1) if self.name is None else [self.name]

def _mpl_repr(self) -> np.ndarray:
    # how to represent ourselves to matplotlib
    if isinstance(self.dtype, np.dtype) and self.dtype.kind == "M":
        return self.astype(object, copy=False)._values  # type: ignore[return-value]  # pyright: ignore[reportReturnType]
    elif isinstance(self.dtype, ExtensionDtype):
        values = cast("ExtensionArray", self._values)
        if self.dtype.kind in "mM":
            # e.g. ArrowDtype - relying on default of NaT for those dtypes
            # (explicitly specifying NaT raises an error)
            return values.to_numpy()
        if self.dtype.kind == "O":
            return values.to_numpy(na_value=None)
        if self.hasnans:
            return values.to_numpy(na_value=np.nan)
        else:
            return values.to_numpy()
    return self._values  # type: ignore[return-value]  # pyright: ignore[reportReturnType]

def _format_flat(
    self,
    *,
    include_name: bool,
    formatter: Callable | None = None,
) -> list[str_t]:
    """
    Render a string representation of the Index.
    """
    from pandas.io.formats.format import format_name

    header = []
    if include_name:
        header.append(format_name(self.name))

    if formatter is not None:
        return header + list(self.map(formatter))

    return self._format_with_header(header=header, na_rep=self._default_na_rep)

def _validate_names(
    self,
    name: Hashable = None,
    names: Sequence[Hashable] | None = None,
    deep: bool = False,
) -> list[Hashable]:
    """
    Handles the quirks of having a singular 'name' parameter for general
    Index and plural 'names' parameter for MultiIndex.
    """
    from copy import deepcopy

    if names is not None and name is not None:
        raise TypeError("Can only provide one of `names` and `name`")
    if names is None and name is None:
        new_names = deepcopy(self.names) if deep else self.names
    elif names is not None:
        if not is_list_like(names):
            raise TypeError("Must pass list-like as `names`.")
        new_names = names
    elif not is_list_like(name):
        new_names = [name]
    else:
        new_names = name

    if len(new_names) != len(self.names):  # pyright: ignore[reportArgumentType]
        raise ValueError(
            f"Length of new names must be {len(self.names)}, got {len(new_names)}"  # pyright: ignore[reportArgumentType]
        )

    # All items in 'new_names' need to be hashable
    validate_all_hashable(*new_names, error_name=f"{type(self).__name__}.name")  # pyright: ignore[reportOptionalIterable, reportGeneralTypeIssues]

    return new_names  # pyright: ignore[reportReturnType]

def _validate_index_level(self, level: Level) -> None:
    """
    Validate index level.

    For single-level Index getting level number is a no-op, but some
    verification must be done like in MultiIndex.

    """
    is_level_na = cast("bool", isna(level))
    is_name_na = cast("bool", isna(self.name))
    if is_level_na and is_name_na:
        if is_matching_na(level, self.name):
            return
        raise KeyError(
            f"Requested level ({level}) does not match index name ({self.name})"
        )
    elif is_level_na:
        raise KeyError(
            f"Requested level ({level}) does not match index name ({self.name})"
        )

    if is_integer(level):
        if is_integer(self.name) and level == self.name:
            return
        if level < 0 and level != -1:
            raise IndexError(
                "Too many levels: Index has only 1 level, "
                f"{level} is not a valid level number"
            )
        if level > 0:
            raise IndexError(
                f"Too many levels: Index has only 1 level, not {level + 1}"
            )
        return
    elif level != self.name:
        raise KeyError(
            f"Requested level ({level}) does not match index name ({self.name})"

def _can_hold_na(self) -> bool:
    if isinstance(self.dtype, ExtensionDtype):
        return self.dtype._can_hold_na
    if self.dtype.kind in "iub":
        return False
    return True

def _is_all_dates(self) -> bool:
    """
    Whether or not the index values only consist of dates.
    """
    if needs_i8_conversion(self.dtype):
        return True
    elif self.dtype != _dtype_obj:
        # TODO(ExtensionIndex): 3rd party EA might override?
        # Note: this includes IntervalIndex, even when the left/right
        #  contain datetime-like objects.
        return False
    elif self._is_multi:
        return False
    return is_datetime_array(ensure_object(self._values))

def _na_value(self) -> Hashable:
    """The expected NA value to use with this index."""
    dtype = self.dtype
    if isinstance(dtype, np.dtype):
        if dtype.kind in "mM":
            return NaT
        return np.nan
    return dtype.na_value

def _wrap_setop_result(
    self, other: Index, result: Index | ArrayLike | MultiIndex
) -> Index:
    name = get_op_result_name(self, other)  # type: ignore[no-untyped-call]
    if isinstance(result, Index):
        if result.name != name:
            result = result.rename(name)
    else:
        result = self._shallow_copy(result, name=name)
    return result

def _intersection(
    self, other: Index, sort: bool = False
) -> Index | ArrayLike | MultiIndex:
    """
    intersection specialized to the case with matching dtypes.
    """
    if self._can_use_libjoin and other._can_use_libjoin:
        try:
            res_indexer, indexer, _ = self._inner_indexer(other)  # pyright: ignore[reportArgumentType]
        except TypeError:
            # non-comparable; should only be for object dtype
            pass
        else:
            # TODO: algos.unique1d should preserve DTA/TDA
            if is_numeric_dtype(self.dtype):
                # This is faster, because Index.unique() checks for uniqueness
                # before calculating the unique values.
                res = algos.unique1d(res_indexer)
            else:
                result = self.take(indexer)
                res = result.drop_duplicates()  # type: ignore[assignment]
            return ensure_wrapped_if_datetimelike(res)  # type: ignore[no-untyped-call]

    res_values = self._intersection_via_get_indexer(other, sort=sort)
    res_values = _maybe_try_sort(res_values, sort)  # type: ignore[assignment]
    return res_values

def _get_indexer(
    self,
    target: Index,
    method: str_t | None = None,
    limit: int | None = None,
    tolerance: Any = None,
) -> npt.NDArray[np.intp]:
    if tolerance is not None:
        tolerance = self._convert_tolerance(tolerance, target)

    if method in ["pad", "backfill"]:
        indexer = self._get_fill_indexer(target, method, limit, tolerance)
    elif method == "nearest":
        indexer = self._get_nearest_indexer(target, limit, tolerance)
    else:
        if target._is_multi and self._is_multi:
            engine = self._engine
            # error: Item "IndexEngine" of "Union[IndexEngine, ExtensionEngine]"
            # has no attribute "_extract_level_codes"
            tgt_values = engine._extract_level_codes(  # type: ignore[union-attr]
                target
            )
        else:
            tgt_values = target._get_engine_target()

        indexer = self._engine.get_indexer(tgt_values)  # pyright: ignore[reportArgumentType]

    if method is not None and target._can_hold_na and not target._is_multi:
        # GH#32572 NaT/NaN in the target should not be matched
        #  by pad/backfill/nearest
        na_mask = target._isnan
        if na_mask.any():
            indexer[na_mask] = -1

    return ensure_platform_int(indexer)

def _should_partial_index(self, target: Index) -> bool:
    """
    Should we attempt partial-matching indexing?
    """
    if isinstance(self.dtype, IntervalDtype):
        if isinstance(target.dtype, IntervalDtype):
            return False
        # "Index" has no attribute "left"
        return self.left._should_compare(target)  # type: ignore[attr-defined]
    return False

def _check_indexing_method(
    self,
    method: str_t | None,
    limit: int | None = None,
    tolerance: Any = None,
) -> None:
    """
    Raise if we have a get_indexer `method` that is not supported or valid.
    """
    if method not in [None, "bfill", "backfill", "pad", "ffill", "nearest"]:
        # in practice the clean_reindex_fill_method call would raise
        #  before we get here
        raise ValueError("Invalid fill method")  # pragma: no cover

    if self._is_multi:
        if method == "nearest":
            raise NotImplementedError(
                "method='nearest' not implemented yet "
                "for MultiIndex; see GitHub issue 9365"
            )
        if method in ("pad", "backfill"):
            if tolerance is not None:
                raise NotImplementedError(
                    "tolerance not implemented yet for MultiIndex"
                )

    if isinstance(self.dtype, (IntervalDtype, CategoricalDtype)):
        # GH#37871 for now this is only for IntervalIndex and CategoricalIndex
        if method is not None:
            raise NotImplementedError(
                f"method {method} not yet implemented for {type(self).__name__}"
            )

    if method is None:
        if tolerance is not None:
            raise ValueError(
                "tolerance argument only valid if doing pad, "
                "backfill or nearest reindexing"
            )
        if limit is not None:
            raise ValueError(
                "limit argument only valid if doing pad, "

def _convert_tolerance(
    self, tolerance: Any, target: np.ndarray | Index
) -> np.ndarray:
    # override this method on subclasses
    tolerance = np.asarray(tolerance)
    if target.size != tolerance.size and tolerance.size > 1:
        raise ValueError("list-like tolerance size must match target index size")
    elif is_numeric_dtype(self) and not np.issubdtype(tolerance.dtype, np.number):
        if tolerance.ndim > 0:
            raise ValueError(
                f"tolerance argument for {type(self).__name__} with dtype "
                f"{self.dtype} must contain numeric elements if it is list type"
            )

        raise ValueError(
            f"tolerance argument for {type(self).__name__} with dtype {self.dtype} "
            f"must be numeric if it is a scalar: {tolerance!r}"
        )
    return tolerance

def _get_fill_indexer(
    self,
    target: Index,
    method: str_t,
    limit: int | None = None,
    tolerance: Any = None,
) -> npt.NDArray[np.intp]:
    if self._is_multi:
        if not (self.is_monotonic_increasing or self.is_monotonic_decreasing):
            raise ValueError("index must be monotonic increasing or decreasing")
        encoded = self.append(target)._engine.values  # type: ignore[union-attr]
        self_encoded = Index(encoded[: len(self)], copy=False)
        target_encoded = Index(encoded[len(self) :], copy=False)
        return self_encoded._get_fill_indexer(
            target_encoded, method, limit, tolerance
        )

    if self.is_monotonic_increasing and target.is_monotonic_increasing:
        target_values = target._get_engine_target()
        own_values = self._get_engine_target()
        if not isinstance(target_values, np.ndarray) or not isinstance(
            own_values, np.ndarray
        ):
            raise NotImplementedError

        if method == "pad":
            indexer = libalgos.pad(own_values, target_values, limit=limit)
        else:
            # i.e. "backfill"
            indexer = libalgos.backfill(own_values, target_values, limit=limit)
    else:
        indexer = self._get_fill_indexer_searchsorted(target, method, limit)
    if tolerance is not None and len(self):
        indexer = self._filter_indexer_tolerance(target, indexer, tolerance)
    return indexer

def _maybe_preserve_names(self, target: IndexT, preserve_names: bool) -> IndexT:
    if preserve_names and target.nlevels == 1 and target.name != self.name:
        target = target.copy(deep=False)
        target.name = self.name
    return target

def _join_empty(
    self, other: Index, how: JoinHow, sort: bool
) -> tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    assert len(self) == 0 or len(other) == 0
    _validate_join_method(how)

    lidx: np.ndarray | None
    ridx: np.ndarray | None

    if len(other):
        how = cast("JoinHow", {"left": "right", "right": "left"}.get(how, how))
        join_index, ridx, lidx = other._join_empty(self, how, sort)
    elif how in ["left", "outer"]:
        if sort and not self.is_monotonic_increasing:
            lidx = self.argsort()
            join_index = self.take(lidx)
        else:
            lidx = None
            join_index = self._view()
        ridx = np.broadcast_to(np.intp(-1), len(join_index))
    else:
        join_index = other._view()
        lidx = np.array([], dtype=np.intp)
        ridx = None
    return join_index, lidx, ridx

def _join_via_get_indexer(
    self, other: Index, how: JoinHow, sort: bool
) -> tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    # Fallback if we do not have any fastpaths available based on
    #  uniqueness/monotonicity

    # Note: at this point we have checked matching dtypes
    lindexer: npt.NDArray[np.intp] | None
    rindexer: npt.NDArray[np.intp] | None

    if how == "left":
        if sort:
            join_index, lindexer = self.sort_values(return_indexer=True)
            rindexer = other.get_indexer_for(join_index)
            return join_index, lindexer, rindexer
        else:
            join_index = self
    elif how == "right":
        if sort:
            join_index, rindexer = other.sort_values(return_indexer=True)
            lindexer = self.get_indexer_for(join_index)
            return join_index, lindexer, rindexer
        else:
            join_index = other
    elif how == "inner":
        join_index = self.intersection(other, sort=sort)
    elif how == "outer":
        try:
            join_index = self.union(other, sort=sort)
        except TypeError:
            join_index = self.union(other)
            try:
                join_index = _maybe_try_sort(join_index, sort)  # type: ignore[assignment]
            except TypeError:
                pass

    names = other.names if how == "right" else self.names
    if join_index.names != names:  # pyright: ignore[reportAttributeAccessIssue]
        join_index = join_index.set_names(names)  # pyright: ignore[reportAttributeAccessIssue]

    if join_index is self:
        lindexer = None
    else:
        lindexer = self.get_indexer_for(join_index)  # pyright: ignore[reportArgumentType]
    if join_index is other:
        rindexer = None
    else:
        rindexer = other.get_indexer_for(join_index)  # pyright: ignore[reportArgumentType]
    return join_index, lindexer, rindexer  # pyright: ignore[reportReturnType]

def _join_non_unique(
    self, other: Index, how: JoinHow = "left", sort: bool = False
) -> tuple[Index, npt.NDArray[np.intp], npt.NDArray[np.intp]]:
    from pandas.core.reshape.merge import get_join_indexers_non_unique

    # We only get here if dtypes match
    assert self.dtype == other.dtype

    left_idx, right_idx = get_join_indexers_non_unique(
        self._values, other._values, how=how, sort=sort
    )

    if how == "right":
        join_index = other.take(right_idx)
    else:
        join_index = self.take(left_idx)

    if how == "outer":
        mask = left_idx == -1
        if mask.any():
            right = other.take(right_idx)
            join_index = join_index.putmask(mask, right)

    if isinstance(join_index, ABCMultiIndex) and how == "outer":
        # test_join_index_levels
        join_index = join_index._sort_levels_monotonic()
    return join_index, left_idx, right_idx

def _wrap_join_result(
    self,
    joined: ArrayLike,
    other: Self,
    lidx: npt.NDArray[np.intp] | None,
    ridx: npt.NDArray[np.intp] | None,
    how: JoinHow,
) -> tuple[Self, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    assert other.dtype == self.dtype

    if lidx is not None and lib.is_range_indexer(lidx, len(self)):
        lidx = None
    if ridx is not None and lib.is_range_indexer(ridx, len(other)):
        ridx = None

    # return self or other if possible to maintain cached attributes
    if lidx is None:
        join_index = self
    elif ridx is None:
        join_index = other
    else:
        join_index = self._constructor._with_infer(
            joined, dtype=self.dtype, copy=False
        )

    names = other.names if how == "right" else self.names
    if join_index.names != names:
        join_index = join_index.set_names(names)

    return join_index, lidx, ridx

def _get_engine_target(self) -> ArrayLike:
    """
    Get the ndarray or ExtensionArray that we can pass to the IndexEngine
    constructor.
    """
    vals = self._values
    if isinstance(vals, StringArray):
        # GH#45652 much more performant than ExtensionEngine
        return vals._ndarray
    if isinstance(vals, ArrowExtensionArray) and self.dtype.kind in "Mm":
        import pyarrow as pa

        pa_type = vals._pa_array.type
        if pa.types.is_timestamp(pa_type):
            vals = vals._to_datetimearray()
            return vals._ndarray.view("i8")
        elif pa.types.is_duration(pa_type):
            vals = vals._to_timedeltaarray()
            return vals._ndarray.view("i8")
    if (
        type(self) is Index
        and isinstance(vals, ExtensionArray)
        and not isinstance(vals, BaseMaskedArray)
        and not (
            isinstance(vals, ArrowExtensionArray)
            and is_numeric_dtype(self.dtype)
            # Exclude decimal
            and self.dtype.kind != "O"
        )
    ):
        # TODO(ExtensionIndex): remove special-case, just use self._values
        return vals.astype(object)
    return vals

def _get_join_target(self) -> np.ndarray:
    """
    Get the ndarray or ExtensionArray that we can pass to the join
    functions.
    """
    if isinstance(self._values, BaseMaskedArray):
        # This is only used if our array is monotonic, so no NAs present
        return self._values._data
    elif (
        isinstance(self._values, ArrowExtensionArray)
        and self.dtype.kind not in "mM"
    ):
        # This is only used if our array is monotonic, so no missing values
        # present
        # "mM" cases will go through _get_engine_target and cast to i8
        return self._values.to_numpy()

    target = self._get_engine_target()
    if not isinstance(target, np.ndarray):
        raise ValueError("_can_use_libjoin should return False.")
    return target

def _from_join_target(self, result: np.ndarray) -> ArrayLike:
    """
    Cast the ndarray returned from one of the libjoin.foo_indexer functions
    back to type(self._data).
    """
    if isinstance(self.values, BaseMaskedArray):
        return type(self.values)(result, np.zeros(result.shape, dtype=np.bool_))
    elif isinstance(self.values, (ArrowExtensionArray, StringArray)):
        return type(self.values)._from_sequence(result, dtype=self.dtype)
    return result

def _maybe_copy_array_input(
    cls, data: object, copy: bool | None, dtype: Dtype | None
) -> tuple[Any, bool]:
    """
    Ensure that the input data is copied if necessary.
    GH#63388
    """
    if isinstance(data, (ExtensionArray, np.ndarray)):
        if copy is not False:
            if dtype is None or astype_is_view(data.dtype, pandas_dtype(dtype)):
                data = data.copy()
                copy = False
    return data, bool(copy)

def _validate_fill_value(self, value: object) -> object:
    """
    Check if the value can be inserted into our array without casting,
    and convert it to an appropriate native type if necessary.

    Raises
    ------
    TypeError
        If the value cannot be inserted into an array of this dtype.
    """
    dtype = self.dtype
    if isinstance(dtype, np.dtype) and dtype.kind not in "mM":
        if isinstance(value, tuple) and dtype != object:
            # GH#54385
            raise TypeError
        try:
            return np_can_hold_element(dtype, value)
        except LossySetitemError as err:
            # re-raise as TypeError for consistency
            raise TypeError from err
    elif not can_hold_element(self._values, value):
        raise TypeError
    return value

def _is_memory_usage_qualified(self) -> bool:
    """
    Return a boolean if we need a qualified .info display.
    """
    return is_object_dtype(self.dtype) or (
        is_string_dtype(self.dtype) and self.dtype.storage == "python"  # type: ignore[union-attr]

def __getitem__(self, key: Any) -> Any:
    """
    Override numpy.ndarray's __getitem__ method to work as desired.

    This function adds lists and Series as valid boolean indexers
    (ndarrays only supports ndarray with dtype=bool).

    If resulting ndim != 1, plain ndarray is returned instead of
    corresponding `Index` subclass.

    """
    getitem = self._data.__getitem__

    key = lib.item_from_zerodim(key)
    if is_integer(key) or is_float(key):
        # GH#44051 exclude bool, which would return a 2d ndarray
        key = com.cast_scalar_indexer(key)
        return maybe_unbox_numpy_scalar(getitem(key), object_with_dtype=self)

    if isinstance(key, slice):
        # This case is separated from the conditional above to avoid
        # pessimization com.is_bool_indexer and ndim checks.
        return self._getitem_slice(key)

    if com.is_bool_indexer(key):
        # if we have list[bools, length=1e5] then doing this check+convert
        #  takes 166 µs + 2.1 ms and cuts the ndarray.__getitem__
        #  time below from 3.8 ms to 496 µs
        # if we already have ndarray[bool], the overhead is 1.4 µs or .25%
        if isinstance(getattr(key, "dtype", None), ExtensionDtype):
            key = key.to_numpy(dtype=bool, na_value=False)
        else:
            key = np.asarray(key, dtype=bool)

        if not isinstance(self.dtype, ExtensionDtype):
            if len(key) == 0 and len(key) != len(self):
                raise ValueError(
                    "The length of the boolean indexer cannot be 0 "
                    "when the Index has length greater than 0."
                )

    result = getitem(key)
    # Because we ruled out integer above, we always get an arraylike here
    if result.ndim > 1:
        disallow_ndim_indexing(result)

    # NB: Using _constructor._simple_new would break if MultiIndex
    #  didn't override __getitem__
    return self._constructor._simple_new(result, name=self._name)

def _get_indexer_strict(
    self, key: Axes, axis_name: str_t
) -> tuple[Index, np.ndarray]:
    """
    Analogue to get_indexer that raises if any elements are missing.
    """
    keyarr = key
    if not isinstance(keyarr, Index):
        keyarr = com.asarray_tuplesafe(keyarr)

    if self._index_as_unique:
        indexer = self.get_indexer_for(keyarr)  # pyright: ignore[reportArgumentType]
        if not isinstance(keyarr, Index):
            keyarr = ensure_index(keyarr)
            keyarr.name = self.name
    else:
        keyarr, indexer, new_indexer = self._reindex_non_unique(keyarr)  # type: ignore[arg-type]  # pyright: ignore[reportArgumentType]

    self._raise_if_missing(keyarr, indexer, axis_name)

    keyarr = self.take(indexer)
    if lib.is_np_dtype(keyarr.dtype, "mM") or isinstance(
        keyarr.dtype, DatetimeTZDtype
    ):
        # DTI/TDI.take can infer a freq in some cases when we dont want one
        if isinstance(key, list) or (
            isinstance(key, type(self))
            # "Index" has no attribute "freq"
            and key.freq is None  # type: ignore[attr-defined]
        ):
            # error: "Index" has no attribute "_with_freq"; maybe "_with_infer"?
            keyarr = keyarr._with_freq(None)  # type: ignore[attr-defined]

    return keyarr, indexer

def _maybe_downcast_for_indexing(self, other: Index) -> tuple[Index, Index]:
    """
    When dealing with an object-dtype Index and a non-object Index, see
    if we can upcast the object-dtype one to improve performance.
    """

    if isinstance(self, ABCDatetimeIndex) and isinstance(other, ABCDatetimeIndex):
        if (
            self.tz is not None
            and other.tz is not None
            and not tz_compare(self.tz, other.tz)
        ):
            # standardize on UTC
            return self.tz_convert("UTC"), other.tz_convert("UTC")

    elif self.inferred_type == "date" and isinstance(other, ABCDatetimeIndex):
        try:
            result = type(other)(self)
        except ValueError:
            # e.g. out of bounds, or dates mixed with tz-aware Timestamps
            return self, other
        else:
            if self.is_unique and not result.is_unique:
                return self, other
            warnings.warn(
                # GH#62158 deprecate special-case treatment of date objects
                "Indexing a DatetimeIndex with a sequence of datetime.date "
                "objects is deprecated. Use Timestamp objects instead.",
                Pandas4Warning,
                stacklevel=find_stack_level(),
            )
            return result, other
    elif self.inferred_type == "timedelta" and isinstance(other, ABCTimedeltaIndex):
        # TODO: we dont have tests that get here
        return type(other)(self), other

    elif self.dtype.kind == "u" and other.dtype.kind == "i":
        # GH#41873
        if other.min() >= 0:  # type: ignore[operator]  # pyright: ignore[reportOperatorIssue]
            # lookup min as it may be cached
            # TODO: may need itemsize check if we have non-64-bit Indexes
            return self, other.astype(self.dtype)

    elif self._is_multi and not other._is_multi:
        try:
            # "Type[Index]" has no attribute "from_tuples"
            other = type(self).from_tuples(other)  # type: ignore[attr-defined]
        except (TypeError, ValueError):
            # let's instead try with a straight Index
            self = Index(self._values, copy=False)

    if not is_object_dtype(self.dtype) and is_object_dtype(other.dtype):
        # Reverse op so we dont need to re-implement on the subclasses
        other, self = other._maybe_downcast_for_indexing(self)

    return self, other

def _is_comparable_dtype(self, dtype: DtypeObj) -> bool:
    """
    Can we compare values of the given dtype to our own?
    """
    if self.dtype.kind == "b":
        return dtype.kind == "b"
    elif is_numeric_dtype(self.dtype):
        return is_numeric_dtype(dtype)
    # TODO: this was written assuming we only get here with object-dtype,
    #  which is no longer correct. Can we specialize for EA?
    return True

def _transform_index(self, func: Callable, *, level: int | None = None) -> Index:
    """
    Apply function to all values found in index.

    This includes transforming multiindex entries separately.
    Only apply function to one level of the MultiIndex if level is specified.
    """
    if isinstance(self, ABCMultiIndex):
        values = [
            (
                self.get_level_values(i).map(func)
                if i == level or level is None
                else self.get_level_values(i)
            )
            for i in range(self.nlevels)
        ]
        return type(self).from_arrays(values)
    else:
        items = [func(x) for x in self]
        if not items:
            return Index(
                items, dtype=self.dtype, name=self.name, tupleize_cols=False
            )
        new_values = self.array._cast_pointwise_result(items)
        return Index(
            new_values,
            dtype=new_values.dtype,
            copy=False,
            name=self.name,
            tupleize_cols=False,

def _searchsorted_monotonic(
    self, label: Hashable, side: Literal["left", "right"] = "left"
) -> int:
    if self.is_monotonic_increasing:
        return self.searchsorted(label, side=side)  # type: ignore[call-overload]
    elif self.is_monotonic_decreasing:
        # np.searchsorted expects ascending sort order, have to reverse
        # everything for it to work (element ordering, search side and
        # resulting value).
        pos = self[::-1].searchsorted(  # type: ignore[call-overload]
            label,  # pyright: ignore[reportArgumentType]
            side="right" if side == "left" else "left",
        )
        return maybe_unbox_numpy_scalar(len(self) - pos)

    raise ValueError("index must be monotonic increasing or decreasing")

def _cmp_method(self, other: object, op: Callable) -> Any:
    """
    Wrapper used to dispatch comparison operations.
    """
    if isinstance(other, Index) and self.is_(other):
        # fastpath
        if op in {operator.eq, operator.le, operator.ge}:
            arr = np.ones(len(self), dtype=bool)
            if self._can_hold_na and not isinstance(self, ABCMultiIndex):
                # TODO: should set MultiIndex._can_hold_na = False?
                arr[self.isna()] = False
            return arr
        elif op is operator.ne:
            arr = np.zeros(len(self), dtype=bool)
            if self._can_hold_na and not isinstance(self, ABCMultiIndex):
                arr[self.isna()] = True
            return arr

    if isinstance(other, (np.ndarray, Index, ABCSeries, ExtensionArray)) and len(
        self
    ) != len(other):
        raise ValueError("Lengths must match to compare")

    if (
        not isinstance(self, ABCMultiIndex)
        and not isinstance(self._values, ExtensionArray)
        and self._values.dtype != object
    ):
        # MultiIndex and object dtype already treat a non-standard listlike
        # as scalar-like; for EA-backed values the warning is emitted
        # downstream by the EA (GH#62423).
        ops.maybe_warn_listlike(other)

    if not isinstance(other, ABCMultiIndex):
        other = extract_array(other, extract_numpy=True)
    else:
        other = np.asarray(other)

    result = ops.comparison_op(self._values, other, op)

    return result

def is_mask(key: object) -> bool:
    """
    Whether ``key`` is a boolean mask, possibly holding missing values.

    A boolean dtype is a mask. Otherwise ``key`` must be a list or an
    object-dtype array-like that is one-dimensional with every non-missing
    element a bool. A tuple or DataFrame is never a mask.
    """
    if isinstance(key, ABCDataFrame):
        return False
    if isinstance(key, list):
        values = np.asarray(key, dtype=object)
    else:
        dtype = getattr(key, "dtype", None)
        if dtype is None or isinstance(key, ABCMultiIndex):
            return False
        if is_bool_dtype(dtype):
            return True
        if dtype != np.object_:
            return False
        values = np.asarray(key, dtype=object)
    if values.ndim != 1:
        # lib.is_bool_array iterates a 2-D array flat, so a list of bool tuples
        # (labels for a MultiIndex) would otherwise be mistaken for a mask.
        return False
    return lib.is_bool_array(values, skipna=True)

def _parse_select_args(args: tuple) -> list:
    """
    Parse the positional arguments of DataFrame.select.

    A single list-like argument (other than a tuple, which is a single
    column label) is treated as the sequence of items to select; otherwise
    each argument is one item. Mixing a sequence with other positional
    arguments raises, as do sets, whose iteration order is undefined.
    """

    def is_sequence(arg: object) -> bool:
        if isinstance(arg, (set, frozenset)):
            raise TypeError(
                "`select` does not support sets, as the resulting column "
                "order would be undefined; pass a list instead"
            )
        return not isinstance(arg, (tuple, Expression)) and is_list_like(arg)

    if len(args) == 1 and is_sequence(args[0]):
        return list(args[0])
    if any(is_sequence(arg) for arg in args):
        raise TypeError(
            "`select` supports individual columns "
            "`df.select('col1', 'col2', ...)` or a single list "
            "`df.select(['col1', 'col2', ...])`, but not both. "
            "You can unpack the list if you have a mix: "
            "`df.select(*['col1', 'col2'], 'col3')`."
        )
    return list(args)

def reorder_columns(ldesc: Sequence[Series]) -> list[Hashable]:
    """Set a convenient order for rows for display."""
    names: list[Hashable] = []
    seen_names: set[Hashable] = set()
    ldesc_indexes = sorted((x.index for x in ldesc), key=len)
    for idxnames in ldesc_indexes:
        for name in idxnames:
            if name not in seen_names:
                seen_names.add(name)
                names.append(name)
    return names

def select_describe_func(
    data: Series,
) -> Callable:
    """Select proper function for describing series based on data type.

    Parameters
    ----------
    data : Series
        Series to be described.
    """
    if is_bool_dtype(data.dtype):
        return describe_categorical_1d
    elif is_numeric_dtype(data):
        return describe_numeric_1d
    elif data.dtype.kind == "M" or isinstance(data.dtype, DatetimeTZDtype):
        return describe_timestamp_1d
    elif data.dtype.kind == "m":
        return describe_numeric_1d
    else:
        return describe_categorical_1d

def _select_data(self) -> DataFrame:
    """Select columns to be described."""
    if (self.include is None) and (self.exclude is None):
        # when some numerics are found, keep only numerics
        default_include: list[npt.DTypeLike] = [np.number, "datetime"]
        data = self.obj.select_dtypes(include=default_include)
        if len(data.columns) == 0:
            data = self.obj
    elif isinstance(self.include, str) and self.include == "all":
        # isinstance guard so an array-like spec is not compared elementwise
        if self.exclude is not None:
            msg = "exclude must be None when include is 'all'"
            raise ValueError(msg)
        data = self.obj
    else:
        data = self.obj.select_dtypes(
            include=self.include,
            exclude=self.exclude,
        )
        if len(data.columns) == 0:
            msg = "No columns match the specified include or exclude data types"
            raise ValueError(msg)
    return data

def create_data_for_split(
    df: DataFrame, are_all_object_dtype_cols: bool, object_dtype_indices: list[int]
) -> Generator[list]:
    """
    Simple helper method to create data for to ``to_dict(orient="split")``
    to create the main output data
    """
    if are_all_object_dtype_cols:
        for tup in df.itertuples(index=False, name=None):
            yield list(map(maybe_box_native, tup))
    else:
        for tup in df.itertuples(index=False, name=None):
            data = list(tup)
            if object_dtype_indices:
                # If we have object_dtype_cols, apply maybe_box_naive after
                # for perf
                for i in object_dtype_indices:
                    data[i] = maybe_box_native(data[i])
            yield data

def _coerce_scalar_to_timedelta_type(
    r, unit: UnitChoices | None = "ns", errors: DateTimeErrorChoices = "raise"
) -> Timedelta | NaTType:
    """Convert string 'r' to a timedelta object."""
    result: Timedelta | NaTType

    try:
        result = Timedelta(r, unit)
    except ValueError:
        if errors == "raise":
            raise
        # coerce
        result = NaT

    return result

def _guess_datetime_format_for_array(arr, dayfirst: bool | None = False) -> str | None:
    # Try to guess the format based on the first non-NaN element, return None if can't
    if (first_non_null := tslib.first_non_null(arr)) != -1:
        if type(first_non_nan_element := arr[first_non_null]) is str:
            # GH#32264 np.str_ object
            guessed_format = guess_datetime_format(
                first_non_nan_element, dayfirst=dayfirst
            )
            if guessed_format is not None:
                return guessed_format
            # If there are multiple non-null elements, warn about
            # how parsing might not be consistent
            if tslib.first_non_null(arr[first_non_null + 1 :]) != -1:
                warnings.warn(
                    "Could not infer format, so each element will be parsed "
                    "individually, falling back to `dateutil`. To ensure parsing is "
                    "consistent and as-expected, please specify a format.",
                    UserWarning,
                    stacklevel=find_stack_level(),
                )
    return None

def _guess_time_format_for_array(arr):
    # Try to guess the format based on the first non-NaN element
    non_nan_elements = notna(arr).nonzero()[0]
    if len(non_nan_elements):
        element = arr[non_nan_elements[0]]
        for time_format in _time_formats:
            try:
                datetime.strptime(element, time_format)
                return time_format
            except ValueError:
                pass

    return None

def astype_float_to_int_nansafe(
    values: np.ndarray, dtype: np.dtype, copy: bool
) -> np.ndarray:
    """
    astype with a check preventing converting NaN to a meaningless integer value.
    """
    if not np.isfinite(values).all():
        raise IntCastingNaNError(
            "Cannot convert non-finite values (NA or inf) to integer. "
            "Replace or remove non-finite values or cast to an integer type "
            "that supports these values (e.g. 'Int64')"
        )
    if dtype.kind == "u":
        # GH#45151
        if not (values >= 0).all():
            raise ValueError(f"Cannot losslessly cast from {values.dtype} to {dtype}")
    with warnings.catch_warnings():
        warnings.filterwarnings("ignore", category=RuntimeWarning)
        return values.astype(dtype, copy=copy)

def astype_is_view(dtype: DtypeObj, new_dtype: DtypeObj) -> bool:
    """Checks if astype avoided copying the data.

    Parameters
    ----------
    dtype : Original dtype
    new_dtype : target dtype

    Returns
    -------
    True if new data is a view or not guaranteed to be a copy, False otherwise
    """
    if dtype.kind in "iufb" and dtype.kind == new_dtype.kind:
        # fastpath for numeric dtypes
        if hasattr(dtype, "itemsize") and hasattr(new_dtype, "itemsize"):
            return dtype.itemsize == new_dtype.itemsize  # pyright: ignore[reportAttributeAccessIssue]

    if isinstance(dtype, np.dtype) and not isinstance(new_dtype, np.dtype):
        new_dtype, dtype = dtype, new_dtype

    if dtype == new_dtype:
        return True

    elif isinstance(dtype, np.dtype) and isinstance(new_dtype, np.dtype):
        # GH#63936: pandas realizes a numpy str ("<U") target as an object
        #  array via ensure_string_array, which views an object source.
        if is_object_dtype(dtype) and is_string_dtype(new_dtype):
            return True
        # Only equal numpy dtypes avoid a copy
        return False

    elif is_string_dtype(dtype) and is_string_dtype(new_dtype):
        from pandas.core.arrays.string_ import StringDtype

        if (
            isinstance(dtype, StringDtype)
            and dtype.storage == "pyarrow"
            and new_dtype == "object"
        ):
            # for conversion of pyarrow array to numpy object array -> always a copy
            return False
        # Potentially! a view when converting from object to string
        return True

    elif is_object_dtype(dtype) and new_dtype.kind == "O":
        # When the underlying array has dtype object, we don't have to make a copy
        return True

    elif dtype.kind in "mM" and new_dtype.kind in "mM":
        dtype = getattr(dtype, "numpy_dtype", dtype)
        new_dtype = getattr(new_dtype, "numpy_dtype", new_dtype)
        return getattr(dtype, "unit", None) == getattr(new_dtype, "unit", None)

    elif new_dtype == object and isinstance(
        dtype, (DatetimeTZDtype, PeriodDtype, IntervalDtype)
    ):
        return False

    elif isinstance(dtype, CategoricalDtype) and not isinstance(
        new_dtype, CategoricalDtype
    ):
        return False

    numpy_dtype = getattr(dtype, "numpy_dtype", None)
    new_numpy_dtype = getattr(new_dtype, "numpy_dtype", None)

    if numpy_dtype is None and isinstance(dtype, np.dtype):
        numpy_dtype = dtype

    if new_numpy_dtype is None and isinstance(new_dtype, np.dtype):
        new_numpy_dtype = new_dtype

    if numpy_dtype is not None and new_numpy_dtype is not None:
        # if both have NumPy dtype or one of them is a numpy dtype
        # they are only a view when the numpy dtypes are equal, e.g.
        # int64 -> Int64 or int64[pyarrow]
        # int64 -> Int32 copies
        return numpy_dtype == new_numpy_dtype

    # Assume this is a view since we don't know for sure if a copy was made
    return True

def _get_result_dtype(
    to_concat: Sequence[ArrayLike], non_empties: Sequence[ArrayLike]
) -> tuple[bool, set[str], DtypeObj | None]:
    target_dtype = None

    dtypes = {obj.dtype for obj in to_concat}
    kinds = {obj.dtype.kind for obj in to_concat}

    any_ea = any(not isinstance(x, np.ndarray) for x in to_concat)
    if any_ea:
        # i.e. any ExtensionArrays

        # we ignore axis here, as internally concatting with EAs is always
        # for axis=0
        if len(dtypes) != 1:
            target_dtype = find_common_type([x.dtype for x in to_concat])
            target_dtype = common_dtype_categorical_compat(to_concat, target_dtype)

    elif not len(non_empties):
        # we have all empties, but may need to coerce the result dtype to
        # object if we have non-numeric type operands (numpy would otherwise
        # cast this to float)
        if len(kinds) != 1:
            if not len(kinds - {"i", "u", "f"}) or not len(kinds - {"b", "i", "u"}):
                # let numpy coerce
                pass
            else:
                # coerce to object
                target_dtype = np.dtype(object)
                kinds = {"o"}
    elif "b" in kinds and len(kinds) > 1:
        # GH#21108, GH#45101
        target_dtype = np.dtype(object)
        kinds = {"o"}
    else:
        # error: Argument 1 to "np_find_common_type" has incompatible type
        # "*Set[Union[ExtensionDtype, Any]]"; expected "dtype[Any]"
        target_dtype = np_find_common_type(*dtypes)  # type: ignore[arg-type]

    return any_ea, kinds, target_dtype

def _isna(obj: object) -> bool | npt.NDArray[np.bool_] | NDFrame:
    """
    Detect missing values, treating None, NaN or NA as null.

    Parameters
    ----------
    obj: ndarray or object value
        Input array or scalar value.

    Returns
    -------
    boolean ndarray or boolean
    """
    if is_scalar(obj):
        return libmissing.checknull(obj)
    elif isinstance(obj, ABCMultiIndex):
        raise NotImplementedError("isna is not defined for MultiIndex")
    elif isinstance(obj, type):
        return False
    elif isinstance(obj, (np.ndarray, ABCExtensionArray)):
        return _isna_array(obj)
    elif isinstance(obj, ABCIndex):
        # Try to use cached isna, which also short-circuits for integer dtypes
        #  and avoids materializing RangeIndex._values
        if not obj._can_hold_na:
            return obj.isna()
        return _isna_array(obj._values)

    elif isinstance(obj, ABCSeries):
        result = _isna_array(obj._values)
        # box
        result = obj._constructor(result, index=obj.index, name=obj.name, copy=False)
        return result
    elif isinstance(obj, ABCDataFrame):
        return obj.isna()
    elif isinstance(obj, list):
        return _isna_array(np.asarray(obj, dtype=object))
    elif hasattr(obj, "__array__"):
        return _isna_array(np.asarray(obj))
    else:
        return False

def _isna_string_dtype(values: np.ndarray) -> npt.NDArray[np.bool_]:
    # Working around NumPy ticket 1542
    dtype = values.dtype

    if dtype.kind in ("S", "U"):
        result = np.zeros(values.shape, dtype=bool)
    elif values.ndim in {1, 2}:
        result = libmissing.isnaobj(values)
    else:
        # 0-D, reached via e.g. mask_missing
        result = libmissing.isnaobj(values.ravel())
        result = result.reshape(values.shape)

    return result

def _array_equivalent_float(left: np.ndarray, right: np.ndarray) -> bool:
    # lib.array_equivalent_float only accepts native float32/float64. Complex is
    # compared with numpy: viewing it to float pairs would test the real and
    # imaginary parts independently, breaking whole-element NA semantics -- a
    # complex value is NA if either part is NaN (GH#66160). float16, longdouble,
    # and byte-swapped floats also fall back to numpy (GH#65192).
    if left.dtype.kind == "c" or not (
        left.dtype.isnative and left.dtype.itemsize in (4, 8)
    ):
        return bool(((left == right) | (np.isnan(left) & np.isnan(right))).all())
    if left.ndim > 1:
        if left.flags.f_contiguous and right.flags.f_contiguous:
            # .T is a C-contiguous view of an F-contiguous array
            left = left.T
            right = right.T
        if not (left.flags.c_contiguous and right.flags.c_contiguous):
            return bool(((left == right) | (np.isnan(left) & np.isnan(right))).all())
        left = left.ravel()
        right = right.ravel()
    return lib.array_equivalent_float(left, right)

def _array_equivalent_object(
    left: np.ndarray, right: np.ndarray, strict_nan: bool
) -> bool:
    left = ensure_object(left)
    right = ensure_object(right)

    mask: npt.NDArray[np.bool_] | None = None
    if strict_nan:
        mask = isna(left) & isna(right)
        if not mask.any():
            mask = None

    try:
        if mask is None:
            return lib.array_equivalent_object(left, right)
        if not lib.array_equivalent_object(left[~mask], right[~mask]):
            return False
        left_remaining = left[mask]
        right_remaining = right[mask]
    except ValueError:
        # can raise a ValueError if left and right cannot be
        # compared (e.g. nested arrays)
        left_remaining = left
        right_remaining = right

    for left_value, right_value in zip(left_remaining, right_remaining, strict=True):
        if left_value is NaT and right_value is not NaT:
            return False

        elif left_value is libmissing.NA and right_value is not libmissing.NA:
            return False

        elif isinstance(left_value, float) and np.isnan(left_value):
            if not isinstance(right_value, float) or not np.isnan(right_value):
                return False
        else:
            with warnings.catch_warnings():
                # suppress numpy's "elementwise comparison failed"
                warnings.simplefilter("ignore", DeprecationWarning)
                try:
                    if np.any(np.asarray(left_value != right_value)):
                        return False
                except TypeError as err:
                    if "boolean value of NA is ambiguous" in str(err):
                        return False
                    raise
                except ValueError:
                    # numpy can raise a ValueError if left and right cannot be
                    # compared (e.g. nested arrays)
                    return False
    return True

def array_equals(left: ArrayLike, right: ArrayLike) -> bool:
    """
    ExtensionArray-compatible implementation of array_equivalent.
    """
    if left.dtype != right.dtype:
        return False
    elif isinstance(left, ABCExtensionArray):
        return left.equals(right)
    else:
        return array_equivalent(left, right, dtype_equal=True)

def is_valid_na_for_dtype(obj: object, dtype: DtypeObj) -> bool:
    """
    isna check that excludes incompatible dtypes

    Parameters
    ----------
    obj : object
    dtype : np.datetime64, np.timedelta64, DatetimeTZDtype, or PeriodDtype

    Returns
    -------
    bool
    """
    if not lib.is_scalar(obj) or not isna(obj):  # pyright: ignore[reportGeneralTypeIssues]
        return False
    elif dtype.kind == "M":
        if isinstance(dtype, np.dtype):
            # i.e. not tzaware
            return not isinstance(obj, (np.timedelta64, Decimal))
        # we have to rule out tznaive dt64("NaT")
        return not isinstance(obj, (np.timedelta64, np.datetime64, Decimal))
    elif dtype.kind == "m":
        return not isinstance(obj, (np.datetime64, Decimal))
    elif dtype.kind in "iufc":
        # Numeric
        return obj is not NaT and not isinstance(obj, (np.datetime64, np.timedelta64))
    elif dtype.kind == "b":
        # We allow pd.NA, None, np.nan in BooleanArray (same as IntervalDtype)
        return lib.is_float(obj) or obj is None or obj is libmissing.NA

    elif dtype == _dtype_str:
        # numpy string dtypes to avoid float np.nan
        return not isinstance(obj, (np.datetime64, np.timedelta64, Decimal, float))

    elif dtype == _dtype_object:
        # This is needed for Categorical, but is kind of weird
        return True

    elif isinstance(dtype, PeriodDtype):
        return not isinstance(obj, (np.datetime64, np.timedelta64, Decimal))

    elif isinstance(dtype, IntervalDtype):
        return lib.is_float(obj) or obj is None or obj is libmissing.NA

    elif isinstance(dtype, CategoricalDtype):
        return is_valid_na_for_dtype(obj, dtype.categories.dtype)

    # fallback, default to allowing NaN, None, NA, NaT
    return not isinstance(obj, (np.datetime64, np.timedelta64, Decimal))

def _disallow_mismatched_datetimelike(value: Scalar, dtype: DtypeObj) -> None:
    """
    numpy allows np.array(dt64values, dtype="timedelta64[ns]") and
    vice-versa, but we do not want to allow this, so we need to
    check explicitly
    """
    vdtype = getattr(value, "dtype", None)
    if vdtype is None:
        return
    elif (vdtype.kind == "m" and dtype.kind == "M") or (
        vdtype.kind == "M" and dtype.kind == "m"
    ):
        raise TypeError(f"Cannot cast {value!r} to {dtype}")

def maybe_downcast_to_dtype(result: ArrayLike, dtype: np.dtype) -> ArrayLike:
    """
    try to cast to the specified dtype (e.g. convert back to bool/int
    or could be an astype of float64->float32
    """
    if isinstance(result, ABCSeries):
        result = result._values
    do_round = False

    if not isinstance(dtype, np.dtype):
        # enforce our signature annotation
        raise TypeError(dtype)  # pragma: no cover

    converted = maybe_downcast_numeric(result, dtype, do_round)
    if converted is not result:
        return converted

    # a datetimelike
    # GH12821, iNaT is cast to float
    if dtype.kind in "mM" and result.dtype.kind in "if":
        result = result.astype(dtype)

    elif dtype.kind == "m" and result.dtype == _dtype_obj:
        # test_where_downcast_to_td64
        result = cast("np.ndarray", result)
        result = array_to_timedelta64(result)

    elif dtype == np.dtype("M8[ns]") and result.dtype == _dtype_obj:
        result = cast("np.ndarray", result)
        return np.asarray(maybe_cast_to_datetime(result, dtype=dtype))

    return result

def maybe_upcast_numeric_to_64bit(arr: NumpyIndexT) -> NumpyIndexT:
    """
    If array is an int/uint/float bit size lower than 64 bit, upcast it to 64 bit.

    Parameters
    ----------
    arr : ndarray or ExtensionArray

    Returns
    -------
    ndarray or ExtensionArray
    """
    dtype = arr.dtype
    if dtype.kind == "i" and dtype != np.int64:
        return arr.astype(np.int64)
    elif dtype.kind == "u" and dtype != np.uint64:
        return arr.astype(np.uint64)
    elif dtype.kind == "f" and dtype != np.float64:
        return arr.astype(np.float64)
    else:
        return arr

def ensure_dtype_can_hold_na(dtype: DtypeObj) -> DtypeObj:
    """
    If we have a dtype that cannot hold NA values, find the best match that can.
    """
    if isinstance(dtype, ExtensionDtype):
        if dtype._can_hold_na:
            return dtype
        elif isinstance(dtype, IntervalDtype):
            # TODO(GH#45349): don't special-case IntervalDtype, allow
            #  overriding instead of returning object below.
            return IntervalDtype(np.float64, closed=dtype.closed)
        return _dtype_obj
    elif dtype.kind in "bSUV":
        return _dtype_obj
    elif dtype.kind in "iu":
        return np.dtype(np.float64)
    return dtype

def coerce_indexer_dtype(indexer: np.ndarray, categories: Index) -> np.ndarray:
    """coerce the indexer input array to the smallest dtype possible"""
    length = len(categories)
    if length < _int8_max:
        return ensure_int8(indexer)
    elif length < _int16_max:
        return ensure_int16(indexer)
    elif length < _int32_max:
        return ensure_int32(indexer)
    return ensure_int64(indexer)

def find_common_type(types: list[DtypeObj]) -> DtypeObj:  # type: ignore[misc]
    """
    Find a common data type among the given dtypes.

    Parameters
    ----------
    types : list of dtypes

    Returns
    -------
    pandas extension or numpy dtype

    See Also
    --------
    numpy.find_common_type

    """
    if not types:
        raise ValueError("no types given")

    first = types[0]

    # workaround for find_common_type([np.dtype('datetime64[ns]')] * 2)
    # => object
    if lib.dtypes_all_equal(list(types)):
        return first

    # get unique types (dict.fromkeys is used as order-preserving set())
    types = list(dict.fromkeys(types).keys())

    if any(isinstance(t, ExtensionDtype) for t in types):
        for t in types:
            if isinstance(t, ExtensionDtype):
                res = t._get_common_dtype(types)
                if res is not None:
                    return res
        return np.dtype("object")

    # At this point, all types are np.dtype (ExtensionDtype was handled above)
    np_types = cast("list[np.dtype]", types)

    # take lowest unit
    if all(lib.is_np_dtype(t, "M") for t in np_types):
        return np.dtype(max(np_types))
    if all(lib.is_np_dtype(t, "m") for t in np_types):
        return np.dtype(max(np_types))

    # don't mix bool / int or float or complex
    # this is different from numpy, which casts bool with float/int as int
    has_bools = any(t.kind == "b" for t in np_types)
    if has_bools:
        for t in np_types:
            if t.kind in "iufc":
                return np.dtype("object")

    return np_find_common_type(*np_types)

def construct_2d_arraylike_from_scalar(
    value: Scalar, length: int, width: int, dtype: np.dtype, copy: bool
) -> np.ndarray:
    shape = (length, width)

    if dtype.kind in "mM":
        value = _maybe_box_and_unbox_datetimelike(value, dtype)
    elif dtype == _dtype_obj:
        if isinstance(value, (np.timedelta64, np.datetime64)):
            # calling np.array below would cast to pytimedelta/pydatetime
            out = np.empty(shape, dtype=object)
            out.fill(value)
            return out

    # Attempt to coerce to a numpy array
    try:
        if not copy:
            arr = np.asarray(value, dtype=dtype)
        else:
            arr = np.array(value, dtype=dtype, copy=copy)
    except (ValueError, TypeError) as err:
        raise TypeError(
            f"DataFrame constructor called with incompatible data and dtype: {err}"
        ) from err

    if arr.ndim != 0:
        raise ValueError("DataFrame constructor not properly called!")

    return np.full(shape, arr)

def construct_1d_arraylike_from_scalar(
    value: Scalar, length: int, dtype: DtypeObj | None
) -> ArrayLike:
    """
    create an np.ndarray / pandas type of specified shape and dtype
    filled with values

    Parameters
    ----------
    value : scalar value
    length : int
    dtype : pandas_dtype or np.dtype

    Returns
    -------
    np.ndarray / pandas type of length, filled with value

    """

    if dtype is None:
        try:
            dtype, value = infer_dtype_from_scalar(value)
        except OutOfBoundsDatetime:
            dtype = _dtype_obj

    if isinstance(dtype, ExtensionDtype):
        cls = dtype.construct_array_type()
        seq = [] if length == 0 else [value]
        return cls._from_sequence(seq, dtype=dtype).repeat(length)

    if length and dtype.kind in "iu" and isna(value):
        # coerce if we have nan for an integer dtype
        dtype = np.dtype("float64")
    elif lib.is_np_dtype(dtype, "US"):
        # we need to coerce to object dtype to avoid
        # to allow numpy to take our string as a scalar value
        dtype = np.dtype("object")
        if not isna(value):
            value = ensure_str(value)
    elif dtype.kind in "mM":
        value = _maybe_box_and_unbox_datetimelike(value, dtype)

    subarr = np.empty(length, dtype=dtype)
    if length:
        # GH 47391: numpy > 1.24 will raise filling np.nan into int dtypes
        subarr.fill(value)

    return subarr

def _dtype_can_hold_range(rng: range, dtype: np.dtype) -> bool:
    """
    _maybe_infer_dtype_type infers to int64 (and float64 for very large endpoints),
    but in many cases a range can be held by a smaller integer dtype.
    Check if this is one of those cases.
    """
    if not len(rng):
        return True
    return np_can_cast_scalar(rng.start, dtype) and np_can_cast_scalar(rng.stop, dtype)

def ensure_str(value: bytes | Any) -> str:
    """
    Ensure that bytes and non-strings get converted into ``str`` objects.
    """
    if isinstance(value, bytes):
        value = value.decode("utf-8")
    elif not isinstance(value, str):
        value = str(value)
    return value

def _is_dtype_type(arr_or_dtype, condition) -> bool:
    """
    Return true if the condition is satisfied for the arr_or_dtype.

    Parameters
    ----------
    arr_or_dtype : array-like or dtype
        The array-like or dtype object whose dtype we want to extract.
    condition : callable[Union[np.dtype, ExtensionDtypeType]]

    Returns
    -------
    bool : if the condition is satisfied for the arr_or_dtype
    """
    if arr_or_dtype is None:
        return condition(type(None))

    # fastpath
    if isinstance(arr_or_dtype, np.dtype):
        return condition(arr_or_dtype.type)
    elif isinstance(arr_or_dtype, type):
        if issubclass(arr_or_dtype, ExtensionDtype):
            arr_or_dtype = arr_or_dtype.type
        return condition(np.dtype(arr_or_dtype).type)

    # if we have an array-like
    if hasattr(arr_or_dtype, "dtype"):
        arr_or_dtype = arr_or_dtype.dtype

    # we are not possibly a dtype
    elif is_list_like(arr_or_dtype):
        return condition(type(None))

    try:
        tipo = pandas_dtype(arr_or_dtype).type
    except (TypeError, ValueError):
        if is_scalar(arr_or_dtype):
            return condition(type(None))

        return False

    return condition(tipo)

def is_all_strings(value: ArrayLike) -> bool:
    """
    Check if this is an array of strings that we should try parsing.

    Includes object-dtype ndarray containing all-strings, StringArray,
    and Categorical with all-string categories.
    Does not include numpy string dtypes.
    """
    dtype = value.dtype

    if isinstance(dtype, np.dtype):
        if len(value) == 0:
            return dtype == np.dtype("object")
        else:
            return dtype == np.dtype("object") and lib.is_string_array(
                np.asarray(value), skipna=False
            )
    elif isinstance(dtype, CategoricalDtype):
        return dtype.categories.inferred_type == "string"
    return dtype == "string"

def find(
    self, dtype: type_t[ExtensionDtype] | ExtensionDtype | npt.DTypeLike
) -> type_t[ExtensionDtype] | ExtensionDtype | None:
    """
    Parameters
    ----------
    dtype : ExtensionDtype class or instance or str or numpy dtype or python type

    Returns
    -------
    return the first matching dtype, otherwise return None
    """
    if not isinstance(dtype, str):
        dtype_type: type_t
        if not isinstance(dtype, type):
            dtype_type = type(dtype)
        else:
            dtype_type = dtype
        if issubclass(dtype_type, ExtensionDtype):
            # cast needed here as mypy doesn't know we have figured
            # out it is an ExtensionDtype or type_t[ExtensionDtype]
            return cast("ExtensionDtype | type_t[ExtensionDtype]", dtype)

        return None

    for dtype_type in self.dtypes:
        try:
            return dtype_type.construct_from_string(dtype)
        except TypeError:
            pass

    return None

def _from_categorical_dtype(
    cls, dtype: CategoricalDtype, categories=None, ordered: Ordered | None = None
) -> CategoricalDtype:
    if categories is ordered is None:
        return dtype
    if categories is None:
        categories = dtype.categories
    if ordered is None:
        ordered = dtype.ordered
    return cls(categories, ordered)

def _finalize(self, categories, ordered: Ordered, fastpath: bool = False) -> None:
    if ordered is not None:
        self.validate_ordered(ordered)

    if categories is not None:
        categories = self.validate_categories(categories, fastpath=fastpath)

    self._categories = categories
    self._ordered = ordered

def __hash__(self) -> int:
    # _hash_categories returns a uint64, so use the negative
    # space for when we have unknown categories to avoid a conflict
    if self.categories is None:
        if self.ordered:
            return -1
        else:
            return -2
    # We *do* want to include the real self.ordered here
    return int(self._hash_categories)

def __repr__(self) -> str_type:
    if self.categories is None:
        data = "None"
        dtype = "None"
    else:
        data = self.categories._format_data(name=type(self).__name__)
        if isinstance(self.categories, ABCRangeIndex):
            data = str(self.categories._range)
        data = data.rstrip(", ")
        dtype = self.categories.dtype

    return (
        f"CategoricalDtype(categories={data}, ordered={self.ordered}, "
        f"categories_dtype={dtype})"

def _hash_categories(self) -> int:
    from pandas.core.util.hashing import (
        combine_hash_arrays,
        hash_array,
        hash_tuples,
    )

    categories = self.categories
    ordered = self.ordered

    if len(categories) and isinstance(categories[0], tuple):
        # assumes if any individual category is a tuple, then all our. ATM
        # I don't really want to support just some of the categories being
        # tuples.
        cat_list = list(categories)  # breaks if an np.array of categories
        cat_array = hash_tuples(cat_list)
    else:
        if categories.dtype == "O" and len({type(x) for x in categories}) != 1:
            # TODO: hash_array doesn't handle mixed types. It casts
            # everything to a str first, which means we treat
            # {'1', '2'} the same as {'1', 2}
            # find a better solution
            hashed = hash((tuple(categories), ordered))
            return hashed

        cat_array = hash_array(categories._values, categorize=False)
    if ordered:
        cat_array = np.vstack(
            [cat_array, np.arange(len(cat_array), dtype=cat_array.dtype)]
        )
    else:
        cat_array = cat_array.reshape(1, len(cat_array))
    combined_hashed = combine_hash_arrays(iter(cat_array), num_items=len(cat_array))
    return np.bitwise_xor.reduce(combined_hashed)

def _get_common_dtype(self, dtypes: list[DtypeObj]) -> DtypeObj | None:
    # check if we have all categorical dtype with identical categories
    if all(isinstance(x, CategoricalDtype) for x in dtypes):
        first = dtypes[0]
        if all(first == other for other in dtypes[1:]):
            return first

    # special case non-initialized categorical
    # TODO we should figure out the expected return value in general
    non_init_cats = [
        isinstance(x, CategoricalDtype) and x.categories is None for x in dtypes
    ]
    if all(non_init_cats):
        return self
    elif any(non_init_cats):
        return None

    # categorical is aware of Sparse -> extract sparse subdtypes
    subtypes = (x.subtype if isinstance(x, SparseDtype) else x for x in dtypes)
    # extract the categories' dtype
    non_cat_dtypes = [
        x.categories.dtype if isinstance(x, CategoricalDtype) else x
        for x in subtypes
    ]
    # TODO should categorical always give an answer?
    from pandas.core.dtypes.cast import find_common_type

    return find_common_type(non_cat_dtypes)

def __init__(self, unit: TimeUnit | DatetimeTZDtype = "ns", tz=None) -> None:
    if isinstance(unit, DatetimeTZDtype):
        # error: "str" has no attribute "tz"
        unit, tz = unit.unit, unit.tz  # type: ignore[union-attr]

    if unit != "ns":
        if isinstance(unit, str) and tz is None:
            # maybe a string like datetime64[ns, tz], which we support for
            # now.
            result = type(self).construct_from_string(unit)
            unit = result.unit
            tz = result.tz
            msg = (
                f"Passing a dtype alias like 'datetime64[ns, {tz}]' "
                "to DatetimeTZDtype is no longer supported. Use "
                "'DatetimeTZDtype.construct_from_string()' instead."
            )
            raise ValueError(msg)
        if unit not in ["s", "ms", "us", "ns"]:
            raise ValueError("DatetimeTZDtype only supports s, ms, us, ns units")

    if tz:
        tz = timezones.maybe_get_tz(tz)
        tz = timezones.tz_standardize(tz)
    elif tz is not None:
        raise zoneinfo.ZoneInfoNotFoundError(tz)
    if tz is None:
        raise TypeError("A 'tz' is required.")

    self._unit = unit
    self._tz = tz

def __eq__(self, other: object) -> bool:
    if isinstance(other, str):
        if other.startswith("M8["):
            other = f"datetime64[{other[3:]}"
        return other == self.name

    return (
        isinstance(other, DatetimeTZDtype)
        and self.unit == other.unit
        and tz_compare(self.tz, other.tz)

def _get_common_dtype(self, dtypes: list[DtypeObj]) -> DtypeObj | None:
    if all(isinstance(t, DatetimeTZDtype) and t.tz == self.tz for t in dtypes):
        np_dtype = np.max(
            [cast("DatetimeTZDtype", t).base for t in [self, *dtypes]]
        )
        unit = np.datetime_data(np_dtype)[0]
        unit = cast("TimeUnit", unit)
        return type(self)(unit=unit, tz=self.tz)
    return super()._get_common_dtype(dtypes)

def _parse_dtype_strict(cls, freq: str_type) -> BaseOffset:
    if isinstance(freq, str):  # note: freq is already of type str!
        if freq.startswith(("Period[", "period[")):
            m = cls._match.search(freq)
            if m is not None:
                freq = m.group("freq")

        freq_offset = to_offset(freq, is_period=True)
        if freq_offset is not None:
            return freq_offset

    raise TypeError(
        "PeriodDtype argument should be string or BaseOffset, "
        f"got {type(freq).__name__}"

def construct_from_string(cls, string: str_type) -> PeriodDtype:
    """
    Strict construction from a string, raise a TypeError if not
    possible
    """
    if (
        isinstance(string, str) and (string.startswith(("period[", "Period[")))
    ) or isinstance(string, BaseOffset):
        # do not parse string like U as period[U]
        # avoid tuple to be regarded as freq
        try:
            return cls(freq=string)
        except ValueError:
            pass
    if isinstance(string, str):
        msg = f"Cannot construct a 'PeriodDtype' from '{string}'"
    else:
        msg = f"'construct_from_string' expects a string, got {type(string)}"
    raise TypeError(msg)

def is_dtype(cls, dtype: object) -> bool:
    """
    Return a boolean if the passed type is an actual dtype that we
    can match (via string or type)
    """
    if isinstance(dtype, str):
        # PeriodDtype can be instantiated from freq string like "U",
        # but doesn't regard freq str like "U" as dtype.
        if dtype.startswith(("period[", "Period[")):
            try:
                return cls._parse_dtype_strict(dtype) is not None
            except ValueError:
                return False
        else:
            return False
    return super().is_dtype(dtype)

def __from_arrow__(self, array: pa.Array | pa.ChunkedArray) -> PeriodArray:
    """
    Construct PeriodArray from pyarrow Array/ChunkedArray.
    """
    import pyarrow

    from pandas.core.arrays import PeriodArray
    from pandas.core.arrays.arrow._arrow_utils import (
        pyarrow_array_to_numpy_and_mask,
    )

    if isinstance(array, pyarrow.Array):
        chunks = [array]
    else:
        chunks = array.chunks

    results = []
    for arr in chunks:
        data, mask = pyarrow_array_to_numpy_and_mask(arr, dtype=np.dtype(np.int64))
        parr = PeriodArray(data.copy(), dtype=self, copy=False)
        # error: Invalid index type "ndarray[Any, dtype[bool_]]" for "PeriodArray";
        # expected type "Union[int, Sequence[int], Sequence[bool], slice]"
        parr[~mask] = NaT  # type: ignore[index]
        results.append(parr)

    if not results:
        return PeriodArray(np.array([], dtype="int64"), dtype=self, copy=False)
    return PeriodArray._concat_same_type(results)

def __init__(self, subtype=None, closed: IntervalClosedType | None = None) -> None:
    from pandas.core.dtypes.common import (
        is_string_dtype,
        pandas_dtype,
    )

    if closed is not None and closed not in {"right", "left", "both", "neither"}:
        raise ValueError("closed must be one of 'right', 'left', 'both', 'neither'")

    if isinstance(subtype, IntervalDtype):
        if closed is not None and closed != subtype.closed:
            raise ValueError(
                "dtype.closed and 'closed' do not match. "
                "Try IntervalDtype(dtype.subtype, closed) instead."
            )
        self._subtype = subtype._subtype
        self._closed = subtype._closed
    elif subtype is None:
        # we are called as an empty constructor
        # generally for pickle compat
        self._subtype = None
        self._closed = closed
    elif isinstance(subtype, str) and subtype.lower() == "interval":
        self._subtype = None
        self._closed = closed
    else:
        if isinstance(subtype, str):
            m = IntervalDtype._match.search(subtype)
            if m is not None:
                gd = m.groupdict()
                subtype = gd["subtype"]
                if gd.get("closed", None) is not None:
                    if closed is not None:
                        if closed != gd["closed"]:
                            raise ValueError(
                                "'closed' keyword does not match value "
                                "specified in dtype string"
                            )
                    closed = gd["closed"]  # type: ignore[assignment]

        try:
            subtype = pandas_dtype(subtype)
        except TypeError as err:
            raise TypeError("could not construct IntervalDtype") from err
        if CategoricalDtype.is_dtype(subtype) or is_string_dtype(subtype):
            # GH 19016
            msg = (
                "category, object, and string subtypes are not supported "
                "for IntervalDtype"
            )
            raise TypeError(msg)
        self._subtype = subtype
        self._closed = closed

def _can_hold_na(self) -> bool:
    subtype = self._subtype
    if subtype is None:
        # partially-initialized
        raise NotImplementedError(
            "_can_hold_na is not defined for partially-initialized IntervalDtype"
        )
    if subtype.kind in "iu":
        return False
    return True

def construct_from_string(cls, string: str_type) -> IntervalDtype:
    """
    attempt to construct this type from a string, raise a TypeError
    if its not possible
    """
    if not isinstance(string, str):
        raise TypeError(
            f"'construct_from_string' expects a string, got {type(string)}"
        )

    if string.lower() == "interval" or cls._match.search(string) is not None:
        return cls(string)

    msg = (
        f"Cannot construct a 'IntervalDtype' from '{string}'.\n\n"
        "Incorrectly formatted string passed to constructor. "
        "Valid formats include Interval or Interval[dtype] "
        "where dtype is numeric, datetime, or timedelta"
    )
    raise TypeError(msg)

def __str__(self) -> str_type:
    if self.subtype is None:
        return "interval"
    if self.closed is None:
        # Only partially initialized GH#38394
        return f"interval[{self.subtype}]"
    return f"interval[{self.subtype}, {self.closed}]"

def __eq__(self, other: object) -> bool:
    if isinstance(other, str):
        return other.lower() in (self.name.lower(), str(self).lower())
    elif not isinstance(other, IntervalDtype):
        return False
    elif self.subtype is None or other.subtype is None:
        # None should match any subtype
        return True
    elif self.closed != other.closed:
        return False
    else:
        return self.subtype == other.subtype

def is_dtype(cls, dtype: object) -> bool:
    """
    Return a boolean if the passed type is an actual dtype that we
    can match (via string or type)
    """
    if isinstance(dtype, str):
        if dtype.lower().startswith("interval"):
            try:
                return cls.construct_from_string(dtype) is not None
            except (ValueError, TypeError):
                return False
        else:
            return False
    return super().is_dtype(dtype)

def __from_arrow__(self, array: pa.Array | pa.ChunkedArray) -> IntervalArray:
    """
    Construct IntervalArray from pyarrow Array/ChunkedArray.
    """
    import pyarrow

    from pandas.core.arrays import IntervalArray
    from pandas.core.arrays.arrow.array import to_pyarrow_type

    if isinstance(array, pyarrow.Array):
        chunks = [array]
    else:
        chunks = array.chunks

    # np.asarray can't take an ExtensionDtype, e.g. DatetimeTZDtype
    subtype_is_numpy = isinstance(self.subtype, np.dtype)

    def _convert(values: pyarrow.Array):
        if subtype_is_numpy:
            return np.asarray(values, dtype=self.subtype)
        return self.subtype.__from_arrow__(values)

    results = []
    for arr in chunks:
        if isinstance(arr, pyarrow.ExtensionArray):
            arr = arr.storage
        left = _convert(arr.field("left"))
        right = _convert(arr.field("right"))
        iarr = IntervalArray.from_arrays(left, right, closed=self.closed)
        results.append(iarr)

    if not results:
        empty = pyarrow.array([], type=to_pyarrow_type(self.subtype))
        return IntervalArray.from_arrays(
            _convert(empty),
            _convert(empty),
            closed=self.closed,
        )
    return IntervalArray._concat_same_type(results)

def _get_common_dtype(self, dtypes: list[DtypeObj]) -> DtypeObj | None:
    if not all(isinstance(x, IntervalDtype) for x in dtypes):
        return None

    closed = cast("IntervalDtype", dtypes[0]).closed
    if not all(cast("IntervalDtype", x).closed == closed for x in dtypes):
        return np.dtype(object)

    from pandas.core.dtypes.cast import find_common_type

    common = find_common_type([cast("IntervalDtype", x).subtype for x in dtypes])
    if common == object:
        return np.dtype(object)
    return IntervalDtype(common, closed=closed)

def construct_from_string(cls, string: str) -> NumpyEADtype:
    try:
        dtype = np.dtype(string)
    except TypeError as err:
        if not isinstance(string, str):
            msg = f"'construct_from_string' expects a string, got {type(string)}"
        else:
            msg = f"Cannot construct a 'NumpyEADtype' from '{string}'"
        raise TypeError(msg) from err
    return cls(dtype)

def _truthy_value(self):
    # Fill values used for 'any'
    if self.kind == "f":
        return 1.0
    if self.kind in "iu":
        return 1
    return True

def _falsey_value(self):
    # Fill values used for 'all'
    if self.kind == "f":
        return 0.0
    if self.kind in "iu":
        return 0
    return False

def from_numpy_dtype(cls, dtype: np.dtype) -> BaseMaskedDtype:
    """
    Construct the MaskedDtype corresponding to the given numpy dtype.
    """
    if dtype.kind == "b":
        from pandas.core.arrays.boolean import BooleanDtype

        return BooleanDtype()
    elif dtype.kind in "iu":
        from pandas.core.arrays.integer import NUMPY_INT_TO_DTYPE

        return NUMPY_INT_TO_DTYPE[dtype]
    elif dtype.kind == "f":
        from pandas.core.arrays.floating import NUMPY_FLOAT_TO_DTYPE

        return NUMPY_FLOAT_TO_DTYPE[dtype]
    else:
        raise NotImplementedError(dtype)

def _get_common_dtype(self, dtypes: list[DtypeObj]) -> DtypeObj | None:
    # We unwrap any masked dtypes, find the common dtype we would use
    #  for that, then re-mask the result.
    from pandas.core.dtypes.cast import find_common_type

    new_dtype = find_common_type(
        [
            dtype.numpy_dtype if isinstance(dtype, BaseMaskedDtype) else dtype
            for dtype in dtypes
        ]
    )
    if not isinstance(new_dtype, np.dtype):
        # If we ever support e.g. Masked[DatetimeArray] then this will change
        return None
    try:
        return type(self).from_numpy_dtype(new_dtype)
    except (KeyError, NotImplementedError):
        return None

def __init__(self, dtype: Dtype = np.float64, fill_value: Any = None) -> None:
    if isinstance(dtype, type(self)):
        if fill_value is None:
            fill_value = dtype.fill_value
        dtype = dtype.subtype

    from pandas.core.dtypes.common import (
        is_string_dtype,
        pandas_dtype,
    )
    from pandas.core.dtypes.missing import (
        is_valid_na_for_dtype,
        na_value_for_dtype,
    )

    dtype = pandas_dtype(dtype)
    if is_string_dtype(dtype):
        dtype = np.dtype("object")
    if not isinstance(dtype, np.dtype):
        # GH#53160
        raise TypeError("SparseDtype subtype must be a numpy dtype")
    if dtype.kind in "mM" and not is_supported_dtype(dtype):
        # GH#68522 hold the subtype to what the dense constructors accept.
        #  Their own check is cast._ensure_nanosecond_dtype, which this
        #  module cannot import; keep the messages identical.
        if is_unitless(dtype):
            raise ValueError(
                f"The '{dtype.name}' dtype has no unit. "
                f"Please pass in '{dtype.name}[ns]' instead."
            )
        raise TypeError(
            f"dtype={dtype} is not supported. Supported resolutions are 's', "
            "'ms', 'us', and 'ns'"
        )

    if fill_value is None:
        fill_value = na_value_for_dtype(dtype)
    elif dtype.kind in "mM" and is_valid_na_for_dtype(fill_value, dtype):
        # GH#68449, GH#68558 store the subtype's own NaT, so that every
        #  spelling of an NA fill value behaves identically downstream
        fill_value = na_value_for_dtype(dtype)

    self._dtype = dtype
    self._fill_value = fill_value
    self._check_fill_value()

    if isinstance(fill_value, (Timestamp, Timedelta)) and dtype.kind in "mM":
        # GH#68589 store the subtype's own scalar, like the NaT case above:
        #  numpy converts a boxed scalar through datetime, truncating a
        #  nanosecond fill value wherever it reaches numpy
        self._fill_value = fill_value.asm8.astype(dtype)

def _check_fill_value(self) -> None:
    if not lib.is_scalar(self._fill_value):
        raise ValueError(
            f"fill_value must be a scalar. Got {self._fill_value} instead"
        )

    from pandas.core.dtypes.cast import can_hold_element
    from pandas.core.dtypes.missing import (
        is_valid_na_for_dtype,
        isna,
    )

    from pandas.core.construction import ensure_wrapped_if_datetimelike

    # GH#23124 require fill_value and subtype to match
    val = self._fill_value
    if isna(val):
        if not is_valid_na_for_dtype(val, self.subtype):
            raise ValueError(
                # GH#53043
                "fill_value must be a valid value for the SparseDtype.subtype"
            )
    else:
        dummy = np.empty(0, dtype=self.subtype)
        dummy = ensure_wrapped_if_datetimelike(dummy)

        if not can_hold_element(dummy, val):
            raise ValueError(
                # GH#53043
                "fill_value must be a valid value for the SparseDtype.subtype"

def is_dtype(cls, dtype: object) -> bool:
    dtype = getattr(dtype, "dtype", dtype)
    if isinstance(dtype, str) and dtype.startswith("Sparse"):
        sub_type, _ = cls._parse_subtype(dtype)
        dtype = np.dtype(sub_type)
    elif isinstance(dtype, cls):
        return True
    return isinstance(dtype, np.dtype) or dtype == "Sparse"

def __init__(self, pyarrow_dtype: pa.DataType) -> None:
    super().__init__("pyarrow")
    if not HAS_PYARROW:
        raise ImportError(
            f"pyarrow>={PYARROW_MIN_VERSION} is required for ArrowDtype"
        )
    if not isinstance(pyarrow_dtype, pa.DataType):
        raise ValueError(
            f"pyarrow_dtype ({pyarrow_dtype}) must be an instance "
            f"of a pyarrow.DataType. Got {type(pyarrow_dtype)} instead."
        )
    self.pyarrow_dtype = pyarrow_dtype

def type(self):
    """
    Returns associated scalar type.
    """
    pa_type = self.pyarrow_dtype
    if pa.types.is_integer(pa_type):
        return int
    elif pa.types.is_floating(pa_type):
        return float
    elif pa.types.is_string(pa_type) or pa.types.is_large_string(pa_type):
        return str
    elif (
        pa.types.is_binary(pa_type)
        or pa.types.is_fixed_size_binary(pa_type)
        or pa.types.is_large_binary(pa_type)
    ):
        return bytes
    elif pa.types.is_boolean(pa_type):
        return bool
    elif pa.types.is_duration(pa_type):
        if pa_type.unit == "ns":
            return Timedelta
        else:
            return timedelta
    elif pa.types.is_timestamp(pa_type):
        if pa_type.unit == "ns":
            return Timestamp
        else:
            return datetime
    elif pa.types.is_date(pa_type):
        return date
    elif pa.types.is_time(pa_type):
        return time
    elif pa.types.is_decimal(pa_type):
        return Decimal
    elif pa.types.is_dictionary(pa_type):
        # TODO: Potentially change this & CategoricalDtype.type to
        #  something more representative of the scalar
        return CategoricalDtypeType
    elif pa.types.is_list(pa_type) or pa.types.is_large_list(pa_type):
        return list
    elif pa.types.is_fixed_size_list(pa_type):
        return list
    elif pa.types.is_map(pa_type):
        return list
    elif pa.types.is_struct(pa_type):
        return dict
    elif pa.types.is_null(pa_type):
        # TODO: None? pd.NA? pa.null?
        return type(pa_type)
    elif isinstance(pa_type, pa.BaseExtensionType):
        return type(self)(pa_type.storage_type).type
    raise NotImplementedError(pa_type)

def numpy_dtype(self) -> np.dtype:
    """Return an instance of the related numpy dtype"""
    if pa.types.is_timestamp(self.pyarrow_dtype):
        # pa.timestamp(unit).to_pandas_dtype() returns ns units
        # regardless of the pyarrow timestamp units.
        # This can be removed if/when pyarrow addresses it:
        # https://github.com/apache/arrow/issues/34462
        return np.dtype(f"datetime64[{self.pyarrow_dtype.unit}]")
    if pa.types.is_duration(self.pyarrow_dtype):
        # pa.duration(unit).to_pandas_dtype() returns ns units
        # regardless of the pyarrow duration units
        # This can be removed if/when pyarrow addresses it:
        # https://github.com/apache/arrow/issues/34462
        return np.dtype(f"timedelta64[{self.pyarrow_dtype.unit}]")
    if pa.types.is_string(self.pyarrow_dtype) or pa.types.is_large_string(
        self.pyarrow_dtype
    ):
        # pa.string().to_pandas_dtype() = object which we don't want
        return np.dtype(str)
    try:
        return np.dtype(self.pyarrow_dtype.to_pandas_dtype())
    except (NotImplementedError, TypeError):
        return np.dtype(object)

def construct_from_string(cls, string: str) -> ArrowDtype:
    """
    Construct this type from a string.

    Parameters
    ----------
    string : str
        string should follow the format f"{pyarrow_type}[pyarrow]"
        e.g. int64[pyarrow]
    """
    if not isinstance(string, str):
        raise TypeError(
            f"'construct_from_string' expects a string, got {type(string)}"
        )
    if not string.endswith("[pyarrow]"):
        raise TypeError(f"'{string}' must end with '[pyarrow]'")
    if string in ("string[pyarrow]", "str[pyarrow]"):
        # Ensure Registry.find skips ArrowDtype to use StringDtype instead
        raise TypeError("string[pyarrow] should be constructed by StringDtype")
    if not HAS_PYARROW:
        raise ImportError(
            f"pyarrow>={PYARROW_MIN_VERSION} is required for ArrowDtype"
        )

    base_type = string[:-9]  # get rid of "[pyarrow]"
    try:
        pa_dtype = pa.type_for_alias(base_type)
    except ValueError as err:
        has_parameters = re.search(r"[\[\(].*[\]\)]", base_type)
        if has_parameters:
            # Fallback to try common temporal types
            try:
                return cls._parse_temporal_dtype_string(base_type)
            except (NotImplementedError, ValueError):
                # Fall through to raise with nice exception message below
                pass

            raise NotImplementedError(
                "Passing pyarrow type specific parameters "
                f"({has_parameters.group()}) in the string is not supported. "
                "Please construct an ArrowDtype object with a pyarrow_dtype "
                "instance with specific parameters."
            ) from err
        raise TypeError(f"'{base_type}' is not a valid pyarrow data type.") from err
    return cls(pa_dtype)

def _get_common_dtype(self, dtypes: list[DtypeObj]) -> DtypeObj | None:
    # We unwrap any masked dtypes, find the common dtype we would use
    #  for that, then re-mask the result.
    # Mirrors BaseMaskedDtype
    from pandas.core.dtypes.cast import find_common_type

    null_dtype = type(self)(pa.null())
    non_null_dtypes = [dtype for dtype in dtypes if dtype != null_dtype]

    if not non_null_dtypes:
        return null_dtype
    first = non_null_dtypes[0]
    if isinstance(first, ArrowDtype) and all(
        dtype == first for dtype in non_null_dtypes[1:]
    ):
        # Going through numpy_dtype is lossy for pyarrow types with no
        #  numpy analogue, e.g. date32 -> M8[ms], tz-aware timestamp -> M8,
        #  decimal/time/binary/list -> object.  GH#62343
        return first

    def unwrap(dtype: DtypeObj) -> DtypeObj:
        if not isinstance(dtype, ArrowDtype):
            return dtype
        pa_dtype = dtype.pyarrow_dtype
        if pa.types.is_timestamp(pa_dtype) and pa_dtype.tz is not None:
            # numpy_dtype drops the tz, which would unify tz-aware dtypes
            #  into a tz-naive one (GH#69029)
            return DatetimeTZDtype(unit=pa_dtype.unit, tz=pa_dtype.tz)
        return dtype.numpy_dtype

    try:
        unwrapped = [unwrap(dtype) for dtype in non_null_dtypes]
    except (KeyError, ValueError):
        # pa.timestamp does not validate its tz, so it can carry a label
        #  pandas cannot resolve; see test_get_common_dtype_unresolvable_tz
        #  (GH#69029)
        return None

    new_dtype = find_common_type(unwrapped)
    if isinstance(new_dtype, DatetimeTZDtype):
        return type(self)(pa.timestamp(new_dtype.unit, tz=new_dtype.tz))
    if not isinstance(new_dtype, np.dtype):
        return None
    try:
        pa_dtype = pa.from_numpy_dtype(new_dtype)
        return type(self)(pa_dtype)
    except NotImplementedError:
        return None

def unstack(
    obj: Series | DataFrame, level, fill_value=None, sort: bool = True
) -> Series | DataFrame:
    if isinstance(level, (tuple, list)):
        if len(level) != 1:
            # _unstack_multiple only handles MultiIndexes,
            # and isn't needed for a single level
            return _unstack_multiple(obj, level, fill_value=fill_value, sort=sort)
        else:
            level = level[0]

    if not is_integer(level) and not level == "__placeholder__":
        # check if level is valid in case of regular index
        obj.index._get_level_number(level)

    if isinstance(obj, DataFrame):
        if isinstance(obj.index, MultiIndex):
            return _unstack_frame(obj, level, fill_value=fill_value, sort=sort)
        else:
            return obj.T.stack()
    elif not isinstance(obj.index, MultiIndex):
        # GH 36113
        # Give nicer error messages when unstack a Series whose
        # Index is not a MultiIndex.
        raise ValueError(
            f"index must be a MultiIndex to unstack, {type(obj.index)} was passed"
        )
    else:
        if is_1d_only_ea_dtype(obj.dtype):
            return _unstack_extension_series(obj, level, fill_value, sort=sort)
        unstacker = _Unstacker(
            obj.index, level=level, constructor=obj._constructor_expanddim, sort=sort
        )
        return unstacker.get_result(obj, value_columns=None, fill_value=fill_value)

def _unstack_frame(
    obj: DataFrame, level, fill_value=None, sort: bool = True
) -> DataFrame:
    assert isinstance(obj.index, MultiIndex)  # checked by caller
    unstacker = _Unstacker(
        obj.index, level=level, constructor=obj._constructor, sort=sort
    )

    if not obj._can_fast_transpose:
        mgr = obj._mgr.unstack(unstacker, fill_value=fill_value)
        return obj._constructor_from_mgr(mgr, axes=mgr.axes)
    else:
        return unstacker.get_result(
            obj, value_columns=obj.columns, fill_value=fill_value

def _stack_multi_column_index(columns: MultiIndex) -> MultiIndex | Index:
    """Creates a MultiIndex from the first N-1 levels of this MultiIndex."""
    if len(columns.levels) <= 2:
        return columns.levels[0]._rename(name=columns.names[0])

    levs = (
        [lev[c] if c >= 0 else None for c in codes]
        for lev, codes in zip(columns.levels[:-1], columns.codes[:-1], strict=True)
    )

    # Remove duplicate tuples in the MultiIndex.
    tuples = zip(*levs, strict=True)
    unique_tuples = (key for key, _ in itertools.groupby(tuples))
    new_levs = zip(*unique_tuples, strict=True)

    # The dtype of each level must be explicitly set to avoid inferring the wrong type.
    # See GH-36991.
    return MultiIndex.from_arrays(
        [
            # Not all indices can accept None values.
            Index(new_lev, dtype=lev.dtype) if None not in new_lev else new_lev
            for new_lev, lev in zip(new_levs, columns.levels[:-1], strict=True)
        ],
        names=columns.names[:-1],

def get_result(self, obj, value_columns, fill_value) -> DataFrame:
    values = obj._values
    if values.ndim == 1:
        values = values[:, np.newaxis]

    if value_columns is None and values.shape[1] != 1:  # pragma: no cover
        raise ValueError("must pass column labels for multi-column data")

    new_values = self.get_new_values(values, fill_value)
    columns = self.get_new_columns(value_columns)
    index = self.new_index

    result = self.constructor(
        new_values, index=index, columns=columns, dtype=new_values.dtype, copy=False
    )
    if isinstance(values, np.ndarray):
        base, new_base = values.base, new_values.base
    elif isinstance(values, NDArrayBackedExtensionArray):
        base, new_base = values._ndarray.base, new_values._ndarray.base
    else:
        base, new_base = 1, 2  # type: ignore[assignment]
    if base is new_base:
        # We can only get here if one of the dimensions is size 1
        result._mgr.add_references(obj._mgr)
    return result

def get_new_columns(self, value_columns: Index | None):
    if value_columns is None:
        if not self.has_nan:
            return self.removed_level._rename(name=self.removed_name)

        nan_index = 0 if self.sort else self.unique_nan_index
        lev = self.removed_level.insert(
            nan_index, item=self.removed_level._na_value
        )
        return lev.rename(self.removed_name)

    stride = len(self.removed_level) + self.has_nan
    width = len(value_columns)
    propagator = np.repeat(np.arange(width), stride)

    new_levels: FrozenList | list[Index]

    if isinstance(value_columns, MultiIndex):
        new_levels = value_columns.levels + (self.removed_level_full,)  # pyright: ignore[reportOperatorIssue] # noqa: RUF005
        new_names = value_columns.names + (self.removed_name,)  # noqa: RUF005

        new_codes = [lab.take(propagator) for lab in value_columns.codes]
    else:
        new_levels = [
            value_columns,
            self.removed_level_full,
        ]
        new_names = [value_columns.name, self.removed_name]
        new_codes = [propagator]

    repeater = self._repeater

    # The entire level is then just a repetition of the single chunk:
    new_codes.append(np.tile(repeater, width))
    return MultiIndex(
        levels=new_levels, codes=new_codes, names=new_names, verify_integrity=False

def _compute_grand_margin(
    data: DataFrame, values, aggfunc, kwargs, margins_name: Hashable = "All"
):
    if values:
        grand_margin = {}
        for k, v in data[values].items():
            try:
                if isinstance(aggfunc, str):
                    grand_margin[k] = getattr(v, aggfunc)(**kwargs)
                elif isinstance(aggfunc, dict):
                    if k in aggfunc:
                        if isinstance(aggfunc[k], str):
                            grand_margin[k] = getattr(v, aggfunc[k])(**kwargs)
                        else:
                            grand_margin[k] = aggfunc[k](v, **kwargs)
                else:
                    grand_margin[k] = aggfunc(v, **kwargs)
            except TypeError:
                pass
        return grand_margin
    else:
        from pandas import Categorical

        # Use groupby for consistency with how values are aggregated.
        gb = Series(np.nan, index=data.index).groupby(
            Categorical(np.zeros(len(data.index)), categories=[0]), observed=False
        )
        agged = gb.agg(aggfunc, **kwargs)
        assert isinstance(agged, Series) and len(agged) == 1
        return {margins_name: agged.iloc[0]}

def _convert_by(by):
    if by is None:
        by = []
    elif (
        is_scalar(by)
        or isinstance(by, (np.ndarray, Index, ABCSeries, Grouper))
        or callable(by)
    ):
        by = [by]
    else:
        by = list(by)
    return by

def _get_names(arrs, names, prefix: str = "row") -> list:
    if names is None:
        names = []
        for i, arr in enumerate(arrs):
            if isinstance(arr, ABCSeries) and arr.name is not None:
                names.append(arr.name)
            else:
                names.append(f"{prefix}_{i}")
    else:
        if len(names) != len(arrs):
            raise AssertionError("arrays and names must have the same length")
        if not isinstance(names, list):
            names = list(names)

    return names

def _sanitize_mixed_ndim(
    objs: list[Series | DataFrame],
    sample: Series | DataFrame,
    ignore_index: bool,
    axis: AxisInt,
) -> list[Series | DataFrame]:
    # if we have mixed ndims, then convert to highest ndim
    # creating column numbers as needed

    new_objs = []

    current_column = 0
    max_ndim = sample.ndim
    for obj in objs:
        ndim = obj.ndim
        if ndim == max_ndim:
            pass

        elif ndim != max_ndim - 1:
            raise ValueError(
                "cannot concatenate unaligned mixed dimensional NDFrame objects"
            )

        else:
            name = getattr(obj, "name", None)
            rename_columns = False
            if ignore_index or name is None:
                if axis == 1:
                    # doing a row-wise concatenation so need everything
                    # to line up
                    if name is None:
                        name = 0
                        rename_columns = True
                # doing a column-wise concatenation so need series
                # to have unique names
                elif name is None:
                    rename_columns = True
                    name = current_column
                    current_column += 1
                obj = sample._constructor(obj, copy=False)
                if isinstance(obj, ABCDataFrame) and rename_columns:
                    obj.columns = range(name, name + 1, 1)
            else:
                obj = sample._constructor({name: obj}, copy=False)

        new_objs.append(obj)

    return new_objs

def _get_concat_axis_series(
    objs: list[Series | DataFrame],
    ignore_index: bool,
    bm_axis: AxisInt,
    keys: Iterable[Hashable] | None,
    levels,
    verify_integrity: bool,
    names: list[HashableT] | None,
) -> Index:
    """Return result concat axis when concatenating Series objects."""
    if ignore_index:
        return default_index(len(objs))
    elif bm_axis == 0:
        indexes = [x.index for x in objs]
        if keys is None:
            if levels is not None:
                raise ValueError("levels supported only when keys is not None")
            concat_axis = _concat_indexes(indexes)
        else:
            concat_axis = _make_concat_multiindex(indexes, keys, levels, names)
        if verify_integrity and not concat_axis.is_unique:
            overlap = concat_axis[concat_axis.duplicated()].unique()
            raise ValueError(f"Indexes have overlapping values: {overlap}")
        return concat_axis
    elif keys is None:
        result_names: list[Hashable] = [None] * len(objs)
        num = 0
        has_names = False
        for i, x in enumerate(objs):
            if x.ndim != 1:
                raise TypeError(
                    f"Cannot concatenate type 'Series' with "
                    f"object of type '{type(x).__name__}'"
                )
            if x.name is not None:
                result_names[i] = x.name
                has_names = True
            else:
                result_names[i] = num
                num += 1
        if has_names:
            return Index(result_names)
        else:
            return default_index(len(objs))
    else:
        return ensure_index(keys).set_names(names)  # type: ignore[arg-type]

def _get_concat_axis_dataframe(
    objs: list[Series | DataFrame],
    axis: AxisInt,
    ignore_index: bool,
    keys: Iterable[Hashable] | None,
    names: list[HashableT] | None,
    levels,
    verify_integrity: bool,
) -> Index:
    """Return result concat axis when concatenating DataFrame objects."""
    indexes_gen = (x.axes[axis] for x in objs)

    if ignore_index:
        return default_index(sum(len(i) for i in indexes_gen))
    else:
        indexes = list(indexes_gen)

    if keys is None:
        if levels is not None:
            raise ValueError("levels supported only when keys is not None")
        concat_axis = _concat_indexes(indexes)
    else:
        concat_axis = _make_concat_multiindex(indexes, keys, levels, names)

    if verify_integrity and not concat_axis.is_unique:
        overlap = concat_axis[concat_axis.duplicated()].unique()
        raise ValueError(f"Indexes have overlapping values: {overlap}")

    return concat_axis

def _clean_keys_and_objs(
    objs: Iterable[Series | DataFrame] | Mapping[HashableT, Series | DataFrame],
    keys,
) -> tuple[list[Series | DataFrame], Index | None, set[int]]:
    """
    Returns
    -------
    clean_objs : list[Series | DataFrame]
        List of DataFrame and Series with Nones removed.
    keys : Index | None
        None if keys was None
        Index if objs was a Mapping or keys was not None. Filtered where objs was None.
    ndim : set[int]
        Unique .ndim attribute of obj encountered.
    """
    if isinstance(objs, abc.Mapping):
        if keys is None:
            keys = objs.keys()
        objs = [objs[k] for k in keys]
    elif isinstance(objs, (ABCSeries, ABCDataFrame)) or is_scalar(objs):
        raise TypeError(
            "first argument must be an iterable of pandas "
            f'objects, you passed an object of type "{type(objs).__name__}"'
        )
    elif not isinstance(objs, abc.Sized):
        objs = list(objs)

    if len(objs) == 0:
        raise ValueError("No objects to concatenate")

    if keys is not None:
        if not isinstance(keys, Index):
            keys = Index(keys)
        if len(keys) != len(objs):
            # GH#43485
            raise ValueError(
                f"The length of the keys ({len(keys)}) must match "
                f"the length of the objects to concatenate ({len(objs)})"
            )

    # GH#1649
    key_indices = []
    clean_objs = []
    ndims = set()
    for i, obj in enumerate(objs):
        if obj is None:
            continue
        elif isinstance(obj, (ABCSeries, ABCDataFrame)):
            key_indices.append(i)
            clean_objs.append(obj)
            ndims.add(obj.ndim)
        else:
            msg = (
                f"cannot concatenate object of type '{type(obj)}'; "
                "only Series and DataFrame objs are valid"
            )
            raise TypeError(msg)

    if keys is not None and len(key_indices) < len(keys):
        keys = keys.take(key_indices)

    if len(clean_objs) == 0:
        raise ValueError("All objects passed were None")

    return clean_objs, keys, ndims

def _get_sample_object(
    objs: list[Series | DataFrame],
    ndims: set[int],
    keys,
    names,
    levels,
    intersect: bool,
) -> tuple[Series | DataFrame, list[Series | DataFrame]]:
    # get the sample
    # want the highest ndim that we have, and must be non-empty
    # unless all objs are empty
    if len(ndims) > 1:
        max_ndim = max(ndims)
        for obj in objs:
            if obj.ndim == max_ndim and sum(obj.shape):  # type: ignore[arg-type]
                return obj, objs
    elif keys is None and names is None and levels is None and not intersect:
        # filter out the empties if we have not multi-index possibilities
        # note to keep empty Series as it affects the result columns / name
        if ndims.pop() == 2:
            non_empties = [obj for obj in objs if sum(obj.shape)]
        else:
            non_empties = objs

        if len(non_empties):
            return non_empties[0], non_empties

    return objs[0], objs

def _postprocess_for_cut(fac, bins, retbins: bool, original):
    """
    handles post processing for the cut method where
    we combine the index information if the originally passed
    datatype was a series
    """
    if isinstance(original, ABCSeries):
        fac = original._constructor(fac, index=original.index, name=original.name)

    if not retbins:
        return fac

    if isinstance(bins, Index) and is_numeric_dtype(bins.dtype):
        bins = bins._values

    return fac, bins

def _round_frac(x, precision: int):
    """
    Round the fractional part of the given number
    """
    if not np.isfinite(x) or x == 0:
        return x
    else:
        frac, whole = np.modf(x)
        if whole == 0:
            digits = -int(np.floor(np.log10(abs(frac)))) - 1 + precision
        else:
            digits = precision
        return np.around(x, digits)

def _infer_precision(base_precision: int, bins: Index) -> int:
    """
    Infer an appropriate precision for _round_frac
    """
    for precision in range(base_precision, 20):
        levels = np.asarray([_round_frac(b, precision) for b in bins])
        if algos.unique(levels).size == bins.size:
            return precision
    return base_precision  # default

def _maybe_promote_to_rangeindex(idx: Index) -> Index:
    if idx.dtype.kind in "iu" and idx.is_monotonic_increasing and idx.is_unique:
        values = idx._values
        if isinstance(values, np.ndarray):
            result = maybe_sequence_to_range(values)
            if isinstance(result, range):
                return RangeIndex(result, name=idx.name)
    return idx

def _get_multiindex_indexer(
    join_keys: list[ArrayLike], index: MultiIndex, sort: bool
) -> tuple[npt.NDArray[np.intp], npt.NDArray[np.intp]]:
    # left & right join labels and num. of levels at each location
    mapped = (
        _factorize_keys(index.levels[n]._values, join_keys[n], sort=sort)
        for n in range(index.nlevels)
    )
    zipped = zip(*mapped, strict=True)
    rcodes, lcodes, shape = (list(x) for x in zipped)
    if sort:
        rcodes = list(map(np.take, rcodes, index.codes))
    else:
        i8copy = lambda a: a.astype("i8", subok=False)
        rcodes = list(map(i8copy, index.codes))

    # fix right labels if there were any nulls
    for i, join_key in enumerate(join_keys):
        mask = index.codes[i] == -1
        if mask.any():
            # check if there already was any nulls at this location
            # if there was, it is factorized to `shape[i] - 1`
            a = join_key[lcodes[i] == shape[i] - 1]
            if a.size == 0 or not a[0] != a[0]:
                shape[i] += 1

            rcodes[i][mask] = shape[i] - 1

    # get flat i8 join keys
    lkey, rkey = _get_join_keys(lcodes, rcodes, tuple(shape), sort)
    return lkey, rkey

def _left_join_on_index(
    left_ax: Index, right_ax: Index, join_keys: list[ArrayLike], sort: bool = False
) -> tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp]]:
    if isinstance(right_ax, MultiIndex):
        lkey, rkey = _get_multiindex_indexer(join_keys, right_ax, sort=sort)
    else:
        # error: Incompatible types in assignment (expression has type
        # "Union[Union[ExtensionArray, ndarray[Any, Any]], Index, Series]",
        # variable has type "ndarray[Any, dtype[signedinteger[Any]]]")
        lkey = join_keys[0]  # type: ignore[assignment]
        # error: Incompatible types in assignment (expression has type "Index",
        # variable has type "ndarray[Any, dtype[signedinteger[Any]]]")
        rkey = right_ax._values  # type: ignore[assignment]

    left_key, right_key, count = _factorize_keys(lkey, rkey, sort=sort, how="left")
    if count == -1:
        left_indexer, right_indexer = left_key, right_key
    else:
        left_indexer, right_indexer = libjoin.left_outer_join(
            left_key, right_key, count, sort=sort
        )

    if sort or len(left_ax) != len(left_indexer):
        # if asked to sort or there are 1-to-many matches
        join_index = left_ax.take(left_indexer)
        return join_index, left_indexer, right_indexer

    # left frame preserves order & length of its index
    return left_ax, None, right_indexer

def _convert_arrays_and_get_rizer_klass(
    lk: ArrayLike, rk: ArrayLike
) -> tuple[type[libhashtable.Factorizer], ArrayLike, ArrayLike]:
    klass: type[libhashtable.Factorizer]
    if is_numeric_dtype(lk.dtype):
        if lk.dtype != rk.dtype:
            dtype = find_common_type([lk.dtype, rk.dtype])
            if isinstance(dtype, ExtensionDtype):
                cls = dtype.construct_array_type()
                if not isinstance(lk, ExtensionArray):
                    lk = cls._from_sequence(lk, dtype=dtype, copy=False)
                else:
                    lk = lk.astype(dtype, copy=False)

                if not isinstance(rk, ExtensionArray):
                    rk = cls._from_sequence(rk, dtype=dtype, copy=False)
                else:
                    rk = rk.astype(dtype, copy=False)
            else:
                lk = lk.astype(dtype, copy=False)
                rk = rk.astype(dtype, copy=False)
        if isinstance(lk, BaseMaskedArray):
            klass = _factorizers[lk.dtype.type]
        elif isinstance(lk.dtype, ArrowDtype):
            klass = _factorizers[lk.dtype.numpy_dtype.type]
        else:
            klass = _factorizers[lk.dtype.type]

    else:
        klass = libhashtable.ObjectFactorizer
        lk = ensure_object(lk)
        rk = ensure_object(rk)
    return klass, lk, rk

def _fuse_key_view(arr: ArrayLike) -> np.ndarray | None:
    """
    Integer-valued view of a key column for fusing, or None if unsupported.
    """
    dtype = arr.dtype
    if isinstance(dtype, np.dtype):
        if dtype.kind in "mM":
            # raw ndarray or numpy-backed DatetimeArray/TimedeltaArray
            values = (
                arr if isinstance(arr, np.ndarray) else getattr(arr, "_ndarray", None)
            )
            if isinstance(values, np.ndarray) and values.dtype.isnative:
                return values.view(np.int64)
        elif isinstance(arr, np.ndarray):
            if dtype.kind in "iu":
                return arr
            if dtype.kind == "b":
                return arr.view(np.uint8)
    elif isinstance(dtype, DatetimeTZDtype):
        i8values = getattr(arr, "_ndarray", None)
        if isinstance(i8values, np.ndarray):
            return i8values.view(np.int64)
    return None

def _validate_operand(obj: DataFrame | Series) -> DataFrame:
    if isinstance(obj, ABCDataFrame):
        return obj
    elif isinstance(obj, ABCSeries):
        if obj.name is None:
            raise ValueError("Cannot merge a Series without a name")
        return obj.to_frame()
    else:
        raise TypeError(
            f"Can only merge Series or DataFrame objects, a {type(obj)} was passed"

def _indicator_name(self) -> str | None:
    if isinstance(self.indicator, str):
        return self.indicator
    elif isinstance(self.indicator, bool):
        return "_merge" if self.indicator else None
    else:
        raise ValueError(
            "indicator option can only accept boolean or string arguments"

def _get_join_info(
    self,
) -> tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    left_ax = self.left.index
    right_ax = self.right.index

    if self.left_index and self.right_index and self.how != "asof":
        join_index, left_indexer, right_indexer = left_ax.join(
            right_ax, how=self.how, return_indexers=True, sort=self.sort
        )

    elif self.right_index and self.how == "left":
        join_index, left_indexer, right_indexer = _left_join_on_index(
            left_ax, right_ax, self.left_join_keys, sort=self.sort
        )

    elif self.left_index and self.how == "right":
        join_index, right_indexer, left_indexer = _left_join_on_index(
            right_ax, left_ax, self.right_join_keys, sort=self.sort
        )
    else:
        (left_indexer, right_indexer) = self._get_join_indexers()

        if self.right_index:
            if len(self.left) > 0:
                join_index = self._create_join_index(
                    left_ax,
                    right_ax,
                    left_indexer,
                    how="right",
                )
            elif right_indexer is None:
                join_index = right_ax.copy()
            else:
                join_index = right_ax.take(right_indexer)
        elif self.left_index:
            if self.how == "asof":
                # GH#33463 asof should always behave like a left merge
                join_index = self._create_join_index(
                    left_ax,
                    right_ax,
                    left_indexer,
                    how="left",
                )

            elif len(self.right) > 0:
                join_index = self._create_join_index(
                    right_ax,
                    left_ax,
                    right_indexer,
                    how="left",
                )
            elif left_indexer is None:
                join_index = left_ax.copy()
            else:
                join_index = left_ax.take(left_indexer)
        else:
            n = len(left_ax) if left_indexer is None else len(left_indexer)
            join_index = default_index(n)

    if self.anti_join:
        join_index, left_indexer, right_indexer = self._handle_anti_join(
            join_index, left_indexer, right_indexer
        )

    return join_index, left_indexer, right_indexer

def _validate_validate_kwd(self, validate: str) -> None:
    # Check uniqueness of each
    if self.left_index:
        left_join_index = self.orig_left.index
        left_unique = left_join_index.is_unique
    else:
        left_join_index = MultiIndex.from_arrays(self.left_join_keys)
        left_unique = left_join_index.is_unique

    if self.right_index:
        right_join_index = self.orig_right.index
        right_unique = self.orig_right.index.is_unique
    else:
        right_join_index = MultiIndex.from_arrays(self.right_join_keys)
        right_unique = right_join_index.is_unique

    def left_error_msg(x: Index) -> str:
        name = self.left_on if not self.left_index else lib.no_default
        msg = x[x.duplicated()][:5].to_frame(name=name).to_string(index=False)
        return f"\nDuplicates in left:\n {msg} ..."

    def right_error_msg(x: Index) -> str:
        name = self.right_on if not self.right_index else lib.no_default
        msg = x[x.duplicated()][:5].to_frame(name=name).to_string(index=False)
        return f"\nDuplicates in right:\n {msg} ..."

    # Check data integrity
    if validate in ["one_to_one", "1:1"]:
        if not left_unique and not right_unique:
            raise MergeError(
                "Merge keys are not unique in either left "
                "or right dataset; not a one-to-one merge."
                f"{left_error_msg(left_join_index)}"
                f"{right_error_msg(right_join_index)}"
            )
        if not left_unique:
            raise MergeError(
                "Merge keys are not unique in left dataset; not a one-to-one merge"
                f"{left_error_msg(left_join_index)}"
            )
        if not right_unique:
            raise MergeError(
                "Merge keys are not unique in right dataset; not a one-to-one merge"
                f"{right_error_msg(right_join_index)}"
            )

    elif validate in ["one_to_many", "1:m"]:
        if not left_unique:
            raise MergeError(
                "Merge keys are not unique in left dataset; not a one-to-many merge"
                f"{left_error_msg(left_join_index)}"
            )

    elif validate in ["many_to_one", "m:1"]:
        if not right_unique:
            raise MergeError(
                "Merge keys are not unique in right dataset; "
                "not a many-to-one merge\n"
                f"{right_error_msg(right_join_index)}"
            )

    elif validate in ["many_to_many", "m:m"]:
        pass

    else:
        raise ValueError(
            f'"{validate}" is not a valid argument. '

def get_result(self) -> DataFrame:
    join_index, left_indexer, right_indexer = self._get_join_info()

    left_join_indexer: npt.NDArray[np.intp] | None
    right_join_indexer: npt.NDArray[np.intp] | None

    if self.fill_method == "ffill":
        if left_indexer is None:
            left_join_indexer = None
        else:
            left_join_indexer = libjoin.ffill_indexer(left_indexer)
        if right_indexer is None:
            right_join_indexer = None
        else:
            right_join_indexer = libjoin.ffill_indexer(right_indexer)
    elif self.fill_method is None:
        left_join_indexer = left_indexer
        right_join_indexer = right_indexer
    else:
        raise ValueError("fill_method must be 'ffill' or None")

    result = self._reindex_and_concat(
        join_index, left_join_indexer, right_join_indexer
    )
    self._maybe_add_join_keys(result, left_indexer, right_indexer)

    return result

def _maybe_require_matching_dtypes(
    self, left_join_keys: list[ArrayLike], right_join_keys: list[ArrayLike]
) -> None:
    # TODO: why do we do this for AsOfMerge but not the others?

    def _check_dtype_match(left: ArrayLike, right: ArrayLike, i: int) -> None:
        if left.dtype != right.dtype:
            if isinstance(left.dtype, CategoricalDtype) and isinstance(
                right.dtype, CategoricalDtype
            ):
                # The generic error message is confusing for categoricals.
                #
                # In this function, the join keys include both the original
                # ones of the merge_asof() call, and also the keys passed
                # to its by= argument. Unordered but equal categories
                # are not supported for the former, but will fail
                # later with a ValueError, so we don't *need* to check
                # for them here.
                msg = (
                    f"incompatible merge keys [{i}] {left.dtype!r} and "
                    f"{right.dtype!r}, both sides category, but not equal ones"
                )
            else:
                msg = (
                    f"incompatible merge keys [{i}] {left.dtype!r} and "
                    f"{right.dtype!r}, must be the same type"
                )
            raise MergeError(msg)

    # validate index types are the same
    for i, (lk, rk) in enumerate(zip(left_join_keys, right_join_keys, strict=True)):
        _check_dtype_match(lk, rk, i)

    if self.left_index:
        lt = self.left.index._values
    else:
        lt = left_join_keys[-1]

    if self.right_index:
        rt = self.right.index._values
    else:
        rt = right_join_keys[-1]

    _check_dtype_match(lt, rt, 0)

def _validate_tolerance(self, left_join_keys: list[ArrayLike]) -> None:
    # validate tolerance; datetime.timedelta or Timedelta if we have a DTI
    if self.tolerance is not None:
        if self.left_index:
            lt = self.left.index._values
        else:
            lt = left_join_keys[-1]

        msg = (
            f"incompatible tolerance {self.tolerance}, must be compat "
            f"with type {lt.dtype!r}"
        )

        if needs_i8_conversion(lt.dtype) or (
            isinstance(lt, ArrowExtensionArray) and lt.dtype.kind in "mM"
        ):
            if not isinstance(self.tolerance, datetime.timedelta):
                raise MergeError(msg)
            if self.tolerance < Timedelta(0):
                raise MergeError("tolerance must be non-negative")

        elif is_integer_dtype(lt.dtype):
            if not is_integer(self.tolerance):
                raise MergeError(msg)
            if self.tolerance < 0:
                raise MergeError("tolerance must be non-negative")

        elif is_float_dtype(lt.dtype):
            if not is_number(self.tolerance):
                raise MergeError(msg)
            # error: Unsupported operand types for > ("int" and "Number")
            if self.tolerance < 0:  # type: ignore[operator]
                raise MergeError("tolerance must be non-negative")

        else:
            raise MergeError("key must be integer, timestamp or float")

def _convert_values_for_libjoin(
    self, values: AnyArrayLike, side: str
) -> np.ndarray:
    # we require sortedness and non-null values in the join keys
    if not Index(values, copy=False).is_monotonic_increasing:
        if isna(values).any():
            raise ValueError(f"Merge keys contain null values on {side} side")
        raise ValueError(f"{side} keys must be sorted")

    if isinstance(values, ArrowExtensionArray):
        values = values._maybe_convert_datelike_array()

    if needs_i8_conversion(values.dtype):
        values = values.view("i8")

    elif isinstance(values, BaseMaskedArray):
        # we've verified above that no nulls exist
        values = values._data
    elif isinstance(values, ExtensionArray):
        values = values.to_numpy()

    # error: Incompatible return value type (got "Union[ExtensionArray,
    # Any, ndarray[Any, Any], ndarray[Any, dtype[Any]], Index, Series]",
    # expected "ndarray[Any, Any]")
    return values  # type: ignore[return-value]

def ensure_list_vars(arg_vars, variable: str, columns) -> list:
    if arg_vars is not None:
        if not is_list_like(arg_vars):
            return [arg_vars]
        elif isinstance(columns, MultiIndex) and not isinstance(arg_vars, list):
            raise ValueError(
                f"{variable} must be a list of tuples when columns are a MultiIndex"
            )
        else:
            return list(arg_vars)
    else:
        return []

def replace_regex(
    values: ArrayLike, rx: re.Pattern, value, mask: npt.NDArray[np.bool_] | None
) -> None:
    """
    Parameters
    ----------
    values : ArrayLike
        Object dtype.
    rx : re.Pattern
    value : Any
    mask : np.ndarray[bool], optional

    Notes
    -----
    Alters values in-place.
    """

    # deal with replacing values with objects (strings) that match but
    # whose replacement is not a string (numeric, nan, object)
    if isna(value) or not isinstance(value, str):

        def re_replacer(s):
            if is_re(rx) and isinstance(s, str):
                return value if rx.search(s) is not None else s
            else:
                return s

    else:
        # value is guaranteed to be a string here, s can be either a string
        # or null if it's null it gets returned
        def re_replacer(s):
            if is_re(rx) and isinstance(s, str):
                return rx.sub(value, s)
            else:
                return s

    f = np.vectorize(re_replacer, otypes=[np.object_])

    if mask is None:
        values[:] = f(values)
    else:
        if values.ndim != mask.ndim:
            mask = np.broadcast_to(mask, values.shape)
        values[mask] = f(values[mask])

def _take_nd_ndarray(
    arr: np.ndarray,
    indexer: npt.NDArray[np.intp] | None,
    axis: AxisInt,
    fill_value,
    allow_fill: bool,
) -> np.ndarray:
    if indexer is None:
        indexer = np.arange(arr.shape[axis], dtype=np.intp)
        dtype, fill_value = arr.dtype, arr.dtype.type()
    else:
        indexer = ensure_platform_int(indexer)

    dtype, fill_value, mask_info = _take_preprocess_indexer_and_fill_value(
        arr, indexer, fill_value, allow_fill
    )

    flip_order = False
    if arr.ndim == 2 and arr.flags.f_contiguous:
        flip_order = True

    if flip_order:
        arr = arr.T
        axis = arr.ndim - axis - 1

    # at this point, it's guaranteed that dtype can hold both the arr values
    # and the fill_value
    out_shape_ = list(arr.shape)
    out_shape_[axis] = len(indexer)
    out_shape = tuple(out_shape_)
    if arr.flags.f_contiguous and axis == arr.ndim - 1:
        # minor tweak that can make an order-of-magnitude difference
        # for dataframes initialized directly from 2-d ndarrays
        # (s.t. df.values is c-contiguous and df._mgr.blocks[0] is its
        # f-contiguous transpose)
        out = np.empty(out_shape, dtype=dtype, order="F")
    else:
        out = np.empty(out_shape, dtype=dtype)

    func = _get_take_nd_function(
        arr.ndim, arr.dtype, out.dtype, axis=axis, mask_info=mask_info
    )
    if mask_info is not None:
        _, needs_fill = mask_info
    else:
        needs_fill = allow_fill
    func(arr, indexer, out, fill_value, allow_fill=needs_fill)

    if flip_order:
        out = out.T
    return out

def _get_take_nd_function_cached(
    ndim: int, arr_dtype: np.dtype, out_dtype: np.dtype, axis: AxisInt
):
    """
    Part of _get_take_nd_function below that doesn't need `mask_info` and thus
    can be cached (mask_info potentially contains a numpy ndarray which is not
    hashable and thus cannot be used as argument for cached function).
    """
    tup = (arr_dtype.name, out_dtype.name)
    if ndim == 1:
        func = _take_1d_dict.get(tup, None)
    elif ndim == 2:
        if axis == 0:
            func = _take_2d_axis0_dict.get(tup, None)
        else:
            func = _take_2d_axis1_dict.get(tup, None)
    if func is not None:
        return func

    # We get here with string, uint, float16, and complex dtypes that could
    #  potentially be handled in algos_take_helper.
    #  Also a couple with (M8[ns], object) and (m8[ns], object)
    tup = (out_dtype.name, out_dtype.name)
    if ndim == 1:
        func = _take_1d_dict.get(tup, None)
    elif ndim == 2:
        if axis == 0:
            func = _take_2d_axis0_dict.get(tup, None)
        else:
            func = _take_2d_axis1_dict.get(tup, None)
    if func is not None:
        func = _convert_wrapper(func, out_dtype)
        return func

    # datetime64/timedelta64 of any resolution use int64 storage;
    # the dispatch dicts only have entries for ns resolution, so handle
    # other resolutions here.
    if arr_dtype.kind in "mM" and arr_dtype == out_dtype:
        if ndim == 1:
            base_func = libalgos.take_1d_int64_int64
        elif axis == 0:
            base_func = libalgos.take_2d_axis0_int64_int64
        else:
            base_func = libalgos.take_2d_axis1_int64_int64
        return _view_wrapper(base_func, np.int64, np.int64, fill_wrap=np.int64)

    return None

def _get_take_nd_function(
    ndim: int,
    arr_dtype: np.dtype,
    out_dtype: np.dtype,
    axis: AxisInt = 0,
    mask_info=None,
):
    """
    Get the appropriate "take" implementation for the given dimension, axis
    and dtypes.
    """
    func = None
    if ndim <= 2:
        # for this part we don't need `mask_info` -> use the cached algo lookup
        func = _get_take_nd_function_cached(ndim, arr_dtype, out_dtype, axis)

    if func is None:

        def func(arr, indexer, out, fill_value=np.nan, allow_fill: bool = True) -> None:
            indexer = ensure_platform_int(indexer)
            _take_nd_object(
                arr, indexer, out, axis=axis, fill_value=fill_value, mask_info=mask_info
            )

    return func

def _take_nd_object(
    arr: np.ndarray,
    indexer: npt.NDArray[np.intp],
    out: np.ndarray,
    axis: AxisInt,
    fill_value,
    mask_info,
) -> None:
    if mask_info is not None:
        mask, needs_masking = mask_info
    else:
        mask = indexer == -1
        needs_masking = mask.any()
    if arr.dtype != out.dtype:
        arr = arr.astype(out.dtype)
    if arr.shape[axis] > 0:
        arr.take(indexer, axis=axis, out=out)
    if needs_masking:
        outindexer = [slice(None)] * arr.ndim
        outindexer[axis] = mask
        out[tuple(outindexer)] = fill_value

def _take_2d_multi_object(
    arr: np.ndarray,
    indexer: tuple[npt.NDArray[np.intp], npt.NDArray[np.intp]],
    out: np.ndarray,
    fill_value,
    mask_info,
) -> None:
    # this is not ideal, performance-wise, but it's better than raising
    # an exception (best to optimize in Cython to avoid getting here)
    row_idx, col_idx = indexer  # both np.intp
    if mask_info is not None:
        (row_mask, col_mask), (row_needs, col_needs) = mask_info
    else:
        row_mask = row_idx == -1
        col_mask = col_idx == -1
        row_needs = row_mask.any()
        col_needs = col_mask.any()
    if fill_value is not None:
        if row_needs:
            out[row_mask, :] = fill_value
        if col_needs:
            out[:, col_mask] = fill_value
    for i, u_ in enumerate(row_idx):
        if u_ != -1:
            for j, v in enumerate(col_idx):
                if v != -1:
                    out[i, j] = arr[u_, v]

def shift(values: np.ndarray, periods: int, fill_value: Scalar) -> np.ndarray:
    new_values = values

    if periods == 0 or values.size == 0:
        return new_values.copy()

    # Always shift along the last axis.
    axis = new_values.ndim - 1

    # make sure array sent to np.roll is c_contiguous
    f_ordered = values.flags.f_contiguous
    if f_ordered:
        new_values = new_values.T
        axis = 0

    if new_values.size:
        new_values = np.roll(
            new_values,
            np.intp(periods),
            axis=axis,
        )

    axis_indexer = [slice(None)] * values.ndim
    if periods > 0:
        axis_indexer[axis] = slice(None, periods)
    else:
        axis_indexer[axis] = slice(periods, None)
    new_values[tuple(axis_indexer)] = fill_value

    # restore original order
    if f_ordered:
        new_values = new_values.T

    return new_values

def _get_min_value(dtype: np.dtype) -> int | float:
    """Get the minimum value for a given numpy dtype."""
    if dtype.kind == "f":
        return -np.inf
    elif dtype.kind == "u":
        return 0
    else:
        return np.iinfo(dtype).min

def _minmax(
    func: Callable,
    values: np.ndarray,
    mask: npt.NDArray[np.bool_],
    *,
    skipna: bool = True,
    axis: AxisInt | None = None,
):
    """
    Reduction for 1D masked array.

    Parameters
    ----------
    func : np.min or np.max
    values : np.ndarray
        Numpy array with the values (can be of any dtype that support the
        operation).
    mask : np.ndarray[bool]
        Boolean numpy array (True values indicate missing values).
    skipna : bool, default True
        Whether to skip NA.
    axis : int, optional, default None
    """
    if not skipna:
        if axis is not None and values.ndim > 1:
            # For 2D with axis, compute the reduction and let the caller
            # handle per-row/column masking via _wrap_reduction_result.
            return func(values, axis=axis)
        if mask.any() or not values.size:
            # min/max with empty array raise in numpy, pandas returns NA
            return libmissing.NA
        else:
            return func(values, axis=axis)
    else:
        if axis is not None and values.ndim > 1:
            # Can't use values[~mask] which would flatten the array.
            # Instead, replace masked values with the identity element
            # and then reduce.
            if func is np.min:
                fill_value = _get_max_value(values.dtype)
            else:
                fill_value = _get_min_value(values.dtype)
            filled = np.where(mask, fill_value, values)
            return func(filled, axis=axis)
        subset = values[~mask]
        if subset.size:
            return func(subset, axis=axis)
        else:
            # min/max with empty array raise in numpy, pandas returns NA
            return libmissing.NA

def mean(
    values: np.ndarray,
    mask: npt.NDArray[np.bool_],
    *,
    skipna: bool = True,
    axis: AxisInt | None = None,
):
    if not values.size or (mask.all() and (axis is None or values.ndim == 1)):
        return libmissing.NA
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", RuntimeWarning)
        return _reductions(np.mean, values=values, mask=mask, skipna=skipna, axis=axis)

def comp_method_OBJECT_ARRAY(op, x, y):
    if isinstance(y, list):
        # e.g. test_tuple_categories
        y = construct_1d_object_array_from_listlike(y)

    if isinstance(y, (np.ndarray, ABCSeries, ABCIndex)):
        if not is_object_dtype(y.dtype):
            y = y.astype(np.object_)

        if isinstance(y, (ABCSeries, ABCIndex)):
            y = y._values

        if x.shape != y.shape:
            raise ValueError("Shapes must match", x.shape, y.shape)
        result = libops.vec_compare(x.ravel(), y.ravel(), op)
    else:
        result = libops.scalar_compare(x.ravel(), y, op)
    return result.reshape(x.shape)

def maybe_prepare_scalar_for_op(obj, shape: Shape):
    """
    Cast non-pandas objects to pandas types to unify behavior of arithmetic
    and comparison operations.

    Parameters
    ----------
    obj: object
    shape : tuple[int]

    Returns
    -------
    out : object

    Notes
    -----
    Be careful to call this *after* determining the `name` attribute to be
    attached to the result of the arithmetic operation.
    """
    if type(obj) is datetime.timedelta:
        # GH#22390  cast up to Timedelta to rely on Timedelta
        # implementation; otherwise operation against numeric-dtype
        # raises TypeError
        return Timedelta(obj)
    elif type(obj) is datetime.datetime:
        # cast up to Timestamp to rely on Timestamp implementation, see Timedelta above
        return Timestamp(obj)
    elif isinstance(obj, np.datetime64):
        # GH#28080 numpy casts integer-dtype to datetime64 when doing
        #  array[int] + datetime64, which we do not allow
        if isna(obj):
            from pandas.core.arrays import DatetimeArray

            # Avoid possible ambiguities with pd.NaT
            # GH 52295
            if is_unitless(obj.dtype):
                # Use second resolution to ensure that the result of e.g.
                #  `left - np.datetime64("NaT")` retains the unit of left.unit
                obj = obj.astype("datetime64[s]")
            elif not is_supported_dtype(obj.dtype):
                new_dtype = get_supported_dtype(obj.dtype)
                obj = obj.astype(new_dtype)
            right = np.broadcast_to(obj, shape)
            return DatetimeArray._simple_new(right, dtype=right.dtype)

        return Timestamp(obj)

    elif isinstance(obj, np.timedelta64):
        if isna(obj):
            from pandas.core.arrays import TimedeltaArray

            # wrapping timedelta64("NaT") in Timedelta returns NaT,
            #  which would incorrectly be treated as a datetime-NaT, so
            #  we broadcast and wrap in a TimedeltaArray
            # GH 52295
            if is_unitless(obj.dtype):
                # Use second resolution to ensure that the result of e.g.
                #  `left + np.timedelta64("NaT")` retains the unit of left.unit
                obj = obj.astype("timedelta64[s]")
            elif not is_supported_dtype(obj.dtype):
                new_dtype = get_supported_dtype(obj.dtype)
                obj = obj.astype(new_dtype)
            right = np.broadcast_to(obj, shape)
            return TimedeltaArray._simple_new(right, dtype=right.dtype)

        # In particular non-nanosecond timedelta64 needs to be cast to
        #  nanoseconds, or else we get undesired behavior like
        #  np.timedelta64(3, 'D') / 2 == np.timedelta64(1, 'D')
        return Timedelta(obj)

    # We want NumPy numeric scalars to behave like Python scalars
    # post NEP 50
    elif isinstance(obj, np.integer):
        return int(obj)

    elif isinstance(obj, np.floating):
        return float(obj)

    return obj

def _bool_arith_check(op, a: np.ndarray, b) -> None:
    """
    In contrast to numpy, pandas raises an error for certain operations
    with booleans.
    """
    if op in _BOOL_OP_NOT_ALLOWED:
        if a.dtype.kind == "b" and (is_bool_dtype(b) or lib.is_bool(b)):
            op_name = op.__name__.strip("_").lstrip("r")
            raise NotImplementedError(
                f"operator '{op_name}' not implemented for bool dtypes"

def _is_datetimelike_array(obj: object) -> bool:
    if lib.is_scalar(obj):
        return False
    dtype = getattr(obj, "dtype", None)
    if dtype is None:
        return False
    return _is_datetimelike_dtype(dtype)

def _is_datetimelike_dtype(dtype: object) -> bool:
    kind = getattr(dtype, "kind", None)
    if not isinstance(kind, str) or kind in "biufc":
        # no numeric or bool dtype is datetimelike, and logical_op is hot.  A
        #  third-party dtype may have no kind at all, or one that is not a string,
        #  and must fall through rather than crash, see test_logical_op_third_party
        return False
    if isinstance(dtype, CategoricalDtype) and dtype.categories is not None:
        # a Categorical hides its categories behind kind "O"
        return _is_datetimelike_dtype(dtype.categories.dtype)
    if isinstance(dtype, ArrowDtype):
        import pyarrow as pa

        pa_type = dtype.pyarrow_dtype
        if pa.types.is_dictionary(pa_type) or pa.types.is_run_end_encoded(pa_type):
            # the arrow spellings of the CategoricalDtype unwrap above
            pa_type = pa_type.value_type
        # kind is "O" for those two, for time32/time64 and for month_day_nano_interval
        return pa.types.is_temporal(pa_type)
    # kind covers numpy M8/m8 and DatetimeTZDtype; PeriodDtype has kind "O" and needs
    #  naming.  Plain object dtype is excluded on purpose, see
    #  test_logical_op_object_dtype_still_truthy
    return kind in "mM" or isinstance(dtype, PeriodDtype)

def __from_arrow__(
    self, array: pyarrow.Array | pyarrow.ChunkedArray
) -> BaseMaskedArray:
    """
    Construct IntegerArray/FloatingArray from pyarrow Array/ChunkedArray.
    """
    import pyarrow

    from pandas.core.arrays.arrow._arrow_utils import (
        pyarrow_array_to_numpy_and_mask,
    )

    array_class = self.construct_array_type()

    pyarrow_type = pyarrow.from_numpy_dtype(self.type)
    if not array.type.equals(pyarrow_type) and not pyarrow.types.is_null(
        array.type
    ):
        # test_from_arrow_type_error raise for string, but allow
        #  through itemsize conversion GH#31896
        rt_dtype = pandas_dtype(array.type.to_pandas_dtype())
        if rt_dtype.kind not in "iuf":
            # Could allow "c" or potentially disallow float<->int conversion,
            #  but at the moment we specifically test that uint<->int works
            raise TypeError(
                f"Expected array of {self} type, got {array.type} instead"
            )

        array = array.cast(pyarrow_type)

    if isinstance(array, pyarrow.ChunkedArray):
        array = array.combine_chunks()

    data, mask = pyarrow_array_to_numpy_and_mask(array, dtype=self.numpy_dtype)
    if data.dtype.kind == "f" and is_nan_na():
        mask[np.isnan(data)] = False
    return array_class(data.copy(), ~mask, copy=False)

def _standardize_dtype(cls, dtype: NumericDtype | str | np.dtype) -> NumericDtype:
    """
    Convert a string representation or a numpy dtype to NumericDtype.
    """
    if isinstance(dtype, str) and (dtype.startswith(("Int", "UInt", "Float"))):
        # Avoid DeprecationWarning from NumPy about np.dtype("Int64")
        # https://github.com/numpy/numpy/pull/7476
        dtype = dtype.lower()

    if not isinstance(dtype, NumericDtype):
        mapping = cls._get_dtype_mapping()
        try:
            dtype = mapping[np.dtype(dtype)]
        except KeyError as err:
            raise ValueError(f"invalid dtype specified {dtype}") from err
    return dtype

def ensure_arraylike_for_datetimelike(
    data, copy: bool, cls_name: str
) -> tuple[ArrayLike, bool]:
    if not hasattr(data, "dtype"):
        # e.g. list, tuple
        if not isinstance(data, (list, tuple)) and np.ndim(data) == 0:
            # i.e. generator
            data = list(data)

        data = construct_1d_object_array_from_listlike(data)
        copy = False
    elif isinstance(data, ABCMultiIndex):
        raise TypeError(f"Cannot create a {cls_name} from a MultiIndex.")
    else:
        data = extract_array(data, extract_numpy=True)

    if isinstance(data, IntegerArray) or (
        isinstance(data, ArrowExtensionArray) and data.dtype.kind in "iu"
    ):
        data = data.to_numpy("int64", na_value=iNaT)
        copy = False
    elif isinstance(data, ArrowExtensionArray):
        data = data._maybe_convert_datelike_array()
        data = data.to_numpy()
        copy = False
    elif not isinstance(data, (np.ndarray, ExtensionArray)):
        # GH#24539 e.g. xarray, dask object
        data = np.asarray(data)

    elif isinstance(data, ABCCategorical):
        # GH#18664 preserve tz in going DTI->Categorical->DTI
        # TODO: cases where we need to do another pass through maybe_convert_dtype,
        #  e.g. the categories are timedelta64s
        data = data.categories.take(data.codes, allow_fill=True, fill_value=NaT)._values
        copy = False

    if data.ndim == 0:
        raise ValueError(f"Cannot construct {cls_name} from 0-dim input")

    return data, copy

def __iter__(self) -> Iterator:
    if self.ndim > 1:
        return (self[n] for n in range(len(self)))
    else:
        return (self._box_func(v) for v in self.asi8)

def __array__(
    self, dtype: NpDtype | None = None, copy: bool | None = None
) -> np.ndarray:
    # used for Timedelta/DatetimeArray, overwritten by PeriodArray
    if is_object_dtype(dtype):
        if copy is False:
            raise ValueError(
                "Unable to avoid copy while creating an array as requested."
            )
        return np.array(list(self), dtype=object)

    if copy is True:
        return np.array(self._ndarray, dtype=dtype)

    result = self._ndarray
    if self._readonly:
        result = result.view()
        result.flags.writeable = False
    return result

def astype(self, dtype, copy: bool = True):
    # Some notes on cases we don't have to handle here in the base class:
    #   1. PeriodArray.astype handles period -> period
    #   2. DatetimeArray.astype handles conversion between tz.
    #   3. DatetimeArray.astype handles datetime -> period
    dtype = pandas_dtype(dtype)

    if dtype == object:
        if self.dtype.kind == "M":
            self = cast("DatetimeArray", self)
            # *much* faster than self._box_values
            #  for e.g. test_get_loc_tuple_monotonic_above_size_cutoff
            i8data = self.asi8
            converted = ints_to_pydatetime(
                i8data,
                tz=self.tz,
                box="timestamp",
                reso=self._creso,
            )
            return converted

        elif self.dtype.kind == "m":
            return ints_to_pytimedelta(self._ndarray, box=True)

        return self._box_values(self.asi8.ravel()).reshape(self.shape)

    elif is_string_dtype(dtype):
        if isinstance(dtype, ExtensionDtype):
            arr_object = self._format_native_types(na_rep=dtype.na_value)  # type: ignore[arg-type]
            cls = dtype.construct_array_type()
            return cls._from_sequence(arr_object, dtype=dtype, copy=False)
        else:
            return self._format_native_types()

    elif isinstance(dtype, ExtensionDtype):
        return super().astype(dtype, copy=copy)
    elif dtype.kind in "iu":
        # we deliberately ignore int32 vs. int64 here.
        # See https://github.com/pandas-dev/pandas/issues/24381 for more.
        values = self.asi8
        if dtype != np.int64:
            raise TypeError(
                f"Converting from {self.dtype} to {dtype} is not supported. "
                "Do obj.astype('int64').astype(dtype) instead"
            )

        if copy:
            values = values.copy()
        return values
    elif (dtype.kind in "mM" and self.dtype != dtype) or dtype.kind == "f":
        # disallow conversion between datetime/timedelta,
        # and conversions for any datetimelike to float
        msg = f"Cannot cast {type(self).__name__} to dtype {dtype}"
        raise TypeError(msg)
    else:
        return np.asarray(self, dtype=dtype)

def _validate_comparison_value(self, other):
    if isinstance(other, str):
        try:
            # GH#18435 strings get a pass from tzawareness compat
            other = self._scalar_from_string(other)
        except (ValueError, IncompatibleFrequency) as err:
            # failed to parse as Timestamp/Timedelta/Period
            raise InvalidComparison(other) from err

    if isinstance(other, self._recognized_scalars) or other is NaT:
        # error: Argument 1 to "Timestamp" has incompatible type "object";
        # expected "integer[Any] | float | str | date | datetime |
        # datetime64[date | int | None]"  [arg-type]
        other = self._scalar_type(other)  # type: ignore[arg-type]
        try:
            self._check_compatible_with(other)
        except TypeError as err:
            # e.g. tzawareness mismatch
            raise InvalidComparison(other) from err

    elif not is_list_like(other):
        raise InvalidComparison(other)

    elif len(other) != len(self):
        raise ValueError("Lengths must match")

    else:
        try:
            other = self._validate_listlike(other, allow_object=True)
            self._check_compatible_with(other)
        except TypeError as err:
            if is_object_dtype(getattr(other, "dtype", None)):
                # We will have to operate element-wise
                pass
            else:
                raise InvalidComparison(other) from err

    return other

def fillna(self, value, limit: int | None = None, copy: bool = True) -> Self:
    # Fast path: single-pass Cython using iNaT sentinel. GH#42147
    if lib.is_scalar(value):
        if not self._hasna:
            return self.copy() if copy else self[:]
        try:
            validated = self._validate_setitem_value(value)
        except (ValueError, TypeError):
            pass
        else:
            if copy:
                new_ndarray = self._ndarray.copy()
            else:
                if self._readonly:
                    raise ValueError("Cannot modify read-only array")
                new_ndarray = self._ndarray

            arr_i8 = new_ndarray.view("i8")
            fill_i8 = np.array(validated, dtype=new_ndarray.dtype).view("i8")[()]
            algos.scalar_fillna_inplace(
                arr_i8, fill_i8, is_datetimelike=True, limit=limit
            )

            return type(self)._simple_new(new_ndarray, dtype=self.dtype)

    return super().fillna(value, limit=limit, copy=copy)

def isin(self, values: ArrayLike) -> npt.NDArray[np.bool_]:
    """
    Compute boolean array of whether each value is found in the
    passed set of values.

    Parameters
    ----------
    values : np.ndarray or ExtensionArray

    Returns
    -------
    ndarray[bool]
    """
    if values.dtype.kind in "fiuc":
        # TODO: de-duplicate with equals, validate_comparison_value
        return np.zeros(self.shape, dtype=bool)

    values = ensure_wrapped_if_datetimelike(values)

    if not isinstance(values, type(self)):
        if values.dtype == object:
            values = lib.maybe_convert_objects(
                values,  # type: ignore[arg-type]
                convert_non_numeric=True,
                dtype_if_all_nat=self.dtype,
            )
            if values.dtype != object:
                return self.isin(values)
            else:
                # TODO: Deprecate this case
                # https://github.com/pandas-dev/pandas/pull/58645/files#r1604055791
                return isin(self.astype(object), values)
        return np.zeros(self.shape, dtype=bool)

    if self.dtype.kind in "mM":
        self = cast("DatetimeArray | TimedeltaArray", self)
        # Cast to the higher resolution to avoid silently truncating
        #  finer-resolution values, which could lead to false matches.
        self, values = self._ensure_matching_resos(values)

    try:
        # error: Argument 1 to "_check_compatible_with" of "DatetimeLikeArrayMixin"
        # has incompatible type "ExtensionArray | ndarray[Any, Any]"; expected
        # "Period | Timestamp | Timedelta | NaTType"
        self._check_compatible_with(values)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        # Includes tzawareness mismatch and IncompatibleFrequencyError
        return np.zeros(self.shape, dtype=bool)

    # error: Item "ExtensionArray" of "ExtensionArray | ndarray[Any, Any]"
    # has no attribute "asi8"
    return isin(self.asi8, values.asi8)  # type: ignore[union-attr]

def _inferred_freq_str(self) -> str | None:
    """
    Internal version of inferred_freq without deprecation warning.
    """
    if self.ndim != 1:
        return None
    try:
        return frequencies.infer_freq_str(self)
    except ValueError:
        return None

def _cmp_method(self, other, op):
    if self.ndim > 1 and getattr(other, "shape", None) == self.shape:
        # TODO: handle 2D-like listlikes
        return op(self.ravel(), other.ravel()).reshape(self.shape)

    if is_list_like(other):
        if not isinstance(
            other, (list, np.ndarray, ExtensionArray)
        ) and not ops.has_castable_attr(other):
            warnings.warn(
                f"Operation with {type(other).__name__} is deprecated. "
                "In a future version these will be treated as scalar-like. "
                "To retain the old behavior, explicitly wrap in a Series "
                "instead.",
                Pandas4Warning,
                stacklevel=find_stack_level(),
            )

    try:
        other = self._validate_comparison_value(other)
    except InvalidComparison:
        if hasattr(other, "dtype") and isinstance(other.dtype, ArrowDtype):
            return NotImplemented
        return invalid_comparison(self, other, op)

    dtype = getattr(other, "dtype", None)
    if is_object_dtype(dtype):
        # We have to use comp_method_OBJECT_ARRAY instead of numpy
        #  comparison otherwise it would raise when comparing to None
        result = ops.comp_method_OBJECT_ARRAY(
            op, np.asarray(self.astype(object)), other
        )
        return result
    if other is NaT:
        if op is operator.ne:
            result = np.ones(self.shape, dtype=bool)
        else:
            result = np.zeros(self.shape, dtype=bool)
        return result

    if not isinstance(self.dtype, PeriodDtype):
        self = cast("TimelikeOps", self)
        if self._creso != other._creso:
            if not isinstance(other, type(self)):
                # i.e. Timedelta/Timestamp, cast to ndarray and let
                #  compare_mismatched_resolutions handle broadcasting
                try:
                    # GH#52080 see if we can losslessly cast to shared unit
                    other = other.as_unit(self.unit, round_ok=False)
                except ValueError:
                    other_arr = np.array(other.asm8)
                    return compare_mismatched_resolutions(
                        self._ndarray, other_arr, op
                    )
            else:
                other_arr = other._ndarray
                return compare_mismatched_resolutions(self._ndarray, other_arr, op)

    other_vals = self._unbox(other)
    # GH#37462 comparison on i8 values is almost 2x faster than M8/m8
    result = op(self._ndarray.view("i8"), other_vals.view("i8"))

    o_mask = isna(other)
    mask = self._isnan | o_mask
    if mask.any():
        nat_result = op is operator.ne
        np.putmask(result, mask, nat_result)

    return result

def _sub_datetimelike_scalar(
    self, other: datetime | np.datetime64
) -> TimedeltaArray:
    if self.dtype.kind != "M":
        raise TypeError(f"cannot subtract a datelike from a {type(self).__name__}")

    self = cast("DatetimeArray", self)
    # subtract a datetime from myself, yielding an ndarray[timedelta64[ns]]

    if isna(other):
        # i.e. np.datetime64("NaT")
        return self - NaT

    ts = Timestamp(other)

    self, ts = self._ensure_matching_resos(ts)
    return self._sub_datetimelike(ts)

def _sub_datetime_arraylike(self, other: DatetimeArray) -> TimedeltaArray:
    if self.dtype.kind != "M":
        raise TypeError(f"cannot subtract a datelike from a {type(self).__name__}")

    if len(self) != len(other):
        raise ValueError("cannot add indices of unequal length")

    self = cast("DatetimeArray", self)

    self, other = self._ensure_matching_resos(other)
    return self._sub_datetimelike(other)

def __add__(self, other):
    other_dtype = getattr(other, "dtype", None)
    other = ensure_wrapped_if_datetimelike(other)

    # scalar others
    if other is NaT:
        result: np.ndarray | DatetimeLikeArrayMixin = self._add_nat()
    elif isinstance(other, (Tick, timedelta, np.timedelta64)):
        result = self._add_timedeltalike_scalar(other)
    elif isinstance(other, Day) and lib.is_np_dtype(self.dtype, "Mm"):
        # We treat this as Tick-like
        td = Timedelta(days=other.n).as_unit("s")
        result = self._add_timedeltalike_scalar(td)
    elif isinstance(other, BaseOffset):
        # specifically _not_ a Tick
        result = self._add_offset(other)
    elif isinstance(other, (datetime, np.datetime64)):
        result = self._add_datetimelike_scalar(other)
    elif isinstance(other, Period) and lib.is_np_dtype(self.dtype, "m"):
        result = self._add_period(other)
    elif lib.is_integer(other):
        # This check must come after the check for np.timedelta64
        # as is_integer returns True for these
        if not isinstance(self.dtype, PeriodDtype):
            raise integer_op_not_supported(self)
        obj = cast("PeriodArray", self)
        result = obj._addsub_int_array_or_scalar(other * obj.dtype._n, operator.add)

    # array-like others
    elif lib.is_np_dtype(other_dtype, "m"):
        # TimedeltaIndex, ndarray[timedelta64]
        result = self._add_timedelta_arraylike(other)
    elif is_object_dtype(other_dtype):
        # e.g. Array/Index of DateOffset objects
        result = self._addsub_object_array(other, operator.add)
    elif lib.is_np_dtype(other_dtype, "M") or isinstance(
        other_dtype, DatetimeTZDtype
    ):
        # DatetimeIndex, ndarray[datetime64]
        return self._add_datetime_arraylike(other)
    elif is_integer_dtype(other_dtype):
        if not isinstance(self.dtype, PeriodDtype):
            raise integer_op_not_supported(self)
        obj = cast("PeriodArray", self)
        result = obj._addsub_int_array_or_scalar(other * obj.dtype._n, operator.add)
    elif other_dtype is not None and other_dtype.kind == "b":
        # GH#68452 is_integer_dtype is False for bool, so without this bool
        #  operands fall through to numpy, which reads True as a one-unit
        #  timedelta.  Period, where ints are legal, keeps its object-path raise
        if isinstance(self.dtype, PeriodDtype):
            return NotImplemented
        raise integer_op_not_supported(self)
    else:
        # Includes Categorical, other ExtensionArrays
        # For PeriodDtype, if self is a TimedeltaArray and other is a
        #  PeriodArray with  a timedelta-like (i.e. Tick) freq, this
        #  operation is valid.  Defer to the PeriodArray implementation.
        #  In remaining cases, this will end up raising TypeError.
        return NotImplemented

    if isinstance(result, np.ndarray) and lib.is_np_dtype(result.dtype, "m"):
        from pandas.core.arrays import TimedeltaArray

        return TimedeltaArray._from_sequence(result, dtype=result.dtype)
    return result

def __sub__(self, other):
    other_dtype = getattr(other, "dtype", None)
    other = ensure_wrapped_if_datetimelike(other)

    # scalar others
    if other is NaT:
        result: np.ndarray | DatetimeLikeArrayMixin = self._sub_nat()
    elif isinstance(other, (Tick, timedelta, np.timedelta64)):
        result = self._add_timedeltalike_scalar(-other)
    elif isinstance(other, Day) and lib.is_np_dtype(self.dtype, "Mm"):
        # We treat this as Tick-like
        td = Timedelta(days=other.n).as_unit("s")
        result = self._add_timedeltalike_scalar(-td)
    elif isinstance(other, BaseOffset):
        # specifically _not_ a Tick
        result = self._add_offset(-other)
    elif isinstance(other, (datetime, np.datetime64)):
        result = self._sub_datetimelike_scalar(other)
    elif lib.is_integer(other):
        # This check must come after the check for np.timedelta64
        # as is_integer returns True for these
        if not isinstance(self.dtype, PeriodDtype):
            raise integer_op_not_supported(self)
        obj = cast("PeriodArray", self)
        result = obj._addsub_int_array_or_scalar(other * obj.dtype._n, operator.sub)

    elif isinstance(other, Period):
        result = self._sub_periodlike(other)

    # array-like others
    elif lib.is_np_dtype(other_dtype, "m"):
        # TimedeltaIndex, ndarray[timedelta64]
        result = self._add_timedelta_arraylike(-other)
    elif is_object_dtype(other_dtype):
        # e.g. Array/Index of DateOffset objects
        result = self._addsub_object_array(other, operator.sub)
    elif lib.is_np_dtype(other_dtype, "M") or isinstance(
        other_dtype, DatetimeTZDtype
    ):
        # DatetimeIndex, ndarray[datetime64]
        result = self._sub_datetime_arraylike(other)
    elif isinstance(other_dtype, PeriodDtype):
        # PeriodIndex
        result = self._sub_periodlike(other)
    elif is_integer_dtype(other_dtype):
        if not isinstance(self.dtype, PeriodDtype):
            raise integer_op_not_supported(self)
        obj = cast("PeriodArray", self)
        result = obj._addsub_int_array_or_scalar(other * obj.dtype._n, operator.sub)
    elif other_dtype is not None and other_dtype.kind == "b":
        # GH#68452, see __add__
        if isinstance(self.dtype, PeriodDtype):
            return NotImplemented
        raise integer_op_not_supported(self)
    else:
        # Includes ExtensionArrays, float_dtype
        return NotImplemented

    if isinstance(result, np.ndarray) and lib.is_np_dtype(result.dtype, "m"):
        from pandas.core.arrays import TimedeltaArray

        return TimedeltaArray._from_sequence(result, dtype=result.dtype)
    return result

def median(self, *, axis: AxisInt | None = None, skipna: bool = True, **kwargs):
    nv.validate_median((), kwargs)

    if axis is not None and abs(axis) >= self.ndim:
        raise ValueError("abs(axis) must be less than ndim")

    result = nanops.nanmedian(self._ndarray, axis=axis, skipna=skipna)
    return self._wrap_reduction_result(axis, result)

def __iter__(self) -> Iterator:
    if self.ndim > 1:
        for i in range(len(self)):
            yield self[i]
    else:
        # convert in chunks of 10k for efficiency
        data = self._ndarray
        length = len(self)
        chunksize = _ITER_CHUNKSIZE
        chunks = (length // chunksize) + 1
        for i in range(chunks):
            start_i = i * chunksize
            end_i = min((i + 1) * chunksize, length)
            yield from self._iter_convert_chunk(data[start_i:end_i])

def _ensure_matching_resos(self, other):
    if self._creso != other._creso:
        # Just as with Timestamp/Timedelta, we cast to the higher resolution
        if self._creso < other._creso:
            self = self.as_unit(other.unit)
        else:
            other = other.as_unit(self.unit)
    return self, other

def __array_ufunc__(self, ufunc: np.ufunc, method: str, *inputs, **kwargs):
    if (
        ufunc in [np.isnan, np.isinf, np.isfinite]
        and len(inputs) == 1
        and inputs[0] is self
    ):
        # numpy 1.18 changed isinf and isnan to not raise on dt64/td64
        return getattr(ufunc, method)(self._ndarray, **kwargs)

    return super().__array_ufunc__(ufunc, method, *inputs, **kwargs)

def _round(self, freq, mode, ambiguous, nonexistent):
    # round the local times
    if isinstance(self.dtype, DatetimeTZDtype):
        # operate on naive timestamps, then convert back to aware
        self = cast("DatetimeArray", self)
        naive = self.tz_localize(None)
        result = naive._round(freq, mode, ambiguous, nonexistent)
        return result.tz_localize(
            self.tz, ambiguous=ambiguous, nonexistent=nonexistent
        )

    values = self.view("i8")
    values = cast("np.ndarray", values)
    nanos = get_unit_for_round(freq, self._creso)
    if nanos == 0:
        # GH 52761
        return self.copy()
    result_i8 = round_nsint64(values, mode, nanos)
    result = self._maybe_mask_results(result_i8, fill_value=iNaT)
    result = result.view(self._ndarray.dtype)
    return self._simple_new(result, dtype=self.dtype)

def __init__(
    self, values: np.ndarray | NumpyExtensionArray, copy: bool = False
) -> None:
    if isinstance(values, type(self)):
        values = values._ndarray
    if not isinstance(values, np.ndarray):
        raise ValueError(
            f"'values' must be a NumPy array, not {type(values).__name__}"
        )

    if values.ndim == 0:
        # Technically we support 2, but do not advertise that fact.
        raise ValueError("NumpyExtensionArray must be 1-dimensional.")

    if copy:
        values = values.copy()

    dtype = NumpyEADtype(values.dtype)
    super().__init__(values, dtype)

def _from_sequence(
    cls, scalars, *, dtype: Dtype | None = None, copy: bool = False
) -> NumpyExtensionArray:
    if isinstance(dtype, NumpyEADtype):
        dtype = dtype._dtype
    if dtype is not None:
        dtype = np.dtype(dtype)  # type: ignore[arg-type]

    if dtype is not None and dtype.kind in "iu":
        # GH#41724 - validate NaN before casting float -> int
        result = np.asarray(scalars)
        if np.issubdtype(result.dtype, np.floating):
            result = astype_float_to_int_nansafe(result, dtype, copy=copy)
        else:
            result = np.asarray(scalars, dtype=dtype)
    else:
        result = np.asarray(scalars, dtype=dtype)
    if (
        result.ndim > 1
        and not hasattr(scalars, "dtype")
        and (dtype is None or dtype == object)
    ):
        # e.g. list-of-tuples
        result = construct_1d_object_array_from_listlike(scalars)

    if copy and result is scalars:
        result = result.copy()
    return cls(result)

def _validate_setitem_value(self, value):
    if isinstance(value, type(self)):
        value = value._ndarray

    # Match Block._standardize_fill_value behavior
    if self._ndarray.dtype.kind != "O" and is_valid_na_for_dtype(
        value, self._ndarray.dtype
    ):
        value = self.dtype.na_value

    try:
        return np_can_hold_element(self._ndarray.dtype, value)
    except LossySetitemError as err:
        raise TypeError(
            f"Invalid value '{value!s}' for dtype '{self.dtype}'"
        ) from err
    except NotImplementedError:
        # np_can_hold_element doesn't handle all dtypes (e.g. "U"),
        # fall back to no validation for those.
        return value

def _cast_pointwise_result(self, values) -> ArrayLike:
    result = super()._cast_pointwise_result(values)
    lkind = self.dtype.kind
    rkind = result.dtype.kind
    if (
        (lkind in "iu" and rkind in "iu")
        or (lkind == "f" and rkind == "f")
        or (lkind == rkind == "c")
    ):
        result = maybe_downcast_to_dtype(result, self.dtype.numpy_dtype)
    elif rkind in "Mm":
        # Ensure potential subsequent .astype(object) doesn't incorrectly
        #  convert Timestamps/Timedeltas to ints
        from pandas import array as pd_array

        result = pd_array(result, copy=False)
    if isinstance(result, np.ndarray) and isinstance(self.dtype, NumpyEADtype):
        # Subclasses like StringArray have their own validation;
        # only wrap for plain NumpyEADtype.
        result = type(self)(result)
    return result

def __array__(
    self, dtype: np.dtype | None = None, copy: bool | None = None
) -> np.ndarray:
    if copy is not None:
        # Note: branch avoids `copy=None` for NumPy 1.x support
        result = np.array(self._ndarray, dtype=dtype, copy=copy)
    else:
        result = np.asarray(self._ndarray, dtype=dtype)

    if (
        self._readonly
        and not copy
        and (dtype is None or astype_is_view(self.dtype, dtype))
    ):
        result = result.view()
        result.flags.writeable = False

    return result

def __array_ufunc__(self, ufunc: np.ufunc, method: str, *inputs, **kwargs):
    # Lightly modified version of
    # https://numpy.org/doc/stable/reference/generated/numpy.lib.mixins.NDArrayOperatorsMixin.html
    # The primary modification is not boxing scalar return values
    # in NumpyExtensionArray, since pandas' ExtensionArrays are 1-d.

    # this path never reaches ExtensionArray.__array_ufunc__
    ops.disallow_datetimelike_logical_ufunc(ufunc, inputs)

    out = kwargs.get("out", ())

    result = arraylike.maybe_dispatch_ufunc_to_dunder_op(
        self, ufunc, method, *inputs, **kwargs
    )
    if result is not NotImplemented:
        return result

    if "out" in kwargs:
        # e.g. test_ufunc_unary
        return arraylike.dispatch_ufunc_with_out(
            self, ufunc, method, *inputs, **kwargs
        )

    if method == "reduce":
        result = arraylike.dispatch_reduction_ufunc(
            self, ufunc, method, *inputs, **kwargs
        )
        if result is not NotImplemented:
            # e.g. tests.series.test_ufunc.TestNumpyReductions
            return result

    # Defer to the implementation of the ufunc on unwrapped values.
    inputs = tuple(
        x._ndarray if isinstance(x, NumpyExtensionArray) else x for x in inputs
    )
    if out:
        kwargs["out"] = tuple(
            x._ndarray if isinstance(x, NumpyExtensionArray) else x for x in out
        )
    result = getattr(ufunc, method)(*inputs, **kwargs)

    if ufunc.nout > 1:
        # multiple return values; re-box array-like results
        return tuple(type(self)(x) for x in result)
    elif method == "at":
        # no return value
        return None
    elif method == "reduce":
        if isinstance(result, np.ndarray):
            # e.g. test_np_reduce_2d
            return type(self)(result)

        # e.g. test_np_max_nested_tuples
        return result
    else:
        if self.dtype.type is str:  # type: ignore[comparison-overlap]
            # StringDtype
            self = cast("StringArray", self)
            try:
                # specify dtype to preserve storage/na_value
                return type(self)(result, dtype=self.dtype)
            except ValueError:
                # if validation of input fails (no strings)
                # -> fallback to returning raw numpy array
                return result
        # one return value; re-box array-like results
        return type(self)(result)

def astype(self, dtype, copy: bool = True):
    dtype = pandas_dtype(dtype)

    if dtype == self.dtype:
        if copy:
            return self.copy()
        return self

    result = astype_array(self._ndarray, dtype=dtype, copy=copy)
    return result

def to_numpy(
    self,
    dtype: npt.DTypeLike | None = None,
    copy: bool = False,
    na_value: object = lib.no_default,
) -> np.ndarray:
    if na_value is not lib.no_default and (mask := self.isna()).any():
        result = self._ndarray.copy()
        result[mask] = na_value
    else:
        result = self._ndarray
        if not copy and self._readonly:
            result = result.view()
            result.flags.writeable = False

    result = np.asarray(result, dtype=dtype)

    if copy and result is self._ndarray:
        result = result.copy()

    return result

def _cmp_method(self, other, op):
    if isinstance(other, NumpyExtensionArray):
        other = other._ndarray

    other = ops.maybe_prepare_scalar_for_op(other, (len(self),))
    pd_op = ops.get_array_op(op)
    other = ensure_wrapped_if_datetimelike(other)
    result = pd_op(self._ndarray, other)

    if op is divmod or op is ops.rdivmod:
        a, b = result
        if isinstance(a, np.ndarray):
            # for e.g. op vs TimedeltaArray, we may already
            #  have an ExtensionArray, in which case we do not wrap
            return self._wrap_ndarray_result(a), self._wrap_ndarray_result(b)
        return a, b

    if isinstance(result, np.ndarray):
        # for e.g. multiplication vs TimedeltaArray, we may already
        #  have an ExtensionArray, in which case we do not wrap
        return self._wrap_ndarray_result(result)
    return result

def _wrap_ndarray_result(self, result: np.ndarray):
    # If we have timedelta64[ns] result, return a TimedeltaArray instead
    #  of a NumpyExtensionArray
    if result.dtype.kind == "m" and is_supported_dtype(result.dtype):
        from pandas.core.arrays import TimedeltaArray

        return TimedeltaArray._simple_new(result, dtype=result.dtype)
    return type(self)(result)

def _formatter(self, boxed: bool = False) -> Callable[[Any], str | None]:
    # NEP 51: https://github.com/numpy/numpy/pull/22449
    if self.dtype.kind == "U":
        # not "S": str(np.bytes_(b"foo")) is already "b'foo'"
        return "'{}'".format
    elif self.dtype == "object":
        return repr
    else:
        return str

def _validate_td64_dtype(dtype) -> DtypeObj:
    dtype = pandas_dtype(dtype)
    if dtype == np.dtype("m8"):
        # no precision disallowed GH#24806
        msg = (
            "Passing in 'timedelta' dtype with no precision is not allowed. "
            "Please pass in 'timedelta64[ns]' instead."
        )
        raise ValueError(msg)

    if not lib.is_np_dtype(dtype, "m"):
        raise ValueError(f"dtype '{dtype}' is invalid, should be np.timedelta64 dtype")
    elif not is_supported_dtype(dtype):
        raise ValueError("Supported timedelta64 resolutions are 's', 'ms', 'us', 'ns'")

    return dtype

def _from_sequence(cls, data, *, dtype=None, copy: bool = False) -> Self:
    if dtype:
        dtype = _validate_td64_dtype(dtype)

    data, copy = dtl.ensure_arraylike_for_datetimelike(
        data, copy, cls_name="TimedeltaArray"
    )

    unit = None
    if dtype is not None:
        if data.dtype == object:
            # GH#68639 the unit applies to the numeric entries, matching
            #  to_timedelta(data, unit=...), except that a str alongside
            #  them would make array_to_timedelta64 reject the unit
            apply_unit = not contains_str(data)
        else:
            apply_unit = data.dtype.kind in "iuf"
        if apply_unit:
            unit = np.datetime_data(dtype)[0]

    data = sequence_to_td64ns(data, copy=copy, unit=unit)

    if dtype is not None:
        data = astype_overflowsafe(data, dtype=dtype, copy=False)

    return cls._simple_new(data, dtype=data.dtype)

def _generate_range(
    cls, start, end, periods, freq, closed=None, *, unit: TimeUnit
) -> Self:
    periods = dtl.validate_periods(periods)
    if freq is None and any(x is None for x in [periods, start, end]):
        raise ValueError("Must provide freq argument if no data is supplied")

    if com.count_not_none(start, end, periods, freq) != 3:
        raise ValueError(
            "Of the four parameters: start, end, periods, "
            "and freq, exactly three must be specified"
        )

    if start is not None:
        start = Timedelta(start).as_unit("ns")

    if end is not None:
        end = Timedelta(end).as_unit("ns")

    if unit not in ["s", "ms", "us", "ns"]:
        raise ValueError("'unit' must be one of 's', 'ms', 'us', 'ns'")

    if start is not None and unit is not None:
        start = start.as_unit(unit, round_ok=False)
    if end is not None and unit is not None:
        end = end.as_unit(unit, round_ok=False)

    left_closed, right_closed = validate_endpoints(closed)

    if freq is not None:
        index = generate_regular_range(start, end, periods, freq, unit=unit)
    else:
        index = np.linspace(start._value, end._value, periods).astype("i8")

    if not left_closed:
        index = index[1:]
    if not right_closed:
        index = index[:-1]

    td64values = index.view(f"m8[{unit}]")
    return cls._simple_new(td64values, dtype=td64values.dtype)

def _unbox_scalar(self, value) -> np.timedelta64:
    if not isinstance(value, self._scalar_type) and value is not NaT:
        raise ValueError("'value' should be a Timedelta.")
    self._check_compatible_with(value)
    if value is NaT:
        return np.timedelta64(value._value, self.unit)
    else:
        #  error: Incompatible return value type (got "timedelta64[timedelta |
        # int | None] | datetime64[date | int | None]",
        # expected "timedelta64[timedelta | int | None]")
        return value.as_unit(self.unit, round_ok=False).asm8  # type: ignore[return-value]

def astype(self, dtype, copy: bool = True):
    # We handle
    #   --> timedelta64[ns]
    #   --> timedelta64
    # DatetimeLikeArrayMixin super call handles other cases
    dtype = pandas_dtype(dtype)

    if lib.is_np_dtype(dtype, "m"):
        if dtype == self.dtype:
            if copy:
                return self.copy()
            return self

        if is_supported_dtype(dtype):
            # unit conversion e.g. timedelta64[s]
            res_values = astype_overflowsafe(self._ndarray, dtype, copy=False)
            return type(self)._simple_new(res_values, dtype=res_values.dtype)
        else:
            raise ValueError(
                f"Cannot convert from {self.dtype} to {dtype}. "
                "Supported resolutions are 's', 'ms', 'us', 'ns'"
            )

    return dtl.DatetimeLikeArrayMixin.astype(self, dtype, copy=copy)

def std(
    self,
    *,
    axis: AxisInt | None = None,
    dtype: NpDtype | None = None,
    out=None,
    ddof: int = 1,
    keepdims: bool = False,
    skipna: bool = True,
):
    nv.validate_stat_ddof_func(
        (), {"dtype": dtype, "out": out, "keepdims": keepdims}, fname="std"
    )

    result = nanops.nanstd(self._ndarray, axis=axis, skipna=skipna, ddof=ddof)
    if axis is None or self.ndim == 1:
        return self._box_func(result)
    return self._from_backing_data(result)

def _accumulate(self, name: str, *, skipna: bool = True, **kwargs):
    if name == "cumsum":
        op = getattr(datetimelike_accumulations, name)
        result = op(self._ndarray.copy(), skipna=skipna, **kwargs)

        return type(self)._simple_new(result, dtype=self.dtype)
    elif name == "cumprod":
        raise TypeError("cumprod not supported for Timedelta.")

    else:
        return super()._accumulate(name, skipna=skipna, **kwargs)

def __mul__(self, other) -> Self:
    if is_scalar(other):
        if lib.is_bool(other):
            raise TypeError(
                f"Cannot multiply '{self.dtype}' by bool, explicitly cast to "
                "integers instead"
            )
        other = _exact_if_integral(other)
        if lib.is_integer(other):
            # GH#43178: detect int64 overflow rather than silently wrapping
            #  in the i8 cast below (e.g. a multiplier outside int64 bounds).
            # TODO(numpy>=2.5): numpy detects this natively (numpy GH-31378)
            #  but raises OverflowError; once the numpy floor is >= 2.5, drop
            #  mul_overflowsafe and re-wrap numpy's error as
            #  OutOfBoundsTimedelta. The non-integral float path isn't
            #  covered and stays.
            other = int(other)
            if other > lib.i8max or other < -lib.i8max - 1:
                raise OutOfBoundsTimedelta("Overflow in int64 multiplication")
            i8_vals = self.asi8
            if other != 0 and i8_vals.size:
                # The extreme elements bound all products, so checking them
                #  with exact Python-int arithmetic lets the common
                #  no-overflow case use a vectorized multiply. NaT
                #  (int64.min) always trips the bound, falling through to
                #  the NaT-aware cython loop.
                low_prod = int(i8_vals.min()) * other
                high_prod = int(i8_vals.max()) * other
                if max(abs(low_prod), abs(high_prod)) <= lib.i8max:
                    result = (i8_vals * other).view(self._ndarray.dtype)
                    return type(self)._simple_new(result, dtype=result.dtype)
            return self._mul_int_overflowsafe(np.asarray(other, dtype="i8"))
        if lib.is_float(other):
            return self._mul_float_overflowsafe(other)
        # numpy will raise TypeError for non-numeric scalar
        result = self._ndarray * other
        if result.dtype.kind != "m":
            # numpy >= 2.1 may not raise a TypeError
            # and seems to dispatch to others.__rmul__?
            raise TypeError(f"Cannot multiply with {type(other).__name__}")
        return type(self)._simple_new(result, dtype=result.dtype)

    if not hasattr(other, "dtype"):
        # list, tuple
        other = np.array(other)

    if other.dtype.kind == "b":
        # GH#58054
        raise TypeError(
            f"Cannot multiply '{self.dtype}' by bool, explicitly cast to "
            "integers instead"
        )
    if isinstance(other.dtype, (ArrowDtype, BaseMaskedDtype)):
        # GH#58054
        return NotImplemented

    if len(other) != len(self) and not lib.is_np_dtype(other.dtype, "m"):
        # Exclude timedelta64 here so we correctly raise TypeError
        #  for that instead of ValueError
        raise ValueError("Cannot multiply with unequal lengths")

    if is_object_dtype(other.dtype):
        # this multiplication will succeed only if all elements of other
        #  are int or float scalars, so we will end up with
        #  timedelta64[ns]-dtyped result
        arr = self._ndarray
        obj_result = np.array([arr[n] * other[n] for n in range(len(self))])
        return type(self)._simple_new(obj_result, dtype=obj_result.dtype)

    if other.dtype.kind in "iu":
        # GH#43178: detect int64 overflow rather than silently wrapping.
        #  Cast to int64 first: an unsigned multiplier above int64.max wraps
        #  to negative, which we detect by sign. We check the sign rather
        #  than ``other > i8max`` because comparing a broadcast unsigned
        #  array to a Python int segfaults on numpy < 2.2 (hit via the
        #  DataFrame blockwise path).
        i8_other = other.astype("i8", copy=False)
        if other.dtype.kind == "u" and (i8_other < 0).any():
            raise OutOfBoundsTimedelta("Overflow in int64 multiplication")
        return self._mul_int_overflowsafe(i8_other)

    if other.dtype.kind == "f":
        return self._mul_float_overflowsafe(other)

    # numpy will raise TypeError for non-numeric dtype
    result = self._ndarray * other
    if result.dtype.kind != "m":
        # numpy >= 2.1 may not raise a TypeError
        # and seems to dispatch to others.__rmul__?
        raise TypeError(f"Cannot multiply with {type(other).__name__}")
    return type(self)._simple_new(result, dtype=result.dtype)

def _scalar_divlike_op(self, other, op):
    """
    Shared logic for __truediv__, __rtruediv__, __floordiv__, __rfloordiv__
    with scalar 'other'.
    """
    if isinstance(other, self._recognized_scalars):
        other = Timedelta(other)
        # mypy assumes that __new__ returns an instance of the class
        # github.com/python/mypy/issues/1020
        if cast("Timedelta | NaTType", other) is NaT:
            # specifically timedelta64-NaT
            res = np.empty(self.shape, dtype=np.float64)
            res.fill(np.nan)
            return res

        # otherwise, dispatch to Timedelta implementation
        return op(self._ndarray, other)

    else:
        # caller is responsible for checking lib.is_scalar(other)
        # assume other is numeric, otherwise numpy will raise

        if op in [roperator.rtruediv, roperator.rfloordiv]:
            raise TypeError(
                f"Cannot divide {type(other).__name__} by {type(self).__name__}"
            )

        other = _exact_if_integral(other)
        if lib.is_float(other):
            # GH#43178: raise instead of silently saturating on overflow
            self._check_float_div_overflow(other)
        result = op(self._ndarray, other)
        return type(self)._simple_new(result, dtype=result.dtype)

def _cast_divlike_op(self, other):
    if not hasattr(other, "dtype"):
        # e.g. list, tuple
        other = np.array(other)

    if len(other) != len(self):
        raise ValueError("Cannot divide vectors with unequal lengths")
    return other

def __truediv__(self, other):
    # timedelta / X is well-defined for timedelta-like or numeric X
    op = operator.truediv
    if is_scalar(other):
        return self._scalar_divlike_op(other, op)

    other = self._cast_divlike_op(other)
    if (
        lib.is_np_dtype(other.dtype, "m")
        or is_integer_dtype(other.dtype)
        or is_float_dtype(other.dtype)
    ):
        return self._vector_divlike_op(other, op)

    if is_object_dtype(other.dtype):
        other = np.asarray(other)
        if self.ndim > 1:
            res_cols = [
                left / right for left, right in zip(self, other, strict=True)
            ]
            res_cols2 = [x.reshape(1, -1) for x in res_cols]
            result = np.concatenate(res_cols2, axis=0)
        else:
            result = truediv_object_array(self._ndarray, other)

        return result

    else:
        return NotImplemented

def __rtruediv__(self, other):
    # X / timedelta is defined only for timedelta-like X
    op = roperator.rtruediv
    if is_scalar(other):
        return self._scalar_divlike_op(other, op)

    other = self._cast_divlike_op(other)
    if lib.is_np_dtype(other.dtype, "m"):
        return self._vector_divlike_op(other, op)

    elif is_object_dtype(other.dtype):
        # Note: unlike in __truediv__, we do not _need_ to do type
        #  inference on the result.  It does not raise, a numeric array
        #  is returned.  GH#23829
        result_list = [other[n] / self[n] for n in range(len(self))]
        return np.array(result_list)

    else:
        return NotImplemented

def __floordiv__(self, other):
    op = operator.floordiv
    if is_scalar(other):
        return self._scalar_divlike_op(other, op)

    other = self._cast_divlike_op(other)
    if (
        lib.is_np_dtype(other.dtype, "m")
        or is_integer_dtype(other.dtype)
        or is_float_dtype(other.dtype)
    ):
        return self._vector_divlike_op(other, op)

    elif is_object_dtype(other.dtype):
        other = np.asarray(other)
        if self.ndim > 1:
            res_cols = [
                left // right for left, right in zip(self, other, strict=True)
            ]
            res_cols2 = [x.reshape(1, -1) for x in res_cols]
            result = np.concatenate(res_cols2, axis=0)
        else:
            result = floordiv_object_array(self._ndarray, other)

        assert result.dtype == object
        return result

    else:
        return NotImplemented

def __rfloordiv__(self, other):
    op = roperator.rfloordiv
    if is_scalar(other):
        return self._scalar_divlike_op(other, op)

    other = self._cast_divlike_op(other)
    if lib.is_np_dtype(other.dtype, "m"):
        return self._vector_divlike_op(other, op)

    elif is_object_dtype(other.dtype):
        result_list = [other[n] // self[n] for n in range(len(self))]
        result = np.array(result_list)
        return result

    else:
        return NotImplemented

def _maybe_normalize_endpoints(
    start: _TimestampNoneT1, end: _TimestampNoneT2, normalize: bool
) -> tuple[_TimestampNoneT1, _TimestampNoneT2]:
    if normalize:
        if start is not None:
            start = start.normalize()

        if end is not None:
            end = end.normalize()

    return start, end

def _validate_dtype(cls, values, dtype):
    # used in TimeLikeOps.__init__
    dtype = _validate_dt64_dtype(dtype)
    _validate_dt64_dtype(values.dtype)
    if isinstance(dtype, np.dtype):
        if values.dtype != dtype:
            raise ValueError("Values resolution does not match dtype.")
    else:
        vunit = np.datetime_data(values.dtype)[0]
        if vunit != dtype.unit:
            raise ValueError("Values resolution does not match dtype.")
    return dtype

def _unbox_scalar(self, value) -> np.datetime64:
    if not isinstance(value, self._scalar_type) and value is not NaT:
        raise ValueError("'value' should be a Timestamp.")
    self._check_compatible_with(value)
    if value is NaT:
        return np.datetime64(value._value, self.unit)
    else:
        return value.as_unit(self.unit, round_ok=False).asm8

def astype(self, dtype, copy: bool = True):
    # We handle
    #   --> datetime
    #   --> period
    # DatetimeLikeArrayMixin Super handles the rest.
    dtype = pandas_dtype(dtype)

    if dtype == self.dtype:
        if copy:
            return self.copy()
        return self

    elif isinstance(dtype, ExtensionDtype):
        if not isinstance(dtype, DatetimeTZDtype):
            # e.g. Sparse[datetime64[ns]]
            return super().astype(dtype, copy=copy)
        elif self.tz is None:
            # pre-2.0 this did self.tz_localize(dtype.tz), which did not match
            #  the Series behavior which did
            #  values.tz_localize("UTC").tz_convert(dtype.tz)
            raise TypeError(
                "Cannot use .astype to convert from timezone-naive dtype to "
                "timezone-aware dtype. Use obj.tz_localize instead or "
                "series.dt.tz_localize instead"
            )
        else:
            # tzaware unit conversion e.g. datetime64[s, UTC]
            np_dtype = np.dtype(dtype.str)
            res_values = astype_overflowsafe(self._ndarray, np_dtype, copy=copy)
            return type(self)._simple_new(res_values, dtype=dtype)

    elif (
        self.tz is None
        and lib.is_np_dtype(dtype, "M")
        and not is_unitless(dtype)
        and is_supported_dtype(dtype)
    ):
        # unit conversion e.g. datetime64[s]
        res_values = astype_overflowsafe(self._ndarray, dtype, copy=True)
        return type(self)._simple_new(res_values, dtype=res_values.dtype)
        # TODO: preserve freq?

    elif self.tz is not None and lib.is_np_dtype(dtype, "M"):
        # pre-2.0 behavior for DTA/DTI was
        #  values.tz_convert("UTC").tz_localize(None), which did not match
        #  the Series behavior
        raise TypeError(
            "Cannot use .astype to convert from timezone-aware dtype to "
            "timezone-naive dtype. Use obj.tz_localize(None) or "
            "obj.tz_convert('UTC').tz_localize(None) instead."
        )

    elif (
        self.tz is None
        and lib.is_np_dtype(dtype, "M")
        and dtype != self.dtype
        and is_unitless(dtype)
    ):
        raise TypeError(
            "Casting to unit-less dtype 'datetime64' is not supported. "
            "Pass e.g. 'datetime64[ns]' instead."
        )

    elif isinstance(dtype, PeriodDtype):
        return self.to_period(freq=dtype.freq)
    return dtl.DatetimeLikeArrayMixin.astype(self, dtype, copy)

def _format_native_types(
    self, *, na_rep: str | float = "NaT", date_format=None, **kwargs
) -> npt.NDArray[np.object_]:
    if date_format is None and self._is_dates_only:
        # Only dates and no timezone: provide a default format
        date_format = "%Y-%m-%d"

    return tslib.format_array_from_datetime(
        self.asi8, tz=self.tz, format=date_format, na_rep=na_rep, reso=self._creso

def _assert_tzawareness_compat(self, other) -> None:
    # adapted from _Timestamp._assert_tzawareness_compat
    other_tz = getattr(other, "tzinfo", None)
    other_dtype = getattr(other, "dtype", None)

    if isinstance(other_dtype, DatetimeTZDtype):
        # Get tzinfo from Series dtype
        other_tz = other.dtype.tz
    if other is NaT:
        # pd.NaT quacks both aware and naive
        pass
    elif self.tz is None:
        if other_tz is not None:
            raise TypeError(
                "Cannot compare tz-naive and tz-aware datetime-like objects."
            )
    elif other_tz is None:
        raise TypeError(
            "Cannot compare tz-naive and tz-aware datetime-like objects"

def _add_offset(self, offset: BaseOffset) -> Self:
    assert not isinstance(offset, Tick)

    # For pure-timedelta DateOffset with tz-aware data, add to UTC values
    # directly to avoid nonexistent/ambiguous time errors from
    # re-localizing wall-time results near DST (GH#28610).
    if (
        self.tz is not None
        and isinstance(offset, RelativeDeltaOffset)
        and not offset._use_relativedelta
    ):
        # GH#64806 _add_timedeltalike_scalar casts to the finer of the two
        # resolutions, so the result keeps offset._pd_timedelta's unit when
        # that is finer than self's.
        result = self._add_timedeltalike_scalar(offset._pd_timedelta)
        if offset.normalize:
            result = result.normalize()
        return result

    if self.tz is not None:
        values = self.tz_localize(None)
    else:
        values = self

    try:
        res_values = offset._add_datetime_ndarray(values._ndarray)
        if res_values.dtype.kind == "i":
            # values is tz-naive here, so its dtype is the ndarray's
            res_values = res_values.view(values._ndarray.dtype)
    except NotImplementedError:
        if config["mode"]["performance_warnings"]:
            warnings.warn(
                "Non-vectorized DateOffset being applied to Series or "
                "DatetimeIndex.",
                PerformanceWarning,
                stacklevel=find_stack_level(),
            )
        res_values = self.astype("O") + offset
        # GH#56586 use the finer resolution between self and offset.offset
        # to avoid truncating sub-unit precision
        res_unit = self.unit
        if hasattr(offset, "offset") and offset.offset:
            offset_unit = Timedelta(offset.offset).unit
            if abbrev_to_npy_unit(offset_unit) > abbrev_to_npy_unit(res_unit):
                res_unit = offset_unit
        dtype = tz_to_dtype(self.tz, unit=res_unit)
        result = type(self)._from_sequence(res_values, dtype=dtype)

    else:
        result = type(self)._simple_new(res_values, dtype=res_values.dtype)
        if offset.normalize:
            result = result.normalize()

        if self.tz is not None:
            result = result.tz_localize(self.tz)

    return result

def _reduce(
    self, name: str, *, skipna: bool = True, keepdims: bool = False, **kwargs
):
    result = super()._reduce(name, skipna=skipna, keepdims=keepdims, **kwargs)
    if keepdims and isinstance(result, np.ndarray):
        if name == "std":
            from pandas.core.arrays import TimedeltaArray

            return TimedeltaArray._from_sequence(result)
        else:
            return self._from_sequence(result, dtype=self.dtype)
    return result

def __getitem__(self, key: PositionalIndexer) -> Self | IntervalOrNA:
    key = check_array_indexer(self, key)
    left = self._left[key]
    right = self._right[key]

    if not isinstance(left, (np.ndarray, ExtensionArray)):
        # scalar
        if is_scalar(left) and isna(left):
            return self._fill_value
        return Interval(left, right, self.closed)
    if np.ndim(left) > 1:
        # GH#30588 multi-dimensional indexer disallowed
        raise ValueError("multi-dimensional indexing not allowed")
    # Argument 2 to "_simple_new" of "IntervalArray" has incompatible type
    # "Union[Period, Timestamp, Timedelta, NaTType, DatetimeArray, TimedeltaArray,
    # ndarray[Any, Any]]"; expected "Union[Union[DatetimeArray, TimedeltaArray],
    # ndarray[Any, Any]]"
    result = self._simple_new(left, right, dtype=self.dtype)  # type: ignore[arg-type]
    if getitem_returns_view(self, key):
        result._readonly = self._readonly
    return result

def argsort(
    self,
    *,
    ascending: bool = True,
    kind: SortKind = "quicksort",
    na_position: str = "last",
    **kwargs,
) -> np.ndarray:
    ascending = nv.validate_argsort_with_ascending(ascending, (), kwargs)

    if ascending and kind == "quicksort" and na_position == "last":
        # TODO: in an IntervalIndex we can reuse the cached
        #  IntervalTree.left_sorter
        return np.lexsort((self.right, self.left))

    # TODO: other cases we can use lexsort for?  much more performant.
    return super().argsort(
        ascending=ascending, kind=kind, na_position=na_position, **kwargs

def min(self, *, axis: AxisInt | None = None, skipna: bool = True) -> IntervalOrNA:
    nv.validate_minmax_axis(axis, self.ndim)

    if not len(self):
        return self._na_value

    mask = self.isna()
    if mask.any():
        if not skipna:
            return self._na_value
        obj = self[~mask]
    else:
        obj = self

    indexer = obj.argsort()[0]
    return obj[indexer]

def max(self, *, axis: AxisInt | None = None, skipna: bool = True) -> IntervalOrNA:
    nv.validate_minmax_axis(axis, self.ndim)

    if not len(self):
        return self._na_value

    mask = self.isna()
    if mask.any():
        if not skipna:
            return self._na_value
        obj = self[~mask]
    else:
        obj = self

    indexer = obj.argsort()[-1]
    return obj[indexer]

def astype(self, dtype, copy: bool = True):
    """
    Cast to an ExtensionArray or NumPy array with dtype 'dtype'.

    Parameters
    ----------
    dtype : str or dtype
        Typecode or data-type to which the array is cast.

    copy : bool, default True
        Whether to copy the data, even if not necessary. If False,
        a copy is made only if the old dtype does not match the
        new dtype.

    Returns
    -------
    array : ExtensionArray or ndarray
        ExtensionArray or NumPy ndarray with 'dtype' for its dtype.
    """
    from pandas import Index

    if dtype is not None:
        dtype = pandas_dtype(dtype)

    if isinstance(dtype, IntervalDtype):
        if dtype == self.dtype:
            return self.copy() if copy else self

        if is_float_dtype(self.dtype.subtype) and needs_i8_conversion(
            dtype.subtype
        ):
            # This is allowed on the Index.astype but we disallow it here
            msg = (
                f"Cannot convert {self.dtype} to {dtype}; subtypes are incompatible"
            )
            raise TypeError(msg)

        # need to cast to different subtype
        try:
            # We need to use Index rules for astype to prevent casting
            #  np.nan entries to int subtypes
            new_left = Index(self._left, copy=False).astype(dtype.subtype)
            new_right = Index(self._right, copy=False).astype(dtype.subtype)
        except IntCastingNaNError:
            # e.g test_subtype_integer
            raise
        except (TypeError, ValueError) as err:
            # e.g. test_subtype_integer_errors f8->u8 can be lossy
            #  and raises ValueError
            msg = (
                f"Cannot convert {self.dtype} to {dtype}; subtypes are incompatible"
            )
            raise TypeError(msg) from err
        return self._shallow_copy(new_left, new_right)
    else:
        try:
            return super().astype(dtype, copy=copy)
        except (TypeError, ValueError) as err:
            msg = f"Cannot cast {type(self).__name__} to dtype {dtype}"
            raise TypeError(msg) from err

def equals(self, other) -> bool:
    if type(self) != type(other):
        return False

    return bool(
        self.closed == other.closed
        and self.left.equals(other.left)
        and self.right.equals(other.right)

def shift(self, periods: int = 1, fill_value: object = None) -> IntervalArray:
    if not len(self) or periods == 0:
        return self.copy()

    self._validate_scalar(fill_value)

    # ExtensionArray.shift doesn't work for two reasons
    # 1. IntervalArray.dtype.na_value may not be correct for the dtype.
    # 2. IntervalArray._from_sequence only accepts NaN for missing values,
    #    not other values like NaT

    empty_len = min(abs(periods), len(self))
    if isna(fill_value):
        from pandas import Index

        fill_value = Index(self._left, copy=False)._na_value
        empty = IntervalArray.from_breaks(
            [fill_value] * (empty_len + 1), closed=self.closed
        )
    else:
        empty = self._from_sequence([fill_value] * empty_len, dtype=self.dtype)

    if periods > 0:
        a = empty
        b = self[:-periods]
    else:
        a = self[abs(periods) :]
        b = empty
    return self._concat_same_type([a, b])

def _validate_listlike(self, value):
    # list-like of intervals
    try:
        array = IntervalArray(value)
        self._check_closed_matches(array, name="value")
        value_left, value_right = array.left, array.right
    except TypeError as err:
        # wrong type: not interval or NA
        msg = f"'value' should be an interval type, got {type(value)} instead."
        raise TypeError(msg) from err

    try:
        self.left._validate_fill_value(value_left)
    except (LossySetitemError, TypeError) as err:
        msg = (
            "'value' should be a compatible interval type, "
            f"got {type(value)} instead."
        )
        raise TypeError(msg) from err

    return value_left, value_right

def _validate_scalar(self, value):
    if isinstance(value, Interval):
        self._check_closed_matches(value, name="value")
        left, right = value.left, value.right
        self.left._validate_fill_value(left)
        self.left._validate_fill_value(right)
    elif is_valid_na_for_dtype(value, self.left.dtype):
        # GH#18295
        left = right = self.left._na_value
    else:
        raise TypeError(
            "can only insert Interval objects and NA into an IntervalArray"
        )
    return left, right

def _validate_setitem_value(self, value):
    if is_list_like(value):
        return self._validate_listlike(value)

    left, right = self._validate_scalar(value)

    if is_valid_na_for_dtype(value, self.left.dtype):
        if is_integer_dtype(self.dtype.subtype):
            # can't set NaN on a numpy integer array
            # GH#45484 TypeError, not ValueError, matches what we get with
            #  non-NA un-holdable value.
            raise TypeError("Cannot set float NaN to integer-backed IntervalArray")

    return left, right

def __array__(
    self, dtype: NpDtype | None = None, copy: bool | None = None
) -> np.ndarray:
    """
    Return the IntervalArray's data as a numpy array of Interval
    objects (with dtype='object')
    """
    if copy is False:
        raise ValueError(
            "Unable to avoid copy while creating an array as requested."
        )

    left = self._left
    right = self._right
    mask = self.isna()
    closed = self.closed

    result = np.empty(len(left), dtype=object)
    for i, left_value in enumerate(left):
        if mask[i]:
            result[i] = np.nan
        else:
            result[i] = Interval(left_value, right[i], closed)
    return result

def __arrow_array__(self, type=None):
    """
    Convert myself into a pyarrow Array.
    """
    import pyarrow

    from pandas.core.arrays.arrow.array import to_pyarrow_type
    from pandas.core.arrays.arrow.extension_types import ArrowIntervalType

    try:
        subtype = to_pyarrow_type(self.dtype.subtype)
    except (TypeError, pyarrow.ArrowNotImplementedError) as err:
        raise TypeError(
            f"Conversion to arrow with subtype '{self.dtype.subtype}' "
            "is not supported"
        ) from err
    if subtype is None:
        raise TypeError(
            f"Conversion to arrow with subtype '{self.dtype.subtype}' "
            "is not supported"
        )
    interval_type = ArrowIntervalType(subtype, self.closed)

    def _to_arrow(values) -> pyarrow.Array:
        if isinstance(self.dtype.subtype, np.dtype):
            return pyarrow.array(values, type=subtype, from_pandas=True)
        # pyarrow would fall back on `.values`, dropping the tz; _ndarray is UTC
        return pyarrow.array(values._ndarray, from_pandas=True).cast(subtype)

    storage_array = pyarrow.StructArray.from_arrays(
        [_to_arrow(self._left), _to_arrow(self._right)],
        names=["left", "right"],
    )
    mask = self.isna()
    if mask.any():
        # if there are missing values, set validity bitmap also on the array level
        null_bitmap = pyarrow.array(~mask).buffers()[1]
        storage_array = pyarrow.StructArray.from_buffers(
            storage_array.type,
            len(storage_array),
            [null_bitmap],
            children=[storage_array.field(0), storage_array.field(1)],
        )

    if type is not None:
        if type.equals(interval_type.storage_type):
            return storage_array
        elif isinstance(type, ArrowIntervalType):
            # ensure we have the same subtype and closed attributes
            if not type.equals(interval_type):
                raise TypeError(
                    "Not supported to convert IntervalArray to type with "
                    f"different 'subtype' ({self.dtype.subtype} vs {type.subtype}) "
                    f"and 'closed' ({self.closed} vs {type.closed}) attributes"
                )
        else:
            raise TypeError(
                f"Not supported to convert IntervalArray to '{type}' type"
            )

    return pyarrow.ExtensionArray.from_storage(interval_type, storage_array)

def _putmask(self, mask: npt.NDArray[np.bool_], value) -> None:
    if self._readonly:
        raise ValueError("Cannot modify read-only array")
    value_left, value_right = self._validate_setitem_value(value)

    if isinstance(self._left, np.ndarray):
        np.putmask(self._left, mask, value_left)
        assert isinstance(self._right, np.ndarray)
        np.putmask(self._right, mask, value_right)
    else:
        self._left._putmask(mask, value_left)
        assert not isinstance(self._right, np.ndarray)
        self._right._putmask(mask, value_right)

def delete(self, loc) -> Self:
    new_left: np.ndarray | DatetimeArray | TimedeltaArray
    new_right: np.ndarray | DatetimeArray | TimedeltaArray
    if isinstance(self._left, np.ndarray):
        new_left = np.delete(self._left, loc)
        assert isinstance(self._right, np.ndarray)
        new_right = np.delete(self._right, loc)
    else:
        new_left = self._left.delete(loc)
        assert not isinstance(self._right, np.ndarray)
        new_right = self._right.delete(loc)
    return self._shallow_copy(left=new_left, right=new_right)

def isin(self, values: ArrayLike) -> npt.NDArray[np.bool_]:
    if isinstance(values, IntervalArray):
        if self.closed != values.closed:
            # not comparable -> no overlap
            return np.zeros(self.shape, dtype=bool)

        if self.dtype == values.dtype:
            left = self._combined
            right = values._combined
            return np.isin(left, right).ravel()

        elif needs_i8_conversion(self.left.dtype) ^ needs_i8_conversion(
            values.left.dtype
        ):
            # not comparable -> no overlap
            return np.zeros(self.shape, dtype=bool)

    return isin(self.astype(object), values.astype(object))

def _from_combined(self, combined: np.ndarray) -> IntervalArray:
    """
    Create a new IntervalArray with our dtype from a 1D complex128 ndarray.
    """

    dtype = self._left.dtype
    if needs_i8_conversion(dtype):
        nc = combined.view("i8").reshape(-1, 2)
        assert isinstance(self._left, (DatetimeArray, TimedeltaArray))
        new_left: DatetimeArray | TimedeltaArray | np.ndarray = type(
            self._left
        )._from_sequence(nc[:, 0], dtype=dtype)
        assert isinstance(self._right, (DatetimeArray, TimedeltaArray))
        new_right: DatetimeArray | TimedeltaArray | np.ndarray = type(
            self._right
        )._from_sequence(nc[:, 1], dtype=dtype)
    else:
        assert isinstance(dtype, np.dtype)
        new_left = np.real(combined).astype(dtype).ravel()
        new_right = np.imag(combined).astype(dtype).ravel()
    return self._shallow_copy(left=new_left, right=new_right)

def to_numpy_dtype_inference(
    arr: ExtensionArray,
    dtype: npt.DTypeLike | None,
    na_value,
    hasna: bool,
) -> tuple[np.dtype | None, Any]:
    result_dtype: np.dtype | None
    inferred_numeric_dtype = False
    if dtype is None and is_numeric_dtype(arr.dtype):
        inferred_numeric_dtype = True
        if hasna:
            if arr.dtype.kind == "b":
                result_dtype = np.dtype(np.object_)
            else:
                if arr.dtype.kind in "iu":
                    result_dtype = np.dtype(np.float64)
                else:
                    result_dtype = arr.dtype.numpy_dtype  # type: ignore[attr-defined]
                if na_value is lib.no_default:
                    if not is_nan_na():
                        na_value = NA
                        dtype = np.dtype(object)
                    else:
                        na_value = np.nan
        else:
            result_dtype = arr.dtype.numpy_dtype  # type: ignore[attr-defined]
    elif dtype is not None:
        result_dtype = np.dtype(dtype)
    else:
        result_dtype = None

    if na_value is lib.no_default:
        if result_dtype is None or not hasna:
            na_value = arr.dtype.na_value
        elif result_dtype.kind == "f":
            na_value = np.nan
        elif result_dtype.kind == "M":
            unit = np.datetime_data(result_dtype)[0]  # type: ignore[arg-type]
            na_value = np.datetime64("NaT", unit)  # type: ignore[call-overload]
        elif result_dtype.kind == "m":
            unit = np.datetime_data(result_dtype)[0]  # type: ignore[arg-type]
            na_value = np.timedelta64("NaT", unit)  # type: ignore[call-overload]
        else:
            na_value = arr.dtype.na_value

    if inferred_numeric_dtype and hasna:
        try:
            np_can_hold_element(result_dtype, na_value)  # type: ignore[arg-type]
        except LossySetitemError:
            result_dtype = np.dtype(np.object_)
    return result_dtype, na_value

def __init__(
    self,
    storage: str | None = None,
    na_value: libmissing.NAType | float = libmissing.NA,
) -> None:
    # infer defaults
    if storage is None:
        storage = config["mode"]["string_storage"]
        if storage == "auto":
            if HAS_PYARROW:
                storage = "pyarrow"
            else:
                storage = "python"

    # validate options
    if storage not in {"python", "pyarrow"}:
        raise ValueError(
            f"Storage must be 'python' or 'pyarrow'. Got {storage} instead."
        )
    if storage == "pyarrow" and not HAS_PYARROW:
        raise ImportError(
            f"pyarrow>={PYARROW_MIN_VERSION} is required for PyArrow "
            "backed StringArray."
        )

    if isinstance(na_value, float) and np.isnan(na_value):
        # when passed a NaN value, always set to np.nan to ensure we use
        # a consistent NaN value (and we can use `dtype.na_value is np.nan`)
        na_value = np.nan
    elif na_value is not libmissing.NA:
        raise ValueError(f"'na_value' must be np.nan or pd.NA, got {na_value}")

    self._storage = cast("str", storage)
    self._na_value = na_value

def __eq__(self, other: object) -> bool:
    # we need to override the base class __eq__ because na_value (NA or NaN)
    # cannot be checked with normal `==`
    if isinstance(other, str):
        # TODO should dtype == "string" work for the NaN variant?
        if other == "string" or other == self.name:  # noqa: PLR1714 (repeated-equality-comparison)
            return True
        try:
            other = self.construct_from_string(other)
        except (TypeError, ImportError):
            # TypeError if `other` is not a valid string for StringDtype
            # ImportError if pyarrow is not installed for "string[pyarrow]"
            return False
    if isinstance(other, type(self)):
        return self.storage == other.storage and self.na_value is other.na_value
    return False

def construct_from_string(cls, string) -> Self:
    """
    Construct a StringDtype from a string.

    Parameters
    ----------
    string : str
        The type of the name. The storage type will be taking from `string`.
        Valid options and their storage types are

        ========================== ==============================================
        string                     result storage
        ========================== ==============================================
        ``'string'``               pd.options.mode.string_storage, default python
        ``'string[python]'``       python
        ``'string[pyarrow]'``      pyarrow
        ========================== ==============================================

    Returns
    -------
    StringDtype

    Raise
    -----
    TypeError
        If the string is not a valid option.
    """
    if not isinstance(string, str):
        raise TypeError(
            f"'construct_from_string' expects a string, got {type(string)}"
        )
    if string == "string":
        return cls()
    elif string == "str" and using_string_dtype():
        return cls(na_value=np.nan)
    elif string == "string[python]":
        return cls(storage="python")
    elif string == "string[pyarrow]":
        return cls(storage="pyarrow")
    else:
        raise TypeError(f"Cannot construct a '{cls.__name__}' from '{string}'")

def construct_array_type(self) -> type_t[BaseStringArray]:
    """
    Return the array type associated with this dtype.

    Returns
    -------
    type
    """
    from pandas.core.arrays.string_arrow import (
        ArrowStringArray,
    )

    if self.storage == "python" and self._na_value is libmissing.NA:
        return StringArray
    elif self.storage == "pyarrow" and self._na_value is libmissing.NA:
        return ArrowStringArray
    elif self.storage == "python":
        return StringArray
    else:
        return ArrowStringArray

def _get_common_dtype(self, dtypes: list[DtypeObj]) -> DtypeObj | None:
    storages = set()
    na_values = set()

    for dtype in dtypes:
        if isinstance(dtype, StringDtype):
            storages.add(dtype.storage)
            na_values.add(dtype.na_value)
        elif isinstance(dtype, np.dtype) and dtype.kind in ("U", "T"):
            continue
        else:
            return None

    if len(storages) == 2:
        # if both python and pyarrow storage -> priority to pyarrow
        storage = "pyarrow"
    else:
        storage = next(iter(storages))

    na_value: libmissing.NAType | float
    if len(na_values) == 2:
        # if both NaN and NA -> priority to NA
        na_value = libmissing.NA
    else:
        na_value = next(iter(na_values))

    return StringDtype(storage=storage, na_value=na_value)

def __from_arrow__(
    self, array: pyarrow.Array | pyarrow.ChunkedArray
) -> BaseStringArray:
    """
    Construct StringArray from pyarrow Array/ChunkedArray.
    """
    if self.storage == "pyarrow":
        from pandas.core.arrays.string_arrow import (
            ArrowStringArray,
            _check_pyarrow_available,
        )

        _check_pyarrow_available()

        if not pa.types.is_large_string(array.type):
            array = pc.cast(array, pa.large_string())

        return ArrowStringArray(array, dtype=self)

    else:
        import pyarrow

        if isinstance(array, pyarrow.Array):
            chunks = [array]
        else:
            # pyarrow.ChunkedArray
            chunks = array.chunks

        results = []
        for arr in chunks:
            # convert chunk by chunk to numpy and concatenate then, to avoid
            # overflow for large string data when concatenating the pyarrow arrays
            arr = arr.to_numpy(zero_copy_only=False)
            arr = ensure_string_array(arr, na_value=self.na_value)
            results.append(arr)

    if len(chunks) == 0:
        arr = np.array([], dtype=object)
    else:
        arr = np.concatenate(results)

    # Bypass validation inside StringArray constructor, see GH#47781
    new_string_array = StringArray.__new__(StringArray)
    NDArrayBacked.__init__(new_string_array, arr, self)
    return new_string_array

def _str_map(
    self,
    f,
    na_value=lib.no_default,
    dtype: Dtype | None = None,
    convert: bool = True,
):
    if self.dtype.na_value is np.nan:
        return self._str_map_nan_semantics(f, na_value=na_value, dtype=dtype)

    from pandas.arrays import BooleanArray

    if dtype is None:
        dtype = self.dtype
    if na_value is lib.no_default:
        na_value = self.dtype.na_value

    mask = isna(self)
    arr = np.asarray(self)

    if is_integer_dtype(dtype) or is_bool_dtype(dtype):
        constructor: type[IntegerArray | BooleanArray]
        if is_integer_dtype(dtype):
            constructor = IntegerArray
        else:
            constructor = BooleanArray

        na_value_is_na = isna(na_value)
        if na_value_is_na:
            na_value = 1
        elif dtype == np.dtype("bool"):
            # GH#55736
            na_value = bool(na_value)
        result = lib.map_infer_mask(
            arr,
            f,
            mask.view("uint8"),
            convert=False,
            na_value=na_value,
            # error: Argument 1 to "dtype" has incompatible type
            # "Union[ExtensionDtype, str, dtype[Any], Type[object]]"; expected
            # "Type[object]"
            dtype=np.dtype(cast("type", dtype)),
        )

        if not na_value_is_na:
            mask[:] = False

        return constructor(result, mask)

    else:
        return self._str_map_str_or_object(dtype, na_value, arr, f, mask)

def _str_map_nan_semantics(
    self, f, na_value=lib.no_default, dtype: Dtype | None = None
):
    if dtype is None:
        dtype = self.dtype
    if na_value is lib.no_default:
        if is_bool_dtype(dtype):
            # NaN propagates as False
            na_value = False
        else:
            na_value = self.dtype.na_value

    mask = isna(self)
    arr = np.asarray(self)

    if is_integer_dtype(dtype) or is_bool_dtype(dtype):
        na_value_is_na = isna(na_value)
        if na_value_is_na:
            if is_integer_dtype(dtype):
                na_value = 0
            else:
                # NaN propagates as False
                na_value = False

        result = lib.map_infer_mask(
            arr,
            f,
            mask.view("uint8"),
            convert=False,
            na_value=na_value,
            dtype=np.dtype(cast("type", dtype)),
        )
        if na_value_is_na and is_integer_dtype(dtype) and mask.any():
            # TODO: we could alternatively do this check before map_infer_mask
            #  and adjust the dtype/na_value we pass there. Which is more
            #  performant?
            result = result.astype("float64")
            result[mask] = np.nan

        return result

    else:
        return self._str_map_str_or_object(dtype, na_value, arr, f, mask)

def __init__(
    self, values, *, dtype: StringDtype | None = None, copy: bool = False
) -> None:
    if dtype is None:
        dtype = StringDtype()
    values = extract_array(values)

    super().__init__(values, copy=copy)
    if not isinstance(values, type(self)):
        self._validate(dtype)
    NDArrayBacked.__init__(
        self,
        self._ndarray,
        dtype,

def _validate(self, dtype: StringDtype) -> None:
    """Validate that we only store NA or strings."""

    if dtype._na_value is libmissing.NA:
        if len(self._ndarray) and not lib.is_string_array(
            self._ndarray, skipna=True
        ):
            raise ValueError(
                "StringArray requires a sequence of strings or pandas.NA"
            )
        if self._ndarray.dtype != "object":
            raise ValueError(
                "StringArray requires a sequence of strings or pandas.NA. Got "
                f"'{self._ndarray.dtype}' dtype instead."
            )
        # Check to see if need to convert Na values to pd.NA
        if self._ndarray.ndim > 2:
            # Ravel if ndims > 2 b/c no cythonized version available
            lib.convert_nans_to_NA(self._ndarray.ravel("K"))
        else:
            lib.convert_nans_to_NA(self._ndarray)
    else:
        # Validate that we only store NaN or strings.
        if len(self._ndarray) and not lib.is_string_array(
            self._ndarray, skipna=True
        ):
            raise ValueError("StringArray requires a sequence of strings or NaN")
        if self._ndarray.dtype != "object":
            raise ValueError(
                "StringArray requires a sequence of strings "

def _validate_scalar(self, value):
    # used by NDArrayBackedExtensionIndex.insert
    if isna(value):
        return self.dtype.na_value
    elif not isinstance(value, str):
        raise TypeError(
            f"Invalid value '{value}' for dtype '{self.dtype}'. Value should be a "
            f"string or missing value, got '{type(value).__name__}' instead."
        )
    return value

def _validate_setitem_value(self, value):
    """Validate / convert value to be StringArray compatible."""
    if lib.is_scalar(value):
        if isna(value):
            value = self.dtype.na_value
        elif not isinstance(value, str):
            raise TypeError(
                f"Invalid value '{value}' for dtype '{self.dtype}'. Value should "
                f"be a string or missing value, got '{type(value).__name__}' "
                "instead."
            )
    else:
        value = extract_array(value, extract_numpy=True)
        if not is_array_like_deprecate_non_pandas(value):
            value = np.asarray(value, dtype=object)
        elif isinstance(value.dtype, type(self.dtype)):
            return value
        else:
            # cast categories and friends to arrays to see if values are
            # compatible, compatibility with arrow backed strings
            value = np.asarray(value)
        if len(value) and not lib.is_string_array(value, skipna=True):
            raise TypeError(
                "Invalid value for dtype 'str'. Value should be a "
                "string or missing value (or array of those)."
            )
    return value

def __setitem__(self, key, value) -> None:
    if self._readonly:
        raise ValueError("Cannot modify read-only array")

    value = self._validate_setitem_value(value)

    key = check_array_indexer(self, key)
    scalar_key = lib.is_scalar(key)
    scalar_value = lib.is_scalar(value)
    if scalar_key and not scalar_value:
        raise ValueError("setting an array element with a sequence.")

    if not scalar_value:
        if value.dtype == self.dtype:
            value = value._ndarray
        else:
            value = np.asarray(value)
            mask = isna(value)
            if mask.any():
                value = value.copy()
                value[isna(value)] = self.dtype.na_value

    super().__setitem__(key, value)

def isin(self, values: ArrayLike) -> npt.NDArray[np.bool_]:
    if isinstance(values, BaseStringArray) or (
        isinstance(values, ExtensionArray) and is_string_dtype(values.dtype)
    ):
        values = values.astype(self.dtype, copy=False)
    else:
        if not lib.is_string_array(np.asarray(values), skipna=True):
            values = np.array(
                [val for val in values if isinstance(val, str) or isna(val)],
                dtype=object,
            )
            if not len(values):
                return np.zeros(self.shape, dtype=bool)

        values = self._from_sequence(values, dtype=self.dtype)

    return isin(np.asarray(self), np.asarray(values))

def astype(self, dtype, copy: bool = True):
    dtype = pandas_dtype(dtype)

    if dtype == self.dtype:
        if copy:
            return self.copy()
        return self

    elif isinstance(dtype, IntegerDtype):
        arr = self._ndarray.copy()
        mask = self.isna()
        arr[mask] = 0
        values = arr.astype(dtype.numpy_dtype)
        return IntegerArray(values, mask, copy=False)
    elif isinstance(dtype, FloatingDtype):
        arr_ea = self.copy()
        mask = self.isna()
        arr_ea[mask] = "0"
        values = arr_ea.astype(dtype.numpy_dtype)
        return FloatingArray(values, mask, copy=False)
    elif isinstance(dtype, ExtensionDtype):
        # Skip the NumpyExtensionArray.astype method
        return ExtensionArray.astype(self, dtype, copy)
    elif np.issubdtype(dtype, np.floating):
        arr = self._ndarray.copy()
        mask = self.isna()
        arr[mask] = 0
        values = arr.astype(dtype)
        values[mask] = np.nan
        return values

    return super().astype(dtype, copy)

def _reduce(
    self,
    name: str,
    *,
    skipna: bool = True,
    keepdims: bool = False,
    axis: AxisInt | None = 0,
    **kwargs,
):
    if self.dtype.na_value is np.nan and name in ["any", "all"]:
        if name == "any":
            return nanops.nanany(self._ndarray, skipna=skipna)
        else:
            return nanops.nanall(self._ndarray, skipna=skipna)
    elif name == "count":
        return super().count()
    elif name in ["min", "max", "argmin", "argmax", "sum"]:
        result = getattr(self, name)(skipna=skipna, axis=axis, **kwargs)
        if keepdims:
            return self._from_sequence([result], dtype=self.dtype)
        return result

    raise TypeError(f"Cannot perform reduction '{name}' with string dtype")

def memory_usage(self, deep: bool = False) -> int:
    result = self._ndarray.nbytes
    if deep and not PYPY:
        # deep introspection relies on sys.getsizeof, which always
        # raises TypeError on PyPy (GH#46176)
        return result + lib.memory_usage_of_objects(self._ndarray)
    return result

def __from_arrow__(
    self, array: pyarrow.Array | pyarrow.ChunkedArray
) -> BooleanArray:
    """
    Construct BooleanArray from pyarrow Array/ChunkedArray.
    """
    import pyarrow

    if array.type != pyarrow.bool_() and not pyarrow.types.is_null(array.type):
        raise TypeError(f"Expected array of boolean type, got {array.type} instead")

    if isinstance(array, pyarrow.Array):
        chunks = [array]
        length = len(array)
    else:
        # pyarrow.ChunkedArray
        chunks = array.chunks
        length = array.length()

    if pyarrow.types.is_null(array.type):
        mask = np.ones(length, dtype=bool)
        # No need to init data, since all null
        data = np.empty(length, dtype=bool)
        return BooleanArray(data, mask)

    results = []
    for arr in chunks:
        buflist = arr.buffers()
        data = pyarrow.BooleanArray.from_buffers(
            arr.type, len(arr), [None, buflist[1]], offset=arr.offset
        ).to_numpy(zero_copy_only=False)
        if arr.null_count != 0:
            mask = pyarrow.BooleanArray.from_buffers(
                arr.type, len(arr), [None, buflist[0]], offset=arr.offset
            ).to_numpy(zero_copy_only=False)
            mask = ~mask
        else:
            mask = np.zeros(len(arr), dtype=bool)

        bool_arr = BooleanArray(data, mask)
        results.append(bool_arr)

    if not results:
        return BooleanArray(
            np.array([], dtype=np.bool_), np.array([], dtype=np.bool_)
        )
    else:
        return BooleanArray._concat_same_type(results)

def __init__(
    self, values: np.ndarray, mask: np.ndarray, copy: bool = False
) -> None:
    if not (isinstance(values, np.ndarray) and values.dtype == np.bool_):
        raise TypeError(
            "values should be boolean numpy array. Use "
            "the 'pd.array' function instead"
        )
    self._dtype = BooleanDtype()
    super().__init__(values, mask, copy=copy)

def _from_sequence_of_strings(
    cls,
    strings: list[str],
    *,
    dtype: ExtensionDtype,
    copy: bool = False,
    true_values: list[str] | None = None,
    false_values: list[str] | None = None,
    none_values: list[str] | None = None,
) -> BooleanArray:
    true_values_union = cls._TRUE_VALUES.union(true_values or [])
    false_values_union = cls._FALSE_VALUES.union(false_values or [])

    if none_values is None:
        none_values = []

    def map_string(s) -> bool | None:
        if s in true_values_union:
            return True
        elif s in false_values_union:
            return False
        elif s in none_values:
            return None
        else:
            raise ValueError(f"{s} cannot be cast to bool")

    scalars = np.array(strings, dtype=object)
    mask = isna(scalars)
    scalars[~mask] = list(map(map_string, scalars[~mask]))
    return cls._from_sequence(scalars, dtype=dtype, copy=copy)

def _coerce_to_array(
    cls, value, *, dtype: DtypeObj, copy: bool = False
) -> tuple[np.ndarray, np.ndarray]:
    if dtype:
        assert dtype == "boolean"
    return coerce_to_array(value, copy=copy)

def _logical_method(self, other, op):
    assert op.__name__ in {"or_", "ror_", "and_", "rand_", "xor", "rxor"}
    ops.disallow_datetimelike_logical_op(self, other, op)
    other_is_scalar = lib.is_scalar(other)
    mask = None

    if isinstance(other, BooleanArray):
        other, mask = other._data, other._mask
    elif is_list_like(other):
        if not isinstance(
            other, (list, ExtensionArray, np.ndarray)
        ) and not ops.has_castable_attr(other):
            warnings.warn(
                f"Operation with {type(other).__name__} is deprecated. "
                "In a future version these will be treated as scalar-like. "
                "To retain the old behavior, explicitly wrap in a Series "
                "instead.",
                Pandas4Warning,
                stacklevel=find_stack_level(),
            )

        other = np.asarray(other, dtype="bool")
        if other.ndim > 1:
            return NotImplemented
        other, mask = coerce_to_array(other, copy=False)
    elif isinstance(other, np.bool_):
        other = other.item()

    if other_is_scalar and other is not libmissing.NA and not lib.is_bool(other):
        raise TypeError(
            "'other' should be pandas.NA or a bool. "
            f"Got {type(other).__name__} instead."
        )

    if not other_is_scalar and len(self) != len(other):
        raise ValueError("Lengths must match")

    if op.__name__ in {"or_", "ror_"}:
        result, mask = ops.kleene_or(self._data, other, self._mask, mask)
    elif op.__name__ in {"and_", "rand_"}:
        result, mask = ops.kleene_and(self._data, other, self._mask, mask)
    else:
        # i.e. xor, rxor
        result, mask = ops.kleene_xor(self._data, other, self._mask, mask)

    # i.e. BooleanArray
    return self._maybe_mask_result(result, mask)

def _str_pad(
    self,
    width: int,
    side: Literal["left", "right", "both"] = "left",
    fillchar: str = " ",
) -> Self:
    if side == "left":
        pa_pad = pc.utf8_lpad
    elif side == "right":
        pa_pad = pc.utf8_rpad
    elif side == "both":
        if pa_version_under17p0:
            # GH#59624 fall back to object dtype
            from pandas import array

            obj_arr = self.astype(object, copy=False)  # type: ignore[attr-defined]
            obj = array(obj_arr, dtype=object)
            result = obj._str_pad(width, side, fillchar)  # type: ignore[attr-defined]
            return type(self)._from_sequence(result, dtype=self.dtype)  # type: ignore[attr-defined]
        else:
            # GH#54792
            # https://github.com/apache/arrow/issues/15053#issuecomment-2317032347
            lean_left = (width % 2) == 0
            pa_pad = partial(pc.utf8_center, lean_left_on_odd_padding=lean_left)
    else:
        raise ValueError(
            f"Invalid side: {side}. Side must be one of 'left', 'right', 'both'"
        )
    return self._from_pyarrow_array(
        pa_pad(self._pa_array, width=width, padding=fillchar)

def _str_normalize(self, form: Literal["NFC", "NFD", "NFKC", "NFKD"]) -> Self:
    if form not in ("NFC", "NFD", "NFKC", "NFKD"):
        raise ValueError("invalid normalization form")
    if form in ("NFC", "NFKC"):
        # GH#64359 pc.utf8_normalize only decomposes; it skips the canonical
        #  composition step, so for the composing forms it returns decomposed
        #  output. Fall back to unicodedata for these.
        predicate = lambda val: unicodedata.normalize(form, val)
        result = self._apply_elementwise(predicate)
        return self._from_pyarrow_array(
            pa.chunked_array(result, type=self._pa_array.type)
        )
    return self._from_pyarrow_array(pc.utf8_normalize(self._pa_array, form=form))

def _str_slice(
    self, start: int | None = None, stop: int | None = None, step: int | None = None
) -> Self:
    if start is None:
        if step is not None and step < 0:
            # GH#59710
            start = -1
        else:
            start = 0
    if step is None:
        step = 1
    return self._from_pyarrow_array(
        pc.utf8_slice_codeunits(self._pa_array, start=start, stop=stop, step=step)

def _str_slice_replace(
    self, start: int | None = None, stop: int | None = None, repl: str | None = None
) -> Self:
    if repl is None:
        repl = ""
    if start is None:
        start = 0
    if stop is None:
        stop = np.iinfo(np.int64).max
    return self._from_pyarrow_array(
        pc.utf8_replace_slice(self._pa_array, start, stop, repl)

def _str_replace(
    self,
    pat: str | re.Pattern,
    repl: str | Callable,
    n: int = -1,
    case: bool = True,
    flags: int = 0,
    regex: bool = True,
) -> Self:
    if (
        isinstance(pat, re.Pattern)
        or callable(repl)
        or not case
        or flags
        or (isinstance(repl, str) and r"\g<" in repl)
    ):
        raise NotImplementedError(
            "replace is not supported with a re.Pattern, callable repl, "
            "case=False, flags!=0, or when the replacement string contains "
            "named group references (\\g<...>)"
        )

    if pat == "":
        # pyarrow hangs for empty patterns
        # (https://github.com/apache/arrow/issues/39149)
        # use same func definition as ObjectStringArrayMixin._str_replace
        if regex:
            count = n if n >= 0 else 0
            func = lambda val: re.sub(pat, repl, val, count=count)
        else:
            func = lambda val: val.replace(pat, repl, n)

        result = self._apply_elementwise(func)
        return self._from_pyarrow_array(
            pa.chunked_array(result, type=self._pa_array.type)
        )

    func = pc.replace_substring_regex if regex else pc.replace_substring
    # https://github.com/apache/arrow/issues/39149
    # GH 56404, unexpected behavior with negative max_replacements with pyarrow.
    pa_max_replacements = None if n < 0 else n
    result = func(
        self._pa_array,
        pattern=pat,
        replacement=repl,
        max_replacements=pa_max_replacements,
    )
    return self._from_pyarrow_array(result)

def _str_startswith(
    self, pat: str | tuple[str, ...], na: Scalar | lib.NoDefault = lib.no_default
):
    if isinstance(pat, str):
        result = pc.starts_with(self._pa_array, pattern=pat)
    elif len(pat) == 0:
        # For empty tuple we return null for missing values and False
        #  for valid values.
        result = pc.if_else(pc.is_null(self._pa_array), None, False)
    else:
        result = pc.starts_with(self._pa_array, pattern=pat[0])

        for p in pat[1:]:
            result = pc.or_(result, pc.starts_with(self._pa_array, pattern=p))
    return self._convert_bool_result(result, na=na, method_name="startswith")

def _str_endswith(
    self, pat: str | tuple[str, ...], na: Scalar | lib.NoDefault = lib.no_default
):
    if isinstance(pat, str):
        result = pc.ends_with(self._pa_array, pattern=pat)
    elif len(pat) == 0:
        # For empty tuple we return null for missing values and False
        #  for valid values.
        result = pc.if_else(pc.is_null(self._pa_array), None, False)
    else:
        result = pc.ends_with(self._pa_array, pattern=pat[0])

        for p in pat[1:]:
            result = pc.or_(result, pc.ends_with(self._pa_array, pattern=p))
    return self._convert_bool_result(result, na=na, method_name="endswith")

def _str_contains(
    self,
    pat,
    case: bool = True,
    flags: int = 0,
    na: Scalar | lib.NoDefault = lib.no_default,
    regex: bool = True,
):
    if regex:
        # GH#66348 a compiled `pat` reaches us from ArrowExtensionArray, which
        #  unlike ArrowStringArray does not unwrap it before dispatching here.
        pat, case, flags = self._unwrap_re_pattern(pat, case, flags)

    if flags:
        raise NotImplementedError(f"contains not implemented with {flags=}")

    if regex:
        pa_contains = pc.match_substring_regex
    else:
        pa_contains = pc.match_substring
    result = pa_contains(self._pa_array, pat, ignore_case=not case)
    return self._convert_bool_result(result, na=na, method_name="contains")

def _str_fullmatch(
    self,
    pat: str | re.Pattern,
    case: bool = True,
    flags: int = 0,
    na: Scalar | lib.NoDefault = lib.no_default,
):
    pat, case, flags = self._unwrap_re_pattern(pat, case, flags)

    if (not pat.endswith("$") or pat.endswith("\\$")) and not pat.startswith("^"):
        pat = f"^({pat})$"
    elif not pat.endswith("$") or pat.endswith("\\$"):
        pat = f"^({pat[1:]})$"
    elif not pat.startswith("^"):
        pat = f"^({pat[0:-1]})$"
    return ArrowStringArrayMixin._str_match(self, pat, case, flags, na)

def _str_find(self, sub: str, start: int = 0, end: int | None = None):
    # min_count=0 so that an empty or all-null array reports True instead of
    #  null, keeping it on the pyarrow path below
    if not pc.all(pc.string_is_ascii(self._pa_array), min_count=0).as_py():
        # GH#64123 - pc.find_substring returns byte offsets instead of
        # character offsets for multi-byte UTF-8 characters, so we fall back
        # to Python str.find which correctly returns character offsets.
        res_list = self._apply_elementwise(lambda val: val.find(sub, start, end))
        return self._convert_int_result(pa.chunked_array(res_list, type=pa.int64()))

    if (start == 0 or start is None) and end is None:
        result = pc.find_substring(self._pa_array, sub)
    else:
        if sub == "":
            # GH#56792
            res_list = self._apply_elementwise(
                lambda val: val.find(sub, start, end)
            )
            return self._convert_int_result(
                pa.chunked_array(res_list, type=pa.int64())
            )
        if start is None:
            start_offset = 0
            start = 0
        elif start < 0:
            start_offset = pc.add(start, pc.utf8_length(self._pa_array))
            start_offset = pc.if_else(pc.less(start_offset, 0), 0, start_offset)
        else:
            start_offset = start
        slices = pc.utf8_slice_codeunits(self._pa_array, start, stop=end)
        result = pc.find_substring(slices, sub)
        found = pc.not_equal(result, pa.scalar(-1, type=result.type))
        offset_result = pc.add(result, start_offset)
        result = pc.if_else(found, offset_result, -1)
    result = result.cast(pa.int64())
    return self._convert_int_result(result)

def __init__(self, values, *, dtype: StringDtype | None = None) -> None:
    _check_pyarrow_available()
    if isinstance(values, (pa.Array, pa.ChunkedArray)) and (
        pa.types.is_string(values.type)
        or pa.types.is_string_view(values.type)
        or (
            pa.types.is_dictionary(values.type)
            and (
                pa.types.is_string(values.type.value_type)
                or pa.types.is_large_string(values.type.value_type)
                or pa.types.is_string_view(values.type.value_type)
            )
        )
    ):
        values = pc.cast(values, pa.large_string())

    super().__init__(values)

    if dtype is None:
        dtype = StringDtype(storage="pyarrow", na_value=libmissing.NA)
    self._dtype = dtype

    if not pa.types.is_large_string(self._pa_array.type):
        raise ValueError(
            "ArrowStringArray requires a PyArrow (chunked) array of "

def _cast_pointwise_result(self, values) -> ArrayLike:
    if len(values) == 0:
        return self[:0].copy()

    try:
        arr = pa.array(values, from_pandas=True)
    except (ValueError, TypeError):
        values = construct_1d_object_array_from_listlike(values)
        return lib.maybe_convert_objects(values, convert_non_numeric=True)
    if pa.types.is_string(arr.type) or pa.types.is_large_string(arr.type):
        return self._from_pyarrow_array(arr)
    if self.dtype.na_value is np.nan:
        # ArrowEA has different semantics, so we return numpy-based
        #  result instead
        values = construct_1d_object_array_from_listlike(values)
        return lib.maybe_convert_objects(values, convert_non_numeric=True)
    return ArrowExtensionArray(arr)

def _box_pa_scalar(cls, value, pa_type: pa.DataType | None = None) -> pa.Scalar:
    pa_scalar = super()._box_pa_scalar(value, pa_type)
    if pa.types.is_string(pa_scalar.type) and pa_type is None:
        pa_scalar = pc.cast(pa_scalar, pa.large_string())
    return pa_scalar

def _box_pa_array(
    cls, value, pa_type: pa.DataType | None = None, copy: bool = False
) -> pa.Array | pa.ChunkedArray:
    pa_array = super()._box_pa_array(value, pa_type)
    if pa.types.is_string(pa_array.type) and pa_type is None:
        pa_array = pc.cast(pa_array, pa.large_string())
    return pa_array

def insert(self, loc: int, item) -> ArrowStringArray:
    if self.dtype.na_value is np.nan and item is np.nan:
        item = libmissing.NA
    if not isinstance(item, str) and item is not libmissing.NA:
        raise TypeError(
            f"Invalid value '{item}' for dtype 'str'. Value should be a "
            f"string or missing value, got '{type(item).__name__}' instead."
        )
    return super().insert(loc, item)

def _convert_bool_result(self, values, na=lib.no_default, method_name=None):
    validate_na_arg(na, name="na")
    if self.dtype.na_value is np.nan:
        if na is lib.no_default or isna(na):
            # NaN propagates as False
            values = values.fill_null(False)
        else:
            values = values.fill_null(na)
        return values.to_numpy()
    elif na is not lib.no_default and not isna(na):  # pyright: ignore [reportGeneralTypeIssues]
        values = values.fill_null(na)
    return BooleanDtype().__from_arrow__(values)

def _validate_setitem_value(self, value):
    """Maybe convert value to be pyarrow compatible."""
    if is_scalar(value):
        if isna(value):
            value = None
        elif not isinstance(value, str):
            raise TypeError(
                f"Invalid value '{value}' for dtype 'str'. Value should be a "
                f"string or missing value, got '{type(value).__name__}' instead."
            )
    elif isinstance(value, type(self)):
        pass
    else:
        if not is_array_like_deprecate_non_pandas(value):
            value = np.asarray(value, dtype=object)
        else:
            value = np.asarray(value)
        if len(value) and not (
            value.ndim == 1 and lib.is_string_array(value, skipna=True)
        ):
            raise TypeError(
                "Invalid value for dtype 'str'. Value should be a "
                "string or missing value (or array of those)."
            )
    return super()._validate_setitem_value(value)

def isin(self, values: ArrayLike) -> npt.NDArray[np.bool_]:
    value_set = [
        pa_scalar.as_py()
        for pa_scalar in [pa.scalar(value, from_pandas=True) for value in values]
        if pa_scalar.type in (pa.string(), pa.null(), pa.large_string())
    ]

    # short-circuit to return all False array.
    if not value_set:
        return np.zeros(len(self), dtype=bool)

    result = pc.is_in(
        self._pa_array, value_set=pa.array(value_set, type=self._pa_array.type)
    )
    # pyarrow 2.0.0 returned nulls, so we explicitly specify dtype to convert nulls
    # to False
    return np.array(result, dtype=np.bool_)

def astype(self, dtype, copy: bool = True):
    dtype = pandas_dtype(dtype)

    if dtype == self.dtype:
        if copy:
            return self.copy()
        return self
    elif isinstance(dtype, NumericDtype):
        data = self._pa_array.cast(pa.from_numpy_dtype(dtype.numpy_dtype))
        return dtype.__from_arrow__(data)
    elif isinstance(dtype, np.dtype) and np.issubdtype(dtype, np.floating):
        return self.to_numpy(dtype=dtype, na_value=np.nan)

    return super().astype(dtype, copy=copy)

def _str_contains(
    self,
    pat,
    case: bool = True,
    flags: int = 0,
    na=lib.no_default,
    regex: bool = True,
):
    if (
        flags
        or self._is_re_pattern_with_flags(pat)
        or (regex and self._has_unsupported_regex(pat))
        # a compiled pattern is not a valid literal; defer to the object path
        or (not regex and isinstance(pat, re.Pattern))
    ):
        return super()._str_contains(pat, case, flags, na, regex)

    # with regex=False `pat` is matched literally, so must not be rewritten
    if regex:
        pat, case, flags = self._preprocess_re_pattern(pat, case, flags)
    return ArrowStringArrayMixin._str_contains(self, pat, case, flags, na, regex)

def _str_match(
    self,
    pat: str | re.Pattern,
    case: bool = True,
    flags: int = 0,
    na: Scalar | lib.NoDefault = lib.no_default,
):
    if (
        flags
        or self._is_re_pattern_with_flags(pat)
        or self._has_unsupported_regex(pat)
    ):
        return super()._str_match(pat, case, flags, na)

    pat, case, flags = self._preprocess_re_pattern(pat, case, flags)
    return ArrowStringArrayMixin._str_match(self, pat, case, flags, na)

def _str_fullmatch(
    self,
    pat: str | re.Pattern,
    case: bool = True,
    flags: int = 0,
    na: Scalar | lib.NoDefault = lib.no_default,
):
    if (
        flags
        or self._is_re_pattern_with_flags(pat)
        or self._has_unsupported_regex(pat)
    ):
        return super()._str_fullmatch(pat, case, flags, na)

    pat, case, flags = self._preprocess_re_pattern(pat, case, flags)
    return ArrowStringArrayMixin._str_fullmatch(self, pat, case, flags, na)

def _str_replace(
    self,
    pat: str | re.Pattern,
    repl: str | Callable,
    n: int = -1,
    case: bool = True,
    flags: int = 0,
    regex: bool = True,
):
    if (
        isinstance(pat, re.Pattern)
        or callable(repl)
        or not case
        or flags
        or (  # substitution contains a named group pattern
            # https://docs.python.org/3/library/re.html
            isinstance(repl, str) and r"\g<" in repl
        )
        or (regex and self._has_unsupported_regex(pat))
    ):
        return super()._str_replace(pat, repl, n, case, flags, regex)

    if regex:
        pat, case, flags = self._preprocess_re_pattern(pat, case, flags)

    return ArrowStringArrayMixin._str_replace(
        self, pat, repl, n, case, flags, regex

def _str_count(self, pat: str | re.Pattern, flags: int = 0):
    if (
        flags
        or self._is_re_pattern_with_flags(pat)
        or self._has_unsupported_regex(pat)
    ):
        return super()._str_count(pat, flags)

    pat, case, _ = self._preprocess_re_pattern(pat, True, 0)
    result = pc.count_substring_regex(self._pa_array, pat, ignore_case=not case)
    return self._convert_int_result(result)

def _str_get_dummies(self, sep: str = "|", dtype: NpDtype | None = None):
    if dtype is None:
        dtype = np.int64
    dummies_pa, labels = ArrowExtensionArray(self._pa_array)._str_get_dummies(
        sep, dtype
    )
    if len(labels) == 0:
        return np.empty(shape=(0, 0), dtype=dtype), labels
    dummies = np.vstack(dummies_pa.to_numpy())
    _dtype = pandas_dtype(dtype)
    dummies_dtype: NpDtype
    if isinstance(_dtype, np.dtype):
        dummies_dtype = _dtype
    else:
        dummies_dtype = np.bool_
    return dummies.astype(dummies_dtype, copy=False), labels

def _convert_int_result(self, result):
    if self.dtype.na_value is np.nan:
        result = result.cast(pa.int64())
        if isinstance(result, pa.Array):
            result = result.to_numpy(zero_copy_only=False)
        else:
            result = result.to_numpy()
        return result

    return Int64Dtype().__from_arrow__(result)

def _convert_rank_result(self, result):
    if self.dtype.na_value is np.nan:
        if isinstance(result, pa.Array):
            result = result.to_numpy(zero_copy_only=False)
        else:
            result = result.to_numpy()
        return result.astype("float64", copy=False)

    return Float64Dtype().__from_arrow__(result)

def _reduce(
    self,
    name: str,
    *,
    skipna: bool = True,
    keepdims: bool = False,
    axis: AxisInt | None = 0,
    **kwargs,
):
    nv.validate_minmax_axis(axis, self.ndim)
    if self.dtype.na_value is np.nan and name in ["any", "all"]:
        if not skipna:
            nas = pc.is_null(self._pa_array)
            arr = pc.or_kleene(nas, pc.not_equal(self._pa_array, ""))
        else:
            arr = pc.not_equal(self._pa_array, "")
        result = ArrowExtensionArray(arr)._reduce(
            name, skipna=skipna, keepdims=keepdims, **kwargs
        )
        if keepdims:
            # ArrowExtensionArray will return a length-1 bool[pyarrow] array
            return result.astype(np.bool_)
        return result

    if name in ("count", "min", "max", "sum", "argmin", "argmax"):
        result = self._reduce_calc(name, skipna=skipna, keepdims=keepdims, **kwargs)
    else:
        raise TypeError(f"Cannot perform reduction '{name}' with string dtype")

    if name in ("argmin", "argmax") and isinstance(result, pa.Array):
        return self._convert_int_result(result)
    elif isinstance(result, pa.Array):
        return type(self)(result, dtype=self.dtype)
    else:
        return result

def _cmp_method(self, other, op):
    if (
        isinstance(other, (BaseStringArray, ArrowExtensionArray))
        and self.dtype.na_value is not libmissing.NA
        and other.dtype.na_value is libmissing.NA
    ):
        # NA has priority of NaN semantics
        return NotImplemented

    result = super()._cmp_method(other, op)
    if self.dtype.na_value is np.nan:
        if op == operator.ne:
            return result.to_numpy(np.bool_, na_value=True)
        else:
            return result.to_numpy(np.bool_, na_value=False)
    return result

def view(self, dtype: Dtype | None = None) -> ArrayLike:
    # We handle datetime64, datetime64tz, timedelta64, and period
    #  dtypes here. Everything else we pass through to the underlying
    #  ndarray.
    if dtype is None or dtype is self.dtype:
        return self._from_backing_data(self._ndarray)

    if isinstance(dtype, type):
        # we sometimes pass non-dtype objects, e.g np.ndarray;
        #  pass those through to the underlying ndarray
        return self._ndarray.view(dtype)

    dtype = pandas_dtype(dtype)
    arr = self._ndarray

    if isinstance(dtype, PeriodDtype):
        cls = dtype.construct_array_type()
        return cls(arr.view("i8"), dtype=dtype)
    elif isinstance(dtype, DatetimeTZDtype):
        dt_cls = dtype.construct_array_type()
        dt64_values = arr.view(f"M8[{dtype.unit}]")
        return dt_cls._simple_new(dt64_values, dtype=dtype)
    elif lib.is_np_dtype(dtype, "M") and is_supported_dtype(dtype):
        from pandas.core.arrays import DatetimeArray

        dt64_values = arr.view(dtype)
        return DatetimeArray._simple_new(dt64_values, dtype=dtype)
    elif lib.is_np_dtype(dtype, "m") and is_supported_dtype(dtype):
        from pandas.core.arrays import TimedeltaArray

        td64_values = arr.view(dtype)
        return TimedeltaArray._simple_new(td64_values, dtype=dtype)
    # error: Argument "dtype" to "view" of "ndarray" has incompatible type
    # "ExtensionDtype | dtype[Any]"; expected "dtype[Any] | _HasDType[dtype[Any]]"
    return arr.view(dtype=dtype)  # type: ignore[arg-type]

def equals(self, other) -> bool:
    if type(self) is not type(other):
        return False
    if self.dtype != other.dtype:
        return False
    return bool(array_equivalent(self._ndarray, other._ndarray, dtype_equal=True))

def argmin(self, axis: AxisInt = 0, skipna: bool = True):  # type: ignore[override]
    # override base class by adding axis keyword
    validate_bool_kwarg(skipna, "skipna")
    if not skipna and self._hasna:
        raise ValueError("Encountered an NA value with skipna=False")
    return nargminmax(self, "argmin", axis=axis)

def argmax(self, axis: AxisInt = 0, skipna: bool = True):  # type: ignore[override]
    # override base class by adding axis keyword
    validate_bool_kwarg(skipna, "skipna")
    if not skipna and self._hasna:
        raise ValueError("Encountered an NA value with skipna=False")
    return nargminmax(self, "argmax", axis=axis)

def __setitem__(self, key, value) -> None:
    if self._readonly:
        raise ValueError("Cannot modify read-only array")

    key = check_array_indexer(self, key)
    value = self._validate_setitem_value(value)
    try:
        self._ndarray[key] = value
    except TypeError as err:
        if self._ndarray.dtype.kind == "c":
            # GH#54761 numpy raises TypeError for cases like setting a
            # 1d sequence into a complex scalar position ("only 0-dimensional
            # arrays can be converted to Python scalars"); normalize to
            # ValueError for consistency with other numeric dtypes.
            raise ValueError(*err.args) from err
        raise

def __getitem__(
    self,
    key: PositionalIndexer2D,
) -> Self | Any:
    if lib.is_integer(key):
        # fast-path
        result = self._ndarray[key]
        if self.ndim == 1:
            return self._box_func(result)
        result = self._from_backing_data(result)
        if getitem_returns_view(self, key):
            result._readonly = self._readonly
        return result

    # error: Incompatible types in assignment (expression has type "ExtensionArray",
    # variable has type "Union[int, slice, ndarray]")
    key = extract_array(key, extract_numpy=True)  # type: ignore[assignment]
    key = check_array_indexer(self, key)
    result = self._ndarray[key]
    if lib.is_scalar(result):
        return self._box_func(result)

    result = self._from_backing_data(result)
    if getitem_returns_view(self, key):
        result._readonly = self._readonly
    return result

def _pad_or_backfill(
    self,
    *,
    method: FillnaOptions,
    limit: int | None = None,
    limit_area: Literal["inside", "outside"] | None = None,
    copy: bool = True,
) -> Self:
    mask = self.isna()
    if mask.any():
        # (for now) when self.ndim == 2, we assume axis=0
        func = missing.get_fill_func(method, ndim=self.ndim)

        npvalues = self._ndarray.T
        if copy:
            npvalues = npvalues.copy()
        elif self._readonly:
            raise ValueError("Cannot modify read-only array")
        func(npvalues, limit=limit, limit_area=limit_area, mask=mask.T)
        npvalues = npvalues.T

        if copy:
            new_values = self._from_backing_data(npvalues)
        else:
            new_values = self

    elif copy:
        new_values = self.copy()
    else:
        new_values = self
    return new_values

def __init__(
    self, values: np.ndarray, mask: npt.NDArray[np.bool_], copy: bool = False
) -> None:
    # values is supposed to already be validated in the subclass
    if not (isinstance(mask, np.ndarray) and mask.dtype == np.bool_):
        raise TypeError(
            "mask should be boolean numpy array. Use "
            "the 'pd.array' function instead"
        )
    if values.shape != mask.shape:
        raise ValueError("values.shape must match mask.shape")

    if copy:
        values = values.copy()
        mask = mask.copy()

    self._data = values
    self._mask = mask

def _cast_pointwise_result(self, values) -> ArrayLike:
    if isna(values).all():
        return type(self)._from_sequence(values, dtype=self.dtype)
    if not (isinstance(values, np.ndarray) and values.dtype == object):
        values = construct_1d_object_array_from_listlike(values)
    result = lib.maybe_convert_objects(values, convert_to_nullable_dtype=True)
    lkind = self.dtype.kind
    rkind = result.dtype.kind
    if (lkind in "iu" and rkind in "iu") or (lkind == rkind == "f"):
        result = cast("BaseMaskedArray", result)
        new_data = maybe_downcast_to_dtype(
            result._data, dtype=self.dtype.numpy_dtype
        )
        result = type(result)(new_data, result._mask)
    return result

def __getitem__(self, item: PositionalIndexer) -> Self | Any:
    item = check_array_indexer(self, item)

    newmask = self._mask[item]
    if is_bool(newmask):
        # This is a scalar indexing
        if newmask:
            return self.dtype.na_value
        return self._data[item]

    result = self._simple_new(self._data[item], newmask)
    if getitem_returns_view(self, item):
        result._readonly = self._readonly
    return result

def _pad_or_backfill(
    self,
    *,
    method: FillnaOptions,
    limit: int | None = None,
    limit_area: Literal["inside", "outside"] | None = None,
    copy: bool = True,
) -> Self:
    mask = self._mask

    if mask.any():
        func = missing.get_fill_func(method, ndim=self.ndim)

        npvalues = self._data.T
        new_mask = mask.T
        if copy:
            npvalues = npvalues.copy()
            new_mask = new_mask.copy()
        else:
            if self._readonly:
                raise ValueError("Cannot modify read-only array")
            if limit_area is not None:
                mask = mask.copy()
        func(npvalues, limit=limit, mask=new_mask)

        if limit_area is not None and not mask.all():
            mask = mask.T
            neg_mask = ~mask
            first = neg_mask.argmax()
            last = len(neg_mask) - neg_mask[::-1].argmax() - 1
            if limit_area == "inside":
                new_mask[:first] |= mask[:first]
                new_mask[last + 1 :] |= mask[last + 1 :]
            elif limit_area == "outside":
                new_mask[first + 1 : last] |= mask[first + 1 : last]

        if copy:
            return self._simple_new(npvalues.T, new_mask.T)
        else:
            return self
    elif copy:
        new_values = self.copy()
    else:
        new_values = self
    return new_values

def __setitem__(self, key, value) -> None:
    if self._readonly:
        raise ValueError("Cannot modify read-only array")

    key = check_array_indexer(self, key)

    if is_scalar(value):
        if is_valid_na_for_dtype(value, self.dtype) and not (
            lib.is_float(value) and not is_nan_na()
        ):
            self._mask[key] = True
        else:
            value = self._validate_setitem_value(value)
            self._data[key] = value
            self._mask[key] = False
        return

    value, mask = self._validate_listlike(value)

    self._data[key] = value
    self._mask[key] = mask

def __contains__(self, key) -> bool:
    if isna(key) and key is not self.dtype.na_value:
        # GH#52840
        if lib.is_float(key) and is_nan_na():
            key = self.dtype.na_value
        elif self._data.dtype.kind == "f" and lib.is_float(key):
            return bool((np.isnan(self._data) & ~self._mask).any())

    return bool(super().__contains__(key))

def __iter__(self) -> Iterator:
    if self.ndim == 1:
        if not self._hasna:
            for val in self._data:
                yield val
        else:
            na_value = self.dtype.na_value
            for isna_, val in zip(self._mask, self._data, strict=True):
                if isna_:
                    yield na_value
                else:
                    yield val
    else:
        for i in range(len(self)):
            yield self[i]

def astype(self, dtype: AstypeArg, copy: bool = True) -> ArrayLike:
    dtype = pandas_dtype(dtype)

    if dtype == self.dtype:
        if copy:
            return self.copy()
        return self

    # if we are astyping to another nullable masked dtype, we can fastpath
    if isinstance(dtype, BaseMaskedDtype):
        # TODO deal with NaNs for FloatingArray case
        with warnings.catch_warnings():
            warnings.filterwarnings("ignore", category=RuntimeWarning)
            # TODO: Is rounding what we want long term?
            data = self._data.astype(dtype.numpy_dtype, copy=copy)
        # mask is copied depending on whether the data was copied, and
        # not directly depending on the `copy` keyword
        mask = self._mask if data is self._data else self._mask.copy()
        cls = dtype.construct_array_type()
        return cls(data, mask, copy=False)

    if isinstance(dtype, ExtensionDtype):
        eacls = dtype.construct_array_type()
        return eacls._from_sequence(self, dtype=dtype, copy=copy)

    na_value: float | np.datetime64 | lib.NoDefault

    # coerce
    if dtype.kind == "f":
        # In astype, we consider dtype=float to also mean na_value=np.nan
        na_value = np.nan
    elif dtype.kind == "M":
        unit = np.datetime_data(dtype)[0]
        na_value = np.datetime64("NaT", unit)  # type: ignore[call-overload]
    else:
        na_value = lib.no_default

    # to_numpy will also raise, but we get somewhat nicer exception messages here
    if dtype.kind in "iu" and self._hasna:
        raise ValueError("cannot convert NA to integer")
    if dtype.kind == "b" and self._hasna:
        # careful: astype_nansafe converts np.nan to True
        raise ValueError("cannot convert float NaN to bool")

    data = self.to_numpy(dtype=dtype, na_value=na_value, copy=copy)
    return data

def __array__(
    self, dtype: NpDtype | None = None, copy: bool | None = None
) -> np.ndarray:
    """
    the array interface, return my values
    We return an object array here to preserve our scalar values
    """
    if copy is False:
        if not self._hasna:
            # special case, here we can simply return the underlying data
            result = np.array(self._data, dtype=dtype, copy=copy)
            # If the ExtensionArray is readonly, make the numpy array readonly too
            if self._readonly:
                result = result.view()
                result.flags.writeable = False
            return result
        raise ValueError(
            "Unable to avoid copy while creating an array as requested."
        )

    if copy is None:
        copy = False  # The NumPy copy=False meaning is different here.
    return self.to_numpy(dtype=dtype, copy=copy)

def __array_ufunc__(self, ufunc: np.ufunc, method: str, *inputs, **kwargs):
    # For MaskedArray inputs, we apply the ufunc to ._data
    # and mask the result.

    # this path never reaches ExtensionArray.__array_ufunc__, and a datetimelike
    #  scalar is not in _HANDLED_TYPES, so this has to precede that loop
    ops.disallow_datetimelike_logical_ufunc(ufunc, inputs)

    out = kwargs.get("out", ())

    for x in inputs + out:
        if not isinstance(x, (*self._HANDLED_TYPES, BaseMaskedArray)):
            return NotImplemented

    # for binary ops, use our custom dunder methods
    result = arraylike.maybe_dispatch_ufunc_to_dunder_op(
        self, ufunc, method, *inputs, **kwargs
    )
    if result is not NotImplemented:
        return result

    if "out" in kwargs:
        # e.g. test_ufunc_with_out
        return arraylike.dispatch_ufunc_with_out(
            self, ufunc, method, *inputs, **kwargs
        )

    if method == "reduce":
        result = arraylike.dispatch_reduction_ufunc(
            self, ufunc, method, *inputs, **kwargs
        )
        if result is not NotImplemented:
            return result

    mask = np.zeros(len(self), dtype=bool)
    inputs2 = []
    for x in inputs:
        if isinstance(x, BaseMaskedArray):
            mask |= x._mask
            inputs2.append(x._data)
        else:
            inputs2.append(x)

    def reconstruct(x: np.ndarray):
        # we don't worry about scalar `x` here, since we
        # raise for reduce up above.
        from pandas.core.arrays import (
            BooleanArray,
            FloatingArray,
            IntegerArray,
        )

        if x.dtype.kind == "b":
            m = mask.copy()
            return BooleanArray(x, m)
        elif x.dtype.kind in "iu":
            m = mask.copy()
            return IntegerArray(x, m)
        elif x.dtype.kind == "f":
            m = mask.copy()
            if x.dtype == np.float16:
                # reached in e.g. np.sqrt on BooleanArray
                # we don't support float16
                x = x.astype(np.float32)
            if is_nan_na():
                m[np.isnan(x)] = True
            return FloatingArray(x, m)
        else:
            x[mask] = np.nan
        return x

    result = getattr(ufunc, method)(*inputs2, **kwargs)
    if ufunc.nout > 1:
        # e.g. np.divmod
        return tuple(reconstruct(x) for x in result)
    elif method == "reduce":
        # e.g. np.add.reduce; test_ufunc_reduce_raises
        if self._mask.any():
            return self._na_value
        return result
    else:
        return reconstruct(result)

def _propagate_mask(
    self, mask: npt.NDArray[np.bool_] | None, other
) -> npt.NDArray[np.bool_]:
    if mask is None:
        mask = self._mask.copy()  # TODO: need test for BooleanArray needing a copy
        if other is libmissing.NA:
            # GH#45421 don't alter inplace
            mask = mask | True
        elif is_list_like(other) and len(other) == len(mask):
            mask = mask | isna(other)
    else:
        mask = self._mask | mask
    return mask

def _maybe_mask_result(
    self, result: np.ndarray | tuple[np.ndarray, np.ndarray], mask: np.ndarray
):
    """
    Parameters
    ----------
    result : array-like or tuple[array-like]
    mask : array-like bool
    """
    if isinstance(result, tuple):
        # i.e. divmod
        div, mod = result
        return (
            self._maybe_mask_result(div, mask),
            self._maybe_mask_result(mod, mask),
        )

    if result.dtype.kind == "f":
        from pandas.core.arrays import FloatingArray

        if is_nan_na():
            mask[np.isnan(result)] = True

        return FloatingArray(result, mask, copy=False)

    elif result.dtype.kind == "b":
        from pandas.core.arrays import BooleanArray

        return BooleanArray(result, mask, copy=False)

    elif lib.is_np_dtype(result.dtype, "m") and is_supported_dtype(result.dtype):
        # e.g. test_numeric_arr_mul_tdscalar_numexpr_path
        from pandas.core.arrays import TimedeltaArray

        unit = np.datetime_data(result.dtype)[0]
        result[mask] = np.timedelta64("NaT", unit)  # type: ignore[call-overload]

        if not isinstance(result, TimedeltaArray):
            return TimedeltaArray._simple_new(result, dtype=result.dtype)

        return result

    elif result.dtype.kind in "iu":
        from pandas.core.arrays import IntegerArray

        return IntegerArray(result, mask, copy=False)

    elif result.dtype == object:
        result[mask] = self.dtype.na_value
        return result
    else:
        result[mask] = np.nan
        return result

def _concat_same_type(
    cls,
    to_concat: Sequence[Self],
    axis: AxisInt = 0,
) -> Self:
    data = np.concatenate([x._data for x in to_concat], axis=axis)
    mask = np.concatenate([x._mask for x in to_concat], axis=axis)
    return cls(data, mask)

def _is_monotonic_increasing(self) -> bool:
    if self._hasna:
        return False
    data = self._data
    if data.dtype.kind == "b":
        data = data.view("uint8")
    return libalgos.is_monotonic(data, timelike=False)[0]

def _is_monotonic_decreasing(self) -> bool:
    if self._hasna:
        return False
    data = self._data
    if data.dtype.kind == "b":
        data = data.view("uint8")
    return libalgos.is_monotonic(data, timelike=False)[1]

def _rank(
    self,
    *,
    axis: AxisInt = 0,
    method: RankMethod = "average",
    na_option: RankNaOption = "keep",
    ascending: bool = True,
    pct: bool = False,
):
    # GH#62043 Avoid going through copy-making ensure_data in algorithms.rank
    if axis != 0 or self.ndim != 1:
        raise NotImplementedError

    from pandas.core.arrays import FloatingArray

    data = self._data
    if data.dtype.kind == "b":
        data = data.view("uint8")

    result = libalgos.rank_1d(
        data,
        is_datetimelike=False,
        ties_method=method,
        ascending=ascending,
        na_option=na_option,
        pct=pct,
        mask=self.isna(),
    )
    if na_option in ["top", "bottom"]:
        mask = np.zeros(self.shape, dtype=bool)
    else:
        mask = self._mask.copy()

    if method != "average" and not pct:
        if na_option not in ["top", "bottom"]:
            result[self._mask] = 0  # avoid warning on casting
        result = result.astype("uint64", copy=False)
        from pandas.core.arrays import IntegerArray

        return IntegerArray(result, mask=mask)

    return FloatingArray(result, mask=mask)

def _reduce(
    self,
    name: str,
    *,
    skipna: bool = True,
    keepdims: bool = False,
    axis: int | None = 0,
    **kwargs,
):
    result: Any
    if name == "count":
        result = self.count()
    elif name in {"any", "all", "min", "max", "sum", "prod", "mean", "var", "std"}:
        result = getattr(self, name)(skipna=skipna, axis=axis, **kwargs)
    else:
        # median, skew, kurt, sem
        data = self._data
        mask = self._mask
        op = getattr(nanops, f"nan{name}")
        result = op(data, axis=axis, skipna=skipna, mask=mask, **kwargs)

    if self.ndim == 2 and axis is not None:
        if keepdims:
            raise NotImplementedError(
                "keepdims=True is not implemented for 2D MaskedArray "
                "reductions with axis"
            )
        return result

    if keepdims:
        if isna(result):
            return self._wrap_na_result(name=name, axis=0, mask_size=(1,))
        else:
            if using_python_scalars():
                result = np.array([result])
            else:
                result = result.reshape(1)
            mask = np.zeros(1, dtype=bool)
            return self._maybe_mask_result(result, mask)

    if isna(result):
        return libmissing.NA
    else:
        return result

def _wrap_reduction_result(self, name: str, result, *, skipna, axis):
    if isinstance(result, np.ndarray):
        if skipna:
            # we only retain mask for all-NA rows/columns
            mask = self._mask.all(axis=axis)
        else:
            mask = self._mask.any(axis=axis)

        return self._maybe_mask_result(result, mask)
    return result

def _wrap_na_result(self, *, name, axis, mask_size):
    mask = np.ones(mask_size, dtype=bool)

    float_dtyp = "float32" if self.dtype == "Float32" else "float64"
    if name in ("any", "all"):
        np_dtype = "bool"
    elif name in ["mean", "median", "var", "std", "skew", "kurt", "sem"]:
        np_dtype = float_dtyp
    elif name in ["min", "max"] or self.dtype.itemsize == 8:
        np_dtype = self.dtype.numpy_dtype.name
    else:
        is_windows_or_32bit = is_platform_windows() or not IS64
        int_dtyp = "int32" if is_windows_or_32bit else "int64"
        uint_dtyp = "uint32" if is_windows_or_32bit else "uint64"
        np_dtype = {"b": int_dtyp, "i": int_dtyp, "u": uint_dtyp, "f": float_dtyp}[
            self.dtype.kind
        ]

    value = np.array([1], dtype=np_dtype)
    return self._maybe_mask_result(value, mask=mask)

def _wrap_min_count_reduction_result(
    self, name: str, result, *, skipna, min_count, axis
):
    if min_count == 0 and skipna and isinstance(result, np.ndarray):
        return self._maybe_mask_result(result, np.zeros(result.shape, dtype=bool))
    return self._wrap_reduction_result(name, result, skipna=skipna, axis=axis)

def _get_ordinal_range(start, end, periods, freq, mult: int = 1):
    if com.count_not_none(start, end, periods) != 2:
        raise ValueError(
            "Of the three parameters: start, end, and periods, "
            "exactly two must be specified"
        )

    if freq is not None:
        freq = to_offset(freq, is_period=True)
        mult = freq.n

    if start is not None:
        start = Period(start, freq)
    if end is not None:
        end = Period(end, freq)

    is_start_per = isinstance(start, Period)
    is_end_per = isinstance(end, Period)

    if is_start_per and is_end_per and start.freq != end.freq:
        raise ValueError("start and end must have same freq")
    if start is NaT or end is NaT:
        raise ValueError("start and end must not be NaT")

    if freq is None:
        if is_start_per:
            freq = start.freq
        elif is_end_per:
            freq = end.freq
        else:  # pragma: no cover
            raise ValueError("Could not infer freq from start/end")
        mult = freq.n

    if periods is not None:
        periods = periods * mult
        if start is None:
            data = np.arange(
                end.ordinal - periods + mult, end.ordinal + 1, mult, dtype=np.int64
            )
        else:
            data = np.arange(
                start.ordinal, start.ordinal + periods, mult, dtype=np.int64
            )
    else:
        data = np.arange(start.ordinal, end.ordinal + 1, mult, dtype=np.int64)

    return data, freq

def _field_to_int64(values) -> np.ndarray:
    values = np.asarray(values)
    if values.dtype.kind == "f" and np.isnan(values).any():
        # Match the error raised by the scalar Period constructor; casting
        #  NaN to int64 would otherwise silently produce garbage ordinals.
        raise ValueError("cannot convert float NaN to integer")
    return values.astype(np.int64, copy=False)

def _make_field_arrays(*fields) -> list[np.ndarray]:
    length = None
    for x in fields:
        if isinstance(x, (list, tuple, np.ndarray, ABCSeries)):
            if length is not None and len(x) != length:
                raise ValueError("Mismatched Period array lengths")
            if length is None:
                length = len(x)

    # error: Argument 2 to "repeat" has incompatible type "Optional[int]"; expected
    # "Union[Union[int, integer[Any]], Union[bool, bool_], ndarray, Sequence[Union[int,
    # integer[Any]]], Sequence[Union[bool, bool_]], Sequence[Sequence[Any]]]"
    return [
        (
            np.asarray(x)
            if isinstance(x, (np.ndarray, list, tuple, ABCSeries))
            else np.repeat(x, length)  # type: ignore[arg-type]
        )
        for x in fields

def __init__(self, values, dtype: Dtype | None = None, copy: bool = False) -> None:
    if dtype is not None:
        dtype = pandas_dtype(dtype)
        if not isinstance(dtype, PeriodDtype):
            raise ValueError(f"Invalid dtype {dtype} for PeriodArray")

    if isinstance(values, ABCSeries):
        values = values._values
        if not isinstance(values, type(self)):
            raise TypeError("Incorrect dtype")

    elif isinstance(values, ABCPeriodIndex):
        values = values._values

    if isinstance(values, type(self)):
        if dtype is not None and dtype != values.dtype:
            raise raise_on_incompatible(values, dtype.freq)
        values, dtype = values._ndarray, values.dtype

    if not copy:
        values = np.asarray(values, dtype="int64")
    else:
        values = np.array(values, dtype="int64", copy=copy)
    if dtype is None:
        raise ValueError("dtype is not specified and cannot be inferred")
    dtype = cast("PeriodDtype", dtype)
    NDArrayBacked.__init__(self, values, dtype)

def _from_sequence(
    cls,
    scalars,
    *,
    dtype: Dtype | None = None,
    copy: bool = False,
) -> Self:
    if dtype is not None:
        dtype = pandas_dtype(dtype)

    # Note: we can't do extract_array until after from_datetime64 path
    #  bc of GH#64241
    data_dtype = getattr(scalars, "dtype", None)
    if lib.is_np_dtype(data_dtype, "M"):
        freq = dtype._freq if dtype is not None else None  # type: ignore[union-attr]
        return cls._from_datetime64(scalars, freq)

    scalars = extract_array(scalars, extract_numpy=True)
    if isinstance(scalars, cls):
        if dtype is not None:
            return scalars.astype(dtype, copy=copy)
        elif copy:
            return scalars.copy()
        return scalars

    if not isinstance(
        scalars, (np.ndarray, list, tuple, ABCSeries, ABCIndex, ExtensionArray)
    ):
        # test_constructor_empty_special has a case with an iter object
        scalars = list(scalars)

    if isinstance(scalars, ExtensionArray) and scalars.dtype.kind in "iu":
        # e.g. masked or arrow-backed integer array; np.asarray would cast
        #  integers-with-NA to float and raise a misleading "floating point"
        #  error below, so route through object dtype to keep the integers.
        scalars = scalars.to_numpy(dtype=object, na_value=NaT)

    arrdata = np.asarray(scalars)
    if (
        arrdata.dtype.kind == "u"
        and arrdata.size
        and arrdata.max() > np.iinfo(np.int64).max
    ):
        # GH#64231 the int64 cast below would wrap these silently; read
        #  them through the object path, which rejects them the way the
        #  Period(int) scalar constructor does.
        arrdata = arrdata.astype(object)

    if arrdata.dtype.kind == "f" and len(arrdata) > 0:
        if not lib.all_nans(arrdata):
            raise TypeError(
                "PeriodArray does not allow floating point in construction"
            )
        ordinals = np.full(arrdata.shape, iNaT, dtype=np.int64)
        return cls(ordinals, dtype=dtype)

    elif arrdata.dtype.kind in "iu":
        # GH#64227 enforcing means dropping from_calendar_ordinals here and
        #  reading arrdata as ordinals; the object-dtype and Period-scalar
        #  paths in tslibs.period must be enforced at the same time or the
        #  two interpretations diverge again.
        warnings.warn(
            INT_TO_PERIOD_DEPR_MSG,
            Pandas4Warning,
            stacklevel=find_stack_level(),
        )
        arr = arrdata.astype(np.int64, copy=False)
        ordinals = libperiod.from_calendar_ordinals(arr, dtype)  # type: ignore[arg-type]
        return cls(ordinals, dtype=dtype)
    else:
        periods = ensure_object(arrdata)

        if dtype is None:
            dtype_base = libperiod.extract_period_unit(periods)
            dtype = PeriodDtype(dtype_base)
        ordinals = libperiod.extract_ordinals(periods, dtype)  # type: ignore[arg-type]
        return cls(ordinals, dtype=dtype)

def _generate_range(cls, start, end, periods, freq):
    periods = dtl.validate_periods(periods)

    if freq is not None:
        freq = Period._maybe_convert_freq(freq)

    if start is not None or end is not None:
        subarr, freq = _get_ordinal_range(start, end, periods, freq)
    else:
        raise ValueError("Not enough parameters to construct Period range")

    return subarr, freq

def _unbox_scalar(
    self,
    # error: Argument 1 of "_unbox_scalar" is incompatible with supertype
    # "pandas.core.arrays.datetimelike.DatetimeLikeArrayMixin"; supertype
    #  defines the argument type as "Period | Timestamp | Timedelta | NaTType"
    value: Period | NaTType,  # type: ignore[override]
) -> np.int64:
    if value is NaT:
        return np.int64(value._value)
    elif isinstance(value, self._scalar_type):
        self._check_compatible_with(value)
        return np.int64(value.ordinal)
    else:
        raise ValueError(f"'value' should be a Period. Got '{value}' instead.")

def _check_compatible_with(
    self,
    #  error: Argument 1 of "_check_compatible_with" is incompatible with
    # supertype "pandas.core.arrays.datetimelike.DatetimeLikeArrayMixin";
    # supertype defines the argument type as "Period | Timestamp | Timedelta
    # | NaTType"
    other: Period | NaTType | PeriodArray,  # type: ignore[override]
) -> None:
    if other is NaT:
        return
    elif isinstance(other, Period):
        self._require_matching_unit(other._dtype._freqstr)
    else:
        # error: Item "NaTType" of "NaTType | PeriodArray" has no
        # attribute "freq"
        self._require_matching_unit(other.dtype._freqstr)  # type: ignore[union-attr]

def __array__(
    self, dtype: NpDtype | None = None, copy: bool | None = None
) -> np.ndarray:
    if dtype == "i8":
        # For NumPy 1.x compatibility we cannot use copy=None.  And
        # `copy=False` has the meaning of `copy=None` here:
        if not copy:
            result = np.asarray(self.asi8, dtype=dtype)
            if self._readonly:
                result = result.view()
                result.flags.writeable = False
            return result
        else:
            return np.array(self.asi8, dtype=dtype)

    if copy is False:
        raise ValueError(
            "Unable to avoid copy while creating an array as requested."
        )

    if dtype == bool:
        return ~self._isnan

    # This will raise TypeError for non-object dtypes
    return np.array(list(self), dtype=object)

def __arrow_array__(self, type=None):
    """
    Convert myself into a pyarrow Array.
    """
    import pyarrow

    from pandas.core.arrays.arrow.extension_types import ArrowPeriodType

    if type is not None:
        if pyarrow.types.is_integer(type):
            return pyarrow.array(self._ndarray, mask=self.isna(), type=type)
        elif isinstance(type, ArrowPeriodType):
            # ensure we have the same freq
            if self.freqstr != type.freq:
                raise TypeError(
                    "Not supported to convert PeriodArray to array with different "
                    f"'freq' ({self.freqstr} vs {type.freq})"
                )
        else:
            raise TypeError(
                f"Not supported to convert PeriodArray to '{type}' type"
            )

    period_type = ArrowPeriodType(self.freqstr)
    storage_array = pyarrow.array(self._ndarray, mask=self.isna(), type="int64")
    return pyarrow.ExtensionArray.from_storage(period_type, storage_array)

def astype(self, dtype, copy: bool = True):
    # We handle Period[T] -> Period[U]
    # Our parent handles everything else.
    dtype = pandas_dtype(dtype)
    if dtype == self._dtype:
        if not copy:
            return self
        else:
            return self.copy()
    if isinstance(dtype, PeriodDtype):
        return self.asfreq(dtype.freq)

    if lib.is_np_dtype(dtype, "M") or isinstance(dtype, DatetimeTZDtype):
        # GH#45038 match PeriodIndex behavior.
        tz = getattr(dtype, "tz", None)
        unit = dtl.dtype_to_unit(dtype)
        # error: Argument 1 to "as_unit" of "TimelikeOps" has incompatible
        # type "str"; expected "Literal['s', 'ms', 'us', 'ns']"  [arg-type]
        return self.to_timestamp().tz_localize(tz).as_unit(unit)  # type: ignore[arg-type]

    return super().astype(dtype, copy=copy)

def _add_offset(self, other: BaseOffset):
    assert not isinstance(other, Tick)

    if isinstance(other, Day):
        return self + np.timedelta64(other.n, "D")

    self._require_matching_unit(other._period_unit, base=True)
    return self._addsub_int_array_or_scalar(other.n, operator.add)

def _add_timedeltalike_scalar(self, other):
    """
    Parameters
    ----------
    other : timedelta, Tick, np.timedelta64

    Returns
    -------
    PeriodArray
    """
    if not isinstance(self.freq, (Tick, Day)):
        # We cannot add timedelta-like to non-tick PeriodArray
        raise raise_on_incompatible(self, other)

    if isna(other):
        # i.e. np.timedelta64("NaT")
        return super()._add_timedeltalike_scalar(other)

    if isinstance(other, Day):
        td = np.asarray(Timedelta(days=other.n).asm8)
    else:
        td = np.asarray(Timedelta(other).asm8)
    return self._add_timedelta_arraylike(td)

def _reduce(
    self, name: str, *, skipna: bool = True, keepdims: bool = False, **kwargs
):
    result = super()._reduce(name, skipna=skipna, keepdims=keepdims, **kwargs)
    if keepdims and isinstance(result, np.ndarray):
        return self._from_sequence(result, dtype=self.dtype)
    return result

def _cast_pointwise_result(self, values) -> ArrayLike:
    res = super()._cast_pointwise_result(values)
    with warnings.catch_warnings():
        warnings.filterwarnings(
            "ignore",
            "Constructing a Categorical with a dtype and values containing",
        )
        try:
            cat = type(self)._from_sequence(res, dtype=self.dtype)
        except (TypeError, ValueError):
            return res
    if (cat.isna() == isna(res)).all():
        # i.e. the conversion was non-lossy
        return cat
    return res

def astype(self, dtype: AstypeArg, copy: bool = True) -> ArrayLike:
    """
    Coerce this type to another dtype

    Parameters
    ----------
    dtype : numpy dtype or pandas type
    copy : bool, default True
        By default, astype always returns a newly allocated object.
        If copy is set to False and dtype is categorical, the original
        object is returned.
    """
    dtype = pandas_dtype(dtype)
    result: Categorical | np.ndarray
    if self.dtype is dtype:
        result = self.copy() if copy else self

    elif isinstance(dtype, CategoricalDtype):
        # GH 10696/18593/18630
        dtype = self.dtype.update_dtype(dtype)
        self = self.copy() if copy else self
        result = self._set_dtype(dtype, copy=False)
        wrong = result.isna() & ~self.isna()
        if wrong.any():
            warnings.warn(
                "Constructing a Categorical with a dtype and values containing "
                "non-null entries not in that dtype's categories is deprecated "
                "and will raise in a future version.",
                Pandas4Warning,
                stacklevel=find_stack_level(),
            )

    elif isinstance(dtype, ExtensionDtype):
        return super().astype(dtype, copy=copy)

    elif dtype.kind in "iu" and self.isna().any():
        raise ValueError("Cannot convert float NaN to integer")

    elif len(self.codes) == 0 or len(self.categories) == 0:
        # For NumPy 1.x compatibility we cannot use copy=None.  And
        # `copy=False` has the meaning of `copy=None` here:
        if not copy:
            result = np.asarray(self, dtype=dtype)
        else:
            result = np.array(self, dtype=dtype)

    else:
        # GH8628 (PERF): astype category codes instead of astyping array
        new_cats = self.categories._values

        try:
            new_cats = new_cats.astype(dtype=dtype, copy=copy)
            fill_value = self.categories._na_value
            if not is_valid_na_for_dtype(fill_value, dtype):
                fill_value = lib.item_from_zerodim(
                    np.array(self.categories._na_value).astype(dtype)
                )
        except (
            TypeError,  # downstream error msg for CategoricalIndex is misleading
            ValueError,
        ) as err:
            msg = f"Cannot cast {self.categories.dtype} dtype to {dtype}"
            raise ValueError(msg) from err

        result = take_nd(
            new_cats, ensure_platform_int(self._codes), fill_value=fill_value
        )

    return result

def _validate_codes_for_dtype(cls, codes, *, dtype: CategoricalDtype) -> np.ndarray:
    if isinstance(codes, ExtensionArray) and is_integer_dtype(codes.dtype):
        # Avoid the implicit conversion of Int to object
        if isna(codes).any():
            raise ValueError("codes cannot contain NA values")
        codes = codes.to_numpy(dtype=np.int64)
    else:
        codes = np.asarray(codes)
    if len(codes) and codes.dtype.kind not in "iu":
        raise ValueError("codes need to be array-like integers")

    if len(codes) and (codes.max() >= len(dtype.categories) or codes.min() < -1):
        raise ValueError("codes need to be between -1 and len(categories)-1")
    return codes

def __array_ufunc__(self, ufunc: np.ufunc, method: str, *inputs, **kwargs):
    # for binary ops, use our custom dunder methods
    result = arraylike.maybe_dispatch_ufunc_to_dunder_op(
        self, ufunc, method, *inputs, **kwargs
    )
    if result is not NotImplemented:
        return result

    if "out" in kwargs:
        # e.g. test_numpy_ufuncs_out
        return arraylike.dispatch_ufunc_with_out(
            self, ufunc, method, *inputs, **kwargs
        )

    if method == "reduce":
        # e.g. TestCategoricalAnalytics::test_min_max_ordered
        result = arraylike.dispatch_reduction_ufunc(
            self, ufunc, method, *inputs, **kwargs
        )
        if result is not NotImplemented:
            return result

    # for all other cases, raise for now (similarly as what happens in
    # Series.__array_prepare__)
    raise TypeError(
        f"Object with dtype {self.dtype} cannot perform "
        f"the numpy op {ufunc.__name__}"

def __setstate__(self, state) -> None:
    """Necessary for making this object picklable"""
    if not isinstance(state, dict):
        return super().__setstate__(state)

    if "_dtype" not in state:
        state["_dtype"] = CategoricalDtype(state["_categories"], state["_ordered"])

    if "_codes" in state and "_ndarray" not in state:
        # backward compat, changed what is property vs attribute
        state["_ndarray"] = state.pop("_codes")

    super().__setstate__(state)

def _internal_get_values(self) -> ArrayLike:
    """
    Return the values.

    For internal compatibility with pandas formatting.

    Returns
    -------
    np.ndarray or ExtensionArray
        A numpy array or ExtensionArray of the same dtype as
        categorical.categories.dtype.
    """
    # if we are a datetime and period index, return Index to keep metadata
    if needs_i8_conversion(self.categories.dtype):
        return self.categories.take(
            self._codes, allow_fill=True, fill_value=NaT
        )._values
    elif is_integer_dtype(self.categories.dtype) and -1 in self._codes:
        return (
            self.categories.astype("object")
            .take(self._codes, allow_fill=True, fill_value=np.nan)
            ._values
        )
    return np.array(self)

def __iter__(self) -> Iterator:
    """
    Returns an Iterator over the values of this Categorical.
    """
    if self.ndim == 1:
        return iter(self._internal_get_values().tolist())
    else:
        return (self[n] for n in range(len(self)))

def _format_values_line(fmt_values: list[str], max_width: int) -> str:
    """Format a list of values into a bracketed, width-respecting string."""
    if max_width == 0:
        return "[" + ", ".join(fmt_values) + "]"

    parts = ["["]
    cur_col_len = 1  # account for the opening bracket
    start = True
    for val in fmt_values:
        if not start:
            if cur_col_len + 2 + len(val) > max_width:
                parts.append(",\n ")
                cur_col_len = 1  # 1 space indent
            else:
                parts.append(", ")
                cur_col_len += 2
        parts.append(val)
        cur_col_len += len(val)
        start = False
    parts.append("]")
    return "".join(parts)

def _reduce(
    self, name: str, *, skipna: bool = True, keepdims: bool = False, **kwargs
):
    result = super()._reduce(name, skipna=skipna, keepdims=keepdims, **kwargs)
    if name in ["argmax", "argmin"]:
        # don't wrap in Categorical!
        return result
    if keepdims:
        return type(self)(result, dtype=self.dtype)
    else:
        return result

def _accumulate(self, name: str, skipna: bool = True, **kwargs) -> Self:
    func: Callable
    if name == "cummin":
        func = np.minimum.accumulate
    elif name == "cummax":
        func = np.maximum.accumulate
    else:
        raise TypeError(f"Accumulation {name} not supported for {type(self)}")
    self.check_for_ordered(name)

    codes = self.codes.copy()
    mask = self.isna()
    if func == np.minimum.accumulate:
        codes[mask] = np.iinfo(codes.dtype.type).max
    # no need to change codes for maximum because codes[mask] is already -1
    if not skipna:
        mask = np.maximum.accumulate(mask)

    codes = func(codes)
    codes[mask] = -1
    return self._simple_new(codes, dtype=self._dtype)

def _str_map(
    self, f, na_value=lib.no_default, dtype=np.dtype("object"), convert: bool = True
):
    # Optimization to apply the callable `f` to the categories once
    # and rebuild the result by `take`ing from the result with the codes.
    # Returns the same type as the object-dtype implementation though.
    categories = self.categories
    codes = self.codes
    if categories.dtype == "string":
        result = categories.array._str_map(f, na_value, dtype)  # type: ignore[attr-defined]
        if (
            categories.dtype.na_value is np.nan  # type: ignore[union-attr]
            and is_bool_dtype(dtype)
            and (na_value is lib.no_default or isna(na_value))
        ):
            # NaN propagates as False for functions with boolean return type
            na_value = False
    else:
        from pandas.core.arrays import NumpyExtensionArray

        result = NumpyExtensionArray(categories.to_numpy())._str_map(
            f, na_value, dtype
        )
    return take_nd(result, codes, fill_value=na_value)

def __contains__(self, item: object) -> bool | np.bool_:
    """
    Return for `item in self`.
    """
    # GH37867
    # comparisons of any item to pd.NA always return pd.NA, so e.g. "a" in [pd.NA]
    # would raise a TypeError. The implementation below works around that.
    if is_scalar(item) and isna(item):
        if not self._can_hold_na:
            return False
        elif item is self.dtype.na_value or isinstance(item, self.dtype.type):
            return self._hasna
        else:
            return False
    else:
        # error: Item "ExtensionArray" of "Union[ExtensionArray, ndarray]" has no
        # attribute "any"
        return (item == self).any()  # type: ignore[union-attr]

def __array_ufunc__(self, ufunc: np.ufunc, method: str, *inputs, **kwargs):
    # the fallback at the end of this method np.asarray()s the values: M8/m8
    #  survive to be truth-tested, the rest flatten to object
    ops.disallow_datetimelike_logical_ufunc(ufunc, inputs)

    if any(
        isinstance(other, (ABCSeries, ABCIndex, ABCDataFrame)) for other in inputs
    ):
        return NotImplemented

    result = arraylike.maybe_dispatch_ufunc_to_dunder_op(
        self, ufunc, method, *inputs, **kwargs
    )
    if result is not NotImplemented:
        return result

    if "out" in kwargs:
        return arraylike.dispatch_ufunc_with_out(
            self, ufunc, method, *inputs, **kwargs
        )

    if method == "reduce":
        result = arraylike.dispatch_reduction_ufunc(
            self, ufunc, method, *inputs, **kwargs
        )
        if result is not NotImplemented:
            return result

    return arraylike.default_array_ufunc(self, ufunc, method, *inputs, **kwargs)

def _as_sparse_operand(
    values: np.ndarray, fill_value, dtype: Dtype | None = None
) -> SparseArray:
    """
    Wrap a non-sparse operand for _sparse_array_op, reusing the other operand's
    fill_value where that is a valid value for this operand's subtype.
    """
    # GH#68466 fill_value need not suit the operand's subtype; check it here
    #  rather than catch the construction, which can warn before it raises.
    try:
        SparseDtype(dtype if dtype is not None else values.dtype, fill_value)
    except (TypeError, ValueError):
        # leave any real incompatibility for op() to report
        return SparseArray(values, dtype=dtype)
    return SparseArray(values, fill_value=fill_value, dtype=dtype)

def _wrap_result(
    name: str,
    data,
    sparse_index,
    fill_value,
    dtype: Dtype | None = None,
    kind: SparseIndexKind = "integer",
) -> SparseArray:
    """
    wrap op result to have correct dtype
    """
    if name.startswith("__"):
        # e.g. __eq__ --> eq
        name = name[2:-2]

    if name in _comparison_ops:
        dtype = bool

    fill_value = lib.item_from_zerodim(fill_value)

    if is_bool_dtype(dtype):
        # fill_value may be np.bool_
        fill_value = bool(fill_value)
    if sparse_index is None:
        # a dense result, e.g. from _wrap_dense_result: sparsify it here
        return SparseArray(data, fill_value=fill_value, dtype=dtype, kind=kind)

    data, sparse_index = _prune_fill_value(data, sparse_index, fill_value)

    if dtype is not None:
        data = np.asarray(data, dtype=dtype)  # type: ignore[arg-type]
    else:
        data = np.asarray(data)
    sparse_dtype = SparseDtype(data.dtype, fill_value)
    return SparseArray._simple_new(data, sparse_index, sparse_dtype)

def _differs_from_fill(values: np.ndarray, fill_value) -> np.ndarray:
    """
    Which of ``values`` would not densify as ``fill_value``.
    """
    if isna(fill_value):
        return notna(values)
    mask = values != fill_value
    if values.dtype.kind == "f" and fill_value == 0:
        # -0.0 == 0.0 but the two densify differently, so a stored signed zero
        #  is a real point
        mask |= np.signbit(values) != np.signbit(fill_value)
    return mask

def _prune_fill_value(
    sp_values: np.ndarray, sparse_index: SparseIndex, fill_value
) -> tuple[np.ndarray, SparseIndex]:
    """
    Drop stored values that densify as fill_value, so sp_index holds only real points.

    GH#45126 the ops reuse an operand's sparse index or the union of both, either
    of which can cover a position the op turned into the fill value.
    """
    if sp_values.dtype.kind == "c":
        # isna() is True when either part is NaN, so it cannot decide a complex
        #  on its own
        mask = _differs_from_fill(sp_values.real, np.real(fill_value)) | (
            _differs_from_fill(sp_values.imag, np.imag(fill_value))
        )
    elif sp_values.dtype == object:
        if isna(fill_value):
            # object can hold several NAs at once, and only the fill's own spelling
            #  densifies back as the fill
            mask = np.array(
                [not libmissing.is_matching_na(x, fill_value) for x in sp_values],
                dtype=bool,
            )
        else:
            # 0, 0.0 and False compare equal, so use _make_sparse's type-aware check
            mask = splib.make_mask_object_ndarray(sp_values, fill_value)
    else:
        mask = _differs_from_fill(sp_values, fill_value)

    if mask.all():
        return sp_values, sparse_index

    kind: SparseIndexKind = "integer" if isinstance(sparse_index, IntIndex) else "block"
    indices = sparse_index.indices[mask]
    return sp_values[mask], make_sparse_index(sparse_index.length, indices, kind)

def _unbox_for_fill(dtype: np.dtype, fill_value):
    """
    ``fill_value`` unboxed — for a datetimelike ``dtype``, as a numpy scalar in
    that dtype's own unit. Only valid once ``_can_hold_for_fill`` has accepted it.
    """
    if dtype.kind not in "mM":
        # an object dtype holds these as-is; only a datetimelike array needs
        #  the numpy scalar, and only it rejects np.nan in place of NaT
        return fill_value
    if isna(fill_value):
        # a unitless NaT is deprecated as of numpy 2.5
        return dtype.type("NaT", np.datetime_data(dtype)[0])
    # numpy routes a boxed scalar through the stdlib datetime protocol and
    #  truncates; can_hold_element has already ruled out a lossy conversion
    box = Timestamp if dtype.kind == "M" else Timedelta
    return box(fill_value).asm8.astype(dtype)

def make_sparse_index(length: int, indices, kind: SparseIndexKind) -> SparseIndex:
    index: SparseIndex
    if kind == "block":
        locs, lens = splib.get_blocks(indices)
        index = BlockIndex(length, locs, lens)
    elif kind == "integer":
        index = IntIndex(length, indices)
    else:  # pragma: no cover
        raise ValueError("must be block or integer type")
    return index

def __array__(
    self, dtype: NpDtype | None = None, copy: bool | None = None
) -> np.ndarray:
    if (
        dtype is not None
        and np.dtype(dtype) == object
        and self.sp_values.dtype.kind in "mM"
    ):
        # numpy renders datetime64/timedelta64 as ints when casting to
        # object; box them ourselves, see test_array_object_datetimelike
        if copy is False:
            raise ValueError(
                "Unable to avoid copy while creating an array as requested."
            )
        dense = ensure_wrapped_if_datetimelike(np.asarray(self))
        return np.asarray(dense, dtype=object)

    if self.sp_index.ngaps == 0:
        # Compat for na dtype and int values.
        if copy is True:
            return np.array(self.sp_values)
        else:
            result = self.sp_values
            if self._readonly:
                result = result.view()
                result.flags.writeable = False
            return result

    if copy is False:
        raise ValueError(
            "Unable to avoid copy while creating an array as requested."
        )

    fill_value = self.fill_value

    if self.sp_values.dtype.kind in "mM":
        # np.result_type gives object for a Timestamp/Timedelta fill value
        #  and raises for np.nan; the helper also puts the fill in the
        #  subtype's unit, see test_to_dense_datetimelike_fill_other_unit
        inferred, fill_value = _promote_for_fill(self.sp_values.dtype, fill_value)
        if dtype is None:
            dtype = inferred
    elif dtype is None:
        # Can NumPy represent this type?
        # If not, `np.result_type` will raise. We catch that
        # and return object.
        try:
            dtype = np.result_type(self.sp_values.dtype, type(fill_value))
        except TypeError:
            dtype = object

    out = np.full(self.shape, fill_value, dtype=dtype)
    out[self.sp_index.indices] = self.sp_values
    return out

def _cast_pointwise_result(self, values):
    if not (isinstance(values, np.ndarray) and values.dtype == object):
        values = construct_1d_object_array_from_listlike(values)
    result = lib.maybe_convert_objects(values, convert_non_numeric=True)
    if result.dtype.kind == self.dtype.kind:
        try:
            # e.g. test_groupby_agg_extension
            res = type(self)._from_sequence(result, dtype=self.dtype)
            if ((res == result) | (isna(result) & res.isna())).all():
                # This does not hold for e.g.
                #  test_arith_frame_with_scalar[0-__truediv__]
                return res
            return type(self)._from_sequence(result)
        except (ValueError, TypeError):
            return type(self)._from_sequence(result)
    else:
        # e.g. test_combine_le avoid casting bools to Sparse[float64, nan]
        return type(self)._from_sequence(result)

def shift(self, periods: int = 1, fill_value=None) -> Self:
    if not len(self) or periods == 0:
        return self.copy()

    if isna(fill_value):
        fill_value = self.dtype.na_value

    subtype, fill_value = _promote_for_fill(self.dtype.subtype, fill_value)

    if subtype != self.dtype.subtype:
        # just coerce up front
        arr = self.astype(SparseDtype(subtype, self.fill_value))
    else:
        arr = self

    empty = self._from_sequence(
        [fill_value] * min(abs(periods), len(self)), dtype=arr.dtype
    )

    if periods > 0:
        a = empty
        b = arr[:-periods]
    else:
        a = arr[abs(periods) :]
        b = empty
    return arr._concat_same_type([a, b])

def _get_val_at(self, loc):
    n = len(self)
    if loc < 0:
        loc += n

    if loc >= n or loc < 0:
        raise IndexError(
            f"index is out of bounds: must be an integer between -{n} and {n - 1}"
        )

    sp_loc = self.sp_index.lookup(loc)
    if sp_loc == -1:
        return self.fill_value
    else:
        val = self.sp_values[sp_loc]
        val = maybe_box_datetimelike(val, self.sp_values.dtype)
        return val

def take(self, indices, *, allow_fill: bool = False, fill_value=None) -> Self:
    if is_scalar(indices):
        raise ValueError(f"'indices' must be an array, not a scalar '{indices}'.")
    indices = np.asarray(indices, dtype=np.int32)

    dtype = None
    if indices.size == 0:
        result = np.array([], dtype="object")
        dtype = self.dtype
    elif allow_fill:
        result = self._take_with_fill(indices, fill_value=fill_value)
    else:
        return self._take_without_fill(indices)

    return type(self)(
        result, fill_value=self.fill_value, kind=self.kind, dtype=dtype

def _take_without_fill(self, indices) -> Self:
    to_shift = indices < 0

    n = len(self)

    if (indices.max() >= n) or (indices.min() < -n):
        if n == 0:
            raise IndexError("cannot do a non-empty take from an empty axes.")
        raise IndexError("out of bounds value in 'indices'.")

    if to_shift.any():
        indices = indices.copy()
        indices[to_shift] += n

    sp_indexer = self.sp_index.lookup_array(indices)
    value_mask = sp_indexer != -1
    new_sp_values = self.sp_values[sp_indexer[value_mask]]

    value_indices = np.flatnonzero(value_mask).astype(np.int32, copy=False)

    new_sp_index = make_sparse_index(len(indices), value_indices, kind=self.kind)
    return type(self)._simple_new(new_sp_values, new_sp_index, dtype=self.dtype)

def insert(self, loc: int, item) -> Self:
    if not is_valid_na_for_dtype(item, self.dtype):
        # GH#69028 our _from_sequence casts to the subtype instead of
        #  raising, so validate here; Index.insert widens on the raise
        if not _can_hold_for_fill(self.dtype.subtype, item):
            raise TypeError(f"Invalid value '{item!s}' for dtype '{self.dtype}'")
    return super().insert(loc, item)

def _fill_value_matches(self, fill_value, subtype) -> bool:
    """Whether fill_value is the value the gaps already hold under subtype."""
    if isna(self.fill_value) or isna(fill_value):
        return bool(isna(self.fill_value) and isna(fill_value))
    if is_object_dtype(self.dtype.subtype) or is_object_dtype(subtype):
        # _make_sparse tells 0, 0.0 and False apart for object data, so this
        # has to as well, see make_mask_object_ndarray
        return type(self.fill_value) is type(fill_value) and bool(
            self.fill_value == fill_value
        )
    return bool(self.fill_value == fill_value)

def _reduce(
    self, name: str, *, skipna: bool = True, keepdims: bool = False, **kwargs
):
    method = getattr(self, name, None)

    if method is None:
        raise TypeError(f"cannot perform {name} with type {self.dtype}")

    if name in _skipna_aware_reductions:
        # these methods handle skipna themselves; dropping NAs beforehand
        # would hide the NA from their skipna=False short-circuit
        result = method(skipna=skipna, **kwargs)
    else:
        if skipna:
            arr = self
        else:
            arr = self.dropna()
        result = getattr(arr, name)(**kwargs)

    if keepdims:
        dtype = self.dtype
        result_dtype = np.asarray(result).dtype
        if name in _positional_reductions:
            # intp over result_dtype, which varies with which branch of
            # _argmin_argmax answered.  See test_frame_idxmin_idxmax
            dtype = SparseDtype(np.intp)
        elif name in _boolean_reductions:
            # see test_any_all_keepdims_is_boolean
            dtype = SparseDtype(bool)
        elif name in _complex_to_real_reductions and dtype.subtype.kind == "c":
            # np.result_type below would widen the real result straight back to
            # complex, and a complex fill value has no real counterpart. Gated on
            # the reduction, not the result dtype; see
            # test_frame_complex_reduction_na_keeps_complex
            dtype = SparseDtype(result_dtype)
        elif dtype.subtype.kind in "biufc":
            # The reduction is not always closed over self.dtype, e.g. the
            # mean of an integer column, the sum of a narrow one, or the
            # NaN that min_count inserts; casting the result back to
            # self.dtype would silently truncate it.
            subtype = np.result_type(dtype.subtype, result)
            if subtype != dtype.subtype:
                fill_value = self.fill_value
                if notna(fill_value):
                    # keep the fill value so that reducing a frame of
                    # sparse columns does not mix fill values
                    fill_value = subtype.type(fill_value).item()
                dtype = SparseDtype(subtype, fill_value)
        elif dtype.subtype.kind in "mM" and (
            result is NaT or isinstance(result, (Timestamp, Timedelta))
        ):
            # datetimelike reductions are closed over the subtype except std,
            # which turns a datetime64 column into a timedelta64 one. Go by
            # the reduction, not the result: a boxed result no longer says which.
            if dtype.subtype.kind == "M" and name in _complex_to_real_reductions:
                unit = np.datetime_data(dtype.subtype)[0]
                dtype = SparseDtype(np.dtype(f"m8[{unit}]"))
            if result is NaT:
                # a boxed NaT is inferred as datetime64, so a timedelta64
                # subtype needs the numpy NaT back
                result = na_value_for_dtype(dtype.subtype, compat=False)
        return type(self)([result], dtype=dtype)
    else:
        return result

def _accumulate(self, name: str, *, skipna: bool = True, **kwargs) -> SparseArray:
    accum_func = {
        "cumsum": np.cumsum,
        "cumprod": np.cumprod,
        "cummin": np.minimum.accumulate,
        "cummax": np.maximum.accumulate,
    }.get(name)
    if accum_func is None:
        raise NotImplementedError(f"cannot perform {name} with type {self.dtype}")

    if name == "cumsum" and skipna and self.dtype.subtype.kind in "biufc":
        # numeric cumsum keeps the NA gaps as gaps instead of densifying;
        # other subtypes go dense to match its NA handling
        return self.cumsum(**kwargs)

    result: ExtensionArray | np.ndarray
    values = ensure_wrapped_if_datetimelike(self._densify())
    if isinstance(values, ExtensionArray):
        # datetimelike subtypes have their own accumulations
        result = values._accumulate(name, skipna=skipna, **kwargs)
    else:
        result = na_accum_func(values, accum_func, skipna=skipna)

    # like cumsum, the result's fill value is NA regardless of our own
    fill_value = na_value_for_dtype(result.dtype, compat=False)
    return type(self)(result, fill_value=fill_value)

def _min_max(self, kind: Literal["min", "max"], skipna: bool) -> Scalar:
    """
    Min/max of non-NA/null values

    Parameters
    ----------
    kind : {"min", "max"}
    skipna : bool

    Returns
    -------
    scalar
    """
    valid_vals = self._valid_sp_values
    has_nonnull_fill_vals = not self._null_fill_value and self.sp_index.ngaps > 0

    if len(valid_vals) > 0:
        sp_min_max = getattr(valid_vals, kind)()

        if not skipna and self._hasna:
            return self._na_scalar

        # If a non-null fill value is currently present, it might be the min/max
        if has_nonnull_fill_vals:
            func = max if kind == "max" else min
            result = func(sp_min_max, self.fill_value)
        else:
            # A present NA with skipna=False is handled above, so the min/max
            # of the valid sparse values is the result.
            result = sp_min_max
    elif not skipna and self._hasna:
        return self._na_scalar
    elif has_nonnull_fill_vals:
        result = self.fill_value
    else:
        return self._na_scalar
    return maybe_box_datetimelike(result, self.dtype.subtype)

def argmax(self, skipna: bool = True) -> int:
    validate_bool_kwarg(skipna, "skipna")
    if not skipna and self._hasna:
        raise ValueError("Encountered an NA value with skipna=False")
    return self._argmin_argmax("argmax")

def argmin(self, skipna: bool = True) -> int:
    validate_bool_kwarg(skipna, "skipna")
    if not skipna and self._hasna:
        raise ValueError("Encountered an NA value with skipna=False")
    return self._argmin_argmax("argmin")

def __array_ufunc__(self, ufunc: np.ufunc, method: str, *inputs, **kwargs):
    # this path never reaches ExtensionArray.__array_ufunc__, and a datetimelike
    #  scalar is not in _HANDLED_TYPES, so this has to precede that loop
    ops.disallow_datetimelike_logical_ufunc(ufunc, inputs)

    out = kwargs.get("out", ())

    for x in inputs + out:
        if not isinstance(x, (*self._HANDLED_TYPES, SparseArray)):
            return NotImplemented

    # for binary ops, use our custom dunder methods
    result = arraylike.maybe_dispatch_ufunc_to_dunder_op(
        self, ufunc, method, *inputs, **kwargs
    )
    if result is not NotImplemented:
        return result

    if "out" in kwargs:
        # e.g. tests.arrays.sparse.test_arithmetics.test_ndarray_inplace
        res = arraylike.dispatch_ufunc_with_out(
            self, ufunc, method, *inputs, **kwargs
        )
        return res

    if method == "reduce":
        result = arraylike.dispatch_reduction_ufunc(
            self, ufunc, method, *inputs, **kwargs
        )
        if result is not NotImplemented:
            # e.g. tests.series.test_ufunc.TestNumpyReductions
            return result

    if len(inputs) == 1:
        if method == "reduce":
            # GH#68453 reducing sp_values alone would drop the gaps
            return ufunc.reduce(self._densify(), **kwargs)

        if method == "accumulate":
            # GH#68566 numpy cannot accumulate the scalar fill_value; like
            #  _accumulate, the densified result's fill value is NA regardless
            result = ufunc.accumulate(self._densify(), **kwargs)
            fill_value = na_value_for_dtype(result.dtype, compat=False)
            return type(self)(result, fill_value=fill_value)

        # No alignment necessary.
        sp_values = getattr(ufunc, method)(self.sp_values, **kwargs)
        fill_value = getattr(ufunc, method)(self.fill_value, **kwargs)

        if ufunc.nout > 1:
            # multiple outputs. e.g. modf
            arrays = tuple(
                self._simple_new(
                    sp_value, self.sp_index, SparseDtype(sp_value.dtype, fv)
                )
                for sp_value, fv in zip(sp_values, fill_value, strict=True)
            )
            return arrays

        return self._simple_new(
            sp_values, self.sp_index, SparseDtype(sp_values.dtype, fill_value)
        )

    new_inputs = tuple(np.asarray(x) for x in inputs)
    result = getattr(ufunc, method)(*new_inputs, **kwargs)
    if out:
        if len(out) == 1:
            out = out[0]
        return out

    if ufunc.nout > 1:
        return tuple(type(self)(x) for x in result)
    elif method == "at":
        # no return value
        return None
    else:
        return type(self)(result)

def _arith_method(self, other, op):
    op_name = op.__name__

    if isinstance(other, SparseArray):
        return _sparse_array_op(self, other, op, op_name)

    elif is_scalar(other):
        with np.errstate(all="ignore"):
            fill = op(_get_fill(self), np.asarray(other))
            result = op(self.sp_values, other)

        if op_name == "divmod":
            left, right = result
            lfill, rfill = fill
            return (
                _wrap_result(op_name, left, self.sp_index, lfill),
                _wrap_result(op_name, right, self.sp_index, rfill),
            )

        return _wrap_result(op_name, result, self.sp_index, fill)

    else:
        if not isinstance(
            other, (list, np.ndarray, ExtensionArray)
        ) and not ops.has_castable_attr(other):
            warnings.warn(
                f"Operation with {type(other).__name__} is deprecated. "
                "In a future version these will be treated as scalar-like. "
                "To retain the old behavior, explicitly wrap in a Series "
                "instead.",
                Pandas4Warning,
                stacklevel=find_stack_level(),
            )

        other = np.asarray(other)
        with np.errstate(all="ignore"):
            if len(self) != len(other):
                raise AssertionError(
                    f"length mismatch: {len(self)} vs. {len(other)}"
                )
            if not isinstance(other, SparseArray):
                dtype = getattr(other, "dtype", None)
                other = _as_sparse_operand(other, self.fill_value, dtype=dtype)
            return _sparse_array_op(self, other, op, op_name)

def _cmp_or_logical_op(self, other, op) -> SparseArray:
    # Shared by _cmp_method and _logical_method's fast path.
    if (
        is_list_like(other)
        and not isinstance(other, (list, np.ndarray, ExtensionArray))
        and not ops.has_castable_attr(other)
    ):
        warnings.warn(
            f"Operation with {type(other).__name__} is deprecated. "
            "In a future version these will be treated as scalar-like. "
            "To retain the old behavior, explicitly wrap in a Series "
            "instead.",
            Pandas4Warning,
            stacklevel=find_stack_level(),
        )
    if not is_scalar(other) and not isinstance(other, type(self)):
        # convert list-like to ndarray
        other = np.asarray(other)

    if isinstance(other, np.ndarray):
        # TODO: make this more flexible than just ndarray...
        other = _as_sparse_operand(other, self.fill_value)

    op_name = op.__name__.strip("_")
    # _logical_method routes and/or/xor here for the sparse fast path, and the
    #  dense route below only knows the comparison operators
    is_cmp = op_name in ("eq", "ne", "lt", "gt", "le", "ge")

    if isinstance(other, SparseArray):
        if len(self) != len(other):
            raise ValueError(
                f"operands have mismatched length {len(self)} and {len(other)}"
            )

        if is_cmp and object in (self.dtype.subtype, other.dtype.subtype):
            # GH#68586 _sparse_array_op casts both operands to their common
            #  subtype, so object on either side reaches a kernel splib lacks
            return self._cmp_method_dense(other.to_dense(), other.fill_value, op)

        return _sparse_array_op(self, other, op, op_name)
    elif other is libmissing.NA:
        # GH#68579 NA has no truth value, so the scalar arm below cannot
        #  build a boolean result; answer as the dense path does.
        fill_value = op is operator.ne
        if self.dtype.subtype.kind in "mM":
            result = ops.invalid_comparison(self, other, op)
        else:
            result = np.full(len(self), fill_value, dtype=np.bool_)
        return type(self)(result, fill_value=fill_value, dtype=np.bool_)
    elif is_cmp and self.dtype.subtype == object:
        # GH#68586 the np.bool_ buffer below cannot hold the result of comparing
        #  e.g. pd.NA, so use the kernel the dense path uses -- but only the
        #  stored values need it, so this stays O(nnz) rather than O(len)
        sp_values = ops.comparison_op(self.sp_values, other, op)
        fill_value = self._cmp_fill_value(other, op)
        return _wrap_result(op_name, sp_values, self.sp_index, fill_value)
    else:
        # scalar
        fill_value = op(self.fill_value, other)
        result = np.full(len(self), fill_value, dtype=np.bool_)
        result[self.sp_index.indices] = op(self.sp_values, other)

        return type(self)(
            result,
            fill_value=fill_value,
            dtype=np.bool_,

def _logical_needs_dense(self, other) -> bool:
    # The and/or/xor sparse kernels only support boolean/integer subtypes;
    #  everything else (object/float produced by NA upcasting) must be
    #  computed densely. Inspect dtypes without materializing so the fast
    #  path still receives the original operand (and its warnings).
    if self.dtype.subtype.kind not in "biu":
        return True
    other_dtype = getattr(other, "dtype", None)
    if other_dtype is None:
        # scalar or a dtype-less sequence (e.g. list); the fast path
        #  handles these, including raising on length mismatch
        return False
    if isinstance(other_dtype, SparseDtype):
        return other_dtype.subtype.kind not in "biu"
    return other_dtype.kind not in "biu"

def _unary_method(self, op) -> SparseArray:
    fill_value = op(np.array(self.fill_value)).item()
    dtype = SparseDtype(self.dtype.subtype, fill_value)
    # NOTE: if fill_value doesn't change
    # we just have to apply op to sp_values
    if isna(self.fill_value) or fill_value == self.fill_value:
        values = op(self.sp_values)
        return type(self)._simple_new(values, self.sp_index, self.dtype)
    # In the other case we have to recalc indexes
    return type(self)(op(self.to_dense()), dtype=dtype)

def _check_is_partition(parts: Iterable, whole: Iterable) -> None:
    whole = set(whole)
    parts = [set(x) for x in parts]
    if set.intersection(*parts) != set():
        raise ValueError("Is not a partition because intersection is not null.")
    if set.union(*parts) != whole:
        raise ValueError("Is not a partition because union is not the whole.")

def _delegate_method(self, name: str, *args, **kwargs):
    if name == "from_coo":
        return self.from_coo(*args, **kwargs)
    elif name == "to_coo":
        return self.to_coo(*args, **kwargs)
    else:
        raise ValueError

def _prep_index(data, index, columns):
    from pandas.core.indexes.api import (
        default_index,
        ensure_index,
    )

    N, K = data.shape
    if index is None:
        index = default_index(N)
    else:
        index = ensure_index(index)
    if columns is None:
        columns = default_index(K)
    else:
        columns = ensure_index(columns)

    if len(columns) != K:
        raise ValueError(f"Column length mismatch: {len(columns)} vs. {K}")
    if len(index) != N:
        raise ValueError(f"Index length mismatch: {len(index)} vs. {N}")
    return index, columns

def cast_for_truediv(
    arrow_array: pa.ChunkedArray, pa_object: pa.Array | pa.Scalar
) -> tuple[pa.ChunkedArray, pa.Array | pa.Scalar]:
    # Ensure int / int -> float mirroring Python/Numpy behavior
    # as pc.divide_checked(int, int) -> int
    if pa.types.is_integer(arrow_array.type) and pa.types.is_integer(
        pa_object.type
    ):
        # GH: 56645.
        # https://github.com/apache/arrow/issues/35563
        return pc.cast(arrow_array, pa.float64(), safe=False), pc.cast(
            pa_object, pa.float64(), safe=False
        )

    return arrow_array, pa_object

def to_pyarrow_type(
    dtype: ArrowDtype | pa.DataType | Dtype | None,
) -> pa.DataType | None:
    """
    Convert dtype to a pyarrow type instance.
    """
    if isinstance(dtype, ArrowDtype):
        return dtype.pyarrow_dtype
    elif isinstance(dtype, pa.DataType):
        return dtype
    elif isinstance(dtype, DatetimeTZDtype):
        return pa.timestamp(dtype.unit, dtype.tz)
    elif dtype:
        try:
            # Accepts python types too
            # Doesn't handle all numpy types
            return pa.from_numpy_dtype(dtype)
        except pa.ArrowNotImplementedError:
            pass
    return None

def _is_temporal_pa_type(pa_type: pa.DataType) -> bool | None:
    """
    Whether `pa_type` is temporal, or None if it does not settle that.
    """
    if pa.types.is_dictionary(pa_type):
        return _is_temporal_pa_type(pa_type.value_type)
    if pa.types.is_temporal(pa_type):
        return True
    if (
        pa.types.is_integer(pa_type)
        or pa.types.is_floating(pa_type)
        or pa.types.is_boolean(pa_type)
        or pa.types.is_decimal(pa_type)
    ):
        return False
    # a string can parse to a timestamp, and nothing else here rules either way
    return None

def _is_temporal_dtype(dtype: DtypeObj) -> bool | None:
    """
    Whether `dtype` is temporal, or None if it does not settle that.
    """
    if isinstance(dtype, ArrowDtype):
        return _is_temporal_pa_type(dtype.pyarrow_dtype)
    if isinstance(dtype, CategoricalDtype):
        return _is_temporal_dtype(dtype.categories.dtype)
    if dtype.kind in "mM" or needs_i8_conversion(dtype):
        # kind catches wrappers such as SparseDtype("M8[ns]"); needs_i8_conversion
        #  catches PeriodDtype, whose kind is "O"
        return True
    if dtype.kind in "iufbc":
        return False
    # Anything unrecognized has to land here: a wrong False would reject a
    #  valid assignment, see test_setitem_temporal_still_accepted
    return None

def _is_temporal_value(value) -> bool | None:
    """
    Whether `value` is temporal, or None if its type does not settle that.

    pyarrow converts a temporal value into an integer array without complaint
    (`pa.array(dta, type=pa.int64())` succeeds), so a setitem has to reject the
    reinterpretation before handing the value to `_box_pa` (GH#68419).
    """
    if is_scalar(value) and isna(value):
        # NA of any flavor is settable into any dtype; a NaT scalar carries
        #  an M8/m8 dtype, so this has to come before the dtype lookup
        return None
    if type(value) in (int, float, bool):
        # the common scalar setitem: skips infer_dtype_from_scalar (~10%), and
        #  settles an int too wide for any integer dtype, which it maps to object
        return False

    value = extract_array(value, extract_numpy=True)
    if isinstance(value, pa.Scalar):
        # a typed null scalar is just "assign NA"; isna() does not recognize
        #  pa.Scalar, so the guard above does not catch it
        return None if not value.is_valid else _is_temporal_pa_type(value.type)
    if isinstance(value, (pa.Array, pa.ChunkedArray)):
        return _is_temporal_pa_type(value.type)

    dtype = getattr(value, "dtype", None)
    if dtype is None:
        if is_list_like(value):
            return None
        if isinstance(value, (date, time)):
            # infer_dtype_from_scalar maps both to object, which would leave the
            #  scalar disagreeing with the date32/time64 array forms
            return True
        if isinstance(value, Decimal):
            # object again, this time disagreeing with the decimal128 array form
            return False
        dtype = infer_dtype_from_scalar(value)[0]
    return _is_temporal_dtype(dtype)

def _copy_pyarrow_buffers(
    pa_array: pa.Array | pa.ChunkedArray,
) -> pa.Array | pa.ChunkedArray:
    """
    Return an equal array that owns its buffers (GH#67990).

    ``pa.concat_arrays`` reuses the ``dictionary`` child rather than copying it,
    so dictionary types are rebuilt from copies of both halves.
    """
    if isinstance(pa_array, pa.ChunkedArray):
        return pa.chunked_array(
            [_copy_pyarrow_buffers(chunk) for chunk in pa_array.chunks],
            type=pa_array.type,
        )
    if pa.types.is_dictionary(pa_array.type):
        return pa.DictionaryArray.from_arrays(
            _copy_pyarrow_buffers(pa_array.indices),
            _copy_pyarrow_buffers(pa_array.dictionary),
            ordered=pa_array.type.ordered,
        )
    return pa.concat_arrays([pa_array])

def __init__(self, values: pa.Array | pa.ChunkedArray) -> None:
    if not HAS_PYARROW:
        msg = (
            f"pyarrow>={PYARROW_MIN_VERSION} is required for PyArrow "
            "backed ArrowExtensionArray."
        )
        raise ImportError(msg)
    if isinstance(values, pa.Array):
        self._pa_array = pa.chunked_array([values])
    elif isinstance(values, pa.ChunkedArray):
        self._pa_array = values
    else:
        raise ValueError(
            f"Unsupported type '{type(values)}' for ArrowExtensionArray"
        )
    self._dtype = ArrowDtype(self._pa_array.type)
    self._cache = {}

def _box_pa(
    cls, value, pa_type: pa.DataType | None = None
) -> pa.Array | pa.ChunkedArray | pa.Scalar:
    """
    Box value into a pyarrow Array, ChunkedArray or Scalar.

    Parameters
    ----------
    value : any
    pa_type : pa.DataType | None

    Returns
    -------
    pa.Array or pa.ChunkedArray or pa.Scalar
    """
    if isinstance(value, pa.Scalar) or not is_list_like(value):
        return cls._box_pa_scalar(value, pa_type)
    return cls._box_pa_array(value, pa_type)

def __iter__(self) -> Iterator[Any]:
    """
    Iterate over elements of the array.
    """
    na_value = self._dtype.na_value
    # GH 53326
    pa_type = self._pa_array.type
    box_timestamp = pa.types.is_timestamp(pa_type) and pa_type.unit != "ns"
    box_timedelta = pa.types.is_duration(pa_type) and pa_type.unit != "ns"
    for value in self._pa_array:
        val = value.as_py()
        if val is None:
            yield na_value
        elif box_timestamp:
            yield Timestamp(val).as_unit(pa_type.unit)
        elif box_timedelta:
            yield Timedelta(val).as_unit(pa_type.unit)
        else:
            yield val

def __array_ufunc__(self, ufunc: np.ufunc, method: str, *inputs, **kwargs):
    if (
        not is_nan_na()
        and type(self) is ArrowExtensionArray
        and (
            pa.types.is_floating(self._pa_array.type)
            or pa.types.is_integer(self._pa_array.type)
        )
    ):
        # this branch returns without reaching ExtensionArray.__array_ufunc__
        ops.disallow_datetimelike_logical_ufunc(ufunc, inputs)

        # GH#62506 - when distinguish_nan_and_na is True,
        # default_array_ufunc converts to numpy via np.asarray which
        # produces object dtype that most ufuncs can't handle.
        # Replicate ExtensionArray.__array_ufunc__ but convert with
        # na_value=np.nan (float, not object) in the default fallback,
        # then re-mask NA positions in the result.
        if any(
            isinstance(other, (ABCSeries, ABCIndex, ABCDataFrame))
            for other in inputs
        ):
            return NotImplemented

        result = arraylike.maybe_dispatch_ufunc_to_dunder_op(
            self, ufunc, method, *inputs, **kwargs
        )
        if result is not NotImplemented:
            return result

        if "out" in kwargs:
            return arraylike.dispatch_ufunc_with_out(
                self, ufunc, method, *inputs, **kwargs
            )

        if method == "reduce":
            result = arraylike.dispatch_reduction_ufunc(
                self, ufunc, method, *inputs, **kwargs
            )
            if result is not NotImplemented:
                return result

        # Default: convert to numpy with NaN for NA instead of
        # object dtype, run the ufunc, then re-mask.
        mask = self.isna()
        new_inputs = [
            self.to_numpy(na_value=np.nan) if x is self else x for x in inputs
        ]
        result = getattr(ufunc, method)(*new_inputs, **kwargs)

        remask = functools.partial(pa.array, mask=mask, from_pandas=False)
        if isinstance(result, tuple):
            return tuple(type(self)(remask(res)) for res in result)
        return type(self)(remask(result))

    # Need to wrap np.array results GH#62800
    result = super().__array_ufunc__(ufunc, method, *inputs, **kwargs)
    if type(self) is ArrowExtensionArray:
        # Exclude ArrowStringArray
        return type(self)._from_sequence(result)
    return result

def __array__(
    self, dtype: NpDtype | None = None, copy: bool | None = None
) -> np.ndarray:
    """Correctly construct numpy arrays when passed to `np.asarray()`."""
    if copy is False:
        # TODO: By using `zero_copy_only` it may be possible to implement this
        raise ValueError(
            "Unable to avoid copy while creating an array as requested."
        )
    elif copy is None:
        # `to_numpy(copy=False)` has the meaning of NumPy `copy=None`.
        copy = False

    return self.to_numpy(dtype=dtype, copy=copy)

def __invert__(self) -> Self:
    # This is a bit wise op for integer types
    if pa.types.is_integer(self._pa_array.type):
        return self._from_pyarrow_array(pc.bit_wise_not(self._pa_array))
    elif pa.types.is_string(self._pa_array.type) or pa.types.is_large_string(
        self._pa_array.type
    ):
        # Raise TypeError instead of pa.ArrowNotImplementedError
        raise TypeError("__invert__ is not supported for string dtypes")
    else:
        return self._from_pyarrow_array(pc.invert(self._pa_array))

def _cmp_method(self, other, op) -> ArrowExtensionArray:
    pc_func = ARROW_CMP_FUNCS[op.__name__]
    ltype = self._pa_array.type

    if isinstance(other, range):
        # GH#63429 our callers defer this to the EA for EA-backed values
        ops.maybe_warn_listlike(other)

    if isinstance(other, (ExtensionArray, np.ndarray, list, range)):
        ops.raise_if_2d(other)
        if is_list_like(other) and len(self) != len(other):
            # is_list_like excludes 0-dim ndarrays, which are scalars here
            raise ValueError("Lengths must match to compare")
        try:
            boxed = self._box_pa(other)
        except pa.lib.ArrowInvalid:
            # e.g. GH#60228 [1, "b"] we have to operate pointwise
            res_values = [op(x, y) for x, y in zip(self, other, strict=True)]
            result = pa.array(res_values, type=pa.bool_(), from_pandas=True)
        else:
            rtype = boxed.type
            if (pa.types.is_timestamp(ltype) and pa.types.is_date(rtype)) or (
                pa.types.is_timestamp(rtype) and pa.types.is_date(ltype)
            ):
                # GH#62157 match non-pyarrow behavior
                result = ops.invalid_comparison(self, other, op)
                result = pa.array(result, type=pa.bool_())
            else:
                try:
                    result = pc_func(self._pa_array, boxed)
                except pa.ArrowNotImplementedError:
                    result = ops.invalid_comparison(self, other, op)
                    result = pa.array(result, type=pa.bool_())

    elif is_scalar(other):
        if (isinstance(other, datetime) and pa.types.is_date(ltype)) or (
            type(other) is date and pa.types.is_timestamp(ltype)
        ):
            # GH#62157 match non-pyarrow behavior
            result = ops.invalid_comparison(self, other, op)
            result = pa.array(result, type=pa.bool_())
        else:
            try:
                result = pc_func(self._pa_array, self._box_pa(other))
            except (pa.lib.ArrowNotImplementedError, pa.lib.ArrowInvalid):
                mask = isna(self) | isna(other)
                valid = ~mask
                result = np.zeros(len(self), dtype="bool")
                np_array = np.array(self)
                try:
                    result[valid] = op(np_array[valid], other)
                except TypeError:
                    result = ops.invalid_comparison(self, other, op)
                result = pa.array(result, type=pa.bool_())
                result = pc.if_else(valid, result, None)
    else:
        raise NotImplementedError(
            f"{op.__name__} not implemented for {type(other)}"
        )
    return ArrowExtensionArray(result)

def _logical_method(self, other, op) -> Self:
    # checked here too because the GH#60234 arm below returns without
    #  reaching _evaluate_op_method
    ops.raise_if_2d(other)

    # For integer types `^`, `|`, `&` are bitwise operators and return
    # integer types. Otherwise these are boolean ops.
    if pa.types.is_integer(self._pa_array.type):
        return self._evaluate_op_method(other, op, ARROW_BIT_WISE_FUNCS)
    elif (
        (
            pa.types.is_string(self._pa_array.type)
            or pa.types.is_large_string(self._pa_array.type)
        )
        and op in (roperator.ror_, roperator.rand_, roperator.rxor)
        and isinstance(other, np.ndarray)
        and other.dtype == bool
    ):
        # GH#60234 backward compatibility for the move to StringDtype in 3.0
        op_name = op.__name__[1:].strip("_")
        warnings.warn(
            f"'{op_name}' operations between boolean dtype and {self.dtype} are "
            "deprecated and will raise in a future version. Explicitly "
            "cast the strings to a boolean dtype before operating instead.",
            Pandas4Warning,
            stacklevel=find_stack_level(),
        )
        return op(other, self.astype(bool))
    else:
        return self._evaluate_op_method(other, op, ARROW_LOGICAL_FUNCS)

def _str_arith_method_object_fallback(
    self, other, op
) -> Self | npt.NDArray[np.object_]:
    mask = isna(self) | isna(other)
    valid = ~mask

    if is_list_like(other):
        if len(other) != len(self):
            raise ValueError(
                f"Lengths of operands do not match: {len(self)} != {len(other)}"
            )
        if not is_array_like_deprecate_non_pandas(other):
            other = np.asarray(other)
        other = other[valid]

    result = np.empty(len(self), dtype=object)
    result[mask] = self.dtype.na_value
    result[valid] = op(np.asarray(self, dtype=object)[valid], other)

    if not lib.is_string_array(result, skipna=True):
        return result
    return type(self)._from_sequence(result, dtype=self.dtype)

def _arith_method(self, other, op) -> Self | npt.NDArray[np.object_]:
    if isinstance(other, BaseOffset) and pa.types.is_date(self._pa_array.type):
        # Cast date32/date64 → timestamp, apply offset via DatetimeArray, cast back
        ts_array = type(self)(self._pa_array.cast(pa.timestamp("us")))
        dt_array = ts_array._to_datetimearray()

        shifted = op(dt_array, other)
        check = shifted[~shifted.isna()] if shifted._hasna else shifted
        if not check.is_normalized:
            raise TypeError(
                f"DateOffset {other} is intra-day and cannot be "
                f"applied to date32/date64 arrays"
            )
        result_pa = pa.array(shifted._ndarray, from_pandas=True).cast(
            self._pa_array.type
        )
        return self._from_pyarrow_array(result_pa)

    result: Self | npt.NDArray[np.object_]
    if pa.types.is_string(self._pa_array.type) or pa.types.is_large_string(
        self._pa_array.type
    ):
        try:
            result = self._evaluate_op_method(other, op, ARROW_ARITHMETIC_FUNCS)
        except (pa.ArrowInvalid, pa.ArrowTypeError):
            result = self._str_arith_method_object_fallback(other, op)
    else:
        result = self._evaluate_op_method(other, op, ARROW_ARITHMETIC_FUNCS)
    if isinstance(result, np.ndarray):
        return result
    if is_nan_na() and result.dtype.kind == "f":
        parr = result._pa_array
        mask = pc.is_nan(parr).fill_null(False).to_numpy()
        arr = pc.replace_with_mask(parr, mask, pa.scalar(None, type=parr.type))
        result = type(self)(arr)
    return result

def __contains__(self, key) -> bool:
    # https://github.com/pandas-dev/pandas/pull/51307#issuecomment-1426372604
    if isna(key) and key is not self.dtype.na_value:
        if lib.is_float(key) and is_nan_na():
            return self.dtype.na_value in self
        elif self.dtype.kind == "f" and lib.is_float(key):
            # Check specifically for NaN
            return pc.any(pc.is_nan(self._pa_array)).as_py()

        # e.g. date or timestamp types we do not allow None here to match pd.NA
        return False
        # TODO: maybe complex? object?

    return bool(super().__contains__(key))

def isna(self) -> npt.NDArray[np.bool_]:
    """
    Boolean NumPy array indicating if each value is missing.

    This should return a 1-D array the same length as 'self'.
    """
    # GH51630: fast paths
    null_count = self._pa_array.null_count
    if null_count == 0:
        return np.zeros(len(self), dtype=np.bool_)
    elif null_count == len(self):
        return np.ones(len(self), dtype=np.bool_)

    return self._pa_array.is_null().to_numpy()

def _argmin_max(self, skipna: bool, method: str) -> int:
    if self._pa_array.length() in (0, self._pa_array.null_count) or (
        self._hasna and not skipna
    ):
        # For empty or all null, pyarrow returns -1 but pandas expects TypeError
        # For skipna=False and data w/ null, pandas expects NotImplementedError
        # let ExtensionArray.arg{max|min} raise
        return getattr(super(), f"arg{method}")(skipna=skipna)

    data = self._pa_array
    if pa.types.is_duration(data.type):
        data = data.cast(pa.int64())

    value = getattr(pc, method)(data, skip_nulls=skipna)
    return pc.index(data, value).as_py()

def _pad_or_backfill(
    self,
    *,
    method: FillnaOptions,
    limit: int | None = None,
    limit_area: Literal["inside", "outside"] | None = None,
    copy: bool = True,
) -> Self:
    if not self._hasna:
        return self

    if limit is None and limit_area is None:
        method = missing.clean_fill_method(method)
        try:
            if method == "pad":
                return self._from_pyarrow_array(
                    pc.fill_null_forward(self._pa_array)
                )
            elif method == "backfill":
                return self._from_pyarrow_array(
                    pc.fill_null_backward(self._pa_array)
                )
        except pa.ArrowNotImplementedError:
            # ArrowNotImplementedError: Function 'coalesce' has no kernel
            #   matching input types (duration[ns], duration[ns])
            # TODO: remove try/except wrapper if/when pyarrow implements
            #   a kernel for duration types.
            pass

    return super()._pad_or_backfill(
        method=method, limit=limit, limit_area=limit_area, copy=copy

def _maybe_convert_datelike_array(self):
    """Maybe convert to a datelike array."""
    pa_type = self._pa_array.type
    if pa.types.is_timestamp(pa_type):
        return self._to_datetimearray()
    elif pa.types.is_duration(pa_type):
        return self._to_timedeltaarray()
    return self

def _str_accumulate(
    self, name: str, *, skipna: bool = True, **kwargs
) -> ArrowExtensionArray | ExtensionArray:
    """
    Accumulate implementation for strings, see `_accumulate` docstring for details.

    pyarrow.compute does not implement these methods for strings.
    """
    if name == "cumprod":
        msg = f"operation '{name}' not supported for dtype '{self.dtype}'"
        raise TypeError(msg)

    # We may need to strip out trailing NA values
    tail: pa.array | None = None
    na_mask: pa.array | None = None
    pa_array = self._pa_array
    np_func = {
        "cumsum": np.cumsum,
        "cummin": np.minimum.accumulate,
        "cummax": np.maximum.accumulate,
    }[name]

    if self._hasna:
        na_mask = pc.is_null(pa_array)
        if pc.all(na_mask) == pa.scalar(True):
            return self._from_pyarrow_array(pa_array)
        if skipna:
            if name == "cumsum":
                pa_array = _safe_fill_null(pa_array, "")
            else:
                # We can retain the running min/max by forward/backward filling.
                pa_array = pc.fill_null_forward(pa_array)
                pa_array = pc.fill_null_backward(pa_array)
        else:
            # When not skipping NA values, the result should be null from
            # the first NA value onward.
            idx = pc.index(na_mask, True).as_py()
            tail = pa.nulls(len(pa_array) - idx, type=pa_array.type)
            pa_array = pa_array[:idx]

    # error: Cannot call function of unknown type
    pa_result = pa.array(np_func(pa_array), type=pa_array.type)  # type: ignore[operator]

    if tail is not None:
        pa_result = pa.concat_arrays([pa_result, tail])
    elif na_mask is not None:
        pa_result = pc.if_else(na_mask, None, pa_result)

    result = self._from_pyarrow_array(pa_result)
    return result

def _reduce_calc(
    self, name: str, *, skipna: bool = True, keepdims: bool = False, **kwargs
):
    pa_result = self._reduce_pyarrow(name, skipna=skipna, **kwargs)

    if keepdims:
        if isinstance(pa_result, pa.Scalar):
            result = pa.array([pa_result.as_py()], type=pa_result.type)
        else:
            result = pa.array(
                [pa_result],
                type=to_pyarrow_type(infer_dtype_from_scalar(pa_result)[0]),
            )
        return result

    if pc.is_null(pa_result).as_py():
        return self.dtype.na_value
    elif isinstance(pa_result, pa.Scalar):
        result = pa_result.as_py()
        pa_type = pa_result.type
        if pa.types.is_duration(pa_type) and pa_type.unit != "ns":
            return Timedelta(result).as_unit(pa_type.unit)
        elif pa.types.is_timestamp(pa_type) and pa_type.unit != "ns":
            return Timestamp(result).as_unit(pa_type.unit)
        return result
    else:
        return pa_result

def _is_monotonic_increasing(self) -> bool:
    pa_array = self._pa_array
    if pa_array.null_count > 0:
        return False
    if len(pa_array) <= 1:
        return True
    try:
        return pc.all(pc.greater_equal(pa_array[1:], pa_array[:-1])).as_py()
    except pa.ArrowNotImplementedError:
        # If the type doesn't support comparison, e.g. list types
        return False

def _is_monotonic_decreasing(self) -> bool:
    pa_array = self._pa_array
    if pa_array.null_count > 0:
        return False
    if len(pa_array) <= 1:
        return True
    try:
        return pc.all(pc.less_equal(pa_array[1:], pa_array[:-1])).as_py()
    except pa.ArrowNotImplementedError:
        # If the type doesn't support comparison, e.g. list types
        return False

def _validate_setitem_value(self, value):
    """Maybe convert value to be pyarrow compatible."""
    self_temporal = _is_temporal_pa_type(self._pa_array.type)
    if self_temporal is not None:
        value_temporal = _is_temporal_value(value)
        if value_temporal is not None and value_temporal != self_temporal:
            # an all-NA value carries nothing to reinterpret; only the
            #  temporal direction is rejected, matching int64/Int64, see
            #  test_setitem_all_na_temporal_array_still_raises
            if value_temporal or not _is_all_na(value):
                msg = f"Invalid value '{value!s}' for dtype '{self.dtype}'"
                raise TypeError(msg)
            if is_list_like(value) and getattr(value, "ndim", 1) == 1:
                # _box_pa would still cast, and e.g. double -> timestamp has
                #  no cast kernel. len() is the element count only for a 1-D
                #  value, so anything else stays with _box_pa
                return pa.nulls(len(value), type=self._pa_array.type)
    try:
        value = self._box_pa(value, self._pa_array.type)
    except pa.ArrowTypeError as err:
        msg = f"Invalid value '{value!s}' for dtype '{self.dtype}'"
        raise TypeError(msg) from err
    return value

def _if_else(
    cls,
    cond: npt.NDArray[np.bool_] | bool,
    left: ArrayLike | Scalar,
    right: ArrayLike | Scalar,
) -> pa.Array:
    """
    Choose values based on a condition.

    Analogous to pyarrow.compute.if_else, with logic
    to fallback to numpy for unsupported types.

    Parameters
    ----------
    cond : npt.NDArray[np.bool_] or bool
    left : ArrayLike | Scalar
    right : ArrayLike | Scalar

    Returns
    -------
    pa.Array
    """

    # TODO: Remove this part when pa.if_else is fixed (GH#64320)
    def _maybe_combine(arr):
        if not isinstance(arr, pa.ChunkedArray) or not _is_varbinary_type(arr.type):
            return arr
        if not any(chunk.offset != 0 for chunk in arr.chunks):
            return arr
        try:
            return arr.combine_chunks()
        except (pa.ArrowInvalid, pa.ArrowCapacityError, MemoryError):
            return None

    left_c, right_c = _maybe_combine(left), _maybe_combine(right)
    if left_c is not None and right_c is not None:
        try:
            return pc.if_else(cond, left_c, right_c)
        except pa.ArrowNotImplementedError:
            pass
    if left_c is not None:
        left = left_c
    if right_c is not None:
        right = right_c

    def _to_numpy_and_type(value) -> tuple[np.ndarray, pa.DataType | None]:
        if isinstance(value, (pa.Array, pa.ChunkedArray)):
            pa_type = value.type
        elif isinstance(value, pa.Scalar):
            pa_type = value.type
            value = value.as_py()
        else:
            pa_type = None
        return np.array(value, dtype=object), pa_type

    left, left_type = _to_numpy_and_type(left)
    right, right_type = _to_numpy_and_type(right)
    pa_type = left_type or right_type
    result = np.where(cond, left, right)
    return pa.array(result, type=pa_type, from_pandas=is_nan_na())

def _to_masked(self):
    pa_dtype = self._pa_array.type

    if pa.types.is_floating(pa_dtype) or pa.types.is_integer(pa_dtype):
        na_value = 1
    elif pa.types.is_boolean(pa_dtype):
        na_value = True
    else:
        raise NotImplementedError

    dtype = _arrow_dtype_mapping()[pa_dtype]
    mask = self.isna()
    arr = self.to_numpy(dtype=dtype.numpy_dtype, na_value=na_value)
    return dtype.construct_array_type()(arr, mask)

def _to_groupby_compatible(self) -> ExtensionArray:
    """Convert to a type compatible with groupby cython ops."""
    pa_type = self._pa_array.type
    if pa.types.is_timestamp(pa_type):
        return self._to_datetimearray()
    elif pa.types.is_duration(pa_type):
        return self._to_timedeltaarray()
    else:
        return self._to_masked()

def _groupby_result_to_arrow(self, result: ArrayLike) -> ArrayLike:
    """Convert a groupby result from a delegated type back to Arrow."""
    if isinstance(result, np.ndarray):
        return result
    elif isinstance(result, BaseMaskedArray):
        pa_result = result.__arrow_array__()
        return self._from_pyarrow_array(pa_result)
    else:
        # DatetimeArray, TimedeltaArray
        pa_result = pa.array(result)
        return self._from_pyarrow_array(pa_result)

def _apply_elementwise(self, func: Callable) -> list[list[Any]]:
    """Apply a callable to each element while maintaining the chunking structure."""
    return [
        [
            None if val is None else func(val)
            for val in chunk.to_numpy(zero_copy_only=False)
        ]
        for chunk in self._pa_array.iterchunks()

def _str_contains(
    self,
    pat: str | re.Pattern,
    case: bool = True,
    flags: int = 0,
    na: Scalar | lib.NoDefault = lib.no_default,
    regex: bool = True,
):
    if regex:
        pat, case, flags = self._unwrap_re_pattern(pat, case, flags)

    if flags:
        if regex:
            compiled = self._compile_re_fallback(pat, case, flags)
            func = lambda val: compiled.search(val) is not None
        elif case:
            func = lambda val: pat in val
        else:
            upper_pat = pat.upper()  # type: ignore[union-attr]
            func = lambda val: upper_pat in val.upper()
        result = self._apply_re_fallback(func, pa.bool_())
        return self._convert_bool_result(result, na=na, method_name="contains")

    return ArrowStringArrayMixin._str_contains(self, pat, case, flags, na, regex)

def _str_count(self, pat: str | re.Pattern, flags: int = 0) -> Self:
    pat, case, flags = self._unwrap_re_pattern(pat, True, flags)

    if flags:
        compiled = self._compile_re_fallback(pat, case, flags)
        func = lambda val: len(compiled.findall(val))
        # match the width pyarrow's kernel reports for this storage type
        pa_type = (
            pa.int64()
            if pa.types.is_large_string(self._pa_array.type)
            or pa.types.is_large_binary(self._pa_array.type)
            else pa.int32()
        )
        return self._convert_int_result(self._apply_re_fallback(func, pa_type))

    result = pc.count_substring_regex(self._pa_array, pat, ignore_case=not case)
    return self._convert_int_result(result)

def _str_replace(
    self,
    pat: str | re.Pattern,
    repl: str | Callable,
    n: int = -1,
    case: bool = True,
    flags: int = 0,
    regex: bool = True,
) -> Self:
    if (
        isinstance(pat, re.Pattern)
        or callable(repl)
        or not case
        or flags
        or (isinstance(repl, str) and r"\g<" in repl)
    ):
        # None of these are expressible with pc.replace_substring_regex; mirror
        #  ObjectStringArrayMixin._str_replace instead, which leaves the flags
        #  of an already-compiled `pat` alone. GH#66348
        if not isinstance(pat, re.Pattern):
            if not regex:
                pat = re.escape(pat)
            pat = self._compile_re_fallback(pat, case, flags)
        count = n if n >= 0 else 0
        func = lambda val: pat.sub(repl=repl, string=val, count=count)
        return self._from_pyarrow_array(
            self._apply_re_fallback(func, self._pa_array.type)
        )

    return ArrowStringArrayMixin._str_replace(
        self, pat, repl, n, case, flags, regex

def _str_join(self, sep: str) -> Self:
    pa_type = self._pa_array.type
    if pa.types.is_string(pa_type) or pa.types.is_large_string(pa_type):
        result = self._apply_elementwise(list)
        # pc.binary_join has no kernel for large_string values, so join as
        #  string and restore the input's own type afterwards
        listed = pa.chunked_array(result, type=pa.list_(pa.string()))
        return self._from_pyarrow_array(pc.binary_join(listed, sep).cast(pa_type))
    return self._from_pyarrow_array(pc.binary_join(self._pa_array, sep))

def _str_extract(self, pat: str | re.Pattern, flags: int = 0, expand: bool = True):
    compiled = self._compile_re_fallback(pat, flags=flags)
    groups = compiled.groupindex.keys()
    if len(groups) == 0:
        raise ValueError(f"{pat=} must contain a symbolic group name.")

    if flags or isinstance(pat, re.Pattern):
        # pc.extract_regex has no `ignore_case`, so unlike elsewhere not even
        #  IGNORECASE can be honored by the kernel
        matches = self._apply_elementwise(compiled.search)

        def extract_group(name: str):
            chunks = [
                [None if match is None else match.group(name) for match in chunk]
                for chunk in matches
            ]
            return self._from_pyarrow_array(
                pa.chunked_array(chunks, type=self._pa_array.type)
            )

        if not expand:
            return extract_group(next(iter(groups)))
        return {col: extract_group(col) for col in groups}

    result = pc.extract_regex(self._pa_array, pat)
    if expand:
        return {
            col: self._from_pyarrow_array(pc.struct_field(result, [i]))
            for col, i in zip(groups, range(result.type.num_fields), strict=True)
        }
    else:
        return type(self)(pc.struct_field(result, [0]))

def _str_split(
    self,
    pat: str | None = None,
    n: int | None = -1,
    expand: bool = False,
    regex: bool | None = None,
) -> Self:
    if n in {-1, 0}:
        n = None
    if pat is None:
        split_func = pc.utf8_split_whitespace
    elif regex is True:
        split_func = functools.partial(pc.split_pattern_regex, pattern=pat)
    elif regex is False:
        split_func = functools.partial(pc.split_pattern, pattern=pat)
    # GH#58321: regex is None — infer: single-char literal, multi-char regex
    elif len(pat) == 1:
        split_func = functools.partial(pc.split_pattern, pattern=pat)
    else:
        split_func = functools.partial(pc.split_pattern_regex, pattern=pat)
    return self._from_pyarrow_array(split_func(self._pa_array, max_splits=n))

def _str_rsplit(self, pat: str | None = None, n: int | None = -1) -> Self:
    if pat is not None and not isinstance(pat, str):
        msg = f"expected a string object, not {type(pat).__name__}"
        raise TypeError(msg)
    if n in {-1, 0}:
        n = None
    if pat is None:
        return self._from_pyarrow_array(
            pc.utf8_split_whitespace(self._pa_array, max_splits=n, reverse=True)
        )
    return self._from_pyarrow_array(
        pc.split_pattern(self._pa_array, pat, max_splits=n, reverse=True)

def _dt_to_pytimedelta(self) -> np.ndarray:
    data = self._pa_array.to_pylist()
    if self._dtype.pyarrow_dtype.unit == "ns":
        data = [None if ts is None else ts.to_pytimedelta() for ts in data]
    return np.array(data, dtype=object)

def _dt_as_unit(self, unit: str) -> Self:
    pa_type = self._pa_array.type
    if pa.types.is_timestamp(pa_type):
        target_type = pa.timestamp(unit, tz=pa_type.tz)
    elif pa.types.is_duration(pa_type):
        target_type = pa.duration(unit)
    else:
        raise NotImplementedError(f"as_unit not implemented for {pa_type}")

    nanos_per_unit = {"s": 1_000_000_000, "ms": 1_000_000, "us": 1_000, "ns": 1}
    from_nanos = nanos_per_unit[pa_type.unit]
    to_nanos = nanos_per_unit[unit]
    if to_nanos <= from_nanos:
        # Same or finer resolution: exact upscale. Use safe=True so that
        # out-of-bounds values raise instead of silently wrapping, matching
        # numpy/pandas as_unit.
        try:
            result = pc.cast(self._pa_array, target_type)
        except pa.ArrowInvalid as err:
            err_type = (
                OutOfBoundsDatetime
                if pa.types.is_timestamp(pa_type)
                else OutOfBoundsTimedelta
            )
            raise err_type(
                f"Cannot convert {pa_type} to {target_type} without overflow"
            ) from err
    else:
        # Coarser resolution: floor toward -inf like numpy/pandas. pc.cast
        # truncates toward zero, which is wrong for negative timedeltas and
        # pre-epoch timestamps (GH#63573).
        ratio = pa.scalar(to_nanos // from_nanos, type=pa.int64())
        i8 = pc.cast(self._pa_array, pa.int64())
        quotient = pc.divide(i8, ratio)
        remainder = pc.subtract(i8, pc.multiply(quotient, ratio))
        floored = pc.if_else(
            pc.less(remainder, 0), pc.subtract(quotient, 1), quotient
        )
        result = pc.cast(floored, target_type)
    return self._from_pyarrow_array(result)

def _dt_to_pydatetime(self) -> Series:
    from pandas import Series

    if pa.types.is_date(self.dtype.pyarrow_dtype):
        raise ValueError(
            f"to_pydatetime cannot be called with {self.dtype.pyarrow_dtype} type. "
            "Convert to pyarrow timestamp type."
        )
    data = self._pa_array.to_pylist()
    if self._dtype.pyarrow_dtype.unit == "ns":
        data = [None if ts is None else ts.to_pydatetime(warn=False) for ts in data]
    return Series(data, dtype=object)

def _dt_tz_localize(
    self,
    tz,
    ambiguous: TimeAmbiguous = "raise",
    nonexistent: TimeNonexistent = "raise",
) -> Self:
    if ambiguous != "raise":
        raise NotImplementedError(f"{ambiguous=} is not supported")
    nonexistent_pa = {
        "raise": "raise",
        "shift_backward": "earliest",
        "shift_forward": "latest",
    }.get(
        nonexistent,  # type: ignore[arg-type]
        None,
    )
    if nonexistent_pa is None:
        raise NotImplementedError(f"{nonexistent=} is not supported")
    if tz is None:
        result = pc.local_timestamp(self._pa_array)
    else:
        result = pc.assume_timezone(
            self._pa_array, str(tz), ambiguous=ambiguous, nonexistent=nonexistent_pa
        )
    return self._from_pyarrow_array(result)

def _list_element_neg(chunk: pa.Array, key: int) -> pa.Array:
    if pa.types.is_fixed_size_list(chunk.type):
        chunk = chunk.cast(pa.list_(chunk.type.value_type))
    if pc.any(pc.less(pc.list_value_length(chunk), -key)).as_py():
        raise IndexError(f"list index {key} out of range")
    indices = pc.add(chunk.offsets[1:], key)
    if chunk.null_count:
        indices = pc.if_else(chunk.is_valid(), indices, None)
    return chunk.values.take(indices)

def _validate(self, data) -> None:
    dtype = data.dtype
    if not HAS_PYARROW or not isinstance(dtype, ArrowDtype):
        # Raise AttributeError so that inspect can handle non-struct Series.
        raise AttributeError(self._validation_msg.format(dtype=dtype))

    if not self._is_valid_pyarrow_dtype(dtype.pyarrow_dtype):
        # Raise AttributeError so that inspect can handle invalid Series.
        raise AttributeError(self._validation_msg.format(dtype=dtype))

def _is_valid_pyarrow_dtype(self, pyarrow_dtype) -> bool:
    return (
        pa.types.is_list(pyarrow_dtype)
        or pa.types.is_fixed_size_list(pyarrow_dtype)
        or pa.types.is_large_list(pyarrow_dtype)

def __eq__(self, other):
    if isinstance(other, pyarrow.BaseExtensionType):
        return type(self) == type(other) and self.freq == other.freq
    else:
        return NotImplemented

def __eq__(self, other):
    if isinstance(other, pyarrow.BaseExtensionType):
        return (
            type(self) == type(other)
            and self.subtype == other.subtype
            and self.closed == other.closed
        )
    else:
        return NotImplemented

def to_pandas_dtype(self) -> IntervalDtype:
    subtype = self.subtype
    if pyarrow.types.is_timestamp(subtype) and subtype.tz is not None:
        # pyarrow may return a pytz zone, which != pandas' zoneinfo zone
        pandas_subtype: object = DatetimeTZDtype(unit=subtype.unit, tz=subtype.tz)
    else:
        pandas_subtype = subtype.to_pandas_dtype()
    return IntervalDtype(pandas_subtype, self.closed)

def dtype(self) -> tuple[DtypeKind, int, str, str]:
    dtype = self._col.dtype

    if isinstance(dtype, pd.CategoricalDtype):
        codes = self._col.values.codes
        (
            _,
            bitwidth,
            c_arrow_dtype_f_str,
            _,
        ) = self._dtype_from_pandasdtype(codes.dtype)
        return (
            DtypeKind.CATEGORICAL,
            bitwidth,
            c_arrow_dtype_f_str,
            Endianness.NATIVE,
        )
    elif is_string_dtype(dtype):
        if infer_dtype(self._col) in ("string", "empty"):
            return (
                DtypeKind.STRING,
                8,
                dtype_to_arrow_c_fmt(dtype),
                Endianness.NATIVE,
            )
        raise NotImplementedError("Non-string object dtypes are not supported yet")
    else:
        return self._dtype_from_pandasdtype(dtype)

def _dtype_from_pandasdtype(self, dtype) -> tuple[DtypeKind, int, str, str]:
    """
    See `self.dtype` for details.
    """
    # Note: 'c' (complex) not handled yet (not in array spec v1).
    #       'b', 'B' (bytes), 'S', 'a', (old-style string) 'V' (void) not handled
    #       datetime and timedelta both map to datetime (is timedelta handled?)

    kind = _NP_KINDS.get(dtype.kind, None)
    if kind is None:
        # Not a NumPy dtype. Check if it's a categorical maybe
        raise ValueError(f"Data type {dtype} not supported by interchange protocol")
    if isinstance(dtype, ArrowDtype):
        byteorder = dtype.numpy_dtype.byteorder
    elif isinstance(dtype, DatetimeTZDtype):
        byteorder = dtype.base.byteorder  # type: ignore[union-attr]
    elif isinstance(dtype, BaseMaskedDtype):
        byteorder = dtype.numpy_dtype.byteorder
    else:
        byteorder = dtype.byteorder

    if dtype == "bool[pyarrow]":
        # return early to avoid the `* 8` below, as this is a bitmask
        # rather than a bytemask
        return (
            kind,
            dtype.itemsize,  # pyright: ignore[reportAttributeAccessIssue]
            ArrowCTypes.BOOL,
            byteorder,
        )

    return kind, dtype.itemsize * 8, dtype_to_arrow_c_fmt(dtype), byteorder

def get_chunks(self, n_chunks: int | None = None):
    """
    Return an iterator yielding the chunks.
    See `DataFrame.get_chunks` for details on ``n_chunks``.
    """
    if n_chunks and n_chunks > 1:
        size = len(self._col)
        step = size // n_chunks
        if size % n_chunks != 0:
            step += 1
        for start in range(0, step * n_chunks, step):
            yield PandasColumn(
                self._col.iloc[start : start + step], self._allow_copy
            )
    else:
        yield self

def select_columns(self, indices: Sequence[int]) -> PandasDataFrameXchg:
    if not isinstance(indices, abc.Sequence):
        raise ValueError("`indices` is not a sequence")
    if not isinstance(indices, list):
        indices = list(indices)

    return PandasDataFrameXchg(
        self._df.iloc[:, indices], allow_copy=self._allow_copy

def select_columns_by_name(self, names: list[str]) -> PandasDataFrameXchg:  # type: ignore[override]
    if not isinstance(names, abc.Sequence):
        raise ValueError("`names` is not a sequence")
    if not isinstance(names, list):
        names = list(names)

    return PandasDataFrameXchg(self._df.loc[:, names], allow_copy=self._allow_copy)

def get_chunks(self, n_chunks: int | None = None) -> Iterable[PandasDataFrameXchg]:
    """
    Return an iterator yielding the chunks.
    """
    if n_chunks and n_chunks > 1:
        size = len(self._df)
        step = size // n_chunks
        if size % n_chunks != 0:
            step += 1
        for start in range(0, step * n_chunks, step):
            yield PandasDataFrameXchg(
                self._df.iloc[start : start + step, :],
                allow_copy=self._allow_copy,
            )
    else:
        yield self

def dtype_to_arrow_c_fmt(dtype: DtypeObj) -> str:
    """
    Represent pandas `dtype` as a format string in Apache Arrow C notation.

    Parameters
    ----------
    dtype : np.dtype
        Datatype of pandas DataFrame to represent.

    Returns
    -------
    str
        Format string in Apache Arrow C notation of the given `dtype`.
    """
    if isinstance(dtype, CategoricalDtype):
        return ArrowCTypes.INT64
    elif dtype == np.dtype("O"):
        return ArrowCTypes.STRING
    elif isinstance(dtype, ArrowDtype):
        import pyarrow as pa

        pa_type = dtype.pyarrow_dtype
        if pa.types.is_decimal(pa_type):
            return f"d:{pa_type.precision},{pa_type.scale}"
        elif pa.types.is_timestamp(pa_type) and pa_type.tz is not None:
            return f"ts{pa_type.unit[0]}:{pa_type.tz}"
        format_str = PYARROW_CTYPES.get(str(pa_type), None)
        if format_str is not None:
            return format_str

    format_str = getattr(ArrowCTypes, dtype.name.upper(), None)
    if format_str is not None:
        return format_str

    if isinstance(dtype, pd.StringDtype):
        # TODO(infer_string) this should be LARGE_STRING for pyarrow storage,
        # but current tests don't cover this distinction
        return ArrowCTypes.STRING

    elif lib.is_np_dtype(dtype, "M"):
        # Selecting the first char of resolution string:
        # dtype.str -> '<M8[ns]' -> 'n'
        resolution = np.datetime_data(dtype)[0][0]
        return ArrowCTypes.TIMESTAMP.format(resolution=resolution, tz="")

    elif isinstance(dtype, DatetimeTZDtype):
        return ArrowCTypes.TIMESTAMP.format(resolution=dtype.unit[0], tz=dtype.tz)

    elif isinstance(dtype, pd.BooleanDtype):
        return ArrowCTypes.BOOL

    raise NotImplementedError(
        f"Conversion of {dtype} to Arrow C format string is not implemented."

def __init__(self, x: np.ndarray, allow_copy: bool = True) -> None:
    """
    Handle only regular columns (= numpy arrays) for now.
    """
    if x.strides[0] and not x.strides == (x.dtype.itemsize,):
        # The protocol does not support strided buffers, so a copy is
        # necessary. If that's not allowed, we need to raise an exception.
        if allow_copy:
            x = x.copy()
        else:
            raise RuntimeError(
                "Exports cannot be zero-copy in the case of a non-contiguous buffer"
            )

    # Store the numpy array in which the data resides as a private
    # attribute, so we can use it to retrieve the public attributes
    self._x = x

def zsqrt(x):
    with np.errstate(all="ignore"):
        result = np.sqrt(x)
        mask = x < 0

    if isinstance(x, ABCDataFrame):
        if mask._values.any():
            result[mask] = 0
    elif mask.any():
        result[mask] = 0

    return result

def _validate(self) -> None:
    if self.center is not None and not is_bool(self.center):
        raise ValueError("center must be a boolean")
    if self.min_periods is not None:
        if not is_integer(self.min_periods):
            raise ValueError("min_periods must be an integer")
        if self.min_periods < 0:
            raise ValueError("min_periods must be >= 0")
        if is_integer(self.window) and self.min_periods > self.window:
            raise ValueError(
                f"min_periods {self.min_periods} must be <= window {self.window}"
            )
    if self.closed is not None and self.closed not in [
        "right",
        "both",
        "left",
        "neither",
    ]:
        raise ValueError("closed must be 'right', 'left', 'both' or 'neither'")
    if not isinstance(self.obj, (ABCSeries, ABCDataFrame)):
        raise TypeError(f"invalid type: {type(self)}")
    if isinstance(self.window, BaseIndexer):
        # Validate that the passed BaseIndexer subclass has
        # a get_window_bounds with the correct signature.
        get_window_bounds_signature = inspect.signature(
            self.window.get_window_bounds
        ).parameters.keys()
        expected_signature = inspect.signature(
            BaseIndexer().get_window_bounds
        ).parameters.keys()
        if get_window_bounds_signature != expected_signature:
            raise ValueError(
                f"{type(self.window).__name__} does not implement "
                f"the correct signature for get_window_bounds"
            )
    if self.method not in ["table", "single"]:
        raise ValueError("method must be 'table' or 'single")
    if self.step is not None:
        if not is_integer(self.step):
            raise ValueError("step must be an integer")
        if self.step < 0:
            raise ValueError("step must be >= 0")

def _check_window_bounds(
    self, start: np.ndarray, end: np.ndarray, num_vals: int
) -> None:
    if len(start) != len(end):
        raise ValueError(
            f"start ({len(start)}) and end ({len(end)}) bounds must be the "
            f"same length"
        )
    if len(start) != (num_vals + (self.step or 1) - 1) // (self.step or 1):
        raise ValueError(
            f"start and end bounds ({len(start)}) must be the same length "
            f"as the object ({num_vals}) divided by the step ({self.step}) "

def _slice_axis_for_step(self, index: Index, result: Sized | None = None) -> Index:
    """
    Slices the index for a given result and the preset step.
    """
    return (
        index
        if result is None or len(result) == len(index)
        else index[:: self.step]

def _create_data(self, obj: NDFrameT, numeric_only: bool = False) -> NDFrameT:
    """
    Split data into blocks & return conformed data.
    """
    # filter out the on from the object
    if self.on is not None and not isinstance(self.on, Index) and obj.ndim == 2:
        obj = obj.reindex(columns=obj.columns.difference([self.on], sort=False))
    if obj.ndim > 1 and numeric_only:
        obj = self._make_numeric_only(obj)
    return obj

def __getattr__(self, attr: str):
    if attr in self._internal_names_set:
        return object.__getattribute__(self, attr)
    if attr in self.obj:
        return self[attr]

    raise AttributeError(
        f"'{type(self).__name__}' object has no attribute '{attr}'"

def _prep_values(self, values: ArrayLike) -> np.ndarray:
    """Convert input to numpy arrays for Cython routines"""
    if needs_i8_conversion(values.dtype) or is_arrow_temporal_dtype(values.dtype):
        # GH#66445 ArrowDtype timestamps/durations are not covered by
        #  needs_i8_conversion, so without the second check they fell through
        #  to the ExtensionArray branch below and were silently converted to
        #  float64 counts instead of raising like their NumPy counterparts.
        raise NotImplementedError(
            f"ops for {type(self).__name__} for this "
            f"dtype {values.dtype} is not implemented"
        )
    # GH #12373 : rolling functions error on float32 data
    # make sure the data is coerced to float64
    try:
        if isinstance(values, ExtensionArray):
            values = values.to_numpy(np.float64, na_value=np.nan)
        else:
            values = ensure_float64(values)
    except (ValueError, TypeError) as err:
        raise TypeError(f"cannot handle this type -> {values.dtype}") from err

    # Convert inf to nan for C funcs
    inf = np.isinf(values)
    if inf.any():
        values = np.where(inf, np.nan, values)

    return values

def _index_array(self) -> npt.NDArray[np.int64] | None:
    # TODO: why do we get here with e.g. MultiIndex?
    if isinstance(self._on, (PeriodIndex, DatetimeIndex, TimedeltaIndex)):
        return self._on.asi8
    elif isinstance(self._on.dtype, ArrowDtype) and self._on.dtype.kind in "mM":
        return self._on.to_numpy(dtype=np.int64)
    return None

def _resolve_output(self, out: DataFrame, obj: DataFrame) -> DataFrame:
    """Validate and finalize result."""
    if out.shape[1] == 0 and obj.shape[1] > 0:
        raise DataError("No numeric types to aggregate")
    if out.shape[1] == 0:
        return obj.astype("float64")

    self._insert_on_column(out, obj)
    return out

def _get_window_indexer(self) -> BaseIndexer:
    """
    Return an indexer class that will compute the window start and end bounds
    """
    if isinstance(self.window, BaseIndexer):
        return self.window
    if self._win_freq_i8 is not None:
        return VariableWindowIndexer(
            index_array=self._index_array,
            window_size=self._win_freq_i8,
            center=self.center,
        )
    return FixedWindowIndexer(window_size=self.window)

def _apply_series(
    self, homogeneous_func: Callable[..., ArrayLike], name: str | None = None
) -> Series:
    """
    Series version of _apply_columnwise
    """
    obj = self._create_data(self._selected_obj)

    if name == "count":
        # GH 12541: Special case for count where we support date-like types
        obj = notna(obj).astype(int)
    try:
        values = self._prep_values(obj._values)
    except (TypeError, NotImplementedError) as err:
        raise DataError("No numeric types to aggregate") from err

    result = homogeneous_func(values)
    index = self._slice_axis_for_step(obj.index, result)
    return obj._constructor(result, index=index, name=obj.name)

def _apply_pairwise(
    self,
    target: DataFrame | Series,
    other: DataFrame | Series | None,
    pairwise: bool | None,
    func: Callable[[DataFrame | Series, DataFrame | Series], DataFrame | Series],
    numeric_only: bool,
) -> DataFrame | Series:
    """
    Apply the given pairwise function given 2 pandas objects (DataFrame/Series)
    """
    target = self._create_data(target, numeric_only)
    if other is None:
        other = target
        # only default unset
        pairwise = True if pairwise is None else pairwise
    elif not isinstance(other, (ABCDataFrame, ABCSeries)):
        raise ValueError("other must be a DataFrame or Series")
    elif other.ndim == 2 and numeric_only:
        other = self._make_numeric_only(other)

    return flex_binary_moment(target, other, func, pairwise=bool(pairwise))

def aggregate(self, func=None, *args, **kwargs):
    relabeling, func, columns, order = reconstruct_func(func, **kwargs)
    result = ResamplerWindowApply(self, func, args=args, kwargs=kwargs).agg()
    if isinstance(result, ABCDataFrame) and relabeling:
        result = result.iloc[:, order]
        result.columns = columns
    if result is None:
        return self.apply(func, raw=False, args=args, kwargs=kwargs)
    return result

def _validate(self) -> None:
    super()._validate()

    if not isinstance(self.win_type, str):
        raise ValueError(f"Invalid win_type {self.win_type}")
    signal = import_optional_dependency(
        "scipy.signal.windows", extra="Scipy is required to generate window weight."
    )
    self._scipy_weight_generator = getattr(signal, self.win_type, None)
    if self._scipy_weight_generator is None:
        raise ValueError(f"Invalid win_type {self.win_type}")

    if isinstance(self.window, BaseIndexer):
        raise NotImplementedError(
            "BaseIndexer subclasses not implemented with win_types."
        )
    if not is_integer(self.window) or self.window < 0:
        raise ValueError("window must be an integer 0 or greater")

    if self.method != "single":
        raise NotImplementedError("'single' is the only supported method type.")

def apply(
    self,
    func: Callable[..., Any],
    raw: bool = False,
    engine: Literal["cython", "numba"] | None = None,
    engine_kwargs: dict[str, bool] | None = None,
    args: tuple[Any, ...] | None = None,
    kwargs: dict[str, Any] | None = None,
):
    if args is None:
        args = ()
    if kwargs is None:
        kwargs = {}

    if not is_bool(raw):
        raise ValueError("raw parameter must be `True` or `False`")

    numba_args: tuple[Any, ...] = ()
    if maybe_use_numba(engine):
        if raw is False:
            raise ValueError("raw must be `True` when using the numba engine")
        numba_args, kwargs = prepare_function_arguments(
            func, args, kwargs, num_required_args=1
        )
        if self.method == "single":
            apply_func = generate_numba_apply_func(
                func, **get_jit_arguments(engine_kwargs)
            )
        else:
            apply_func = generate_numba_table_func(
                func, **get_jit_arguments(engine_kwargs)
            )
    elif engine in ("cython", None):
        if engine_kwargs is not None:
            raise ValueError("cython engine does not accept engine_kwargs")
        apply_func = self._generate_cython_apply_func(args, kwargs, raw, func)
    else:
        raise ValueError("engine must be either 'numba' or 'cython'")

    return self._apply(
        apply_func,
        name="apply",
        numba_args=numba_args,

def sum(
    self,
    numeric_only: bool = False,
    engine: Literal["cython", "numba"] | None = None,
    engine_kwargs: dict[str, bool] | None = None,
):
    if maybe_use_numba(engine):
        if self.method == "table":
            func = generate_manual_numpy_nan_agg_with_axis(np.nansum)
            return self.apply(
                func,
                raw=True,
                engine=engine,
                engine_kwargs=engine_kwargs,
            )
        else:
            from pandas.core._numba.kernels import sliding_sum

            return self._numba_apply(sliding_sum, engine_kwargs)
    window_func = window_aggregations.roll_sum
    return self._apply(window_func, name="sum", numeric_only=numeric_only)

def max(
    self,
    numeric_only: bool = False,
    engine: Literal["cython", "numba"] | None = None,
    engine_kwargs: dict[str, bool] | None = None,
):
    if maybe_use_numba(engine):
        if self.method == "table":
            func = generate_manual_numpy_nan_agg_with_axis(np.nanmax)
            return self.apply(
                func,
                raw=True,
                engine=engine,
                engine_kwargs=engine_kwargs,
            )
        else:
            from pandas.core._numba.kernels import sliding_min_max

            return self._numba_apply(sliding_min_max, engine_kwargs, is_max=True)
    window_func = window_aggregations.roll_max
    return self._apply(window_func, name="max", numeric_only=numeric_only)

