def std(
    self,
    ddof: int = 1,
    numeric_only: bool = False,
    engine: Literal["cython", "numba"] | None = None,
    engine_kwargs: dict[str, bool] | None = None,
):
    if maybe_use_numba(engine):
        if self.method == "table":
            raise NotImplementedError("std not supported with method='table'")
        from pandas.core._numba.kernels import sliding_var

        return zsqrt(self._numba_apply(sliding_var, engine_kwargs, ddof=ddof))
    window_func = window_aggregations.roll_var

    def zsqrt_func(values, begin, end, min_periods):
        return zsqrt(window_func(values, begin, end, min_periods, ddof=ddof))

    return self._apply(
        zsqrt_func,
        name="std",
        numeric_only=numeric_only,

def var(
    self,
    ddof: int = 1,
    numeric_only: bool = False,
    engine: Literal["cython", "numba"] | None = None,
    engine_kwargs: dict[str, bool] | None = None,
):
    if maybe_use_numba(engine):
        if self.method == "table":
            raise NotImplementedError("var not supported with method='table'")
        from pandas.core._numba.kernels import sliding_var

        return self._numba_apply(sliding_var, engine_kwargs, ddof=ddof)
    window_func = partial(window_aggregations.roll_var, ddof=ddof)
    return self._apply(
        window_func,
        name="var",
        numeric_only=numeric_only,

def quantile(
    self,
    q: float,
    interpolation: QuantileInterpolation = "linear",
    numeric_only: bool = False,
):
    if q == 1.0:
        window_func = window_aggregations.roll_max
    elif q == 0.0:
        window_func = window_aggregations.roll_min
    else:
        window_func = partial(
            window_aggregations.roll_quantile,
            quantile=q,
            interpolation=interpolation,
        )

    return self._apply(window_func, name="quantile", numeric_only=numeric_only)

def _validate(self) -> None:
    super()._validate()

    # we allow rolling on a datetimelike index
    if (
        self.obj.empty
        or isinstance(self._on, (DatetimeIndex, TimedeltaIndex, PeriodIndex))
        or (isinstance(self._on.dtype, ArrowDtype) and self._on.dtype.kind in "mM")
    ) and isinstance(self.window, (str, BaseOffset, timedelta)):
        self._validate_datetimelike_monotonic()

        # this will raise ValueError on non-fixed freqs
        try:
            freq = to_offset(self.window)
        except (TypeError, ValueError) as err:
            raise ValueError(
                f"passed window {self.window} is not "
                "compatible with a datetimelike index"
            ) from err
        if isinstance(self._on, PeriodIndex):
            # error: Incompatible types in assignment (expression has type
            # "float", variable has type "Optional[int]")
            self._win_freq_i8 = freq.nanos / (  # type: ignore[assignment]
                self._on.freq.nanos / self._on.freq.n
            )
        else:
            try:
                unit = dtype_to_unit(self._on.dtype)  # type: ignore[arg-type]
            except TypeError:
                # if not a datetime dtype, eg for empty dataframes
                unit = "ns"
            unit = cast("TimeUnit", unit)
            self._win_freq_i8 = Timedelta(freq.nanos).as_unit(unit)._value

        # min_periods must be an integer
        if self.min_periods is None:
            self.min_periods = 1

        if self.step is not None:
            raise NotImplementedError(
                "step is not supported with frequency windows"
            )

    elif isinstance(self.window, BaseIndexer):
        # Passed BaseIndexer subclass should handle all other rolling kwargs
        pass
    elif not is_integer(self.window) or self.window < 0:
        raise ValueError("window must be an integer 0 or greater")

def _validate_datetimelike_monotonic(self) -> None:
    """
    Validate self._on is monotonic (increasing or decreasing) and has
    no NaT values for frequency windows.
    """
    if self._on.hasnans:
        self._raise_monotonic_error("values must not have NaT")
    if not (self._on.is_monotonic_increasing or self._on.is_monotonic_decreasing):
        self._raise_monotonic_error("values must be monotonic")

def _validate_datetimelike_monotonic(self) -> None:
    """
    Validate that each group in self._on is monotonic
    """
    # GH 46061
    if self._on.hasnans:
        self._raise_monotonic_error("values must not have NaT")
    for group_indices in self._grouper.indices.values():
        group_on = self._on.take(group_indices)
        if not (
            group_on.is_monotonic_increasing or group_on.is_monotonic_decreasing
        ):
            on = "index" if self.on is None else self.on
            raise ValueError(
                f"Each group within {on} must be monotonic. "
                f"Sort the values in {on} first."

def get_center_of_mass(
    comass: float | None,
    span: float | None,
    halflife: float | None,
    alpha: float | None,
) -> float:
    valid_count = common.count_not_none(comass, span, halflife, alpha)
    if valid_count > 1:
        raise ValueError("comass, span, halflife, and alpha are mutually exclusive")

    # Convert to center of mass; domain checks ensure 0 < alpha <= 1
    if comass is not None:
        if comass < 0:
            raise ValueError("comass must satisfy: comass >= 0")
    elif span is not None:
        if span < 1:
            raise ValueError("span must satisfy: span >= 1")
        comass = (span - 1) / 2
    elif halflife is not None:
        if halflife <= 0:
            raise ValueError("halflife must satisfy: halflife > 0")
        decay = 1 - np.exp(np.log(0.5) / halflife)
        comass = 1 / decay - 1
    elif alpha is not None:
        if alpha <= 0 or alpha > 1:
            raise ValueError("alpha must satisfy: 0 < alpha <= 1")
        comass = (1 - alpha) / alpha
    else:
        raise ValueError("Must pass one of comass, span, halflife, or alpha")

    return float(comass)

def length_of_indexer(indexer, target=None) -> int:
    """
    Return the expected length of target[indexer]

    Returns
    -------
    int
    """
    if target is not None and isinstance(indexer, slice):
        target_len = len(target)
        # GH#66100 slice.indices() correctly resolves None bounds for both
        # positive and negative step, which the previous manual arithmetic
        # did not (it could return negative lengths for negative-step
        # slices with start/stop left as None).
        start, stop, step = indexer.indices(target_len)
        return len(range(start, stop, step))
    elif isinstance(indexer, (ABCSeries, ABCIndex, np.ndarray, list)):
        if isinstance(indexer, list):
            indexer = np.array(indexer)

        if indexer.dtype == bool:
            # GH#25774
            # np.asarray because Index has no .sum; GH#68021
            return int(np.asarray(indexer).sum())
        return len(indexer)
    elif isinstance(indexer, range):
        try:
            return len(indexer)
        except OverflowError:
            step = indexer.step
            if step > 0:
                low, high = indexer.start, indexer.stop
            else:
                low, high = indexer.stop, indexer.start
                step = -step
            if low >= high:
                return 0
            return (high - low - 1) // step + 1
    elif not is_list_like_indexer(indexer):
        return 1
    raise AssertionError("cannot find the length of the indexer")

def unpack_tuple_and_ellipses(item: tuple[Any, ...]):
    """
    Possibly unpack arr[..., n] to arr[n]
    """
    if len(item) > 1:
        # Note: we are assuming this indexing is being done on a 1D arraylike
        if item[0] is Ellipsis:
            item = item[1:]
        elif item[-1] is Ellipsis:
            item = item[:-1]

    if len(item) > 1:
        raise IndexError("too many indices for array.")

    item = item[0]
    return item

def _safe_fill_null(
    arr: pa.Array | pa.ChunkedArray, fill_value: Any
) -> pa.Array | pa.ChunkedArray:
    """
    Safe wrapper for pyarrow.compute.fill_null with fallback for Windows + pyarrow 21.

    pyarrow 21.0.0 on Windows has a bug in fill_null that incorrectly fills null values.
    This function uses a fallback implementation for that specific case, otherwise uses
    the standard pyarrow.compute.fill_null.

    Parameters
    ----------
    arr : pyarrow.Array | pyarrow.ChunkedArray
        Input array with potential null values.
    fill_value : Any
        Value to fill nulls with.

    Returns
    -------
    pyarrow.Array | pyarrow.ChunkedArray
        Array with nulls filled with fill_value.
    """
    import pyarrow.compute as pc

    is_windows = sys.platform in ["win32", "cygwin"]
    use_fallback = (
        HAS_PYARROW and is_windows and not pa_version_under21p0 and pa_version_under22p0
    )
    if not use_fallback or isinstance(fill_value, (pa.Array, pa.ChunkedArray)):
        return pc.fill_null(arr, fill_value)

    fill_scalar = pa.scalar(fill_value, type=arr.type)

    if pa.types.is_duration(arr.type):

        def fill_null_duration(arr: pa.Array, fill_scalar: pa.Scalar) -> pa.Array:
            mask = pc.is_null(arr)
            zero_duration = pa.scalar(0, type=arr.type)
            arr_zeroed = pc.if_else(mask, zero_duration, arr)
            return pc.if_else(mask, fill_scalar, arr_zeroed)

        if isinstance(arr, pa.ChunkedArray):
            return pa.chunked_array(
                [fill_null_duration(chunk, fill_scalar) for chunk in arr.chunks]
            )
        return fill_null_duration(arr, fill_scalar)

    if isinstance(arr, pa.ChunkedArray):
        return pa.chunked_array(
            [pc.if_else(pc.is_null(chunk), fill_scalar, chunk) for chunk in arr.chunks]
        )
    return pc.if_else(pc.is_null(arr), fill_scalar, arr)

def _cgroup_cpu_quota() -> float | None:
    """CPUs allowed by the process's cgroup CFS quota, or None if unlimited."""
    # cgroup v2; under a cgroup namespace (the common container case) this is the
    # limit the container itself sees.
    text = _read_sysfs_str("/sys/fs/cgroup/cpu.max")
    if text is not None:
        return _parse_cgroup_v2_quota(text)
    # cgroup v1
    quota = _read_sysfs_int("/sys/fs/cgroup/cpu/cpu.cfs_quota_us")
    period = _read_sysfs_int("/sys/fs/cgroup/cpu/cpu.cfs_period_us")
    if quota and quota > 0 and period and period > 0:
        return quota / period
    return None

def get_version(module: types.ModuleType) -> str:
    version = getattr(module, "__version__", None)

    if version is None:
        raise ImportError(f"Can't determine version for {module.__name__}")
    if module.__name__ == "psycopg2":
        # psycopg2 appends " (dt dec pq3 ext lo64)" to its version
        version = version.split()[0]
    return version

def load_newobj(self) -> None:
    args = self.stack.pop()  # type: ignore[attr-defined]
    cls = self.stack.pop()  # type: ignore[attr-defined]

    # compat
    if issubclass(cls, DatetimeArray) and not args:
        arr = np.array([], dtype="M8[ns]")
        obj = cls.__new__(cls, arr, arr.dtype)  # pyright: ignore[reportCallIssue]
    elif issubclass(cls, TimedeltaArray) and not args:
        arr = np.array([], dtype="m8[ns]")
        obj = cls.__new__(cls, arr, arr.dtype)  # pyright: ignore[reportCallIssue]
    elif cls is BlockManager and not args:
        # error: Too many arguments for "__new__" of "object"
        obj = cls.__new__(cls, (), [], False)  # type: ignore[call-arg]
    else:
        obj = cls.__new__(cls, *args)
    self.append(obj)  # type: ignore[attr-defined]

def process_skipna(
    skipna: bool | ndarray | None, args: tuple[Any, ...]
) -> tuple[bool, tuple[Any, ...]]:
    if isinstance(skipna, ndarray) or skipna is None:
        args = (skipna, *args)
        skipna = True

    return skipna, args

def __call__(
    self,
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
    fname: str | None = None,
    max_fname_arg_count: int | None = None,
    method: str | None = None,
) -> None:
    if not args and not kwargs:
        return None

    fname = self.fname if fname is None else fname
    max_fname_arg_count = (
        self.max_fname_arg_count
        if max_fname_arg_count is None
        else max_fname_arg_count
    )
    method = self.method if method is None else method

    if method == "args":
        validate_args(fname, args, cast("int", max_fname_arg_count), self.defaults)
    elif method == "kwargs":
        validate_kwargs(fname, kwargs, self.defaults)
    elif method == "both":
        validate_args_and_kwargs(
            fname, args, kwargs, cast("int", max_fname_arg_count), self.defaults
        )
    else:
        raise ValueError(f"invalid validation method '{method}'")

def _process_single_doc(self, single_doc):
    """
    Make sure the provided value for --single is a path to an existing
    .rst/.ipynb file, or a pandas object that can be imported.

    For example, categorial.rst or pandas.DataFrame.head. For the latter,
    return the corresponding file path
    (e.g. reference/api/pandas.DataFrame.head.rst).
    """
    base_name, extension = os.path.splitext(single_doc)
    if extension in (".rst", ".ipynb"):
        if os.path.exists(os.path.join(SOURCE_PATH, single_doc)):
            return single_doc
        else:
            raise FileNotFoundError(f"File {single_doc} not found")

    elif single_doc.startswith("pandas."):
        try:
            obj = pandas  # noqa: F821
            for name in single_doc.split("."):
                obj = getattr(obj, name)
        except AttributeError as err:
            raise ImportError(f"Could not import {single_doc}") from err
        else:
            return single_doc[len("pandas.") :]
    else:
        raise ValueError(
            f"--single={single_doc} not understood. "

def html(self):
    """
    Build HTML documentation.
    """
    ret_code = self._sphinx_build("html")
    zip_fname = os.path.join(BUILD_PATH, "html", "pandas.zip")
    if os.path.exists(zip_fname):
        os.remove(zip_fname)  # noqa: TID251

    if ret_code == 0:
        if self.single_doc_html is not None:
            if not self.no_browser:
                self._open_browser(self.single_doc_html)
        else:
            self._add_redirects()
            if self.whatsnew and not self.no_browser:
                self._open_browser(os.path.join("whatsnew", "index.html"))

    return ret_code

def latex(self, force=False):
    """
    Build PDF documentation.
    """
    if sys.platform == "win32":
        sys.stderr.write("latex build has not been tested on windows\n")
    else:
        ret_code = self._sphinx_build("latex")
        os.chdir(os.path.join(BUILD_PATH, "latex"))
        if force:
            for i in range(3):
                self._run_os("pdflatex", "-interaction=nonstopmode", "pandas.tex")
            raise SystemExit(
                'You should check the file "build/latex/pandas.pdf" for problems.'
            )
        self._run_os("make")
        return ret_code

def run(self):
    range_ = self.arguments[0]
    if range_.endswith("x..HEAD"):
        return [nodes.paragraph(), nodes.bullet_list()]
    try:
        components = build_components(range_)
    except git.GitCommandError as exc:
        return [
            self.state.document.reporter.warning(
                f"Cannot find contributors for range {repr(range_)}: {exc}",
                line=self.lineno,
            )
        ]
    else:
        message = nodes.paragraph()
        message += nodes.Text(components["author_message"])

        listnode = nodes.bullet_list()

        for author in components["authors"]:
            para = nodes.paragraph()
            para += nodes.Text(author)
            listnode += nodes.list_item("", para)

    return [message, listnode]

def _pandas_validate(obj_name, validator_cls=None, **validator_kwargs):
    result = _original_numpydoc_validate(
        obj_name, validator_cls=validator_cls, **validator_kwargs
    )

    docstring = result.get("docstring", "")
    if not docstring:
        return result

    errors = result["errors"]

    # GL04: private classes mentioned in public docstrings
    mentioned = [klass for klass in _PANDAS_PRIVATE_CLASSES if klass in docstring]
    if mentioned:
        errors.append(
            numpydoc.validate.error(
                "GL04", mentioned_private_classes=", ".join(mentioned)
            )
        )

    # PD01: array_like instead of array-like
    if "array_like" in docstring:
        errors.append(numpydoc.validate.error("PD01"))

    # SA05: See Also references with unnecessary pandas. prefix
    doc = NumpyDocString(docstring)
    for ref_group in doc["See Also"]:
        for ref_name, _ in ref_group[0]:
            if ref_name.startswith("pandas."):
                errors.append(
                    numpydoc.validate.error(
                        "SA05",
                        reference_name=ref_name,
                        right_reference=ref_name[len("pandas.") :],
                    )
                )

    # EX04: redundant numpy/pandas imports in examples
    examples_source = "".join(
        line.source for line in doctest.DocTestParser().get_examples(docstring)
    )
    for lib in ("numpy", "pandas"):
        if f"import {lib}" in examples_source:
            errors.append(numpydoc.validate.error("EX04", imported_library=lib))

    return result

def linkcode_resolve(domain, info) -> str | None:
    """
    Determine the URL corresponding to Python object
    """
    if domain != "py":
        return None

    modname = info["module"]
    fullname = info["fullname"]

    submod = sys.modules.get(modname)
    if submod is None:
        return None

    obj = submod
    for part in fullname.split("."):
        try:
            with warnings.catch_warnings():
                # Accessing deprecated objects will generate noisy warnings
                warnings.simplefilter("ignore", FutureWarning)
                obj = getattr(obj, part)
        except AttributeError:
            return None

    if isinstance(obj, type):
        if hasattr(obj, "_module_source"):
            obj.__module__, obj._module_source = obj._module_source, obj.__module__

    try:
        fn = inspect.getsourcefile(inspect.unwrap(obj))
    except TypeError:
        try:  # property
            fn = inspect.getsourcefile(inspect.unwrap(obj.fget))
        except (AttributeError, TypeError):
            fn = None
    if not fn:
        return None

    try:
        source, lineno = inspect.getsourcelines(obj)
    except TypeError:
        try:  # property
            source, lineno = inspect.getsourcelines(obj.fget)
        except (AttributeError, TypeError):
            lineno = None
    except OSError:
        lineno = None

    if lineno:
        linespec = f"#L{lineno}-L{lineno + len(source) - 1}"
    else:
        linespec = ""

    fn = os.path.relpath(fn, start=os.path.dirname(pandas.__file__))

    if isinstance(obj, type) and hasattr(obj, "_module_source"):
        obj.__module__, obj._module_source = obj._module_source, obj.__module__

    if "+" in full_version:
        return f"https://github.com/pandas-dev/pandas/blob/main/pandas/{fn}{linespec}"
    else:
        return (
            f"https://github.com/pandas-dev/pandas/blob/"
            f"v{full_version}/pandas/{fn}{linespec}"

def resolve_name(self, modname, parents, path, base):
    if modname is None:
        if path:
            mod_cls = path.rstrip(".")
        else:
            mod_cls = None
            # if documenting a class-level object without path,
            # there must be a current class, either from a parent
            # auto directive ...
            mod_cls = self.env.temp_data.get("autodoc:class")
            # ... or from a class directive
            if mod_cls is None:
                mod_cls = self.env.temp_data.get("py:class")
            # ... if still None, there's no way to know
            if mod_cls is None:
                return None, []
        # HACK: this is added in comparison to ClassLevelDocumenter
        # mod_cls still exists of class.accessor, so an extra
        # rpartition is needed
        modname, _, accessor = mod_cls.rpartition(".")
        modname, _, cls = modname.rpartition(".")
        parents = [cls, accessor]
        # if the module name is still missing, get it like above
        if not modname:
            modname = self.env.temp_data.get("autodoc:module")
        if not modname:
            if sphinx.__version__ > "1.3":
                modname = self.env.ref_context.get("py:module")
            else:
                modname = self.env.temp_data.get("py:module")
        # ... else, it stays None, which means invalid
    return modname, [*parents, base]

def _replace_pandas_items(self, display_name, sig, summary, real_name):
    # this a hack: ideally we should extract the signature from the
    # .__call__ method instead of hard coding this
    if display_name == "DataFrame.plot":
        sig = "([x, y, kind, ax, ....])"
        summary = "DataFrame plotting accessor and method"
    elif display_name == "Series.plot":
        sig = "([kind, ax, figsize, ....])"
        summary = "Series plotting accessor and method"
    return (display_name, sig, summary, real_name)

def _is_deprecated(real_name):
    try:
        obj, parent, modname = _import_by_name(real_name)
    except ImportError:
        return False
    doc = NumpyDocString(obj.__doc__ or "")
    summary = "".join(doc["Summary"] + doc["Extended Summary"])
    return ".. deprecated::" in summary

def _add_deprecation_prefixes(self, items):
    for item in items:
        display_name, sig, summary, real_name = item
        if self._is_deprecated(real_name):
            summary = f"(DEPRECATED) {summary}"
        yield display_name, sig, summary, real_name

def apply_signature_overrides() -> None:
    for offset_class, parameter_names in _OFFSET_SIGNATURES.items():
        signature = inspect.Signature(
            parameters=[_OFFSET_PARAMETERS[name] for name in parameter_names]
        )

        assert offset_class() == offset_class(
            **{name: param.default for name, param in signature.parameters.items()}
        )

        offset_class.__signature__ = signature

def _public_names() -> frozenset[str]:
    """Return ``pandas.__all__``, read without importing pandas."""
    path = Path(__file__).parent.parent / "pandas" / "__init__.py"
    tree = ast.parse(path.read_text(encoding="utf-8"))
    for node in tree.body:
        if (
            isinstance(node, ast.Assign)
            and any(
                isinstance(target, ast.Name) and target.id == "__all__"
                for target in node.targets
            )
            and isinstance(node.value, ast.List)
        ):
            return frozenset(
                element.value
                for element in node.value.elts
                if isinstance(element, ast.Constant)
            )
    raise AssertionError(f"could not find __all__ in {path}")

def _check_import_from(node: ast.ImportFrom) -> Iterator[str]:
    if node.level != 0 or node.module != "pandas":
        return
    for alias in node.names:
        if alias.name in PUBLIC_NAMES:
            yield (
                f"use 'pd.{alias.name}' rather than importing '{alias.name}' "
                "from the pandas namespace"
            )
        else:
            yield (
                f"import '{alias.name}' from the module which defines it "

def main(content: str, file: str) -> int:
    tree = ast.parse(content)
    ret = 0
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            messages = _check_import(node)
        elif isinstance(node, ast.ImportFrom):
            messages = _check_import_from(node)
        else:
            continue
        for message in messages:
            print(f"{file}:{node.lineno}:{node.col_offset} {message}")
            ret = 1
    return ret

def sort_whatsnew_note(content: str) -> int:
    new_lines = []
    block: list[str] = []
    lines = content.splitlines(keepends=True)
    for line in lines:
        if line.startswith("- ") and pattern.search(line) is not None:
            block.append(line)
        else:
            block = sorted(block)
            new_lines.extend(block)
            new_lines.append(line)
            block = []
    if sorted(new_lines) != sorted(lines):  # pragma: no cover
        # Defensive check - this script should only reorder lines, not modify any
        # content.
        raise AssertionError(
            "Script modified content of file. Something is wrong, please don't "
            "trust it."
        )
    return "".join(new_lines)

def get_warnings_and_exceptions_from_api_path() -> set[str]:
    with open(API_PATH, encoding="utf-8") as f:
        doc_errors = {
            line.split(".")[1].strip() for line in f.readlines() if "errors" in line
        }
        return doc_errors

def visit_ClassDef(self, node) -> None:
    def is_an_exception_subclass(base_id: str) -> bool:
        return base_id == "Exception" or base_id.endswith(("Warning", "Error"))

    exception_classes = []

    # Go through the class's bases and check if they are an Exception or Warning.
    for base in node.bases:
        base_id = getattr(base, "id", None)
        if base_id and is_an_exception_subclass(base_id):
            exception_classes.append(base_id)

    # The class subclassed an Exception or Warning so add it to the list.
    if exception_classes:
        self.found_exceptions.add(node.name)

def _find_names(node: ast.Module) -> Iterator[str]:
    for _node in ast.walk(node):
        if isinstance(_node, ast.Name):
            yield _node.id
        elif isinstance(_node, ast.Attribute):
            yield _node.attr

def _is_fixture(node: ast.expr) -> bool:
    if isinstance(node, ast.Call):
        node = node.func
    return (
        isinstance(node, ast.Attribute)
        and node.attr == "fixture"
        and isinstance(node.value, ast.Name)
        and node.value.id == "pytest"

def is_misnamed_test_class(
    node: ast.expr | ast.stmt, names: Sequence[str], line: str
) -> bool:
    return (
        isinstance(node, ast.ClassDef)
        and not node.name.startswith("Test")
        and names.count(node.name) == 0
        and not any(_is_register_dtype(decorator) for decorator in node.decorator_list)
        and PRAGMA not in line

def doesnt_use_pandas_warnings(file_obj: IO[str]) -> Iterable[tuple[int, str]]:
    """
    Checking that pandas-specific warnings are used for deprecations.

    Parameters
    ----------
    file_obj : IO
        File-like object containing the Python code to validate.

    Yields
    ------
    line_number : int
        Line number of the warning.
    msg : str
        Explanation of the error.
    """
    contents = file_obj.read()
    lines = contents.split("\n")
    tree = ast.parse(contents)
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue

        if isinstance(node.func, ast.Attribute) and isinstance(
            node.func.value, ast.Name
        ):
            # Check for `warnings.warn`.
            if node.func.value.id != "warnings" or node.func.attr != "warn":
                continue
        elif isinstance(node.func, ast.Name):
            # Check for just `warn` when using `from warnings import warn`.
            if node.func.id != "warn":
                continue
        if any(
            "# pdlint: ignore[warning_class]" in lines[k]
            for k in range(node.lineno - 1, node.end_lineno + 1)
        ):
            continue
        values = [arg.id for arg in node.args if isinstance(arg, ast.Name)] + [
            kw.value.id for kw in node.keywords if kw.arg == "category"
        ]
        for value in values:
            matches = re.match(DEPRECATION_WARNINGS_PATTERN, value)
            if matches is not None:
                yield (
                    node.lineno,
                    f"Don't use {matches[0]}, use a pandas-specific warning in "

def _message_regex_source(node: ast.AST) -> str | None:
    """Return the (approximate) regex source for a string-literal node.

    Adjacent string literals are already concatenated by the parser. For an
    f-string each substitution is treated as opaque placeholder text, so a bare
    ``f"{a}|{b}"`` is still detected while the contents of ``{...}`` are not
    interpreted as regex syntax. Returns ``None`` for anything that is not a
    string literal (e.g. a ``"|".join([...])`` call or a plain name).
    """
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    if isinstance(node, ast.JoinedStr):
        parts = []
        for value in node.values:
            if isinstance(value, ast.Constant) and isinstance(value.value, str):
                parts.append(value.value)
            else:
                parts.append("\x00")  # opaque placeholder for a {substitution}
        return "".join(parts)
    return None

def _has_top_level_pipe(regex: str) -> bool:
    """Whether ``regex`` contains a ``|`` at the top level.

    A top-level ``|`` is one that is not backslash-escaped, not inside a
    ``(...)`` group, and not inside a ``[...]`` character class -- i.e. a real
    alternation between separate messages rather than an inline ``(a|b)``.
    """
    depth = 0
    in_character_class = False
    index = 0
    while index < len(regex):
        char = regex[index]
        if char == "\\":
            index += 2
            continue
        if in_character_class:
            if char == "]":
                in_character_class = False
        elif char == "[":
            in_character_class = True
        elif char == "(":
            depth += 1
        elif char == ")":
            depth = max(0, depth - 1)
        elif char == "|" and depth == 0:
            return True
        index += 1
    return False

def conda_package_to_pip(package: str):
    """
    Convert a conda package to its pip equivalent.

    In most cases they are the same, those are the exceptions:
    - Packages that should be excluded (in `EXCLUDE`)
    - Packages that should be renamed (in `CONDA_TO_PIP`)
    - A package requiring a specific version, in conda is defined with a single
      equal (e.g. ``pandas=1.0``) and in pip with two (e.g. ``pandas==1.0``)
    """
    package = re.sub("(?<=[^<>~!])=", "==", package).strip()

    for compare in ("<=", ">=", "=="):
        if compare in package:
            pkg, version = package.split(compare)
            if pkg in EXCLUDE:
                return
            if pkg in REMAP_VERSION:
                return "".join((pkg, compare, REMAP_VERSION[pkg]))
            if pkg in CONDA_TO_PIP:
                return "".join((CONDA_TO_PIP[pkg], compare, version))

    if package in EXCLUDE:
        return

    if package in CONDA_TO_PIP:
        return CONDA_TO_PIP[package]

    return package

def main(source_paths: list[str]) -> int:
    """
    The main method to print all headings with incorrect capitalization.

    Parameters
    ----------
    source_paths : str
        List of directories to validate, provided through command line arguments.

    Returns
    -------
    int
        Number of incorrect headings found overall.
    """

    number_of_errors: int = 0

    for filename in source_paths:
        for title, line_number in find_titles(filename):
            if title != correct_title_capitalization(title):
                print(
                    f"""{filename}:{line_number}:{err_msg} "{title}" to "{
                        correct_title_capitalization(title)
                    }" """
                )
                number_of_errors += 1

    return number_of_errors

def get_defined_errors(content: str) -> set[str]:
    errors = set()
    for node in ast.walk(ast.parse(content)):
        if isinstance(node, ast.ClassDef):
            errors.add(node.name)
        elif isinstance(node, ast.ImportFrom) and node.module != "__future__":
            for alias in node.names:
                errors.add(alias.name)
    return errors

def declared_packages(pixi: dict, environments: Iterable[str]) -> set[str]:
    """
    Every package installed in at least one of ``environments``.
    """
    packages = set(pixi.get("dependencies", {}))
    for environment in environments:
        specification = pixi["environments"][environment]
        if isinstance(specification, dict):
            features = specification["features"]
        else:
            features = specification
        for feature in features:
            block = pixi["feature"].get(feature, {})
            packages.update(block.get("dependencies", {}))
            packages.update(block.get("pypi-dependencies", {}))
    return packages

def gated_modules() -> dict[str, set[str]]:
    """
    Map each gated top level module to the files that gate on it.
    """
    modules: dict[str, set[str]] = {}
    for path in sorted(PANDAS_PATH.rglob("*.py")):
        if path == DEFINITION_SITE:
            continue
        for match in GATE_PATTERN.finditer(path.read_text(encoding="utf-8")):
            module = (match.group(1) or match.group(2)).split(".")[0]
            modules.setdefault(module, set()).add(str(path.relative_to(BASE_PATH)))
    return modules

def validate_test_dependencies() -> int:
    with open(PIXI_PATH, "rb") as file_handle:
        pixi = tomllib.load(file_handle)
    declared = declared_packages(pixi, environments_running_tests())

    ret = 0
    for module, paths in sorted(gated_modules().items()):
        if module in ALLOWED_UNDECLARED or module in sys.stdlib_module_names:
            continue
        package = IMPORT_TO_CONDA.get(module, module)
        if package in declared:
            continue
        print(MESSAGE.format(module=module, package=package))
        for path in sorted(paths):
            print(f"    {path}")
        ret = 1
    return ret

def replace_inconsistent_pandas_namespace(visitor: Visitor, content: str) -> str:
    from tokenize_rt import (
        reversed_enumerate,
        src_to_tokens,
        tokens_to_src,
    )

    tokens = src_to_tokens(content)
    for n, i in reversed_enumerate(tokens):
        offset_with_namespace = OffsetWithNamespace(i.offset[0], i.offset[1], i.src)
        if (
            offset_with_namespace in visitor.pandas_namespace
            and visitor.pandas_namespace[offset_with_namespace]
            in visitor.imported_from_pandas
        ):
            # Replace `pd`
            tokens[n] = i._replace(src="")
            # Replace `.`
            tokens[n + 1] = tokens[n + 1]._replace(src="")

    new_src: str = tokens_to_src(tokens)
    return new_src

def visit_Attribute(self, node: ast.Attribute) -> None:
    if isinstance(node.value, ast.Name) and node.value.id in {"pandas", "pd"}:
        offset_with_namespace = OffsetWithNamespace(
            node.lineno, node.col_offset, node.value.id
        )
        self.pandas_namespace[offset_with_namespace] = node.attr
    self.generic_visit(node)

def get_operator_from(dependency: str) -> str | None:
    if "!=" in dependency:
        operator = "!="
    elif "<=" in dependency:
        operator = "<="
    elif ">=" in dependency:
        operator = ">="
    elif "=" in dependency:
        operator = "="
    elif ">" in dependency:
        operator = ">"
    elif "<" in dependency:
        operator = "<"
    else:
        operator = None
    return operator

def get_yaml_map_from(
    yaml_dic: list[str | dict[str, list[str]]],
) -> dict[str, list[str] | None]:
    yaml_map: dict[str, list[str] | None] = {}
    for dependency in yaml_dic:
        if isinstance(dependency, dict) or dependency in yaml_map:
            continue
        search_text = str(dependency)
        operator = get_operator_from(search_text)
        if "," in dependency:
            yaml_dependency, yaml_version1 = search_text.split(",")
            operator = get_operator_from(yaml_dependency)
            assert operator is not None
            yaml_package, yaml_version2 = yaml_dependency.split(operator)
            yaml_version2 = operator + yaml_version2
            yaml_map[yaml_package] = [yaml_version1, yaml_version2]
        elif operator is not None:
            yaml_package, yaml_version = search_text.split(operator)
            yaml_version = operator + yaml_version
            yaml_map[yaml_package] = [yaml_version]
        else:
            yaml_package, yaml_version = search_text.strip(), None
            yaml_map[yaml_package] = yaml_version
    return yaml_map

def clean_version_list(
    yaml_versions: list[str], toml_version: version.Version
) -> list[str]:
    for i in range(len(yaml_versions)):
        yaml_version = yaml_versions[i].strip()
        operator = get_operator_from(yaml_version)
        assert operator is not None
        if operator == "!=":
            continue
        if "<=" in operator or ">=" in operator:
            yaml_version = yaml_version[2:]
        else:
            yaml_version = yaml_version[1:]
        yaml_version = version.parse(yaml_version)
        if yaml_version < toml_version:
            yaml_versions[i] = "-" + str(yaml_version)
        elif yaml_version >= toml_version:
            if ">" in operator:
                yaml_versions[i] = "-" + str(yaml_version)
    return yaml_versions

def pin_min_versions_to_yaml_file(
    yaml_map: dict[str, list[str] | None], toml_map: dict[str, str], yaml_file_data: str
) -> str:
    data = yaml_file_data
    for yaml_package, yaml_versions in yaml_map.items():
        old_dep = yaml_package
        if yaml_versions is not None:
            old_dep = old_dep + ", ".join(yaml_versions)
        if CONDA_TO_PIP.get(yaml_package, yaml_package) in toml_map:
            min_dep = toml_map[CONDA_TO_PIP.get(yaml_package, yaml_package)]
        elif yaml_package in toml_map:
            min_dep = toml_map[yaml_package]
        else:
            continue
        if yaml_versions is None:
            new_dep = old_dep + ">=" + min_dep
            data = data.replace(old_dep, new_dep, 1)
            continue
        toml_version = version.parse(min_dep)
        yaml_versions_list = clean_version_list(yaml_versions, toml_version)
        cleaned_yaml_versions = [x for x in yaml_versions_list if "-" not in x]
        new_dep = yaml_package
        for clean_yaml_version in cleaned_yaml_versions:
            new_dep += clean_yaml_version + ", "
        operator = get_operator_from(new_dep)
        if operator != "=":
            new_dep += ">=" + min_dep
        else:
            new_dep = new_dep[:-2]
        data = data.replace(old_dep, new_dep)
    return data

def get_versions_from_code() -> dict[str, str]:
    """Min versions for checking within pandas code."""
    install_map = _optional.INSTALL_MAPPING
    inverse_install_map = {v: k for k, v in install_map.items()}
    versions = _optional.VERSIONS
    for item in EXCLUDE_DEPS:
        item = inverse_install_map.get(item, item)
        versions.pop(item, None)
    return {install_map.get(k, k).casefold(): v for k, v in versions.items()}

def _get_required_dependencies_from_pixi_content(
    content: list[str], pixi_toml: dict[str, Any]
) -> dict[str, str]:
    # pixi.toml keeps build and required deps in the same TOML table.
    required_deps = {}
    in_dependencies = False
    in_required_dependencies = False
    for line in content:
        line = line.strip()
        if not line:
            continue
        if line.startswith("["):
            in_dependencies = line == "[dependencies]"
            in_required_dependencies = False
            continue
        if not in_dependencies:
            continue
        if line.casefold() == "# required dependencies":
            in_required_dependencies = True
            continue
        if line.startswith("#"):
            in_required_dependencies = False
            continue
        if not in_required_dependencies:
            continue
        package = line.split("=", maxsplit=1)[0].strip()
        version = _get_version_from_pixi_spec(pixi_toml["dependencies"][package])
        if version is not None and package not in EXCLUDE_DEPS:
            required_deps[package.casefold()] = version
    return required_deps

def _get_dependencies_from_pixi_table(
    dependencies: dict[str, str | dict[str, Any]],
    install_map: dict[str, str],
    packages: set[str] | None = None,
) -> dict[str, str]:
    versions = {}
    for package, spec in dependencies.items():
        package = install_map.get(package, package).casefold()
        if package in EXCLUDE_DEPS or (
            packages is not None and package not in packages
        ):
            continue
        version = _get_version_from_pixi_spec(spec)
        if version is not None:
            versions[package] = version
    return versions

def _get_version_from_pixi_spec(spec: str | dict[str, Any]) -> str | None:
    if isinstance(spec, dict):
        spec = spec.get("version", "")
    if spec in {"", "*"}:
        return None
    for operator in ("==", ">=", "="):
        if spec.startswith(operator):
            version = spec.removeprefix(operator).split(",", maxsplit=1)[0]
            if "*" not in version:
                return version
    return None

def get_versions_from_toml() -> dict[str, str]:
    """Min versions in pyproject.toml for pip install pandas[extra]."""
    install_map = _optional.INSTALL_MAPPING
    optional_dependencies = {}
    with open(PYPROJECT_PATH, "rb") as pyproject_f:
        pyproject_toml = tomllib.load(pyproject_f)
        opt_deps = pyproject_toml["project"]["optional-dependencies"]
        dependencies = set(opt_deps["all"])

        # remove pytest plugin dependencies
        pytest_plugins = {dep for dep in opt_deps["test"] if dep.startswith("pytest-")}
        dependencies = dependencies.difference(pytest_plugins)

    for dependency in dependencies:
        package, version = dependency.strip().split(">=")
        optional_dependencies[install_map.get(package, package).casefold()] = (
            _strip_extra_specifiers(version)
        )

    for item in EXCLUDE_DEPS:
        optional_dependencies.pop(item, None)
    return optional_dependencies

def _current_stances(
    reviews: list[Review],
) -> dict[str | None, tuple[datetime, str | None]]:
    """Each maintainer reviewer's current stance, keyed by reviewer login.

    Only an ``OWNER``/``MEMBER`` review counts; a review from any other
    account is ignored. A reviewer's stance is their newest
    ``APPROVED``/``CHANGES_REQUESTED``/``DISMISSED`` review — later
    ``COMMENTED`` reviews leave the previous verdict standing, while a
    dismissal (which rewrites the review's state to ``DISMISSED`` in place)
    withdraws it.
    """
    stances: dict[str | None, tuple[datetime, str | None]] = {}
    for r in reviews:
        submitted = r["submitted_at"]
        if (
            r.get("state") in STANCE_REVIEW_STATES
            and (r.get("author_association") or "") in REVIEW_BLOCKING_ASSOCIATIONS
            and submitted is not None
        ):
            current = stances.get(r.get("author"))
            if current is None or submitted > current[0]:
                stances[r.get("author")] = (submitted, r.get("state"))
    return stances

def awaiting_contributor(
    changes_requested_at: datetime | None, rereview_requested_at: datetime | None
) -> bool:
    """True when changes were requested and no re-review has been asked for since.

    A mere push doesn't move the ball back — WIP commits aren't a claim of
    readiness. The contributor has to explicitly re-request review (newer than
    the changes-requested review) to put the PR back in the maintainers' court.
    """
    if changes_requested_at is None:
        return False
    if rereview_requested_at is None:
        return True
    return changes_requested_at > rereview_requested_at

def gate_decision(
    author: str,
    author_association: str | None,
    author_is_bot: bool,
    linked_issues: list[LinkedIssue],
) -> GateDecision:
    """Decide what the assignment gate should do for a pull request.

    Returns a dict whose ``outcome`` is one of ``not_in_scope`` (gate doesn't
    apply), ``valid_assignment`` (author is an assignee — clear the flag), or
    ``invalid_assignment`` (author isn't validly assigned — flag it). An
    ``invalid_assignment`` also carries a ``variant`` (``unassigned`` /
    ``assigned_other``), the ``issue`` number to reference, and (for
    ``assigned_other``) the ``assignee`` holding it.
    """
    if is_exempt(author_association, author_is_bot):
        return {"outcome": "not_in_scope", "reason": "exempt"}
    if not linked_issues:
        return {"outcome": "not_in_scope", "reason": "no_linked_issue"}
    if any(author in issue["assignees"] for issue in linked_issues):
        return {"outcome": "valid_assignment"}
    unassigned = [issue for issue in linked_issues if not issue["assignees"]]
    if unassigned:
        return {
            "outcome": "invalid_assignment",
            "variant": "unassigned",
            "issue": unassigned[0]["number"],
        }
    issue = linked_issues[0]
    return {
        "outcome": "invalid_assignment",
        "variant": "assigned_other",
        "issue": issue["number"],
        "assignee": issue["assignees"][0],

def reconcile_all(client: SupportsLabelReconcile) -> None:
    label = core.AWAITING_REVIEW_LABEL
    for pr in client.iter_open_pull_requests_review_state():
        if core.is_exempt(pr["author_association"], False):
            continue
        changes_requested_at = core.outstanding_changes_requested_at(pr["reviews"])
        contributors = {pr["author"]} - {None}
        rereview_requested_at = core.latest_rereview_request_at(
            pr["review_requests"], contributors
        )
        fully_approved = core.all_reviewers_approved(
            pr["reviews"], pr["has_pending_review_requests"]
        )
        want = core.GATE_LABEL not in pr[
            "labels"
        ] and core.should_label_awaiting_review(
            True,
            pr["is_draft"],
            changes_requested_at,
            rereview_requested_at,
            fully_approved,
        )
        has = label in pr["labels"]
        if want and not has:
            client.add_labels(pr["number"], [label])
        elif has and not want:
            client.remove_label(pr["number"], label)

def free_linked_issues(client: GitHubClient, number: int, author: str | None) -> None:
    """Unassign ``author`` from every linked issue they hold + comment on each."""
    if author is None:
        return
    for issue in client.linked_issues_for_pr(number):
        if author in issue["assignees"]:
            client.remove_assignees(issue["number"], [author])
            client.comment(issue["number"], messages.issue_freed_stale_pr())

def run_sweep(client: GitHubClient) -> None:
    now = datetime.now(UTC)  # noqa: TID251
    window = timedelta(days=core.STALE_ASSIGNEE_DAYS)
    for number in client.list_open_assigned_issue_numbers():
        activity = client.issue_activity(number)
        assignees = activity["assignees"]
        if not assignees:
            continue
        assignee_set = set(assignees)
        has_open_pr = any(a in assignee_set for a in activity["open_pr_authors"])
        candidates = [
            activity["assigned_at"],
            core.latest_assignee_comment_at(activity["comments"], assignees),
            core.ROLLOUT_CUTOFF,
        ]
        last_activity_at = max(t for t in candidates if t is not None)
        if core.issue_is_active(
            now, has_open_pr, last_activity_at, core.STALE_ASSIGNEE_DAYS
        ):
            continue
        # Unassigning is destructive, so an absence of protecting signals in
        # the bounded windows has to be re-checked exactly before acting.
        if activity["comments_truncated"] and (
            client.latest_comment_at_since(number, assignee_set, now - window)
            is not None
        ):
            continue
        if activity["crossrefs_truncated"] and any(
            a in assignee_set for a in client.open_pr_authors_exact(number)
        ):
            continue
        to_unassign = [a for a in assignees if not client.is_exempt_collaborator(a)]
        if not to_unassign:
            continue
        client.remove_assignees(number, to_unassign)
        client.comment(number, messages.issue_unassigned_inactive(to_unassign))

def run_pr_closed(client: GitHubClient, event: dict[str, Any]) -> None:
    pr = event["pull_request"]
    if pr.get("merged"):
        return
    if core.is_exempt(pr.get("author_association"), pr["user"].get("type") == "Bot"):
        return
    labels = [label["name"] for label in pr.get("labels", [])]
    if core.STALE_LABEL not in labels:
        return
    free_linked_issues(client, pr["number"], pr["user"]["login"])

def _graphql(self, query: str, **variables: str | int | None) -> dict[str, Any]:
    args = [
        "api",
        "graphql",
        "-f",
        f"query={query}",
        "-f",
        f"owner={self.owner}",
        "-f",
        f"name={self.name}",
    ]
    for key, value in variables.items():
        if value is None:
            continue
        if isinstance(value, bool):
            args += ["-F", f"{key}={'true' if value else 'false'}"]
        elif isinstance(value, int):
            args += ["-F", f"{key}={value}"]
        else:
            args += ["-f", f"{key}={value}"]
    return json.loads(self._gh(args))["data"]["repository"]

def _linked_issues(self, nodes: list[dict[str, Any]]) -> list[LinkedIssue]:
    return [
        {
            "number": node["number"],
            "assignees": [a["login"] for a in node["assignees"]["nodes"]],
        }
        for node in nodes
        # Ignore linked issues to other repositories.
        if node["repository"]["nameWithOwner"].lower() == self.repo.lower()

def issue_activity(self, number: int) -> IssueActivity:
    issue = self._graphql(_ISSUE_ACTIVITY_QUERY, number=number)["issue"]
    assignees = [a["login"] for a in issue["assignees"]["nodes"]]
    assigned_times = [
        assigned
        for event in issue["assignedEvents"]["nodes"]
        if (assigned := parse_dt(event["createdAt"])) is not None
    ]
    comments: list[Comment] = [
        {
            "author": (c["author"] or {}).get("login"),
            "created_at": parse_dt(c["createdAt"]),
        }
        for c in issue["comments"]["nodes"]
    ]
    crossrefs = issue["crossrefs"]
    open_pr_authors: list[str] = []
    for node in crossrefs["nodes"]:
        source = node.get("source") or {}
        if source.get("state") == "OPEN":
            author = (source.get("author") or {}).get("login")
            if author:
                open_pr_authors.append(author)
    return {
        "assignees": assignees,
        "assigned_at": max(assigned_times) if assigned_times else None,
        "comments": comments,
        "comments_truncated": issue["comments"]["totalCount"] > len(comments),
        "open_pr_authors": open_pr_authors,
        "crossrefs_truncated": crossrefs["totalCount"] > len(crossrefs["nodes"]),

def open_pr_authors_exact(self, number: int) -> list[str]:
    """Exact authors of open PRs cross-referencing an issue.

    Used when a batched read sets ``crossrefs_truncated``.
    """
    out = self._gh(
        [
            "api",
            "--paginate",
            "--slurp",
            f"repos/{self.repo}/issues/{number}/timeline?per_page=100",
        ]
    )
    authors = []
    for page in json.loads(out):
        for event in page:
            if event.get("event") != "cross-referenced":
                continue
            source = (event.get("source") or {}).get("issue") or {}
            if "pull_request" in source and source.get("state") == "open":
                login = (source.get("user") or {}).get("login")
                if login:
                    authors.append(login)
    return authors

def is_exempt_collaborator(self, username: str) -> bool:
    """Whether ``username`` has triage-or-higher access to the repository.

    Used where no GitHub provided author association is available (issue
    assignees). Reads ``role_name``; the legacy ``permission`` field
    reports ``read`` for everyone on a public repository.
    """
    try:
        out = self._gh(
            ["api", f"repos/{self.repo}/collaborators/{quote(username)}/permission"]
        )
    except subprocess.CalledProcessError as err:
        if "404" in (err.stderr or ""):
            return False
        raise
    return json.loads(out).get("role_name") in _EXEMPT_ROLES

def remove_label(self, number: int, label: str) -> None:
    path = f"repos/{self.repo}/issues/{number}/labels/{quote(label)}"
    try:
        self._gh(["api", "--method", "DELETE", path])
    except subprocess.CalledProcessError as err:
        if "404" not in (err.stderr or ""):
            raise

def get_callable(obj_as_str: str) -> object:
    """
    Get a Python object from its string representation.

    For example, for ``sys.stdout.write`` would import the module ``sys``
    and return the ``write`` function.
    """
    components = obj_as_str.split(".")
    attrs = []
    while components:
        try:
            obj = importlib.import_module(".".join(components))
        except ImportError:
            attrs.insert(0, components.pop())
        else:
            break

    if not obj:
        raise ImportError(f'Could not import "{obj_as_str}"')

    for attr in attrs:
        obj = getattr(obj, attr)

    return obj

def get_source_files(source_path: pathlib.Path) -> typing.Generator[str, None, None]:
    """
    Generate the list of files present in the source directory.
    """
    for path in source_path.rglob("*"):
        if path.is_file():
            yield path.relative_to(source_path)

def pytest_configure(config):
    if config.getoption("--reactor") in {"asyncio", "none"}:
        # Needed on Windows to switch from proactor to selector, which supports
        # add_reader/add_writer (required by the Twisted asyncio reactor, and by
        # tests that register their own readers) and is what Twisted expects.
        set_asyncio_event_loop_policy()
    if config.getoption("--reactor") == "none":
        install_reactor_import_hook()

def pytest_collection_modifyitems(items):
    items[:] = _interleave_evenly(items, _is_subprocess_heavy)
    for item in items:
        if item.get_closest_marker("requires_internet"):
            # Requests to real websites fail every now and then in CI for
            # reasons unrelated to the code under test.
            item.add_marker(pytest.mark.flaky(reruns=2, reruns_delay=5))

def pytest_runtest_setup(item):
    # Skip tests based on reactor markers
    reactor = item.config.getoption("--reactor")

    if item.get_closest_marker("requires_reactor") and reactor == "none":
        pytest.skip('This test is only run when the --reactor value is not "none"')

    if item.get_closest_marker("only_asyncio") and reactor not in {"asyncio", "none"}:
        pytest.skip(
            'This test is only run when the --reactor value is "asyncio" (default) or "none"'
        )

    if item.get_closest_marker("only_not_asyncio") and reactor in {"asyncio", "none"}:
        pytest.skip(
            'This test is only run when the --reactor value is not "asyncio" (default) or "none"'
        )

    # Skip tests requiring optional dependencies
    optional_deps = [
        "uvloop",
        "botocore",
        "boto3",
    ]

    for module in optional_deps:
        if item.get_closest_marker(f"requires_{module}") and find_spec(module) is None:
            pytest.skip(f"{module} is not installed")

    if item.get_closest_marker("requires_mitmproxy") and mitmdump_cmd() is None:
        pytest.skip("mitmdump is not available")

def fetch(
    self,
    request_or_url: Request | str,
    spider: Spider | None = None,
    redirect: bool = True,
    **kwargs: Any,
) -> None:
    if isinstance(request_or_url, Request):
        request = request_or_url
        if (
            not (request.callback is None or request.callback is NO_CALLBACK)
            or request.errback
        ):
            warnings.warn(
                "Callbacks and errbacks of Request objects passed to fetch() are ignored.",
                stacklevel=2,
            )
    else:
        url = any_to_uri(request_or_url)
        request = Request(url, callback=NO_CALLBACK, dont_filter=True, **kwargs)
        if not redirect:
            request.meta["dont_redirect"] = True
    response: Response | None = None
    if self._use_reactor:
        from twisted.internet import reactor

        with contextlib.suppress(IgnoreRequest):
            response = threads.blockingCallFromThread(
                reactor,
                deferred_f_from_coro_f(self._schedule),  # type: ignore[arg-type]
                request,
                spider,
            )
    else:
        assert self._loop
        with contextlib.suppress(IgnoreRequest):
            future = asyncio.run_coroutine_threadsafe(
                self._schedule(request, spider), self._loop
            )
            response = future.result()
    self.populate_vars(response, request, self.spider)

def get_help(self) -> str:
    b = []
    b.append("Available Scrapy objects:")
    b.append(
        "  scrapy     scrapy module (contains scrapy.Request, scrapy.Selector, etc)"
    )
    for k, v in sorted(self.vars.items()):
        if self._is_relevant(v):
            b.append(f"  {k:<10} {v}")
    b.append("Useful shortcuts:")
    if self.fetch_available:
        b.append(
            "  fetch(url[, redirect=True]) "
            "Fetch URL and update local objects (by default, redirects are followed)"
        )
        b.append(
            "  fetch(req)                  "
            "Fetch a scrapy.Request and update local objects "
        )
    b.append("  shelp()           Shell help (print this help)")
    b.append("  view(response)    View response in a browser")

    return "\n".join(f"[s] {line}" for line in b) + "\n"

def request_seen(self, request: Request) -> bool:
    fp = self._fingerprint(request)
    if fp in self._fingerprints:
        return True
    self._fingerprints.add(fp)
    if self.file:
        self.file.write(len(fp).to_bytes(_SIZE_BYTES, "big") + fp)
    return False

def log(self, request: Request, spider: Spider) -> None:
    if self.debug:
        msg = "Filtered duplicate request: %(request)s (referer: %(referer)s)"
        args = {"request": request, "referer": referer_str(request)}
        self.logger.debug(msg, args, extra={"spider": spider})
    elif self.logdupes:
        msg = (
            "Filtered duplicate request: %(request)s"
            " - no more duplicates will be shown"
            " (see DUPEFILTER_DEBUG to show all duplicates)"
        )
        self.logger.debug(msg, {"request": request}, extra={"spider": spider})
        self.logdupes = False

    spider.crawler.stats.inc_value("dupefilter/filtered")

def _load_all_spiders(self) -> None:
    for name in self.spider_modules:
        try:
            for module in walk_modules_iter(name):
                self._load_spiders(module)
        except (ImportError, SyntaxError):
            if self.warn_only:
                warnings.warn(
                    f"\n{traceback.format_exc()}Could not load spiders "
                    f"from module '{name}'. "
                    "See above traceback for details.",
                    stacklevel=2,
                    category=RuntimeWarning,
                )
            else:
                raise
    self._check_name_duplicates()

def load_settings(self, settings: Settings) -> None:
    """Load add-ons and configurations from a settings object and apply them.

    This will load the add-on for every add-on path in the
    ``ADDONS`` setting and execute their ``update_settings`` methods.

    :param settings: The :class:`~scrapy.settings.Settings` object from \
        which to read the add-on configuration
    :type settings: :class:`~scrapy.settings.Settings`
    """
    for clspath in build_component_list(settings["ADDONS"]):
        try:
            addoncls = load_object(clspath)
            addon = build_from_crawler(addoncls, self.crawler)
            if hasattr(addon, "update_settings"):
                addon.update_settings(settings)
            self.addons.append(addon)
        except NotConfigured as e:
            if e.args:
                logger.warning(
                    "Disabled %(clspath)s: %(eargs)s",
                    {"clspath": clspath, "eargs": e.args[0]},
                    extra={"crawler": self.crawler},
                )
    logger.info(
        "Enabled addons:\n%(addons)s",
        {
            "addons": self.addons,
        },
        extra={"crawler": self.crawler},

def get_serialized_fields(
    self, item: Any, default_value: Any = None, include_empty: bool | None = None
) -> Iterable[tuple[str, Any]]:
    """Return the fields of *item* to export, as an iterable of
    ``(name, serialized_value)`` tuples, taking :attr:`fields_to_export`
    into account and applying :meth:`serialize_field` to every value.

    Fields missing from *item* are exported with *default_value*.

    *include_empty* overrides :attr:`export_empty_fields`.
    """
    item = ItemAdapter(item)

    if include_empty is None:
        include_empty = self.export_empty_fields

    if self.fields_to_export is None:
        field_iter = (
            item.field_names()
            if include_empty
            else self._get_populated_field_names(item)
        )
    elif isinstance(self.fields_to_export, Mapping):
        if include_empty:
            field_iter = self.fields_to_export.items()
        else:
            field_iter = (
                (x, y) for x, y in self.fields_to_export.items() if x in item
            )
    elif include_empty:
        field_iter = self.fields_to_export
    else:
        field_iter = (x for x in self.fields_to_export if x in item)

    for field_name in field_iter:
        if isinstance(field_name, str):
            item_field, output_field = field_name, field_name
        else:
            item_field, output_field = field_name
        if item_field in item:
            field_meta = item.get_field_meta(item_field)
            value = self.serialize_field(field_meta, output_field, item[item_field])
        else:
            value = default_value

        yield output_field, value

def _export_xml_field(self, name: str, serialized_value: Any, depth: int) -> None:
    self._beautify_indent(depth=depth)
    self.xg.startElement(name, AttributesImpl({}))
    if hasattr(serialized_value, "items"):
        self._beautify_newline()
        for subname, value in serialized_value.items():
            self._export_xml_field(subname, value, depth=depth + 1)
        self._beautify_indent(depth=depth)
    elif is_listlike(serialized_value):
        self._beautify_newline()
        for value in serialized_value:
            self._export_xml_field("value", value, depth=depth + 1)
        self._beautify_indent(depth=depth)
    elif isinstance(serialized_value, str):
        self.xg.characters(serialized_value)
    else:
        self.xg.characters(str(serialized_value))
    self.xg.endElement(name)
    self._beautify_newline()

def _join_if_needed(self, value: Any) -> Any:
    if isinstance(value, (list, tuple)):
        try:
            return self._join_multivalued.join(value)
        except TypeError:  # list in value may not contain strings
            pass
    return value

def _build_row(self, values: Iterable[Any]) -> Iterable[Any]:
    for s in values:
        try:
            yield to_unicode(s, self.encoding)
        except TypeError:
            yield s

def _write_headers_and_set_fields_to_export(self, item: Any) -> None:
    if self.include_headers_line:
        if not self.fields_to_export:
            # use declared field names, or keys if the item is a dict
            self.fields_to_export = ItemAdapter(item).field_names()
            self._autodetected_fields = True
        fields: Iterable[str]
        if isinstance(self.fields_to_export, Mapping):
            fields = self.fields_to_export.values()
        else:
            assert self.fields_to_export
            fields = self.fields_to_export
        row = list(self._build_row(fields))
        self.csv_writer.writerow(row)

def _serialize_value(self, value: Any) -> Any:
    if isinstance(value, Item):
        return self.export_item(value)
    if isinstance(value, (str, bytes)):
        return to_unicode(value, encoding=self.encoding)
    if is_item(value):
        return dict(self._serialize_item(value))
    if is_listlike(value):
        return [self._serialize_value(v) for v in value]
    return value

def decode_robotstxt(
    robotstxt_body: bytes, spider: Spider | None, to_native_str_type: bool = False
) -> str:
    try:
        if to_native_str_type:
            body_decoded = to_unicode(robotstxt_body)
        else:
            body_decoded = robotstxt_body.decode("utf-8-sig", errors="ignore")
    except UnicodeDecodeError:
        # If we found garbage or robots.txt in an encoding other than UTF-8, disregard it.
        # Switch to 'allow all' state.
        logger.warning(
            "Failure while parsing robots.txt. File either contains garbage or "
            "is in an encoding other than UTF-8, treating it as an empty file.",
            exc_info=sys.exc_info(),
            extra={"spider": spider},
        )
        body_decoded = ""
    return body_decoded

def _spider(self) -> Spider:
    if self.crawler is not None:
        if self.crawler.spider is None:
            raise ValueError(
                f"{type(self).__name__} needs to access self.crawler.spider but it is None."
            )
        return self.crawler.spider
    if self._compat_spider is not None:
        return self._compat_spider
    raise ValueError(f"{type(self).__name__} has no known Spider instance.")

def _set_compat_spider(self, spider: Spider | None) -> None:
    if spider is None or self.crawler is not None:
        return
    # printing a deprecation warning is the caller's responsibility
    if self._compat_spider is None:
        self._compat_spider = spider
    elif self._compat_spider is not spider:
        raise RuntimeError(
            f"Different instances of Spider were passed to {type(self).__name__}:"
            f" {self._compat_spider!r} and {spider!r}"

def from_crawler(cls, crawler: Crawler) -> Self:
    mwlist = cls._get_mwlist_from_settings(crawler.settings)
    middlewares = []
    enabled = []
    for clspath in mwlist:
        try:
            mwcls = load_object(clspath)
            mw = build_from_crawler(mwcls, crawler)
            middlewares.append(mw)
            enabled.append(clspath)
        except NotConfigured as e:
            if e.args:
                logger.warning(
                    "Disabled %(clspath)s: %(eargs)s",
                    {"clspath": clspath, "eargs": e.args[0]},
                    extra={"crawler": crawler},
                )

    logger.info(
        "Enabled %(componentname)ss:\n%(enabledlist)s",
        {
            "componentname": cls.component_name,
            "enabledlist": pprint.pformat(enabled),
        },
        extra={"crawler": crawler},
    )
    return cls(*middlewares, crawler=crawler)

async def _process_chain(
    self,
    methodname: str,
    obj: _T,
    *args: Any,
    add_spider: bool = False,
    always_add_spider: bool = False,
    warn_deferred: bool = False,
) -> _T:
    methods = cast(
        "Iterable[Callable[Concatenate[_T, _P], _T]]", self.methods[methodname]
    )
    for method in methods:
        warn = global_object_name(method) if warn_deferred else None
        if always_add_spider or (
            add_spider and method in self._mw_methods_requiring_spider
        ):
            obj = await ensure_awaitable(
                method(obj, *(*args, self._spider)), _warn=warn
            )
        else:
            obj = await ensure_awaitable(method(obj, *args), _warn=warn)
    return obj

def __new__(
    mcs, class_name: str, bases: tuple[type, ...], attrs: dict[str, Any]
) -> ItemMeta:
    classcell = attrs.pop("__classcell__", None)
    new_bases = tuple(base._class for base in bases if hasattr(base, "_class"))
    _class = super().__new__(mcs, "x_" + class_name, new_bases, attrs)

    fields = getattr(_class, "fields", {})
    for n in _ordered_field_names(_class):
        fields[n] = getattr(_class, n)
    new_attrs = {n: v for n, v in attrs.items() if not isinstance(v, Field)}

    new_attrs["fields"] = fields
    new_attrs["_class"] = _class
    if classcell is not None:
        new_attrs["__classcell__"] = classcell
    return super().__new__(mcs, class_name, bases, new_attrs)

def __init__(self, *args: Any, **kwargs: Any):
    self._values: dict[str, Any] = {}
    if args or kwargs:  # avoid creating dict for most common case
        for k, v in dict(*args, **kwargs).items():
            self[k] = v

def getHostByName(self, name: str, timeout: Sequence[int] = ()) -> Deferred[str]:
    if name in dnscache:
        return defer.succeed(dnscache[name])
    # in Twisted<=16.6, getHostByName() is always called with
    # a default timeout of 60s (actually passed as (1, 3, 11, 45) tuple),
    # so the input argument above is simply overridden
    # to enforce Scrapy's DNS_TIMEOUT setting's value
    # The timeout arg is typed as Sequence[int] but supports floats.
    timeout = (self.timeout,)  # type: ignore[assignment]
    d = super().getHostByName(name, timeout)
    if dnscache.limit:
        d.addCallback(self._cache_result, name)
    return d

def resolveHostName(
    self,
    resolutionReceiver: IResolutionReceiver,
    hostName: str,
    portNumber: int = 0,
    addressTypes: Sequence[type[IAddress]] | None = None,
    transportSemantics: str = "TCP",
) -> IHostResolution:
    try:
        addresses = dnscache[hostName]
    except KeyError:
        return self.original_resolver.resolveHostName(
            _CachingResolutionReceiver(resolutionReceiver, hostName),
            hostName,
            portNumber,
            addressTypes,
            transportSemantics,
        )
    resolutionReceiver.resolutionBegan(HostResolution(hostName))
    for address in addresses:
        resolutionReceiver.addressResolved(_address_with_port(address, portNumber))
    resolutionReceiver.resolutionComplete()
    return resolutionReceiver

def __get__(
    self, instance: Crawler | None, owner: type[Crawler]
) -> _LateAttribute[_T] | _T:
    if instance is None:
        return self
    value: _T | None = getattr(instance, self._private_name)
    if value is None:
        raise RuntimeError(
            f"Crawler.{self._name} is not set yet. It is set when the "
            "crawl starts, so it can only be used from then on, e.g. "
            "from the spider_opened signal handler onwards."
        )
    return value

def _apply_settings(self) -> None:
    if self.settings.frozen:
        return

    self.addons.load_settings(self.settings)
    self._apply_deprecated_spider_attr("download_delay", "DOWNLOAD_DELAY")
    self._apply_deprecated_spider_attr(
        "max_concurrent_requests", "CONCURRENT_REQUESTS_PER_DOMAIN"
    )
    self.stats = load_object(self.settings["STATS_CLASS"])(self)

    lf_cls: type[LogFormatter] = load_object(self.settings["LOG_FORMATTER"])
    self.logformatter = build_from_crawler(lf_cls, self)

    self.request_fingerprinter = build_from_crawler(
        load_object(self.settings["REQUEST_FINGERPRINTER_CLASS"]),
        self,
    )

    use_reactor = self.settings.getbool("TWISTED_REACTOR_ENABLED")
    if use_reactor:
        # We either install a reactor or expect one to be installed.
        reactor_class: str = self.settings["TWISTED_REACTOR"]
        event_loop: str = self.settings["ASYNCIO_EVENT_LOOP"]
        if self._init_reactor:
            # We need to install a reactor.
            # This needs to be done after the spider settings are merged,
            # but before something imports twisted.internet.reactor.
            if reactor_class:
                # Install a specific reactor.
                install_reactor(reactor_class, event_loop)
            else:
                # Install the default one.
                from twisted.internet import reactor  # noqa: F401
        elif not is_reactor_installed():
            # We need a reactor to be already installed.
            raise RuntimeError(
                "We expected a Twisted reactor to be installed but it isn't."
            )
        if reactor_class:
            # We need to check that the correct reactor is installed.
            verify_installed_reactor(reactor_class)
            if _is_asyncio_reactor_installed() and event_loop:
                verify_installed_asyncio_event_loop(event_loop)

        if self._init_reactor or reactor_class:
            log_reactor_info()
    else:
        # We expect a reactor to not be installed.
        if is_reactor_installed():
            raise RuntimeError(
                "TWISTED_REACTOR_ENABLED is False but a Twisted reactor is installed."
            )
        logger.debug("Not using a Twisted reactor")
        self._apply_reactorless_default_settings()

    self.extensions = build_from_crawler(ExtensionManager, self)
    self.settings.freeze()

    d = dict(overridden_settings(self.settings))
    logger.info(
        "Overridden settings:\n%(settings)s", {"settings": pprint.pformat(d)}

def crawl(self, *args: Any, **kwargs: Any) -> Generator[Deferred[Any], Any, None]:
    """Start the crawler by instantiating its spider class with the given
    *args* and *kwargs* arguments, while setting the execution engine in
    motion. Should be called only once.

    Return a deferred that is fired when the crawl is finished.
    """
    if self.crawling:
        raise RuntimeError("Crawling already taking place")
    if self._started:
        raise RuntimeError(
            "Cannot run Crawler.crawl() more than once on the same instance."
        )
    self.crawling = self._started = True

    try:
        self.spider = self._create_spider(*args, **kwargs)
        self._apply_settings()
        self._update_root_log_handler()
        self.engine = self._create_engine()
        try:
            yield deferred_from_coro(self.engine.open_spider_async())
        except CloseSpider as exc:
            yield deferred_from_coro(
                self.engine.close_async(reason=exc.reason, error=exc.error)
            )
        else:
            yield deferred_from_coro(self.engine.start_async())
    except Exception:
        self.crawling = False
        if self._engine is not None:
            yield deferred_from_coro(self._engine.close_async())
        raise

async def crawl_async(self, *args: Any, **kwargs: Any) -> None:
    """Start the crawler by instantiating its spider class with the given
    *args* and *kwargs* arguments, while setting the execution engine in
    motion. Should be called only once.

    .. versionadded:: 2.14

    Complete when the crawl is finished.
    """
    if self.crawling:
        raise RuntimeError("Crawling already taking place")
    if self._started:
        raise RuntimeError(
            "Cannot run Crawler.crawl_async() more than once on the same instance."
        )
    self.crawling = self._started = True

    try:
        self.spider = self._create_spider(*args, **kwargs)
        self._apply_settings()
        self._update_root_log_handler()
        self.engine = self._create_engine()
        try:
            await self.engine.open_spider_async()
        except CloseSpider as exc:
            await self.engine.close_async(reason=exc.reason, error=exc.error)
        else:
            await self.engine.start_async()
    except Exception:
        self.crawling = False
        if self._engine is not None:
            await self._engine.close_async()
        raise

async def stop_async(self, *, mode: _StopMode = "graceful") -> None:
    """Start a graceful stop of the crawler and complete when the crawler is stopped.

    .. versionadded:: 2.14
    """
    mode = _normalize_stop_mode(mode)
    was_crawling = self.crawling
    self.crawling = False

    if not was_crawling and mode == "graceful":
        return

    if mode == "force":
        if self._force_stop_callback is not None:
            await ensure_awaitable(self._force_stop_callback())
            return
        logger.warning(
            "Force stop requested, but no process-level force stop callback is available. Falling back to fast stop."
        )
        mode = "fast"

    if self._engine is None:
        return

    # During shutdown callbacks, graceful stop may be re-entered after
    # the engine has already switched to non-running state.
    if mode == "graceful" and not self._engine.running:
        return

    try:
        await self._engine.stop_async(mode=mode)
    except RuntimeError as exc:
        if str(exc) != "Engine not running":
            raise

def _get_component(
    component_class: type[_T], components: Iterable[object]
) -> _T | None:
    for component in components:
        if isinstance(component, component_class):
            return component
    return None

def create_crawler(
    self, crawler_or_spidercls: type[Spider] | str | Crawler
) -> Crawler:
    crawler = super().create_crawler(crawler_or_spidercls)
    if self._reactor_crawler is None:
        self._reactor_crawler = crawler
    else:
        ignored = [
            setting
            for setting in _REACTOR_SETTINGS
            if self._reactor_crawler.settings[setting] != crawler.settings[setting]
        ]
        if ignored:
            warnings.warn(
                f"Spider {crawler.spidercls.__name__} defines a different "
                f"value than spider "
                f"{self._reactor_crawler.spidercls.__name__} for the "
                f"following reactor settings: {', '.join(ignored)}. Only "
                f"the value of the first spider is used, since the "
                f"reactor is shared by every spider in a process.",
                stacklevel=2,
            )
    return crawler

def _force_stop(self) -> None:
    if self.settings.getbool("TWISTED_REACTOR_ENABLED"):
        self._stop_reactor()
        return

    if (loop := self._reactorless_loop) is None:
        return
    if (task := self._reactorless_main_task) is not None:
        loop.call_soon_threadsafe(task.cancel)

def _cancel_all_tasks(loop: asyncio.AbstractEventLoop) -> None:
    # copy of asyncio.runners._cancel_all_tasks()
    to_cancel = asyncio.all_tasks(loop)
    if not to_cancel:
        return

    for task in to_cancel:
        task.cancel()

    loop.run_until_complete(asyncio.gather(*to_cancel, return_exceptions=True))

    for task in to_cancel:
        if task.cancelled():
            continue
        if task.exception() is not None:
            loop.call_exception_handler(
                {
                    "message": "unhandled exception during AsyncCrawlerProcess shutdown",
                    "exception": task.exception(),
                    "task": task,

def _schedule_reactorless_shutdown(self, *, mode: _StopMode, signum: int) -> None:
    if (loop := self._reactorless_loop) is None:
        return

    log_func = self._log_fast_shutdown if mode == "fast" else self._log_shutdown
    loop.call_soon_threadsafe(log_func, signum)

    def _create_shutdown_task() -> None:
        coro = self._shutdown_reactorless(mode=mode)
        try:
            loop.create_task(coro)
        except RuntimeError:
            coro.close()

    loop.call_soon_threadsafe(_create_shutdown_task)

def _signal_kill_reactorless(self, signum: int, _: FrameType | None) -> None:
    install_shutdown_handlers(signal.SIG_IGN)
    if (loop := self._reactorless_loop) is None:
        return
    loop.call_soon_threadsafe(self._log_kill, signum)
    if (task := self._reactorless_main_task) is not None:
        # Give the log line a moment to actually reach its output before
        # the process exits, since nothing else delays that exit past
        # this point.
        loop.call_later(_DEFER_DELAY, task.cancel)

def init_prios(self, startprios: Iterable[int]) -> None:
    if not startprios:
        return

    for priority in startprios:
        q = self.qfactory(priority)
        if q:
            self.queues[priority] = q
        else:
            q.close()
            self.changed = True
        if self._start_queue_cls:
            q = self._sqfactory(priority)
            if q:
                self._start_queues[priority] = q
            else:
                q.close()
                self.changed = True

    self.curprio = min(startprios)

def push(self, request: Request) -> None:
    priority = self.priority(request)
    is_start_request = request.meta.get("is_start_request", False)
    if is_start_request and self._start_queue_cls:
        if priority not in self._start_queues:
            self._start_queues[priority] = self._sqfactory(priority)
            self.changed = True
        q = self._start_queues[priority]
    else:
        if priority not in self.queues:
            self.queues[priority] = self.qfactory(priority)
            self.changed = True
        q = self.queues[priority]
    q.push(request)  # this may fail (eg. serialization error)
    if self.curprio is None or priority < self.curprio:
        self.curprio = priority

def pop(self) -> Request | None:
    while self.curprio is not None:
        try:
            q = self.queues[self.curprio]
        except KeyError:
            pass
        else:
            m = q.pop()
            if not q:
                del self.queues[self.curprio]
                q.close()
                self.changed = True
                if not self._start_queues:
                    self._update_curprio()
            return m
        if self._start_queues:
            try:
                q = self._start_queues[self.curprio]
            except KeyError:
                self._update_curprio()
            else:
                m = q.pop()
                if not q:
                    del self._start_queues[self.curprio]
                    q.close()
                    self.changed = True
                    self._update_curprio()
                return m
        else:
            self._update_curprio()
    return None

def _update_curprio(self) -> None:
    prios = {
        p
        for queues in (self.queues, self._start_queues)
        for p, q in queues.items()
        if q
    }
    self.curprio = min(prios) if prios else None

def close(self) -> list[int]:
    active = self.state()
    for queues in (self.queues, self._start_queues):
        for q in queues.values():
            q.close()
    return active

def __len__(self) -> int:
    return (
        sum(
            len(x)
            for queues in (self.queues, self._start_queues)
            for x in queues.values()
        )
        if self.queues or self._start_queues
        else 0

def _next_slot(self, stats: list[tuple[int, str]], *, update_state: bool) -> str:
    last = self._last_selected_slot
    min_active: int | None = None
    best_slot: str | None = None
    best_slot_after_last: str | None = None
    for active, slot in stats:
        if min_active is None or active < min_active:
            min_active = active
            best_slot = slot
            best_slot_after_last = None
            if last is not None and slot > last:
                best_slot_after_last = slot
        elif active == min_active:
            if best_slot is None or slot < best_slot:
                best_slot = slot
            if (
                last is not None
                and slot > last
                and (best_slot_after_last is None or slot < best_slot_after_last)
            ):
                best_slot_after_last = slot
    assert best_slot is not None
    slot = best_slot_after_last if best_slot_after_last is not None else best_slot
    if update_state:
        self._last_selected_slot = slot
    return slot

def from_headers(self, headers: Mapping[bytes, bytes]) -> type[Response]:
    """Return the most appropriate Response class by looking at the HTTP
    headers"""
    cls = Response
    if b"Content-Type" in headers:
        cls = self.from_content_type(
            content_type=headers[b"Content-Type"],
            content_encoding=headers.get(b"Content-Encoding"),
        )
    if cls is Response and b"Content-Disposition" in headers:
        cls = self.from_content_disposition(headers[b"Content-Disposition"])
    return cls

def from_filename(self, filename: str) -> type[Response]:
    """Return the most appropriate Response class from a file name"""
    mimetype, encoding = self.mimetypes.guess_type(filename)
    if mimetype and not encoding:
        return self.from_mimetype(mimetype)
    return Response

def from_body(self, body: bytes) -> type[Response]:
    """Try to guess the appropriate response based on the body content.
    This method is a bit magic and could be improved in the future, but
    it's not meant to be used except for special cases where response types
    cannot be guess using more straightforward methods."""
    chunk = body[:5000]
    chunk = to_bytes(chunk)
    if not binary_is_text(chunk):
        return self.from_mimetype("application/octet-stream")
    lowercase_chunk = chunk.lower()
    if b"<html>" in lowercase_chunk:
        return self.from_mimetype("text/html")
    if b"<?xml" in lowercase_chunk:
        return self.from_mimetype("text/xml")
    if b"<!doctype html>" in lowercase_chunk:
        return self.from_mimetype("text/html")
    return self.from_mimetype("text")

def from_args(
    self,
    headers: Mapping[bytes, bytes] | None = None,
    url: str | None = None,
    filename: str | None = None,
    body: bytes | None = None,
) -> type[Response]:
    """Guess the most appropriate Response class based on
    the given arguments."""
    cls = Response
    if headers is not None:
        cls = self.from_headers(headers)
    if cls is Response and url is not None:
        cls = self.from_filename(url)
    if cls is Response and filename is not None:
        cls = self.from_filename(filename)
    if cls is Response and body is not None:
        cls = self.from_body(body)
    return cls

def scraped(
    self, item: Any, response: Response | Failure | None, spider: Spider
) -> LogFormatterResult:
    """Logs a message when an item is scraped by a spider."""
    src: Any
    if response is None:
        src = f"{global_object_name(spider.__class__)}.start"
    elif isinstance(response, Failure):
        src = response.getErrorMessage()
    else:
        src = response
    return {
        "level": logging.DEBUG,
        "msg": SCRAPEDMSG,
        "args": {
            "src": src,
            "item": item,

def dropped(
    self,
    item: Any,
    exception: BaseException,
    response: Response | Failure | None,
    spider: Spider,
) -> LogFormatterResult:
    """Logs a message when an item is dropped while it is passing through the item pipeline."""
    if (level := getattr(exception, "log_level", None)) is None:
        level = spider.crawler.settings["DEFAULT_DROPITEM_LOG_LEVEL"]
    if isinstance(level, str):
        level = getattr(logging, level)
    return {
        "level": level,
        "msg": DROPPEDMSG,
        "args": {
            "exception": exception,
            "item": item,

def _iter_command_classes(module_name: str) -> Iterable[type[ScrapyCommand]]:
    # TODO: add `name` attribute to commands and merge this function with
    # scrapy.utils.spider.iter_spider_classes
    for module in walk_modules_iter(module_name):
        for obj in vars(module).values():
            if (
                inspect.isclass(obj)
                and issubclass(obj, ScrapyCommand)
                and obj.__module__ == module.__name__
                and obj not in {ScrapyCommand, BaseRunSpiderCommand}
            ):
                yield obj

def _get_commands_from_module(module: str, inproject: bool) -> dict[str, ScrapyCommand]:
    d: dict[str, ScrapyCommand] = {}
    for cmd in _iter_command_classes(module):
        if inproject or not cmd.requires_project:
            cmdname = cmd.__module__.split(".")[-1]
            d[cmdname] = cmd()
    return d

def _get_commands_from_entry_points(
    inproject: bool, group: str = "scrapy.commands"
) -> dict[str, ScrapyCommand]:
    cmds: dict[str, ScrapyCommand] = {}
    for entry_point in entry_points(group=group):
        obj = entry_point.load()
        if inspect.isclass(obj) and issubclass(obj, ScrapyCommand):
            cmds[entry_point.name] = obj()
        else:
            raise ValueError(f"Invalid entry point {entry_point.name}")
    return cmds

def _pop_command_name(argv: list[str]) -> str | None:
    for i in range(1, len(argv)):
        if not argv[i].startswith("-"):
            return argv.pop(i)
    return None

def _print_commands(settings: BaseSettings, inproject: bool) -> None:
    _print_header(settings, inproject)
    print(
        "Usage:\n",
        "  scrapy <command> [options] [args]\n",
        "Available commands:\n",
    )
    cmds = _get_commands_dict(settings, inproject)
    print(
        "\n".join(
            f"  {cmdname:<13} {cmdclass.short_desc()}"
            for cmdname, cmdclass in sorted(cmds.items())
        )
    )
    if not inproject:
        print(
            "\n",
            "  [ more ]      More commands available when run from project directory",
        )
    print("\n", 'Use "scrapy <command> -h" to see more info about a command')

def _print_unknown_command_msg(
    settings: BaseSettings, cmdname: str, inproject: bool
) -> None:
    proj_only_cmds = _get_project_only_cmds(settings)
    if cmdname in proj_only_cmds and not inproject:
        cmd_list = ", ".join(sorted(proj_only_cmds))
        print(
            f"The {cmdname} command is not available from this location.\n"
            f"These commands are only available from within a project: {cmd_list}.\n"
        )
    else:
        print(f"Unknown command: {cmdname}\n")

def _run_print_help(
    parser: argparse.ArgumentParser,
    func: Callable[_P, None],
    *a: _P.args,
    **kw: _P.kwargs,
) -> None:
    try:
        func(*a, **kw)
    except UsageError as e:
        if str(e):
            parser.error(str(e))
        if e.print_help:
            parser.print_help()
        sys.exit(2)

def execute(argv: list[str] | None = None, settings: Settings | None = None) -> None:
    if argv is None:
        argv = sys.argv

    if settings is None:
        settings = get_project_settings()
        # set EDITOR from environment if available
        try:
            editor = os.environ["EDITOR"]
        except KeyError:
            pass
        else:
            settings["EDITOR"] = editor

    inproject = inside_project()
    cmds = _get_commands_dict(settings, inproject)
    cmdname = _pop_command_name(argv)
    if not cmdname:
        _print_commands(settings, inproject)
        sys.exit(0)
    elif cmdname not in cmds:
        _print_unknown_command(settings, cmdname, inproject)
        sys.exit(2)

    cmd = cmds[cmdname]
    parser = ScrapyArgumentParser(
        formatter_class=ScrapyHelpFormatter,
        usage=f"scrapy {cmdname} {cmd.syntax()}",
        conflict_handler="resolve",
        description=cmd.long_desc(),
    )
    settings.setdict(cmd.default_settings, priority="command")
    cmd.settings = settings
    cmd.add_options(parser)
    opts, args = parser.parse_known_args(args=argv[1:])
    _run_print_help(parser, cmd.process_options, args, opts)

    if cmd.requires_crawler_process:
        if (
            settings["TWISTED_REACTOR"] == _asyncio_reactor_path
            and not settings.getbool("FORCE_CRAWLER_PROCESS")
        ) or not settings.getbool("TWISTED_REACTOR_ENABLED"):
            cmd.crawler_process = AsyncCrawlerProcess(settings)
        else:
            cmd.crawler_process = CrawlerProcess(settings)
    _run_print_help(parser, _run_command, cmd, args, opts)
    sys.exit(cmd.exitcode)

def __eq__(self, other: object) -> bool:
    if not isinstance(other, Link):
        return NotImplemented
    return (
        self.url == other.url
        and self.text == other.text
        and self.fragment == other.fragment
        and self.nofollow == other.nofollow

def iter_default_settings() -> Iterable[tuple[str, Any]]:
    """Return the default settings as an iterator of (name, value) tuples"""
    for name in dir(default_settings):
        if name.isupper():
            yield name, getattr(default_settings, name)

def overridden_settings(
    settings: Mapping[str, Any],
) -> Iterable[tuple[str, Any]]:
    """Return an iterable of the settings that have been overridden"""
    for name, defvalue in iter_default_settings():
        value = settings[name]
        if not isinstance(defvalue, dict) and value != defvalue:
            yield name, value

def set(self, value: Any, priority: int) -> None:
    """Sets value if priority is higher or equal than current priority."""
    if priority >= self.priority:
        if isinstance(self.value, BaseSettings):
            value = BaseSettings(value, priority=priority)
        self.value = value
        self.priority = priority

def getdictorlist(
    self,
    name: str,
    default: dict[Any, Any] | list[Any] | tuple[Any, ...] | None = None,
) -> dict[Any, Any] | list[Any]:
    """Get a setting value as either a :class:`dict` or a :class:`list`.

    If the setting is already a dict or a list, a copy of it will be
    returned.

    If it is a string it will be evaluated as JSON, or as a comma-separated
    list of strings as a fallback.

    For example, settings populated from the command line will return:

    -   ``{'key1': 'value1', 'key2': 'value2'}`` if set to
        ``'{"key1": "value1", "key2": "value2"}'``

    -   ``['one', 'two']`` if set to ``'["one", "two"]'`` or ``'one,two'``

    :param name: the setting name
    :type name: str

    :param default: the value to return if no setting is found
    :type default: object
    """
    value = self.get(name, default)
    if value is None:
        return {}
    if isinstance(value, str):
        try:
            value_loaded = json.loads(value)
            if not isinstance(value_loaded, (dict, list)):
                raise ValueError(
                    f"JSON string for setting '{name}' must evaluate to a dict or list, "
                    f"got {type(value_loaded).__name__}: {value_loaded!r}"
                )
            return value_loaded
        except ValueError:
            return value.split(",")
    if isinstance(value, tuple):
        return list(value)
    if not isinstance(value, (dict, list)):
        raise ValueError(
            f"Setting '{name}' must be a dict, list, tuple, or string, "
            f"got {type(value).__name__}: {value!r}"
        )
    return copy.deepcopy(value)

def get_component_priority_dict_with_base(self, name: str) -> BaseSettings:
    """Get a composition of a component priority dictionary setting and
    its ``_BASE`` counterpart.

    Keys are resolved to their import path for deduplication and then
    restored to their latest input representation.

    :param name: name of the component priority dictionary setting
    :type name: str
    """
    if not isinstance(name, str):
        raise ValueError(f"Base setting key must be a string, got {name}")

    normalized_keys = {}
    obj_keys = set()

    def track_loaded_key(k: Any) -> None:
        if k not in obj_keys:
            obj_keys.add(k)
            return
        logger.warning(
            f"Setting {name} contains multiple keys that refer to the "
            f"same object: {global_object_name(k)}. Only the last one will "
            f"be kept."
        )

    def normalize_key(key: Any) -> str:
        try:
            loaded_key = load_object(key)
        except (ImportError, NameError, TypeError, ValueError) as exception:
            raise ValueError(
                f"Could not load {key!r}, a key of the {name} setting: "
                f"{exception}. Fix its import path or remove the entry."
            ) from exception
        import_path = global_object_name(loaded_key)
        normalized_keys[import_path] = key
        track_loaded_key(loaded_key)
        return import_path

    def restore_key(k: str) -> Any:
        return normalized_keys.get(k, k)

    result = dict(self[name + "_BASE"] or {})
    override = {normalize_key(k): v for k, v in (self[name] or {}).items()}
    result.update(override)
    return BaseSettings(
        {restore_key(k): v for k, v in result.items() if v is not None}

def maxpriority(self) -> int:
    """
    Return the numerical value of the highest priority present throughout
    all settings, or the numerical value for ``default`` from
    :attr:`~scrapy.settings.SETTINGS_PRIORITIES` if there are no settings
    stored.
    """
    if len(self) > 0:
        return max(cast("int", self.getpriority(name)) for name in self)
    return get_settings_priority("default")

def delete(self, name: str, priority: int | str = "project") -> None:
    if name not in self:
        raise KeyError(name)
    self._assert_mutability()
    priority = get_settings_priority(priority)
    if priority >= cast("int", self.getpriority(name)):
        del self.attributes[name]

def pop(self, name: str, default: Any = __default) -> Any:  # pylint: disable=arguments-renamed
    try:
        value = self.attributes[name].value
    except KeyError:
        if default is self.__default:
            raise
        return default
    del self[name]
    return value

def _parse(self, response: Response, **kwargs: Any) -> Any:
    response = self.adapt_response(response)
    nodes: Iterable[Selector]
    if self.iterator == "iternodes":
        nodes = self._iternodes(response)
    elif self.iterator == "xml":
        if not isinstance(response, TextResponse):
            raise ValueError("Response content isn't text")
        selector = Selector(response, type="xml")
        self._register_namespaces(selector)
        nodes = selector.xpath(f"//{self.itertag}")
    elif self.iterator == "html":
        if not isinstance(response, TextResponse):
            raise ValueError("Response content isn't text")
        selector = Selector(response, type="html")
        self._register_namespaces(selector)
        nodes = selector.xpath(f"//{self.itertag}")
    else:
        raise NotSupported("Unsupported node iterator")

    return self.parse_nodes(response, nodes)

def __init__(self, name: str | None = None, **kwargs: Any):
    if name is not None:
        self.name: str = name
    elif not getattr(self, "name", None):
        raise ValueError(f"{type(self).__name__} must have a name")
    self.__dict__.update(kwargs)
    if not hasattr(self, "start_urls"):
        self.start_urls: list[str] = []

def _get_method(method: _CallableT | str | None, spider: Spider) -> _CallableT | None:
    if callable(method):
        return method
    if isinstance(method, str):
        return getattr(spider, method, None)
    return None

def _requests_to_follow(self, response: Response) -> Iterable[Request | None]:
    if not isinstance(response, HtmlResponse):
        return
    seen: set[Link] = set()
    response_rule_name = (
        response.request.meta.get("rule_name") if response.request else None
    )
    for rule_index, rule in enumerate(self._rules):
        if (
            rule.from_rules is not None
            and response_rule_name not in rule.from_rules
        ):
            continue
        links: list[Link] = [
            lnk
            for lnk in rule.link_extractor.extract_links(response)
            if lnk not in seen
        ]
        for link in cast("ProcessLinksT", rule.process_links)(links):
            seen.add(link)
            request = self._build_request(rule_index, link)
            yield cast("ProcessRequestT", rule.process_request)(request, response)

async def parse_with_rules(
    self,
    response: Response,
    callback: CallbackT | None,
    cb_kwargs: dict[str, Any],
    follow: bool = True,
) -> AsyncIterator[Any]:
    try:
        if callback:
            cb_res = callback(response, **cb_kwargs) or ()
            if isinstance(cb_res, AsyncIterator):
                cb_res = await collect_asyncgen(cb_res)
            elif isinstance(cb_res, Awaitable):
                cb_res = await cb_res
            cb_res = self.process_results(response, cb_res)
            for request_or_item in iterate_spider_output(cb_res):
                yield request_or_item
    finally:
        if follow and self._follow_links:
            for request_or_item in self._requests_to_follow(response):
                yield request_or_item

def _handle_failure(
    self, failure: Failure, errback: Callable[[Failure], Any] | None
) -> Iterable[Any]:
    if errback:
        results = errback(failure) or ()
        yield from iterate_spider_output(results)

def iterloc(it: Iterable[dict[str, Any]], alt: bool = False) -> Iterable[str]:
    for d in it:
        if loc := d["loc"]:
            yield loc

        # Also consider alternate URLs (xhtml:link rel="alternate")
        if alt and (alt_list := d.get("alternate")):
            yield from alt_list

def __init__(self, *a: Any, **kw: Any):
    super().__init__(*a, **kw)
    self._cbs: list[tuple[re.Pattern[str], CallbackT]] = []
    for r, c in self.sitemap_rules:
        if isinstance(c, str):
            c = cast("CallbackT", getattr(self, c))  # noqa: PLW2901
        self._cbs.append((regex(r), c))
    self._follow: list[re.Pattern[str]] = [regex(x) for x in self.sitemap_follow]

def _parse_sitemap(self, response: Response) -> Iterable[Request]:
    if response.url.endswith("/robots.txt"):
        urls = list(sitemap_urls_from_robots(response.body, base_url=response.url))
        return (Request(url, callback=self._parse_sitemap) for url in urls)

    body = self._get_sitemap_body(response)
    if not body:
        logger.warning(
            "Ignoring invalid sitemap: %(response)s",
            {"response": response},
            extra={"spider": self},
        )
        return ()

    s = Sitemap(body)

    if s.type == "sitemapindex":
        urls = list(
            self._get_urls_from_sitemapindex(self.sitemap_filter(s), response.url)
        )
        return (Request(loc, callback=self._parse_sitemap) for loc in urls)

    if s.type == "urlset":
        url_callback_pairs = list(
            self._get_urls_and_callbacks_from_urlset(
                self.sitemap_filter(s), response.url
            )
        )
        return (Request(loc, callback=c) for loc, c in url_callback_pairs)

    logger.warning(
        "Ignoring invalid sitemap: %(response)s",
        {"response": response},
        extra={"spider": self},
    )

    return ()

def _get_urls_from_sitemapindex(
    self, it: Iterable[dict[str, Any]], base_url: str
) -> Iterable[str]:
    for loc in iterloc(it, self.sitemap_alternate_links):
        loc = urljoin(base_url, loc)  # noqa: PLW2901
        if any(x.search(loc) for x in self._follow):
            yield loc

def _get_urls_and_callbacks_from_urlset(
    self, it: Iterable[dict[str, Any]], base_url: str
) -> Iterable[tuple[str, CallbackT]]:
    for loc in iterloc(it, self.sitemap_alternate_links):
        loc = urljoin(base_url, loc)  # noqa: PLW2901
        for r, c in self._cbs:
            if r.search(loc):
                yield loc, c
                break

def parse_cachecontrol(header: bytes) -> dict[bytes, bytes | None]:
    """Parse Cache-Control header

    https://www.w3.org/Protocols/rfc2616/rfc2616-sec14.html#sec14.9

    >>> parse_cachecontrol(b'public, max-age=3600') == {b'public': None,
    ...                                                 b'max-age': b'3600'}
    True
    >>> parse_cachecontrol(b'') == {}
    True

    """
    directives = {}
    for directive in header.split(b","):
        key, sep, val = directive.strip().partition(b"=")
        if key:
            directives[key.lower()] = val if sep else None
    return directives

def rfc1123_to_epoch(date_str: str | bytes | None) -> int | None:
    # The HTTP time format (which is how we use this function) is actually in
    # RFC 7231 §7.1.1.1, it refers to RFC 5322 and also requires support for
    # two obsolete formats (RFC 850 and asctime()). email.utils evidently
    # supports all three.
    if date_str is None:
        return None
    try:
        date_str = to_unicode(date_str, encoding="ascii")
        date = parsedate_to_datetime(date_str)
        if date.tzinfo is None:
            date = date.replace(tzinfo=timezone.utc)
        return int(date.timestamp())
    except Exception:
        return None

def _parse_cachecontrol(self, r: Request | Response) -> dict[bytes, bytes | None]:
    if r not in self._cc_parsed:
        cch = r.headers.get(b"Cache-Control", b"")
        assert cch is not None
        parsed = parse_cachecontrol(cch)
        if isinstance(r, Response):
            for key in self.ignore_response_cache_controls:
                parsed.pop(key, None)
        self._cc_parsed[r] = parsed
    return self._cc_parsed[r]

def is_cached_response_fresh(
    self, cachedresponse: Response, request: Request
) -> bool:
    cc = self._parse_cachecontrol(cachedresponse)
    ccreq = self._parse_cachecontrol(request)
    if b"no-cache" in cc or b"no-cache" in ccreq:
        return False

    now = time()
    freshnesslifetime = self._compute_freshness_lifetime(
        cachedresponse, request, now
    )
    currentage = self._compute_current_age(cachedresponse, request, now)

    reqmaxage = self._get_max_age(ccreq)
    if reqmaxage is not None:
        freshnesslifetime = min(freshnesslifetime, reqmaxage)

    if currentage < freshnesslifetime:
        return True

    if b"max-stale" in ccreq and b"must-revalidate" not in cc:
        # From RFC2616: "Indicates that the client is willing to
        # accept a response that has exceeded its expiration time.
        # If max-stale is assigned a value, then the client is
        # willing to accept a response that has exceeded its
        # expiration time by no more than the specified number of
        # seconds. If no value is assigned to max-stale, then the
        # client is willing to accept a stale response of any age."
        staleage = ccreq[b"max-stale"]
        if staleage is None:
            return True

        try:
            if currentage < freshnesslifetime + max(0, int(staleage)):
                return True
        except ValueError:
            pass

    # Cached response is stale, try to set validators if any
    self._set_conditional_validators(request, cachedresponse)
    return False

def is_cached_response_valid(
    self, cachedresponse: Response, response: Response, request: Request
) -> bool:
    # Use the cached response if the new response is a server error,
    # as long as the old response didn't specify must-revalidate.
    if response.status >= 500:
        cc = self._parse_cachecontrol(cachedresponse)
        if b"must-revalidate" not in cc:
            return True

    # Use the cached response if the server says it hasn't changed.
    return response.status == 304

def _set_conditional_validators(
    self, request: Request, cachedresponse: Response
) -> None:
    if b"Last-Modified" in cachedresponse.headers:
        request.headers[b"If-Modified-Since"] = cachedresponse.headers[
            b"Last-Modified"
        ]

    if b"ETag" in cachedresponse.headers:
        request.headers[b"If-None-Match"] = cachedresponse.headers[b"ETag"]

def _compute_current_age(
    self, response: Response, request: Request, now: float
) -> float:
    # Reference nsHttpResponseHead::ComputeCurrentAge
    # https://dxr.mozilla.org/mozilla-central/source/netwerk/protocol/http/nsHttpResponseHead.cpp#658
    currentage: float = 0
    # If Date header is not set we assume it is a fast connection, and
    # clock is in sync with the server
    date = rfc1123_to_epoch(response.headers.get(b"Date")) or now
    if now > date:
        currentage = now - date

    if b"Age" in response.headers:
        try:
            age = int(response.headers[b"Age"])  # type: ignore[arg-type]
            currentage = max(currentage, age)
        except ValueError:
            pass

    return currentage

def _read_data(
    self, spider: Spider, request: Request
) -> tuple[dict[str, Any], float] | None:
    key = self._fingerprinter.fingerprint(request).hex()
    db = self.db
    tkey = f"{key}_time"
    if tkey not in db:
        return None  # not found

    ts = float(db[tkey])
    if 0 < self.expiration_secs < time() - ts:
        return None  # expired

    data = cast("dict[str, Any]", pickle.loads(db[f"{key}_data"]))  # noqa: S301
    return data, ts

def _read_meta(self, spider: Spider, request: Request) -> dict[str, Any] | None:
    rpath = Path(self._get_request_path(spider, request))
    metapath = rpath / "pickled_meta"
    if not metapath.exists():
        return None  # not found
    mtime = metapath.stat().st_mtime
    if 0 < self.expiration_secs < time() - mtime:
        return None  # expired
    with self._open(metapath, "rb") as f:
        return cast("dict[str, Any]", pickle.load(f))  # noqa: S301

def __init__(self, crawler: Crawler):
    self.crawler: Crawler = crawler
    if not crawler.settings.getbool("AUTOTHROTTLE_ENABLED"):
        raise NotConfigured

    self.debug: bool = crawler.settings.getbool("AUTOTHROTTLE_DEBUG")
    self.target_concurrency: float = crawler.settings.getfloat(
        "AUTOTHROTTLE_TARGET_CONCURRENCY"
    )
    if self.target_concurrency <= 0.0:
        raise NotConfigured(
            f"AUTOTHROTTLE_TARGET_CONCURRENCY "
            f"({self.target_concurrency!r}) must be higher than 0."
        )
    crawler.signals.connect(self._spider_opened, signal=signals.spider_opened)
    crawler.signals.connect(
        self._response_downloaded, signal=signals.response_downloaded

def _effective_timeout(
    requested: float | None, default: float, maximum: float
) -> float:
    """Clamp a client-requested timeout to ``maximum``."""
    if requested is None or not requested > 0:
        requested = default
    return min(requested, maximum)

def __init__(self, crawler: Crawler):
    if not crawler.settings.getbool("REMOTE_CONTROL_ENABLED"):
        raise NotConfigured
    if (
        crawler.settings.getbool("TWISTED_REACTOR_ENABLED")
        and not is_asyncio_available()
    ):
        raise NotConfigured(
            f"{type(self).__name__} requires the asyncio support."
            f" You can set the REMOTE_CONTROL_ENABLED setting to False to remove this warning."
        )
    self._crawler: Crawler = crawler
    self._default_timeout: float = crawler.settings.getfloat(
        "REMOTE_CONTROL_TIMEOUT_DEFAULT"
    )
    self._max_timeout: float = crawler.settings.getfloat(
        "REMOTE_CONTROL_TIMEOUT_MAX"
    )
    self._output_max_bytes: int = crawler.settings.getint(
        "REMOTE_CONTROL_OUTPUT_MAX_BYTES"
    )
    self._traceback_max_bytes: int = crawler.settings.getint(
        "REMOTE_CONTROL_TRACEBACK_MAX_BYTES"
    )
    if self._default_timeout <= 0 or self._max_timeout <= 0:
        raise NotConfigured("REMOTE_CONTROL_TIMEOUT_* must be positive")

    self._stash: dict[str, Any] = {}
    self._auth_token: str | None = None
    self._runner: web.AppRunner | None = None
    self._job_file_path: Path | None = None

    crawler.signals.connect(self.start, signal=signals.engine_started)
    crawler.signals.connect(self.stop, signal=signals.engine_stopped)

async def _handle_execute(self, request: web.Request) -> web.Response:
    """An aiohttp request handler for the ``/execute`` endpoint."""
    if not self._is_authenticated(request):
        return web.json_response({"error": "unauthorized"}, status=401)

    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "invalid JSON body"}, status=400)
    if not isinstance(body, dict) or not isinstance(body.get("code"), str):
        return web.json_response(
            {"error": "Missing or invalid 'code' value"}, status=400
        )
    requested_timeout = body.get("timeout_sec")
    if requested_timeout is not None and not isinstance(
        requested_timeout, (int, float)
    ):
        return web.json_response(
            {"error": "Invalid 'timeout_sec' value"}, status=400
        )
    timeout = _effective_timeout(
        requested_timeout, self._default_timeout, self._max_timeout
    )
    compiled = _compile(body["code"])
    result: ExecuteResult
    if isinstance(compiled, CodeType):
        result = await self._run_code(compiled, timeout)
    else:
        result = {
            "status": "compile_error",
            "output": "",
            "traceback": compiled,
            "elapsed_sec": 0.0,
        }
    return web.json_response(result)

def spider_closed(self, spider: Spider, reason: str) -> None:
    if self.task and self.task.running:
        self.task.stop()

    rpm_final, ipm_final = self.calculate_final_stats(spider)
    self.stats.set_value("responses_per_minute", rpm_final)
    self.stats.set_value("items_per_minute", ipm_final)

def calculate_final_stats(
    self, spider: Spider
) -> tuple[None, None] | tuple[float, float]:
    start_time = self.stats.get_value("start_time")
    finish_time = self.stats.get_value("finish_time")

    if not start_time or not finish_time:
        return None, None

    mins_elapsed = (finish_time - start_time).seconds / 60

    if mins_elapsed == 0:
        return None, None

    items = self.stats.get_value("item_scraped_count", 0)
    pages = self.stats.get_value("response_received_count", 0)

    return (pages / mins_elapsed), (items / mins_elapsed)

def _thread_stacks(self) -> str:
    id2name = {th.ident: th.name for th in threading.enumerate()}
    dumps = ""
    for id_, frame in sys._current_frames().items():
        name = id2name.get(id_, "")
        dump = "".join(traceback.format_stack(frame))
        dumps += f"# Thread: {name}({id_})\n{dump}\n"
    return dumps

def __init__(self, crawler: Crawler):
    self.crawler: Crawler = crawler

    # for CLOSESPIDER_TIMEOUT
    self.task: CallLaterResult | None = None

    # for CLOSESPIDER_TIMEOUT_NO_ITEM
    self.task_no_item: AsyncioLoopingCall[[], None] | LoopingCall | None = None

    self.close_on: dict[str, Any] = {
        "timeout": crawler.settings.getfloat("CLOSESPIDER_TIMEOUT"),
        "itemcount": crawler.settings.getint("CLOSESPIDER_ITEMCOUNT"),
        "pagecount": crawler.settings.getint("CLOSESPIDER_PAGECOUNT"),
        "errorcount": crawler.settings.getint("CLOSESPIDER_ERRORCOUNT"),
        "timeout_no_item": crawler.settings.getint("CLOSESPIDER_TIMEOUT_NO_ITEM"),
        "pagecount_no_item": crawler.settings.getint(
            "CLOSESPIDER_PAGECOUNT_NO_ITEM"
        ),
    }

    if not any(self.close_on.values()):
        raise NotConfigured

    self.counter: defaultdict[str, int] = defaultdict(int)

    if self.close_on.get("errorcount"):
        crawler.signals.connect(self.error_count, signal=signals.spider_error)
    if self.close_on.get("pagecount") or self.close_on.get("pagecount_no_item"):
        crawler.signals.connect(self.page_count, signal=signals.response_received)
    if self.close_on.get("timeout"):
        crawler.signals.connect(self.spider_opened, signal=signals.spider_opened)
    if self.close_on.get("itemcount") or self.close_on.get("pagecount_no_item"):
        crawler.signals.connect(self.item_scraped, signal=signals.item_scraped)
    if self.close_on.get("timeout_no_item"):
        self.timeout_no_item: int = self.close_on["timeout_no_item"]
        self.items_in_period: int = 0
        crawler.signals.connect(
            self.spider_opened_no_item, signal=signals.spider_opened
        )
        crawler.signals.connect(
            self.item_scraped_no_item, signal=signals.item_scraped
        )

    crawler.signals.connect(self.spider_closed, signal=signals.spider_closed)

def page_count(self, response: Response, request: Request, spider: Spider) -> None:
    self.counter["pagecount"] += 1
    self.counter["pagecount_since_last_item"] += 1
    if self.counter["pagecount"] == self.close_on["pagecount"]:
        self._close_spider("closespider_pagecount")
        return
    if self.close_on["pagecount_no_item"] and (
        self.counter["pagecount_since_last_item"]
        >= self.close_on["pagecount_no_item"]
    ):
        self._close_spider("closespider_pagecount_no_item")

def spider_closed(self, spider: Spider) -> None:
    if self.task:
        self.task.cancel()
        self.task = None

    if self.task_no_item:
        if self.task_no_item.running:  # pragma: no branch
            self.task_no_item.stop()
        self.task_no_item = None

def spider_closed(self, spider: Spider) -> None:
    if self.jobdir:
        with Path(self.statefn).open("wb") as f:
            assert hasattr(spider, "state")  # set in spider_opened
            pickle.dump(spider.state, f, protocol=4)

def spider_opened(self, spider: Spider) -> None:
    if self.jobdir and Path(self.statefn).exists():
        with Path(self.statefn).open("rb") as f:
            spider.state = pickle.load(f)  # type: ignore[attr-defined]  # noqa: S301
    else:
        spider.state = {}  # type: ignore[attr-defined]

def from_crawler(cls, crawler: Crawler) -> Self:
    interval: float = crawler.settings.getfloat("LOGSTATS_INTERVAL")
    if not interval:
        raise NotConfigured
    try:
        ext_stats: dict[str, Any] | None = crawler.settings.getdict(
            "PERIODIC_LOG_STATS"
        )
    except (TypeError, ValueError):
        ext_stats = (
            {"enabled": True}
            if crawler.settings.getbool("PERIODIC_LOG_STATS")
            else None
        )
    try:
        ext_delta: dict[str, Any] | None = crawler.settings.getdict(
            "PERIODIC_LOG_DELTA"
        )
    except (TypeError, ValueError):
        ext_delta = (
            {"enabled": True}
            if crawler.settings.getbool("PERIODIC_LOG_DELTA")
            else None
        )

    ext_timing_enabled: bool = crawler.settings.getbool(
        "PERIODIC_LOG_TIMING_ENABLED"
    )
    if not (ext_stats or ext_delta or ext_timing_enabled):
        raise NotConfigured
    assert ext_stats is not None
    assert ext_delta is not None
    o = cls(
        crawler.stats,
        interval,
        ext_stats,
        ext_delta,
        ext_timing_enabled,
    )
    crawler.signals.connect(o.spider_opened, signal=signals.spider_opened)
    crawler.signals.connect(o.spider_closed, signal=signals.spider_closed)
    return o

def log(self) -> None:
    data: dict[str, Any] = {}
    if self.ext_timing_enabled:
        data.update(self.log_timing())
    if self.ext_delta_enabled:
        data.update(self.log_delta())
    if self.ext_stats_enabled:
        data.update(self.log_crawler_stats())
    logger.info(self.encoder.encode(data))

def log_delta(self) -> dict[str, Any]:
    num_stats: dict[str, int | float] = {
        k: v
        for k, v in self.stats._stats.items()
        if isinstance(v, (int, float))
        and self.param_allowed(k, self.ext_delta_include, self.ext_delta_exclude)
    }
    delta = {k: v - self.delta_prev.get(k, 0) for k, v in num_stats.items()}
    self.delta_prev = num_stats
    return {"delta": delta}

def log_crawler_stats(self) -> dict[str, Any]:
    stats = {
        k: v
        for k, v in self.stats._stats.items()
        if self.param_allowed(k, self.ext_stats_include, self.ext_stats_exclude)
    }
    return {"stats": stats}

def param_allowed(
    self, stat_name: str, include: Sequence[str], exclude: Sequence[str]
) -> bool:
    if not include and not exclude:
        return True
    for p in exclude:
        if p in stat_name:
            return False
    if exclude and not include:
        return True
    return any(p in stat_name for p in include)

def __init__(self, feed_options: dict[str, Any] | None) -> None:
    self.feed_options = feed_options
    if feed_options is not None:
        self.item_classes = tuple(
            load_object(item_class)
            for item_class in feed_options.get("item_classes") or ()
        )
    else:
        self.item_classes = ()

def open(self, spider: Spider) -> IO[bytes]:
    path = spider.crawler.settings["FEED_TEMPDIR"]
    if path and not Path(path).is_dir():
        raise OSError("Not a Directory: " + str(path))

    return NamedTemporaryFile(prefix="feed-", dir=path)

def __init__(
    self,
    uri: str,
    _stdout: IO[bytes] | None = None,
    *,
    feed_options: dict[str, Any] | None = None,
):
    if not _stdout:
        _stdout = sys.stdout.buffer
    self._stdout: IO[bytes] = _stdout
    if feed_options and feed_options.get("overwrite", False) is True:
        logger.warning(
            "Standard output (stdout) storage does not support "

def __init__(self, uri: str, *, feed_options: dict[str, Any] | None = None):
    self.path: str = file_uri_to_path(uri) if uri.startswith("file:") else uri
    feed_options = feed_options or {}
    self.write_mode: OpenBinaryMode = (
        "wb" if feed_options.get("overwrite", False) else "ab"

def open(self, spider: Spider) -> IO[bytes]:
    dirname = Path(self.path).parent
    if dirname and not dirname.exists():
        dirname.mkdir(parents=True)
    return Path(self.path).open(self.write_mode)

def __init__(self, crawler: Crawler):
    self.crawler: Crawler = crawler
    self.settings: Settings = crawler.settings
    self.feeds: dict[str, dict[str, Any]] = {}
    self.slots: list[FeedSlot] = []
    self.filters: dict[str, ItemFilter] = {}
    self.processors: dict[str, _ItemProcessor | None] = {}
    self._pending_close_tasks: list[asyncio.Task[None] | Deferred[None]] = []

    if not self.settings["FEEDS"] and not self.settings["FEED_URI"]:
        raise NotConfigured

    # Begin: Backward compatibility for FEED_URI and FEED_FORMAT settings
    if self.settings["FEED_URI"]:
        warnings.warn(
            "The `FEED_URI` and `FEED_FORMAT` settings have been deprecated in favor of "
            "the `FEEDS` setting. Please see the `FEEDS` setting docs for more details",
            category=ScrapyDeprecationWarning,
            stacklevel=2,
        )
        uri = self.settings["FEED_URI"]
        # handle pathlib.Path objects
        uri = str(uri.absolute()) if isinstance(uri, Path) else str(uri)
        feed_options = {"format": self.settings["FEED_FORMAT"]}
        self.feeds[uri] = feed_complete_default_values_from_settings(
            feed_options, self.settings, uri
        )
        self.filters[uri] = self._load_filter(feed_options)
        self.processors[uri] = self._load_processor(feed_options)
    # End: Backward compatibility for FEED_URI and FEED_FORMAT settings

    # 'FEEDS' setting takes precedence over 'FEED_URI'
    for settings_uri, feed_options in self.settings.getdict("FEEDS").items():
        # handle pathlib.Path objects
        uri = (
            str(settings_uri.absolute())
            if isinstance(settings_uri, Path)
            else str(settings_uri)
        )
        self.feeds[uri] = feed_complete_default_values_from_settings(
            feed_options, self.settings, uri
        )
        self.filters[uri] = self._load_filter(feed_options)
        self.processors[uri] = self._load_processor(feed_options)

    self.storages: dict[str, type[FeedStorageProtocol]] = self._load_components(
        "FEED_STORAGES"
    )
    self.exporters: dict[str, type[BaseItemExporter]] = self._load_components(
        "FEED_EXPORTERS"
    )
    for uri, feed_options in self.feeds.items():
        if not self._storage_supported(uri, feed_options):
            raise NotConfigured
        if not self._settings_are_valid():
            raise NotConfigured
        if not self._exporter_supported(feed_options["format"]):
            raise NotConfigured

async def close_spider(self, spider: Spider) -> None:
    for slot in self.slots:
        self._schedule_slot_close(slot, spider)

    if self._pending_close_tasks:  # pragma: no branch
        if is_asyncio_available():
            await asyncio.wait(
                cast("list[asyncio.Task[None]]", list(self._pending_close_tasks))
            )
        else:
            await DeferredList(
                cast("list[Deferred[None]]", list(self._pending_close_tasks))
            )

    # Send FEED_EXPORTER_CLOSED signal
    await self.crawler.signals.send_catch_log_async(signals.feed_exporter_closed)

def _get_file(slot_: FeedSlot) -> IO[bytes]:
    assert slot_.file
    if isinstance(slot_.file, PostProcessingManager):
        slot_.file.close()
        return slot_.file.file
    return slot_.file

def item_scraped(self, item: Any, spider: Spider) -> None:
    slots = []
    for slot in self.slots:
        if not slot.filter.accepts(item):
            slots.append(
                slot
            )  # if slot doesn't accept item, continue with next slot
            continue

        processor = self.processors[slot.uri_template]
        for exported_item in processor(item) if processor else (item,):
            slot.start_exporting()
            assert slot.exporter
            try:
                slot.exporter.export_item(exported_item)
            except Exception as e:
                if sys.version_info >= (3, 11):
                    e.add_note(f"Item: {exported_item!r}")
                raise
            slot.itemcount += 1
            # create new slot for each slot with itemcount == FEED_EXPORT_BATCH_ITEM_COUNT and close the old one
            if (
                self.feeds[slot.uri_template]["batch_item_count"]
                and slot.itemcount
                >= self.feeds[slot.uri_template]["batch_item_count"]
            ):
                uri_params = self._get_uri_params(
                    spider, self.feeds[slot.uri_template]["uri_params"], slot
                )
                self._schedule_slot_close(slot, spider)
                slot = self._start_new_batch(  # noqa: PLW2901
                    batch_id=slot.batch_id + 1,
                    uri=apply_uri_params(slot.uri_template, uri_params),
                    feed_options=self.feeds[slot.uri_template],
                    spider=spider,
                    uri_template=slot.uri_template,
                )
        slots.append(slot)
    self.slots = slots

def _exporter_supported(self, format_: str) -> bool:
    if format_ in self.exporters:
        return True
    if format_:
        logger.error("Unknown feed format: %(format)s", {"format": format_})
    else:
        logger.error(
            "Feed format not set and it could not be inferred from the "
            "feed URI; set it explicitly with the 'format' key"
        )
    return False

def _storage_supported(self, uri: str, feed_options: dict[str, Any]) -> bool:
    scheme = urlparse(uri).scheme
    if scheme in self.storages or PureWindowsPath(uri).drive:
        try:
            self._get_storage(uri, feed_options)
            return True
        except NotConfigured as e:
            logger.error(
                "Disabled feed storage scheme: %(scheme)s. Reason: %(reason)s",
                {"scheme": scheme, "reason": str(e)},
            )
    else:
        logger.error("Unknown feed storage scheme: %(scheme)s", {"scheme": scheme})
    return False

def spider_closed(self, spider: Spider, reason: str) -> None:
    gc.collect()
    self.stats.set_value("memdebug/gc_garbage_count", len(gc.garbage))
    for cls, wdict in live_refs.items():
        if not wdict:
            continue
        self.stats.set_value(f"memdebug/live_refs/{cls.__name__}", len(wdict))

def __init__(
    self,
    item: Any = None,
    selector: Selector | None = None,
    response: TextResponse | None = None,
    parent: itemloaders.ItemLoader | None = None,
    **context: Any,
):
    if selector is None and response is not None:
        try:
            selector = self.default_selector_class(response)
        except AttributeError:
            selector = None
    context.update(response=response)
    super().__init__(item=item, selector=selector, parent=parent, **context)

def _collect(result: Any) -> list[Any]:
    if isinstance(result, (AsyncGenerator, CoroutineType)):
        if isinstance(result, CoroutineType):
            result.close()
        raise TypeError(
            "Callbacks that return a coroutine or an asynchronous generator "
            "must be defined with async def to be supported by contracts."
        )
    return list(arg_to_iter(result))

async def _collect_async(result: Any) -> list[Any]:
    if isinstance(result, AsyncGenerator):
        return await collect_asyncgen(result)
    if isinstance(result, CoroutineType):
        return await _collect_async(await result)
    return list(arg_to_iter(result))

def _run_hook(
    process: Callable[[Any], None],
    value: Any,
    testcase: TestCase,
    results: TestResult,
) -> None:
    try:
        results.startTest(testcase)
        process(value)
        results.stopTest(testcase)
    except AssertionError:
        results.addFailure(testcase, sys.exc_info())
    except Exception:
        results.addError(testcase, sys.exc_info())
    else:
        results.addSuccess(testcase)

def add_pre_hook(self, request: Request, results: TestResult) -> Request:
    if hasattr(self, "pre_process"):
        cb = request.callback
        assert cb is not None
        pre_process = self.pre_process
        testcase = self.testcase_pre

        if _is_async(cb):

            @wraps(cb)
            async def async_wrapper(
                response: Response, **cb_kwargs: Any
            ) -> list[Any]:
                _run_hook(pre_process, response, testcase, results)
                return await _collect_async(cb(response, **cb_kwargs))

            request.callback = async_wrapper
        else:

            @wraps(cb)
            def wrapper(response: Response, **cb_kwargs: Any) -> list[Any]:
                _run_hook(pre_process, response, testcase, results)
                return _collect(cb(response, **cb_kwargs))

            request.callback = wrapper

    return request

def add_post_hook(self, request: Request, results: TestResult) -> Request:
    if hasattr(self, "post_process"):
        cb = request.callback
        assert cb is not None
        post_process = self.post_process
        testcase = self.testcase_post

        if _is_async(cb):

            @wraps(cb)
            async def async_wrapper(
                response: Response, **cb_kwargs: Any
            ) -> list[Any]:
                output = await _collect_async(cb(response, **cb_kwargs))
                _run_hook(post_process, output, testcase, results)
                return output

            request.callback = async_wrapper
        else:

            @wraps(cb)
            def wrapper(response: Response, **cb_kwargs: Any) -> list[Any]:
                output = _collect(cb(response, **cb_kwargs))
                _run_hook(post_process, output, testcase, results)
                return output

            request.callback = wrapper

    return request

def __init__(self, contracts: Iterable[type[Contract]]):
    for contract in contracts:
        if (
            contract.add_pre_hook is not Contract.add_pre_hook
            or contract.add_post_hook is not Contract.add_post_hook
        ):
            warnings.warn(
                f"{contract.__module__}.{contract.__qualname__} overrides"
                " Contract.add_pre_hook() or Contract.add_post_hook(), which is"
                " deprecated. Define pre_process() or post_process() instead."
                " Contracts that override those methods do not support"
                " asynchronous callbacks.",
                ScrapyDeprecationWarning,
                stacklevel=2,
            )
        self.contracts[contract.name] = contract

def _iter_contract_batches(self, docstring: str) -> Iterator[list[tuple[str, str]]]:
    """Yield the ``(name, args)`` pairs of the lines of *docstring* that
    declare a registered contract, grouped into batches, one per blank line
    found after the first contract line.

    Lines that start with ``@`` but do not name a registered contract are
    ignored, so that docstrings may include unrelated content such as
    decorators in code examples.
    """
    batch: list[tuple[str, str]] = []
    for line_ in docstring.split("\n"):
        line = line_.strip()
        if not line:
            if batch:
                yield batch
                batch = []
            continue
        if not line.startswith("@"):
            continue
        m = re.match(r"@(\w+)\s*(.*)", line)
        if m is None:
            continue
        name, args = m.groups()
        if name in self.contracts:
            batch.append((name, args))
    if batch:
        yield batch

def tested_methods_from_spidercls(self, spidercls: type[Spider]) -> list[str]:
    return [
        key
        for key, value in getmembers(spidercls)
        if callable(value)
        and value.__doc__
        and any(self._iter_contract_batches(value.__doc__))

def from_spider(self, spider: Spider, results: TestResult) -> list[Request]:
    requests: list[Request] = []
    for method in self.tested_methods_from_spidercls(type(spider)):
        bound_method = getattr(spider, method)
        try:
            requests.extend(self.from_method(bound_method, results))
        except Exception:
            case = _create_testcase(bound_method, "contract")
            results.addError(case, sys.exc_info())

    return requests

def _clean_req(
    self, request: Request, method: Callable[..., Any], results: TestResult
) -> None:
    """stop the request from returning objects and records any errors"""

    cb = request.callback
    assert cb is not None

    if _is_async(cb):

        @wraps(cb)
        async def cb_wrapper(response: Response, **cb_kwargs: Any) -> None:
            try:
                await _collect_async(cb(response, **cb_kwargs))
            except Exception:
                case = _create_testcase(method, "callback")
                results.addError(case, sys.exc_info())

    else:

        @wraps(cb)
        def cb_wrapper(response: Response, **cb_kwargs: Any) -> None:
            try:
                _collect(cb(response, **cb_kwargs))
            except Exception:
                case = _create_testcase(method, "callback")
                results.addError(case, sys.exc_info())

    def eb_wrapper(failure: Failure) -> None:
        case = _create_testcase(method, "errback")
        exc_info = failure.type, failure.value, failure.getTracebackObject()
        results.addError(case, exc_info)  # type: ignore[arg-type]

    request.callback = cb_wrapper
    request.errback = eb_wrapper

def __init__(self, *args: Any, **kwargs: Any):
    super().__init__(*args, **kwargs)

    if len(self.args) not in {1, 2, 3}:
        raise ValueError(
            f"Incorrect argument quantity: expected 1, 2 or 3, got {len(self.args)}"
        )
    self.obj_name = self.args[0] or None
    self.obj_type_verifier = self.object_type_verifiers[self.obj_name]

    try:
        self.min_bound: float = int(self.args[1])
    except IndexError:
        self.min_bound = 1

    try:
        self.max_bound: float = int(self.args[2])
    except IndexError:
        self.max_bound = float("inf")

def post_process(self, output: list[Any]) -> None:
    occurrences = 0
    for x in output:
        if self.obj_type_verifier(x):
            occurrences += 1

    assertion = self.min_bound <= occurrences <= self.max_bound

    if not assertion:
        if self.min_bound == self.max_bound:
            expected = str(self.min_bound)
        else:
            expected = f"{self.min_bound}..{self.max_bound}"

        raise ContractFail(
            f"Returned {occurrences} {self.obj_name}, expected {expected}"

def post_process(self, output: list[Any]) -> None:
    for x in output:
        if is_item(x):
            missing = [arg for arg in self.args if arg not in ItemAdapter(x)]
            if missing:
                missing_fields = ", ".join(missing)
                raise ContractFail(f"Missing fields: {missing_fields}")

def _nons(tag: Any) -> Any:
    if (
        isinstance(tag, str)
        and tag[0] == "{"
        and tag[1 : len(XHTML_NAMESPACE) + 1] == XHTML_NAMESPACE
    ):
        return tag.split("}")[-1]
    return tag

def __init__(
    self,
    tag: str | Callable[[str], bool] = "a",
    attr: str | Callable[[str], bool] = "href",
    process: Callable[[Any], Any] | None = None,
    unique: bool = False,
    strip: bool = True,
    canonicalized: bool = False,
):
    # mypy doesn't infer types for operator.* and also for partial()
    self.scan_tag: Callable[[str], bool] = (
        tag
        if callable(tag)
        else cast("Callable[[str], bool]", partial(operator.eq, tag))
    )
    self.scan_attr: Callable[[str], bool] = (
        attr
        if callable(attr)
        else cast("Callable[[str], bool]", partial(operator.eq, attr))
    )
    self.process_attr: Callable[[Any], Any] = (
        process if callable(process) else _identity
    )
    self.unique: bool = unique
    self.strip: bool = strip
    self.link_key: Callable[[Link], str] = (
        cast("Callable[[Link], str]", operator.attrgetter("url"))
        if canonicalized
        else _canonicalize_link_url

def _iter_links(
    self, document: HtmlElement
) -> Iterable[tuple[HtmlElement, str, str]]:
    for el in document.iter(etree.Element):
        if not self.scan_tag(_nons(el.tag)):
            continue
        attribs = el.attrib
        for attrib in attribs:
            if not self.scan_attr(attrib):
                continue
            yield el, attrib, attribs[attrib]

def _extract_links(
    self,
    selector: Selector,
    response_url: str,
    response_encoding: str,
    base_url: str,
) -> list[Link]:
    links: list[Link] = []
    # hacky way to get the underlying lxml parsed document
    for el, _, attr_val in self._iter_links(selector.root):
        # pseudo lxml.html.HtmlElement.make_links_absolute(base_url)
        try:
            if self.strip:
                attr_val = strip_html5_whitespace(attr_val)  # noqa: PLW2901 this is intended
            attr_val = urljoin(base_url, attr_val)  # noqa: PLW2901
        except ValueError:
            continue  # skipping bogus links
        else:
            url = self.process_attr(attr_val)
            if url is None:
                continue
        try:
            url = safe_url_string(url, encoding=response_encoding)
        except ValueError:
            logger.debug(f"Skipping extraction of link with bad URL {url!r}")
            continue

        # to fix relative links after process_value
        url = urljoin(response_url, url)
        link = Link(
            url,
            _collect_string_content(el) or "",
            nofollow=rel_has_nofollow(el.get("rel")),
        )
        links.append(link)
    return self._deduplicate_if_needed(links)

def _link_allowed(self, link: Link) -> bool:
    parsed_url = urlparse(link.url)
    if self.schemes and parsed_url.scheme not in self.schemes:
        return False
    if self.allow_res and not _matches(link.url, self.allow_res):
        return False
    if self.deny_res and _matches(link.url, self.deny_res):
        return False
    if self.allow_domains and not url_is_from_any_domain(
        parsed_url, self.allow_domains
    ):
        return False
    if self.deny_domains and url_is_from_any_domain(parsed_url, self.deny_domains):
        return False
    if self.deny_extensions and url_has_any_extension(
        parsed_url, self.deny_extensions
    ):
        return False
    return not self.restrict_text or _matches(link.text, self.restrict_text)

def matches(self, url: str) -> bool:
    if self.allow_domains and not url_is_from_any_domain(url, self.allow_domains):
        return False
    if self.deny_domains and url_is_from_any_domain(url, self.deny_domains):
        return False

    allowed = (
        (regex.search(url) for regex in self.allow_res)
        if self.allow_res
        else [True]
    )
    denied = (regex.search(url) for regex in self.deny_res) if self.deny_res else ()
    return any(allowed) and not any(denied)

def _process_links(self, links: list[Link]) -> list[Link]:
    links = [x for x in links if self._link_allowed(x)]
    if self.canonicalize:
        for link in links:
            link.url = canonicalize_url(link.url)
        return self.link_extractor._process_links(links)
    return links

def extract_links(self, response: TextResponse) -> list[Link]:
    """Returns a list of :class:`~scrapy.link.Link` objects from the
    specified :class:`response <scrapy.http.Response>`.

    Only links that match the settings passed to the ``__init__`` method of
    the link extractor are returned.

    Duplicate links are omitted if the ``unique`` attribute is set to ``True``,
    otherwise they are returned.
    """
    base_url = get_base_url(response)
    if self.restrict_xpaths:
        docs = [
            subdoc for x in self.restrict_xpaths for subdoc in response.xpath(x)
        ]
    else:
        docs = [response.selector]
    all_links = []
    for doc in docs:
        links = self._extract_links(doc, response.url, response.encoding, base_url)
        all_links.extend(self._process_links(links))
    if self.link_extractor.unique and len(docs) > 1:
        return unique_list(all_links, key=self.link_extractor.link_key)
    return all_links

def normvalue(self, value: _RawValue | Iterable[_RawValue]) -> list[bytes]:
    """Normalize values to bytes"""
    _value: Iterable[_RawValue]
    if value is None:
        _value = []
    elif isinstance(value, (str, bytes)):
        _value = [value]
    elif hasattr(value, "__iter__"):
        _value = value
    else:
        _value = [value]

    return [self._tobytes(x) for x in _value]

def _tobytes(self, x: _RawValue) -> bytes:
    if isinstance(x, bytes):
        return x
    if isinstance(x, str):
        return x.encode(self.encoding)
    if isinstance(x, int):
        return str(x).encode(self.encoding)
    raise TypeError(f"Unsupported value type: {type(x)}")

def getlist(
    self, key: str | bytes, def_val: _RawValue | Iterable[_RawValue] | None = None
) -> list[bytes]:
    try:
        return cast("list[bytes]", dict.__getitem__(self, self.normkey(key)))
    except KeyError:
        if def_val is not None:
            return self.normvalue(def_val)
        return []

def potential_domain_matches(domain: str) -> list[str]:
    """Potential domain matches for a cookie

    >>> potential_domain_matches('www.example.com')
    ['www.example.com', 'example.com', '.www.example.com', '.example.com']

    """
    matches = [domain]
    try:
        start = domain.index(".") + 1
        end = domain.rindex(".")
        while start < end:
            matches.append(domain[start:])
            start = domain.index(".", start) + 1
    except ValueError:
        pass
    return matches + ["." + d for d in matches]

def add_cookie_header(self, request: Request) -> None:
    wreq = WrappedRequest(request)
    self.policy._now = self.jar._now = int(time.time())  # type: ignore[attr-defined]

    # the cookiejar implementation iterates through all domains
    # instead we restrict to potential matches on the domain
    req_host = urlparse_cached(request).hostname
    if not req_host:
        return

    if not IPV4_RE.search(req_host):
        hosts = potential_domain_matches(req_host)
        if "." not in req_host:
            hosts += potential_domain_matches(req_host + ".local")
    else:
        hosts = [req_host, "." + req_host]

    cookies = []
    for host in hosts:
        if host in self.jar._cookies:  # type: ignore[attr-defined]
            cookies.extend(self.jar._cookies_for_domain(host, wreq))  # type: ignore[attr-defined]

    attrs = self.jar._cookie_attrs(cookies)  # type: ignore[attr-defined]
    if attrs and not wreq.has_header("Cookie"):
        wreq.add_unredirected_header("Cookie", "; ".join(attrs))

    self.processed += 1
    if self.processed % self.check_expired_frequency == 0:
        # This is still quite inefficient for large number of cookies
        self.jar.clear_expired_cookies()

def header_items(self) -> list[tuple[str, list[str]]]:
    return [
        (
            to_unicode(k, errors="replace"),
            [to_unicode(x, errors="replace") for x in v],
        )
        for k, v in self.request.headers.items()

def _get_form_url(form: FormElement, url: str | None) -> str:
    assert form.base_url is not None  # typing
    if url is None:
        action = form.get("action")
        if action is None:
            return form.base_url
        return urljoin(form.base_url, strip_html5_whitespace(action))
    return urljoin(form.base_url, url)

def _urlencode(seq: Iterable[FormdataKVType], enc: str) -> str:
    values = [
        (to_bytes(k, enc), to_bytes(v, enc))
        for k, vs in seq
        for v in (vs if is_listlike(vs) else [cast("str", vs)])
    ]
    return urlencode(values, doseq=True)

def _get_form(
    response: TextResponse,
    formname: str | None,
    formid: str | None,
    formnumber: int,
    formxpath: str | None,
) -> FormElement:
    """Find the wanted form element within the given response."""
    root = response.selector.root
    forms = root.xpath("//form")
    if not forms:
        raise ValueError(f"No <form> element found in {response}")

    if formname is not None:
        f = root.xpath(f'//form[@name="{formname}"]')
        if f:
            return cast("FormElement", f[0])

    if formid is not None:
        f = root.xpath(f'//form[@id="{formid}"]')
        if f:
            return cast("FormElement", f[0])

    # Get form element from xpath, if not found, go up
    if formxpath is not None:
        nodes = root.xpath(formxpath)
        if nodes:
            el = nodes[0]
            while True:
                if el.tag == "form":
                    return cast("FormElement", el)
                el = el.getparent()
                if el is None:
                    break
        raise ValueError(f"No <form> element found with {formxpath}")

    # If we get here, it means that either formname was None or invalid
    try:
        form = forms[formnumber]
    except IndexError:
        raise IndexError(f"Form number {formnumber} not found in {response}") from None
    return cast("FormElement", form)

def _select_value(
    ele: SelectElement, n: str | None, v: str | MultipleSelectOptions | None
) -> tuple[str | None, str | MultipleSelectOptions | None]:
    multiple = ele.multiple
    if v is None and not multiple:
        # Match browser behaviour on simple select tag without options selected
        # And for select tags without options
        o = ele.value_options
        return (n, o[0]) if o else (None, None)
    return n, v

def _get_clickable(
    clickdata: dict[str, str | int] | None, form: FormElement
) -> tuple[str, str] | None:
    """
    Returns the clickable element specified in clickdata,
    if the latter is given. If not, it returns the first
    clickable element found
    """
    clickables = list(
        form.xpath(
            'descendant::input[re:test(@type, "^(submit|image)$", "i")]'
            '|descendant::button[not(@type) or re:test(@type, "^submit$", "i")]',
            namespaces={"re": "http://exslt.org/regular-expressions"},
        )
    )
    if not clickables:
        return None

    # If we don't have clickdata, we just use the first clickable element
    if clickdata is None:
        el = clickables[0]
        return (el.get("name"), el.get("value") or "")

    # If clickdata is given, we compare it to the clickable elements to find a
    # match. We first look to see if the number is specified in clickdata,
    # because that uniquely identifies the element
    nr = clickdata.get("nr", None)
    if nr is not None:
        assert isinstance(nr, int)
        try:
            el = list(form.inputs)[nr]
        except IndexError:
            pass
        else:
            return (cast("str", el.get("name")), el.get("value") or "")

    # We didn't find it, so now we build an XPath expression out of the other
    # arguments, because they can be used as such
    xpath = ".//*" + "".join(f'[@{k}="{v}"]' for k, v in clickdata.items())
    el = form.xpath(xpath)
    if len(el) == 1:
        return (el[0].get("name"), el[0].get("value") or "")
    if len(el) > 1:
        raise ValueError(
            f"Multiple elements found ({el!r}) matching the "
            f"criteria in clickdata: {clickdata!r}"
        )
    raise ValueError(f"No clickable element matching clickdata: {clickdata!r}")

def __init__(
    self, *args: Any, formdata: FormdataType = None, **kwargs: Any
) -> None:
    if formdata and kwargs.get("method") is None:
        kwargs["method"] = "POST"

    super().__init__(*args, **kwargs)

    if formdata:
        items = formdata.items() if isinstance(formdata, Mapping) else formdata
        form_query_str = _urlencode(items, self.encoding)
        if self.method == "POST":
            self.headers.setdefault(
                b"Content-Type", b"application/x-www-form-urlencoded"
            )
            self._set_body(form_query_str)
        else:
            self._set_url(
                urlunsplit(urlsplit(self.url)._replace(query=form_query_str))

def __init__(self, *args: Any, encoding: str | None = None, **kwargs: Any):
    if "body" not in kwargs and "params" in kwargs:
        kw = {k: kwargs.pop(k) for k in DUMPS_ARGS if k in kwargs}
        kwargs["body"] = xmlrpclib.dumps(**kw)

    # spec defines that requests must use POST method
    kwargs.setdefault("method", "POST")

    # xmlrpc query multiples times over the same url
    kwargs.setdefault("dont_filter", True)

    # restore encoding
    if encoding is not None:
        kwargs["encoding"] = encoding

    super().__init__(*args, **kwargs)
    self.headers.setdefault("Content-Type", "text/xml")

def _set_url(self, url: str) -> None:
    if not isinstance(url, str):
        raise TypeError(f"Request url must be str, got {type(url).__name__}")

    if self._url_is_verbatim():
        self._url = url
    else:
        self._url = safe_url_string(url, self.encoding)

    if (
        "://" not in self._url
        and not self._url.startswith("about:")
        and not self._url.startswith("data:")
    ):
        raise ValueError(f"Missing scheme in request url: {self._url}")

def headers(
    self,
    value: Mapping[str, Any]
    | Mapping[bytes, Any]
    | Iterable[tuple[str | bytes, Any]]
    | None,
) -> None:
    if isinstance(value, Headers):
        self._headers = value
    else:
        self._headers = (
            Headers(value, encoding=self.encoding) if value is not None else None

def replace(
    self, *args: Any, cls: type[Request] | None = None, **kwargs: Any
) -> Request:
    """Create a new Request with the same attributes except for those given new values"""
    for x in self.attributes:
        kwargs.setdefault(x, getattr(self, x))
    if cls is None:
        cls = self.__class__
    return cls(*args, **kwargs)

def to_dict(self, *, spider: scrapy.Spider | None = None) -> dict[str, Any]:
    """Return a dictionary containing the Request's data.

    Use :func:`~scrapy.utils.request.request_from_dict` to convert back into a :class:`~scrapy.Request` object.

    If a spider is given, this method will try to find out the name of the spider methods used as callback
    and errback and include them in the output dict, raising an exception if they cannot be found.
    """
    d = {
        "url": self.url,  # urls are safe (safe_string_url)
        "callback": (
            _find_method(spider, self.callback)
            if callable(self.callback)
            else self.callback
        ),
        "errback": (
            _find_method(spider, self.errback)
            if callable(self.errback)
            else self.errback
        ),
        "headers": dict(self.headers),
    }
    for attr in self.attributes:
        d.setdefault(attr, getattr(self, attr))
    if type(self) is not Request:  # pylint: disable=unidiomatic-typecheck
        d["_class"] = self.__module__ + "." + self.__class__.__name__
    return d

def __init__(
    self, *args: Any, dumps_kwargs: dict[str, Any] | None = None, **kwargs: Any
) -> None:
    dumps_kwargs = copy.deepcopy(dumps_kwargs) if dumps_kwargs is not None else {}
    dumps_kwargs.setdefault("sort_keys", True)
    self._dumps_kwargs: dict[str, Any] = dumps_kwargs

    body_passed = kwargs.get("body") is not None
    data: Any = kwargs.pop("data", None)
    data_passed: bool = data is not None

    if body_passed and data_passed:
        warnings.warn(
            "Both body and data passed. data will be ignored", stacklevel=2
        )
    elif not body_passed and data_passed:
        kwargs["body"] = self._dumps(data)
        if "method" not in kwargs:
            kwargs["method"] = "POST"

    super().__init__(*args, **kwargs)
    self.headers.setdefault("Content-Type", "application/json")
    self.headers.setdefault(
        "Accept", "application/json, text/javascript, */*; q=0.01"

def replace(
    self, *args: Any, cls: type[Request] | None = None, **kwargs: Any
) -> Request:
    body_passed = kwargs.get("body") is not None
    data: Any = kwargs.pop("data", None)
    data_passed: bool = data is not None

    if body_passed and data_passed:
        warnings.warn(
            "Both body and data passed. data will be ignored", stacklevel=2
        )
    elif not body_passed and data_passed:
        kwargs["body"] = self._dumps(data)

    return super().replace(*args, cls=cls, **kwargs)

def _set_body(self, body: bytes | None) -> None:
    if body is None:
        self._body = b""
    elif not isinstance(body, bytes):
        raise TypeError(
            "Response body must be bytes. "
            "If you want to pass unicode body use TextResponse "
            "or HtmlResponse."
        )
    else:
        self._body = body

def headers(
    self,
    value: Mapping[str, Any]
    | Mapping[bytes, Any]
    | Iterable[tuple[str | bytes, Any]]
    | None,
) -> None:
    if isinstance(value, Headers):
        self._headers = value
    else:
        self._headers = Headers(value) if value is not None else None

def replace(
    self, *args: Any, cls: type[Response] | None = None, **kwargs: Any
) -> Response:
    """Create a new Response with the same attributes except for those given new values"""
    for x in self.attributes:
        kwargs.setdefault(x, getattr(self, x))
    if cls is None:
        cls = self.__class__
    return cls(*args, **kwargs)

def from_dict(cls, d: dict[str, Any]) -> Self:
    """Return a response built from the *d* dict, as returned by
    :meth:`to_dict`.

    .. versionadded:: 2.19.0
    """
    return cls(**{key: value for key, value in d.items() if key != "_class"})

def _url_from_selector(sel: parsel.Selector) -> str:
    if isinstance(sel.root, str):
        # e.g. ::attr(href) result
        return strip_html5_whitespace(sel.root)
    if not hasattr(sel.root, "tag"):
        raise _InvalidSelector(f"Unsupported selector: {sel}")
    if sel.root.tag not in {"a", "link"}:
        raise _InvalidSelector(
            f"Only <a> and <link> elements are supported; got <{sel.root.tag}>"
        )
    href = sel.root.get("href")
    if href is None:
        raise _InvalidSelector(f"<{sel.root.tag}> element has no href attribute: {sel}")
    return strip_html5_whitespace(href)

def _set_body(self, body: str | bytes | None) -> None:
    self._body: bytes = b""  # used by encoding detection
    if isinstance(body, str):
        if self._encoding is None:
            raise TypeError(
                "Cannot convert unicode body - "
                f"{type(self).__name__} has no encoding"
            )
        self._body = body.encode(self._encoding)
        # Keep body as text only if decoding _body gives it back
        # unchanged. html_to_unicode() may resolve the encoding to
        # another codec (e.g. latin-1 to cp1252) and strips a BOM.
        if resolve_encoding(self._encoding) == "utf-8" and not body.startswith(
            "\ufeff"
        ):
            self._cached_ubody = body
    else:
        super()._set_body(body)

def _declared_encoding(self) -> str | None:
    return (
        self._encoding
        or self._bom_encoding()
        or self._headers_encoding()
        or self._body_declared_encoding()

def _auto_detect_fun(self, text: bytes) -> str | None:
    for enc in (self._DEFAULT_ENCODING, "utf-8"):
        try:
            text.decode(enc)
        except UnicodeError:
            continue
        return resolve_encoding(enc)
    match = from_bytes(text).best()
    return resolve_encoding(match.encoding) if match else None

def iterate_spider_output(
    result: Any,
) -> Iterable[Any] | AsyncGenerator[_T] | Deferred[_T]:
    if inspect.isasyncgen(result):
        return cast("AsyncGenerator[_T]", result)
    d: Deferred[_T] = deferred_from_coro(result)
    if inspect.iscoroutine(result):
        return d.addCallback(iterate_spider_output)
    return arg_to_iter(d)

def iter_spider_classes(module: ModuleType) -> Iterable[type[Spider]]:
    """Return an iterator over all spider classes defined in the given module
    that can be instantiated (i.e. which have name)
    """
    for obj in vars(module).values():
        if (
            inspect.isclass(obj)
            and issubclass(obj, Spider)
            and obj.__module__ == module.__name__
            and getattr(obj, "name", None)
        ):
            yield obj

def spidercls_for_request(
    spider_loader: SpiderLoaderProtocol,
    request: Request,
    default_spidercls: type[Spider] | None = None,
    log_none: bool = False,
    log_multiple: bool = False,
) -> type[Spider] | None:
    """Return a spider class that handles the given Request.

    This will look for the spiders that can handle the given request (using
    the spider loader) and return a Spider class if (and only if) there is
    only one Spider able to handle the Request.

    If multiple spiders (or no spider) are found, it will return the
    default_spidercls passed. It can optionally log if multiple or no spiders
    are found.
    """
    snames = spider_loader.find_by_request(request)
    if len(snames) == 1:
        return spider_loader.load(snames[0])

    if len(snames) > 1 and log_multiple:
        logger.error(
            "More than one spider can handle: %(request)s - %(snames)s",
            {"request": request, "snames": ", ".join(snames)},
        )

    if len(snames) == 0 and log_none:
        logger.error(
            "Unable to find spider that handles: %(request)s", {"request": request}
        )

    return default_spidercls

def request_from_dict(d: dict[str, Any], *, spider: Spider | None = None) -> Request:
    """Create a :class:`~scrapy.Request` object from a dict.

    If a spider is given, it will try to resolve the callbacks looking at the
    spider for methods with the same name.
    """
    request_cls: type[Request] = load_object(d["_class"]) if "_class" in d else Request
    kwargs = {key: value for key, value in d.items() if key in request_cls.attributes}
    if d.get("callback") and spider:
        kwargs["callback"] = _get_method(spider, d["callback"])
    if d.get("errback") and spider:
        kwargs["errback"] = _get_method(spider, d["errback"])
    return request_cls(**kwargs)

def _decode_cookie(cookie: VerboseCookie, request: Request) -> dict[str, str] | None:
    """Return a dict with non-flag verbose cookie values converted to strings.

    ``name``, ``value``, ``path``, ``domain`` are included, ``secure`` isn't.
    """

    decoded = {}
    for key in ("name", "value", "path", "domain"):
        value = cookie.get(key)
        if value is None:
            if key in {"name", "value"}:
                logger.warning(
                    f"Invalid cookie found in request {request}:"
                    f" {cookie} ('{key}' is missing)"
                )
                return None
            continue
        if isinstance(value, (bool, float, int, str)):
            decoded[key] = str(value)
        else:
            assert isinstance(value, bytes)
            try:
                decoded[key] = value.decode("utf8")
            except UnicodeDecodeError:
                logger.warning(
                    f"Non UTF-8 encoded cookie found in request {request}: {cookie}",
                )
                decoded[key] = value.decode("latin1", errors="replace")
    return decoded

def to_unicode(
    text: str | bytes, encoding: str | None = None, errors: str = "strict"
) -> str:
    """Return the unicode representation of a bytes object ``text``. If
    ``text`` is already an unicode object, return it as-is."""
    if isinstance(text, str):
        return text
    if not isinstance(text, (bytes, str)):
        raise TypeError(
            f"to_unicode must receive a bytes or str object, got {type(text).__name__}"
        )
    if encoding is None:
        encoding = "utf-8"
    return text.decode(encoding, errors)

def to_bytes(
    text: str | bytes, encoding: str | None = None, errors: str = "strict"
) -> bytes:
    """Return the binary representation of ``text``. If ``text``
    is already a bytes object, return it as-is."""
    if isinstance(text, bytes):
        return text
    if not isinstance(text, str):
        raise TypeError(
            f"to_bytes must receive a str or bytes object, got {type(text).__name__}"
        )
    if encoding is None:
        encoding = "utf-8"
    return text.encode(encoding, errors)

def _chunk_iter(
    text: str, chunk_size: int
) -> Iterable[tuple[str, int]]:  # pragma: no cover
    offset = len(text)
    while True:
        offset -= chunk_size * 1024
        if offset <= 0:
            break
        yield (text[offset:], offset)
    yield (text, 0)

def binary_is_text(data: bytes) -> bool:
    """Returns ``True`` if the given ``data`` argument (a ``bytes`` object)
    does not contain unprintable control characters.
    """
    if not isinstance(data, bytes):
        raise TypeError(f"data must be bytes, got '{type(data).__name__}'")
    return all(c not in _BINARYCHARS for c in data)

def get_func_args_dict(
    func: Callable[..., Any], stripself: bool = False
) -> Mapping[str, inspect.Parameter]:
    """Return the argument dict of a callable object.

    Annotations are not evaluated, so on Python 3.14 and later the ``annotation``
    attribute of the returned parameters may be a ``ForwardRef`` instead of the
    resolved type.

    .. versionadded:: 2.14
    """
    if not callable(func):
        raise TypeError(f"func must be callable, got '{type(func).__name__}'")

    args: Mapping[str, inspect.Parameter]
    try:
        sig = _signature(func)
    except ValueError:
        return {}

    if isinstance(func, partial) and func.keywords:
        # The signature of a partial already omits the parameters bound to
        # positional arguments, but it keeps those bound to keyword arguments,
        # turned into keyword-only parameters with a default.
        args = {
            name: param
            for name, param in sig.parameters.items()
            if name not in func.keywords
        }
    else:
        args = sig.parameters

    if stripself and args and "self" in args:
        args = {k: v for k, v in args.items() if k != "self"}
    return args

def without_none_values(
    iterable: Mapping[_KT, _VT] | Iterable[_KT],
) -> dict[_KT, _VT] | Iterable[_KT]:
    """Return a copy of ``iterable`` with all ``None`` entries removed.

    If ``iterable`` is a mapping, return a dictionary where all pairs that have
    value ``None`` have been removed.
    """
    if isinstance(iterable, Mapping):
        return {k: v for k, v in iterable.items() if v is not None}
    # the iterable __init__ must take another iterable
    return type(iterable)(v for v in iterable if v is not None)  # type: ignore[call-arg]

async def _async_chain(
    *iterables: Iterable[_T] | AsyncIterator[_T],
) -> AsyncIterator[_T]:
    for it in iterables:
        async for o in as_async_generator(it):
            yield o

def _looks_like_import_path(value: str) -> bool:
    """Return True if **value** looks like a valid Python import path or False
    otherwise."""
    if not value:
        return False
    if any(c.isspace() for c in value):
        return False
    allowed_chars = set(
        "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_."
    )
    if any(c not in allowed_chars for c in value):
        return False
    if value[0] == "." or value[-1] == ".":
        return False
    parts = value.split(".")
    if any(part == "" for part in parts):
        return False
    return all(part.isidentifier() for part in parts)

def closest_scrapy_cfg(
    path: str | os.PathLike[str] = ".",
    prevpath: str | os.PathLike[str] | None = None,
) -> str:
    """Return the path to the closest scrapy.cfg file by traversing the current
    directory and its parents
    """
    if prevpath is not None and str(path) == str(prevpath):
        return ""
    path = Path(path).resolve()
    cfgfile = path / "scrapy.cfg"
    if cfgfile.exists():
        return str(cfgfile)
    return closest_scrapy_cfg(path.parent, path)

def init_env(project: str = "default", set_syspath: bool = True) -> None:
    """Initialize environment to use command-line tool from inside a project
    dir. This sets the Scrapy settings module and modifies the Python path to
    be able to locate the project module.
    """
    cfg = get_config()
    if "SCRAPY_SETTINGS_MODULE" not in os.environ and cfg.has_option(
        "settings", project
    ):
        os.environ["SCRAPY_SETTINGS_MODULE"] = cfg.get("settings", project)
    closest = closest_scrapy_cfg()
    if closest:
        projdir = str(Path(closest).parent)
        if set_syspath and projdir not in sys.path:
            sys.path.append(projdir)

def get_sources(use_closest: bool = True) -> list[str]:
    xdg_config_home = (
        os.environ.get("XDG_CONFIG_HOME") or Path("~/.config").expanduser()
    )
    sources = [
        "/etc/scrapy.cfg",
        r"c:\scrapy\scrapy.cfg",
        str(Path(xdg_config_home) / "scrapy.cfg"),
        str(Path("~/.scrapy.cfg").expanduser()),
    ]
    if use_closest:
        sources.append(closest_scrapy_cfg())
    return sources

def feed_process_params_from_cli(
    settings: BaseSettings,
    output: list[str],
    *,
    overwrite_output: list[str] | None = None,
) -> dict[str, dict[str, Any]]:
    """
    Receives feed export params (from the 'crawl' or 'runspider' commands),
    checks for inconsistencies in their quantities and returns a dictionary
    suitable to be used as the FEEDS setting.
    """
    valid_output_formats: Iterable[str] = without_none_values(
        cast("dict[str, str]", settings.getwithbase("FEED_EXPORTERS"))
    ).keys()

    def check_valid_format(output_format: str) -> None:
        if output_format not in valid_output_formats:
            raise UsageError(
                f"Unrecognized output format '{output_format}'. "
                f"Set a supported one ({tuple(valid_output_formats)}) "
                "after a colon at the end of the output URI (i.e. -o/-O "
                "<URI>:<FORMAT>) or as a file extension."
            )

    overwrite = False
    if overwrite_output:
        if output:
            raise UsageError(
                "Please use only one of -o/--output and -O/--overwrite-output"
            )
        output = overwrite_output
        overwrite = True

    result: dict[str, dict[str, Any]] = {}
    for element in output:
        try:
            feed_uri, feed_format = element.rsplit(":", 1)
            check_valid_format(feed_format)
        except (ValueError, UsageError):
            feed_uri = element
            feed_format = Path(element).suffix.replace(".", "")
        else:
            if feed_uri == "-":
                feed_uri = "stdout:"
        check_valid_format(feed_format)
        result[feed_uri] = {"format": feed_format}
        if overwrite:
            result[feed_uri]["overwrite"] = True

    # FEEDS setting should take precedence over the matching CLI options
    result.update(settings.getdict("FEEDS"))

    return result

def _job_dir(settings: BaseSettings) -> str | None:
    path: str | None = settings["JOBDIR"]
    if not path:
        return None
    if not Path(path).exists():
        Path(path).mkdir(parents=True)
    return path

def _normalize_stop_mode(mode: _StopMode, *, allow_force: bool = True) -> _StopMode:
    if mode not in _STOP_MODE_PRIORITY:
        raise ValueError(
            f"Unknown stop mode {mode!r}. Expected one of: graceful, fast, force"
        )
    if mode == "force" and not allow_force:
        raise ValueError("The force stop mode is not supported in this context")
    return mode

def _call(self) -> None:
    """Execute the function."""
    try:
        result = self._func(*self._args, **self._kwargs)
    except Exception:
        logger.exception("Error calling the AsyncioLoopingCall function")
        self.stop()
    else:
        if isinstance(result, (Coroutine, Deferred)):
            self.stop()
            raise TypeError(
                "The AsyncioLoopingCall function must not return a coroutine or a Deferred"

def cancel(self) -> None:
    """Cancel the underlying delayed call.

    Does nothing if the delayed call was already called or cancelled.
    """
    if self._timer_handle:
        self._timer_handle.cancel()
        self._timer_handle = None
    elif self._delayed_call and self._delayed_call.active():
        self._delayed_call.cancel()
        self._delayed_call = None

def inside_project() -> bool:
    scrapy_module = os.environ.get(ENVVAR)
    if scrapy_module:
        try:
            import_module(scrapy_module)
        except ImportError as exc:
            warnings.warn(
                f"Cannot import scrapy settings module {scrapy_module}: {exc}",
                stacklevel=2,
            )
        else:
            return True
    return bool(closest_scrapy_cfg())

def project_data_dir(project: str = "default") -> str:
    """Return the current project data dir, creating it if it doesn't exist"""
    if not inside_project():
        raise NotConfigured("Not inside a project")
    cfg = get_config()
    if cfg.has_option(DATADIR_CFG_SECTION, project):
        d = Path(cfg.get(DATADIR_CFG_SECTION, project))
    else:
        scrapy_cfg = closest_scrapy_cfg()
        if not scrapy_cfg:
            raise NotConfigured(
                "Unable to find scrapy.cfg file to infer project data dir"
            )
        d = (Path(scrapy_cfg).parent / ".scrapy").resolve()
    if not d.exists():
        d.mkdir(parents=True)
    return str(d)

def data_path(path: str | os.PathLike[str], createdir: bool = False) -> str:
    """
    Return the given path joined with the .scrapy data directory.
    If given an absolute path, return it unmodified.
    """
    path_obj = Path(path)
    if not path_obj.is_absolute():
        if inside_project():
            path_obj = Path(project_data_dir(), path)
        else:
            path_obj = Path(".scrapy", path)
    if createdir and not path_obj.exists():
        path_obj.mkdir(parents=True)
    return str(path_obj)

def _getarg(
    request: Request, name: bytes, default: Any = None, type_: type = str
) -> Any:
    assert request.args is not None
    return type_(request.args[name][0]) if name in request.args else default

def format_live_refs(
    ignore: type[Any] | tuple[type[Any], ...] = NoneType,
) -> str:
    """Return a tabular representation of tracked objects"""
    s = "Live References\n\n"
    now_ns = monotonic_ns()
    for cls, wdict in sorted(live_refs.items(), key=lambda x: x[0].__name__):
        if not wdict:
            continue
        if issubclass(cls, ignore):
            continue
        oldest_ns = min(wdict.values())
        s += f"{cls.__name__:<30} {len(wdict):6}   oldest: {int((now_ns - oldest_ns) // 1e9)}s ago\n"
    return s

def get_oldest(class_name: str) -> Any:
    """Return the oldest object alive with the given class name, or ``None`` if
    none is found. Use :func:`print_live_refs` first to get a list of all
    tracked live objects per class name."""
    for cls, wdict in live_refs.items():
        if cls.__name__ == class_name:
            if not wdict:
                break
            return min(wdict.items(), key=itemgetter(1))[0]
    return None

def iter_all(class_name: str) -> Iterable[Any]:
    """Return an iterator over all objects alive with the given class name. Use
    :func:`print_live_refs` first to get a list of all tracked live objects per
    class name."""
    for cls, wdict in live_refs.items():
        if cls.__name__ == class_name:
            return wdict.keys()
    return ()

def listen_tcp(portrange: list[int], host: str, factory: ServerFactory) -> Port:
    """Like reactor.listenTCP but tries different ports in a range."""
    from twisted.internet import reactor

    if len(portrange) > 2:
        raise ValueError(f"invalid portrange: {portrange}")
    if len(portrange) == 2 and portrange[0] > portrange[1]:
        raise ValueError(f"invalid portrange: {portrange}")
    if not portrange:
        return reactor.listenTCP(0, factory, interface=host)  # type: ignore[no-any-return]
    for x in range(portrange[0], portrange[-1]):
        try:
            return reactor.listenTCP(x, factory, interface=host)  # type: ignore[no-any-return]
        except error.CannotListenError:
            pass
    # The last port of the range is tried outside the loop so that its
    # CannotListenError propagates to the caller.
    return reactor.listenTCP(portrange[-1], factory, interface=host)  # type: ignore[no-any-return]

def tty_supports_color() -> bool:
    if sys.platform != "win32":
        return True

    if parse_version(platform.version()) < parse_version("10.0.14393"):
        return True

    # Windows >= 10.0.14393 interprets ANSI escape sequences providing terminal
    # processing is enabled.
    return _enable_windows_terminal_processing()

def _colorize(text: str, colorize: bool = True) -> str:
    # pylint: disable=no-name-in-module
    if not colorize or not sys.stdout.isatty() or not tty_supports_color():
        return text
    try:
        from pygments import highlight  # noqa: PLC0415
    except ImportError:
        return text
    from pygments.formatters import TerminalFormatter  # noqa: PLC0415
    from pygments.lexers import PythonLexer  # noqa: PLC0415

    return highlight(text, PythonLexer(), TerminalFormatter())

def response_from_dict(d: dict[str, Any]) -> Response:
    """Return a response built from the *d* dict, as returned by
    :meth:`Response.to_dict() <scrapy.http.Response.to_dict>`.

    .. versionadded:: 2.19.0

    If *d* does not indicate a response class, e.g. because it comes from a
    plain :class:`~scrapy.http.Response` object or predates :meth:`~scrapy.http.Response.to_dict`,
    the class is guessed with :attr:`~scrapy.responsetypes.responsetypes`.
    """
    # Imported here to avoid a circular import.
    from scrapy.responsetypes import responsetypes  # noqa: PLC0415

    d = {**d, "headers": Headers(d.get("headers") or {})}
    response_cls: type[Response] = (
        load_object(d["_class"])
        if "_class" in d
        else responsetypes.from_args(
            headers=d["headers"], url=d["url"], body=d.get("body")
        )
    )
    return response_cls.from_dict(d)

def arg_to_iter(arg: Any) -> Iterable[Any]:
    """Convert an argument to an iterable. The argument can be a None, single
    value, or an iterable.

    Exception: if arg is a dict, [arg] will be returned
    """
    if arg is None:
        return ()
    if not isinstance(arg, _ITERABLE_SINGLE_VALUES) and hasattr(arg, "__iter__"):
        return cast("Iterable[Any]", arg)
    return [arg]

def load_object(path: str | Callable[..., Any]) -> Any:
    """Load an object given its absolute object path, and return it.

    The object can be the import path of a class, function, variable or an
    instance, e.g. 'scrapy.downloadermiddlewares.redirect.RedirectMiddleware'.

    If ``path`` is not a string, but is a callable object, such as a class or
    a function, then return it as is.
    """

    if not isinstance(path, str):
        if callable(path):
            return path
        raise TypeError(
            f"Unexpected argument type, expected string or object, got: {type(path)}"
        )

    try:
        dot = path.rindex(".")
    except ValueError:
        raise ValueError(f"Error loading object '{path}': not a full path") from None

    module, name = path[:dot], path[dot + 1 :]
    mod = import_module(module)

    try:
        obj = getattr(mod, name)
    except AttributeError:
        raise NameError(
            f"Module '{module}' doesn't define any object named '{name}'"
        ) from None

    return obj

def set_environ(**kwargs: str) -> Iterator[None]:
    """Temporarily set environment variables inside the context manager and
    fully restore previous environment afterwards
    """

    original_env = {k: os.environ.get(k) for k in kwargs}
    os.environ.update(kwargs)
    try:
        yield
    finally:
        for k, v in original_env.items():
            if v is None:
                del os.environ[k]
            else:
                os.environ[k] = v

def is_generator_with_return_value(callable: Callable[..., Any]) -> bool:  # noqa: A002
    """
    Returns True if a callable is a generator function which includes a
    'return' statement with a value different than None, False otherwise
    """
    if callable in _generator_callbacks_cache:
        return bool(_generator_callbacks_cache[callable])

    if inspect.isgeneratorfunction(callable):
        func = callable
        while isinstance(func, partial):
            func = func.func

        src = inspect.getsource(func)
        pattern = re.compile(r"(^[\t ]+)")
        code = pattern.sub("", src)

        match = pattern.match(src)  # finds indentation
        if match:
            code = re.sub(f"\n{match.group(0)}", "\n", code)  # remove indentation

        tree = ast.parse(code)
        for node in walk_callable(tree):
            if isinstance(node, ast.Return) and not _returns_none(node):
                _generator_callbacks_cache[callable] = True
                return bool(_generator_callbacks_cache[callable])

    _generator_callbacks_cache[callable] = False
    return bool(_generator_callbacks_cache[callable])

def iter_errback(
    iterable: Iterable[_T],
    errback: Callable[Concatenate[Failure, _P], Any],
    *a: _P.args,
    **kw: _P.kwargs,
) -> Iterable[_T]:
    """Wrap an iterable calling an errback if an error is caught while
    iterating it.
    """
    it = iter(iterable)
    while True:
        try:
            yield next(it)
        except StopIteration:
            break
        except Exception:
            errback(failure.Failure(), *a, **kw)

def deferred_from_coro(o: Awaitable[_T] | _T2) -> Deferred[_T] | _T2:
    """Convert a coroutine or other awaitable object into a Deferred,
    or return the object as is if it isn't a coroutine."""
    if isinstance(o, Deferred):
        return o
    if inspect.isawaitable(o):
        if not is_asyncio_available():
            # wrapping the coroutine directly into a Deferred, this doesn't work correctly with coroutines
            # that use asyncio, e.g. "await asyncio.sleep(1)"
            return Deferred.fromCoroutine(cast("Coroutine[Deferred[Any], Any, _T]", o))
        # wrapping the coroutine into a Future and then into a Deferred, this requires AsyncioSelectorReactor
        return Deferred.fromFuture(asyncio.ensure_future(o))
    return o

def _maybeDeferred_coro(
    f: Callable[_P, Any], warn: bool, *args: _P.args, **kw: _P.kwargs
) -> Deferred[Any]:
    """Copy of defer.maybeDeferred that also converts coroutines to Deferreds."""
    try:
        result = f(*args, **kw)
    except:  # noqa: E722
        return fail(failure.Failure(captureVars=Deferred.debug))

    # when the deprecation period has ended we need to make sure the behavior
    # of the public maybeDeferred_coro() function isn't changed, or drop it in
    # the same release
    if isinstance(result, Deferred):
        if warn:
            warnings.warn(
                f"{global_object_name(f)} returned a Deferred, this is deprecated."
                f" Please refactor this function to return a coroutine.",
                ScrapyDeprecationWarning,
                stacklevel=2,
            )
        return result
    if asyncio.isfuture(result) or inspect.isawaitable(result):
        return deferred_from_coro(result)
    if isinstance(result, failure.Failure):  # pragma: no cover
        if warn:
            warnings.warn(
                f"{global_object_name(f)} returned a Failure, this is deprecated."
                f" Please refactor this function to return a coroutine.",
                ScrapyDeprecationWarning,
                stacklevel=2,
            )
        return fail(result)
    return succeed(result)

def ensure_awaitable(o: _T | Awaitable[_T], _warn: str | None = None) -> Awaitable[_T]:
    """Convert any value to an awaitable object.

    For a :class:`~twisted.internet.defer.Deferred` object, use
    :func:`maybe_deferred_to_future` to wrap it into a suitable object. For an
    awaitable object of a different type, return it as is. For any other
    value, return a coroutine that completes with that value.

    .. versionadded:: 2.14
    """
    if isinstance(o, Deferred):
        if _warn:
            warnings.warn(
                f"{_warn} returned a Deferred, this is deprecated."
                f" Please refactor this function to return a coroutine.",
                ScrapyDeprecationWarning,
                stacklevel=2,
            )
        return maybe_deferred_to_future(o)
    if inspect.isawaitable(o):
        return o

    async def coro() -> _T:
        return o

    return coro()

def _callback(self, result: _T) -> None:
    # This gets called when the result from aiterator.__anext__() is available.
    # It calls the callable on it and sends the result to the oldest waiting Deferred
    # (by chaining if the result is a Deferred too or by firing if not).
    self.anext_deferred = None
    self.on_value()
    callable_result = self.callable(
        result, *self.callable_args, **self.callable_kwargs
    )
    d = self.waiting_deferreds.popleft()
    if isinstance(callable_result, Deferred):
        callable_result.chainDeferred(d)
    else:
        d.callback(None)
    if self.waiting_deferreds:
        self._call_anext()

def __next__(self) -> Deferred[Any]:
    # This puts a new Deferred into self.waiting_deferreds and returns it.
    # It also calls __anext__() if needed.
    if self.finished:
        raise StopIteration
    d: Deferred[Any] = Deferred()
    self.waiting_deferreds.append(d)
    if not self.anext_deferred:
        self._call_anext()
    return d

def default(self, o: Any) -> Any:
    if isinstance(o, set):
        return list(o)
    if isinstance(o, (datetime.datetime, datetime.date, datetime.time)):
        return o.isoformat()
    if isinstance(o, decimal.Decimal):
        return str(o)
    if isinstance(o, defer.Deferred):
        return str(o)
    if isinstance(o, Request):
        return f"<{type(o).__name__} {o.method} {o.url}>"
    if isinstance(o, Response):
        return f"<{type(o).__name__} {o.status} {o.url}>"
    if is_item(o):
        return ItemAdapter(o).asdict()
    return super().default(o)

def failure_to_exc_info(
    failure: Failure,
) -> tuple[type[BaseException], BaseException, TracebackType | None] | None:
    """Extract exc_info from Failure instances"""
    if isinstance(failure, Failure):
        assert failure.type
        assert failure.value
        return (
            failure.type,
            failure.value,
            cast("TracebackType | None", failure.getTracebackObject()),
        )
    return None

def _uninstall_scrapy_root_handler() -> None:
    global _scrapy_root_handler  # noqa: PLW0603

    if _scrapy_root_handler is None:
        return

    if _scrapy_root_handler in logging.root.handlers:
        logging.root.removeHandler(_scrapy_root_handler)
    _scrapy_root_handler.close()
    _scrapy_root_handler = None

def _get_formatter(handler: logging.Handler, settings: Settings) -> logging.Formatter:
    fmt = settings.get("LOG_FORMAT")
    datefmt = settings.get("LOG_DATEFORMAT")
    if (
        isinstance(handler, logging.StreamHandler)
        and not isinstance(handler, logging.FileHandler)
        and settings.getbool("LOG_COLOR")
        and handler.stream.isatty()
        and tty_supports_color()
    ):
        try:
            from colorlog import ColoredFormatter  # noqa: PLC0415
        except ImportError:
            pass
        else:
            return ColoredFormatter(fmt=f"%(log_color)s{fmt}", datefmt=datefmt)
    return logging.Formatter(fmt=fmt, datefmt=datefmt)

def logformatter_adapter(
    logkws: LogFormatterResult,
) -> tuple[Any, ...]:
    """
    Helper that takes the dictionary output from the methods in LogFormatter
    and adapts it into a tuple of positional arguments for logger.log calls.
    """

    level = logkws.get("level", logging.INFO)
    message = logkws.get("msg") or ""
    args = logkws.get("args")
    # logging interpolates the message whenever it receives any positional
    # argument, so empty args are left out. Tuple args become one positional
    # argument each, while a dict is a single positional argument.
    if not args:
        if _MSG_MAPPING_PLACEHOLDER.search(message):
            # The log formatter method has already returned, so there is no
            # frame of it left in the stack to point at. msg is part of the
            # warning message instead, so that each offending method gets its
            # own warning.
            warnings.warn(
                f"A log formatter method returned msg {message!r} with "
                f"%(name)s placeholders and no args. Interpolating msg with "
                f"the returned dict is deprecated, return those values under "
                f"args instead.",
                ScrapyDeprecationWarning,
                stacklevel=1,
            )
            return (level, message, logkws)
        return (level, message)
    if isinstance(args, tuple):
        return (level, message, *args)
    return (level, message, args)

def ftp_makedirs_cwd(ftp: FTP, path: str, first_call: bool = True) -> None:
    """Set the current directory of the FTP connection given in the ``ftp``
    argument (as a ftplib.FTP object), creating all parent directories if they
    don't exist. The ftplib.FTP object must be already connected and logged in.
    """
    try:
        ftp.cwd(path)
    except error_perm:
        ftp_makedirs_cwd(ftp, dirname(path), False)
        ftp.mkd(path)
        if first_call:
            ftp.cwd(path)

def wrap_twisted_exceptions() -> Iterator[None]:
    """Context manager that wraps Twisted exceptions into Scrapy exceptions."""
    try:
        yield
    except SchemeNotSupported as e:
        raise UnsupportedURLSchemeError(str(e)) from e
    except CancelledError as e:
        raise DownloadCancelledError(str(e)) from e
    except TxConnectionRefusedError as e:
        raise DownloadConnectionRefusedError(str(e)) from e
    except DNSLookupError as e:
        raise CannotResolveHostError(str(e)) from e
    except ResponseFailed as e:
        raise DownloadFailedError(str(e)) from e
    except TxTimeoutError as e:
        raise DownloadTimeoutError(str(e)) from e

def check_stop_download(
    signal: object, crawler: Crawler, request: Request, **kwargs: Any
) -> StopDownload | None:
    """Send the given signal and check if any of its handlers raised
    :exc:`~scrapy.exceptions.StopDownload`.

    Return the raised exception or ``None``.
    """
    signal_result = crawler.signals.send_catch_log(
        signal=signal,
        request=request,
        spider=crawler.spider,
        **kwargs,
    )
    for handler, result in signal_result:
        if isinstance(result, Failure) and isinstance(result.value, StopDownload):
            logger.debug(
                f"Download stopped for {request} from signal handler {handler.__qualname__}"
            )
            return result.value

    return None

def url_is_from_any_domain(url: UrlT, domains: Iterable[str]) -> bool:
    """Return True if the url belongs to any of the given domains"""
    host = parse_url(url).netloc.lower()
    if not host:
        return False
    return any((host == d) or (host.endswith(f".{d}")) for d in map(str.lower, domains))

def _embed_standard_shell(
    namespace: dict[str, Any] | None = None, banner: str = ""
) -> EmbedFuncT:
    """Start a standard python shell"""
    try:  # readline module is only available on unix systems
        import readline  # noqa: PLC0415
    except ImportError:
        pass
    else:
        import rlcompleter  # noqa: F401,PLC0415

        readline.parse_and_bind("tab:complete")  # type: ignore[attr-defined,unused-ignore]

    @wraps(_embed_standard_shell)
    def wrapper(namespace: dict[str, Any] = namespace or {}, banner: str = "") -> None:
        code.interact(banner=banner, local=namespace)

    return wrapper

def get_shell_embed_func(
    shells: Iterable[str] | None = None, known_shells: KnownShellsT | None = None
) -> EmbedFuncT | None:
    """Return the first acceptable shell-embed function
    from a given list of shell names.
    """
    if shells is None:  # list, preference order of shells
        shells = DEFAULT_PYTHON_SHELLS.keys()
    if known_shells is None:  # available embeddable shells
        known_shells = DEFAULT_PYTHON_SHELLS.copy()
    for shell in shells:
        if shell in known_shells:
            try:
                # function test: run all setup code (imports),
                # but dont fall into the shell
                return known_shells[shell]()
            except ImportError:
                continue
    return None

def start_python_console(
    namespace: dict[str, Any] | None = None,
    banner: str = "",
    shells: Iterable[str] | None = None,
) -> None:
    """Start Python console bound to the given namespace.
    Readline support and tab completion will be used on Unix, if available.
    """
    if namespace is None:
        namespace = {}

    try:
        shell = get_shell_embed_func(shells)
        if shell is not None:
            shell(namespace=namespace, banner=banner)
    except SystemExit:  # raised when using exit() in python code.interact
        pass

def __setitem__(self, key: _KT, value: _VT) -> None:
    if self.limit is not None:
        if self.limit == 0:
            return
        if key not in self:
            while len(self) >= self.limit:
                self.popitem(last=False)
    super().__setitem__(key, value)

def sitemap_urls_from_robots(
    robots_text: str | bytes,
    base_url: str | None = None,
) -> Iterable[str]:
    if isinstance(robots_text, bytes):
        for line in BytesIO(robots_text):
            if line.lstrip()[:8].lower() == b"sitemap:":
                try:
                    url = line.partition(b":")[2].strip().decode()
                except UnicodeDecodeError:
                    continue
                yield urljoin(base_url or "", url)

    else:
        warnings.warn(
            "Passing `str` type as `robots_text` is deprecated, use `bytes`",
            ScrapyDeprecationWarning,
            stacklevel=2,
        )
        yield from _sitemap_urls_from_robots_str(robots_text, base_url)

def _sitemap_urls_from_robots_str(
    robots_text: str,
    base_url: str | None = None,
) -> Iterable[str]:
    for line in StringIO(robots_text):
        if line.lstrip()[:8].lower() == "sitemap:":
            url = line.partition(":")[2].strip()
            yield urljoin(base_url or "", url)

def __iter__(self) -> Iterator[dict[str, Any]]:
    for event, elem in self.xmliter:
        if event == "start":
            continue

        if self._get_tag_name(elem) not in {"url", "sitemap"}:
            continue

        if d := self._process_sitemap_element(elem):
            yield d

def _process_sitemap_element(
    self, elem: lxml.etree._Element
) -> dict[str, Any] | None:
    d: dict[str, Any] = {}
    alternate: list[str] = []
    has_loc = False

    for el in elem:
        try:
            tag_name = self._get_tag_name(el)
            if not tag_name:
                continue

            if tag_name == "link":
                if href := el.get("href"):
                    alternate.append(href)
            else:
                d[tag_name] = el.text.strip() if el.text else ""
                if not has_loc and tag_name == "loc":
                    has_loc = True
        finally:
            el.clear()
    elem.clear()
    parent = elem.getparent()
    if parent is not None:
        while elem.getprevious() is not None:
            del parent[0]

    if not has_loc:
        return None

    if alternate:
        d["alternate"] = alternate

    return d

def _get_tag_name(elem: lxml.etree._Element) -> str:
    tag = elem.tag
    if not isinstance(tag, str):
        return ""
    _, _, localname = tag.partition("}")
    return localname or tag

def get_reactor_settings() -> dict[str, Any]:
    """Return a settings dict that works with the installed reactor.

    ``Crawler._apply_settings()`` checks that the installed reactor matches the
    settings, so tests that run the crawler in the current process may need to
    pass a correct :setting:`TWISTED_REACTOR` setting value when creating it.
    """
    settings: dict[str, Any] = {}
    if is_reactor_installed():
        if not _is_asyncio_reactor_installed():
            settings["TWISTED_REACTOR"] = None
    else:
        # We are either running Scrapy tests for the reactorless mode, or
        # running some 3rd-party library tests for the reactorless mode, or
        # running some 3rd-party library tests without initializing a reactor
        # properly. The first two cases are fine, but we cannot distinguish the
        # last one from them.
        settings["TWISTED_REACTOR_ENABLED"] = False
        settings["DOWNLOAD_HANDLERS"] = {
            "ftp": None,
            "http": "scrapy.core.downloader.handlers._aiohttp.AiohttpDownloadHandler",
            "https": "scrapy.core.downloader.handlers._aiohttp.AiohttpDownloadHandler",
        }
    return settings

def _version(item: str) -> str:
    lowercase_item = item.lower()
    if lowercase_item == "libxml2":
        return ".".join(map(str, lxml.etree.LIBXML_VERSION))
    if lowercase_item == "platform":
        return platform.platform()
    if lowercase_item == "pyopenssl":
        return _get_openssl_version()
    if lowercase_item == "python":
        return sys.version.replace("\n", "- ")
    return version(item)

def get_versions(
    software: list[str] | None = None,
) -> list[tuple[str, str]]:
    software = software or _DEFAULT_SOFTWARE
    return [(item, _version(item)) for item in software]

def _parse_headers_and_cookies(
    parsed_args: argparse.Namespace,
) -> tuple[list[tuple[str, str | bytes]], dict[str, str]]:
    headers: list[tuple[str, str | bytes]] = []
    cookies: dict[str, str] = {}
    for header in parsed_args.headers or ():
        if ":" in header:
            name, val = header.split(":", 1)
        elif header.endswith(";") and header[:-1].strip():
            name, val = header[:-1], ""
        else:
            continue
        name = name.strip()
        val = val.strip()
        if name.title() == "Cookie":
            for name, morsel in SimpleCookie(val).items():
                cookies[name] = morsel.value
        else:
            headers.append((name, val))

    for cookie_param in parsed_args.cookies or ():
        # curl can treat this parameter as either "key=value; key2=value2" pairs, or a filename.
        # Scrapy will only support key-value pairs.
        if "=" not in cookie_param:
            continue
        for name, morsel in SimpleCookie(cookie_param).items():
            cookies[name] = morsel.value

    if parsed_args.auth:
        user, _, password = parsed_args.auth.partition(":")
        headers.append(("Authorization", basic_auth_header(user, password)))

    return headers, cookies

def curl_to_request_kwargs(
    curl_command: str, ignore_unknown_options: bool = True
) -> dict[str, Any]:
    """Convert a cURL command syntax to Request kwargs.

    :param str curl_command: string containing the curl command
    :param bool ignore_unknown_options: If true, only a warning is emitted when
                                        cURL options are unknown. Otherwise
                                        raises an error. (default: True)
    :return: dictionary of Request kwargs
    """

    curl_args = split(curl_command)

    if not curl_args or curl_args[0] != "curl":
        raise ValueError('A curl command must start with "curl"')

    parsed_args, argv = curl_parser.parse_known_args(curl_args[1:])

    if argv:
        msg = f"Unrecognized options: {', '.join(argv)}"
        if ignore_unknown_options:
            warnings.warn(msg, stacklevel=2)
        else:
            raise ValueError(msg)

    url = parsed_args.url

    # curl automatically prepends 'http' if the scheme is missing, but Request
    # needs the scheme to work
    parsed_url = urlparse(url)
    if not parsed_url.scheme:
        url = "http://" + url

    method = parsed_args.method or "GET"

    result: dict[str, Any] = {"method": method.upper(), "url": url}

    headers, cookies = _parse_headers_and_cookies(parsed_args)

    if headers:
        result["headers"] = headers
    if cookies:
        result["cookies"] = cookies
    if parsed_args.data:
        result["body"] = parsed_args.data
        if not parsed_args.method:
            # if the "data" is specified but the "method" is not specified,
            # the default method is 'POST'
            result["method"] = "POST"

    return result

def _get_tls_version_limit(
    settings: BaseSettings, setting_name: str, converter: Callable[[str], _T]
) -> _T | None:
    setting: str | None = settings[setting_name]
    if setting is None:
        return None
    try:
        return converter(setting)
    except Exception as ex:
        raise ValueError(f"Unknown {setting_name} value: {setting}") from ex

def _get_keylog_filename() -> str | None:
    """Return the path where TLS session keys should be logged, or ``None``."""
    if sys.flags.ignore_environment:
        return None
    filename = os.environ.get("SSLKEYLOGFILE")
    if not filename:
        return None
    try:
        with Path(filename).open("ab"):
            pass
    except OSError as ex:
        logger.warning(f"Cannot write TLS session keys to {filename}: {ex}")
        return None
    return filename

def _make_ssl_context(settings: BaseSettings) -> ssl.SSLContext:
    """Create an :class:`ssl.SSLContext` instance according to the settings.

    It's intended to be used in an HTTPS download handler.
    """

    tls_min_ver, tls_max_ver = _get_tls_version_limits(
        settings, _STDLIB_VERSION_MAP.__getitem__
    )
    ciphers_setting: str | None = settings["DOWNLOADER_CLIENT_TLS_CIPHERS"]
    verify_setting = settings.getbool("DOWNLOAD_VERIFY_CERTIFICATES")

    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    if verify_setting:
        ctx.check_hostname = True
        ctx.verify_mode = ssl.CERT_REQUIRED
        ctx.load_default_certs()
    else:
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
    if tls_min_ver is not None:
        ctx.minimum_version = tls_min_ver
    if tls_max_ver is not None:
        ctx.maximum_version = tls_max_ver
    if ciphers_setting:
        ctx.set_ciphers(ciphers_setting)
    if keylog_filename := _get_keylog_filename():
        ctx.keylog_filename = keylog_filename
    return ctx

def _get_cert_options_version_kwargs(
    min_version: TLSVersion | None, max_version: TLSVersion | None
) -> _CertificateOptionsVersionKwargs:
    """Get TLS version kwargs for
    :class:`~twisted.internet.ssl.CertificateOptions` for the given limits."""
    result: _CertificateOptionsVersionKwargs = {}
    if max_version:
        if TWISTED_TLS_LIMITS_OFFBY1:
            # lowerMaximumSecurityTo is treated as 1 version lower than the passed one
            versions = list(TLSVersion.iterconstants())
            max_index = versions.index(max_version)
            if max_index + 1 >= len(versions):
                raise ValueError(
                    f"Due to an error in Twisted < 26.4.0 cannot set the maximum TLS version to {max_version.name}"
                )
            max_version = versions[max_index + 1]
        result["lowerMaximumSecurityTo"] = max_version
    if min_version:
        # We cannot pass both insecurelyLowerMinimumTo and raiseMinimumTo,
        # so we need to know the direction.

        # 1.0 in Twisted 22.8.0 and older, 1.2 in Twisted 22.10.0 and newer
        default_min = CertificateOptions._defaultMinimumTLSVersion
        if min_version < default_min:
            result["insecurelyLowerMinimumTo"] = min_version
        elif min_version > default_min:
            result["raiseMinimumTo"] = min_version
    return result

def _body_or_str(obj: Response | str | bytes, unicode: bool = True) -> str | bytes:
    expected_types = (Response, str, bytes)
    if not isinstance(obj, expected_types):
        expected_types_str = " or ".join(t.__name__ for t in expected_types)
        raise TypeError(
            f"Object {obj!r} must be {expected_types_str}, not {type(obj).__name__}"
        )
    if isinstance(obj, Response):
        if not unicode:
            return obj.body
        if isinstance(obj, TextResponse):
            return obj.text
        return obj.body.decode("utf-8")
    if isinstance(obj, str):
        return obj if unicode else obj.encode("utf-8")
    return obj.decode("utf-8") if unicode else obj

def __init__(self, obj: Response | str | bytes):
    self._ptr: int = 0
    self._text: str | bytes
    if isinstance(obj, TextResponse):
        self._text, self.encoding = obj.body, obj.encoding
    elif isinstance(obj, Response):
        self._text, self.encoding = obj.body, "utf-8"
    else:
        self._text, self.encoding = obj, "utf-8"
    self._is_unicode: bool = isinstance(self._text, str)
    self._is_first_read: bool = True

def read(self, n: int = 65535) -> bytes:
    method: Callable[[int], bytes] = (
        self._read_unicode if self._is_unicode else self._read_string
    )
    result = method(n)
    if self._is_first_read:
        self._is_first_read = False
        result = result.lstrip()
    return result

def update_classpath(path: Any) -> Any:
    """Update a deprecated path from an object with its new location"""
    for prefix, replacement in DEPRECATION_RULES:
        if isinstance(path, str) and path.startswith(prefix):
            new_path = path.replace(prefix, replacement, 1)
            warnings.warn(
                f"`{path}` class is deprecated, use `{new_path}` instead",
                ScrapyDeprecationWarning,
                stacklevel=2,
            )
            return new_path
    return path

async def as_async_generator(
    it: Iterable[_T] | AsyncIterator[_T],
) -> AsyncGenerator[_T]:
    """Wraps an iterable (sync or async) into an async generator."""
    if isinstance(it, AsyncIterator):
        async for r in it:
            yield r
    else:
        for r in it:
            yield r

def _warn_spider_arg(
    func: Callable[_P, _T],
) -> (
    Callable[_P, _T]
    | Callable[_P, Coroutine[Any, Any, _T]]
    | Callable[_P, AsyncGenerator[_T]]
):
    """Decorator to warn if a ``spider`` argument is passed to a function."""
    parameters = _signature(func).parameters
    spider_parameter = parameters.get("spider")
    spider_index = (
        list(parameters).index("spider")
        if spider_parameter is not None
        and spider_parameter.kind
        in (
            inspect.Parameter.POSITIONAL_ONLY,
            inspect.Parameter.POSITIONAL_OR_KEYWORD,
        )
        else None
    )

    def check_args(args: tuple[Any, ...], kwargs: dict[str, Any]) -> None:
        if "spider" in kwargs or (
            spider_index is not None and len(args) > spider_index
        ):
            warnings.warn(
                f"Passing a 'spider' argument to {func.__qualname__}() is deprecated and "
                "the argument will be removed in a future Scrapy version.",
                category=ScrapyDeprecationWarning,
                stacklevel=3,
            )

    if inspect.iscoroutinefunction(func):

        @wraps(func)
        async def async_inner(*args: _P.args, **kwargs: _P.kwargs) -> _T:
            check_args(args, kwargs)
            return cast("_T", await func(*args, **kwargs))

        return async_inner

    if inspect.isasyncgenfunction(func):

        @wraps(func)
        async def asyncgen_inner(
            *args: _P.args, **kwargs: _P.kwargs
        ) -> AsyncGenerator[_T]:
            check_args(args, kwargs)
            async for item in func(*args, **kwargs):
                yield item

        return asyncgen_inner

    @wraps(func)
    def sync_inner(*args: _P.args, **kwargs: _P.kwargs) -> _T:
        check_args(args, kwargs)
        return func(*args, **kwargs)

    return sync_inner

def _unzstd(data: bytes, *, max_size: int = 0) -> bytes:
    stream_reader = zstd.ZstdFile(BytesIO(data))
    output_stream = BytesIO()
    output_chunk = b"."
    decompressed_size = 0
    while output_chunk:
        try:
            output_chunk = stream_reader.read(_CHUNK_SIZE)
        except EOFError:
            # Return as much data as possible out of a truncated response.
            break
        decompressed_size += len(output_chunk)
        _check_max_size(decompressed_size, max_size)
        output_stream.write(output_chunk)
    return output_stream.getvalue()

def process_request(
    self, request: Request, spider: Spider | None = None
) -> Request | Response | None:
    if b"Authorization" in request.headers:
        return None
    # Per-request meta overrides
    usr = request.meta.get("http_user", "")
    pwd = request.meta.get("http_pass", "")
    if usr or pwd:
        domain = request.meta.get("http_auth_domain")
        if not domain or url_is_from_any_domain(request.url, [domain]):
            request.headers[b"Authorization"] = basic_auth_header(usr, pwd)
        return None
    # Middleware-level auth
    if self._auth and (
        not self._domain or url_is_from_any_domain(request.url, [self._domain])
    ):
        request.headers[b"Authorization"] = self._auth
    return None

def process_exception(
    self, request: Request, exception: Exception, spider: Spider | None = None
) -> Request | Response | None:
    cachedresponse: Response | None = request.meta.pop("cached_response", None)
    if cachedresponse is not None and isinstance(
        exception, self.DOWNLOAD_EXCEPTIONS
    ):
        self.stats.inc_value("httpcache/errorrecovery")
        return cachedresponse
    return None

def _freshen_cached_response(
    self, cachedresponse: Response, response: Response
) -> None:
    # RFC 7234, section 4.3.4: update the stored response with the
    # header fields from a successful revalidation (304) response.
    warnings = [
        warning
        for warning in cachedresponse.headers.getlist(b"Warning")
        if warning.split(None, 1)[0].startswith(b"2")
    ]
    cachedresponse.headers.update(response.headers)
    if warnings:
        cachedresponse.headers[b"Warning"] = warnings
    else:
        cachedresponse.headers.pop(b"Warning", None)

def process_response(self, request: Request, response: Response) -> Response:
    if (
        isinstance(response, JsonResponse)
        and request.method != "HEAD"
        and 200 <= response.status < 300
        and response.status != 204
    ):
        response.json()
    return response

def __init__(self, settings: BaseSettings):
    if not settings.getbool("RETRY_ENABLED"):
        raise NotConfigured
    self.max_retry_times = settings.getint("RETRY_TIMES")
    self.retry_http_codes = {int(x) for x in settings.getlist("RETRY_HTTP_CODES")}
    self.priority_adjust = settings.getint("RETRY_PRIORITY_ADJUST")
    self.give_up_log_level = settings["RETRY_GIVE_UP_LOG_LEVEL"]
    self.exceptions_to_retry = _load_objects(settings.getlist("RETRY_EXCEPTIONS"))

def process_response(
    self,
    request: Request,
    response: Response,
    spider: scrapy.Spider | None = None,
) -> Request | Response:
    if request.meta.get("dont_retry", False):
        return response
    if response.status in self.retry_http_codes:
        reason = response_status_message(response.status)
        return self._retry(request, reason) or response
    return response

def process_exception(
    self,
    request: Request,
    exception: Exception,
    spider: scrapy.Spider | None = None,
) -> Request | Response | None:
    if isinstance(exception, self.exceptions_to_retry) and not request.meta.get(
        "dont_retry", False
    ):
        return self._retry(request, exception)
    return None

def process_response(
    self, request: Request, response: Response, spider: Spider | None = None
) -> Request | Response:
    if (
        request.meta.get("dont_redirect", False)
        or response.status
        in getattr(self.crawler.spider, "handle_httpstatus_list", ())
        or response.status in request.meta.get("handle_httpstatus_list", ())
        or request.meta.get("handle_httpstatus_all", False)
    ):
        return response

    if "Location" not in response.headers or response.status not in {
        301,
        302,
        303,
        307,
        308,
    }:
        return response

    assert response.headers["Location"] is not None
    location = safe_url_string(response.headers["Location"])
    if response.headers["Location"].startswith(b"//"):
        request_scheme = urlparse_cached(request).scheme
        location = request_scheme + "://" + location.lstrip("/")

    redirected_url = urljoin(request.url, location)

    if not urlparse(redirected_url).fragment:
        fragment = urlparse_cached(request).fragment
        if fragment:
            redirected_url = urljoin(redirected_url, f"#{fragment}")

    redirected = self._build_redirect_request(request, response, url=redirected_url)
    if urlparse_cached(redirected).scheme not in {"http", "https"}:
        return response

    if (response.status in {301, 302} and request.method == "POST") or (
        response.status == 303 and request.method not in {"GET", "HEAD"}
    ):
        redirected = self._redirect_request_using_get(
            request, response, redirected_url
        )

    return self._redirect(redirected, request, response.status)

def process_response(
    self, request: Request, response: Response, spider: Spider | None = None
) -> Request | Response:
    if (
        request.meta.get("dont_redirect", False)
        or request.method == "HEAD"
        or not isinstance(response, HtmlResponse)
        or urlparse_cached(request).scheme not in {"http", "https"}
    ):
        return response

    interval, url = get_meta_refresh(response, ignore_tags=self._ignore_tags)
    if not url:
        return response
    redirected = self._redirect_request_using_get(request, response, url)
    if urlparse_cached(redirected).scheme not in {"http", "https"}:
        return response
    if cast("float", interval) < self._maxdelay:
        return self._redirect(redirected, request, "meta refresh")
    return response

def __init__(self, auth_encoding: str | None = "latin-1"):
    self.auth_encoding: str | None = auth_encoding
    self.proxies: dict[str, tuple[bytes | None, str]] = {}
    for type_, url in getproxies().items():
        try:
            self.proxies[type_] = self._get_proxy(url, type_)
        # some values such as '/var/run/docker.sock' can't be parsed
        # by _parse_proxy and as such should be skipped
        except ValueError:
            continue

def process_request(
    self, request: Request, spider: Spider | None = None
) -> Request | Response | None:
    creds, proxy_url, scheme = None, None, None
    if "proxy" in request.meta:
        if request.meta["proxy"] is not None:
            creds, proxy_url = self._get_proxy(request.meta["proxy"], "")
    elif self.proxies:
        parsed = urlparse_cached(request)
        _scheme = parsed.scheme
        if (
            # 'no_proxy' is only supported by http schemes
            _scheme not in {"http", "https"}
            or (parsed.hostname and not proxy_bypass(parsed.hostname))
        ) and _scheme in self.proxies:
            scheme = _scheme
            creds, proxy_url = self.proxies[scheme]

    self._set_proxy_and_creds(request, proxy_url, creds, scheme)
    return None

def _set_proxy_and_creds(
    self,
    request: Request,
    proxy_url: str | None,
    creds: bytes | None,
    scheme: str | None,
) -> None:
    if scheme:
        request.meta["_scheme_proxy"] = True
    if proxy_url:
        request.meta["proxy"] = proxy_url
    elif request.meta.get("proxy") is not None:
        request.meta["proxy"] = None
    if creds:
        request.headers[b"Proxy-Authorization"] = b"Basic " + creds
        request.meta["_auth_proxy"] = proxy_url
    elif "_auth_proxy" in request.meta:
        if proxy_url != request.meta["_auth_proxy"]:
            if b"Proxy-Authorization" in request.headers:
                del request.headers[b"Proxy-Authorization"]
            del request.meta["_auth_proxy"]
    elif b"Proxy-Authorization" in request.headers:
        if proxy_url:
            request.meta["_auth_proxy"] = proxy_url
        else:
            del request.headers[b"Proxy-Authorization"]

def _update_host_regex(self, spider: Spider) -> None:
    allowed_domains = list(getattr(spider, "allowed_domains", None) or [])
    if allowed_domains != self._allowed_domains:
        self._allowed_domains = allowed_domains
        self.host_regex = self.get_host_regex(spider)

def get_host_regex(self, spider: Spider) -> re.Pattern[str]:
    allowed_domains = getattr(spider, "allowed_domains", None)
    if not allowed_domains:
        return re.compile("")  # allow all by default
    domains = []
    for domain in allowed_domains:
        if domain is None:
            continue
        domains.append(re.escape(domain))
    regex = rf"^(.*\.)?({'|'.join(domains)})$"
    return re.compile(regex)

async def process_request(
    self, request: Request, spider: Spider | None = None
) -> None:
    if request.meta.get("dont_obey_robotstxt"):
        return
    if request.url.startswith("data:") or request.url.startswith("file:"):
        return
    rp = await self.robot_parser(request)
    self.process_request_2(rp, request)

def process_request_2(self, rp: RobotParser | None, request: Request) -> None:
    if rp is None:
        return

    useragent: str | bytes | None = self._robotstxt_useragent
    if not useragent:
        useragent = request.headers.get(b"User-Agent", self._default_useragent)
        assert useragent is not None
    if not rp.allowed(request.url, useragent):
        logger.debug(
            "Forbidden by robots.txt: %(request)s",
            {"request": request},
            extra={"spider": self.crawler.spider},
        )
        self._stats.inc_value("robotstxt/forbidden")
        raise IgnoreRequest("Forbidden by robots.txt")

def get_header_size(
    headers: dict[str, list[str | bytes] | tuple[str | bytes, ...]],
) -> int:
    size = 0
    for key, value in headers.items():
        if isinstance(value, (list, tuple)):
            for v in value:
                size += len(b": ") + len(key) + len(v)
    return size + len(b"\r\n") * (len(headers.keys()) - 1)

def _process_cookies(
    self, cookies: Iterable[Cookie], *, jar: CookieJar, request: Request
) -> None:
    for cookie in cookies:
        cookie_domain = cookie.domain
        cookie_domain = cookie_domain.removeprefix(".")

        hostname = urlparse_cached(request).hostname
        if hostname is None:
            continue
        request_domain = hostname.lower()

        if cookie_domain and _is_public_domain(cookie_domain):
            if cookie_domain != request_domain:
                continue
            cookie.domain = request_domain

        jar.set_cookie_if_ok(cookie, request)

def _debug_cookie(self, request: Request) -> None:
    if self.debug:
        cl = [
            to_unicode(c, errors="replace")
            for c in request.headers.getlist("Cookie")
        ]
        if cl:
            cookies = "\n".join(f"Cookie: {c}\n" for c in cl)
            msg = f"Sending cookies to: {request}\n{cookies}"
            logger.debug(msg, extra={"spider": self.crawler.spider})

def _debug_set_cookie(self, response: Response) -> None:
    if self.debug:
        cl = [
            to_unicode(c, errors="replace")
            for c in response.headers.getlist("Set-Cookie")
        ]
        if cl:
            cookies = "\n".join(f"Set-Cookie: {c}\n" for c in cl)
            msg = f"Received cookies from: {response}\n{cookies}"
            logger.debug(msg, extra={"spider": self.crawler.spider})

def _get_request_cookies(
    self, jar: CookieJar, request: Request
) -> Sequence[Cookie]:
    """
    Extract cookies from the Request.cookies attribute
    """
    if not request.cookies:
        return ()
    cookies: Iterable[VerboseCookie] = _to_verbose_cookies(request.cookies)
    for cookie in cookies:
        cookie.setdefault("secure", urlparse_cached(request).scheme == "https")
    formatted = filter(None, (self._format_cookie(c, request) for c in cookies))
    response = Response(request.url, headers={"Set-Cookie": formatted})
    return jar.make_cookies(response, request)

def open_spider(self, spider: Spider) -> None:
    if hasattr(spider, "download_maxsize"):
        warn_on_deprecated_spider_attribute("download_maxsize", "DOWNLOAD_MAXSIZE")
        self._max_size = spider.download_maxsize
    if hasattr(spider, "download_warnsize"):
        warn_on_deprecated_spider_attribute(
            "download_warnsize", "DOWNLOAD_WARNSIZE"
        )
        self._warn_size = spider.download_warnsize

def process_response(
    self, request: Request, response: Response, spider: Spider | None = None
) -> Request | Response:
    if request.method == "HEAD":
        return response
    content_encoding = response.headers.getlist("Content-Encoding")
    if content_encoding:
        max_size = request.meta.get("download_maxsize", self._max_size)
        warn_size = request.meta.get("download_warnsize", self._warn_size)
        try:
            decoded_body, content_encoding = self._handle_encoding(
                response.body, content_encoding, max_size
            )
        except _DecompressionMaxSizeExceeded as e:
            msg = (
                f"Ignored response {response} because its body "
                f"({len(response.body)} B compressed, "
                f"{e.decompressed_size} B decompressed so far) exceeded "
                f"DOWNLOAD_MAXSIZE ({max_size} B) during decompression."
            )
            logger.warning(msg)
            raise IgnoreRequest(msg) from e
        except _DECOMPRESSION_ERRORS as e:
            encodings = b", ".join(content_encoding).decode()
            raise DecompressionError(
                f"Could not decompress {response} ({encodings}): {e}"
            ) from e
        if len(response.body) < warn_size <= len(decoded_body):
            logger.warning(
                f"{response} body size after decompression "
                f"({len(decoded_body)} B) is larger than the "
                f"download warning size ({warn_size} B)."
            )
        if content_encoding:
            self._warn_unknown_encoding(response, content_encoding)
        response.headers["Content-Encoding"] = content_encoding
        if self.stats:
            self.stats.inc_value(
                "httpcompression/response_bytes",
                len(decoded_body),
            )
            self.stats.inc_value("httpcompression/response_count")
        respcls = responsetypes.from_args(
            headers=response.headers, url=response.url, body=decoded_body
        )
        kwargs: dict[str, Any] = {"body": decoded_body}
        if issubclass(respcls, TextResponse):
            # force recalculating the encoding until we make sure the
            # responsetypes guessing is reliable
            kwargs["encoding"] = None
        response = response.replace(cls=respcls, **kwargs)
        if not content_encoding:
            del response.headers["Content-Encoding"]
    return response

def _split_encodings(
    content_encoding: list[bytes],
) -> tuple[list[bytes], list[bytes]]:
    supported_encodings = {*ACCEPTED_ENCODINGS, b"x-gzip"}
    to_keep: list[bytes] = [
        encoding.strip().lower()
        for encoding in chain.from_iterable(
            encodings.split(b",") for encodings in content_encoding
        )
    ]
    to_decode: list[bytes] = []
    while to_keep:
        encoding = to_keep.pop()
        if encoding not in supported_encodings:
            to_keep.append(encoding)
            return to_decode, to_keep
        to_decode.append(encoding)
    return to_decode, to_keep

def _decode(body: bytes, encoding: bytes, max_size: int) -> bytes:
    if encoding in {b"gzip", b"x-gzip"}:
        return gunzip(body, max_size=max_size)
    if encoding == b"deflate":
        return _inflate(body, max_size=max_size)
    if encoding == b"br":
        return _unbrotli(body, max_size=max_size)
    if encoding == b"zstd":
        return _unzstd(body, max_size=max_size)
    # shouldn't be reached
    return body  # pragma: no cover

def _maybe_fire_closing(self) -> None:
    if self.closing is not None and not self.inprogress:
        self.nextcall.cancel()
        if self.heartbeat.running:
            self.heartbeat.stop()
        self.closing.callback(None)

async def _process_start_next(self) -> None:
    """Processes the next item or request from Spider.start().

    If a request, it is scheduled. If an item, it is sent to item
    pipelines.
    """
    assert self._start is not None
    try:
        item_or_request = await anext(self._start)
    except StopAsyncIteration:
        self._start = None
    except CloseSpider as exception:
        self._start = None
        _schedule_coro(
            self.close_spider_async(
                reason=exception.reason or "cancelled", error=exception.error
            )
        )
    except Exception as exception:
        self._start = None
        self._start_error = True
        logger.exception("Error while reading start items and requests")
        self.signals.send_catch_log(
            signal=signals.spider_error,
            failure=Failure(),
            response=None,
            spider=self.spider,
        )
        self.crawler.stats.inc_value("spider_exceptions/count")
        self.crawler.stats.inc_value(
            f"spider_exceptions/{type(exception).__name__}"
        )
    else:
        if not self.spider:
            return  # spider already closed
        if isinstance(item_or_request, Request):
            self.crawl(item_or_request)
        else:
            assert self._slot is not None
            self.scraper._start_itemproc_nowait(item_or_request)
            self._slot.nextcall.schedule()

def _start_scheduled_requests(self) -> None:
    if self._slot is None or self._slot.closing is not None or self.paused:
        return

    while not self.needs_backout():
        if not self._start_scheduled_request():
            break

    if self.spider_is_idle() and self._slot.close_if_idle:
        self._spider_idle()

def _handle_downloader_output(
    self, result: Request | Response | Failure, request: Request
) -> Generator[Deferred[Any], Any, None]:
    if (
        isinstance(result, Failure)
        and self._stop_mode == "fast"
        and result.check(
            DownloadCancelledError,
            CancelledError,
            asyncio.exceptions.CancelledError,
        )
    ):
        return

    # downloader middleware can return requests (for example, redirects)
    if isinstance(result, Request):
        self.crawl(result)
        return

    try:
        yield self.scraper.enqueue_scrape(result, request)
    except Exception:
        assert self.spider is not None
        logger.exception(
            "Error while enqueuing scrape", extra={"spider": self.spider}

def spider_is_idle(self) -> bool:
    if self._slot is None:
        raise RuntimeError("Engine slot not assigned")
    if not self.scraper.slot.is_idle():  # type: ignore[union-attr]
        return False
    if self.downloader.active:  # downloader has pending requests
        return False
    if self._start is not None:  # not all start requests are handled
        return False
    return not self._slot.scheduler.has_pending_requests()

def _schedule_request(self, request: Request) -> None:
    request_scheduled_result = self.signals.send_catch_log(
        signals.request_scheduled,
        request=request,
        spider=self.spider,
        dont_log=IgnoreRequest,
    )
    for _, result in request_scheduled_result:
        if isinstance(result, Failure) and isinstance(result.value, IgnoreRequest):
            return
    if not self._slot.scheduler.enqueue_request(request):  # type: ignore[union-attr]
        self.signals.send_catch_log(
            signals.request_dropped, request=request, spider=self.spider

def _download(
    self, request: Request
) -> Generator[Deferred[Any], Any, Response | Request]:
    assert self._slot is not None  # typing
    assert self.spider is not None

    self._slot.add_request(request)
    try:
        result: Response | Request
        if self._downloader_fetch_needs_spider:
            result = yield self.downloader.fetch(request, self.spider)
        else:
            result = yield self.downloader.fetch(request)
        if not isinstance(result, (Response, Request)):
            raise TypeError(
                f"Incorrect type: expected Response or Request, got {type(result)}: {result!r}"
            )
        if isinstance(result, Response):
            if result.request is None:
                result.request = request
            logkws = self.logformatter.crawled(result.request, result, self.spider)
            if logkws is not None:
                logger.log(
                    *logformatter_adapter(logkws), extra={"spider": self.spider}
                )
            self.signals.send_catch_log(
                signal=signals.response_received,
                response=result,
                request=result.request,
                spider=self.spider,
            )
        return result
    finally:
        self._slot.nextcall.schedule()

def _get_start_queue_cls(
    self, crawler: Crawler | None, queue: str
) -> type[BaseQueue] | None:
    if crawler is None:
        return None
    cls = crawler.settings[f"SCHEDULER_START_{queue}_QUEUE"]
    if not cls:
        return None
    return cast("type[BaseQueue]", load_object(cls))

def close(self, reason: str) -> Deferred[None] | None:
    """
    (1) dump pending requests to disk if there is a disk queue
    (2) return the result of the dupefilter's ``close`` method
    """
    if self.dqs is not None:
        state = self.dqs.close()
        assert isinstance(self.dqdir, str)
        self._write_dqs_state(self.dqdir, state)
    return self.df.close(reason)

def _dqdir(self, jobdir: str | None) -> str | None:
    """Return a folder name to keep disk queue state at"""
    if jobdir:
        dqdir = Path(jobdir, "requests.queue")
        if not dqdir.exists():
            dqdir.mkdir(parents=True)
        return str(dqdir)
    return None

def _check_deprecated_itemproc_method(self, method: str) -> None:
    itemproc_cls = type(self.itemproc)
    if not hasattr(self.itemproc, f"{method}_async"):
        warnings.warn(
            f"{global_object_name(itemproc_cls)} doesn't define a {method}_async() method,"
            f" this is deprecated and the method will be required in future Scrapy versions.",
            ScrapyDeprecationWarning,
            stacklevel=2,
        )
        self._itemproc_has_async[method] = False
    elif (
        issubclass(itemproc_cls, ItemPipelineManager)
        and method_is_overridden(itemproc_cls, ItemPipelineManager, method)
        and not method_is_overridden(
            itemproc_cls, ItemPipelineManager, f"{method}_async"
        )
    ):
        warnings.warn(
            f"{global_object_name(itemproc_cls)} overrides {method}() but doesn't override {method}_async()."
            f" This is deprecated. {method}() will be used, but in future Scrapy versions {method}_async() will be used instead.",
            ScrapyDeprecationWarning,
            stacklevel=2,
        )
        self._itemproc_has_async[method] = False
    else:
        self._itemproc_has_async[method] = True

def _check_if_closing(self) -> None:
    assert self.slot is not None  # typing
    if self.slot.closing and self.slot.is_idle():
        assert self.crawler.spider
        self.slot.closing.callback(self.crawler.spider)

def enqueue_scrape(
    self, result: Response | Failure, request: Request
) -> Generator[Deferred[Any], Any, None]:
    if self.slot is None:
        raise RuntimeError("Scraper slot not assigned")
    dfd = self.slot.add_response_request(result, request)
    self._scrape_next()
    try:
        yield dfd  # fired in _wait_for_processing()
    except Exception:
        logger.exception(
            "Scraper bug processing %(request)s",
            {"request": request},
            extra={"spider": self.crawler.spider},
        )
    finally:
        self.slot.finish_response(result, request)
        self._check_if_closing()
        self._scrape_next()

def _scrape_next(self) -> None:
    assert self.slot is not None  # typing
    while self.slot.queue:
        result, request, queue_dfd = self.slot.next_response_request_deferred()
        _schedule_coro(self._wait_for_processing(result, request, queue_dfd))

async def _scrape(self, result: Response | Failure, request: Request) -> None:
    """Handle the downloaded response or failure through the spider callback/errback."""
    if not isinstance(result, (Response, Failure)):
        raise TypeError(
            f"Incorrect type: expected Response or Failure, got {type(result)}: {result!r}"
        )

    output: Iterable[Any] | AsyncIterator[Any]
    if isinstance(result, Response):
        try:
            # call the spider middlewares and the request callback with the response
            output = await self.spidermw.scrape_response_async(
                self.call_spider_async, result, request
            )
        except Exception:
            self.handle_spider_error(Failure(), request, result)
        else:
            await self.handle_spider_output_async(output, request, result)
        return

    if result.check(CloseSpider):
        exc = result.value
        assert isinstance(exc, CloseSpider)  # typing
        _schedule_coro(
            self.crawler.engine.close_spider_async(reason=exc.reason or "cancelled")
        )
        return

    try:
        # call the request errback with the downloader error
        output = await self.call_spider_async(result, request)
    except Exception as spider_exc:
        # the errback didn't silence the exception
        assert self.crawler.spider
        if not result.check(IgnoreRequest):
            logkws = self.logformatter.download_error(
                result, request, self.crawler.spider
            )
            logger.log(
                *logformatter_adapter(logkws),
                extra={"spider": self.crawler.spider},
                exc_info=failure_to_exc_info(result),
            )
        if spider_exc is not result.value:
            # the errback raised a different exception, handle it
            self.handle_spider_error(Failure(), request, result)
    else:
        await self.handle_spider_output_async(output, request, result)

async def _wait_for_processing(
    self, result: Response | Failure, request: Request, queue_dfd: Deferred[None]
) -> None:
    try:
        await self._scrape(result, request)
    except Exception:
        queue_dfd.errback(Failure())
    else:
        queue_dfd.callback(None)  # awaited in enqueue_scrape()

def _add_middleware(self, mw: Any) -> None:
    if hasattr(mw, "process_spider_input"):
        self.methods["process_spider_input"].append(mw.process_spider_input)
        self._check_mw_method_spider_arg(mw.process_spider_input)

    if hasattr(mw, "process_start"):
        self.methods["process_start"].appendleft(mw.process_start)

    process_spider_output = self._get_process_spider_output(mw)
    self.methods["process_spider_output"].appendleft(process_spider_output)
    if process_spider_output is not None:
        self._check_mw_method_spider_arg(process_spider_output)

    process_spider_exception = getattr(mw, "process_spider_exception", None)
    self.methods["process_spider_exception"].appendleft(process_spider_exception)
    if process_spider_exception is not None:
        self._check_mw_method_spider_arg(process_spider_exception)

async def _process_spider_input(
    self,
    scrape_func: ScrapeFunc[_T],
    response: Response,
    request: Request,
) -> Iterable[_T] | AsyncIterator[_T]:
    for method in self.methods["process_spider_input"]:
        assert method is not None
        try:
            if method in self._mw_methods_requiring_spider:
                result = method(response=response, spider=self._spider)
            else:
                result = method(response=response)
            if result is not None:
                msg = (
                    f"{global_object_name(method)} must return None "
                    f"or raise an exception, got {type(result)}"
                )
                raise _InvalidOutput(msg)
        except _InvalidOutput:
            raise
        except Exception:
            return await scrape_func(Failure(), request)
    return await scrape_func(response, request)

def _process_spider_exception(
    self,
    response: Response,
    exception: Exception,
    start_index: int = 0,
) -> MutableAsyncChain[_T]:
    # don't handle _InvalidOutput exception
    if isinstance(exception, _InvalidOutput):
        raise exception
    method_list = islice(
        self.methods["process_spider_exception"], start_index, None
    )
    for method_index, method in enumerate(method_list, start=start_index):
        if method is None:
            continue
        if method in self._mw_methods_requiring_spider:
            result = method(
                response=response, exception=exception, spider=self._spider
            )
        else:
            result = method(response=response, exception=exception)
        if isinstance(result, (Iterable, AsyncIterator)):
            # stop exception handling by handing control over to the
            # process_spider_output chain if an iterable has been returned
            if isinstance(result, Iterable):
                result = as_async_generator(result)
            return self._process_spider_output(response, result, method_index + 1)
        if result is None:
            continue
        msg = (
            f"{global_object_name(method)} must return None "
            f"or an iterable, got {type(result)}"
        )
        raise _InvalidOutput(msg)
    # Every remaining middleware declined to handle the exception, so the
    # outer process_spider_output layers must let it through instead of
    # offering it to those middlewares again.
    with suppress(AttributeError):
        exception._spidermw_unhandled = True  # type: ignore[attr-defined]
    raise exception

def _process_spider_output(
    self,
    response: Response,
    result: AsyncIterator[_T],
    start_index: int = 0,
) -> MutableAsyncChain[_T]:
    # items in this iterable do not need to go through the process_spider_output
    # chain, they went through it already from the process_spider_exception method
    recovered: MutableAsyncChain[_T] = MutableAsyncChain()
    method_list = islice(self.methods["process_spider_output"], start_index, None)
    for method_index, method in enumerate(method_list, start=start_index):
        if method is None:
            continue
        if method in self._mw_methods_requiring_spider:
            result = method(response=response, result=result, spider=self._spider)
        else:
            result = method(response=response, result=result)
        result = self._evaluate_iterable(
            response, result, method_index + 1, recovered
        )
    return MutableAsyncChain(result, recovered)

async def scrape_response_async(
    self,
    scrape_func: ScrapeFunc[_T],
    response: Response,
    request: Request,
) -> MutableAsyncChain[_T]:
    if not self.crawler:
        raise RuntimeError(
            "scrape_response_async() called on a SpiderMiddlewareManager"
            " instance created without a crawler."
        )
    try:
        it: Iterable[_T] | AsyncIterator[_T] = await self._process_spider_input(
            scrape_func, response, request
        )
        ait = it if isinstance(it, AsyncIterator) else as_async_generator(it)
        return await self._process_callback_output(response, ait)
    except Exception as ex:
        await _process_pending_io()
        return self._process_spider_exception(response, ex)

async def process_start(
    self, spider: Spider | None = None
) -> AsyncIterator[Any] | None:
    if spider:
        if self.crawler:
            msg = (
                "Passing a spider argument to SpiderMiddlewareManager.process_start() is deprecated"
                " and the passed value is ignored."
            )
        else:
            msg = (
                "Passing a spider argument to SpiderMiddlewareManager.process_start() is deprecated,"
                " SpiderMiddlewareManager should be instantiated with a Crawler instance instead."
            )
        warn(msg, category=ScrapyDeprecationWarning, stacklevel=2)
        self._set_compat_spider(spider)
    start = self._spider.start()
    if not hasattr(start, "__aiter__"):
        if iscoroutine(start):
            start.close()
        start = self._reject_start(start)
    return await self._process_chain("process_start", start)

def _get_process_spider_output(mw: Any) -> Callable[..., Any] | None:
    normal_method: Callable[..., Any] | None = getattr(
        mw, "process_spider_output", None
    )
    async_method: Callable[..., Any] | None = getattr(
        mw, "process_spider_output_async", None
    )
    if not async_method:
        if normal_method and not isasyncgenfunction(normal_method):
            raise TypeError(
                f"Middleware {global_object_name(mw.__class__)} doesn't support"
                f" asynchronous spider output. Its process_spider_output() method"
                f" should be an async generator function or it should additionally"
                f" define a process_spider_output_async() method."
            )
        return normal_method
    if not normal_method:
        logger.error(
            f"Middleware {global_object_name(mw.__class__)} has"
            f" process_spider_output_async() without process_spider_output(),"
            f" skipping this method. Please rename it to process_spider_output()."
        )
        return None
    if not isasyncgenfunction(async_method):
        logger.error(
            f"{global_object_name(async_method)} is not "
            f"an async generator function, skipping this method."
        )
        return normal_method
    if isasyncgenfunction(normal_method):
        logger.error(
            f"{global_object_name(normal_method)} is an async "
            f"generator function while process_spider_output_async() exists, "
            f"skipping both methods. Please remove process_spider_output_async()."
        )
        return None
    return async_method

def _handle_events(self, events: list[Event]) -> None:
    """Private method which acts as a bridge between the events
    received from the HTTP/2 data and the handlers in this class.

    Arguments:
        events -- A list of events that the remote peer triggered by sending data
    """
    for event in events:
        if isinstance(event, ConnectionTerminated):
            self.connection_terminated(event)
        elif isinstance(event, DataReceived):
            self.data_received(event)
        elif isinstance(event, ResponseReceived):
            self.response_received(event)
        elif isinstance(event, StreamEnded):
            self.stream_ended(event)
        elif isinstance(event, StreamReset):
            self.stream_reset(event)
        elif isinstance(event, WindowUpdated):
            self.window_updated(event)
        elif isinstance(event, SettingsAcknowledged):
            self.settings_acknowledged(event)
        elif isinstance(event, UnknownFrameReceived):
            logger.warning("Unknown frame received: %s", event.frame)

def data_received(self, event: DataReceived) -> None:
    try:
        stream = self.streams[event.stream_id]
    except KeyError:
        pass  # We ignore server-initiated events
    else:
        stream.receive_data(event.data, event.flow_controlled_length)

def response_received(self, event: ResponseReceived) -> None:
    try:
        stream = self.streams[event.stream_id]
    except KeyError:
        pass  # We ignore server-initiated events
    else:
        stream.receive_headers(cast("list[tuple[str, str]]", event.headers))

def stream_ended(self, event: StreamEnded) -> None:
    try:
        stream = self.pop_stream(event.stream_id)
    except KeyError:
        pass  # We ignore server-initiated events
    else:
        stream.close(StreamCloseReason.ENDED, from_protocol=True)

def stream_reset(self, event: StreamReset) -> None:
    try:
        stream = self.pop_stream(event.stream_id)
    except KeyError:
        pass  # We ignore server-initiated events
    else:
        stream.close(StreamCloseReason.RESET, from_protocol=True)

def window_updated(self, event: WindowUpdated) -> None:
    if event.stream_id != 0:
        self.streams[event.stream_id].receive_window_update()
    else:
        # Send leftover data for all the streams
        for stream in self.streams.values():
            stream.receive_window_update()

def get_connection(
    self, key: ConnectionKey, uri: URI, endpoint: HostnameEndpoint
) -> Deferred[H2ClientProtocol]:
    if key in self._pending_requests:
        # Received a request while connecting to remote
        # Create a deferred which will fire with the H2ClientProtocol
        # instance
        d: Deferred[H2ClientProtocol] = Deferred()
        self._pending_requests[key].append(d)
        return d

    # Check if we already have a connection to the remote
    conn = self._connections.get(key, None)
    if conn:
        # Return this connection instance wrapped inside a deferred
        return defer.succeed(conn)

    # No connection is established for the given URI
    return self._new_connection(key, uri, endpoint)

def close_connections(self) -> None:
    """Close all the HTTP/2 connections and remove them from pool."""
    for conn in self._connections.values():
        assert conn.transport is not None  # typing
        conn.transport.abortConnection()

def receive_headers(self, headers: list[tuple[str, str]]) -> None:
    for name, value in headers:
        if name == ":status":
            # it's a pseudo-header
            self._response["status"] = int(value)
        else:
            self._response["headers"].appendlist(name, value)

    expected_size = int(self._response["headers"].get(b"Content-Length", -1))

    if stop_download := check_stop_download(
        signals.headers_received,
        self._crawler,
        self._request,
        headers=self._response["headers"],
        body_length=expected_size if expected_size >= 0 else None,
    ):
        self._stop_download = stop_download
        self.reset_stream(StreamCloseReason.STOP_DOWNLOAD)
        return

    # Check if we exceed the allowed max data size which can be received
    if self._download_maxsize and expected_size > self._download_maxsize:
        self.reset_stream(StreamCloseReason.MAXSIZE_EXCEEDED)
        return

    if self._log_warnsize:
        self.metadata["reached_warnsize"] = True
        warning_msg = get_warnsize_msg(
            expected_size, self._download_warnsize, self._request, expected=True
        )
        logger.warning(warning_msg)

def _slot_jitter(slot_settings: dict[str, Any], default: float) -> float:
    """Return the jitter of a :setting:`DOWNLOAD_SLOTS` entry, from its
    ``jitter`` key, its deprecated ``randomize_delay`` key, or *default*."""
    if "jitter" in slot_settings:
        return float(slot_settings["jitter"])
    if "randomize_delay" in slot_settings:
        warnings.warn(
            "The randomize_delay key of the DOWNLOAD_SLOTS setting is "
            "deprecated, use jitter instead: it takes the magnitude of the "
            "random variation as a number, e.g. 0.5 for the ±50% that "
            "randomize_delay enables, or 0 to disable it.",
            category=ScrapyDeprecationWarning,
            stacklevel=3,
        )
        return 0.5 if slot_settings["randomize_delay"] else 0.0
    return default

def get_slot_key(self, request: Request) -> str:
    meta_slot: str | None = request.meta.get(self.DOWNLOAD_SLOT)
    if meta_slot is not None:
        return meta_slot

    key = urlparse_cached(request).hostname or ""
    if self.ip_concurrency:
        key = dnscache.get(key, key)

    return key

async def _wait_for_download(
    self, slot: Slot, request: Request, queue_dfd: Deferred[Response]
) -> None:
    try:
        response = await self._download(slot, request)
    except Exception:
        if not queue_dfd.called:
            queue_dfd.errback(Failure())
    else:
        queue_dfd.callback(response)  # awaited in _enqueue_request()

async def stop(self) -> int:
    self._accepting_requests = False

    dropped_count = 0

    for slot in self.slots.values():
        slot.close()
        while slot.queue:
            request, queue_dfd = slot.queue.popleft()
            dropped_count += 1
            if not queue_dfd.called:
                queue_dfd.errback(
                    Failure(
                        DownloadCancelledError(
                            "Request dropped due to fast downloader shutdown"
                        )
                    )
                )
            self.signals.send_catch_log(
                signal=signals.request_left_downloader,
                request=request,
                spider=self.crawler.spider,
            )

    cancelled_dfds: list[Deferred[None]] = []
    for download_dfd in list(self._download_tasks.values()):
        if download_dfd.called:
            continue
        dropped_count += 1
        download_dfd.cancel()
        cancelled_dfds.append(download_dfd)

    if cancelled_dfds:
        # Wait for the cancellations themselves to settle, e.g. the
        # _download_tasks entries to be popped by _download_task_done(),
        # instead of guessing how many event loop iterations that takes.
        await maybe_deferred_to_future(
            DeferredList(cancelled_dfds, consumeErrors=True)
        )

    return dropped_count

def _slot_gc(self, age: float = 60) -> None:
    mintime = monotonic() - age
    for key, slot in list(self.slots.items()):
        if not slot.active and slot.lastseen + slot.delay <= mintime:
            self.slots.pop(key).close()

def _add_middleware(self, mw: Any) -> None:
    if hasattr(mw, "process_request"):
        self.methods["process_request"].append(mw.process_request)
        self._check_mw_method_spider_arg(mw.process_request)
    process_response = getattr(mw, "process_response", None)
    self.methods["process_response"].appendleft(process_response)
    if process_response is not None:
        self._check_mw_method_spider_arg(process_response)
    process_exception = getattr(mw, "process_exception", None)
    self.methods["process_exception"].appendleft(process_exception)
    if process_exception is not None:
        self._check_mw_method_spider_arg(process_exception)

async def _process_request(
    self,
    request: Request,
    download_func: Callable[[Request], Coroutine[Any, Any, Response]],
) -> Response | Request:
    for method in self.methods["process_request"]:
        assert method is not None
        response = await ensure_awaitable(
            self._handle_mw_method(method, request=request),
            _warn=global_object_name(method),
        )
        if response is not None and not isinstance(response, (Response, Request)):
            raise _InvalidOutput(
                f"Middleware {method.__qualname__} must return None, Response or "
                f"Request, got {response.__class__.__name__}"
            )
        if response:
            return response
    return await download_func(request)

async def _process_response(
    self, response: Response | Request, request: Request, index: int = 0
) -> Response | Request:
    if response is None:
        raise TypeError("Received None in process_response")

    methods = self.methods["process_response"]
    while index < len(methods):
        if isinstance(response, Request):
            return response
        method = methods[index]
        index += 1
        if method is None:
            continue
        try:
            result = await ensure_awaitable(
                self._handle_mw_method(method, request=request, response=response),
                _warn=global_object_name(method),
            )
        except Exception as ex:
            if not self._response_exceptions:
                # CloseSpider closes the spider either way, it never
                # reaches process_exception().
                if not isinstance(ex, CloseSpider):
                    self._warn_response_exception(method, ex, index)
                raise
            response, index = await self._process_exception(ex, request, index)
            continue

        if not isinstance(result, (Response, Request)):
            raise _InvalidOutput(
                f"Middleware {method.__qualname__} must return Response or Request, "
                f"got {type(result)}"
            )
        response = result
    return response

def _patched_idna_text(octets: bytes) -> str:
    try:
        return _original_idna_text(octets)
    except UnicodeError:
        if not _HOSTNAME.match(octets):
            raise
        return octets.decode("idna")

def _install_twisted_idna_fallbacks() -> None:
    """Patch ``_idnaBytes()``/``_idnaText()`` wherever Twisted uses them for
    client connections.

    Each module binds them at import time, so every reference needs patching,
    not just ``twisted.internet._idna``. Names that are missing or already
    patched are left alone.
    """
    from twisted.internet import _resolver, _sslverify, endpoints  # noqa: PLC0415

    patches = (
        ("_idnaBytes", _original_idna_bytes, _patched_idna_bytes),
        ("_idnaText", _original_idna_text, _patched_idna_text),
    )
    for module in (_idna, _resolver, _sslverify, endpoints):
        for name, original, patched in patches:
            if getattr(module, name, None) is original:
                setattr(module, name, patched)

def __getattr__(name: str) -> Any:
    if name == "DEFAULT_CIPHERS":
        warnings.warn(
            "scrapy.core.downloader.tls.DEFAULT_CIPHERS is deprecated.",
            ScrapyDeprecationWarning,
            stacklevel=2,
        )
        return AcceptableCiphers.fromOpenSSLCipherString("DEFAULT")
    deprecated = {
        "METHOD_TLS": "TLS",
        "METHOD_TLSv10": "TLSv1.0",
        "METHOD_TLSv11": "TLSv1.1",
        "METHOD_TLSv12": "TLSv1.2",
        "openssl_methods": _openssl_methods,
    }
    if name in deprecated:
        warnings.warn(
            f"scrapy.core.downloader.tls.{name} is deprecated.",
            ScrapyDeprecationWarning,
            stacklevel=2,
        )
        return deprecated[name]
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

def _identityVerifyingInfoCallback(
    self, connection: SSL.Connection, where: int, ret: Any
) -> None:
    if where & SSL.SSL_CB_HANDSHAKE_DONE:
        try:
            if self._hostnameIsDnsName:
                verify_hostname(connection, self._hostnameASCII)
            else:
                verify_ip_address(connection, self._hostnameASCII)
        except (CertificateError, VerificationError) as e:
            logger.warning(
                'Remote certificate is not valid for hostname "%s"; %s',
                self._hostnameASCII,
                e,
            )
    else:
        super()._identityVerifyingInfoCallback(connection, where, ret)  # type: ignore[misc]

def _get_cert_options_kwargs(self) -> dict[str, Any]:
    kwargs: dict[str, Any] = {
        "fixBrokenPeers": True,
        "acceptableCiphers": self.tls_ciphers,
    }
    if self.tls_min_version or self.tls_max_version:
        kwargs.update(
            _get_cert_options_version_kwargs(
                self.tls_min_version, self.tls_max_version
            )
        )
    # when ScrapyClientContextFactory is removed self._ssl_method can just be None by default
    elif self._ssl_method != SSL.SSLv23_METHOD:
        kwargs["method"] = self._ssl_method
    return kwargs

def creatorForNetloc(self, hostname: bytes, port: int) -> ClientTLSOptions:
    if not self._verify_certificates:
        # Our options class is needed to skip verification errors
        if TWISTED_TLS_NEW_IMPL:
            return _ScrapyClientTLSOptions26(
                self._get_cert_options()._makeTLSConnection,
                hostname.decode("ascii"),
            )
        return _ScrapyClientTLSOptions(
            hostname.decode("ascii"),  # type: ignore[arg-type]
            self._get_context(),  # type: ignore[arg-type]
        )
    # Otherwise use the normal Twisted function.
    creator = optionsForClientTLS(
        hostname=hostname.decode("ascii"),
        extraCertificateOptions=self._get_cert_options_kwargs(),
    )
    if _get_keylog_filename():
        # This creator builds its own certificate options, so its context
        # doesn't come from _ScrapyCertificateOptions.
        _set_keylog_callback(_get_creator_context(creator))
    return cast("ClientTLSOptions", creator)

async def download_request(self, request: Request) -> Response:
    if not self.supports_proxies and request.meta.get("proxy"):
        raise NotImplementedError(f"{type(self).__name__} doesn't support proxies.")
    if not self.supports_per_request_bindaddress and request.meta.get(
        "bindaddress"
    ):
        logger.error(
            f"The 'bindaddress' request meta key is not supported by"
            f" {type(self).__name__} and will be ignored."
        )
    timeout: float = request.meta.get(
        "download_timeout", self._DEFAULT_CONNECT_TIMEOUT
    )
    start_time = time.monotonic()
    async with self._make_request(request, timeout) as response:
        request.meta["download_latency"] = time.monotonic() - start_time
        return await self._read_response(response, request)

def _extract_proxy_url_with_creds(self, request: Request) -> str | None:
    """Return the proxy URL with the userinfo added based on the
    Proxy-Authorization header.

    This is useful for handlers that cannot take the proxy headers
    separately.
    """
    proxy_url, auth_header = self._extract_proxy(request)
    if proxy_url is None or auth_header is None:
        return proxy_url
    scheme, token = auth_header.split(" ", 1)
    if scheme != "Basic":
        raise ValueError(
            f"Expected Basic auth in Proxy-Authorization, got {scheme}"
        )
    user, password = (
        base64.b64decode(token).decode(self._proxy_auth_encoding).split(":", 1)
    )
    parts = urlsplit(proxy_url)
    netloc = f"{quote(user)}:{quote(password)}@{parts.netloc}"
    return parts._replace(netloc=netloc).geturl()

async def download_request(self, request: Request) -> Response:
    uri = parse_data_uri(request.url)
    respcls = responsetypes.from_mimetype(uri.media_type)

    if issubclass(respcls, TextResponse) and uri.media_type.split("/")[0] == "text":
        charset = uri.media_type_parameters.get("charset")
        return respcls(url=request.url, body=uri.data, encoding=charset)

    return respcls(url=request.url, body=uri.data)

def _get_handler(self, scheme: str) -> DownloadHandlerProtocol | None:
    """Lazy-load the downloadhandler for a scheme
    only on the first request for that scheme.
    """
    if scheme in self._handlers:
        return self._handlers[scheme]
    if scheme in self._notconfigured:
        return None
    if scheme not in self._schemes:
        self._notconfigured[scheme] = "no handler available for that scheme"
        return None

    return self._load_handler(scheme)

async def download_request_async(self, request: Request) -> Response:
    scheme = urlparse_cached(request).scheme
    handler = self._get_handler(scheme)
    if not handler:
        raise NotSupported(
            f"Unsupported URL scheme '{scheme}': {self._notconfigured[scheme]}"
        )
    assert self._crawler.spider
    if scheme in self._old_style_handlers:  # pragma: no cover
        return await maybe_deferred_to_future(
            cast(
                "Deferred[Response]",
                handler.download_request(request, self._crawler.spider),  # type: ignore[call-arg]
            )
        )
    return await handler.download_request(request)

async def start(
    self, connection: aiohttp.connector.Connection
) -> aiohttp.ClientResponse:
    transport = connection.transport
    assert transport is not None
    self._peername = transport.get_extra_info("peername")
    ssl_object = transport.get_extra_info("ssl_object")
    if isinstance(ssl_object, ssl.SSLObject):
        self._ssl_object = ssl_object
    return await super().start(connection)

def _make_client(self, proxy_url: str | None = None) -> httpx.AsyncClient:
    if proxy_url:
        if proxy_url.startswith("https:") and not self._verify_certificates:
            proxy_ssl_context = _make_insecure_ssl_ctx()
        else:
            proxy_ssl_context = None
        proxy = httpx.Proxy(proxy_url, ssl_context=proxy_ssl_context)
    else:
        proxy = None

    client = httpx.AsyncClient(
        cookies=NullCookieJar(),
        transport=httpx.AsyncHTTPTransport(
            verify=self._ssl_context,
            local_address=self._bind_host,
            http2=self._enable_h2,
            limits=self._limits,
            trust_env=False,
            proxy=proxy,
        ),
    )
    # https://github.com/pydantic/httpx2/issues/368
    for header_name in ("accept", "accept-encoding", "user-agent"):
        client.headers.pop(header_name, None)
    return client

def _get_client(self, proxy_url: str | None) -> httpx.AsyncClient:
    if proxy_url is None:
        return self._default_client
    if cached := self._proxy_clients.get(proxy_url):
        return cached
    client = self._make_client(proxy_url)
    self._proxy_clients[proxy_url] = client
    return client

async def _make_request(
    self, request: Request, timeout: float
) -> AsyncIterator[httpx.Response]:
    proxy = self._extract_proxy_url_with_creds(request)
    if proxy and proxy.startswith("socks") and not HAS_SOCKS:  # pragma: no cover
        raise ValueError(
            f"SOCKS proxy support in {type(self).__name__} requires the 'httpx2[socks]' extra to be installed."
        )
    client = self._get_client(proxy)
    headers = self._request_headers(request).to_tuple_list()

    try:
        async with client.stream(
            request.method,
            request.url,
            content=request.body,
            headers=headers,
            timeout=timeout,
        ) as response:
            yield response
    except httpx.TimeoutException as e:
        raise DownloadTimeoutError(
            f"Getting {request.url} took longer than {timeout} seconds."
        ) from e
    except httpx.UnsupportedProtocol as e:
        raise UnsupportedURLSchemeError(str(e)) from e
    except httpx.ConnectError as e:
        if any(isinstance(c, gaierror) for c in _iter_exc_causes(e)):
            raise CannotResolveHostError(str(e)) from e
        raise DownloadConnectionRefusedError(str(e)) from e
    except httpx.ProxyError as e:
        raise DownloadConnectionRefusedError(str(e)) from e
    except DOWNLOAD_FAILED_EXCEPTIONS as e:  # pylint: disable=catching-non-exception
        raise DownloadFailedError(str(e)) from e

def _cb_timeout(self, result: _T, request: Request, url: str, timeout: float) -> _T:
    if self._timeout_cl.active():
        self._timeout_cl.cancel()
        return result
    # needed for HTTPS requests, otherwise _ResponseReader doesn't
    # receive connectionLost()
    if self._txresponse:
        self._txresponse._transport.stopProducing()

    raise DownloadTimeoutError(f"Getting {url} took longer than {timeout} seconds.")

def lineReceived(self, line: bytes) -> None:
    # A copy of twisted.web._newclient.HTTPParser.lineReceived() where the
    # header name and value are only extracted from header lines that have
    # a colon.

    # Handle the normal CR LF case.
    line = line.removesuffix(b"\r")

    if self.state == STATUS:
        self.statusReceived(line)  # type: ignore[no-untyped-call]
        self.state = HEADER
        return

    # HEADER is the only other state in which lines are received, as the
    # parser switches to raw mode for the response body.
    if not line or line[0] not in b" \t":
        if self._partialHeader is not None:
            header = b"".join(self._partialHeader)
            if b":" in header:
                name, value = header.split(b":", 1)
                self.headerReceived(name, value.strip())  # type: ignore[no-untyped-call]
            else:
                logger.debug(
                    f"Skipping the bad response header line {header!r}, as "
                    f"it has no colon."
                )
        if not line:
            # Empty line means the header section is over.
            self.allHeadersReceived()  # type: ignore[no-untyped-call]
        else:
            # Line not beginning with LWS is another header.
            self._partialHeader = [line]
    else:
        # A line beginning with LWS is a continuation of a header begun on
        # a previous line.
        self._partialHeader.append(line)  # type: ignore[union-attr]

def __init__(
    self,
    response: TextResponse | None = None,
    text: str | None = None,
    type: SelectorType | None = None,  # noqa: A002
    root: Any | None = _NOT_SET,
    **kwargs: Any,
):
    if response is not None and text is not None:
        raise ValueError(
            f"{self.__class__.__name__}.__init__() received both response and text"
        )

    # Any other response, e.g. a plain-text one, keeps type unset, so that
    # parsel determines it from the body.
    if type is None and root is _NOT_SET:
        if isinstance(response, XmlResponse):
            type = "xml"  # noqa: A001
        elif isinstance(response, JsonResponse):
            type = "json"  # noqa: A001
        elif response is None or isinstance(response, HtmlResponse):
            type = "html"  # noqa: A001

    if text is not None:
        response = _response_from_text(text, type)

    if response is not None:
        # parsel only treats bytes and text equivalently for "html" and
        # "xml", and treats an empty body as absent, unlike empty text.
        if PARSEL_BODY_ENCODING_FIXED and type in ("html", "xml") and response.body:
            encoding = response.encoding
            # None means the encoding was declared, not inferred from
            # the body, so the body hasn't been decoded as a side effect.
            if response._cached_ubody is None:
                kwargs["body"] = response.body
                kwargs["encoding"] = encoding
                text = None
            else:
                text = response.text
        else:
            text = response.text
        kwargs.setdefault("base_url", get_base_url(response))

    self.response = response

    if root is not _NOT_SET:
        kwargs["root"] = root

    super().__init__(text=text, type=type, **kwargs)

def verify_url_scheme(url: str) -> str:
    """Check url for scheme and insert https if none found."""
    parsed = urlparse(url)
    if parsed.scheme == "" and parsed.netloc == "":
        parsed = urlparse("//" + url)._replace(scheme="https")
    return parsed.geturl()

def run(self, args: list[str], opts: argparse.Namespace) -> None:
    assert self.settings is not None
    if opts.list:
        self._list_templates()
        return
    if opts.dump:
        template_file = self._find_template(opts.dump)
        if template_file:
            print(template_file.read_text(encoding="utf-8"))
        return
    if len(args) != 2:
        raise UsageError

    name, url = args[0:2]
    url = verify_url_scheme(url)
    module = sanitize_module_name(name)

    if self.settings.get("BOT_NAME") == module:
        print("Cannot create a spider with the same name as your project")
        return

    if not opts.force and self._spider_exists(name):
        return

    template_file = self._find_template(opts.template)
    if template_file:
        spider_file = self._genspider(
            module, name, url, opts.template, template_file
        )
        if opts.edit:
            self.exitcode = _edit_file(self.settings["EDITOR"], spider_file)

def _find_template(self, template: str) -> Path | None:
    filename = template if template.endswith(".tmpl") else f"{template}.tmpl"
    for template_file in (Path(filename), Path(self.templates_dir, filename)):
        if template_file.exists():
            return template_file
    print(
        f"Unable to find template: {template}\n",
        'Use "scrapy genspider --list" to see all available templates.',
    )
    return None

def templates_dir(self) -> str:
    assert self.settings is not None
    return str(
        Path(
            self.settings["TEMPLATES_DIR"] or Path(scrapy.__path__[0], "templates"),
            "spiders",

def run(self, args: list[str], opts: argparse.Namespace) -> None:
    assert self.settings is not None
    settings = self.settings
    if opts.get:
        s = settings.get(opts.get)
        if isinstance(s, BaseSettings):
            print(json.dumps(s.copy_to_dict()))
        else:
            print(s)
    elif opts.getbool:
        print(settings.getbool(opts.getbool))
    elif opts.getint:
        print(settings.getint(opts.getint))
    elif opts.getfloat:
        print(settings.getfloat(opts.getfloat))
    elif opts.getlist:
        print(settings.getlist(opts.getlist))

def run(self, args: list[str], opts: argparse.Namespace) -> None:
    if opts.verbose:
        versions = get_versions()
        width = max(len(n) for (n, _) in versions)
        for name, version in versions:
            print(f"{name:<{width}} : {version}")
    else:
        print(f"Scrapy {scrapy.__version__}")

def _report_crawl_errors(
    crawl: Awaitable[None], spidername: str, result: TextTestResult
) -> None:
    """Make an exception that stops *crawl* before its contracts can run show
    up as an error in *result*, instead of being silently discarded."""

    class CrawlTestCase(TestCase):
        # unittest requires a test method, but this one is only reported, never run.
        runTest = staticmethod(lambda: None)

        def __str__(self) -> str:
            return f"[{spidername}] crawl"

    def report(exception: BaseException) -> None:
        result.addError(
            CrawlTestCase(),
            (type(exception), exception, exception.__traceback__),  # type: ignore[arg-type]
        )

    if isinstance(crawl, Deferred):

        def on_failure(failure: Failure) -> None:
            assert failure.value is not None
            report(failure.value)

        crawl.addErrback(on_failure)
    else:
        assert isinstance(crawl, asyncio.Task)

        def on_done(task: asyncio.Task[None]) -> None:
            if not task.cancelled() and (exception := task.exception()) is not None:
                report(exception)

        crawl.add_done_callback(on_done)

def printSummary(self, start: float, stop: float) -> None:
    write = self.stream.write
    writeln = self.stream.writeln

    run = self.testsRun
    plural = "s" if run != 1 else ""

    writeln(self.separator2)
    writeln(f"Ran {run} contract{plural} in {stop - start:.3f}s")
    writeln()

    infos = []
    if not self.wasSuccessful():
        write("FAILED")
        failed, errored = map(len, (self.failures, self.errors))
        if failed:
            infos.append(f"failures={failed}")
        if errored:
            infos.append(f"errors={errored}")
    else:
        write("OK")

    if infos:
        writeln(f" ({', '.join(infos)})")
    else:
        write("\n")

def process_options(self, args: list[str], opts: argparse.Namespace) -> None:
    """Set settings based on the command line options."""
    assert self.settings is not None
    try:
        self.settings.setdict(arglist_to_dict(opts.set), priority="cmdline")
    except ValueError:
        raise UsageError(
            "Invalid -s value, use -s NAME=VALUE", print_help=False
        ) from None

    if opts.logfile:
        self.settings.set("LOG_ENABLED", True, priority="cmdline")
        self.settings.set("LOG_FILE", opts.logfile, priority="cmdline")

    if opts.loglevel:
        self.settings.set("LOG_ENABLED", True, priority="cmdline")
        self.settings.set("LOG_LEVEL", opts.loglevel, priority="cmdline")

    if opts.nolog:
        self.settings.set("LOG_ENABLED", False, priority="cmdline")

    if opts.pidfile:
        Path(opts.pidfile).write_text(
            str(os.getpid()) + os.linesep, encoding="utf-8"
        )

    if opts.pdb:
        try:
            import ipdb  # noqa: T100,PLC0415
        except ImportError:
            pass
        else:
            sys.modules["pdb"] = ipdb
        logging.root.addHandler(_PdbHandler(level=logging.ERROR))

def process_options(self, args: list[str], opts: argparse.Namespace) -> None:
    super().process_options(args, opts)
    try:
        opts.spargs = arglist_to_dict(opts.spargs)
    except ValueError:
        raise UsageError(
            "Invalid -a value, use -a NAME=VALUE", print_help=False
        ) from None
    if opts.output or opts.overwrite_output:
        assert self.settings is not None
        feeds = feed_process_params_from_cli(
            self.settings,
            opts.output,
            overwrite_output=opts.overwrite_output,
        )
        self.settings.set("FEEDS", feeds, priority="cmdline")

def _run_crawler(
    self, spidercls: type[Spider] | str, opts: argparse.Namespace
) -> None:
    assert self.crawler_process is not None
    crawler = self._create_crawler(spidercls)
    self.crawler_process.crawl(crawler, **opts.spargs)
    self.crawler_process.start()
    if self.crawler_process.bootstrap_failed or crawler.stats.get_value(
        "finish_reason_error", False
    ):
        self.exitcode = 1

def _warn_if_feeds_unused(self, sender: Crawler, **kwargs: Any) -> None:
    if (
        sender.settings.getdict("FEEDS")
        and sender.get_extension(FeedExporter) is None
    ):
        logger.warning(
            "The FeedExporter extension is not enabled, so no item will be "

def run(self, args: list[str], opts: argparse.Namespace) -> None:
    if len(args) < 1:
        raise UsageError
    if len(args) > 1:
        raise UsageError(
            "running 'scrapy crawl' with more than one spider is not supported"
        )
    self._run_crawler(args[0], opts)

def run(self, args: list[str], opts: argparse.Namespace) -> None:
    if len(args) != 1:
        raise UsageError
    filename = Path(args[0])
    if not filename.exists():
        raise UsageError(f"File not found: {filename}\n")
    try:
        module = _import_file(filename)
    except (ImportError, ValueError) as e:
        raise UsageError(f"Unable to load {str(filename)!r}: {e}\n") from e
    spclasses = list(iter_spider_classes(module))
    if not spclasses:
        raise UsageError(f"No spider found in file: {filename}\n")
    self._run_crawler(spclasses.pop(), opts)

def _print_response(self, response: Response, opts: Namespace) -> None:
    if opts.headers:
        assert response.request
        self._print_headers(response.request.headers, b">")
        print(">")
        self._print_headers(response.headers, b"<")
    else:
        self._print_bytes(response.body)

def max_level(self) -> int:
    max_items, max_requests = 0, 0
    if self.items:
        max_items = max(self.items)
    if self.requests:
        max_requests = max(self.requests)
    return max(max_items, max_requests)

def iterate_spider_output(self, result: Any) -> Iterable[Any] | Deferred[Any]:
    d: Deferred[Any]
    if inspect.isasyncgen(result):
        d = deferred_from_coro(
            collect_asyncgen(aiter_errback(result, self.handle_exception))
        )
        return d.addCallback(self.iterate_spider_output)
    d = deferred_from_coro(result)
    if inspect.iscoroutine(result):
        return d.addCallback(self.iterate_spider_output)
    return arg_to_iter(d)

def print_items(self, lvl: int | None = None, colour: bool = True) -> None:
    if lvl is None:
        items = [item for lst in self.items.values() for item in lst]
    else:
        items = self.items.get(lvl, [])

    print("# Scraped Items ", "-" * 60)
    _colorize.pprint([ItemAdapter(x).asdict() for x in items], colorize=colour)

def print_requests(self, lvl: int | None = None, colour: bool = True) -> None:
    if lvl is not None:
        requests = self.requests.get(lvl, [])
    elif self.requests:
        requests = self.requests[max(self.requests)]
    else:
        requests = []

    print("# Requests ", "-" * 65)
    _colorize.pprint(requests, colorize=colour)

def print_results(self, opts: argparse.Namespace) -> None:
    colour = not opts.nocolour

    if opts.verbose:
        for level in range(1, self.max_level + 1):
            print(f"\n>>> DEPTH LEVEL: {level} <<<")
            if not opts.noitems:
                self.print_items(level, colour)
            if not opts.nolinks:
                self.print_requests(level, colour)
    else:
        print(f"\n>>> STATUS DEPTH LEVEL {self.max_level} <<<")
        if not opts.noitems:
            self.print_items(colour=colour)
        if not opts.nolinks:
            self.print_requests(colour=colour)

def _get_items_and_requests(
    self,
    spider_output: Iterable[Any],
    opts: argparse.Namespace,
    depth: int,
    spider: Spider,
    callback: CallbackT,
) -> tuple[list[Any], list[Request], argparse.Namespace, int, Spider, CallbackT]:
    items, requests = [], []
    for x in spider_output:
        if isinstance(x, Request):
            requests.append(x)
        else:
            items.append(x)
    return items, requests, opts, depth, spider, callback

def get_callback_from_rules(
    self, spider: Spider, response: Response
) -> CallbackT | str | None:
    if getattr(spider, "rules", None):
        for rule in spider.rules:  # type: ignore[attr-defined]
            if rule.link_extractor.matches(response.url):
                return rule.callback or "parse"
    else:
        logger.error(
            "No CrawlSpider rules found in spider %(spider)r, "
            "please specify a callback to use for parsing",
            {"spider": spider.name},
        )
    return None

def set_spidercls(self, url: str, opts: argparse.Namespace) -> None:
    assert self.crawler_process
    spider_loader = self.crawler_process.spider_loader
    if opts.spider:
        try:
            self.spidercls = spider_loader.load(opts.spider)
        except KeyError:
            logger.error(
                "Unable to find spider: %(spider)s", {"spider": opts.spider}
            )
    else:
        self.spidercls = spidercls_for_request(spider_loader, Request(url))
        if not self.spidercls:
            logger.error("Unable to find spider for: %(url)s", {"url": url})

    async def start(spider: Spider) -> AsyncIterator[Any]:
        yield self.prepare_request(spider, Request(url), opts)

    if self.spidercls:
        self.spidercls.start = start  # type: ignore[assignment,method-assign]

def start_parsing(self, url: str, opts: argparse.Namespace) -> None:
    assert self.crawler_process
    assert self.spidercls
    self.pcrawler = self._create_crawler(self.spidercls)
    self.crawler_process.crawl(self.pcrawler, **opts.spargs)
    self.crawler_process.start()
    if self.crawler_process.bootstrap_failed:
        self.exitcode = 1

    if not self.first_response:
        logger.error("No response downloaded for: %(url)s", {"url": url})

def scraped_data(
    self,
    args: tuple[
        list[Any], list[Request], argparse.Namespace, int, Spider, CallbackT
    ],
) -> list[Any]:
    items, requests, opts, depth, spider, callback = args
    if opts.pipelines:
        itemproc = self.pcrawler.engine.scraper.itemproc
        if hasattr(itemproc, "process_item_async"):
            for item in items:
                _schedule_coro(itemproc.process_item_async(item))
        else:
            for item in items:
                itemproc.process_item(item, spider)
    self.add_items(depth, items)
    self.add_requests(depth, requests)

    scraped_data = items if opts.output else []
    if depth < opts.depth:
        for req in requests:
            req.meta["_depth"] = depth + 1
            req.meta["_callback"] = req.callback
            req.callback = callback
        scraped_data += requests

    return scraped_data

def _get_callback(
    self,
    *,
    spider: Spider,
    opts: argparse.Namespace,
    response: Response | None = None,
) -> CallbackT:
    cb: str | CallbackT | None = None
    if response:
        cb = response.meta["_callback"]
    if not cb:
        if opts.callback:
            cb = opts.callback
        elif response and opts.rules and self.first_response == response:
            cb = self.get_callback_from_rules(spider, response)
            if not cb:
                raise ValueError(
                    f"Cannot find a rule that matches {response.url!r} in spider: "
                    f"{spider.name}"
                )
        else:
            cb = "parse"

    if not callable(cb):
        assert cb is not None
        cb_method = getattr(spider, cb, None)
        if callable(cb_method):
            cb = cb_method
        else:
            raise ValueError(
                f"Cannot find callback {cb!r} in spider: {spider.name}"
            )
    assert callable(cb)
    return cb

def process_request_meta(self, opts: argparse.Namespace) -> None:
    if opts.meta:
        try:
            opts.meta = json.loads(opts.meta)
        except ValueError:
            raise UsageError(
                "Invalid -m/--meta value, pass a valid json string to -m or --meta. "
                'Example: --meta=\'{"foo" : "bar"}\'',
                print_help=False,
            ) from None

def process_request_cb_kwargs(self, opts: argparse.Namespace) -> None:
    if opts.cbkwargs:
        try:
            opts.cbkwargs = json.loads(opts.cbkwargs)
        except ValueError:
            raise UsageError(
                "Invalid --cbkwargs value, pass a valid json string to --cbkwargs. "
                'Example: --cbkwargs=\'{"foo" : "bar"}\'',
                print_help=False,
            ) from None

def run(self, args: list[str], opts: argparse.Namespace) -> None:
    # parse arguments
    if not len(args) == 1 or not is_url(args[0]):
        raise UsageError
    url = args[0]

    # prepare spidercls
    self.set_spidercls(url, opts)

    if self.spidercls and opts.depth > 0:
        self.start_parsing(url, opts)
        self.print_results(opts)

def _is_valid_name(self, project_name: str) -> bool:
    def _module_exists(module_name: str) -> bool:
        spec = find_spec(module_name)
        return spec is not None and spec.loader is not None

    if not re.search(r"^[_a-zA-Z]\w*$", project_name):
        print(
            "Error: Project names must begin with a letter and contain"
            " only\nletters, numbers and underscores"
        )
    elif _module_exists(project_name):
        print(f"Error: Module {project_name!r} already exists")
    else:
        return True
    return False

def templates_dir(self) -> str:
    assert self.settings is not None
    return str(
        Path(
            self.settings["TEMPLATES_DIR"] or Path(scrapy.__path__[0], "templates"),
            "project",

def get_processed_request(
    self, request: Request, response: Response | None
) -> Request | None:
    if response is None:
        return request

    if not self._warned:
        found = self._keys & request.meta.keys()
        if found:
            spider_name = type(self.crawler.spider).__name__
            logger.warning(
                f"{spider_name} yielded a request containing internal "
                f"meta keys that were likely copied from response.meta "
                f"and should not be forwarded to new requests: "
                f"{sorted(found)}. See the MetaCopyDetectionMiddleware "
                f"documentation for more information. Source response: "
                f"{response}, target request: {request}",
                extra={"spider": self.crawler.spider},
            )
            self._warned = True

    return request

def referrer(self, response_url: str, request_url: str) -> str | None:
    if (
        self.tls_protected(response_url)
        and self.potentially_trustworthy(request_url)
    ) or not self.tls_protected(response_url):
        return self.origin_referrer(response_url)
    return None

def referrer(self, response_url: str, request_url: str) -> str | None:
    origin = self.origin(response_url)
    if origin == self.origin(request_url):
        return self.stripped_referrer(response_url)
    if (
        self.tls_protected(response_url)
        and self.potentially_trustworthy(request_url)
    ) or not self.tls_protected(response_url):
        return self.origin_referrer(response_url)
    return None

def policy(
    self,
    response: Response | str | None = None,
    request: Request | None = None,
    **kwargs: Unpack[_PolicyKwargs],
) -> ReferrerPolicy:
    """Return the referrer policy to use for *request* based on *request*
    meta, *response* and settings.

    - if a valid policy is set in Request meta, it is used.
    - if the policy is set in meta but is wrong (e.g. a typo error), the
      policy from settings is used
    - if the policy is not set in Request meta, but there is a
      Referrer-Policy header in the parent response, it is used if valid
    - otherwise, the policy from settings is used.
    """
    if "resp_or_url" in kwargs:
        if response is not None:
            raise TypeError("Cannot pass both 'response' and 'resp_or_url'")
        response = kwargs.pop("resp_or_url")
        warn(
            "Passing 'resp_or_url' is deprecated, use 'response' instead.",
            ScrapyDeprecationWarning,
            stacklevel=2,
        )
    if response is None:
        raise TypeError("Missing required argument: 'response'")
    if request is None:
        raise TypeError("Missing required argument: 'request'")
    if isinstance(response, str):
        warn(
            "Passing a response URL to RefererMiddleware.policy() instead "
            "of a Response object is deprecated.",
            ScrapyDeprecationWarning,
            stacklevel=2,
        )
    allow_import_path = True
    policy_name = request.meta.get("referrer_policy")
    if policy_name is None and isinstance(response, Response):
        policy_header = response.headers.get("Referrer-Policy")
        if policy_header is not None:
            policy_name = to_unicode(policy_header.decode("latin1"))
            allow_import_path = False
    if policy_name is None:
        return self.default_policy()
    cls = self._load_policy_class(
        policy_name, warning_only=True, allow_import_path=allow_import_path
    )
    return cls() if cls else self.default_policy()

def get_processed_request(
    self, request: Request, response: Response | None
) -> Request | None:
    if response is None:
        # start requests
        return request
    referrer = self.policy(response, request).referrer(response.url, request.url)
    if referrer is not None:
        request.headers.setdefault("Referer", referrer)
    return request

def _init_depth(self, response: Response) -> None:
    # base case (depth=0)
    if "depth" not in response.meta:
        response.meta["depth"] = 0
        if self.verbose_stats:
            self.stats.inc_value("request_depth_count/0")

def process_spider_input(
    self, response: Response, spider: Spider | None = None
) -> None:
    if 200 <= response.status < 300:  # common case
        return
    meta = response.meta
    if meta.get("handle_httpstatus_all", False):
        return
    if "handle_httpstatus_list" in meta:
        allowed_statuses = meta["handle_httpstatus_list"]
    elif self.handle_httpstatus_all:
        return
    else:
        allowed_statuses = getattr(
            self.crawler.spider,
            "handle_httpstatus_list",
            self.handle_httpstatus_list,
        )
    if response.status in allowed_statuses:
        return
    raise HttpError(response, "Ignoring non-200 response")

def process_spider_output(
    self,
    response: Response | None,
    result: Iterable[Any],
    spider: Spider | None = None,
) -> Iterable[Any]:
    for o in result:
        if (o := self._get_processed(o, response)) is not None:
            yield o

def get_processed_request(
    self, request: Request, response: Response | None
) -> Request | None:
    if response is None:
        return request
    for key in self.sticky_meta_keys:
        if key in response.meta:
            request.meta.setdefault(key, response.meta[key])
    return request

def _add_middleware(self, mw: Any) -> None:
    if hasattr(mw, "open_spider"):
        self.methods["open_spider"].append(mw.open_spider)
        self._check_mw_method_spider_arg(mw.open_spider)
    if hasattr(mw, "close_spider"):
        self.methods["close_spider"].appendleft(mw.close_spider)
        self._check_mw_method_spider_arg(mw.close_spider)
    if hasattr(mw, "process_item"):
        self.methods["process_item"].append(mw.process_item)
        self._check_mw_method_spider_arg(mw.process_item)

def get_media_requests(
    self, item: Any, info: MediaPipeline.SpiderInfo
) -> list[Request]:
    urls = ItemAdapter(item).get(self.images_urls_field, [])
    if not isinstance(urls, list):
        raise TypeError(
            f"{self.images_urls_field} must be a list of URLs, got {type(urls).__name__}. "
        )
    return [Request(u, callback=NO_CALLBACK) for u in urls]

def item_completed(
    self, results: list[FileInfoOrError], item: Any, info: MediaPipeline.SpiderInfo
) -> Any:
    with suppress(KeyError):
        ItemAdapter(item)[self.images_result_field] = [x for ok, x in results if ok]
    return item

async def process_item(self, item: Any, spider: Spider | None = None) -> Any:
    info = self.spiderinfo
    requests = arg_to_iter(self.get_media_requests(item, info))
    coros = [self._process_request(r, info, item) for r in requests]
    results: list[FileInfoOrError] = []
    if coros:
        if is_asyncio_available():
            results_asyncio = await asyncio.gather(*coros, return_exceptions=True)
            for res in results_asyncio:
                if isinstance(res, BaseException):
                    results.append((False, Failure(res)))
                else:
                    results.append((True, res))
        else:
            results = await cast(
                "Deferred[list[FileInfoOrError]]",
                DeferredList(
                    (deferred_from_coro(coro) for coro in coros), consumeErrors=True
                ),
            )
    return self.item_completed(results, item, info)

async def _process_request(
    self, request: Request, info: SpiderInfo, item: Any
) -> FileInfo:
    fp = self._fingerprinter.fingerprint(request)

    eb: Callable[[Failure], FileInfo] | None = request.errback
    request.callback = NO_CALLBACK
    request.errback = None

    # Return cached result if request was already seen
    if fp in info.downloaded:
        await _process_pending_io()
        info.downloaded.move_to_end(fp)
        cached_result = info.downloaded[fp]
        if isinstance(cached_result, Failure):
            if eb:
                return eb(cached_result)
            cached_result.raiseException()
        return cached_result

    # Otherwise, wait for result
    wad: Deferred[FileInfo] = Deferred()
    if eb:
        wad.addErrback(eb)
    info.waiting[fp].append(wad)

    # Check if request is downloading right now to avoid doing it twice
    if fp in info.downloading:
        return await maybe_deferred_to_future(wad)

    # Download request checking media_to_download hook output first
    info.downloading.add(fp)
    await _process_pending_io()
    result: FileInfo | Failure
    try:
        file_info: FileInfo | None = await ensure_awaitable(
            self.media_to_download(request, info, item=item)
        )
        if file_info:
            # got a result without downloading
            result = file_info
        else:
            # download the result
            result = await self._check_media_to_download(request, info, item=item)
    except Exception:
        result = Failure()
        if not _media_request_filtered(result):
            logger.exception(result)
    await _process_pending_io()
    self._cache_result_and_execute_waiters(result, fp, info)
    return await maybe_deferred_to_future(wad)  # it must return wad at last

async def _check_media_to_download(
    self, request: Request, info: SpiderInfo, item: Any
) -> FileInfo:
    try:
        self._modify_media_request(request)
        response = await self.crawler.engine.download_async(request)
        return await ensure_awaitable(
            self.media_downloaded(response, request, info, item=item)
        )
    except Exception:
        failure = self.media_failed(Failure(), request, info)
        if isinstance(failure, Failure):
            warnings.warn(
                f"{global_object_name(self.media_failed)} returned a Failure instance."
                f" This is deprecated, please raise an exception instead, e.g. via failure.raiseException().",
                category=ScrapyDeprecationWarning,
                stacklevel=2,
            )
            failure.raiseException()

def item_completed(
    self, results: list[FileInfoOrError], item: Any, info: SpiderInfo
) -> Any:
    """Called per item when all media requests has been processed"""
    if self.LOG_FAILED_RESULTS:
        for ok, value in results:
            if not ok:
                assert isinstance(value, Failure)
                if _media_request_filtered(value):
                    continue
                logger.error(
                    "%(class)s found errors processing %(item)s",
                    {"class": self.__class__.__name__, "item": item},
                    exc_info=failure_to_exc_info(value),
                    extra={"spider": info.spider},
                )
    return item

def _mkdir(
    self, dirname: Path, domain: MediaPipeline.SpiderInfo | None = None
) -> None:
    seen: set[str] = self.created_directories[domain] if domain else set()
    if str(dirname) not in seen:
        if not dirname.exists():
            dirname.mkdir(parents=True)
        seen.add(str(dirname))

def _stat_file(self, path: str) -> StatInfo:
    try:
        with FTP() as ftp:
            ftp.connect(self.host, self.port)
            ftp.login(self.username, self.password)
            if self.USE_ACTIVE_MODE:
                ftp.set_pasv(False)
            file_path = f"{self.basedir}/{path}"
            modified = ftp.voidcmd(f"MDTM {file_path}")[4:].strip()
            time_format = "%Y%m%d%H%M%S.%f" if "." in modified else "%Y%m%d%H%M%S"
            last_modified = (
                datetime.strptime(modified, time_format)
                .replace(tzinfo=timezone.utc)
                .timestamp()
            )
            m = hashlib.md5()  # noqa: S324
            ftp.retrbinary(f"RETR {file_path}", m.update)
        return {"last_modified": last_modified, "checksum": m.hexdigest()}
    # The file doesn't exist
    except Exception:
        return {}

def get_media_requests(
    self, item: Any, info: MediaPipeline.SpiderInfo
) -> list[Request]:
    urls = ItemAdapter(item).get(self.files_urls_field, [])
    if not isinstance(urls, list):
        raise TypeError(
            f"{self.files_urls_field} must be a list of URLs, got {type(urls).__name__}. "
        )
    return [Request(u, callback=NO_CALLBACK) for u in urls]

def item_completed(
    self, results: list[FileInfoOrError], item: Any, info: MediaPipeline.SpiderInfo
) -> Any:
    with suppress(KeyError):
        ItemAdapter(item)[self.files_result_field] = [x for ok, x in results if ok]
    return item

def old_directives(today: date) -> list[str]:
    """Return the ``versionadded`` and ``versionchanged`` directives that a
    major or minor release made on *today* must remove, i.e. those of
    releases more than 3 years old.
    """
    news = Path("docs/news.rst").read_text(encoding="utf-8")
    new_version = next((m[1] for m in TITLE.finditer(news) if m[2] == "unreleased"), "")
    if not new_version.endswith(".0"):
        return []
    for path in Path("docs/news").glob("*.rst"):
        news += path.read_text(encoding="utf-8")
    released = {
        m[1]: date.fromisoformat(m[2])
        for m in TITLE.finditer(news)
        if m[2] != "unreleased"
    }
    # February 29 becomes February 28.
    cutoff = date(
        today.year - 3, today.month, min(today.day, 28 if today.month == 2 else 31)
    )
    return [
        line
        for line in _git_grep(r"\.\. version(added|changed):: *[0-9]")
        if (m := re.search(r":: *(\d+\.\d+)(\.\d+)?", line))
        and released.get(f"{m[1]}{m[2] or '.0'}", today) < cutoff

def _deps(tox_ini: str, name: str) -> list[str]:
    block = re.search(
        r"^deps =\n((?:[ \t]+.*\n)*)", _section(tox_ini, name)[1], re.MULTILINE
    )
    if not block:
        return []
    deps = (re.sub(r"\s*#.*", "", line).strip() for line in block[1].splitlines())
    return [dep for dep in deps if dep]

def _requirements(tox_ini: str, name: str) -> list[str]:
    requirements = []
    for dep in _deps(tox_ini, name):
        if match := re.fullmatch(r"\{\[(.+)\]deps\}", dep):
            requirements += _requirements(tox_ini, match[1])
        else:
            requirements.append(dep)
    return requirements

def _upgrade_actions(cutoff: datetime) -> None:
    """Pin every GitHub action used in workflows to the commit of its latest
    release published before *cutoff*.
    """
    workflows = list(Path(".github/workflows").glob("*.yml"))
    pattern = r"(uses: ([\w.-]+/[\w.-]+)[\w./-]*@)[0-9a-f]{40} # \S+"
    repos = {
        match[2]
        for path in workflows
        for match in re.finditer(pattern, path.read_text(encoding="utf-8"))
    }
    pins = {}
    for repo in sorted(repos):
        try:
            release = _github(f"repos/{repo}/releases/latest")
        except HTTPError as error:
            if error.code != 404:
                raise
            print(f"{repo} has no releases, keeping its pin")
            continue
        if datetime.fromisoformat(release["published_at"]) > cutoff:
            print(f"{repo} {release['tag_name']} is too recent, keeping its pin")
            continue
        sha = _github(f"repos/{repo}/commits/{release['tag_name']}")["sha"]
        pins[repo] = f"{sha} # {release['tag_name']}"
    for path in workflows:
        text = re.sub(
            pattern,
            lambda m: f"{m[1]}{pins[m[2]]}" if m[2] in pins else m[0],
            path.read_text(encoding="utf-8"),
        )
        path.write_text(text, encoding="utf-8")
